def normalize_persona_id(raw_id=""):
    """角色 id 只允许 [A-Za-z0-9_-]，最多 60 字符。"""
    return re.sub(r"[^A-Za-z0-9_-]+", "_", str(raw_id or ""))[:60].strip("_")

def normalize_persona_item(item, fallback_index=0):
    """把任意输入规整成合法 persona item；不校验 builtin（由调用方决定）。"""
    if not isinstance(item, dict):
        item = {}
    fallback_name = f"角色{int(fallback_index or 0) + 1}"
    pid = normalize_persona_id(item.get("id") or "")
    return {
        "id": pid or f"persona_{uuid.uuid4().hex[:12]}",
        "name": sanitize_asset_name(item.get("name") or fallback_name, fallback_name),
        "description": str(item.get("description") or "").strip()[:PERSONA_DESC_MAX],
        "content": str(item.get("content") or "").strip()[:PERSONA_CONTENT_MAX],
        "builtin": bool(item.get("builtin")),
        "created_at": int(item.get("created_at") or now_ms()),
        "updated_at": int(item.get("updated_at") or item.get("created_at") or now_ms()),
    }

def normalize_persona_library(data):
    """内置角色始终以代码为准（保证新增/修订预置角色能自动同步），用户角色原样保留。"""
    if not isinstance(data, dict):
        data = {}
    raw_items = data.get("personas") if isinstance(data.get("personas"), list) else []
    personas = []
    seen_ids = set()
    builtins = [normalize_persona_item(item, index) for index, item in enumerate(builtin_personas())]
    for item in builtins:
        item["builtin"] = True
        item["created_at"] = PERSONA_BUILTIN_EPOCH_MS
        item["updated_at"] = PERSONA_BUILTIN_EPOCH_MS
        seen_ids.add(item["id"])
        personas.append(item)
    for index, raw in enumerate(raw_items):
        if not isinstance(raw, dict):
            continue
        item = normalize_persona_item(raw, index)
        # 内置条目以代码为准，历史文件里的同 id 条目一律忽略；空内容的无效条目也丢弃。
        if item["builtin"] or item["id"] in seen_ids or not item["content"]:
            continue
        item["builtin"] = False
        seen_ids.add(item["id"])
        personas.append(item)
    return {"personas": personas, "updated_at": int(data.get("updated_at") or now_ms())}

def default_persona_library():
    return normalize_persona_library({})

def save_persona_library(data):
    data = normalize_persona_library(data)
    data["updated_at"] = now_ms()
    os.makedirs(DATA_DIR, exist_ok=True)
    write_json_atomic(PERSONA_LIBRARY_PATH, data, ensure_ascii=False, indent=2)
    return data

def load_persona_library():
    if not os.path.exists(PERSONA_LIBRARY_PATH):
        return save_persona_library(default_persona_library())
    try:
        with open(PERSONA_LIBRARY_PATH, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        data = {}
    if not isinstance(data, dict):
        data = {}
    normalized = normalize_persona_library(data)
    if normalized.get("personas") != data.get("personas"):
        return save_persona_library(normalized)
    return normalized

def public_persona_library(data=None):
    data = normalize_persona_library(data if data is not None else load_persona_library())
    return {"personas": data.get("personas") or [], "updated_at": int(data.get("updated_at") or now_ms())}

def find_persona(data, persona_id=""):
    """按 id 查找角色；找不到返回 None。"""
    if not isinstance(data, dict):
        return None
    for item in (data.get("personas") or []):
        if isinstance(item, dict) and item.get("id") == persona_id:
            return item
    return None

# ── 长期记忆库（memory）· 数据层 ──────────────────────────────────────
# 记忆全部由用户管理（无内置条目）。每条带 enabled 开关（默认开），
# 请求构造时由 memory_block() 把已启用记忆合并进 system prompt，
# 前端 textarea（currentSystemPrompt）不感知，因此 chat / 生图 / agent 三处注入一致。

def normalize_memory_item(item, fallback_index=0):
    """把任意输入规整成合法 memory item。id 复用角色 id 规整器（安全字符集）。
    scope 仅接受 global / conversation，其余一律回退 global；conversation 作用域外的 conversation_id 一律清空。"""
    if not isinstance(item, dict):
        item = {}
    mid = normalize_persona_id(item.get("id") or "")
    scope = str(item.get("scope") or "global").strip()
    if scope not in ("global", "conversation"):
        scope = "global"
    return {
        "id": mid or f"memory_{uuid.uuid4().hex[:12]}",
        "content": str(item.get("content") or "").strip()[:MEMORY_CONTENT_MAX],
        "enabled": bool(item.get("enabled", True)),
        "scope": scope,
        "conversation_id": str(item.get("conversation_id") or "").strip() if scope == "conversation" else "",
        "created_at": int(item.get("created_at") or now_ms()),
        "updated_at": int(item.get("updated_at") or item.get("created_at") or now_ms()),
    }

def normalize_memory_library(data):
    """记忆无内置条目；空/无效内容或重复 id 的条目丢弃。"""
    if not isinstance(data, dict):
        data = {}
    raw_items = data.get("memories") if isinstance(data.get("memories"), list) else []
    memories = []
    seen_ids = set()
    for index, raw in enumerate(raw_items):
        if not isinstance(raw, dict):
            continue
        item = normalize_memory_item(raw, index)
        if not item["content"] or item["id"] in seen_ids:
            continue
        seen_ids.add(item["id"])
        memories.append(item)
    return {"memories": memories, "updated_at": int(data.get("updated_at") or now_ms())}

def default_memory_library():
    return normalize_memory_library({})

def save_memory_library(data):
    data = normalize_memory_library(data)
    data["updated_at"] = now_ms()
    os.makedirs(DATA_DIR, exist_ok=True)
    write_json_atomic(MEMORY_LIBRARY_PATH, data, ensure_ascii=False, indent=2)
    return data

def load_memory_library():
    if not os.path.exists(MEMORY_LIBRARY_PATH):
        return save_memory_library(default_memory_library())
    try:
        with open(MEMORY_LIBRARY_PATH, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        data = {}
    if not isinstance(data, dict):
        data = {}
    normalized = normalize_memory_library(data)
    if normalized.get("memories") != data.get("memories"):
        return save_memory_library(normalized)
    return normalized

def public_memory_library(data=None):
    data = normalize_memory_library(data if data is not None else load_memory_library())
    return {"memories": data.get("memories") or [], "updated_at": int(data.get("updated_at") or now_ms())}

def find_memory(data, memory_id=""):
    """按 id 查找记忆；找不到返回 None。"""
    if not isinstance(data, dict):
        return None
    for item in (data.get("memories") or []):
        if isinstance(item, dict) and item.get("id") == memory_id:
            return item
    return None

def memory_block(conversation_id=""):
    """返回当前已启用记忆的文本块（含中文标签前缀）；无启用记忆返回空串。
    scope == "global" 的记忆始终注入；scope == "conversation" 的记忆仅当
    conversation_id 非空且与请求所属对话一致时注入。
    供 chat / 生图 / agent 三处注入点统一调用，保证行为一致。"""
    cid = str(conversation_id or "").strip()
    try:
        lib = load_memory_library()
    except Exception:
        return ""
    items = lib.get("memories") if isinstance(lib, dict) else None
    if not isinstance(items, list):
        return ""
    active = []
    for m in items:
        if not isinstance(m, dict):
            continue
        if not m.get("enabled", True):
            continue
        if not (m.get("content") or "").strip():
            continue
        scope = str(m.get("scope") or "global")
        if scope == "conversation":
            if not cid or (m.get("conversation_id") or "") != cid:
                continue
        active.append(m)
    if not active:
        return ""
    lines = "\n".join(f"- {(m.get('content') or '').strip()}" for m in active)
    return "【长期记忆】以下是用户希望你在本次及后续对话中始终保持的偏好与事实，请主动遵守：\n" + lines

def effective_system_prompt(payload):
    """合并用户 system_prompt 与已启用记忆，作为最终生效的 system prompt。
    记忆由服务端在请求时自动注入，前端 textarea 无需感知。"""
    prompt = str(getattr(payload, "system_prompt", "") or "").strip()
    mem = memory_block(getattr(payload, "conversation_id", "") or "")
    if mem:
        prompt = (prompt + "\n\n" + mem).strip() if prompt else mem
    return prompt or SYSTEM_PROMPT

def sanitize_asset_name(name, fallback="asset"):
    name = re.sub(r'[\\/:*?"<>|]+', "_", str(name or fallback)).strip()
    return name[:120] or fallback

def content_type_for_path(path):
    ext = os.path.splitext(path)[1].lower()
    if ext in [".mp4", ".m4v"]:
        return "video/mp4"
    if ext == ".webm":
        return "video/webm"
    if ext == ".mov":
        return "video/quicktime"
    if ext == ".avi":
        return "video/x-msvideo"
    if ext == ".mkv":
        return "video/x-matroska"
    if ext == ".flv":
        return "video/x-flv"
    if ext == ".mp3":
        return "audio/mpeg"
    if ext == ".wav":
        return "audio/wav"
    if ext == ".m4a":
        return "audio/mp4"
    if ext == ".aac":
        return "audio/aac"
    if ext == ".ogg":
        return "audio/ogg"
    if ext == ".flac":
        return "audio/flac"
    if ext == ".gif":
        return "image/gif"
    if ext in [".jpg", ".jpeg"]:
        return "image/jpeg"
    if ext == ".webp":
        return "image/webp"
    if ext == ".txt":
        return "text/plain; charset=utf-8"
    if ext == ".json":
        return "application/json; charset=utf-8"
    if ext == ".csv":
        return "text/csv; charset=utf-8"
    if ext == ".md":
        return "text/markdown; charset=utf-8"
    if ext == ".srt":
        return "application/x-subrip; charset=utf-8"
    if ext == ".vtt":
        return "text/vtt; charset=utf-8"
    if ext == ".png":
        return "image/png"
    return "application/octet-stream"

def is_image_reference_value(value):
    if not isinstance(value, str) or not value:
        return False
    if value.startswith("data:image/"):
        return True
    if value.startswith("data:"):
        return False
    if value.startswith("/output/") or value.startswith("/assets/"):
        path = output_file_from_url(value)
        return bool(path and content_type_for_path(path).startswith("image/"))
    clean = value.split("?", 1)[0].lower()
    if re.search(r"\.(mp4|webm|mov|m4v|avi|mkv|mp3|wav|m4a|aac|ogg|flac)$", clean):
        return False
    return True

def is_video_reference_value(value):
    if not isinstance(value, str) or not value:
        return False
    if value.startswith("data:video/"):
        return True
    if value.startswith("data:"):
        return False
    if value.startswith("/output/") or value.startswith("/assets/"):
        path = output_file_from_url(value)
        return bool(path and content_type_for_path(path).startswith("video/"))
    clean = value.split("?", 1)[0].lower()
    return bool(re.search(r"\.(mp4|webm|mov|m4v|avi|mkv)$", clean))

def convert_output_to_jpg(url, quality=88):
    path = output_file_from_url(url)
    if not path:
        return url
    root, ext = os.path.splitext(path)
    if ext.lower() in [".jpg", ".jpeg"]:
        return url
    jpg_path = f"{root}.jpg"
    try:
        with Image.open(path) as img:
            if img.mode in ("RGBA", "LA") or (img.mode == "P" and "transparency" in img.info):
                bg = Image.new("RGB", img.size, (255, 255, 255))
                bg.paste(img.convert("RGBA"), mask=img.convert("RGBA").split()[-1])
                img = bg
            else:
                img = img.convert("RGB")
            img.save(jpg_path, "JPEG", quality=quality, optimize=True)
        try:
            root = ASSETS_DIR if os.path.commonpath([os.path.abspath(ASSETS_DIR), os.path.abspath(jpg_path)]) == os.path.abspath(ASSETS_DIR) else OUTPUT_DIR
        except ValueError:
            root = OUTPUT_DIR
        rel = os.path.relpath(jpg_path, root).replace("\\", "/")
        prefix = "/assets" if root == ASSETS_DIR else "/output"
        return f"{prefix}/{rel}"
    except Exception as e:
        print(f"转换 JPG 失败: {e}")
        return url

def reference_to_data_url(ref, max_size=None):
    """把本地输出文件转为 data URL（base64）。max_size 限制最长边像素，避免 payload 过大。"""
    path = output_file_from_url(ref.get("url", ""))
    if not path:
        return ref.get("url", "")
    if max_size:
        try:
            with Image.open(path) as img:
                img.load()
                w, h = img.size
                if max(w, h) > max_size:
                    img.thumbnail((max_size, max_size), Image.LANCZOS)
                if img.mode not in ("RGB", "RGBA"):
                    img = img.convert("RGB")
                buf = BytesIO()
                fmt = "PNG" if img.mode == "RGBA" else "JPEG"
                img.save(buf, format=fmt, quality=88 if fmt == "JPEG" else None)
                encoded = base64.b64encode(buf.getvalue()).decode("ascii")
                mime = "image/png" if fmt == "PNG" else "image/jpeg"
                return f"data:{mime};base64,{encoded}"
        except Exception as e:
            print(f"reference resize failed, fallback to raw: {e}")
    with open(path, "rb") as f:
        raw = f.read()
    mime = content_type_for_path(path)
    if mime.startswith(("image/", "video/", "audio/")):
        encoded = base64.b64encode(raw).decode("ascii")
        return f"data:{mime};base64,{encoded}"
    # .heic/.avif/.tif 这类扩展名 content_type_for_path 只给 application/octet-stream，
    # 这种 data URL 上游一律拒收；按真实字节再让 Pillow 认一次，认不出返回空串让调用方兜底
    jpeg = image_bytes_to_jpeg_data_url(raw, max_size)
    if jpeg:
        return jpeg
    print(f"参考图不是可识别的图片，返回空地址：{str(path)[:120]}")
    return ""

def pil_image_to_jpeg_data_url(img, max_size=None, quality=88):
    """PIL 图像压成 JPEG data URL；透明区域铺白，避免上游把 RGBA 存成超大 PNG。"""
    img.load()
    if max_size and max(img.size) > max_size:
        img.thumbnail((max_size, max_size), Image.LANCZOS)
    if img.mode in ("RGBA", "LA") or (img.mode == "P" and "transparency" in img.info):
        base = img.convert("RGBA")
        background = Image.new("RGB", base.size, (255, 255, 255))
        background.paste(base, mask=base.split()[-1])
        target = background
    else:
        target = img.convert("RGB")
    buf = BytesIO()
    target.save(buf, format="JPEG", quality=quality, optimize=True)
    return "data:image/jpeg;base64," + base64.b64encode(buf.getvalue()).decode("ascii")

def image_bytes_to_jpeg_data_url(data, max_size=1536, quality=88):
    """内存里的图片字节 → JPEG data URL；Pillow 认不出（非图片/损坏/缺解码器）返回空串。"""
    try:
        with Image.open(BytesIO(data)) as img:
            return pil_image_to_jpeg_data_url(img, max_size, quality)
    except Exception as e:
        print(f"参考图字节无法按图片解码：{e}")
        return ""

def reference_to_jpeg_data_url(ref, max_size, quality=88):
    """把参考图按最长边/质量压成 JPEG data URL；APIMart 网关限 1MB 请求体，RGBA 存 PNG 会比 JPEG 大数倍。"""
    url = str(ref.get("url", "") if isinstance(ref, dict) else ref or "")
    path = output_file_from_url(url)
    if not path:
        return url if url.startswith(("data:", "http://", "https://", "asset://")) else ""
    try:
        with Image.open(path) as img:
            return pil_image_to_jpeg_data_url(img, max_size, quality)
    except Exception as e:
        print(f"APIMart 参考图压缩失败 {url}: {e}")
        return ""

def apimart_fallback_compression_ladder(count):
    """按参考图张数决定起始清晰度，再逐级降尺寸/质量，供回退 data URL 使用。"""
    start = 1536 if count <= 1 else 1280 if count <= 3 else 1024 if count <= 5 else 768
    ladder = []
    size = start
    quality = 88
    while True:
        ladder.append((size, quality))
        if size <= 320:
            return ladder
        size = max(320, int(size * 0.8))
        quality = max(45, quality - 8)

def apimart_json_body_bytes(body, image_urls):
    """精确量出真正要发出去的 JSON 体积（APIMart 网关按字节限流，不是按图片张数）。"""
    candidate = dict(body, image_urls=image_urls)
    return len(json.dumps(candidate, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))

def apimart_reference_fallback_data_url(ref, max_size, quality):
    """单张参考图的压缩结果；压不动时退回原图而不是丢弃，保证 prompt 里「图N」编号不错位。"""
    url = reference_to_jpeg_data_url(ref, max_size, quality)
    if url:
        return url
    source = str(ref.get("url", "") if isinstance(ref, dict) else ref or "").strip()
    if output_file_from_url(source):
        raw = ""
        try:
            raw = reference_to_data_url({"url": source})
        except Exception as e:
            print(f"APIMart 参考图读取失败：{invalid_video_image_preview(source)} {e}")
        if raw.startswith("data:image/"):
            print(f"APIMart 参考图压不成 JPEG，改用原图 data URL（体积可能超出预算）：{invalid_video_image_preview(source)}")
            return raw
    if source.startswith(("data:image/", "http://", "https://", "asset://")):
        return source
    raise HTTPException(
        status_code=400,
        detail=f"参考图读取失败，无法送达上游：{invalid_video_image_preview(source) or '空地址'}。请重新选择参考图后重试。",
    )

APIMART_DIRECT_DATA_URL_MAX_IMAGES = 3

def apimart_direct_data_urls(refs, body, budget_bytes=None):
    """单张/少量图片先压成 data URL 直发：进得了预算就完全不调用上传接口，也就不消耗上传额度。
    返回 None 表示超预算（或图片压不出来），调用方再走上传换公网 URL。"""
    if not refs or len(refs) > APIMART_DIRECT_DATA_URL_MAX_IMAGES:
        return None
    budget = APIMART_JSON_BODY_BUDGET if budget_bytes is None else budget_bytes
    urls = [apimart_reference_fallback_data_url(ref, 1536, 88) for ref in refs]
    if not all(valid_video_image_input(url) for url in urls):
        return None
    total = apimart_json_body_bytes(body, urls)
    if total > budget:
        print(f"APIMart 图片 data URL 直发超预算：{len(urls)} 张，请求体 {total} 字节 > {budget} 字节，改走上传")
        return None
    print(f"APIMart 图片 data URL 直发：{len(urls)} 张，请求体 {total} 字节，不调用上传接口")
    return urls

def apimart_reference_data_urls_with_fit(refs, body, budget_bytes=None):
    """逐级压缩参考图，返回 (urls, 是否低于预算)；urls 的张数与顺序与 refs 一致。"""
    budget = APIMART_JSON_BODY_BUDGET if budget_bytes is None else budget_bytes
    urls = []
    for max_size, quality in apimart_fallback_compression_ladder(len(refs)):
        urls = [apimart_reference_fallback_data_url(ref, max_size, quality) for ref in refs]
        total = apimart_json_body_bytes(body, urls)
        if total <= budget:
            print(f"APIMart 参考图回退压缩：{len(urls)} 张，max_size={max_size} quality={quality}，请求体 {total} 字节")
            return urls, True
    print(f"APIMart 参考图回退压缩：{len(urls)} 张压到最小仍超过预算 {budget} 字节，按最小档发送")
    return urls, False

def apimart_reference_data_urls(refs, body, budget_bytes=None):
    """把参考图压成 data URL，逐级压缩直到整个 JSON 请求体低于预算；张数与顺序与 refs 一致。"""
    urls, _fits = apimart_reference_data_urls_with_fit(refs, body, budget_bytes)
    return urls

APIMART_IMAGE_URL_PREVIEW_CHARS = 60

def apimart_image_url_valid(value):
    """上游 image_urls 只认公网 http(s) 或 image base64 data URI。"""
    text = str(value or "").strip()
    return text.startswith(("http://", "https://", "data:image/"))

def apimart_image_url_preview(value, limit=APIMART_IMAGE_URL_PREVIEW_CHARS):
    text = str(value or "")
    if text.startswith("data:"):
        return (text.split(";base64,", 1)[0] + ";base64,...")[:limit]
    return text[:limit] or "空地址"

def apimart_local_reference_url(*values):
    for value in values:
        text = str(value or "").strip()
        if text.startswith(("/output/", "/assets/")) and output_file_from_url(text):
            return text
    return ""

def apimart_data_url_to_jpeg(value, max_size=1536, quality=88):
    """data: 但 mime 不是 image/* 时按字节转 JPEG；缺 base64 段或解码失败返回空串。"""
    text = str(value or "").strip()
    if ";base64," not in text:
        return ""
    try:
        raw = base64.b64decode(text.split(";base64,", 1)[1])
    except Exception as e:
        print(f"APIMart 参考图 data URL 解码失败：{e}")
        return ""
    return image_bytes_to_jpeg_data_url(raw, max_size, quality)

def sanitize_apimart_image_urls(image_urls, refs=None):
    """发送前统一收口：把本地路径 / data:非图片 / 其它非法值转成上游认的 data:image，
    转不出来直接 400 不出网。refs 与 image_urls 按同一顺序一一对应（调用方已同样截断）。"""
    refs = refs or []
    values = list(image_urls or [])
    illegal = []
    first_failed = None
    for index, value in enumerate(values):
        if apimart_image_url_valid(value):
            continue
        ref = refs[index] if index < len(refs) and isinstance(refs[index], dict) else {}
        source = str(value or "").strip() or str(ref.get("url") or "").strip()
        repaired = ""
        if source.startswith("data:"):
            repaired = apimart_data_url_to_jpeg(source)
        else:
            local = apimart_local_reference_url(source, ref.get("url"))
            if local:
                repaired = reference_to_jpeg_data_url({"url": local}, 1536, 88)
                repaired = repaired if repaired.startswith("data:image/") else ""
        if not repaired and apimart_image_url_valid(ref.get("url")):
            repaired = str(ref.get("url")).strip()
        illegal.append((index, value, source, repaired))
        if repaired:
            values[index] = repaired
        elif first_failed is None:
            first_failed = (index, source)
    if not illegal:
        print(f"APIMart image_urls 发送前校验：{len(values)} 张全部合法")
        return values
    repaired_parts = [f"第 {index + 1} 张 {apimart_image_url_preview(old)} → data:image"
                      for index, old, _source, repaired in illegal if repaired]
    failed_parts = [f"第 {index + 1} 张 {apimart_image_url_preview(source, 120)}"
                    for index, _old, source, repaired in illegal if not repaired]
    print("APIMart image_urls 发送前校验："
          + ("修复 " + "；".join(repaired_parts) if repaired_parts else "无修复")
          + (f"；仍非法：{'；'.join(failed_parts)}" if failed_parts else ""))
    if first_failed:
        index, source = first_failed
        raise HTTPException(
            status_code=400,
            detail=(f"第 {index + 1} 张参考图（来源 {apimart_image_url_preview(source, 120)}）"
                    "格式不支持或文件不存在，请另存为 JPG/PNG 后重试。"),
        )
    return values

def apimart_image_url_rejected(text):
    """上游 4xx/5xx 里点名 url/download/fetch/image，多半是它取不到我们给的外部图片 URL。"""
    lower_text = str(text or "").lower()
    return any(token in lower_text for token in ("url", "download", "fetch", "image"))

def is_image_reference(ref):
    if not isinstance(ref, dict):
        return False
    kind = str(ref.get("kind") or "").strip().lower()
    mime = str(ref.get("mime") or "").strip().lower()
    url = str(ref.get("url") or "").strip().lower()
    if kind:
        return kind == "image"
    if mime:
        return mime.startswith("image/")
    return bool(re.search(r"\.(png|jpe?g|webp|gif|bmp|tiff?)(\?|#|$)", url))

def image_references(refs):
    return [ref for ref in (refs or []) if is_image_reference(ref)]

TEXT_ATTACHMENT_EXTS = {".txt", ".md", ".markdown", ".json", ".csv", ".log", ".py", ".js", ".ts", ".tsx", ".jsx", ".html", ".css", ".xml", ".yaml", ".yml"}
XLSX_IMAGE_EXTS = {".png", ".jpg", ".jpeg", ".webp", ".gif", ".bmp", ".tif", ".tiff"}
EXCEL_MAX_SHEETS = 8
EXCEL_MAX_ROWS_PER_SHEET = 80
EXCEL_MAX_COLS_PER_ROW = 30
MAX_ATTACHMENT_TEXT_CHARS = 12000

def _xml_local_name(tag):
    return str(tag or "").rsplit("}", 1)[-1]

def _xlsx_join_text(node):
    parts = []
    for child in node.iter():
        if _xml_local_name(child.tag) == "t" and child.text:
            parts.append(child.text)
    return "".join(parts).strip()

def _xlsx_shared_strings(archive):
    try:
        raw = archive.read("xl/sharedStrings.xml")
    except KeyError:
        return []
    root = ET.fromstring(raw)
    values = []
    for node in root:
        if _xml_local_name(node.tag) == "si":
            values.append(_xlsx_join_text(node))
    return values

def _xlsx_sheet_paths(archive):
    names = set(archive.namelist())
    fallback = [(os.path.basename(name).rsplit(".", 1)[0], name) for name in sorted(names) if re.match(r"xl/worksheets/sheet\d+\.xml$", name)]
    try:
        workbook = ET.fromstring(archive.read("xl/workbook.xml"))
        rels = ET.fromstring(archive.read("xl/_rels/workbook.xml.rels"))
        rel_map = {}
        for rel in rels:
            rid = rel.attrib.get("Id")
            target = rel.attrib.get("Target") or ""
            if not rid or not target:
                continue
            target = target.lstrip("/")
            if not target.startswith("xl/"):
                target = f"xl/{target}"
            rel_map[rid] = target.replace("\\", "/")
        result = []
        for sheet in workbook.iter():
            if _xml_local_name(sheet.tag) != "sheet":
                continue
            title = sheet.attrib.get("name") or "Sheet"
            rid = sheet.attrib.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
            target = rel_map.get(rid, "")
            if target in names:
                result.append((title, target))
        return result or fallback
    except Exception:
        return fallback

def _xlsx_cell_text(cell, shared_strings):
    cell_type = cell.attrib.get("t", "")
    value_node = None
    formula_node = None
    inline_node = None
    for child in cell:
        name = _xml_local_name(child.tag)
        if name == "v":
            value_node = child
        elif name == "f":
            formula_node = child
        elif name == "is":
            inline_node = child
    raw_value = (value_node.text if value_node is not None else "") or ""
    formula = (formula_node.text if formula_node is not None else "") or ""
    if cell_type == "s" and raw_value.isdigit():
        idx = int(raw_value)
        value = shared_strings[idx] if 0 <= idx < len(shared_strings) else raw_value
    elif cell_type == "inlineStr" and inline_node is not None:
        value = _xlsx_join_text(inline_node)
    elif cell_type == "b":
        value = "TRUE" if raw_value == "1" else "FALSE" if raw_value == "0" else raw_value
    else:
        value = raw_value
    value = str(value or "").strip()
    if formula and value:
        return f"{value} [={formula}]"
    if formula:
        return f"={formula}"
    return value

def read_xlsx_attachment(path, limit=MAX_ATTACHMENT_TEXT_CHARS):
    parts = []
    used = 0
    with zipfile.ZipFile(path) as archive:
        shared = _xlsx_shared_strings(archive)
        sheets = _xlsx_sheet_paths(archive)
        media_count = sum(1 for name in archive.namelist() if name.startswith("xl/media/") and os.path.splitext(name)[1].lower() in XLSX_IMAGE_EXTS)
        parts.append(f"Excel 工作簿：{os.path.basename(path)}")
        if media_count:
            parts.append(f"内嵌图片数量：{media_count}（已作为图片参考一并提供给模型）")
        for sheet_index, (sheet_name, sheet_path) in enumerate(sheets[:EXCEL_MAX_SHEETS], start=1):
            try:
                root = ET.fromstring(archive.read(sheet_path))
            except Exception:
                continue
            rows = []
            for row in root.iter():
                if _xml_local_name(row.tag) != "row":
                    continue
                cells = []
                for cell in row:
                    if _xml_local_name(cell.tag) != "c":
                        continue
                    ref = cell.attrib.get("r") or ""
                    value = _xlsx_cell_text(cell, shared)
                    if value:
                        cells.append(f"{ref}={value}" if ref else value)
                    if len(cells) >= EXCEL_MAX_COLS_PER_ROW:
                        break
                if cells:
                    row_ref = row.attrib.get("r") or str(len(rows) + 1)
                    rows.append(f"第 {row_ref} 行：" + " | ".join(cells))
                if len(rows) >= EXCEL_MAX_ROWS_PER_SHEET:
                    break
            if rows:
                section = f"\n工作表 {sheet_index}：{sheet_name}\n" + "\n".join(rows)
            else:
                section = f"\n工作表 {sheet_index}：{sheet_name}\n（未读取到非空单元格）"
            if used + len(section) > limit:
                remain = max(0, limit - used)
                if remain:
                    parts.append(section[:remain])
                parts.append("\n（Excel 内容较长，已截断）")
                break
            parts.append(section)
            used += len(section)
    return "\n".join(parts).strip()[:limit]

def xlsx_embedded_image_data_urls(path, max_images=4, max_size=1536):
    urls = []
    try:
        with zipfile.ZipFile(path) as archive:
            media = [name for name in archive.namelist() if name.startswith("xl/media/") and os.path.splitext(name)[1].lower() in XLSX_IMAGE_EXTS]
            for name in sorted(media)[:max_images]:
                try:
                    raw = archive.read(name)
                    with Image.open(BytesIO(raw)) as img:
                        img.load()
                        if max(img.size) > max_size:
                            img.thumbnail((max_size, max_size), Image.LANCZOS)
                        if img.mode in ("RGBA", "LA") or (img.mode == "P" and "transparency" in img.info):
                            bg = Image.new("RGB", img.size, (255, 255, 255))
                            bg.paste(img.convert("RGBA"), mask=img.convert("RGBA").split()[-1])
                            img = bg
                        elif img.mode != "RGB":
                            img = img.convert("RGB")
                        buf = BytesIO()
                        img.save(buf, format="JPEG", quality=88, optimize=True)
                        encoded = base64.b64encode(buf.getvalue()).decode("ascii")
                        urls.append(f"data:image/jpeg;base64,{encoded}")
                except Exception as exc:
                    print(f"[chat] failed to extract xlsx image {name}: {exc}")
    except Exception as exc:
        print(f"[chat] failed to read xlsx images {path}: {exc}")
    return urls

def attachment_embedded_image_data_urls(refs, max_images=4):
    urls = []
    for ref in (refs or []):
        if not isinstance(ref, dict) or is_image_reference(ref):
            continue
        path = output_file_from_url(ref.get("url", ""))
        if not path or os.path.splitext(path)[1].lower() != ".xlsx":
            continue
        urls.extend(xlsx_embedded_image_data_urls(path, max_images=max(0, max_images - len(urls))))
        if len(urls) >= max_images:
            break
    return urls[:max_images]

def read_text_attachment(path, limit=MAX_ATTACHMENT_TEXT_CHARS):
    ext = os.path.splitext(path or "")[1].lower()
    if not path or not os.path.isfile(path):
        return ""
    try:
        if ext == ".xlsx":
            return read_xlsx_attachment(path, limit)
        if ext == ".xls":
            return "这是旧版 .xls 二进制 Excel 文件，当前内置解析器暂不支持直接读取内容。请另存为 .xlsx 后重新上传。"
        if ext == ".docx":
            with zipfile.ZipFile(path) as archive:
                raw = archive.read("word/document.xml")
            root = ET.fromstring(raw)
            parts = []
            for node in root.iter():
                if node.tag.endswith("}t") and node.text:
                    parts.append(node.text)
                elif node.tag.endswith("}p"):
                    parts.append("\n")
            return html.unescape("".join(parts)).strip()[:limit]
        if ext in TEXT_ATTACHMENT_EXTS:
            with open(path, "rb") as f:
                data = f.read(min(os.path.getsize(path), limit * 4))
            for encoding in ("utf-8-sig", "utf-8", "gb18030"):
                try:
                    return data.decode(encoding, errors="strict").strip()[:limit]
                except UnicodeDecodeError:
                    continue
            return data.decode("utf-8", errors="replace").strip()[:limit]
    except Exception as exc:
        print(f"[chat] failed to read attachment text {path}: {exc}")
    return ""

def attachment_text_blocks(refs, limit_each=MAX_ATTACHMENT_TEXT_CHARS):
    blocks = []
    for ref in (refs or [])[:CHAT_ATTACHMENT_MAX]:
        if not isinstance(ref, dict) or is_image_reference(ref):
            continue
        path = output_file_from_url(ref.get("url", ""))
        text = read_text_attachment(path, limit_each) if path else ""
        if not text:
            continue
        name = ref.get("name") or os.path.basename(path)
        blocks.append(f"附件：{name}\n{text}")
    return blocks

def media_reference_to_url(value, max_image_size=None):
    if not isinstance(value, str) or not value:
        return ""
    if value.startswith("/output/") or value.startswith("/assets/"):
        return reference_to_data_url({"url": value}, max_size=max_image_size)
    return value

def is_private_asset_url(value: str) -> bool:
    return isinstance(value, str) and value.strip().startswith("asset://")

def volcengine_media_reference_url(value, max_image_size=1536):
    if not isinstance(value, str):
        return ""
    value = value.strip()
    if not value:
        return ""
    if is_private_asset_url(value):
        return value
    if value.startswith("/output/") or value.startswith("/assets/"):
        return reference_to_data_url({"url": value}, max_size=max_image_size)
    return value

async def volcengine_audio_reference_url(value, max_image_size=None):
    """火山参考音频：优先云端上传换公网链接（与参考视频同一通道），上传失败再回退内联 data URL。"""
    text = str(value or "").strip()
    if not text:
        return ""
    if text.startswith(("http://", "https://", "asset://")):
        return text
    try:
        uploaded = await upload_local_video_to_cloud(text)
        url = str((uploaded or {}).get("url") or "").strip()
        if url.startswith(("http://", "https://")):
            return url
    except Exception as e:
        print(f"火山参考音频云上传失败，回退 data URL：{e}")
    return volcengine_media_reference_url(text, max_image_size=max_image_size)

def looks_like_image_media_url(value: str) -> bool:
    text = str(value or "").strip().lower()
    if not text:
        return False
    if text.startswith("data:image/"):
        return True
    if text.startswith("asset://"):
        return False
    path = urllib.parse.urlparse(text).path or text
    return bool(re.search(r"\.(png|jpe?g|webp|gif|bmp|tiff)$", path))

def volcengine_content_role(role: str, kind: str = "image") -> Optional[str]:
    value = str(role or "").strip().lower()
    allowed = {
        "first_frame", "last_frame", "reference_image",
        "reference_video", "reference_audio", "video", "audio", "image"
    }
    if value in allowed:
        if value == "audio" and kind == "audio":
            return "reference_audio"
        # 火山要求参考媒体模式下视频 role 必须是 reference_video（实测 role="video" 报错）；
        # 前端传 "video" 时归一为 reference_video。
        if value == "video" and kind == "video":
            return "reference_video"
        return value
    if kind == "audio":
        return "reference_audio"
    if kind == "video":
        return "reference_video"
    # 修复：未显式指定 role 的纯生图请求不应兜底为 reference_image，
    # 否则火山后端会误判为 r2v(参考图生视频)，导致 seedance/seedream 等生图模型失败。
    return None

def legacy_video_resolution(value: str) -> str:
    """老画布的私有档位 780P 官方没有，统一兼容映射为 720p，不允许原样下发上游。"""
    text = str(value or "").strip()
    return "720p" if text.lower() == "780p" else text

def volcengine_video_duration(duration, model="") -> int:
    # 官方 create-video-generation-task-api「duration 模型支持」：Seedance 2.5 [4,30]、
    # 2.0 系列 [4,15]、1.0 pro / pro fast [2,12]；2.5 编辑任务的 -1 由下方
    # ratio=adaptive / duration=-1 特例接管。
    try:
        value = int(duration)
    except Exception:
        value = 5
    name = str(model or "").strip().lower().replace("_", "-").replace(".", "-")
    if "seedance-2-5" in name:
        return max(4, min(30, value))
    if "seedance-2-0" in name:
        return max(4, min(15, value))
    if "seedance-1-0" in name:
        return max(2, min(12, value))
    return max(1, min(60, value))

def volcengine_video_resolution(value: str, model: str = "") -> str:
    text = str(value or "").strip().lower()
    aliases = {"": "", "auto": "", "480": "480p", "720": "720p", "1080": "1080p", "780p": "720p", "4k": "4k"}
    text = aliases.get(text, text)
    if text not in {"480p", "720p", "1080p", "4k"}:
        return ""
    if text == "4k":
        # 官方「resolution 模型支持」只有 Seedance 2.0（非 fast/mini）开放 4k；
        # 其余模型收敛到最高可用档：2.5 / 1.0 pro 系 1080p，2.0 fast/mini 720p。
        name = str(model or "").strip().lower().replace("_", "-").replace(".", "-")
        if "seedance-2-5" in name:
            return "1080p"
        if "seedance-2-0" in name and ("fast" in name or "mini" in name):
            return "720p"
        if "seedance-2-0" in name:
            return "4k"
        return "1080p"
    return text

def volcengine_video_ratio(aspect: str) -> str:
    """Ark 官方 ratio 白名单没有旧画布保留字 keep_ratio/source，兼容映射为 adaptive。"""
    value = str(aspect or "").strip()
    return "adaptive" if value in {"keep_ratio", "source"} else value

def is_volcengine_seedance2_model(model: str) -> bool:
    value = str(model or "").strip().lower().replace("_", "-").replace(".", "-")
    return "seedance-2-0" in value

def probe_local_audio_duration_seconds(value: str) -> Optional[float]:
    path = output_file_from_url(value)
    if not path or not os.path.isfile(path):
        return None
    ffprobe = ffprobe_binary()
    if not ffprobe:
        return None
    try:
        proc = subprocess.run(
            [
                ffprobe,
                "-v", "error",
                "-show_entries", "format=duration",
                "-of", "default=noprint_wrappers=1:nokey=1",
                path,
            ],
            capture_output=True,
            text=True,
            timeout=20,
        )
        if proc.returncode != 0:
            return None
        duration = float(str(proc.stdout or "").strip())
        return duration if math.isfinite(duration) and duration > 0 else None
    except Exception:
        return None

def probe_video_file_duration_seconds(path: str) -> Optional[float]:
    """探测本地视频文件（绝对路径）时长（秒）。探测失败返回 None。"""
    if not path or not os.path.isfile(path):
        return None
    ffprobe = ffprobe_binary()
    if not ffprobe:
        return None
    try:
        proc = subprocess.run(
            [
                ffprobe,
                "-v", "error",
                "-show_entries", "format=duration",
                "-of", "default=noprint_wrappers=1:nokey=1",
                path,
            ],
            capture_output=True,
            text=True,
            timeout=20,
        )
        if proc.returncode != 0:
            return None
        duration = float(str(proc.stdout or "").strip())
        return duration if math.isfinite(duration) and duration > 0 else None
    except Exception:
        return None

def probe_local_video_duration_seconds(value: str) -> Optional[float]:
    """探测本地视频文件时长（秒）。非本地路径/探测失败返回 None。"""
    return probe_video_file_duration_seconds(output_file_from_url(value))

def volcengine_trim_video_to_seconds(value: str, max_seconds: float = 15.2) -> str:
    """火山参考视频时长限制 ≤15.2s：超限视频自动截取前 max_seconds 秒存 assets/input，
    返回新的 /assets/ URL（截取失败或无需截取返回原值）。"""
    text = str(value or "").strip()
    if not text:
        return text
    duration = probe_local_video_duration_seconds(text)
    if duration is None or duration <= max_seconds:
        return text
    path = output_file_from_url(text)
    if not path or not os.path.isfile(path):
        return text
    ffmpeg = ffmpeg_binary()
    if not ffmpeg:
        return text
    base = os.path.splitext(os.path.basename(path))[0]
    # ffmpeg 截取有容器误差（实测 -t 15.2 产出 15.27s），目标时长留 0.7s 安全余量
    target = max(1.0, float(max_seconds) - 0.7)
    trimmed_rel = f"input/trimmed_{base}_{int(max_seconds)}s.mp4"
    trimmed_path = os.path.join(ASSETS_DIR, trimmed_rel)
    os.makedirs(os.path.dirname(trimmed_path), exist_ok=True)
    try:
        proc = subprocess.run(
            [
                ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
                "-i", path,
                "-t", str(target),
                "-c", "copy",
                "-movflags", "+faststart",
                trimmed_path,
            ],
            capture_output=True,
            text=True,
            timeout=120,
        )
        if proc.returncode != 0 or not os.path.isfile(trimmed_path):
            # copy 流复制失败（如音频编码不兼容）时降级重编码
            proc = subprocess.run(
                [
                    ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
                    "-i", path,
                    "-t", str(target),
                    "-vf", "scale=1280:720:force_original_aspect_ratio=decrease,pad=1280:720:(ow-iw)/2:(oh-ih)/2,setsar=1,fps=30",
                    "-c:v", "libx264", "-preset", "veryfast", "-pix_fmt", "yuv420p",
                    "-c:a", "aac", "-b:a", "128k",
                    "-movflags", "+faststart",
                    trimmed_path,
                ],
                capture_output=True,
                text=True,
                timeout=180,
            )
            if proc.returncode != 0 or not os.path.isfile(trimmed_path):
                return text
        return f"/assets/{trimmed_rel}"
    except Exception as e:
        print(f"[volc] trim video failed: {e}")
        return text


def volcengine_mute_video(value: str) -> str:
    """火山输出音频版权检测：参考视频带背景音乐会报 copyright restrictions。
    静音（去音轨）后重新提交，画面/动作参考不受影响。无音轨或处理失败返回原值。"""
    text = str(value or "").strip()
    if not text:
        return text
    path = output_file_from_url(text)
    if not path or not os.path.isfile(path):
        return text
    ffmpeg = ffmpeg_binary()
    if not ffmpeg:
        return text
    ffprobe = ffprobe_binary()
    if ffprobe:
        try:
            proc = subprocess.run(
                [ffprobe, "-v", "error", "-select_streams", "a", "-show_entries", "stream=index", "-of", "csv=p=0", path],
                capture_output=True, text=True, timeout=20,
            )
            if not str(proc.stdout or "").strip():
                return text  # 无音轨，无需处理
        except Exception:
            pass
    base = os.path.splitext(os.path.basename(path))[0]
    muted_rel = f"input/muted_{base}.mp4"
    muted_path = os.path.join(ASSETS_DIR, muted_rel)
    os.makedirs(os.path.dirname(muted_path), exist_ok=True)
    try:
        proc = subprocess.run(
            [
                ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
                "-i", path,
                "-an", "-c:v", "copy",
                "-movflags", "+faststart",
                muted_path,
            ],
            capture_output=True, text=True, timeout=120,
        )
        if proc.returncode != 0 or not os.path.isfile(muted_path):
            # copy 失败降级重编码
            proc = subprocess.run(
                [
                    ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
                    "-i", path,
                    "-an",
                    "-vf", "scale=1280:720:force_original_aspect_ratio=decrease,pad=1280:720:(ow-iw)/2:(oh-ih)/2,setsar=1,fps=30",
                    "-c:v", "libx264", "-preset", "veryfast", "-pix_fmt", "yuv420p",
                    "-movflags", "+faststart",
                    muted_path,
                ],
                capture_output=True, text=True, timeout=180,
            )
            if proc.returncode != 0 or not os.path.isfile(muted_path):
                return text
        return f"/assets/{muted_rel}"
    except Exception as e:
        print(f"[volc] mute video failed: {e}")
        return text


# ─── 参考视频按秒切分（前端「视频分镜表」自动分解镜头）────────────────────────
VIDEO_SEGMENT_SECONDS_DEFAULT = 3.0
VIDEO_SEGMENT_SECONDS_MIN = 1.0
VIDEO_SEGMENT_SECONDS_MAX = 5.0
VIDEO_SEGMENT_MAX_SEGMENTS_DEFAULT = 30
VIDEO_SEGMENT_MAX_SEGMENTS_LIMIT = 60
# 末段不足 1s 的碎片既看不清也没有分镜价值，并进上一段
VIDEO_SEGMENT_MIN_TAIL_SECONDS = 1.0

def clamp_video_segment_seconds(value) -> float:
    """每段秒数归一到 1.0–5.0；缺省或非法值（含 NaN）回退 3.0。"""
    try:
        seconds = float(value)
    except (TypeError, ValueError):
        return VIDEO_SEGMENT_SECONDS_DEFAULT
    if not math.isfinite(seconds):
        return VIDEO_SEGMENT_SECONDS_DEFAULT
    return min(VIDEO_SEGMENT_SECONDS_MAX, max(VIDEO_SEGMENT_SECONDS_MIN, seconds))

def clamp_video_segment_max_segments(value) -> int:
    """最大段数归一到 1–60；缺省或非法值回退 30。"""
    try:
        count = int(value)
    except (TypeError, ValueError):
        return VIDEO_SEGMENT_MAX_SEGMENTS_DEFAULT
    return min(VIDEO_SEGMENT_MAX_SEGMENTS_LIMIT, max(1, count))

def plan_video_segments(duration, seconds, max_segments) -> Tuple[List[Dict[str, Any]], bool]:
    """纯函数（不碰文件系统）：规划每段 [start, end) 区间，返回 (segments, truncated)。

    start 依次为 0, seconds, 2*seconds…，end = min(start + seconds, duration)；
    末段不足 1s 时并入上一段（上一段 end 拉到 duration），所以总段数可能 -1；
    duration 整除 seconds 时不产生空段，duration < seconds 时只有一段。
    段数超过 max_segments 时只保留前 max_segments 段（truncated=True）。
    """
    total = float(duration)
    step = clamp_video_segment_seconds(seconds)
    limit = clamp_video_segment_max_segments(max_segments)
    if not math.isfinite(total) or total <= 0:
        return [], False
    segments: List[Dict[str, Any]] = []
    start = 0.0
    # 1e-6 容差：duration 恰为 seconds 整数倍时不再多切一个 0 长度的空段
    while start < total - 1e-6:
        end = min(start + step, total)
        segments.append({
            "index": len(segments) + 1,
            "start": round(start, 3),
            "end": round(end, 3),
            "duration": round(end - start, 3),
        })
        start += step
    if len(segments) > 1 and segments[-1]["duration"] < VIDEO_SEGMENT_MIN_TAIL_SECONDS:
        segments.pop()
        segments[-1]["end"] = round(total, 3)
        segments[-1]["duration"] = round(segments[-1]["end"] - segments[-1]["start"], 3)
    truncated = len(segments) > limit
    return (segments[:limit] if truncated else segments), truncated

def video_segments_output_key(src_path: str, seconds) -> str:
    """片段输出目录 key：源文件绝对路径 + 每段秒数的 sha1 前 12 位（同源同参数固定复用）。"""
    raw = f"{os.path.abspath(str(src_path))}|{clamp_video_segment_seconds(seconds):.3f}"
    return hashlib.sha1(raw.encode("utf-8", "ignore")).hexdigest()[:12]

def segment_video_file(src_path: str, out_dir: str, index: int, start: float, duration: float,
                       clip_timeout: float = 120, frame_timeout: float = 60) -> Dict[str, str]:
    """切出第 index 段视频 [start, start+duration) 并抽它的首帧，返回 {clip_path, frame_path}。

    只能重编码不能 -c copy：copy 从关键帧切起会让实际段长明显偏离请求值。
    产物已存在且非空时复用——前端反复刷新分镜表时不再重复转码。
    任一步失败抛 RuntimeError，由路由统一转成 400。
    """
    clip_path = os.path.join(out_dir, f"seg_{int(index):02d}.mp4")
    frame_path = os.path.join(out_dir, f"seg_{int(index):02d}.jpg")
    clip_ready = os.path.isfile(clip_path) and os.path.getsize(clip_path) > 0
    frame_ready = os.path.isfile(frame_path) and os.path.getsize(frame_path) > 0
    if clip_ready and frame_ready:
        return {"clip_path": clip_path, "frame_path": frame_path}
    ffmpeg = ffmpeg_binary()
    if not ffmpeg:
        raise RuntimeError("服务器缺少 ffmpeg，无法切分视频")
    os.makedirs(out_dir, exist_ok=True)
    start = float(start)
    duration = float(duration)
    if not clip_ready:
        try:
            proc = subprocess.run(
                [
                    ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
                    "-ss", f"{start:.3f}",
                    "-i", src_path,
                    "-t", f"{duration:.3f}",
                    "-an",
                    "-c:v", "libx264", "-preset", "veryfast", "-pix_fmt", "yuv420p",
                    "-movflags", "+faststart",
                    clip_path,
                ],
                capture_output=True,
                text=True,
                timeout=clip_timeout,
            )
        except subprocess.TimeoutExpired:
            raise RuntimeError(f"第 {int(index)} 段切片超时（超过 {int(clip_timeout)} 秒）")
        if proc.returncode != 0 or not os.path.isfile(clip_path) or os.path.getsize(clip_path) <= 0:
            detail = (proc.stderr or "").strip()[:300] or "ffmpeg 未输出文件"
            print(f"[segments] cut seg {int(index)} failed: {detail}")
            raise RuntimeError(f"第 {int(index)} 段切片失败：{detail}")
    if not frame_ready:
        # 段首往往是转场帧，往后挪一点再抽，首帧更接近该镜头内容
        frame_at = start + min(0.3, duration / 2)
        try:
            proc = subprocess.run(
                [
                    ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
                    "-ss", f"{frame_at:.3f}",
                    "-i", src_path,
                    "-frames:v", "1", "-q:v", "3",
                    "-vf", "scale='min(768,iw)':-2",
                    frame_path,
                ],
                capture_output=True,
                text=True,
                timeout=frame_timeout,
            )
        except subprocess.TimeoutExpired:
            raise RuntimeError(f"第 {int(index)} 段抽帧超时（超过 {int(frame_timeout)} 秒）")
        if proc.returncode != 0 or not os.path.isfile(frame_path) or os.path.getsize(frame_path) <= 0:
            detail = (proc.stderr or "").strip()[:300] or "ffmpeg 未输出文件"
            print(f"[segments] frame seg {int(index)} failed: {detail}")
            raise RuntimeError(f"第 {int(index)} 段抽帧失败：{detail}")
    return {"clip_path": clip_path, "frame_path": frame_path}

def build_video_segments(src_path: str, duration: float, seconds=None, max_segments=None) -> Dict[str, Any]:
    """规划 + 真实切分：返回 {duration, seconds, truncated, segments}，片段带 clip_url/frame_url。"""
    seconds = clamp_video_segment_seconds(seconds)
    max_segments = clamp_video_segment_max_segments(max_segments)
    plan, truncated = plan_video_segments(duration, seconds, max_segments)
    if not plan:
        raise RuntimeError("视频时长无效，无法切分")
    out_dir = os.path.join(ASSETS_DIR, "input", "segments", video_segments_output_key(src_path, seconds))
    segments = []
    for item in plan:
        paths = segment_video_file(src_path, out_dir, item["index"], item["start"], item["duration"])
        segments.append({
            "index": item["index"],
            "start": item["start"],
            "end": item["end"],
            "duration": item["duration"],
            "clip_url": "/assets/" + os.path.relpath(paths["clip_path"], ASSETS_DIR).replace(os.sep, "/"),
            "frame_url": "/assets/" + os.path.relpath(paths["frame_path"], ASSETS_DIR).replace(os.sep, "/"),
        })
    return {
        "duration": round(float(duration), 3),
        "seconds": seconds,
        "truncated": truncated,
        "segments": segments,
    }

def download_video_url_to_temp(url: str, timeout: float = 120.0) -> str:
    """远程参考视频下载到临时文件（ffmpeg/ffprobe 只吃本地路径）；失败抛 RuntimeError。

    文件名按 URL 固定：片段目录 key 由源文件路径推导，路径漂移会让同一远程地址每次重新转码。
    先写 .part 再原子改名，避免半个文件被后续请求当成有效源视频复用。
    """
    text = str(url or "").strip()
    key = hashlib.sha1(text.encode("utf-8", "ignore")).hexdigest()[:12]
    path = os.path.join(tempfile.gettempdir(), f"novai_segment_src_{key}.mp4")
    if os.path.isfile(path) and os.path.getsize(path) > 0:
        return path
    part_path = f"{path}.{uuid.uuid4().hex[:8]}.part"
    try:
        with httpx.Client(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV,
                          timeout=timeout, follow_redirects=True) as client:
            with client.stream("GET", text) as response:
                response.raise_for_status()
                with open(part_path, "wb") as fp:
                    for chunk in response.iter_bytes(1024 * 256):
                        fp.write(chunk)
        if os.path.getsize(part_path) <= 0:
            raise RuntimeError("下载到的视频是空文件")
        os.replace(part_path, path)
    except Exception as exc:
        try:
            if os.path.isfile(part_path):
                os.remove(part_path)
        except OSError:
            pass
        raise RuntimeError(str(exc) or "下载失败")
    return path


_VOLCENGINE_EDIT_PROMPT_KEYWORDS = (
    "编辑", "修改", "替换", "更换", "删除", "移除", "延长",
    "局部", "替换成", "换成", "改为",
    "edit", "replace", "change", "modify", "remove", "delete",
    "extend", "swap", "alter",
)

def is_volcengine_edit_prompt(text: str) -> bool:
    value = str(text or "").strip().lower()
    if not value:
        return False
    return any(keyword in value for keyword in _VOLCENGINE_EDIT_PROMPT_KEYWORDS)

# 视频编辑任务要求输入视频 4~30 秒；短于 4 秒上游只回一段看不懂的参数错误，
# 所以提交前先拦下（参考视频 r2v 只限上限 15.2 秒，没有这条下限）。
VOLCENGINE_EDIT_VIDEO_MIN_SECONDS = 4.0

def ensure_volcengine_edit_video_duration(duration, is_edit_target):
    if duration is None or not is_edit_target or duration >= VOLCENGINE_EDIT_VIDEO_MIN_SECONDS:
        return
    raise HTTPException(
        status_code=400,
        detail=(
            f"这是视频编辑任务，输入视频要求 4~30 秒，当前视频只有 {duration:.1f} 秒。"
            "素材本身很短的话，建议改用首帧/参考图生视频。"
        ),
    )

async def volcengine_video_reference_content_items(value, max_frames=4, max_size=768, as_target=False):
    text = str(value or "").strip()
    if not text:
        return []
    if as_target:
        # 视频编辑/局部替换任务：目标视频必须以完整视频形式提交（不能抽帧成图片）。
        # 火山要求参考媒体模式下视频 role 必须是 reference_video（实测 role="video" 报
        # InvalidParameter: reference media mode requires video role to be reference_video）。
        # 编辑意图靠 prompt 关键词（替换/编辑）区分，role 保持 reference_video。
        return [{
            "type": "video_url",
            "video_url": {"url": text},
            "role": "reference_video",
        }]
    if is_private_asset_url(text):
        return [{
            "type": "video_url",
            "video_url": {"url": text},
            "role": "reference_video",
        }]
    frame_urls = await video_reference_to_frame_data_urls(text, max_frames=max_frames, max_size=max_size)
    return [
        {
            "type": "image_url",
            "image_url": {"url": frame_url},
            "role": "reference_image",
        }
        for frame_url in frame_urls
        if frame_url
    ]

async def video_reference_to_frame_data_urls(value, max_frames=6, max_size=768):
    if not isinstance(value, str) or not value:
        return []
    path = output_file_from_url(value)
    cleanup_path = ""
    if not path and value.startswith(("http://", "https://")):
        suffix = os.path.splitext(urllib.parse.urlparse(value).path)[1] or ".mp4"
        fd, cleanup_path = tempfile.mkstemp(prefix="canvas_llm_video_", suffix=suffix)
        os.close(fd)
        try:
            async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=httpx.Timeout(connect=20.0, read=120.0, write=30.0, pool=10.0)) as client:
                response = await client.get(value)
                response.raise_for_status()
                with open(cleanup_path, "wb") as f:
                    f.write(response.content)
            path = cleanup_path
        except Exception as e:
            print(f"[canvas-llm] video download failed: {e}")
            if cleanup_path and os.path.exists(cleanup_path):
                try: os.remove(cleanup_path)
                except OSError: pass
            return []
    if not path or not os.path.exists(path):
        return []
    frame_dir = tempfile.mkdtemp(prefix="canvas_llm_frames_")
    try:
        ffmpeg = ffmpeg_binary()
        if not ffmpeg:
            return []
        pattern = os.path.join(frame_dir, "frame_%03d.jpg")
        cmd = [
            ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
            "-i", path,
            "-vf", f"fps=1,scale='min({max_size},iw)':-2",
            "-frames:v", str(max(1, max_frames)),
            pattern
        ]
        proc = await asyncio.to_thread(subprocess.run, cmd, capture_output=True, text=True, timeout=90)
        if proc.returncode != 0:
            print(f"[canvas-llm] ffmpeg frame extract failed: {proc.stderr[:300]}")
            return []
        frames = []
        for name in sorted(os.listdir(frame_dir)):
            if not name.lower().endswith((".jpg", ".jpeg", ".png")):
                continue
            frame_path = os.path.join(frame_dir, name)
            with open(frame_path, "rb") as f:
                frames.append(f"data:image/jpeg;base64,{base64.b64encode(f.read()).decode('ascii')}")
        return frames
    finally:
        shutil.rmtree(frame_dir, ignore_errors=True)
        if cleanup_path and os.path.exists(cleanup_path):
            try: os.remove(cleanup_path)
            except OSError: pass

def compress_data_url_image(value, max_size=1536, jpeg_quality=88):
    if not isinstance(value, str) or not value.startswith("data:image/") or ";base64," not in value:
        return value
    header, encoded = value.split(";base64,", 1)
    try:
        raw = base64.b64decode(encoded)
        with Image.open(BytesIO(raw)) as img:
            img.load()
            if max_size and max(img.size) > max_size:
                img.thumbnail((max_size, max_size), Image.LANCZOS)
            has_alpha = img.mode in ("RGBA", "LA") or (img.mode == "P" and "transparency" in img.info)
            if has_alpha:
                if img.mode != "RGBA":
                    img = img.convert("RGBA")
                fmt, mime = "PNG", "image/png"
            else:
                if img.mode != "RGB":
                    img = img.convert("RGB")
                fmt, mime = "JPEG", "image/jpeg"
            buf = BytesIO()
            if fmt == "JPEG":
                img.save(buf, format=fmt, quality=jpeg_quality, optimize=True)
            else:
                img.save(buf, format=fmt, optimize=True)
            return f"data:{mime};base64,{base64.b64encode(buf.getvalue()).decode('ascii')}"
    except Exception as e:
        print(f"data url image compress failed, fallback to raw: {e}")
        return value

def modelscope_image_url(value, max_size=1536):
    if not value:
        return value
    if isinstance(value, str) and (value.startswith("/output/") or value.startswith("/assets/")):
        return reference_to_data_url({"url": value}, max_size=max_size)
    return value

def valid_video_image_input(value: str) -> bool:
    if not isinstance(value, str):
        return False
    value = value.strip()
    return (
        value.startswith("http://") or
        value.startswith("https://") or
        value.startswith("asset://") or
        (value.startswith("data:image/") and ";base64," in value)
    )

def valid_apimart_video_image_input(value: str) -> bool:
    if not isinstance(value, str):
        return False
    value = value.strip()
    return value.startswith("http://") or value.startswith("https://") or value.startswith("asset://")

def apply_trusted_asset_prompt_index(prompt: str, image_count: int, video_count: int, audio_count: int) -> str:
    """可信素材模式下，按平台规则在 prompt 里补「图片N/视频N/音频N」索引。
    若用户已手动引用了某类素材（如已写「图片1」），则不重复追加该类。"""
    text = str(prompt or "").strip()
    segments = []
    for label, count in (("图片", image_count), ("视频", video_count), ("音频", audio_count)):
        if count <= 0:
            continue
        if any(f"{label}{i}" in text for i in range(1, count + 1)):
            continue
        segments.append("、".join(f"{label}{i}" for i in range(1, count + 1)))
    if not segments:
        return text
    hint = "参考素材：" + "，".join(segments) + "。"
    return f"{text}\n{hint}" if text else hint

def public_base_url() -> str:
    # 实时读 API/.env 且文件优先：公网隧道重启后地址会变，隧道脚本只改 .env；
    # 启动时 load_env_file 会把旧值复制进 os.environ，若 env 优先会永远读到过期地址
    value = (
        read_api_env_value("PUBLIC_MEDIA_BASE_URL") or
        os.getenv("PUBLIC_MEDIA_BASE_URL") or
        PUBLIC_MEDIA_BASE_URL or
        read_api_env_value("PUBLIC_BASE_URL") or
        os.getenv("PUBLIC_BASE_URL") or
        PUBLIC_BASE_URL or
        ""
    ).strip().rstrip("/")
    if value and re.match(r"^https?://", value, re.I):
        return value
    return ""

def public_media_url_suffix() -> str:
    token = str(os.getenv("PUBLIC_MEDIA_TOKEN") or "").strip()
    return f"?token={urllib.parse.quote(token)}" if token else ""

def local_asset_public_url(value: str) -> str:
    text = str(value or "").strip()
    if not text.startswith(("/output/", "/assets/")):
        return ""
    if not output_file_from_url(text):
        return ""
    base = public_base_url()
    if not base:
        return ""
    return f"{base}{urllib.parse.quote(text, safe='/:?&=%#.-_~')}{public_media_url_suffix()}"

async def openai_video_proxy_public_reference_url(ref) -> str:
    """异步生图（openai-video-proxy）的参考图公网化。
    不走公网隧道（暴露本机服务风险高）：本地文件上传图床（Litterbox/temp.sh，72h 短链），
    与 RS 模式同一通道；真正的公网 URL 原样透传；若手动配置了 PUBLIC_MEDIA_BASE_URL 则作为兜底。"""
    raw = ref.get("url", "") if isinstance(ref, dict) else ref
    text = str(raw or "").strip()
    if not text:
        return ""
    parsed = urllib.parse.urlsplit(text)
    local_path = ""
    if parsed.scheme in {"http", "https"}:
        host = (parsed.hostname or "").lower()
        if host in {"127.0.0.1", "localhost", "::1"} or re.match(r"^(192\.168\.|10\.|172\.(1[6-9]|2\d|3[01])\.)", host):
            local_path = urllib.parse.unquote(parsed.path or "")
        else:
            return text
    elif text.startswith(("/output/", "/assets/")):
        local_path = text
    if local_path and output_file_from_url(local_path):
        upload_error = ""
        try:
            uploaded = await upload_local_video_to_cloud(local_path)
            url = str((uploaded or {}).get("url") or "")
            if url.startswith(("http://", "https://")):
                return url
        except HTTPException as exc:
            upload_error = str(exc.detail)
        public_url = local_asset_public_url(local_path)
        if public_url:
            return public_url
        raise HTTPException(
            status_code=400,
            detail=f"参考图上传图床失败，无法转成公网 URL：{upload_error[:200] or '未知错误'}。请检查网络后重试。"
        )
    raise HTTPException(status_code=400, detail=f"参考图不是公网 URL，无法传给上游：{text[:160]}")

def normalize_apimart_video_reference(value: str) -> str:
    text = str(value or "").strip()
    if valid_apimart_video_image_input(text):
        return text
    return local_asset_public_url(text)

def apimart_video_reference_error(value: str) -> str:
    text = str(value or "").strip()
    if not text:
        return "空的视频地址"
    if text.startswith(("/output/", "/assets/")):
        if not output_file_from_url(text):
            return "这是本地画布文件路径，但后端没有找到对应文件，请重新上传视频后再试。"
        return (
            "这是本地画布文件，APIMart 无法访问 127.0.0.1/局域网路径；"
            "请在 API/.env 配置 PUBLIC_MEDIA_BASE_URL 或 PUBLIC_BASE_URL 为可公网访问的媒体地址（例如内网穿透 HTTPS 地址），"
            "或改用公网 http/https 视频 URL、审核后的 asset:// 地址。"
        )
    if text.startswith("data:") or text.startswith("blob:") or text.startswith("file:"):
        return (
            "APIMart 的 video_urls 不支持 data/blob/file 地址；"
            "请改用公网 http/https 视频 URL，或审核后的 asset:// 地址。"
        )
    return "APIMart 的 video_urls 只支持公网 http/https URL 或 asset:// 私域素材 URL。"

def apimart_video_duration(duration, model="") -> int:
    # 官方区间：Seedance 2.0 4-15、seedance-1.0-pro(doubao) 2-12、Kling 3-15；
    # 其它模型沿用原 4-15，VEO3.1 走 apimart_veo31_duration。
    try:
        value = int(duration)
    except Exception:
        value = 5
    name = str(model or "").strip().lower().replace("_", "-").replace(".", "-")
    if "kling" in name:
        return max(3, min(15, value))
    if "seedance-1" in name:
        return max(2, min(12, value))
    return max(4, min(15, value))

def apimart_veo31_duration(duration) -> int:
    try:
        value = int(duration)
    except Exception:
        value = 8
    # APIMart VEO 3.1 currently accepts a narrower duration window than
    # the generic UI. Clamp instead of silently forcing every request to 8s.
    return max(4, min(8, value))

def is_apimart_veo31_model(model: str) -> bool:
    return str(model or "").strip().lower().startswith("veo3.1")

def apimart_veo31_model(model: str) -> str:
    value = str(model or "").strip().lower()
    aliases = {
        "veo3.1": "veo3.1-fast",
        "veo3.1-pro": "veo3.1-quality",
        "veo3.1-preview": "veo3.1-fast",
    }
    value = aliases.get(value, value or "veo3.1-fast")
    allowed = {"veo3.1-fast", "veo3.1-quality", "veo3.1-lite"}
    return value if value in allowed else "veo3.1-fast"

def apimart_veo31_aspect(aspect: str) -> str:
    value = str(aspect or "16:9").strip()
    return value if value in {"16:9", "9:16"} else "16:9"

def apimart_veo31_resolution(resolution: str) -> str:
    value = str(resolution or "").strip().lower()
    aliases = {"": "720p", "auto": "720p", "480p": "720p", "780p": "720p", "1080": "1080p", "4k": "4k"}
    value = aliases.get(value, value)
    return value if value in {"720p", "1080p", "4k"} else "720p"

# 实测 apib.ai 网关（nginx）按 1MB 请求体拦截：1049620 字节回 413、1035348 字节上传成功。
# 首档取 900KB 给 multipart 边界和表单留约 12% 余量，与 APIMART_JSON_BODY_BUDGET 的假设一致。
APIMART_UPLOAD_TIERS = (
    (900_000, 2048),
    (576_000, 1536),
    (384_000, 1280),
    (256_000, 1024),
)

def apimart_jpeg_payload(img, budget: int, max_dim: int, stem: str):
    """把 PIL 图压成 budget 字节以内的 RGB JPEG：带 alpha 先铺白底，长边不超过 max_dim。"""
    if img.mode == "RGB":
        frame = img
    else:
        rgba = img.convert("RGBA")
        frame = Image.new("RGB", rgba.size, (255, 255, 255))
        frame.paste(rgba, mask=rgba.split()[-1])
    width, height = frame.size
    scale = min(1.0, float(max_dim) / max(width, height))
    if scale < 1.0:
        frame = frame.resize((max(1, round(width * scale)), max(1, round(height * scale))), Image.LANCZOS)
    while True:
        low, high, best = 45, 95, None
        while low <= high:
            quality = (low + high) // 2
            buf = BytesIO()
            frame.save(buf, format="JPEG", quality=quality, optimize=True)
            payload = buf.getvalue()
            if len(payload) <= budget:
                best = payload
                low = quality + 1
            else:
                high = quality - 1
        if best is not None:
            return f"{stem}.jpg", best, "image/jpeg"
        if max(frame.size) <= 256:
            raise ValueError(f"图片压缩到 {budget} 字节以内失败")
        frame = frame.resize((max(1, frame.size[0] // 2), max(1, frame.size[1] // 2)), Image.LANCZOS)

def apimart_upload_payload_variants(path=None, data=None, mime="", name_hint="image"):
    """按 APIMART_UPLOAD_TIERS 依次产出 (filename, bytes, content_type, 档位说明)。
    原图已在首档上限内就原样作为第一档；之后每档都重新缩尺寸并编码 JPEG，供 413 时逐档降级。"""
    if path is not None:
        size = os.path.getsize(path)
        stem = os.path.splitext(os.path.basename(path))[0]
    else:
        data = data or b""
        size = len(data)
        stem = name_hint
    top_budget = APIMART_UPLOAD_TIERS[0][0]
    if size <= top_budget and (path is not None or (mime or "").lower() in ("image/png", "image/jpeg", "image/webp")):
        if path is not None:
            with open(path, "rb") as fh:
                raw = fh.read()
            yield os.path.basename(path), raw, content_type_for_path(path), "原图"
        else:
            ext = mimetypes.guess_extension(mime or "image/png") or ".png"
            yield f"{name_hint}{ext}", data, (mime or "image/png"), "原图"
    source = path if path is not None else BytesIO(data)
    with Image.open(source) as opened:
        img = opened.copy()
    for budget, max_dim in APIMART_UPLOAD_TIERS:
        filename, payload, content_type = apimart_jpeg_payload(img, budget, max_dim, stem)
        yield filename, payload, content_type, f"{budget // 1000}KB/{max_dim}px"

def apimart_upload_file_payload(path: str):
    """Return (filename, bytes, content_type) of the first upload tier for a local image path."""
    for filename, content, content_type, _tier in apimart_upload_payload_variants(path=path):
        return filename, content, content_type
    raise ValueError("图片无法读取")

def invalid_video_image_preview(value: str) -> str:
    text = str(value or "")
    if text.startswith("data:"):
        return text.split(";base64,", 1)[0] + ";base64,..."
    return text[:120]

def extract_apimart_asset_url(payload):
    if isinstance(payload, list):
        for item in payload:
            found = extract_apimart_asset_url(item)
            if found:
                return found
        return ""
    if not isinstance(payload, dict):
        return ""
    url_keys = ("url", "asset_url", "assetUrl", "uri", "file_url", "fileUrl")
    for key in url_keys:
        value = str(payload.get(key) or "").strip()
        if valid_apimart_video_image_input(value):
            return value
    id_keys = ("asset_id", "assetId", "file_id", "fileId", "id")
    for key in id_keys:
        value = str(payload.get(key) or "").strip()
        if value:
            return value if value.startswith("asset://") else f"asset://{value}"
    for key in ("data", "file", "asset", "result"):
        found = extract_apimart_asset_url(payload.get(key))
        if found:
            return found
    return ""

def apimart_upload_payload_from_bytes(data: bytes, mime: str, name_hint: str = "image"):
    """把内存中的图片字节按首个上传档位压缩为可上传 payload。"""
    for filename, content, content_type, _tier in apimart_upload_payload_variants(data=data, mime=mime, name_hint=name_hint):
        return filename, content, content_type
    raise ValueError("图片无法读取")

def apimart_upload_raw_file_payload(path: str):
    with open(path, "rb") as fh:
        return os.path.basename(path), fh.read(), content_type_for_path(path)

APIMART_UPLOAD_RETRY_ATTEMPTS = 3

def is_transient_tls_error(exc) -> bool:
    """识别可重试的瞬时 TLS/传输错误，如 SSLV3_ALERT_BAD_RECORD_MAC、EOF occurred 等，
    这类错误多由连接池中被污染/复用坏掉的 TLS 连接引起，换新连接重试通常即可成功。"""
    if isinstance(exc, httpx.TransportError):
        return True
    msg = f"{type(exc).__name__}: {exc}".upper()
    return any(token in msg for token in (
        "SSL", "BAD RECORD MAC", "EOF OCCURRED", "DECRYPTION FAILED", "WRONG VERSION NUMBER",
    ))

async def apimart_upload_post(client, upload_url, headers, file_tuple, timeout=60):
    """上传文件到 APIMart，对瞬时 TLS 错误自动重试；重试时改用全新连接，避免复用坏掉的 TLS 连接。
    file_tuple 形如 (filename, content_bytes, content_type)，content 为已读入内存的 bytes，可跨重试复用。"""
    last_exc = None
    for attempt in range(APIMART_UPLOAD_RETRY_ATTEMPTS):
        files = {"file": file_tuple}
        try:
            if attempt == 0:
                return await client.post(upload_url, headers=headers, files=files, timeout=timeout)
            async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV,
                timeout=httpx.Timeout(connect=20.0, read=max(120.0, float(timeout)), write=120.0, pool=20.0),
                follow_redirects=True,
            ) as fresh:
                return await fresh.post(upload_url, headers=headers, files=files, timeout=timeout)
        except Exception as e:
            if not is_transient_tls_error(e) or attempt == APIMART_UPLOAD_RETRY_ATTEMPTS - 1:
                raise
            last_exc = e
            print(f"APIMart 上传遇到瞬时 TLS 错误，换新连接重试（第 {attempt + 1} 次）：{e}")
            await asyncio.sleep(0.6 * (attempt + 1))
    if last_exc:
        raise last_exc

async def apimart_upload_with_shrink(client, upload_url, headers, variants):
    """按档位依次上传，只有网关 413 才降级到下一档；其它状态码（401/500/网络异常）原样交给调用方处理。
    返回 (最后一个响应, 尝试记录)；尝试记录每项含档位、实际字节数、上游状态码。"""
    attempts = []
    resp = None
    for filename, content, content_type, tier in variants:
        resp = await apimart_upload_post(client, upload_url, headers, (filename, content, content_type), timeout=60)
        attempts.append({"tier": tier, "bytes": len(content), "status": resp.status_code})
        if resp.status_code in (200, 201):
            return resp, attempts
        if resp.status_code != 413:
            return resp, attempts
        print(f"APIMart 上传 {tier}（{len(content)} 字节）被网关 413 拒绝，压缩后重试下一档")
    return resp, attempts

def apimart_upload_shrink_reason(attempts) -> str:
    """所有档位都被 413 拒绝时的错误文案：列出试过的档位、最后一档实际字节数和上游状态码。"""
    if not attempts:
        return "APIMart 上传失败(413)：没有可用的图片档位"
    last = attempts[-1]
    tried = "；".join(f"{item['tier']}({item['bytes']} 字节) → {item['status']}" for item in attempts)
    return (f"APIMart 上传失败({last['status']})：已按档位自动压缩重试，"
            f"最后一档 {last['bytes']} 字节（{last['tier']}）仍被网关拒绝。尝试记录：{tried}")

APIMART_QUOTA_ERROR_MARK = "APIMart 图片上传额度已用尽"

def apimart_upload_quota_exhausted(resp) -> bool:
    """429 或响应体里带 quota/rate_limit 才算额度用尽，普通限流不算。"""
    if resp is None:
        return False
    status = getattr(resp, "status_code", 0) or 0
    text = str(getattr(resp, "text", "") or "").lower()
    if status == 429:
        return True
    return status >= 400 and any(token in text for token in ("rate_limit", "quota", "upload limit"))

def apimart_quota_reset_text(reset_at) -> str:
    try:
        moment = datetime.datetime.fromtimestamp(float(reset_at))
    except (TypeError, ValueError, OverflowError, OSError):
        return ""
    return f"{moment.strftime('%Y-%m-%d %H:%M')}（本地时间）"

def apimart_upload_quota_reason(resp) -> str:
    """429 额度用尽的可读原因：上限、已用、恢复时间（本地时区）与三条降低依赖的建议。"""
    quota = {}
    upstream_message = ""
    try:
        payload = resp.json()
    except Exception:
        payload = None
    if isinstance(payload, dict):
        if isinstance(payload.get("quota"), dict):
            quota = payload["quota"]
        error = payload.get("error")
        if isinstance(error, dict):
            upstream_message = str(error.get("message") or "")
        elif isinstance(payload.get("message"), str):
            upstream_message = payload["message"]

    def _int(value):
        try:
            return int(value)
        except (TypeError, ValueError):
            return None

    limit = _int(quota.get("limit"))
    used = _int(quota.get("used"))
    remaining = _int(quota.get("remaining"))
    window_hours = _int(quota.get("window_hours")) or 72
    limit_text = f"{limit} 个文件/{window_hours} 小时" if limit is not None else f"2000 个文件/{window_hours} 小时"
    used_text = f"已用 {used} 个" if used is not None else "已用数量未知"
    if remaining is not None:
        used_text += f"、剩余 {remaining} 个"
    reset_text = apimart_quota_reset_text(quota.get("reset_at"))
    head = f"{APIMART_QUOTA_ERROR_MARK}（429）：账号上限 {limit_text}，{used_text}"
    head += f"，额度预计 {reset_text}恢复。" if reset_text else "，上游未返回额度恢复时间。"
    advice = ("建议：1) 等额度恢复后再试；2) 换一个 APIMart 账号的 API Key；"
              "3) 用更小的图片或减少参考图数量（本地图片压成 data URL 直发时不消耗上传额度）。")
    detail = head + advice
    if upstream_message:
        detail += f" 上游原文：{upstream_message[:200]}"
    return detail

def apimart_upload_failure_detail(resp, attempts) -> str:
    """上传失败原因：429 说额度、413 说压缩档位、其它给状态码。"""
    if resp is None:
        return "APIMart 上传失败：没有响应"
    if apimart_upload_quota_exhausted(resp):
        return apimart_upload_quota_reason(resp)
    if resp.status_code == 413:
        return apimart_upload_shrink_reason(attempts)
    return f"APIMart 上传失败({resp.status_code})"

def apimart_error_is_quota(value) -> bool:
    return isinstance(value, str) and value.startswith(f"ERR:{APIMART_QUOTA_ERROR_MARK}")

APIMART_UPLOAD_CACHE_MAX = 200
# 图床直链有时效（uguu ≈3 小时、Litterbox 72 小时、temp.sh 3 天），按服务取保守 TTL：
# 过期就当未命中重新上传，避免同 path 一直返回失效链接。
APIMART_TEMP_HOST_URL_TTL = {
    "uguu": 150 * 60,
    "litterbox": 66 * 60 * 60,
    "temp.sh": 66 * 60 * 60,
}
APIMART_UPLOAD_ASSET_TTL_SECONDS = int(os.getenv("APIMART_UPLOAD_ASSET_TTL_SECONDS", str(24 * 60 * 60)))
APIMART_IMAGE_SOURCE_ENV = "APIMART_IMAGE_SOURCE"
_APIMART_UPLOAD_CACHE = {}

def apimart_cache_now() -> float:
    return time.time()

def apimart_image_source() -> str:
    """本地图片转 APIMart 视频输入的优先级：temp=先临时图床（默认），apimart=先官方上传。"""
    value = str(os.getenv(APIMART_IMAGE_SOURCE_ENV) or "").strip().lower()
    return "apimart" if value in {"apimart", "official", "upload"} else "temp"

def apimart_temp_host_url_ttl(service) -> int:
    return int(APIMART_TEMP_HOST_URL_TTL.get(str(service or "").strip().lower(), 150 * 60))

def apimart_upload_cache_key(path):
    """本地图片缓存键：绝对路径 + mtime + size，文件被覆盖后自然失效。"""
    try:
        stat = os.stat(path)
    except OSError:
        return ""
    return f"{os.path.abspath(path)}|{stat.st_mtime_ns}|{stat.st_size}"

def apimart_upload_cache_get(key) -> str:
    if not key:
        return ""
    entry = _APIMART_UPLOAD_CACHE.get(key)
    if not entry:
        return ""
    expires_at = entry.get("expires_at")
    if expires_at is not None and apimart_cache_now() >= float(expires_at):
        _APIMART_UPLOAD_CACHE.pop(key, None)
        print(f"APIMart 图片缓存已过期（{entry.get('source') or 'unknown'}），重新上传：{key.split('|', 1)[0]}")
        return ""
    _APIMART_UPLOAD_CACHE.pop(key)
    _APIMART_UPLOAD_CACHE[key] = entry
    return str(entry.get("url") or "")

def apimart_upload_cache_put(key, url, ttl_seconds=None, source="") -> None:
    if not key or not url:
        return
    expires_at = None if ttl_seconds is None else apimart_cache_now() + float(ttl_seconds)
    _APIMART_UPLOAD_CACHE.pop(key, None)
    _APIMART_UPLOAD_CACHE[key] = {
        "url": str(url),
        "expires_at": expires_at,
        "source": str(source or ""),
    }
    while len(_APIMART_UPLOAD_CACHE) > APIMART_UPLOAD_CACHE_MAX:
        _APIMART_UPLOAD_CACHE.pop(next(iter(_APIMART_UPLOAD_CACHE)))

def apimart_data_url_over_budget_reason(image_urls, body) -> str:
    """额度兜底三段文案的最后一段：压缩 data URL 也塞不进 JSON 预算时补上实际字节数。"""
    total = apimart_json_body_bytes(body, image_urls)
    return (f"；压缩 data URL 兜底也放不下：{len(image_urls)} 张压到最小后请求体 {total} 字节，"
            f"仍超过预算 {APIMART_JSON_BODY_BUDGET} 字节。")

APIMART_TEMP_IMAGE_EXTENSIONS = {
    "image/jpeg": ".jpg",
    "image/png": ".png",
    "image/gif": ".gif",
    "image/webp": ".webp",
    "image/bmp": ".bmp",
    "image/tiff": ".tif",
}

def apimart_data_url_temp_image_file(raw: bytes, mime: str):
    """data URL 输入在额度兜底前落盘：图床链路只接受 /output/ 或 /assets/ 下的本地路径。
    返回 (临时文件对应的 URL, 实际路径)，调用方负责删除。"""
    clean_mime = str(mime or "").split(";", 1)[0].strip().lower() or "image/png"
    ext = APIMART_TEMP_IMAGE_EXTENSIONS.get(clean_mime) or mimetypes.guess_extension(clean_mime) or ".img"
    filename = f"apimart_tmp_{uuid.uuid4().hex[:12]}{ext}"
    path = output_path_for(filename, "output")
    with open(path, "wb") as fh:
        fh.write(raw)
    return output_url_for(filename, "output"), path

# 视频输入（VEO 等）首帧不需要 5000px：长边 >2048 或 >1.2MB 的大图先压到 900KB/2048px 再传图床，
# 小图原样直传不重编码（保画质）；阈值沿用 APIMart 首个上传档位，网关 1MB 拦截同样覆盖。
APIMART_VIDEO_INPUT_MAX_BYTES = 900_000
APIMART_VIDEO_INPUT_MAX_DIM = 2048
APIMART_VIDEO_INPUT_PASSTHROUGH_BYTES = int(1.2 * 1024 * 1024)
APIMART_VIDEO_INPUT_THUMB_PREFIX = "apimart_thumb_"

def apimart_video_input_thumbnail(ref_url: str):
    """视频输入图床链路的上传 payload：大图压成 ≤900KB、长边 ≤2048 的 JPEG，小图原样直传。
    返回 (上传用 ref_url, 临时文件路径)；不需要压缩或压缩失败时临时路径为空、ref_url 不变。"""
    ref_url = str(ref_url or "").strip()
    if not (ref_url.startswith("/output/") or ref_url.startswith("/assets/")):
        return ref_url, ""
    path = output_file_from_url(ref_url)
    if not path:
        return ref_url, ""
    try:
        size = os.path.getsize(path)
        with Image.open(path) as opened:
            width, height = opened.size
            img = opened.copy()
    except Exception as exc:
        print(f"视频输入图床压缩跳过（读取失败，回退原图直传）：{ref_url} {exc}")
        return ref_url, ""
    if size <= APIMART_VIDEO_INPUT_PASSTHROUGH_BYTES and max(width, height) <= APIMART_VIDEO_INPUT_MAX_DIM:
        return ref_url, ""
    temp_path = ""
    try:
        stem = APIMART_VIDEO_INPUT_THUMB_PREFIX.rstrip("_")
        _filename, payload, _content_type = apimart_jpeg_payload(
            img, APIMART_VIDEO_INPUT_MAX_BYTES, APIMART_VIDEO_INPUT_MAX_DIM, stem)
        with Image.open(BytesIO(payload)) as opened:
            thumb_width, thumb_height = opened.size
        filename = f"{APIMART_VIDEO_INPUT_THUMB_PREFIX}{uuid.uuid4().hex[:12]}.jpg"
        temp_path = output_path_for(filename, "output")
        with open(temp_path, "wb") as fh:
            fh.write(payload)
    except Exception as exc:
        if temp_path:
            try:
                os.remove(temp_path)
            except OSError:
                pass
        print(f"视频输入图床压缩失败，回退原图直传：{ref_url} {exc}")
        return ref_url, ""
    print(f"视频输入图床压缩：{width}x{height} / {size} 字节 → "
          f"{thumb_width}x{thumb_height} / {len(payload)} 字节")
    return output_url_for(filename, "output"), temp_path

async def apimart_image_via_temp_host(ref_url: str) -> Dict[str, str]:
    """复用现有临时图床链路（uguu → Litterbox → temp.sh，CLOUD_MEDIA_UPLOAD_SERVICE 仍可覆盖）
    换公网直链，再真发一次 GET 校验 image/*。上传前先把大图压到视频输入够用的档位，小图原样直传。
    视频输入链路默认先走这里，尽量不消耗 APIMart 的 2000 个/72 小时上传额度；
    图片生成链路只在 429 额度兜底时调用。成功返回 {"url", "service"}；失败抛 HTTPException。"""
    upload_ref, thumb_path = apimart_video_input_thumbnail(ref_url)
    try:
        uploaded = await upload_local_video_to_cloud(upload_ref, "auto")
    finally:
        if thumb_path:
            try:
                os.remove(thumb_path)
            except OSError:
                pass
    url = str((uploaded or {}).get("url") or "").strip()
    service = str((uploaded or {}).get("service") or "auto").strip() or "auto"
    if not url.lower().startswith(("http://", "https://")):
        raise HTTPException(status_code=502, detail=f"临时图床（{service}）没有返回可用的公网链接")
    check = await verify_cloud_media_direct_url(url)
    content_type = str(check.get("content_type") or "").strip().lower()
    if not check.get("ok"):
        raise HTTPException(status_code=502, detail=f"临时图床（{service}）直链校验失败：{check.get('reason') or '未知原因'}")
    if not content_type.startswith("image/"):
        raise HTTPException(status_code=502, detail=f"临时图床（{service}）直链不是图片：Content-Type {content_type or '空'}")
    print(f"本地图片已上传临时图床（temp-host({service})）：{url}")
    return {"url": url, "service": service}

async def apimart_quota_temp_host_fallback(ref_url: str, quota_reason: str) -> Dict[str, str]:
    """额度用尽后先试临时图床：成功返回 {"url", "service"}；失败返回 {"error": "ERR:..."}。
    错误串保持 "ERR:APIMart 图片上传额度已用尽" 前缀，apimart_error_is_quota 仍能识别。"""
    try:
        return await apimart_image_via_temp_host(ref_url)
    except HTTPException as exc:
        detail = str(exc.detail or "")
    except Exception as exc:
        detail = f"异常：{exc}"
    print(f"APIMart 上传额度用尽，临时图床兜底失败（temp-host）：{detail}")
    return {"error": f"ERR:{quota_reason}；临时图床兜底失败：{detail}"}

async def upload_image_for_apimart(client, provider, ref_url: str, prefer_temp_host: bool = False) -> str:
    """把本地图片转成上游可接受的输入。
    prefer_temp_host=True（视频输入链路默认）：先临时图床换公网直链并写入带 TTL 的缓存，
    失败再走 APIMart /v1/uploads/images（413 逐档压缩保留；429 返回额度提示 + 图床失败原因，
    调用方回退压缩 data URL）。
    prefer_temp_host=False（图片生成链路）：保持官方上传优先，只有 429 才用图床兜底，
    公网直链不扩散到图片生成。
    绝不把 /output/* 或 /assets/* 这类本地路径直接传给上游。
    返回上游可用 URL；返回值以 "ERR:" 开头表示具体失败原因（供前端展示）。"""
    ref_url = str(ref_url or "").strip()
    if not ref_url:
        return "ERR:空地址"
    # 已经是网络 URL 或 asset:// → 直接可用，无需上传
    if ref_url.startswith("http://") or ref_url.startswith("https://") or ref_url.startswith("asset://"):
        return ref_url
    base_url = video_api_root(provider)
    upload_url = f"{base_url}/v1/uploads/images"
    # data URL: 默认先临时图床（落盘 → 上传 → 删除），图床失败再上传到 APIMart
    if ref_url.startswith("data:"):
        temp_host_error = ""
        try:
            if ";base64," not in ref_url:
                return "ERR:不支持的 data URL（缺少 base64 段）"
            header, encoded = ref_url.split(";base64,", 1)
            mime = header.split(":", 1)[1].split(";", 1)[0] if ":" in header else "image/png"
            raw = base64.b64decode(encoded)
            if prefer_temp_host:
                print(f"图片输入策略：temp-host 优先（{APIMART_IMAGE_SOURCE_ENV}=temp），data URL → 临时文件")
                temp_ref, temp_path = "", ""
                try:
                    temp_ref, temp_path = apimart_data_url_temp_image_file(raw, mime)
                    uploaded = await apimart_image_via_temp_host(temp_ref)
                    return str(uploaded.get("url") or "")
                except HTTPException as exc:
                    temp_host_error = str(exc.detail or "")
                except Exception as exc:
                    temp_host_error = f"异常：{exc}"
                finally:
                    if temp_path:
                        try:
                            os.remove(temp_path)
                        except OSError:
                            pass
                print(f"临时图床不可用，回退 APIMart 上传（temp-host）：{temp_host_error}")
            variants = apimart_upload_payload_variants(data=raw, mime=mime, name_hint="canvas_image")
            resp, attempts = await apimart_upload_with_shrink(client, upload_url, api_headers(json_body=False, provider=provider), variants)
            if resp.status_code in (200, 201):
                rj = resp.json()
                url = extract_apimart_asset_url(rj)
                if valid_apimart_video_image_input(url):
                    print(f"APIMart 上传成功（apimart-upload）：data URL → {url}")
                    return url
                print(f"APIMart 上传 data URL 返回中未找到可用 asset/url: {str(rj)[:300]}")
                return "ERR:APIMart 上传响应未包含可用 URL"
            print(f"APIMart 上传 data URL 失败 ({resp.status_code}): {resp.text[:300]}")
            if apimart_upload_quota_exhausted(resp):
                if prefer_temp_host:
                    return f"ERR:{apimart_upload_failure_detail(resp, attempts)}；临时图床兜底失败：{temp_host_error}"
                temp_ref, temp_path = "", ""
                try:
                    temp_ref, temp_path = apimart_data_url_temp_image_file(raw, mime)
                    fallback = await apimart_quota_temp_host_fallback(temp_ref, apimart_upload_failure_detail(resp, attempts))
                    return str(fallback.get("url") or fallback.get("error") or "")
                finally:
                    if temp_path:
                        try:
                            os.remove(temp_path)
                        except OSError:
                            pass
            return f"ERR:{apimart_upload_failure_detail(resp, attempts)}"
        except ValueError as e:
            return f"ERR:{e}"
        except Exception as e:
            print(f"APIMart 上传 data URL 异常: {e}")
            return f"ERR:上传异常 {e}"
    # 本地 /output/ 或 /assets/ 路径：先确认文件存在再上传
    if ref_url.startswith("/output/") or ref_url.startswith("/assets/"):
        path = output_file_from_url(ref_url)
        if not path:
            print(f"APIMart 上传跳过：本地文件不存在 {ref_url}")
            return "ERR:本地文件不存在或已被删除"
        cache_key = apimart_upload_cache_key(path)
        cached = apimart_upload_cache_get(cache_key)
        if cached:
            print(f"APIMart 图片缓存命中（跳过上传/图床）：{ref_url} → {cached}")
            return cached
        temp_host_error = ""
        if prefer_temp_host:
            print(f"图片输入策略：temp-host 优先（{APIMART_IMAGE_SOURCE_ENV}=temp）：{ref_url}")
            try:
                uploaded = await apimart_image_via_temp_host(ref_url)
                url = str(uploaded.get("url") or "")
                service = str(uploaded.get("service") or "")
                apimart_upload_cache_put(cache_key, url, apimart_temp_host_url_ttl(service), f"temp-host:{service}")
                return url
            except HTTPException as exc:
                temp_host_error = str(exc.detail or "")
            except Exception as exc:
                temp_host_error = f"异常：{exc}"
            print(f"临时图床不可用，回退 APIMart 上传（temp-host）：{temp_host_error}")
        try:
            variants = apimart_upload_payload_variants(path=path)
            resp, attempts = await apimart_upload_with_shrink(client, upload_url, api_headers(json_body=False, provider=provider), variants)
            if resp.status_code in (200, 201):
                rj = resp.json()
                url = extract_apimart_asset_url(rj)
                if valid_apimart_video_image_input(url):
                    apimart_upload_cache_put(cache_key, url, APIMART_UPLOAD_ASSET_TTL_SECONDS, "apimart-upload")
                    print(f"APIMart 上传成功（apimart-upload）：{ref_url} → {url}")
                    return url
                print(f"APIMart 文件上传返回中未找到可用 asset/url: {str(rj)[:300]}")
                return "ERR:APIMart 上传响应未包含可用 URL"
            print(f"APIMart 文件上传失败 ({resp.status_code}): {resp.text[:300]}")
            quota_reason = apimart_upload_failure_detail(resp, attempts)
            if apimart_upload_quota_exhausted(resp):
                if prefer_temp_host:
                    return f"ERR:{quota_reason}；临时图床兜底失败：{temp_host_error}"
                fallback = await apimart_quota_temp_host_fallback(ref_url, quota_reason)
                fallback_url = str(fallback.get("url") or "")
                if fallback_url:
                    service = str(fallback.get("service") or "")
                    apimart_upload_cache_put(cache_key, fallback_url, apimart_temp_host_url_ttl(service), f"temp-host:{service}")
                    print(f"APIMart 上传额度用尽，临时图床 URL 已写入缓存（temp-host）：{ref_url} → {fallback_url}")
                    return fallback_url
                return str(fallback.get("error") or f"ERR:{quota_reason}")
            return f"ERR:{quota_reason}"
        except ValueError as e:
            return f"ERR:{e}"
        except Exception as e:
            print(f"APIMart 文件上传异常: {e}")
            return f"ERR:上传异常 {e}"
    return "ERR:不支持的图片来源（仅支持 http/https/asset/data 或本地 /output/ /assets/ 路径）"

async def upload_video_image_for_apimart(client, provider, ref_url: str) -> str:
    """APIMart 视频输入专用的本地图 → 可用输入：按 APIMART_IMAGE_SOURCE 决定优先级。
    默认 temp：先临时图床（不消耗 APIMart 上传额度），失败再走官方上传；
    apimart：旧顺序（官方上传优先，429 才用图床兜底）。
    图片生成链路直接调用 upload_image_for_apimart，不经过这里，公网直链不会扩散到图片生成。"""
    source = apimart_image_source()
    if source != "temp":
        print(f"图片输入策略：APIMart 上传优先（{APIMART_IMAGE_SOURCE_ENV}={source}）")
    return await upload_image_for_apimart(
        client, provider, ref_url, prefer_temp_host=source == "temp")

async def apimart_image_reference_inputs(client, provider, refs, body):
    """直发 data URL 放得下就走原路径、不上传；超预算时先压小再上传压缩图，换公网 URL 保住多图画质。
    上传撞上 429 额度用尽时先试临时图床，图床也失败才回退压缩 data URL；
    压缩后仍塞不进预算才抛三段文案（额度用尽 → 图床失败原因 → data URL 超预算）。"""
    direct = [reference_to_data_url(ref, max_size=1536) for ref in refs]
    if apimart_json_body_bytes(body, direct) <= APIMART_JSON_BODY_BUDGET:
        return direct
    compressed, fits = apimart_reference_data_urls_with_fit(refs, body)
    uploaded = []
    for url in compressed:
        try:
            up_url = await upload_image_for_apimart(client, provider, url)
        except Exception as e:
            print(f"APIMart 参考图上传异常，改用压缩 data URL：{invalid_video_image_preview(url)} {e}")
            return compressed
        if not str(up_url or "").strip().lower().startswith(("http://", "https://")):
            if apimart_error_is_quota(up_url):
                if not fits:
                    raise HTTPException(
                        status_code=400,
                        detail=str(up_url)[4:] + apimart_data_url_over_budget_reason(compressed, body),
                    )
                print(f"APIMart 上传额度用尽，回退压缩 data URL（data-url）：{invalid_video_image_preview(url)}")
            else:
                print(f"APIMart 参考图上传不可用，改用压缩 data URL（data-url）：{invalid_video_image_preview(url)} {up_url}")
            return compressed
        uploaded.append(up_url)
    return uploaded

# 参考视频走临时图床前的可选压缩：原文件直传又慢又容易撞图床体积限制。
VIDEO_CLOUD_COMPRESS_THRESHOLD_BYTES = int(os.getenv("VIDEO_CLOUD_COMPRESS_THRESHOLD_BYTES", str(24 * 1024 * 1024)))
VIDEO_CLOUD_COMPRESS_MAX_EDGE = int(os.getenv("VIDEO_CLOUD_COMPRESS_MAX_EDGE", "1280"))
VIDEO_CLOUD_COMPRESS_CRF = int(os.getenv("VIDEO_CLOUD_COMPRESS_CRF", "26"))
VIDEO_CLOUD_COMPRESS_PRESET = (os.getenv("VIDEO_CLOUD_COMPRESS_PRESET") or "veryfast").strip() or "veryfast"
VIDEO_CLOUD_COMPRESS_TIMEOUT = int(os.getenv("VIDEO_CLOUD_COMPRESS_TIMEOUT", "600"))

def probe_video_dimensions(path: str) -> Tuple[int, int]:
    """取视频宽高：优先 ffprobe，没装 ffprobe 时用 opencv；都失败返回 (0, 0)。"""
    ffprobe = ffprobe_binary()
    if ffprobe:
        try:
            proc = subprocess.run(
                [ffprobe, "-v", "error", "-select_streams", "v:0",
                 "-show_entries", "stream=width,height", "-of", "csv=p=0:s=x", path],
                capture_output=True, text=True, timeout=30,
            )
            lines = str(proc.stdout or "").strip().splitlines()
            if proc.returncode == 0 and lines:
                parts = lines[0].split("x")
                width, height = int(parts[0]), int(parts[1])
                if width > 0 and height > 0:
                    return width, height
        except Exception:
            pass
    try:
        import cv2
        cap = cv2.VideoCapture(path)
        try:
            if cap.isOpened():
                width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH) or 0)
                height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT) or 0)
                if width > 0 and height > 0:
                    return width, height
        finally:
            cap.release()
    except Exception:
        pass
    return 0, 0

def video_has_audio_stream(ffprobe: Optional[str], path: str) -> Optional[bool]:
    """ffprobe 判断有没有音轨；ffprobe 缺失或探测失败返回 None（按有音轨处理）。"""
    if not ffprobe:
        return None
    try:
        proc = subprocess.run(
            [ffprobe, "-v", "error", "-select_streams", "a",
             "-show_entries", "stream=index", "-of", "csv=p=0", path],
            capture_output=True, text=True, timeout=20,
        )
        if proc.returncode != 0:
            return None
        return bool(str(proc.stdout or "").strip())
    except Exception:
        return None

def compression_scale_filter(width: int, height: int) -> str:
    """长边缩到 1280，短边按比例取偶数；只有一边超限时不放大另一边。"""
    if width >= height:
        return f"scale='min({VIDEO_CLOUD_COMPRESS_MAX_EDGE},iw)':-2"
    return f"scale=-2:'min({VIDEO_CLOUD_COMPRESS_MAX_EDGE},ih)'"

def compress_video_for_cloud_upload(path: str) -> Dict[str, Any]:
    """视频传图床前按需压缩：>24MB 或长边 >1280 → H.264 MP4（长边 1280 / CRF 26 / veryfast）。
    返回 {"path": 压缩产物路径或 "", "reason": 备注, "size", "width", "height", "duration"}；
    压缩产物由调用方删除。没装 ffmpeg、探测不到、压缩失败或压完更大时一律用原文件。"""
    info: Dict[str, Any] = {
        "path": "", "reason": "", "size": 0, "width": 0, "height": 0,
        "duration": probe_video_file_duration_seconds(path),
    }
    try:
        info["size"] = os.path.getsize(path)
    except OSError as exc:
        info["reason"] = f"读取原视频失败：{exc}"
        return info
    width, height = probe_video_dimensions(path)
    info["width"], info["height"] = width, height
    long_edge = max(width, height)
    if info["size"] <= VIDEO_CLOUD_COMPRESS_THRESHOLD_BYTES and long_edge <= VIDEO_CLOUD_COMPRESS_MAX_EDGE:
        info["reason"] = "未超过压缩触发条件"
        return info
    ffmpeg = ffmpeg_binary()
    if not ffmpeg:
        info["reason"] = "未找到 ffmpeg，跳过压缩"
        print(f"参考视频压缩跳过：未找到 ffmpeg，跳过压缩（原 {info['size']} 字节）")
        return info
    duration_text = f"{info['duration']:.1f}s" if info["duration"] else "时长未知"
    stem = re.sub(r"[^A-Za-z0-9._-]+", "_", os.path.splitext(os.path.basename(path))[0])[:40] or "video"
    try:
        fd, temp_path = tempfile.mkstemp(prefix=f"apimart_video_{stem}_", suffix=".mp4")
        os.close(fd)
    except OSError as exc:
        info["reason"] = f"创建临时文件失败：{exc}"
        print(f"参考视频压缩失败，回退原文件：{info['reason']}")
        return info
    audio_args = ["-c:a", "aac", "-b:a", "128k"]
    if video_has_audio_stream(ffprobe_binary(), path) is False:
        audio_args = ["-an"]
    cmd = [
        ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
        "-i", path,
        "-vf", compression_scale_filter(width, height),
        "-c:v", "libx264", "-crf", str(VIDEO_CLOUD_COMPRESS_CRF),
        "-preset", VIDEO_CLOUD_COMPRESS_PRESET,
        "-pix_fmt", "yuv420p",
    ] + audio_args + ["-movflags", "+faststart", temp_path]
    try:
        proc = subprocess.run(
            cmd, capture_output=True, text=True, timeout=VIDEO_CLOUD_COMPRESS_TIMEOUT)
    except Exception as exc:
        try:
            os.remove(temp_path)
        except OSError:
            pass
        info["reason"] = f"ffmpeg 执行异常：{exc}"
        print(f"参考视频压缩失败，回退原文件：{info['reason']}")
        return info
    try:
        new_size = os.path.getsize(temp_path)
    except OSError:
        new_size = 0
    if proc.returncode != 0 or new_size <= 0:
        try:
            os.remove(temp_path)
        except OSError:
            pass
        stderr = (proc.stderr or "").strip()[:300]
        info["reason"] = f"ffmpeg 压缩失败：{stderr or '没有生成输出文件'}"
        print(f"参考视频压缩失败，回退原文件：{info['reason']}")
        return info
    if new_size >= info["size"]:
        try:
            os.remove(temp_path)
        except OSError:
            pass
        info["reason"] = f"压缩后更大（{new_size} >= {info['size']} 字节），回退原文件"
        print(f"参考视频压缩未采用：{info['reason']}")
        return info
    info["path"] = temp_path
    info["reason"] = "压缩成功"
    print(f"参考视频压缩：原 {info['size']} 字节 {width}x{height} {duration_text} → 压缩后 {new_size} 字节"
          f"（{new_size * 100 // info['size']}%）")
    return info

async def apimart_cloud_media_fallback(ref_url: str, reason: str, path_override: str = "") -> str:
    """APIMart 没有可用的音视频上传端点时，退回公开网盘换 http(s) 链接。
    path_override 非空时上传该本地文件（视频压缩后的临时文件），source 仍记原 ref_url。"""
    try:
        if path_override:
            uploaded = await upload_local_video_to_cloud(ref_url, "auto", path_override)
        else:
            uploaded = await upload_local_video_to_cloud(ref_url)
    except HTTPException as exc:
        print(f"APIMart 参考素材云上传失败：{exc.detail}")
        return (f"ERR:APIMart 上传入口不可用（{reason}），云上传也失败：{exc.detail}。"
                "请检查网络后重试，或配置 PUBLIC_BASE_URL/PUBLIC_MEDIA_BASE_URL 把本地素材暴露成公网地址。")
    except Exception as exc:
        print(f"APIMart 参考素材云上传异常：{exc}")
        return (f"ERR:APIMart 上传入口不可用（{reason}），云上传异常：{exc}。"
                "请检查网络后重试，或配置 PUBLIC_BASE_URL/PUBLIC_MEDIA_BASE_URL 把本地素材暴露成公网地址。")
    url = str((uploaded or {}).get("url") or "").strip()
    if valid_apimart_video_image_input(url):
        service = str((uploaded or {}).get("service") or "auto").strip() or "auto"
        local_path = str(path_override or output_file_from_url(ref_url) or "")
        size_note = ""
        if local_path and os.path.isfile(local_path):
            size_note = f"（{os.path.getsize(local_path)} 字节）"
        print(f"参考素材已上传临时图床（{service}）：{url}{size_note}")
        return url
    return (f"ERR:APIMart 上传入口不可用（{reason}），云上传未返回可用的公网链接。"
            "请检查网络后重试，或配置 PUBLIC_BASE_URL/PUBLIC_MEDIA_BASE_URL。")

async def apimart_video_cloud_media_fallback(ref_url: str, reason: str) -> str:
    """参考视频上传图床前的可选压缩：大视频先转 H.264 临时文件，上传完（成功失败都）删除。
    原文件超过图床大小限制时不做压缩，保持原有「超过大小限制」报错。"""
    try:
        path = local_media_path_for_cloud_upload(ref_url)
    except HTTPException:
        return await apimart_cloud_media_fallback(ref_url, reason)
    try:
        compressed = await asyncio.to_thread(compress_video_for_cloud_upload, path)
    except Exception as exc:
        print(f"参考视频压缩异常，回退原文件：{exc}")
        compressed = {"path": ""}
    temp_path = str(compressed.get("path") or "")
    try:
        return await apimart_cloud_media_fallback(ref_url, reason, temp_path)
    finally:
        if temp_path:
            try:
                os.remove(temp_path)
            except OSError:
                pass

def apimart_native_video_upload_enabled() -> bool:
    """APIMart 自己的上传端点默认作为兜底开启；显式设 APIMART_TRY_VIDEO_UPLOAD=0/false/off 才关掉。"""
    flag = str(os.getenv("APIMART_TRY_VIDEO_UPLOAD") or "").strip().lower()
    return flag not in {"0", "false", "no", "off"}


async def apimart_native_video_upload(client, provider, path: str) -> Tuple[str, str]:
    """把本地参考视频传进 APIMart 自己的上传端点，返回 (可用链接, 最后一次失败原因)。
    实测 /v1/uploads/videos 收视频并回 {url, bytes, content_type, expires_at}；
    链接为空表示这层兜底不可用，调用方继续报原来的错误。"""
    base_url = video_api_root(provider)
    filename, content, content_type = apimart_upload_raw_file_payload(path)
    upload_paths = ("/v1/uploads/videos", "/v1/uploads/files", "/v1/uploads/images")
    last_error = ""
    for upload_path in upload_paths:
        upload_url = f"{base_url}{upload_path}"
        try:
            files = {"file": (filename, content, content_type)}
            resp = await client.post(upload_url, headers=api_headers(json_body=False, provider=provider), files=files, timeout=180)
            if resp.status_code in (200, 201):
                rj = resp.json()
                url = extract_apimart_asset_url(rj)
                if valid_apimart_video_image_input(url):
                    print(f"参考视频已上传 APIMart（{upload_path}）：{url}")
                    return url, ""
                last_error = f"{upload_path} 响应里没有可用 URL"
                print(f"APIMart 视频上传返回中未找到可用 asset/url ({upload_path}): {str(rj)[:300]}")
                continue
            last_error = f"{upload_path} 返回 {resp.status_code}: {resp.text[:200]}"
            print(f"APIMart 视频上传失败 {last_error}")
        except Exception as e:
            last_error = f"{upload_path} 异常：{e}"
            print(f"APIMart 视频上传异常: {last_error}")
    return "", last_error or "上传端点返回 404"

async def upload_video_for_apimart(client, provider, ref_url: str) -> str:
    """尽力把本地参考视频转换为 APIMart 可接受的 http/https 或 asset:// URL。

    顺序：已有公网地址 → PUBLIC_BASE_URL → 免费临时图床（不花 APIMart 额度）→ APIMart 原生上传。
    临时图床近两年关停/改版很频繁（uguu 502、Litterbox 500、temp.sh 改成 HTML 查看页，
    2026-11-13 三种同时挂），所以最后必须用 APIMart 自己的上传端点兜底，
    APIMART_TRY_VIDEO_UPLOAD=0/false/off 可以关掉这层兜底。"""
    ref_url = str(ref_url or "").strip()
    if not ref_url:
        return "ERR:空地址"
    if valid_apimart_video_image_input(ref_url):
        return ref_url
    public_url = local_asset_public_url(ref_url)
    if public_url:
        return public_url
    if not (ref_url.startswith("/output/") or ref_url.startswith("/assets/")):
        return f"ERR:{apimart_video_reference_error(ref_url)}"
    path = output_file_from_url(ref_url)
    if not path:
        return "ERR:本地视频不存在或已被删除"
    ct = content_type_for_path(path)
    if not ct.startswith("video/"):
        return "ERR:参考视频不是可识别的视频文件"
    cloud_result = await apimart_video_cloud_media_fallback(ref_url, "临时图床均不可用")
    if not str(cloud_result).startswith("ERR:"):
        return cloud_result
    if not apimart_native_video_upload_enabled():
        return cloud_result
    native_url, native_error = await apimart_native_video_upload(client, provider, path)
    if native_url:
        return native_url
    # 保持「ERR:APIMart 上传入口不可用…」这条老文案开头（前端和测试都按它识别），原生上传的失败原因追加在后
    return f"{cloud_result}（APIMart 原生上传：{native_error}）"

async def upload_audio_for_apimart(client, provider, ref_url: str) -> str:
    """把本地参考音频转换为 APIMart 可接受的 http/https 或 asset:// URL。
    优先用公网地址（PUBLIC_BASE_URL），否则尝试上传到 APIMart 文件端点；
    端点不可用时回退云端网盘（temp.sh）换链接。返回值以 "ERR:" 开头表示失败原因。"""
    ref_url = str(ref_url or "").strip()
    if not ref_url:
        return "ERR:空地址"
    if valid_apimart_video_image_input(ref_url):
        return ref_url
    public_url = local_asset_public_url(ref_url)
    if public_url:
        return public_url
    base_url = video_api_root(provider)
    upload_paths = ("/v1/uploads/audios", "/v1/uploads/files", "/v1/uploads/images")
    last_error = ""
    if ref_url.startswith("data:"):
        if ";base64," not in ref_url:
            return "ERR:不支持的 data URL（缺少 base64 段）"
        header, encoded = ref_url.split(";base64,", 1)
        mime = header.split(":", 1)[1].split(";", 1)[0] if ":" in header else "audio/mpeg"
        try:
            raw = base64.b64decode(encoded)
        except Exception as exc:
            return f"ERR:音频 data URL 解码失败：{exc}"
        ext = mimetypes.guess_extension(mime) or ".mp3"
        filename, content, content_type = (f"canvas_audio{ext}", raw, mime or "audio/mpeg")
    elif ref_url.startswith("/output/") or ref_url.startswith("/assets/"):
        path = output_file_from_url(ref_url)
        if not path:
            return "ERR:本地音频不存在或已被删除"
        ct = content_type_for_path(path)
        if not ct.startswith("audio/"):
            return "ERR:参考音频不是可识别的音频文件"
        filename, content, content_type = apimart_upload_raw_file_payload(path)
    else:
        return f"ERR:{apimart_video_reference_error(ref_url)}"
    for upload_path in upload_paths:
        upload_url = f"{base_url}{upload_path}"
        try:
            files = {"file": (filename, content, content_type)}
            resp = await client.post(upload_url, headers=api_headers(json_body=False, provider=provider), files=files, timeout=180)
            if resp.status_code in (200, 201):
                rj = resp.json()
                url = extract_apimart_asset_url(rj)
                if valid_apimart_video_image_input(url):
                    return url
                last_error = "上传响应未包含可用 URL"
                continue
            last_error = f"{upload_path} 返回 {resp.status_code}: {resp.text[:200]}"
        except Exception as exc:
            last_error = f"{upload_path} 异常：{exc}"
    if ref_url.startswith(("/output/", "/assets/")):
        return await apimart_cloud_media_fallback(ref_url, last_error or "上传端点返回 404")
    return f"ERR:APIMart 未提供可用的音频文件上传入口（{last_error}）。请使用公网 http/https / asset:// 音频地址。"

async def upload_media_for_apimart(client, provider, ref_url: str, kind: str) -> str:
    """按 kind 分派到对应的 APIMart 上传器，拿回上游可用的 http/https/asset:// URL。"""
    if kind == "video":
        return await upload_video_for_apimart(client, provider, ref_url)
    if kind == "audio":
        return await upload_audio_for_apimart(client, provider, ref_url)
    return await upload_image_for_apimart(client, provider, ref_url)

def apimart_avatar_asset_type(kind: str) -> str:
    return {"video": "Video", "audio": "Audio"}.get(str(kind or "").lower(), "Image")

def extract_apimart_avatar_asset_uri(payload) -> str:
    """从 /v1/tasks 审核结果里取出 asset://<id> 形式的可信素材 URI。"""
    if isinstance(payload, list):
        for item in payload:
            found = extract_apimart_avatar_asset_uri(item)
            if found:
                return found
        return ""
    if not isinstance(payload, dict):
        return ""
    for key in ("asset_url", "assetUrl", "uri", "url"):
        value = str(payload.get(key) or "").strip()
        if value.startswith("asset://"):
            return value
    for key in ("usable_assets", "assets", "result", "data"):
        found = extract_apimart_avatar_asset_uri(payload.get(key))
        if found:
            return found
    asset_id = str(payload.get("asset_id") or payload.get("assetId") or "").strip()
    if asset_id:
        return f"asset://{asset_id}"
    return ""

async def submit_apimart_avatar_asset(provider, public_url: str, name: str, kind: str, project_name: str = "default", group_name: str = "") -> str:
    """把一个公网可访问的素材提交到 APIMart private-avatar 审核，立即返回任务 ID（不阻塞轮询）。"""
    base_url = video_api_root(provider)
    if not base_url:
        raise HTTPException(status_code=400, detail=f"{provider.get('name') or provider['id']} 未配置 Base URL")
    register_url = f"{base_url}/v1/seedance2/private-avatar"
    body = {
        "project_name": str(project_name or "default").strip() or "default",
        "asset_type": apimart_avatar_asset_type(kind),
        "group": {"name": (group_name or name or "数字人素材")[:60]},
        "assets": [{"url": public_url, "name": (name or "asset")[:60]}],
    }
    async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=120) as client:
        resp = await client.post(register_url, headers=api_headers(provider=provider), json=body, timeout=120)
        if resp.status_code not in (200, 201):
            raise HTTPException(status_code=502, detail=f"APIMart 数字人注册失败（{resp.status_code}）：{resp.text[:300]}")
        data = resp.json()
        task = data.get("data") if isinstance(data.get("data"), dict) else data
        task_id = str(task.get("id") or task.get("task_id") or "").strip()
        if not task_id:
            raise HTTPException(status_code=502, detail=f"APIMart 数字人注册返回中未找到任务 ID：{str(data)[:300]}")
        return task_id

AVATAR_TASK_DONE_STATUSES = {"completed", "complete", "succeeded", "success", "active", "done"}
AVATAR_TASK_FAIL_STATUSES = {"failed", "fail", "error", "rejected", "canceled", "cancelled", "expired"}

async def check_apimart_avatar_task(provider, task_id: str) -> Dict[str, Any]:
    """查询一次 APIMart 审核任务。返回 {status: Active/Processing/Failed, asset_uri, detail}。"""
    base_url = video_api_root(provider)
    if not base_url:
        raise HTTPException(status_code=400, detail=f"{provider.get('name') or provider['id']} 未配置 Base URL")
    task_url = f"{base_url}/v1/tasks/{task_id}"
    async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=60) as client:
        resp = await client.get(task_url, headers=api_headers(provider=provider), timeout=60)
        if resp.status_code not in (200, 201):
            raise HTTPException(status_code=502, detail=f"查询审核状态失败（{resp.status_code}）：{resp.text[:200]}")
        payload = resp.json()
    node = payload.get("data") if isinstance(payload.get("data"), dict) else payload
    status = str(node.get("status") or "").strip().lower()
    if status in AVATAR_TASK_DONE_STATUSES:
        asset_uri = extract_apimart_avatar_asset_uri(payload)
        if not asset_uri:
            return {"status": "Failed", "asset_uri": "", "detail": "审核完成，但未返回可用的 asset:// 地址（可能部分素材被拒）。"}
        return {"status": "Active", "asset_uri": asset_uri, "detail": ""}
    if status in AVATAR_TASK_FAIL_STATUSES:
        return {"status": "Failed", "asset_uri": "", "detail": f"审核未通过（{status}）。"}
    return {"status": "Processing", "asset_uri": "", "detail": "审核中"}

# ---- 火山 Ark 私域素材资产（Assets）API：AK/SK 签名 V4 + CreateAssetGroup/CreateAsset/GetAsset ----
VOLCENGINE_ARK_ASSET_HOST = "open.volcengineapi.com"
VOLCENGINE_ARK_ASSET_SERVICE = "ark"
VOLCENGINE_ARK_ASSET_REGION = "cn-beijing"
VOLCENGINE_ARK_ASSET_VERSION = "2024-01-01"

def _volc_hmac(key: bytes, msg: str) -> bytes:
    return hmac.new(key, msg.encode("utf-8"), hashlib.sha256).digest()

def volcengine_sign_v4_headers(ak: str, sk: str, action: str, body_str: str,
                               service: str = VOLCENGINE_ARK_ASSET_SERVICE,
                               region: str = VOLCENGINE_ARK_ASSET_REGION,
                               version: str = VOLCENGINE_ARK_ASSET_VERSION,
                               host: str = VOLCENGINE_ARK_ASSET_HOST) -> Dict[str, str]:
    """火山引擎 OpenAPI 签名 V4（POST + JSON body）。返回需随请求发送的鉴权头。"""
    method = "POST"
    content_type = "application/json"
    now = datetime.datetime.now(datetime.timezone.utc)
    x_date = now.strftime("%Y%m%dT%H%M%SZ")
    short_date = x_date[:8]
    payload_hash = hashlib.sha256(body_str.encode("utf-8")).hexdigest()
    # 查询串按键排序：Action < Version
    canonical_query = f"Action={urllib.parse.quote(action, safe='')}&Version={urllib.parse.quote(version, safe='')}"
    canonical_headers = (
        f"content-type:{content_type}\n"
        f"host:{host}\n"
        f"x-content-sha256:{payload_hash}\n"
        f"x-date:{x_date}\n"
    )
    signed_headers = "content-type;host;x-content-sha256;x-date"
    canonical_request = "\n".join([method, "/", canonical_query, canonical_headers, signed_headers, payload_hash])
    algorithm = "HMAC-SHA256"
    credential_scope = f"{short_date}/{region}/{service}/request"
    string_to_sign = "\n".join([
        algorithm, x_date, credential_scope,
        hashlib.sha256(canonical_request.encode("utf-8")).hexdigest(),
    ])
    k_date = _volc_hmac(sk.encode("utf-8"), short_date)
    k_region = _volc_hmac(k_date, region)
    k_service = _volc_hmac(k_region, service)
    k_signing = _volc_hmac(k_service, "request")
    signature = hmac.new(k_signing, string_to_sign.encode("utf-8"), hashlib.sha256).hexdigest()
    authorization = (
        f"{algorithm} Credential={ak}/{credential_scope}, "
        f"SignedHeaders={signed_headers}, Signature={signature}"
    )
    return {
        "Content-Type": content_type,
        "Host": host,
        "X-Date": x_date,
        "X-Content-Sha256": payload_hash,
        "Authorization": authorization,
    }

async def volcengine_ark_asset_call(client, action: str, body: Dict[str, Any]) -> Dict[str, Any]:
    """调用一次火山 Ark Assets OpenAPI，返回 Result 内容；出错抛 HTTPException。"""
    ak = volcengine_access_key_value()
    sk = volcengine_secret_key_value()
    if not ak or not sk:
        raise HTTPException(status_code=400, detail="未配置火山引擎 AK/SK，请在 API 设置中填写 Access Key ID / Secret Access Key。")
    body_str = json.dumps(body, ensure_ascii=False)
    headers = volcengine_sign_v4_headers(ak, sk, action, body_str)
    url = f"https://{VOLCENGINE_ARK_ASSET_HOST}/?Action={urllib.parse.quote(action, safe='')}&Version={urllib.parse.quote(VOLCENGINE_ARK_ASSET_VERSION, safe='')}"
    resp = await client.post(url, headers=headers, content=body_str.encode("utf-8"), timeout=120)
    try:
        payload = resp.json()
    except Exception:
        raise HTTPException(status_code=502, detail=f"火山 {action} 返回非 JSON（{resp.status_code}）：{resp.text[:300]}")
    meta = payload.get("ResponseMetadata") if isinstance(payload, dict) else None
    if isinstance(meta, dict) and isinstance(meta.get("Error"), dict):
        err = meta["Error"]
        code = err.get("Code") or err.get("CodeN") or ""
        msg = err.get("Message") or ""
        raise HTTPException(status_code=502, detail=f"火山 {action} 失败：{code} {msg}".strip())
    if resp.status_code not in (200, 201):
        raise HTTPException(status_code=502, detail=f"火山 {action} 失败（{resp.status_code}）：{resp.text[:300]}")
    result = payload.get("Result") if isinstance(payload, dict) and isinstance(payload.get("Result"), dict) else None
    return result if result is not None else (payload if isinstance(payload, dict) else {})

async def volcengine_ensure_asset_group(client, project_name: str, group_name: str) -> str:
    """复用同名素材组合，没有则新建。返回 GroupId。"""
    name = (group_name or "可信素材").strip()[:60] or "可信素材"
    project_name = (project_name or "default").strip() or "default"
    # 先按 Name 模糊查找复用
    try:
        listed = await volcengine_ark_asset_call(client, "ListAssetGroups", {
            "Filter": {"Name": name, "GroupType": "AIGC"},
            "PageNumber": 1, "PageSize": 10, "ProjectName": project_name,
        })
        for item in (listed.get("Items") or []):
            if str(item.get("Name") or "").strip() == name and str(item.get("ProjectName") or "default") == project_name:
                gid = str(item.get("Id") or "").strip()
                if gid:
                    return gid
    except HTTPException:
        pass  # 查询失败不致命，继续走新建
    created = await volcengine_ark_asset_call(client, "CreateAssetGroup", {
        "Name": name, "Description": name, "ProjectName": project_name,
    })
    gid = str(created.get("Id") or "").strip()
    if not gid:
        raise HTTPException(status_code=502, detail=f"火山 CreateAssetGroup 未返回 GroupId：{str(created)[:200]}")
    return gid

async def submit_volcengine_avatar_asset(public_url: str, name: str, kind: str,
                                         project_name: str = "default", group_name: str = "") -> str:
    """把公网可访问素材提交到火山 Ark 私域素材库（异步）。返回 Asset Id 作为任务 ID。"""
    async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=120) as client:
        group_id = await volcengine_ensure_asset_group(client, project_name, group_name)
        created = await volcengine_ark_asset_call(client, "CreateAsset", {
            "GroupId": group_id,
            "URL": public_url,
            "AssetType": apimart_avatar_asset_type(kind),
            "Name": (name or "asset")[:60],
            "ProjectName": (project_name or "default").strip() or "default",
        })
    asset_id = str(created.get("Id") or "").strip()
    if not asset_id:
        raise HTTPException(status_code=502, detail=f"火山 CreateAsset 未返回 Asset Id：{str(created)[:200]}")
    return asset_id

async def check_volcengine_avatar_task(asset_id: str, project_name: str = "default") -> Dict[str, Any]:
    """查询一次火山素材状态。返回 {status: Active/Processing/Failed, asset_uri, detail}。"""
    async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=60) as client:
        info = await volcengine_ark_asset_call(client, "GetAsset", {
            "Id": asset_id,
            "ProjectName": (project_name or "default").strip() or "default",
        })
    status = str(info.get("Status") or "").strip()
    if status == "Active":
        return {"status": "Active", "asset_uri": f"asset://{asset_id}", "detail": ""}
    if status == "Failed":
        return {"status": "Failed", "asset_uri": "", "detail": "火山素材处理失败，无法用于推理。"}
    return {"status": "Processing", "asset_uri": "", "detail": "火山素材处理中"}

def volcengine_public_asset_url(url: str) -> str:
    """火山 CreateAsset 要求 URL 公网可访问；本地文件需 PUBLIC_BASE_URL，否则返回 ERR:。"""
    text = str(url or "").strip()
    if text.startswith("http://") or text.startswith("https://"):
        return text
    public = local_asset_public_url(text)
    if public:
        return public
    return "ERR:火山要求素材是公网可访问的 http/https URL；本地画布文件需配置 PUBLIC_BASE_URL/PUBLIC_MEDIA_BASE_URL 暴露为公网地址。"

def local_media_path_for_cloud_upload(ref_url: str, allowed_prefixes=("image/", "video/", "audio/")) -> str:
    ref_url = str(ref_url or "").strip()
    if not ref_url:
        raise HTTPException(status_code=400, detail="没有可上传的媒体文件")
    if ref_url.startswith("http://") or ref_url.startswith("https://"):
        return ""
    if not (ref_url.startswith("/output/") or ref_url.startswith("/assets/")):
        raise HTTPException(status_code=400, detail="云端上传只支持画布里的本地图片、视频或音频文件")
    path = output_file_from_url(ref_url)
    if not path:
        raise HTTPException(status_code=404, detail="本地媒体文件不存在或已被删除")
    ct = content_type_for_path(path)
    if not any(ct.startswith(prefix) for prefix in allowed_prefixes):
        raise HTTPException(status_code=400, detail="请选择图片、视频或音频文件再上传云端")
    max_bytes = int(os.getenv("TEMP_SH_MAX_BYTES", str(4 * 1024 * 1024 * 1024)))
    size = os.path.getsize(path)
    if size > max_bytes:
        raise HTTPException(status_code=400, detail=f"媒体文件超过云端上传大小限制：{size} bytes")
    return path

def local_video_path_for_cloud_upload(ref_url: str) -> str:
    return local_media_path_for_cloud_upload(ref_url, ("video/",))

async def upload_video_to_litterbox(path: str, source_url: str) -> Dict[str, str]:
    upload_url = os.getenv("LITTERBOX_UPLOAD_URL", "https://litterbox.catbox.moe/resources/internals/api.php").strip() or "https://litterbox.catbox.moe/resources/internals/api.php"
    time_value = os.getenv("LITTERBOX_TIME", "72h").strip() or "72h"
    ct = content_type_for_path(path)
    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=httpx.Timeout(connect=20.0, read=600.0, write=600.0, pool=20.0), follow_redirects=True) as client:
            with open(path, "rb") as fh:
                files = {"fileToUpload": (os.path.basename(path), fh, ct)}
                data = {"reqtype": "fileupload", "time": time_value}
                response = await client.post(upload_url, data=data, files=files)
        if not response.is_success:
            raise HTTPException(status_code=response.status_code, detail=f"Litterbox 上传失败：{response.text[:300]}")
        direct_url = response.text.strip().splitlines()[0].strip()
        if not re.match(r"^https?://", direct_url, re.I):
            raise HTTPException(status_code=502, detail=f"Litterbox 返回了无法识别的链接：{response.text[:300]}")
        return {"url": direct_url, "source": source_url, "name": os.path.basename(path), "expires": time_value, "service": "litterbox"}
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"Litterbox 上传异常：{exc}") from exc

async def upload_video_to_temp_sh(path: str, source_url: str) -> Dict[str, str]:
    upload_url = os.getenv("TEMP_SH_UPLOAD_URL", "https://temp.sh/upload").strip() or "https://temp.sh/upload"
    ct = content_type_for_path(path)
    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=httpx.Timeout(connect=20.0, read=600.0, write=600.0, pool=20.0), follow_redirects=True) as client:
            with open(path, "rb") as fh:
                files = {"file": (os.path.basename(path), fh, ct)}
                response = await client.post(upload_url, files=files)
        if not response.is_success:
            raise HTTPException(status_code=response.status_code, detail=f"Temp.sh 上传失败：{response.text[:300]}")
        direct_url = response.text.strip().splitlines()[0].strip()
        if not re.match(r"^https?://", direct_url, re.I):
            raise HTTPException(status_code=502, detail=f"Temp.sh 返回了无法识别的链接：{response.text[:300]}")
        return {"url": direct_url, "source": source_url, "name": os.path.basename(path), "expires": "3 days", "service": "temp.sh"}
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"Temp.sh 上传异常：{exc}") from exc

async def upload_video_to_uguu(path: str, source_url: str) -> Dict[str, str]:
    """uguu.se：POST multipart（字段名 files[]）直接回纯文本直链，GET 拿到的就是文件字节。
    实测 mp3/mp4 都是 200 + 正确 Content-Type + 原始大小，约保留 3 小时。"""
    upload_url = os.getenv("UGUU_UPLOAD_URL", "https://uguu.se/upload.php?output=text").strip() or "https://uguu.se/upload.php?output=text"
    ct = content_type_for_path(path)
    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=httpx.Timeout(connect=20.0, read=600.0, write=600.0, pool=20.0), follow_redirects=True) as client:
            with open(path, "rb") as fh:
                files = {"files[]": (os.path.basename(path), fh, ct)}
                response = await client.post(upload_url, files=files)
        if not response.is_success:
            raise HTTPException(status_code=response.status_code, detail=f"uguu 上传失败：{response.text[:300]}")
        lines = response.text.strip().splitlines()
        direct_url = lines[0].strip() if lines else ""
        if not re.match(r"^https?://", direct_url, re.I):
            raise HTTPException(status_code=502, detail=f"uguu 返回了无法识别的链接：{response.text[:300]}")
        return {"url": direct_url, "source": source_url, "name": os.path.basename(path),
                "expires": os.getenv("UGUU_EXPIRES", "3h"), "service": "uguu"}
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"uguu 上传异常：{exc}") from exc

# 只读前几 KB 就够判断「这是文件还是 HTML 查看页」，不必把整个视频拉下来
CLOUD_MEDIA_VERIFY_READ_BYTES = int(os.getenv("CLOUD_MEDIA_VERIFY_READ_BYTES", str(16 * 1024)))

async def verify_cloud_media_direct_url(url: str) -> Dict[str, Any]:
    """真发一次 GET，确认这个链接能直接读到文件：状态 200、Content-Type 不含 text/html、实际字节 > 0。

    temp.sh 的链接 GET 只回 HTML 查看页（POST 才回文件字节），上游按 GET 下载必然失败，
    所以「上传成功」必须以此校验为准，通不过就换下一个通道。"""
    check: Dict[str, Any] = {"ok": False, "status": 0, "content_type": "", "bytes": 0, "reason": ""}
    if not str(url or "").strip():
        check["reason"] = "上传通道没有返回链接"
        return check
    head = b""
    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=httpx.Timeout(connect=20.0, read=120.0, write=60.0, pool=20.0), follow_redirects=True) as client:
            async with client.stream("GET", str(url)) as response:
                check["status"] = response.status_code
                check["content_type"] = str(response.headers.get("content-type") or "")
                if response.status_code == 200:
                    async for chunk in response.aiter_bytes():
                        if not chunk:
                            continue
                        head += chunk
                        if len(head) >= CLOUD_MEDIA_VERIFY_READ_BYTES:
                            break
    except Exception as exc:
        check["reason"] = f"GET 请求异常：{exc}"
        return check
    check["bytes"] = len(head)
    if check["status"] != 200:
        check["reason"] = f"GET 返回 HTTP {check['status']}"
    elif "text/html" in check["content_type"].lower():
        check["reason"] = f"GET 返回的是 HTML 查看页（Content-Type: {check['content_type'] or '空'}）"
    elif looks_like_html_response(head.decode("utf-8", "ignore")):
        check["reason"] = "GET 返回的正文是 HTML 页面"
    elif check["bytes"] <= 0:
        check["reason"] = "GET 读到 0 字节"
    else:
        check["ok"] = True
    return check

async def upload_cloud_media_verified(label: str, uploader, path: str, source_url: str) -> Dict[str, str]:
    """跑一个通道的上传，再对它给的链接做真实 GET 直读校验；不过关就抛错让上层换通道。"""
    uploaded = await uploader(path, source_url)
    check = await verify_cloud_media_direct_url(str(uploaded.get("url") or ""))
    print(f"云端上传 {label}：{uploaded.get('url')} → GET {check['status']} {check['content_type'] or '空'} {check['bytes']} 字节"
          + ("" if check["ok"] else f"，校验失败：{check['reason']}"))
    if not check["ok"]:
        raise HTTPException(status_code=502, detail=f"{label} 上传后 GET 直读校验失败：{check['reason']}（{uploaded.get('url')}）")
    return uploaded

async def upload_local_video_to_cloud(ref_url: str, service: str = "auto", path_override: str = "") -> Dict[str, str]:
    ref_url = str(ref_url or "").strip()
    if ref_url.startswith("http://") or ref_url.startswith("https://"):
        return {"url": ref_url, "source": ref_url, "service": "existing"}
    path = str(path_override or "").strip()
    if path:
        if not os.path.isfile(path):
            raise HTTPException(status_code=404, detail="本地媒体文件不存在或已被删除")
    else:
        path = local_media_path_for_cloud_upload(ref_url)
    service = str(service or "auto").strip().lower()
    if service in {"", "auto"}:
        service = str(os.getenv("CLOUD_MEDIA_UPLOAD_SERVICE") or os.getenv("CLOUD_VIDEO_UPLOAD_SERVICE") or "auto").strip().lower()
    if service in {"uguu", "uguu.se"}:
        return await upload_cloud_media_verified("uguu", upload_video_to_uguu, path, ref_url)
    if service in {"litterbox", "catbox"}:
        return await upload_cloud_media_verified("Litterbox", upload_video_to_litterbox, path, ref_url)
    if service in {"temp", "temp.sh", "tempsh"}:
        return await upload_cloud_media_verified("Temp.sh", upload_video_to_temp_sh, path, ref_url)
    channels = [("uguu", upload_video_to_uguu, "uguu")]
    if not content_type_for_path(path).startswith("audio/"):
        # 音频不放 Litterbox：实测它不收音频（412），别浪费一次必然失败的请求
        channels.append(("litterbox", upload_video_to_litterbox, "Litterbox"))
    channels.append(("temp.sh", upload_video_to_temp_sh, "Temp.sh"))
    errors = []
    for name, func, label in channels:
        try:
            return await upload_cloud_media_verified(label, func, path, ref_url)
        except HTTPException as exc:
            errors.append(f"{name}: {exc.detail}")
    raise HTTPException(status_code=502, detail="云端上传失败：" + "；".join(errors))

async def upload_local_video_to_temp_sh(ref_url: str) -> Dict[str, str]:
    return await upload_local_video_to_cloud(ref_url, "auto")

async def save_ai_image_to_output(image_data, prefix="online_", category="output"):
    # 上游直接把图片以 data URI 返回（中转站常见）时按 base64 落盘；否则 httpx.get(data:...)
    # 必然失败并被原样返回，任务结果里会塞进几百 KB 的 data URI，/assets/output/ 下没有文件。
    value = str(image_data.get("value") or "")
    if image_data.get("type") != "b64" and value.startswith("data:image/") and ";base64," in value:
        header, encoded = value.split(";base64,", 1)
        image_data = {"type": "b64", "value": encoded, "mime_type": header.replace("data:", "", 1) or "image/png"}
    filename = f"{prefix}{uuid.uuid4().hex[:10]}.png"
    path = output_path_for(filename, category)
    if image_data["type"] == "b64":
        extension = image_output_extension(str(image_data.get("mime_type") or ""))
        if extension != ".png":
            filename = filename[:-4] + extension
            path = output_path_for(filename, category)
        with open(path, "wb") as f:
            f.write(base64.b64decode(image_data["value"]))
        return output_url_for(filename, category)
    value = image_data["value"]
    if value.startswith("/output/") or value.startswith("/assets/"):
        return value
    value = rewrite_runninghub_file_url(value)
    try:
        timeout = httpx.Timeout(connect=20.0, read=300.0, write=60.0, pool=20.0)
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=timeout, follow_redirects=True) as client:
            response = await client.get(value)
            response.raise_for_status()
            content_type = response.headers.get("Content-Type", "")
            # Content-Type 缺失或 octet-stream 时按 URL 扩展名兜底，别把 svg/gif 存成 .png；
            # 两者都判不出时再看前 512 字节魔数（SVG/GIF 常常以 octet-stream 返回）。
            extension = image_output_extension(content_type, value)
            if extension == ".png":
                extension = image_output_extension_from_bytes(response.content[:512]) or extension
            if extension != ".png":
                filename = filename[:-4] + extension
                path = output_path_for(filename, category)
            with open(path, "wb") as f:
                f.write(response.content)
            return output_url_for(filename, category)
    except Exception as e:
        print(f"保存上游图片失败: {e}; url={value}")
        return value

# --- 能力运行时的生图执行器（复用 NOVAI 既有生图链路） ---
# server/agents/tools.py 的 image_generate 工具与 OpenClaw 能力运行的生图阶段都通过
# deps 注入调用它；provider/model 一律来自 data/api_providers.json，不写死模型。

_AGENT_IMAGE_REF_EXTS = {".png", ".jpg", ".jpeg", ".webp", ".gif", ".bmp"}


def _agent_image_reference_url(raw):
    """把上传图片 / 本地路径转成生图链路能识别的 URL；不合法返回空串。"""
    text = str(raw or "").strip()
    if not text:
        return ""
    low = text.lower()
    if low.startswith(("http://", "https://", "data:")):
        return text
    if text.startswith(("/output/", "/assets/")) and output_file_from_url(text):
        return text
    path = text if os.path.isabs(text) else os.path.abspath(text)
    if not os.path.isfile(path):
        return ""
    ext = os.path.splitext(path)[1].lower()
    if ext not in _AGENT_IMAGE_REF_EXTS:
        return ""
    name = "agentref_%s%s" % (uuid.uuid4().hex[:10], ext)
    target = output_path_for(name, "input")
    os.makedirs(os.path.dirname(target), exist_ok=True)
    shutil.copyfile(path, target)
    return output_url_for(name, "input")


_AGENT_IMAGE_DOWNLOAD_READ_TIMEOUT = 300.0


def _agent_exc_reason(exc):
    """异常文案：总是「类型名: 非空原因」，str 为空退到 repr。"""
    reason = str(exc).strip()
    if not reason:
        reason = repr(exc).strip()
    if not reason:
        reason = "(无异常信息)"
    return "%s: %s" % (type(exc).__name__, reason)


def _agent_url_digest(url, limit=200):
    """失败源 URL 摘要：只留 scheme://host/path，query 一律丢弃（可能含 api key/token/签名）。"""
    try:
        parsed = urllib.parse.urlparse(str(url or ""))
        host = parsed.hostname or ""
        if parsed.port:
            host = "%s:%d" % (host, parsed.port)
        summary = "%s://%s%s" % (parsed.scheme or "?", host, parsed.path or "")
    except Exception:
        summary = ""
    if not summary or summary.endswith("://"):
        summary = "(无 URL)"
    return summary[:limit]


async def _write_generated_image(image_data, path):
    """把上游返回的图片（b64 / 本地受控 URL / http(s) URL）落盘；失败明确抛错。"""
    if not isinstance(image_data, dict):
        raise _AgentFileToolError("生图上游返回了无法识别的结果（不是图片数据）",
                                  code="image_empty", status_code=502)
    kind = str(image_data.get("type") or "")
    os.makedirs(os.path.dirname(path), exist_ok=True)
    if kind == "b64":
        with open(path, "wb") as handle:
            handle.write(base64.b64decode(image_data.get("value") or ""))
        return
    url = str(image_data.get("value") or "")
    if url.startswith(("/output/", "/assets/")):
        source = output_file_from_url(url)
        if not source:
            raise _AgentFileToolError("生图结果文件不存在：%s" % url, code="image_empty", status_code=502)
        shutil.copyfile(source, path)
        return
    if url.startswith(("http://", "https://")):
        url_digest = _agent_url_digest(url)
        read_timeout = _AGENT_IMAGE_DOWNLOAD_READ_TIMEOUT
        timeout = httpx.Timeout(connect=20.0, read=read_timeout, write=60.0, pool=20.0)
        last_exc = None
        for attempt in (1, 2):
            try:
                async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV,
                                             timeout=timeout, follow_redirects=True) as client:
                    response = await client.get(url)
                    response.raise_for_status()
                    with open(path, "wb") as handle:
                        handle.write(response.content)
                return
            except httpx.HTTPStatusError as exc:
                raise _AgentFileToolError(
                    "下载生图结果失败（image_download_failed，HTTP %s）：%s | 来源=%s"
                    % (exc.response.status_code, _agent_exc_reason(exc), url_digest),
                    code="image_download_failed", status_code=502)
            except (httpx.TimeoutException, httpx.TransportError) as exc:
                last_exc = exc
            except OSError as exc:
                raise _AgentFileToolError(
                    "保存下载的生图结果失败（image_save_failed）：%s | 来源=%s"
                    % (_agent_exc_reason(exc), url_digest),
                    code="image_save_failed", status_code=502)
            if attempt == 1:
                log_net_error("能力生图 下载失败将重试 来源=%s" % url_digest, last_exc, url=url_digest)
        if isinstance(last_exc, httpx.ReadTimeout):
            raise _AgentFileToolError(
                "下载生图结果读超时（image_download_timeout，read 超时 %s 秒，已重试 1 次）：%s | 来源=%s"
                % (read_timeout, _agent_exc_reason(last_exc), url_digest),
                code="image_download_timeout", status_code=502)
        raise _AgentFileToolError(
            "下载生图结果失败（image_download_failed，已重试 1 次）：%s | 来源=%s"
            % (_agent_exc_reason(last_exc), url_digest),
            code="image_download_failed", status_code=502)
    raise _AgentFileToolError("生图上游返回了空的/非 URL 结果：%s" % (url[:200] or kind or "未知"),
                              code="image_empty", status_code=502)


async def capability_generate_image(spec):
    """能力运行时生图：复用 generate_ai_image，产物落 run 产物目录并登记为受控产物。

    spec: {prompt, size?, quality?, model?, provider?, reference_images?, count?, run_id, output_dir?, name_prefix?}
    失败一律抛 _AgentFileToolError（未配置生图模型 / 上游失败 / 落盘失败），不静默降级。
    """
    from server.agents import store as agent_store

    spec = spec if isinstance(spec, dict) else {}
    prompt = str(spec.get("prompt") or "").strip()
    if not prompt:
        raise _AgentFileToolError("生图提示词不能为空", code="invalid_args")
    run_id = str(spec.get("run_id") or "")
    output_dir = str(spec.get("output_dir") or "") or agent_store.run_output_dir(run_id)
    os.makedirs(output_dir, exist_ok=True)

    # 缺省生图平台/模型也可以用环境变量兜底（NOVAI_AGENT_IMAGE_PROVIDER / _MODEL），
    # 仍然不写死模型；没配就回到按 provider 声明的 image_models 自动解析。
    spec_provider = str(spec.get("provider") or "").strip()
    spec_model = str(spec.get("model") or "").strip()
    env_provider = str(os.environ.get("NOVAI_AGENT_IMAGE_PROVIDER") or "").strip()
    env_model = str(os.environ.get("NOVAI_AGENT_IMAGE_MODEL") or "").strip()
    provider_arg = spec_provider or env_provider
    model_arg = spec_model or env_model
    if spec_provider or spec_model:
        origin = "能力参数指定"
    elif env_provider or env_model:
        origin = "环境变量 %s/%s 指定" % (env_provider and "NOVAI_AGENT_IMAGE_PROVIDER" or "-",
                                        env_model and "NOVAI_AGENT_IMAGE_MODEL" or "-")
    else:
        origin = "自动（能力参数与环境变量都没指定）"
    trace = {"origin": origin}
    provider_id, model_id, model_note = _agent_resolve_media_target(
        {"provider": provider_arg, "image_provider": provider_arg, "model": model_arg},
        "image_models", _agent_pick_image_provider, trace)
    # 可验证信息：最终平台/模型 + 为什么选它 + 跳过了谁及原因（进 note、日志和失败文案）
    selection_note = _agent_media_selection_note(provider_id, model_id, trace, model_note)
    print("[Agent] 能力生图选定：%s" % selection_note, flush=True)
    if not model_id:
        raise _AgentFileToolError(
            "未配置生图模型：请在「设置 → API 设置」里为生图平台「%s」填写生图模型"
            "（image_model 单数，或 image_models 清单）后再生图。%s"
            % (provider_id or "无", selection_note),
            code="image_model_missing", status_code=400)
    provider = get_api_provider(provider_id)
    if not provider or provider.get("enabled") is False:
        raise _AgentFileToolError("生图平台不可用：%s；%s" % (provider_id or "未配置", selection_note),
                                  code="image_provider_missing", status_code=400)

    size = agent_image_size(provider_id, model_id, str(spec.get("size") or ""),
                            str(spec.get("ratio") or "")) or "1024x1024"
    quality = str(spec.get("quality") or "").strip() or "auto"
    refs = []
    for raw in (spec.get("reference_images") or []):
        url = _agent_image_reference_url(raw)
        if url:
            refs.append({"url": url, "kind": "image"})
    try:
        count = int(spec.get("count") or 1)
    except (TypeError, ValueError):
        count = 1
    count = max(1, min(count, 4))
    # 单次运行生图总预算（真实计费的安全阀）：NOVAI_AGENT_IMAGE_MAX，默认 4 张/次运行
    try:
        budget = max(0, int(os.environ.get("NOVAI_AGENT_IMAGE_MAX") or 4))
    except (TypeError, ValueError):
        budget = 4
    if run_id and budget >= 0:
        existing = 0
        record = agent_store.load_run(run_id) or {}
        for item in record.get("artifacts") or []:
            if isinstance(item, dict) and str(item.get("kind") or "") == "image":
                existing += 1
        remaining = budget - existing
        if remaining <= 0:
            raise _AgentFileToolError(
                "本次运行生图已达上限 %d 张（NOVAI_AGENT_IMAGE_MAX）：不再继续调用上游生图为避免重复计费。"
                % budget,
                code="image_budget_exhausted", status_code=429)
        count = min(count, remaining)
    prefix = agent_store.safe_filename(str(spec.get("name_prefix") or "生成图")) or "生成图"

    images = []
    for index in range(count):
        try:
            image_data, _raw = await generate_ai_image(prompt, size, quality, model_id, refs, provider_id)
        except HTTPException as exc:
            detail = exc.detail if isinstance(exc.detail, str) else str(exc.detail)
            raise _AgentFileToolError("生图失败（%s）：%s" % (selection_note, detail),
                                      code="image_upstream_failed", status_code=exc.status_code or 502)
        except httpx.HTTPStatusError as exc:
            body = exc.response.text or ""
            detail = friendly_image_error_detail(body, size, model_id) or ("上游生图接口错误：" + body[:300])
            raise _AgentFileToolError("生图失败（%s）：%s" % (selection_note, detail),
                                      code="image_upstream_failed", status_code=exc.response.status_code)
        except httpx.HTTPError as exc:
            log_net_error("能力生图 网络/TLS错误 model=%s" % model_id, exc)
            raise _AgentFileToolError("生图网络错误（%s）：%s" % (selection_note, exc),
                                      code="image_upstream_failed", status_code=502)
        name = agent_store.safe_filename("%s_%d.png" % (prefix, index + 1))
        path = os.path.join(output_dir, name)
        try:
            await _write_generated_image(image_data, path)
        except _AgentFileToolError:
            raise
        except Exception as exc:
            raise _AgentFileToolError("保存生成的图片失败：%s" % _agent_exc_reason(exc),
                                      code="image_save_failed", status_code=502)
        item = agent_store.add_artifact(run_id, "image", name, path)
        images.append({"name": name, "url": item.get("url"), "bytes": os.path.getsize(path)})

    return {"provider": provider_id, "model": model_id, "size": size, "count": len(images),
            "images": images, "model_note": selection_note, "references": len(refs)}


async def _capability_generate_image_charged(spec):
    """能力运行时生图的扣费包装：Agent 走服务端直接生图，不经过 /api/online-image，必须单独计费。"""
    spec = spec if isinstance(spec, dict) else {}
    provider = member_provider(spec.get("provider") or spec.get("image_provider") or "")
    if provider:
        spec = {**spec, "provider": provider}
    model = str(spec.get("model") or spec.get("image_model") or "")
    size = str(spec.get("size") or "")
    width, height = parse_size_pair(size)
    try:
        count = int(spec.get("count") or 1)
    except (TypeError, ValueError):
        count = 1
    params = {"width": width, "height": height, "quality": str(spec.get("quality") or ""),
              "size": size, "rows": max(1, count)}
    charge = credits_charge_start("image", model, params, provider=provider)
    try:
        result = await capability_generate_image(spec)
    except Exception:
        credits_charge_refund(charge, "agent_image_failed")
        raise
    credits_charge_settle(charge, result=result)
    return result


def image_output_meta(url, source_item=None):
    meta = {"url": url, "kind": "image"}
    if not url:
        return meta
    parsed_name = os.path.basename(urllib.parse.urlparse(str(url)).path)
    if parsed_name:
        meta["name"] = parsed_name
    if isinstance(source_item, dict):
        for key in ("natural_w", "natural_h", "width", "height", "w", "h", "layout_w", "layout_h"):
            try:
                value = int(float(source_item.get(key) or 0))
            except (TypeError, ValueError):
                value = 0
            if value > 0:
                meta[key] = value
    path = output_file_from_url(url)
    if path and os.path.exists(path):
        try:
            with Image.open(path) as img:
                width, height = img.size
            if width > 0 and height > 0:
                meta.update({
                    "natural_w": width,
                    "natural_h": height,
                    "width": width,
                    "height": height,
                })
        except Exception:
            pass
    return meta

async def save_remote_video_to_output(url, prefix="video_", category="output"):
    if not url:
        return ""
    if url.startswith("/output/") or url.startswith("/assets/"):
        return url
    video_exts = {".mp4", ".webm", ".mov", ".m4v", ".avi", ".mkv", ".flv"}
    parsed = urllib.parse.urlparse(str(url or "").strip())
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        return url
    clean_ext = os.path.splitext(parsed.path)[1].lower()
    stem = f"{prefix}{uuid.uuid4().hex[:10]}"
    filename = f"{stem}{clean_ext if clean_ext in video_exts else '.mp4'}"
    path = output_path_for(filename, category)
    try:
        timeout = httpx.Timeout(connect=20.0, read=VIDEO_POLL_TIMEOUT, write=60.0, pool=20.0)
        headers = {
            "User-Agent": "ComfyUI-API-Modelscope/1.0",
            "Accept": "video/*,application/octet-stream,*/*;q=0.8",
        }
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=timeout, follow_redirects=True, headers=headers) as client:
            response = await client.get(url)
            response.raise_for_status()
            content_type = (response.headers.get("Content-Type") or "").lower()
            if "text/html" in content_type or "application/json" in content_type:
                raise RuntimeError(f"unexpected video content type: {content_type}")
            ext = clean_ext
            if ext in video_exts:
                filename = f"{stem}{ext}"
                path = output_path_for(filename, category)
            elif "webm" in content_type:
                filename = f"{stem}.webm"
                path = output_path_for(filename, category)
            elif "quicktime" in content_type or "mov" in content_type:
                filename = f"{stem}.mov"
                path = output_path_for(filename, category)
            elif "x-matroska" in content_type or "mkv" in content_type:
                filename = f"{stem}.mkv"
                path = output_path_for(filename, category)
            elif "x-flv" in content_type or "flv" in content_type:
                filename = f"{stem}.flv"
                path = output_path_for(filename, category)
            with open(path, "wb") as f:
                f.write(response.content)
            if os.path.getsize(path) <= 0:
                raise RuntimeError("empty video response")
            return output_url_for(filename, category)
    except Exception as e:
        print(f"保存上游视频失败: {e}")
        try:
            if os.path.exists(path):
                os.remove(path)
        except Exception:
            pass
        return url

def parse_size_pair(size):
    match = re.fullmatch(r"\s*(\d+)\s*[xX*]\s*(\d+)\s*", str(size or ""))
    if not match:
        return 0, 0
    return int(match.group(1)), int(match.group(2))

# 对话页 / Agent 生图比例表：7 个常用比例 × 1k/2k/4k，像素取官方 APIMart gpt-image-2
# size×resolution 映射表的第一组（/tmp/novai-official-docs/text/apimart_gpt_image_2_generation_md.txt:380-422）。
CHAT_RATIO_SIZE_OPTIONS = {
    "1:1": ("1024x1024", "2048x2048", "2880x2880"),
    "2:3": ("1024x1536", "1360x2048", "2336x3520"),
    "3:2": ("1536x1024", "2048x1360", "3520x2336"),
    "3:4": ("768x1024", "1536x2048", "2480x3312"),
    "4:3": ("1024x768", "2048x1536", "3312x2480"),
    "9:16": ("864x1536", "1152x2048", "2160x3840"),
    "16:9": ("1536x864", "2048x1152", "3840x2160"),
}

def chat_prompt_size_override(message, current_size=""):
    text = str(message or "")
    direct = re.search(r"(?<!\d)([1-9]\d{2,4})\s*[xX×*]\s*([1-9]\d{2,4})(?!\d)", text)
    if direct:
        width, height = int(direct.group(1)), int(direct.group(2))
        if width >= 256 and height >= 256:
            return f"{width}x{height}"

    normalized = (
        text.replace("：", ":")
        .replace("﹕", ":")
        .replace("∶", ":")
        .replace("比", ":")
        .replace("／", "/")
        .replace("/", ":")
    )
    ratio_match = re.search(r"(?<!\d)(1|2|3|4|9|16)\s*:\s*(1|2|3|4|9|16)(?!\d)", normalized)
    if not ratio_match:
        return ""
    ratio = f"{int(ratio_match.group(1))}:{int(ratio_match.group(2))}"
    options = CHAT_RATIO_SIZE_OPTIONS.get(ratio)
    if not options:
        return ""
    width, height = parse_size_pair(current_size)
    wants_4k = bool(re.search(r"(?i)\b4\s*k\b|4K|超清|超高分辨率", text))
    wants_2k = bool(re.search(r"(?i)\b2\s*k\b|2K|高清|高分辨率", text))
    long_edge = max(width, height)
    if wants_4k or long_edge >= 2400:
        return options[2] if len(options) > 2 else options[-1]
    if wants_2k or long_edge >= 1500:
        return options[1] if len(options) > 1 else options[0]
    return options[0]

# GPT-Image-2 限制：长边最大 3840，主要受最大像素限制（约 829 万 = 3840x2160）。
# 这里只用于上游报错后给出友好的像素上限提示；不对尺寸做任何缩小（用户选什么就原样发送）。
GPT_IMAGE2_MAX_EDGE = 3840
GPT_IMAGE2_MAX_PIXELS = 8_294_400
GPT_IMAGE2_MIN_PIXELS = 655_360

def is_gpt_image_2_model(model):
    raw = str(model or "").strip().lower()
    normalized = re.sub(r"[^a-z0-9]+", "-", raw).strip("-")
    compact = re.sub(r"[^a-z0-9]+", "", raw)
    return (
        normalized == "gpt-image-2"
        or normalized.startswith("gpt-image-2-")
        or normalized.endswith("-gpt-image-2")
        or "-gpt-image-2-" in normalized
        or compact == "gptimage2"
        or compact.startswith("gptimage2")
        or compact.endswith("gptimage2")
    )

def image_model_rejects_response_format(model):
    """新版官方图像模型（gpt-image-1 / 1.5 / 1-mini 及日期快照）已移除顶层 response_format，
    中转到这些上游会直接报 unknown_parameter: 'response_format'。
    gpt-image-2 的中转普遍仍接受该参数，所以只对 1.x 系列前置去掉，避免影响已经跑通的通道。"""
    name = re.sub(r"[^a-z0-9]+", "-", str(model or "").strip().lower()).strip("-")
    return name == "gpt-image-1" or name.startswith("gpt-image-1-")

# 背景档位：auto=现状；keep/transparent 在原生不支持时只能靠提示词表达。
IMAGE_BACKGROUND_VALUES = {"auto", "keep", "transparent"}

def is_gpt_image_background_model(model):
    """gpt-image 全系（1 / 1.5 / 2 及其日期快照、中转前缀）原生支持 background:"transparent"；
    归一写法与 is_gpt_image_2_model 保持一致。"""
    raw = str(model or "").strip().lower()
    normalized = re.sub(r"[^a-z0-9]+", "-", raw).strip("-")
    compact = re.sub(r"[^a-z0-9]+", "", raw)
    return (
        normalized == "gpt-image"
        or normalized.startswith("gpt-image-")
        or normalized.endswith("-gpt-image")
        or "-gpt-image-" in normalized
        or compact == "gptimage"
        or compact.startswith("gptimage")
    )

def image_supports_native_transparent_background(provider, model):
    """只有当前协议与模型都支持原生 background 参数时才直接下发，其他情况退回提示词。"""
    # 原生透明确认口径不一样：APIMart 以能力表的 native_background 为准（seedream-5-5 这类非 gpt-image
    # 模型也支持，不能再按模型名拦），其他平台沿用 gpt-image 模型名 + openai 请求模式的旧判断。
    if is_apimart_provider(provider):
        return bool(apimart_image_caps_for(provider, model).get("native_background"))
    if not is_gpt_image_background_model(model):
        return False
    # ModelScope 虽声明 openai 协议，但走自己的生图实现（与 generate_ai_image 的分派保持一致）
    if str(provider.get("id") or "").strip().lower() == "modelscope":
        return False
    if effective_protocol(provider, model) != "openai":
        return False
    return effective_image_request_mode(provider, model) == "openai"

def normalize_image_background(background):
    """只认 auto/keep/transparent；老存档、空值和乱值一律按 auto，保证与既有行为完全一致。"""
    value = str(background or "").strip().lower()
    return value if value in IMAGE_BACKGROUND_VALUES else "auto"

# 保留背景在上游没有对应参数（Lovart 这类平台也是用 prompt 传要求，见 lovart_prompt_with_requirements）。
IMAGE_BACKGROUND_INSTRUCTIONS = {
    "keep": "保持参考图中的背景、场景与光线不变，只修改主体。",
    "transparent": "输出透明背景图片：只保留主体，背景必须完全透明（带 alpha 通道的 PNG），不要绘制任何背景、底色、阴影或棋盘格。",
}

def image_background_prompt(prompt, background):
    instruction = IMAGE_BACKGROUND_INSTRUCTIONS.get(background)
    if not instruction:
        return prompt
    return f"{instruction}\n\n{prompt}"

def openai_image_request_body(model, prompt, size, quality="", extra=None):
    """OpenAI 兼容 /images/generations 请求体（response_format 按模型能力决定是否携带）。"""
    body = {"model": model, "prompt": prompt, "size": size, "n": 1}
    if not image_model_rejects_response_format(model):
        body["response_format"] = "url"
    if quality:
        body["quality"] = quality
    if extra:
        body.update(extra)
    return body

def response_mentions_response_format(response):
    try:
        return "response_format" in (response.text or "").lower()
    except Exception:
        return False

def response_mentions_background(response):
    try:
        return "background" in (response.text or "").lower()
    except Exception:
        return False

async def post_openai_image_request(client, url, headers, body):
    """生图 POST；若上游明确拒绝 response_format（unknown_parameter），去掉该参数重试一次。
    这样已知的官方 1.x 通道不用白跑一次失败请求，未知中转也能自动兼容。"""
    response = await client.post(url, headers=headers, json=body)
    if response.status_code >= 400 and "response_format" in body and response_mentions_response_format(response):
        retry_body = {k: v for k, v in body.items() if k != "response_format"}
        print("[image] 上游不接受 response_format，去掉后重试一次")
        response = await client.post(url, headers=headers, json=retry_body)
    # 透明背景同理：只在响应里明确提到 background 时降级重试，避免不支持该参数的中转直接失败。
    if response.status_code >= 400 and "background" in body and response_mentions_background(response):
        retry_body = {k: v for k, v in body.items() if k != "background"}
        print("[image] 上游不接受 background，去掉后重试一次")
        response = await client.post(url, headers=headers, json=retry_body)
    return response

def normalize_gpt_image_2_size(size):
    width, height = parse_size_pair(size)
    if not width or not height:
        return size or "auto"
    # 官方口径：两边都要能被 16 整除、比例落在 1:3~3:1；超限再等比缩到 3840x2160 / 829 万像素内。
    ratio = width / height
    if ratio > 3:
        width = height * 3
    elif ratio < 1 / 3:
        height = width * 3
    scale = min(
        1.0,
        GPT_IMAGE2_MAX_EDGE / max(width, height),
        (GPT_IMAGE2_MAX_PIXELS / max(1, width * height)) ** 0.5,
    )
    width = max(16, int((width * scale) // 16) * 16)
    height = max(16, int((height * scale) // 16) * 16)
    # 16 对齐会把两边削得不一致，比例可能又越界，按 16 的倍数严格夹回官方范围。
    if width > height * 3:
        width = max(16, int((height * 3) // 16) * 16)
    if width * 3 < height:
        height = max(16, int((width * 3) // 16) * 16)
    if width * height < GPT_IMAGE2_MIN_PIXELS:
        grow = (GPT_IMAGE2_MIN_PIXELS / max(1, width * height)) ** 0.5
        width = int((width * grow + 15) // 16) * 16
        height = int((height * grow + 15) // 16) * 16
    return f"{width}x{height}"

def gpt_image_2_size_error_message(size):
    width, height = parse_size_pair(size)
    display_size = size or "未指定"
    return (
        f"GPT-Image-2 不支持当前尺寸 {display_size}：它有最大像素限制"
        "（长边最大 3840、总像素约 829 万）。请改用更小的尺寸，"
        "或切换到 nano-banana 生成更高分辨率。"
    )

def gpt_image_2_size_exceeds_supported(size):
    width, height = parse_size_pair(size)
    return bool(width and height and (max(width, height) > GPT_IMAGE2_MAX_EDGE or width * height > GPT_IMAGE2_MAX_PIXELS))

# GIF 输出（APIMart gpt-image-2.6 家族）的上游规则：size 是「每帧」像素，frame_count 默认 9，
# 各帧拼成整版提交，整版必须 ≤3840 单边、≤829 万像素、比例 ≤3:1，否则提交即 400 invalid_size。
GIF_FRAME_COUNT_MIN = 2
GIF_FRAME_COUNT_MAX = 16
GIF_FRAME_COUNT_DEFAULT = 9
GIF_FRAME_DURATION_DEFAULT = 200
GIF_FRAME_DURATION_MIN = 20
GIF_FRAME_EDGE_STEP = 16
GIF_FRAME_MIN_EDGE = 64

def gif_frame_layout(frame_count, frame_ratio=1.0):
    """帧拼版行列：2–8 帧 4x2、9 帧 3x3、10–12 帧 4x3、13–16 帧 4x4。
    行列可互换，两种朝向都试，取整版四约束下每帧允许面积更大的那种。"""
    try:
        count = int(frame_count or 0)
    except (TypeError, ValueError):
        count = 0
    count = max(GIF_FRAME_COUNT_MIN, min(count, GIF_FRAME_COUNT_MAX))
    if count <= 8:
        base = (4, 2)
    elif count == 9:
        base = (3, 3)
    elif count <= 12:
        base = (4, 3)
    else:
        base = (4, 4)
    ratio = float(frame_ratio or 1.0)
    return max((base, (base[1], base[0])),
               key=lambda pair: _gif_frame_area(pair[0], pair[1], ratio))

def _gif_frame_area(cols, rows, frame_ratio):
    """该朝向在整版约束下允许的每帧最大面积（连续值）；比例装不进整版时为 0。"""
    if cols <= 0 or rows <= 0 or frame_ratio <= 0:
        return 0.0
    sheet_ratio = (cols / float(rows)) * frame_ratio
    if sheet_ratio > 3 or sheet_ratio < 1 / 3.0:
        return 0.0
    width = min(
        GPT_IMAGE2_MAX_EDGE / float(cols),
        GPT_IMAGE2_MAX_EDGE / float(rows) * frame_ratio,
        math.sqrt(GPT_IMAGE2_MAX_PIXELS / float(cols * rows) * frame_ratio),
    )
    return width * width / frame_ratio

def max_gif_frame_size(width, height, frame_count):
    """整版四约束下每帧能取到的最大像素：保持宽高比，两边 16 的倍数、不小于 64。"""
    width = max(1, int(width or 0))
    height = max(1, int(height or 0))
    ratio = width / float(height)
    cols, rows = gif_frame_layout(frame_count, ratio)
    if _gif_frame_area(cols, rows, ratio) <= 0:
        # 比例超出该拼版能装下的区间：先夹到 3:1~1:3（3x3/4x4 的硬边界）再算
        ratio = min(3.0, max(1 / 3.0, ratio))
        cols, rows = gif_frame_layout(frame_count, ratio)
    height_limit = max(GIF_FRAME_MIN_EDGE,
                       (GPT_IMAGE2_MAX_EDGE // rows) // GIF_FRAME_EDGE_STEP * GIF_FRAME_EDGE_STEP)
    width_limit = max(GIF_FRAME_MIN_EDGE, min(
        GPT_IMAGE2_MAX_EDGE / float(cols),
        GPT_IMAGE2_MAX_EDGE / float(rows) * ratio,
        math.sqrt(GPT_IMAGE2_MAX_PIXELS / float(cols * rows) * ratio),
    ))
    start = int(width_limit / GIF_FRAME_EDGE_STEP + 0.5) * GIF_FRAME_EDGE_STEP
    for strict in (True, False):
        for step in range(0, 512):
            frame_width = start - step * GIF_FRAME_EDGE_STEP
            if frame_width < GIF_FRAME_MIN_EDGE:
                break
            frame_height = max(GIF_FRAME_MIN_EDGE, min(
                int(round(frame_width / ratio / GIF_FRAME_EDGE_STEP)) * GIF_FRAME_EDGE_STEP,
                height_limit))
            if cols * frame_width > GPT_IMAGE2_MAX_EDGE or rows * frame_height > GPT_IMAGE2_MAX_EDGE:
                continue
            if cols * rows * frame_width * frame_height > GPT_IMAGE2_MAX_PIXELS:
                continue
            sheet_ratio = (cols * frame_width) / float(rows * frame_height)
            if sheet_ratio > 3 or sheet_ratio < 1 / 3.0:
                continue
            if strict and abs((frame_width / float(frame_height)) / ratio - 1) > 0.009:
                continue
            return frame_width, frame_height
    return (max(GIF_FRAME_MIN_EDGE, width_limit // GIF_FRAME_EDGE_STEP * GIF_FRAME_EDGE_STEP),
            max(GIF_FRAME_MIN_EDGE, height_limit // GIF_FRAME_EDGE_STEP * GIF_FRAME_EDGE_STEP))

def gif_ratio_frame_pixels(ratio):
    """比例名 -> 参考每帧像素：先走对话页比例表，表外按整数比 ×128 展开。"""
    options = CHAT_RATIO_SIZE_OPTIONS.get(str(ratio or "").strip().lower())
    if options:
        return options[0]
    match = re.fullmatch(r"\s*(\d+)\s*[:x]\s*(\d+)\s*", str(ratio or "").strip().lower())
    if not match:
        return ""
    left, right = int(match.group(1)), int(match.group(2))
    if left <= 0 or right <= 0:
        return ""
    return f"{left * 128}x{right * 128}"

def normalize_gif_frame_size(size, frame_count=GIF_FRAME_COUNT_DEFAULT):
    """GIF 每帧尺寸：空/auto -> 512x512；比例名先换算成像素；再按整版上限收敛（已合法就原样保留）。"""
    raw = str(size or "").strip().lower()
    if not raw or raw == "auto":
        return "512x512"
    width, height = parse_size_pair(size)
    if not width or not height:
        width, height = parse_size_pair(gif_ratio_frame_pixels(raw))
        if not width or not height:
            return "512x512"
    width = max(GIF_FRAME_MIN_EDGE, width // GIF_FRAME_EDGE_STEP * GIF_FRAME_EDGE_STEP)
    height = max(GIF_FRAME_MIN_EDGE, height // GIF_FRAME_EDGE_STEP * GIF_FRAME_EDGE_STEP)
    max_width, max_height = max_gif_frame_size(width, height, frame_count)
    if width <= max_width and height <= max_height:
        return f"{width}x{height}"
    return f"{max_width}x{max_height}"

def gif_frame_count(value, caps_gif=None):
    """帧数夹在能力表范围（默认 2–16）；未指定走默认（默认 9 帧）。"""
    caps_gif = caps_gif if isinstance(caps_gif, dict) else {}
    try:
        count = int(value or 0)
    except (TypeError, ValueError):
        count = 0
    if not count:
        count = int(caps_gif.get("default") or GIF_FRAME_COUNT_DEFAULT)
    low = int(caps_gif.get("min") or GIF_FRAME_COUNT_MIN)
    high = int(caps_gif.get("max") or GIF_FRAME_COUNT_MAX)
    return max(low, min(count, high))

def gif_frame_duration(value, caps_gif=None):
    """帧间隔毫秒：未指定走默认 200；最小 20，按 10ms 取整。"""
    caps_gif = caps_gif if isinstance(caps_gif, dict) else {}
    try:
        duration = int(value or 0)
    except (TypeError, ValueError):
        duration = 0
    if not duration:
        duration = int(caps_gif.get("durationDefault") or GIF_FRAME_DURATION_DEFAULT)
    duration = int(duration / 10.0 + 0.5) * 10
    return max(GIF_FRAME_DURATION_MIN, duration)

# APIMart 官方「size × resolution → 实际像素」映射表（docs.apimart.ai gpt-image-2 generation）。
# 档位是独立参数，不能按长边/像素阈值反推：官方表里的像素一律还原成官方档位，表外像素才退回旧口径。
APIMART_ASPECT_RATIOS = [
    (1, 1, "1:1"), (3, 2, "3:2"), (2, 3, "2:3"), (4, 3, "4:3"), (3, 4, "3:4"),
    (5, 4, "5:4"), (4, 5, "4:5"), (16, 9, "16:9"), (9, 16, "9:16"),
    (2, 1, "2:1"), (1, 2, "1:2"), (3, 1, "3:1"), (1, 3, "1:3"),
    (21, 9, "21:9"), (9, 21, "9:21"), (7, 5, "7:5"), (5, 7, "5:7"),
    (9, 19.5, "9:19.5"), (19.5, 9, "19.5:9"), (9, 20, "9:20"), (20, 9, "20:9"),
]
# 同一比例同一档位官方可能给两组等价像素（如 1:1 的 1k = 1024² 或 1254²），全部收录才能精确命中。
APIMART_OFFICIAL_PIXELS = {
    "1:1": {"1k": ((1024, 1024), (1254, 1254)), "2k": ((2048, 2048),), "4k": ((2880, 2880),)},
    "3:2": {"1k": ((1536, 1024),), "2k": ((2048, 1360),), "4k": ((3520, 2336),)},
    "2:3": {"1k": ((1024, 1536),), "2k": ((1360, 2048),), "4k": ((2336, 3520),)},
    "4:3": {"1k": ((1024, 768),), "2k": ((2048, 1536),), "4k": ((3312, 2480),)},
    "3:4": {"1k": ((768, 1024),), "2k": ((1536, 2048),), "4k": ((2480, 3312),)},
    "5:4": {"1k": ((1280, 1024), (1448, 1086)), "2k": ((2560, 2048),), "4k": ((3216, 2576),)},
    "4:5": {"1k": ((1024, 1280), (1122, 1402)), "2k": ((2048, 2560),), "4k": ((2576, 3216),)},
    "16:9": {"1k": ((1536, 864), (1672, 941)), "2k": ((2048, 1152),), "4k": ((3840, 2160),)},
    "9:16": {"1k": ((864, 1536), (941, 1672)), "2k": ((1152, 2048),), "4k": ((2160, 3840),)},
    "2:1": {"1k": ((2048, 1024), (1774, 887)), "2k": ((2688, 1344),), "4k": ((3840, 1920),)},
    "1:2": {"1k": ((1024, 2048), (887, 1774)), "2k": ((1344, 2688),), "4k": ((1920, 3840),)},
    "3:1": {"1k": ((1881, 836), (1536, 512)), "2k": ((3072, 1024),), "4k": ((3840, 1280),)},
    "1:3": {"1k": ((887, 1774), (512, 1536)), "2k": ((1024, 3072),), "4k": ((1280, 3840),)},
    "21:9": {"1k": ((2016, 864), (1915, 821)), "2k": ((2688, 1152),), "4k": ((3840, 1648),)},
    "9:21": {"1k": ((864, 2016), (821, 1915)), "2k": ((1152, 2688),), "4k": ((1648, 3840),)},
}
APIMART_RESOLUTION_LEVELS = ("1k", "2k", "4k")

def apimart_closest_aspect_ratio(width, height):
    ratio = width / height
    return min(APIMART_ASPECT_RATIOS, key=lambda item: abs(ratio - item[0] / item[1]))[2]

def apimart_resolution_from_long_edge(width, height):
    """旧口径的长边 / 总像素阈值；只作为官方映射表之外的兜底。"""
    long_edge = max(width, height)
    pixels = width * height
    if long_edge >= 3000 or pixels > 4_500_000:
        return "4k"
    if long_edge >= 1800 or pixels > 1_800_000:
        return "2k"
    return "1k"

def apimart_official_size_cell(width, height):
    """命中官方映射表返回 (比例, 档位)，否则 None。"""
    for ratio, tiers in APIMART_OFFICIAL_PIXELS.items():
        for level in APIMART_RESOLUTION_LEVELS:
            if (width, height) in tiers.get(level, ()):
                return ratio, level
    return None

def apimart_legacy_size_resolution(size):
    """APIMart 旧口径（Gemini 直连链路继续沿用，本次修正不动它的档位映射）。"""
    width, height = parse_size_pair(size)
    if not width or not height:
        raw = str(size or "").strip().lower()
        if raw in {"1k", "2k", "4k"}:
            return "1:1", raw
        if re.fullmatch(r"(auto|\d+\s*:\s*\d+)", raw):
            return raw.replace(" ", ""), "1k"
        return "1:1", "1k"
    return apimart_closest_aspect_ratio(width, height), apimart_resolution_from_long_edge(width, height)

def apimart_size_resolution(size):
    width, height = parse_size_pair(size)
    if not width or not height:
        return apimart_legacy_size_resolution(size)
    cell = apimart_official_size_cell(width, height)
    if cell:
        return cell
    return apimart_closest_aspect_ratio(width, height), apimart_resolution_from_long_edge(width, height)

def apimart_image_model_lc(model=""):
    return str(model or "").strip().lower()

def apimart_size_notice(requested_ratio, final_ratio, requested_resolution, final_resolution):
    """比例/分辨率被按模型能力收敛时，给用户一句可读说明；没收敛返回空串。"""
    notices = []
    requested = str(requested_resolution or "").strip().upper()
    final = str(final_resolution or "").strip().upper()
    if requested and final and requested != final:
        req_rank = APIMART_IMAGE_RESOLUTION_RANK.get(requested)
        fin_rank = APIMART_IMAGE_RESOLUTION_RANK.get(final)
        if req_rank is not None and fin_rank is not None:
            if fin_rank < req_rank:
                notices.append(f"该模型最高支持 {final}，已按 {final} 生成（原请求 {requested}）")
            else:
                notices.append(f"该模型最低支持 {final}，已按 {final} 生成（原请求 {requested}）")
    ratio_before = str(requested_ratio or "").strip()
    ratio_after = str(final_ratio or "").strip()
    if ratio_before and ratio_after and ratio_before.lower() != ratio_after.lower():
        notices.append(f"该模型不支持 {ratio_before}，已用 {ratio_after} 生成")
    return "；".join(notices)

APIMART_SPECIAL_RESOLUTION_PIXELS = {
    "0.5K": 262144, "768SQ": 589824, "1K": 1048576, "1.5K": 2097152,
    "2K": 4194304, "3K": 9437184, "4K": 16777216,
}

def apimart_image_resolution_from_size_for_model(size, model, caps=None):
    _ratio, resolution = apimart_size_resolution(size)
    caps = caps if isinstance(caps, dict) else (apimart_image_model_caps(model) or {})
    allowed = caps.get("resolutions") or ()
    if "1.5K" not in allowed and "768SQ" not in allowed:
        return resolution
    width, height = parse_size_pair(size)
    if not width or not height:
        return resolution
    pixels = width * height
    return min(allowed, key=lambda level: abs(math.log(pixels / APIMART_SPECIAL_RESOLUTION_PIXELS[level])))

def apimart_image_resolution_for_model(model="", resolution="1K", caps=None):
    """按官方文档逐模型收敛分辨率档位：请求档位超过模型上限时降到该模型最高档，
    不做「静默降级成 1K」；表里没有的模型保持原有白名单透传。"""
    caps = caps if isinstance(caps, dict) else apimart_image_model_caps(model)
    if caps and caps.get("fixed_resolution"):
        return str(caps["fixed_resolution"])
    text = str(resolution or "1K").strip().upper()
    if text not in {"0.5K", "768SQ", "1K", "1.5K", "2K", "3K", "4K"}:
        text = "1K"
    if not caps:
        return text if text in {"0.5K", "1K", "2K", "4K"} else "1K"
    return apimart_clamp_image_resolution(text, caps.get("resolutions"))

def is_apimart_official_image_model(model=""):
    value = re.sub(r"[^a-z0-9]+", "-", str(model or "").strip().lower()).strip("-")
    return value.endswith("-official") or value == "nano-banana-pro"

# 官方文档逐模型给出 size 允许比例 / resolution 允许档位 / n 上限 / mask_url 与 base64 参考图支持；
# 表里只收文档明确写死的集合，任意比例（如 mai-image 的 1:4~4:1）留空表示不收敛。
#
# 家族匹配（apimart_image_model_caps 按「最长 key 是模型名子串」匹配，这是有意的，不是字符串撞车）：
#   * gpt-image-2.5-flare / gpt-image-2.5-sunburst 是上游同一个 gpt-image-2.5 家族的不同出图版本，
#     共用 "gpt-image-2-5" 条目的比例/分辨率/n/精确尺寸/quality 档位（含 low..max）；
#   * gpt-image-2.5-ext / gpt-image-2.5-ext-flare / -sunburst 共用 "gpt-image-2-5-ext" 条目，
#     请求时统一下发 model=gpt-image-2.5-ext + version=flare|sunburst（见 _generate_ai_image_unlimited），
#     ext 条目没声明 qualities，所以这三个名字都不下发 quality（保守，避免上游不认）。
#   * gpt-image-2.6 例外：ext 与 flare/sunburst 能力不同（ext 只 1k、n 仅 1；flare/sunburst 1k/2k/4k、n 1–4），
#     所以 2.6 拆成三条独立条目，靠「最长 key 命中」保证不会落到 "gpt-image-2" 老家族表。
# 结论：flare/sunburst 不是漏表，是「同家族多版本」；上游文档若给出差异能力，才在这里单独加条目。
# SVG 输出的文本模型（上游 svg.model 必填，按该文本模型的 token 计费）：文档举例 gpt-5.4-mini / gpt-5.6-sol。
