def apimart_image_caps_key(model=""):
    return re.sub(r"[^a-z0-9]+", "-", str(model or "").strip().lower()).strip("-")

def apimart_image_model_caps(model=""):
    name = apimart_image_caps_key(model)
    if not name:
        return None
    for key in sorted(APIMART_IMAGE_MODEL_CAPS, key=len, reverse=True):
        if key in name:
            return APIMART_IMAGE_MODEL_CAPS[key]
    return None


def _provider_caps_overrides(provider) -> Dict[str, Dict[str, Any]]:
    """provider.model_caps_overrides 归一后的只读视图（模型名小写 -> {model, kind, caps}）。"""
    if not isinstance(provider, dict):
        return {}
    return normalize_model_caps_overrides(provider.get("model_caps_overrides"))


def _caps_override_for(provider, model, kind) -> Dict[str, Any]:
    key = str(model or "").strip().lower()
    if not key:
        return {}
    info = _provider_caps_overrides(provider).get(key)
    if not isinstance(info, dict):
        return {}
    if str(info.get("kind") or "image") != kind:
        return {}
    return dict(info.get("caps") or {})


def _merge_caps_table(table, override):
    """内置 caps 表 + 更新包覆盖（字段级；override 里有的字段覆盖内置）。返回新 dict。"""
    merged = dict(table or {})
    for field, value in (override or {}).items():
        merged[field] = value
    return merged


def apimart_image_caps_for(provider, model=""):
    """图片能力表 + provider 的 model_caps_overrides（生成与 /api/model-caps 用同一份）。"""
    return _merge_caps_table(apimart_image_model_caps(model), _caps_override_for(provider, model, "image"))


# 输出格式白名单：静态图不发字段（''），其余按下发值原样进请求体。
IMAGE_OUTPUT_FORMAT_VALUES = ("png", "jpeg", "webp", "gif", "svg")
IMAGE_OUTPUT_FORMAT_STATIC_VALUES = ("", "static", "静态图")


def normalize_image_output_format(value):
    """输出格式入参归一：空/静态图/未登记的值 -> ""；jpg 按 jpeg 处理，其余小写原样。"""
    text = str(value or "").strip().lower()
    if text in IMAGE_OUTPUT_FORMAT_STATIC_VALUES:
        return ""
    if text == "jpg":
        return "jpeg"
    return text if text in IMAGE_OUTPUT_FORMAT_VALUES else ""


def image_output_format_fields(model, caps, output_format):
    """输出格式请求字段：空 = 不发；能力表没声明或不在白名单 -> 400 并列出可选项。"""
    fmt = normalize_image_output_format(output_format)
    if not fmt:
        return {}
    allowed = [str(item).strip().lower() for item in ((caps or {}).get("output_formats") or ()) if str(item).strip()]
    if fmt not in allowed:
        options = " / ".join(allowed)
        detail = (f"该模型不支持输出格式 {fmt}；可选：{options}" if options
                  else f"{model or '该模型'} 不支持选择输出格式，请改用默认输出。")
        raise HTTPException(status_code=400, detail=detail)
    return {"output_format": fmt}


def apimart_output_format_fields(model, caps, output_format, n=1, has_refs=False):
    """APIMart 输出格式请求字段。

    文档确证：n 为 1-4（GIF 是动画帧数）；SVG 要求 n=1，且不能带参考图/mask/markup/output_compression。
    所以 SVG 一律把 n 收敛成 1，带参考图/蒙版直接 400；其它格式原样透传。
    """
    fields = image_output_format_fields(model, caps, output_format)
    if fields.get("output_format") != "svg":
        return fields
    if has_refs:
        raise HTTPException(
            status_code=400,
            detail="SVG 矢量输出不支持参考图或蒙版，请改用静态图或 GIF，或移除参考图后重试。",
        )
    fields["n"] = 1
    return fields


def apimart_svg_model(caps=None, override=""):
    """SVG 请求的文本模型（上游 svg.model 必填）：payload 覆盖 > 能力表默认 > 常量默认。"""
    value = str(override or "").strip()
    if value:
        return value
    svg = caps.get("svg") if isinstance(caps, dict) else None
    if isinstance(svg, dict):
        value = str(svg.get("model") or "").strip()
        if value:
            return value
    return APIMART_SVG_DEFAULT_MODEL


def image_output_extension(mime_type="", url=""):
    """落盘扩展名：MIME 优先，缺失/octet-stream 时按 URL 扩展名兜底，都不认识回退 .png。"""
    mime = str(mime_type or "").strip().lower()
    if "svg" in mime:
        return ".svg"
    if "gif" in mime:
        return ".gif"
    if "jpeg" in mime or "jpg" in mime:
        return ".jpg"
    if "webp" in mime:
        return ".webp"
    if "png" in mime:
        return ".png"
    path = str(url or "").split("?", 1)[0].split("#", 1)[0].lower()
    extension = os.path.splitext(path)[1]
    if extension in {".svg", ".gif", ".jpg", ".jpeg", ".webp"}:
        return ".jpg" if extension in {".jpg", ".jpeg"} else extension
    return ".png"


def image_output_extension_from_bytes(head):
    """按文件头识别 SVG / GIF（返回扩展名），其它一律返回 ''，让调用方保持 .png。"""
    data = bytes(head or b"")
    stripped = data.lstrip(b"\xef\xbb\xbf \t\r\n")
    if stripped.startswith(b"<svg") or (stripped.startswith(b"<?xml") and b"<svg" in data):
        return ".svg"
    if stripped.startswith((b"GIF87a", b"GIF89a")):
        return ".gif"
    return ""


def apimart_video_caps_for(provider, model=""):
    return _merge_caps_table(apimart_video_model_caps(model), _caps_override_for(provider, model, "video"))


def apimart_quality_for_model(model="", requested_quality="", caps=None):
    """该模型该下发的 quality；空串 = 不发（auto/空/该模型不支持的档位）。

    唯一收口：请求体组装只认这个函数，别在别处再加一套档位判断。
    档位完全由 caps.qualities 决定，保持既有行为：
      * gpt-image-2.6-ext 的六档来自文档（quality_levels_documented=True）；
      * gpt-image-2.5 等既有推断表原样保留（既有用例断言 quality=max 会下发，本次不动）。
    """
    caps = caps if isinstance(caps, dict) else (apimart_image_model_caps(model) or {})
    levels = caps.get("qualities") or ()
    text = str(requested_quality or "").strip().lower()
    if not text or text == "auto":
        return ""
    return text if text in levels else ""


def apimart_thinking_mode_value(model="", thinking_mode=None, caps=None):
    """该模型该下发的 thinking_mode；None = 不发（跟随上游默认 true）。

    只有 caps 标了 thinking_mode 的模型（目前是文档确证的 wan2.7-image / wan2.7-image-pro）才认这个字段；
    None 与不支持模型都返回 None，避免给别的族发未知参数。
    """
    caps = caps if isinstance(caps, dict) else (apimart_image_model_caps(model) or {})
    if thinking_mode is None or not caps.get("thinking_mode"):
        return None
    return bool(thinking_mode)


def apimart_image_request_identity(model=""):
    """APIMart 图片请求真正下发的 (model, version)。

    flare / sunburst 是 gpt-image-2.5-ext 的出图版本，不是独立模型：上游只认
    model=gpt-image-2.5-ext + version=flare|sunburst，所以带后缀的名字在这里剥掉后缀、改成 version 下发；
    能力表按家族共用 "gpt-image-2-5-ext" 一条（见 APIMART_IMAGE_MODEL_CAPS 上方注释）。
    不带 -ext- 的 gpt-image-2.5-flare / -sunburst 是上游独立模型名，原样下发、不带 version。"""
    request_model = str(model or "").strip()
    name = apimart_image_caps_key(request_model)
    if name.startswith("gpt-image-2-5-ext-"):
        request_model = "gpt-image-2.5-ext"
    if name == "gpt-image-2-5-ext":
        return request_model, "flare"
    if name.startswith("gpt-image-2-5-ext-"):
        return request_model, "sunburst" if "sunburst" in name else "flare"
    return request_model, ""

APIMART_IMAGE_RESOLUTION_RANK = {"0.5K": 0.5, "768SQ": 0.768, "1K": 1.0, "1.5K": 1.5, "2K": 2.0, "3K": 3.0, "4K": 4.0}

def apimart_clamp_image_resolution(value, allowed):
    levels = [str(item).strip().upper() for item in (allowed or ()) if str(item).strip()]
    if not levels:
        return value
    text = str(value or "").strip().upper()
    if text in levels:
        return text
    target = APIMART_IMAGE_RESOLUTION_RANK.get(text, 1.0)
    return min(levels, key=lambda item: (abs(APIMART_IMAGE_RESOLUTION_RANK.get(item, 1.0) - target),
                                         APIMART_IMAGE_RESOLUTION_RANK.get(item, 1.0)))

def apimart_ratio_number(text):
    match = re.fullmatch(r"(\d+(?:\.\d+)?)\s*[:x]\s*(\d+(?:\.\d+)?)", str(text or "").strip().lower())
    if not match:
        return None
    try:
        return float(match.group(1)) / float(match.group(2))
    except ZeroDivisionError:
        return None

def apimart_clamp_ratio(ratio, allowed):
    """把比例收敛到模型允许集合里最接近的一个（按数值比，不按字符串字典序）。"""
    levels = [str(item).strip().lower() for item in (allowed or ()) if str(item).strip()]
    if not levels:
        return ratio
    value = str(ratio or "").strip().lower().replace(" ", "")
    if value in levels:
        return value
    if value == "auto" or not value:
        return "1:1" if "1:1" in levels else levels[0]
    target = apimart_ratio_number(value)
    if target is None:
        return "1:1" if "1:1" in levels else levels[0]
    candidates = [item for item in levels if apimart_ratio_number(item)]
    if not candidates:
        return "1:1" if "1:1" in levels else levels[0]
    return min(candidates, key=lambda item: abs(apimart_ratio_number(item) - target))
# 火山方舟官方按模型给「总像素区间 + 档位」（https://ark.volcengine.com/region:cn-beijing/docs/image-generation-api）：
#   5.0 pro/flash [921600, 4624220]，1K/1.5K/2K；5.0 lite [3686400, 16777216]，2K/3K/4K；
#   4.5 [3686400, 16777216]，2K/4K；4.0 [921600, 16777216]，1K/2K/4K；宽高比一律 [1/16, 16]。
# 官方只约束总像素与宽高比，没有最小/最大边限制（旧口径的 min 边 1536 / max 边 4096 已移除）。
VOLCENGINE_RATIO_MIN = 1 / 16
VOLCENGINE_RATIO_MAX = 16
VOLCENGINE_TIER_SIDES = {"1k": 1024, "1.5k": 1536, "2k": 2048, "3k": 3072, "4k": 4096}
VOLCENGINE_TIER_ORDER = ("1k", "1.5k", "2k", "3k", "4k")
VOLCENGINE_SIZE_RULES = [
    ("seedream-5-0-lite", 3_686_400, 16_777_216, ("2k", "3k", "4k")),
    ("seedream-5-0-pro", 921_600, 4_624_220, ("1k", "1.5k", "2k")),
    ("seedream-5-0-flash", 921_600, 4_624_220, ("1k", "1.5k", "2k")),
    ("seedream-5-0", 921_600, 4_624_220, ("1k", "1.5k", "2k")),
    ("seedream-4-5", 3_686_400, 16_777_216, ("2k", "4k")),
    ("seedream-4-0", 921_600, 16_777_216, ("1k", "2k", "4k")),
]
VOLCENGINE_DEFAULT_SIZE_RULE = (3_686_400, 16_777_216, ("1k", "2k", "4k"))

def is_volcengine_seedream_model(model):
    value = str(model or "").strip().lower()
    return "seedream" in value or "doubao-seedream" in value

def volcengine_size_rule(model=""):
    """按模型名归一化后匹配官方规则；命中多个时列表顺序里更具体的（lite/pro/flash）在前。"""
    name = re.sub(r"[^a-z0-9]+", "-", str(model or "").strip().lower())
    for key, min_pixels, max_pixels, tiers in VOLCENGINE_SIZE_RULES:
        if key in name:
            return min_pixels, max_pixels, tiers
    return VOLCENGINE_DEFAULT_SIZE_RULE

def volcengine_tier_pixels(tier, model=""):
    """方式1 档位 → 官方 1:1 参考像素；档位不被该模型支持时收敛到不超过它的最高档。"""
    _min_pixels, _max_pixels, tiers = volcengine_size_rule(model)
    value = str(tier or "").strip().lower()
    if value in tiers:
        side = VOLCENGINE_TIER_SIDES[value]
    else:
        index = VOLCENGINE_TIER_ORDER.index(value) if value in VOLCENGINE_TIER_ORDER else VOLCENGINE_TIER_ORDER.index("2k")
        lower = [item for item in tiers if VOLCENGINE_TIER_ORDER.index(item) < index]
        side = VOLCENGINE_TIER_SIDES[lower[-1] if lower else tiers[0]]
    return f"{side}x{side}"

def volcengine_size_within_area(width, height, min_pixels, max_pixels):
    """官方方式2：同时满足总像素区间与宽高比；只做等比缩放 + 16 对齐，不再设边上限。"""
    width = max(1, int(width))
    height = max(1, int(height))
    if width * height > max_pixels:
        scale = (max_pixels / (width * height)) ** 0.5
        width = max(64, int(width * scale // 16) * 16)
        height = max(64, int(height * scale // 16) * 16)
    if width * height < min_pixels:
        grow = (min_pixels / max(1, width * height)) ** 0.5
        width = max(64, int(math.ceil(width * grow / 16)) * 16)
        height = max(64, int(math.ceil(height * grow / 16)) * 16)
    # 16 对齐与放大可能把面积再次顶过上限，按上限严格回缩一次
    if width * height > max_pixels:
        scale = (max_pixels / (width * height)) ** 0.5
        width = max(64, int(width * scale // 16) * 16)
        height = max(64, int(height * scale // 16) * 16)
    return f"{width}x{height}"

def normalize_volcengine_size(size, model=""):
    width, height = parse_size_pair(size)
    raw = str(size or "").strip().lower()
    if not width or not height:
        if raw in VOLCENGINE_TIER_SIDES:
            return volcengine_tier_pixels(raw, model)
        return "2048x2048" if is_volcengine_seedream_model(model) else (size or "1024x1024")
    if not is_volcengine_seedream_model(model):
        return f"{width}x{height}"
    ratio = width / max(1, height)
    if ratio > VOLCENGINE_RATIO_MAX:
        width = max(1, round(height * VOLCENGINE_RATIO_MAX))
    elif ratio < VOLCENGINE_RATIO_MIN:
        height = max(1, round(width / VOLCENGINE_RATIO_MIN))
    min_pixels, max_pixels, _tiers = volcengine_size_rule(model)
    return volcengine_size_within_area(width, height, min_pixels, max_pixels)

def friendly_upstream_common_error(text):
    """生图 / 视频 / 聊天通用的上游错误翻译：超时、网关错误、余额不足。返回空串表示没识别出来。"""
    lower_text = str(text or "").lower()
    if ("did not return a complete response" in lower_text or re.search(r"\b(524|504)\b", lower_text) or "timed out" in lower_text
            or "timeout" in lower_text or "gateway time-out" in lower_text):
        return ("上游生成超时（中转站等待模型返回超过了它的时限）。这次可能已经在上游扣费，系统不会自动重发。"
                "可以稍后再试，或降低分辨率 / 减少参考图，或换一个模型。")
    if "bad gateway" in lower_text or "service unavailable" in lower_text or re.search(r"\b(502|503)\b", lower_text):
        return "上游服务暂时不可用（502/503），通常是中转站或模型通道临时故障。稍后再试，或切换到其它平台 / 模型。"
    if ("insufficient_quota" in lower_text or "insufficient balance" in lower_text or "insufficient_user_quota" in lower_text
            or "余额不足" in lower_text or "额度不足" in lower_text or "quota exceeded" in lower_text or "credit" in lower_text and "insufficient" in lower_text):
        return "上游账户余额或额度不足，请到对应平台充值或更换 API Key。"
    return ""

def friendly_image_error_detail(text, size="", model=""):
    text = str(text or "")
    lower_text = text.lower()
    if re.search(r"\b413\b", lower_text) or "payload too large" in lower_text or "entity too large" in lower_text:
        return ("上游平台拒收了这次请求：参考图太多或太大，超过了它单个请求 1MB 的体积上限（413）。"
                "这是上游网关的限制，不是本机出错。请减少参考图数量，或换更小的参考图后重试。")
    if looks_like_html_response(text):
        return ("上游返回的是网关的 HTML 错误页，不是生图接口的正常响应（常见于中转站网关临时故障或请求被拦）。"
                "请稍后重试；若反复出现，减少参考图数量或换更小的参考图。")
    # GIF 的 400 来自「帧拼版整张图」超限，不是静态图的像素上限，别让下面的 GPT 尺寸分支把它吞掉。
    gif_sheet_error = (
        ("gif" in lower_text and any(token in lower_text for token in ("sheet", "frame")))
        or (("invalid_size" in lower_text or "invalid size" in lower_text)
            and any(token in lower_text for token in ("frame_count", "sheet")))
    )
    if gif_sheet_error:
        return ("GIF 输出有帧拼版上限：帧数×每帧尺寸合成的整张图必须 ≤3840 单边、≤829 万像素（9 帧 3x3）。"
                "请减小每帧尺寸或减少帧数；512x512 支持 2–16 帧。")
    # SVG：账号按张固定计费时不支持 SVG；缺 svg.model 是上游文本模型参数问题，别被下面的尺寸分支吞掉。
    svg_fixed_pricing = (
        "svg" in lower_text
        and any(token in lower_text for token in (
            "fixed price", "fixed-price", "fixed pricing", "per-image pricing", "per image pricing",
            "pay-per-image", "pay per image", "按张计费", "固定计费", "固定按张"))
    )
    if svg_fixed_pricing:
        return ("当前 APIMart 账号是固定按张计费，暂不支持 SVG 矢量输出；"
                "可改用静态图，或到平台上换成按量 token 计费的账号。")
    svg_model_error = (
        "svg" in lower_text
        and any(token in lower_text for token in ("svg.model", "svg_model", "requires svg"))
    )
    if svg_model_error:
        return ("SVG 输出需要上游指定的文本模型参数 svg.model（例如 gpt-5.4-mini，按该模型的文本 token 计费）。"
                "这是上游文本模型参数问题，不是尺寸问题：请补上 svg.model，或改用静态图。")
    if is_gpt_image_2_model(model) and gpt_image_2_size_exceeds_supported(size):
        return gpt_image_2_size_error_message(size)
    mentions_size = any(token in lower_text for token in ["size", "resolution", "dimension"])
    is_gpt_size_error = is_gpt_image_2_model(model) and mentions_size and (
        "invalid" in lower_text
        or "unsupported" in lower_text
        or "not supported" in lower_text
        or "exceed" in lower_text
        or "must be one of" in lower_text
    )
    m = re.search(r"longest edge must be less than or equal to (\d+)", text)
    if m and is_gpt_image_2_model(model):
        limit = m.group(1)
        return f"GPT-Image-2 不支持当前尺寸 {size or '未指定'}：最长边超过 {limit}px。如果需要更高分辨率，请切换到 nano-banana；继续使用 GPT 时请调低分辨率。"
    if m:
        limit = m.group(1)
        return f"该模型不支持当前分辨率：最长边超过 {limit}px。请把图片分辨率调低（例如换到 2K 或更小），或更换支持高分辨率的模型。"
    if "image size must be at least" in lower_text:
        pixel_match = re.search(r"at least (\d+) pixels", lower_text)
        pixels = pixel_match.group(1) if pixel_match else "3686400"
        return f"该模型要求更高分辨率，当前尺寸 {size or '过小'} 不满足最低像素要求（至少 {pixels} 像素）。火山 Seedream 5.0 建议从 2K 起步。"
    if is_gpt_size_error or (("invalid size" in lower_text or "invalid_value" in lower_text) and is_gpt_image_2_model(model)):
        return gpt_image_2_size_error_message(size)
    if "invalid size" in lower_text or "invalid_value" in lower_text:
        return f"该模型不支持当前尺寸：{size or '未指定'}。请尝试更换分辨率或模型。"
    if "inputtextsensitivecontentdetected" in lower_text or "policyviolation" in lower_text or "copyright restrictions" in lower_text:
        return "上游内容安全拦截了这段提示词，原因偏向版权/敏感内容限制。请改写提示词，避免直接出现具体 IP、角色名、品牌名、影视/动漫作品名，改成风格特征描述再试。"
    if "rejected by the safety system" in lower_text or "image_generation_user_error" in lower_text or "safety system" in lower_text or "content_policy_violation" in lower_text or "content policy" in lower_text:
        return "上游（Azure/OpenAI 系）内容安全系统拒绝了本次生图请求。可能是提示词或参考图触发了内容审核。请改写提示词、避免敏感/暴力/成人/名人/版权角色等描述；若使用了人物参考图，可换一张图再试。这是上游平台的审核策略，并非本系统报错。"
    if "rate limit" in lower_text or "429" in lower_text:
        return "请求过于频繁，已被上游限流（已自动退避重试 3 次仍失败）。请稍等一分钟再试，或减少同时生成的数量。"
    if "unauthorized" in lower_text or "401" in lower_text:
        return "API Key 无效或已过期，请到「API 设置」检查 Key。"
    friendly_common = friendly_upstream_common_error(text)
    if friendly_common:
        return friendly_common
    if "model_not_found" in lower_text or "channel not found" in lower_text:
        return f"上游平台找不到模型「{model}」可用通道。可能该模型未在此账号开通，请换一个已开通的模型。"
    return ""

def parse_error_payload_text(text):
    body = str(text or "").strip()
    if not body:
        return {}
    try:
        parsed = json.loads(body)
    except Exception:
        return {}
    return parsed if isinstance(parsed, dict) else {}

def friendly_chat_error_detail(text, model="", provider=None):
    raw_text = str(text or "")
    lower_text = raw_text.lower()
    payload = parse_error_payload_text(raw_text)
    error = payload.get("error") if isinstance(payload.get("error"), dict) else {}
    code = str(error.get("code") or payload.get("code") or "").strip()
    message = str(error.get("message") or payload.get("message") or "").strip()
    code_lc = code.lower()
    message_lc = message.lower()
    model_name = str(model or "").strip()

    if is_volcengine_provider(provider):
        if code_lc in {"invalidendpointormodel.notfound", "invalidendpointormodel.modelidaccessdisabled"}:
            provider_name = provider.get("name") or provider.get("id") or "火山方舟"
            return (
                f"{provider_name} 当前不接受模型名「{model_name or '未指定'}」直接调用聊天接口，"
                f"请在火山方舟控制台创建并使用推理接入点 ID（形如 `ep-...`）作为聊天模型。\n\n"
                f"补充说明：`/api/v3/models` 能拉到公开模型列表，但你的账号未必能直接用这些模型名调用 `/chat/completions`；"
                f"很多账号只允许传自己已开通的 `ep-...` 接入点。"
            )
        if "does not exist or you do not have access to it" in message_lc:
            return (
                f"火山方舟找不到或无权访问聊天模型「{model_name or '未指定'}」。"
                f"如果你现在填的是模型名，请改成已开通的推理接入点 ID（`ep-...`）；"
                f"如果已经是 `ep-...`，请检查这个接入点是否绑定了聊天模型、区域是否正确、以及账号是否有调用权限。"
            )
    if "unauthorized" in lower_text or "401" in lower_text:
        return "API Key 无效或已过期，请到「API 设置」检查 Key。"
    if "rate limit" in lower_text or "429" in lower_text:
        return "请求过于频繁，已被上游限流，请稍后再试。"
    return friendly_upstream_common_error(raw_text)

async def generate_modelscope_provider_image(prompt, size, model, reference_images=None, provider=None):
    clean_token = modelscope_api_key()
    if not clean_token:
        raise HTTPException(status_code=400, detail="未配置 ModelScope API Key，请在 API 设置中填写。")
    resolved_model = selected_model(model, "Tongyi-MAI/Z-Image-Turbo")
    size = modelscope_constrain_size(size, resolved_model) or size
    width, height = parse_size_pair(size)
    refs = []
    for ref in (reference_images or [])[:ONLINE_IMAGE_REFERENCE_MAX]:
        if not ref.get("url"):
            continue
        # 本地参考图转为 data URL；前端已生成的 data URL 保持原样，贴近旧版稳定链路。
        refs.append(modelscope_image_url(ref.get("url", ""), max_size=1536))
    headers = {
        "Authorization": f"Bearer {clean_token}",
        "Content-Type": "application/json",
        "X-ModelScope-Async-Mode": "true",
    }
    payload = {
        "model": resolved_model,
        "prompt": prompt.strip(),
    }
    if width and height:
        payload["width"] = width
        payload["height"] = height
        payload["size"] = f"{width}x{height}"
    if refs:
        payload["image_url"] = refs

    api_root = modelscope_image_api_root()
    async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env(provider), timeout=AI_REQUEST_TIMEOUT) as client:
        submit_res = await client.post(f"{api_root}/images/generations", headers=headers, json=payload)
        submit_res.raise_for_status()
        raw = submit_res.json()
        task_id = raw.get("task_id")
        if not task_id:
            try:
                return extract_image(raw), raw
            except HTTPException:
                raise HTTPException(status_code=502, detail=f"ModelScope 未返回 task_id：{raw}")

        deadline = time.monotonic() + AI_REQUEST_TIMEOUT
        last_payload = raw
        while time.monotonic() < deadline:
            await asyncio.sleep(IMAGE_POLL_INTERVAL)
            result = await client.get(
                f"{api_root}/tasks/{task_id}",
                headers={**headers, "X-ModelScope-Task-Type": "image_generation"},
            )
            result.raise_for_status()
            data = result.json()
            last_payload = data
            status = str(data.get("task_status") or "").upper()
            if status == "SUCCEED":
                images = data.get("output_images") or []
                if not images:
                    raise HTTPException(status_code=502, detail=f"ModelScope 成功但没有返回图片：{data}")
                return {"type": "url", "value": images[0]}, data
            if status in {"FAILED", "FAIL", "ERROR", "CANCELED", "CANCELLED", "TIMEOUT", "REVOKED"}:
                detail = data.get("error_info") or data.get("message") or data.get("detail") or str(data)
                raise HTTPException(status_code=502, detail=f"ModelScope 任务失败：{detail}")
        raise HTTPException(status_code=504, detail=f"ModelScope 生图任务超时：{last_payload}")

def gemini_model_name(model):
    value = selected_model(model, "gemini-3-pro-image-preview").strip()
    return value[len("models/"):] if value.startswith("models/") else value

def gemini_endpoint_url(provider, model):
    """Gemini 协议的端点必须配 Gemini 请求体。

    image_generation_endpoint 是 OpenAI 生图端口；模型被自动判定为 Gemini 协议时若沿用它，
    Gemini 原生请求体会打到 /v1/images/generations（真实中转站返回 404 Images API is not supported）。
    只有供应商本来就声明 protocol=gemini 时才允许用该字段覆盖自定义 Gemini 路径。
    """
    model_name = urllib.parse.quote(gemini_model_name(model), safe="")
    override = None if provider_protocol(provider) == "gemini" else ""
    return provider_endpoint_url(provider, "image_generation_endpoint",
                                 f"/v1beta/models/{model_name}:generateContent", override=override)

# Gemini 官方宽高比表（https://ai.google.dev/gemini-api/docs/image-generation）：
# 14 个比例，不含 APIMart 的 2:1/1:2/3:1/1:3/9:21；3.1 Pro Image 只支持其中 10 个。
GEMINI_ASPECT_RATIOS = [
    (1, 1, "1:1"), (1, 4, "1:4"), (1, 8, "1:8"), (2, 3, "2:3"), (3, 2, "3:2"),
    (3, 4, "3:4"), (4, 1, "4:1"), (4, 3, "4:3"), (4, 5, "4:5"), (5, 4, "5:4"),
    (8, 1, "8:1"), (9, 16, "9:16"), (16, 9, "16:9"), (21, 9, "21:9"),
]
GEMINI_PRO_ASPECT_RATIOS = {"1:1", "2:3", "3:2", "3:4", "4:3", "4:5", "5:4", "9:16", "16:9", "21:9"}
GEMINI_TIER_LEVELS = ("0.5K", "1K", "2K", "4K")
GEMINI_512_ALIASES = {"0.5K", "512"}

def gemini_model_lc(model=""):
    return gemini_model_name(model).strip().lower()

def gemini_aspect_ratio_choices(model=""):
    choices = list(GEMINI_ASPECT_RATIOS)
    name = gemini_model_lc(model)
    if "3.1-pro-image" in name or "3-pro-image" in name:
        return [item for item in choices if item[2] in GEMINI_PRO_ASPECT_RATIOS]
    return choices

def gemini_image_size_choices(model=""):
    """官方档位：3.1 Flash Image 多 0.5K；3.1 Flash Lite 仅 1K；2.5 Flash Image 单档。"""
    name = gemini_model_lc(model)
    if "flash-lite" in name or "2.5-flash-image" in name:
        return ("1K",)
    if "3.1-flash-image" in name:
        return ("0.5K", "1K", "2K", "4K")
    return ("1K", "2K", "4K")

def gemini_closest_aspect_ratio(width, height, model=""):
    ratio = width / max(1, height)
    return min(gemini_aspect_ratio_choices(model), key=lambda item: abs(math.log(ratio / (item[0] / item[1]))))[2]

def gemini_clamp_image_size(level, model=""):
    choices = gemini_image_size_choices(model)
    value = str(level or "").strip().upper()
    if value in GEMINI_512_ALIASES:
        value = "0.5K"
    if value in choices:
        return value
    if value in GEMINI_TIER_LEVELS:
        index = GEMINI_TIER_LEVELS.index(value)
        lower = [item for item in choices if item in GEMINI_TIER_LEVELS and GEMINI_TIER_LEVELS.index(item) < index]
        if lower:
            return lower[-1]
        if choices:
            return choices[0]
    return "1K" if "1K" in choices else (choices[0] if choices else "1K")

def gemini_default_image_size(model=""):
    choices = gemini_image_size_choices(model)
    return "2K" if "2K" in choices else ("1K" if "1K" in choices else choices[0])

def gemini_aspect_ratio_from_text(text, model=""):
    match = re.fullmatch(r"(\d+)\s*:\s*(\d+)", str(text or "").strip())
    if not match:
        return "1:1"
    known = {item[2] for item in gemini_aspect_ratio_choices(model)}
    ratio = "%s:%s" % (int(match.group(1)), int(match.group(2)))
    if ratio in known:
        return ratio
    return gemini_closest_aspect_ratio(int(match.group(1)), int(match.group(2)), model)

def gemini_image_config(size, model=""):
    width, height = parse_size_pair(size)
    if not width or not height:
        raw = str(size or "").strip()
        if raw.upper() in GEMINI_TIER_LEVELS or raw in GEMINI_512_ALIASES:
            return {"aspectRatio": "1:1", "imageSize": gemini_clamp_image_size(raw, model)}
        if re.fullmatch(r"\d+\s*:\s*\d+", raw):
            return {"aspectRatio": gemini_aspect_ratio_from_text(raw, model), "imageSize": gemini_default_image_size(model)}
        return {"aspectRatio": "1:1", "imageSize": gemini_default_image_size(model)}
    ratio = gemini_closest_aspect_ratio(width, height, model)
    level = apimart_resolution_from_long_edge(width, height).upper()
    choices = gemini_image_size_choices(model)
    if level == "1K" and "0.5K" in choices and width * height <= 512 * 512 * 2:
        level = "0.5K"
    return {"aspectRatio": ratio, "imageSize": gemini_clamp_image_size(level, model)}

# Agnes 官方「档位 + 宽高比」（https://www.agnes-ai.cn/zh-Hans/docs/agnes-image-25-flash）：
# size 用 1K/2K/3K/4K 档位（也兼容精确 WxH，但会被标准化），ratio 支持 8 个，输出像素见官方参考表。
AGNES_ASPECT_RATIOS = [
    (1, 1, "1:1"), (3, 4, "3:4"), (4, 3, "4:3"), (16, 9, "16:9"),
    (9, 16, "9:16"), (2, 3, "2:3"), (3, 2, "3:2"), (21, 9, "21:9"),
]
AGNES_SIZE_TIERS = ("1K", "2K", "3K", "4K")
AGNES_OUTPUT_PIXELS = {
    "1:1": {"1K": (1024, 1024), "2K": (2048, 2048), "3K": (3072, 3072), "4K": (4096, 4096)},
    "3:4": {"1K": (864, 1152), "2K": (1728, 2304), "3K": (2592, 3456), "4K": (3456, 4608)},
    "4:3": {"1K": (1152, 864), "2K": (2304, 1728), "3K": (3456, 2592), "4K": (4608, 3456)},
    "16:9": {"1K": (1312, 736), "2K": (2624, 1472), "3K": (3936, 2208), "4K": (5248, 2944)},
    "9:16": {"1K": (736, 1312), "2K": (1472, 2624), "3K": (2208, 3936), "4K": (2944, 5248)},
    "2:3": {"1K": (832, 1248), "2K": (1664, 2496), "3K": (2496, 3744), "4K": (3328, 4992)},
    "3:2": {"1K": (1248, 832), "2K": (2496, 1664), "3K": (3744, 2496), "4K": (4992, 3328)},
    "21:9": {"1K": (1568, 672), "2K": (3136, 1344), "3K": (4704, 2016), "4K": (6272, 2688)},
}

def is_agnes_image_model(model=""):
    return str(model or "").strip().lower().startswith("agnes-image-")

def agnes_closest_aspect_ratio(width, height):
    ratio = width / max(1, height)
    return min(AGNES_ASPECT_RATIOS, key=lambda item: abs(math.log(ratio / (item[0] / item[1]))))[2]

def agnes_pixel_size(tier, ratio):
    return AGNES_OUTPUT_PIXELS.get(ratio, AGNES_OUTPUT_PIXELS["1:1"]).get(tier)

def agnes_closest_tier(width, height, ratio):
    target = max(1, width * height)
    def score(tier):
        pixels = agnes_pixel_size(tier, ratio)
        return abs(math.log((pixels[0] * pixels[1]) / target))
    return min(AGNES_SIZE_TIERS, key=score)

def agnes_image_config(size):
    """把请求尺寸换算成官方「档位 + 比例」：返回 (size, ratio)。"""
    width, height = parse_size_pair(size)
    if not width or not height:
        raw = str(size or "").strip().upper()
        if raw in AGNES_SIZE_TIERS:
            return raw, "1:1"
        match = re.fullmatch(r"(\d+)\s*:\s*(\d+)", raw)
        if match:
            return "2K", agnes_closest_aspect_ratio(int(match.group(1)), int(match.group(2)))
        return "2K", "1:1"
    ratio = agnes_closest_aspect_ratio(width, height)
    return agnes_closest_tier(width, height, ratio), ratio

def gemini_reference_part(ref):
    value = reference_to_data_url(ref, max_size=1536)
    if not value:
        return None
    if isinstance(value, str) and value.startswith("data:image/") and ";base64," in value:
        header, encoded = value.split(";base64,", 1)
        mime_type = header.replace("data:", "", 1) or "image/png"
        return {"inlineData": {"mimeType": mime_type, "data": encoded}}
    if isinstance(value, str) and value.startswith(("http://", "https://")):
        return {"fileData": {"mimeType": "image/png", "fileUri": value}}
    return None

async def generate_gemini_provider_image(prompt, size, model, reference_images=None, provider=None):
    model_name = gemini_model_name(model)
    endpoint = gemini_endpoint_url(provider, model_name)
    parts = [{"text": prompt.strip()}]
    for ref in (reference_images or [])[:ONLINE_IMAGE_REFERENCE_MAX]:
        part = gemini_reference_part(ref)
        if part:
            parts.append(part)
    body = {
        "contents": [{"role": "user", "parts": parts}],
        "generationConfig": {
            "responseModalities": ["TEXT", "IMAGE"],
            "imageConfig": gemini_image_config(size, model),
        },
    }
    # 中转站连上游走本机代理，代理偶发抖动就是一次 ConnectTimeout，这里允许连接阶段重试
    retry_context = f"生图 provider={(provider or {}).get('id') or 'comfly'} model={model_name}"
    async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env(provider), timeout=httpx.Timeout(connect=30.0, read=1800.0, write=120.0, pool=20.0)) as client:
        response = await with_connect_retries(
            lambda: client.post(endpoint, headers=api_headers(provider=provider), json=body),
            context=retry_context,
        )
        response.raise_for_status()
        raw = response.json()
        return extract_image(raw), raw

def volcengine_endpoint_url(provider):
    return provider_endpoint_url(provider, "image_generation_endpoint", "/api/v3/images/generations")

def volcengine_image_payload(ref):
    value = reference_to_data_url(ref, max_size=1536)
    if not value:
        return None
    return value

def is_lovart_provider(provider):
    return provider_protocol(provider) == "lovart" or str((provider or {}).get("id") or "").strip().lower() == "lovart"

def lovart_base_url(provider=None):
    base_url = str((provider or {}).get("base_url") or LOVART_DEFAULT_BASE_URL).strip().rstrip("/")
    return base_url or LOVART_DEFAULT_BASE_URL

def lovart_trust_env(provider) -> bool:
    # Lovart 网关在海外且被 Cloudflare 挡直连：默认必须走系统代理，实测直连只会 ConnectError
    mode = normalize_provider_use_proxy((provider or {}).get("use_proxy") if isinstance(provider, dict) else None)
    return mode != "off"

def lovart_http_client(provider, timeout):
    return httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=lovart_trust_env(provider), timeout=timeout)

def lovart_openapi_user_agent():
    # 上游可能按 UA 做来源校验，报 Mac 串会露馅
    return _LOVART_OPENAPI_USER_AGENT_WINDOWS if sys.platform.startswith("win") else LOVART_OPENAPI_USER_AGENT

def lovart_api_path(path: str) -> str:
    text = str(path or "").strip()
    if not text:
        return LOVART_OPENAPI_PREFIX
    if text.startswith(LOVART_OPENAPI_PREFIX):
        return text
    return f"{LOVART_OPENAPI_PREFIX}/{text.lstrip('/')}"

def lovart_signed_headers(method: str, path: str, access_key: str, secret_key: str) -> Dict[str, str]:
    timestamp = str(int(time.time()))
    signature = hmac.new(
        str(secret_key or "").encode("utf-8"),
        f"{method}\n{path}\n{timestamp}".encode("utf-8"),
        hashlib.sha256,
    ).hexdigest()
    headers = {
        "X-Access-Key": str(access_key or ""),
        "X-Timestamp": timestamp,
        "X-Signature": signature,
        "X-Signed-Method": method,
        "X-Signed-Path": path,
        "Content-Type": "application/json",
        "Accept": "*/*",
        "User-Agent": lovart_openapi_user_agent(),
    }
    if method == "POST":
        headers["Idempotency-Key"] = uuid.uuid4().hex
    return headers

def lovart_credentials(access_key="", secret_key=""):
    access = str(access_key or "").strip() or lovart_access_key_value()
    secret = str(secret_key or "").strip() or lovart_secret_key_value()
    if not access or not secret:
        raise HTTPException(status_code=400, detail="未配置 Lovart 的 Access Key / Secret Key，请在 API 设置中填写。")
    return access, secret

def lovart_error_detail(status_code, payload):
    code = payload.get("code") if isinstance(payload, dict) else None
    message = ""
    if isinstance(payload, dict):
        message = str(payload.get("message") or payload.get("error") or payload.get("msg") or "").strip()
        details = str(payload.get("details") or "").strip()
        if details:
            message = f"{message}：{details}" if message else details
    if not message:
        message = str(payload)[:300] if payload is not None else ""
    if status_code == 401 or str(code) == "1005":
        return "Lovart 密钥无效，请检查 Access Key / Secret Key"
    label = f"HTTP {status_code}" + (f"，code={code}" if code is not None else "")
    return f"Lovart 接口失败（{label}）：{message}" if message else f"Lovart 接口失败（{label}）"

async def lovart_request(client, provider, method, path, body=None, params=None, access_key="", secret_key=""):
    path = lovart_api_path(path)
    method = method.upper()
    access, secret = lovart_credentials(access_key, secret_key)
    url = f"{lovart_base_url(provider)}{path}"
    if params:
        url = f"{url}?{urllib.parse.urlencode(params)}"
    headers = lovart_signed_headers(method, path, access, secret)
    payload_bytes = json.dumps(body, ensure_ascii=False).encode("utf-8") if body is not None else None
    response = await client.request(method, url, headers=headers, content=payload_bytes)
    try:
        payload = response.json()
    except Exception:
        payload = None
    if response.status_code >= 400:
        raw = payload if payload is not None else (response.text or "")[:300]
        raise HTTPException(status_code=response.status_code, detail=lovart_error_detail(response.status_code, raw))
    if not isinstance(payload, dict):
        raise HTTPException(status_code=502, detail=f"Lovart 接口返回非 JSON 响应：{(response.text or '')[:300]}")
    code = payload.get("code", 0)
    if code not in (0, "0", None):
        raise HTTPException(status_code=502, detail=lovart_error_detail(response.status_code, payload))
    data = payload.get("data")
    return data if isinstance(data, dict) else (data if data is not None else {})

def lovart_provider_config(provider_id="lovart"):
    try:
        return get_api_provider_exact(provider_id or "lovart")
    except HTTPException:
        provider = {"id": "lovart", "name": "Lovart", "base_url": LOVART_DEFAULT_BASE_URL, "protocol": "lovart"}
    provider["lovart_auto_confirm"] = bool(provider.get("lovart_auto_confirm", False))
    provider["lovart_project_id"] = str(provider.get("lovart_project_id") or "").strip()
    return provider

def lovart_store_project_id(project_id: str):
    project_id = str(project_id or "").strip()
    if not project_id:
        return
    try:
        providers = load_api_providers()
        changed = False
        for item in providers:
            if str(item.get("id") or "").strip().lower() != "lovart" and str(item.get("protocol") or "").strip().lower() != "lovart":
                continue
            if str(item.get("lovart_project_id") or "").strip() != project_id:
                item["lovart_project_id"] = project_id
                changed = True
        if changed:
            save_api_providers(providers)
    except Exception as exc:
        print(f"Lovart 项目 ID 保存失败（不影响本次生成）: {exc}")

def lovart_store_unlimited(unlimited: bool):
    try:
        providers = load_api_providers()
        found = False
        for item in providers:
            if str(item.get("id") or "").strip().lower() != "lovart" and str(item.get("protocol") or "").strip().lower() != "lovart":
                continue
            found = True
            item["lovart_unlimited"] = bool(unlimited)
        if found:
            save_api_providers(providers)
    except Exception as exc:
        print(f"Lovart 账号模式保存失败（不影响本次切换）: {exc}")

async def lovart_ensure_project_id(client, provider):
    project_id = str((provider or {}).get("lovart_project_id") or "").strip()
    if project_id:
        return project_id
    data = await lovart_request(client, provider, "POST", "/project/save", body={
        "project_id": "",
        "canvas": "",
        "project_cover_list": [],
        "pic_count": 0,
        "project_type": 3,
    })
    project_id = str((data or {}).get("project_id") or "").strip() if isinstance(data, dict) else ""
    if not project_id:
        raise HTTPException(status_code=502, detail="Lovart 新建项目失败：接口未返回 project_id")
    provider["lovart_project_id"] = project_id
    lovart_store_project_id(project_id)
    return project_id

def lovart_upload_url(payload):
    if isinstance(payload, str):
        return payload.strip()
    if isinstance(payload, list):
        for item in payload:
            url = lovart_upload_url(item)
            if url:
                return url
        return ""
    if not isinstance(payload, dict):
        return ""
    for key in ("url", "file_url", "fileUrl", "cdn_url", "cdnUrl", "content", "path"):
        value = payload.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    for key in ("files", "list", "urls", "data", "file", "result"):
        if key in payload:
            url = lovart_upload_url(payload.get(key))
            if url:
                return url
    return ""

async def lovart_upload_file(client, provider, local_path):
    with open(local_path, "rb") as f:
        file_bytes = f.read()
    if not file_bytes:
        return ""
    filename = os.path.basename(str(local_path or "")) or "reference.png"
    filename = filename.replace('"', "_").replace("\r", "_").replace("\n", "_")
    boundary = uuid.uuid4().hex
    path = lovart_api_path("/file/upload")
    body = (
        f"--{boundary}\r\n"
        f'Content-Disposition: form-data; name="file"; filename="{filename}"\r\n'
        f"Content-Type: application/octet-stream\r\n\r\n"
    ).encode("utf-8") + file_bytes + f"\r\n--{boundary}--\r\n".encode("utf-8")
    access, secret = lovart_credentials()
    headers = lovart_signed_headers("POST", path, access, secret)
    headers["Content-Type"] = f"multipart/form-data; boundary={boundary}"
    response = await client.post(f"{lovart_base_url(provider)}{path}", headers=headers, content=body)
    try:
        payload = response.json()
    except Exception:
        payload = None
    if response.status_code >= 400:
        raw = payload if payload is not None else (response.text or "")[:300]
        raise HTTPException(status_code=response.status_code, detail=lovart_error_detail(response.status_code, raw))
    if not isinstance(payload, dict):
        raise HTTPException(status_code=502, detail=f"Lovart 参考图上传返回非 JSON 响应：{(response.text or '')[:300]}")
    if payload.get("code", 0) not in (0, "0", None):
        raise HTTPException(status_code=502, detail=lovart_error_detail(response.status_code, payload))
    url = lovart_upload_url(payload.get("data"))
    if not url:
        raise HTTPException(status_code=502, detail=f"Lovart 参考图上传成功但没有返回 CDN 地址：{json.dumps(payload, ensure_ascii=False)[:300]}")
    return url

async def lovart_attachment_urls(client, provider, refs):
    urls = []
    for ref in refs or []:
        ref_url = str((ref or {}).get("url") or "").strip()
        if not ref_url:
            continue
        if ref_url.startswith(("http://", "https://")):
            urls.append(ref_url)
            continue
        local_path = output_file_from_url(ref_url)
        if not local_path or not os.path.isfile(local_path):
            continue
        uploaded = await lovart_upload_file(client, provider, local_path)
        if uploaded:
            urls.append(uploaded)
    return urls

def lovart_thread_id(data):
    if not isinstance(data, dict):
        return ""
    return str(data.get("thread_id") or data.get("threadId") or "").strip()

async def lovart_start_chat(client, provider, prompt, model, category, attachments=None):
    project_id = await lovart_ensure_project_id(client, provider)
    body = {"prompt": str(prompt or ""), "project_id": project_id}
    if attachments:
        body["attachments"] = list(attachments)
    model = str(model or "").strip()
    if model:
        body["tool_config"] = {
            "prefer_tool_categories": {category: [model]},
            "include_tools": [model],
        }
    data = await lovart_request(client, provider, "POST", "/chat", body=body)
    thread_id = lovart_thread_id(data)
    if not thread_id:
        raise HTTPException(status_code=502, detail=f"Lovart 提交任务失败：接口未返回 thread_id（{json.dumps(data, ensure_ascii=False)[:300]}）")
    return thread_id, project_id

def lovart_failures_text(result):
    failures = (result or {}).get("failures") if isinstance(result, dict) else None
    texts = []
    if isinstance(failures, list):
        for item in failures:
            if isinstance(item, dict):
                text = item.get("message") or item.get("reason") or item.get("error")
                if text:
                    texts.append(str(text))
            elif item:
                texts.append(str(item))
    elif failures:
        texts.append(str(failures))
    return "；".join(texts)[:300]

def lovart_pending_signature(pending):
    try:
        return hashlib.sha1(json.dumps(pending, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()
    except Exception:
        return str(pending)[:200]

def lovart_pending_confirmation_detail(pending):
    detail = ""
    if isinstance(pending, dict):
        detail = str(pending.get("message") or pending.get("reason") or pending.get("title") or "").strip()
        cost = pending.get("estimated_cost") or pending.get("cost") or pending.get("credits")
        if cost not in (None, ""):
            detail = f"{detail}（预计消耗 {cost} 积分）" if detail else f"预计消耗 {cost} 积分"
    elif pending:
        detail = str(pending)[:200]
    message = "Lovart 把这个操作判定为高成本操作（例如视频生成、高端图片模型），需要确认后才会继续。"
    if detail:
        message = f"{message}\n{detail}"
    return (
        f"{message}\n"
        "请到 Lovart 网页端确认这次任务，或在「API 设置 → Lovart」里打开「自动确认」（lovart_auto_confirm）后重试。"
    )

async def lovart_wait_for_result(client, provider, thread_id):
    auto_confirm = bool((provider or {}).get("lovart_auto_confirm", False))
    confirmed = set()
    auto_confirmed = False
    done_rechecked = False
    poll_count = 0
    deadline = time.monotonic() + LOVART_CHAT_POLL_TIMEOUT
    while True:
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            raise HTTPException(status_code=504, detail=f"Lovart 任务超时（已等待 {int(LOVART_CHAT_POLL_TIMEOUT)} 秒），thread_id={thread_id}")
        status_data = await lovart_request(client, provider, "GET", "/chat/status", params={"thread_id": thread_id})
        status = str((status_data or {}).get("status") or "").strip().lower() if isinstance(status_data, dict) else ""
        poll_count += 1
        if status == "abort":
            reason = lovart_failures_text(await lovart_request(client, provider, "GET", "/chat/result", params={"thread_id": thread_id}))
            raise HTTPException(status_code=502, detail=f"Lovart 任务被中断：{reason}" if reason else "Lovart 任务被中断（abort）")
        if status == "done":
            if not done_rechecked:
                done_rechecked = True
                await asyncio.sleep(min(LOVART_CHAT_DONE_RECHECK_DELAY, max(0.0, deadline - time.monotonic())))
                continue
            result = await lovart_request(client, provider, "GET", "/chat/result", params={"thread_id": thread_id})
            result = result if isinstance(result, dict) else {}
            pending = result.get("pending_confirmation")
            if not pending:
                result["final_status"] = "done"
                result["auto_confirmed"] = auto_confirmed
                return result
            signature = lovart_pending_signature(pending)
            if signature in confirmed:
                raise HTTPException(status_code=502, detail="Lovart 已确认该高成本操作，但任务仍在等待确认，请到 Lovart 网页端检查任务状态。")
            if not auto_confirm:
                raise HTTPException(status_code=409, detail=lovart_pending_confirmation_detail(pending))
            await lovart_request(client, provider, "POST", "/chat/confirm", body={"thread_id": thread_id})
            confirmed.add(signature)
            auto_confirmed = True
            done_rechecked = False
        elif status == "running" and poll_count % 3 == 0:
            result = await lovart_request(client, provider, "GET", "/chat/result", params={"thread_id": thread_id})
            pending = result.get("pending_confirmation") if isinstance(result, dict) else None
            if pending:
                signature = lovart_pending_signature(pending)
                if signature in confirmed:
                    raise HTTPException(status_code=502, detail="Lovart 已确认该高成本操作，但任务仍在等待确认，请到 Lovart 网页端检查任务状态。")
                if not auto_confirm:
                    raise HTTPException(status_code=409, detail=lovart_pending_confirmation_detail(pending))
                await lovart_request(client, provider, "POST", "/chat/confirm", body={"thread_id": thread_id})
                confirmed.add(signature)
                auto_confirmed = True
        await asyncio.sleep(min(LOVART_CHAT_POLL_INTERVAL, max(0.0, deadline - time.monotonic())))

def lovart_artifact_urls(result, category="IMAGE"):
    kind = "video" if str(category or "").upper() == "VIDEO" else "image"
    urls = []
    seen = set()
    items = (result or {}).get("items") if isinstance(result, dict) else None
    for item in items or []:
        if not isinstance(item, dict):
            continue
        for artifact in item.get("artifacts") or []:
            if not isinstance(artifact, dict):
                continue
            content = artifact.get("content")
            if isinstance(content, list):
                content = next((one for one in content if isinstance(one, str) and one.strip()), "")
            content = str(content or "").strip()
            if not content or content in seen:
                continue
            atype = str(artifact.get("type") or "").strip().lower()
            if atype:
                if kind not in atype:
                    continue
            elif kind == "video":
                if not re.search(r"\.(mp4|webm|mov|m4v)(\?|$)", content, re.I):
                    continue
            elif re.search(r"\.(mp4|webm|mov|m4v)(\?|$)", content, re.I):
                continue
            seen.add(content)
            urls.append(content)
    return urls

async def lovart_download_artifact(client, url, prefix="lovart_"):
    text = str(url or "").strip()
    if not text or text.startswith(("/output/", "/assets/")):
        return text
    if not text.startswith(("http://", "https://")):
        return text
    ext = os.path.splitext(text.split("?", 1)[0].split("#", 1)[0])[1].lower()
    if ext not in {".png", ".jpg", ".jpeg", ".webp", ".gif", ".mp4", ".webm", ".mov", ".m4v"}:
        ext = ".png"
    response = await client.get(text, headers={
        "User-Agent": LOVART_ARTIFACT_USER_AGENT,
        "Referer": LOVART_ARTIFACT_REFERER,
    })
    response.raise_for_status()
    content_type = (response.headers.get("Content-Type") or "").lower()
    for token, suffix in (("jpeg", ".jpg"), ("jpg", ".jpg"), ("webp", ".webp"), ("mp4", ".mp4"), ("webm", ".webm"), ("quicktime", ".mov")):
        if token in content_type:
            ext = suffix
            break
    filename = f"{prefix}{uuid.uuid4().hex[:10]}{ext}"
    path = output_path_for(filename, "output")
    with open(path, "wb") as f:
        f.write(response.content)
    return output_url_for(filename, "output")

async def lovart_run_generation(client, provider, prompt, model, category, reference_images=None):
    kind = str(category or "IMAGE").upper()
    attachments = await lovart_attachment_urls(client, provider, (reference_images or [])[:ONLINE_IMAGE_REFERENCE_MAX])
    thread_id, project_id = await lovart_start_chat(client, provider, prompt, model, kind, attachments)
    result = await lovart_wait_for_result(client, provider, thread_id)
    remote_urls = lovart_artifact_urls(result, kind)
    if not remote_urls:
        failures = lovart_failures_text(result)
        detail = "Lovart 没有返回产物"
        if failures:
            detail = f"{detail}：{failures}"
        else:
            detail = f"{detail}，可能是提示词被上游模型拒绝，或 Agent 只回复了文字没有出图/出视频。"
        raise HTTPException(status_code=502, detail=detail)
    local_urls = []
    for remote in remote_urls:
        local = await lovart_download_artifact(client, remote, prefix="lovart_video_" if kind == "VIDEO" else "lovart_")
        if local:
            local_urls.append(local)
    if not local_urls:
        raise HTTPException(status_code=502, detail="Lovart 产物下载失败（CDN 地址不可访问）")
    raw = {
        "task_id": thread_id,
        "thread_id": thread_id,
        "project_id": project_id,
        "provider": "lovart",
        "model": str(model or ""),
        "final_status": result.get("final_status"),
        "auto_confirmed": result.get("auto_confirmed"),
        "failures": lovart_failures_text(result),
        "images" if kind == "IMAGE" else "videos": local_urls,
    }
    return local_urls, raw

def lovart_chat_mode(payload):
    hint = " ".join([
        str(getattr(payload, "think_level", "") or ""),
        str(getattr(payload, "mode", "") or ""),
    ]).lower()
    return "thinking" if any(key in hint for key in ("think", "high", "max", "deep", "reason")) else "fast"

def lovart_chat_prompt(payload, history_messages=None):
    parts = []
    system_prompt = str(getattr(payload, "system_prompt", "") or "").strip()
    mem = memory_block(getattr(payload, "conversation_id", "") or "")
    if system_prompt or mem:
        block = system_prompt
        if mem:
            block = (block + "\n\n" + mem).strip() if block else mem
        parts.append(f"系统要求：\n{block}")
    history = (history_messages or [])[-MAX_HISTORY_MESSAGES:]
    for item in history:
        role = str(item.get("role") or "").strip()
        content = item.get("content")
        if role in {"user", "assistant"} and content:
            label = "用户" if role == "user" else "助手"
            parts.append(f"{label}：\n{content}")
    message = str(getattr(payload, "message", "") or "").strip()
    last = history[-1] if history else None
    # /api/chat 已把本条用户消息写进 history，末尾再拼一次会让上游把同一句话读两遍
    if not (isinstance(last, dict) and str(last.get("role") or "").strip() == "user" and str(last.get("content") or "").strip() == message):
        parts.append(f"用户：\n{message}")
    parts.append("请直接回答用户，输出纯文本。")
    return "\n\n".join(part for part in parts if part).strip()

def lovart_chat_image_refs(payload):
    refs = []
    if hasattr(payload, "images"):
        refs.extend([{"url": item} for item in (getattr(payload, "images", None) or []) if item])
    if hasattr(payload, "reference_images"):
        refs.extend([ref.dict() for ref in (getattr(payload, "reference_images", None) or []) if getattr(ref, "url", "")])
    return refs

def lovart_result_text(result):
    items = (result or {}).get("items") if isinstance(result, dict) else None
    texts = []
    for item in items or []:
        if not isinstance(item, dict):
            continue
        text = item.get("text")
        if isinstance(text, list):
            text = next((one for one in text if isinstance(one, str) and one.strip()), "")
        text = str(text or "").strip()
        if text:
            texts.append(text)
    for item in items or []:
        if not isinstance(item, dict):
            continue
        for artifact in item.get("artifacts") or []:
            if not isinstance(artifact, dict):
                continue
            if str(artifact.get("type") or "").strip().lower() != "text":
                continue
            content = artifact.get("content")
            if isinstance(content, list):
                content = next((one for one in content if isinstance(one, str) and one.strip()), "")
            content = str(content or "").strip()
            if content:
                texts.append(content)
    return "\n\n".join(dict.fromkeys(texts))

async def lovart_chat_text(payload, history_messages=None):
    provider = lovart_provider_config()
    model = str(getattr(payload, "model", "") or "").strip() or LOVART_DEFAULT_CHAT_MODELS[0]
    prompt = lovart_chat_prompt(payload, history_messages)
    mode = lovart_chat_mode(payload)
    links = []
    try:
        async with lovart_http_client(provider, httpx.Timeout(connect=20.0, read=180.0, write=180.0, pool=20.0)) as client:
            project_id = await lovart_ensure_project_id(client, provider)
            attachments = await lovart_attachment_urls(client, provider, lovart_chat_image_refs(payload))
            body = {"prompt": prompt, "project_id": project_id, "mode": mode}
            if attachments:
                body["attachments"] = attachments
            data = await lovart_request(client, provider, "POST", "/chat", body=body)
            thread_id = lovart_thread_id(data)
            if not thread_id:
                raise HTTPException(status_code=502, detail=f"Lovart 提交对话失败：接口未返回 thread_id（{json.dumps(data, ensure_ascii=False)[:300]}）")
            result = await lovart_wait_for_result(client, provider, thread_id)
            text = lovart_result_text(result)
            for remote in [*lovart_artifact_urls(result, "IMAGE"), *lovart_artifact_urls(result, "VIDEO")]:
                try:
                    local = await lovart_download_artifact(client, remote, prefix="lovart_")
                except httpx.HTTPError as exc:
                    print(f"Lovart 对话产物下载失败，已改用远程地址: {exc}")
                    local = remote
                if local:
                    links.append(f"- [{os.path.basename(local.split('?', 1)[0])}]({local})")
    except httpx.HTTPError as exc:
        raise HTTPException(status_code=502, detail=f"请求 Lovart 对话接口失败：{exc}") from exc
    if not text and not links:
        failures = lovart_failures_text(result)
        detail = f"Lovart 没有返回文字回复：{failures}" if failures else "Lovart 没有返回文字回复，Agent 可能只执行了工具调用。"
        raise HTTPException(status_code=502, detail=detail)
    if links:
        header = f"{text}\n\n产物：" if text else "Lovart 已完成本次任务，产物："
        text = f"{header}\n" + "\n".join(links)
    raw = {
        "task_id": thread_id,
        "thread_id": thread_id,
        "project_id": project_id,
        "provider": "lovart",
        "model": model,
        "mode": mode,
        "final_status": result.get("final_status"),
        "auto_confirmed": result.get("auto_confirmed"),
        "artifacts": links,
        "failures": lovart_failures_text(result),
    }
    return text, raw

def lovart_prompt_with_requirements(prompt, requirements):
    text = str(prompt or "")
    items = [str(item).strip() for item in (requirements or []) if str(item or "").strip()]
    if not items:
        return text
    return f"{text}\n\n要求：{'；'.join(items)}"

def lovart_effective_image_size(model, size):
    """Lovart 的 OpenAPI 没有尺寸参数，尺寸只作为提示词文本下发；只有协议声明 enum 的通道才吸附。"""
    text = str(size or "").strip()
    policy = nova_protocols.size_policy_for(lovart_provider_config(), model)
    if policy.get("mode") != "enum":
        return text
    width, height = parse_size_pair(text)
    if not width or not height:
        return text
    max_edge = int(policy.get("maxEdge") or 0)
    max_pixels = int(policy.get("maxPixels") or 0)
    options = []
    for candidate in policy.get("options") or []:
        cand_width, cand_height = parse_size_pair(candidate)
        if not cand_width or not cand_height:
            continue
        if max_edge and max(cand_width, cand_height) > max_edge:
            continue
        if max_pixels and cand_width * cand_height > max_pixels:
            continue
        options.append((str(candidate), cand_width, cand_height))
    if not options:
        return text
    target_ratio = width / height
    target_area = width * height
    return min(options, key=lambda item: (abs(math.log(target_ratio / (item[1] / item[2]))), abs(item[1] * item[2] - target_area)))[0]

def lovart_size_tier(size):
    width, height = parse_size_pair(size)
    if not width or not height:
        return ""
    edge = max(width, height)
    if edge >= 2160:
        return "4K"
    if edge >= 1440:
        return "2K"
    return "1K"

def lovart_image_requirements(size, requested_size=""):
    size = str(size or "").strip()
    if not size or size == "1024x1024":
        return []
    tier = lovart_size_tier(size)
    if not tier:
        return []
    return [f"请按 {size} 输出（{tier} 档位）；若平台只能按自身档位出图，请保持该比例"]

def lovart_video_requirements(payload):
    items = []
    try:
        duration = int(getattr(payload, "duration", 0) or 0)
    except (TypeError, ValueError):
        duration = 0
    if duration > 0:
        items.append(f"时长 {duration} 秒")
    aspect_ratio = str(getattr(payload, "aspect_ratio", "") or "").strip()
    if aspect_ratio:
        items.append(f"画面比例 {aspect_ratio}")
    resolution = str(getattr(payload, "resolution", "") or "").strip()
    if resolution:
        items.append(f"分辨率 {resolution}")
    return items

async def generate_lovart_provider_image(prompt, size, model, reference_images=None, provider=None):
    provider = provider or lovart_provider_config()
    model = str(model or "").strip() or LOVART_DEFAULT_IMAGE_MODELS[0]
    effective_size = lovart_effective_image_size(model, size)
    prompt = lovart_prompt_with_requirements(prompt, lovart_image_requirements(effective_size, size))
    timeout = httpx.Timeout(connect=20.0, read=180.0, write=180.0, pool=20.0)
    async with lovart_http_client(provider, timeout) as client:
        local_urls, raw = await lovart_run_generation(client, provider, prompt, model, "IMAGE", reference_images)
    return {"type": "url", "value": local_urls[0]}, raw

async def generate_lovart_video(payload, provider=None):
    provider = provider or lovart_provider_config()
    model = str(getattr(payload, "model", "") or "").strip() or LOVART_DEFAULT_VIDEO_MODELS[0]
    refs = [ref.dict() for ref in (getattr(payload, "images", None) or []) if getattr(ref, "url", "")]
    refs = image_references(refs)
    prompt = lovart_prompt_with_requirements(getattr(payload, "prompt", ""), lovart_video_requirements(payload))
    timeout = httpx.Timeout(connect=20.0, read=180.0, write=180.0, pool=20.0)
    async with lovart_http_client(provider, timeout) as client:
        local_urls, raw = await lovart_run_generation(client, provider, prompt, model, "VIDEO", refs)
    return {**{"videos": local_urls, "task_id": raw.get("thread_id"), "raw": raw}, **build_canvas_meta(local_urls, payload, "video")}

async def generate_volcengine_provider_image(prompt, size, model, reference_images=None, provider=None):
    endpoint = volcengine_endpoint_url(provider)
    size = normalize_volcengine_size(size, model)
    body = {
        "model": model,
        "prompt": prompt,
        "size": size,
        "response_format": "url",
    }
    images = [volcengine_image_payload(ref) for ref in (reference_images or [])[:ONLINE_IMAGE_REFERENCE_MAX]]
    images = [value for value in images if value]
    if images:
        body["image"] = images
    async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env(provider), timeout=httpx.Timeout(connect=20.0, read=1800.0, write=120.0, pool=20.0)) as client:
        response = await client.post(endpoint, headers=api_headers(provider=provider), json=body)
        response.raise_for_status()
        raw = response.json()
        return extract_image(raw), raw

def runninghub_api_headers(provider):
    api_key = str((provider or {}).get("api_key") or "").strip() or runninghub_api_key(provider)
    if not api_key:
        raise HTTPException(status_code=400, detail="未配置 RunningHub API Key，请在 API 设置中填写。")
    return {"Authorization": bearer_auth_value(api_key), "Accept": "application/json", "Content-Type": "application/json"}

def runninghub_json_headers(provider):
    return runninghub_api_headers(provider)

def runninghub_provider():
    return get_api_provider_exact("runninghub")

def runninghub_api_key(provider=None, use_wallet=False, prefer_wallet=False):
    provider = provider or runninghub_provider()
    free_key = str((provider or {}).get("api_key") or "").strip() or os.getenv(provider_key_env(provider["id"]), "")
    wallet_key = str((provider or {}).get("wallet_api_key") or "").strip() or os.getenv(runninghub_wallet_key_env(), "")
    api_key = wallet_key if (use_wallet or prefer_wallet) and wallet_key else free_key
    if not api_key:
        raise HTTPException(status_code=400, detail="未配置 RunningHub API Key，请在 RH 设置中填写。")
    return api_key

def runninghub_app_headers(json_body=True, use_wallet=False):
    headers = {"Host": "www.runninghub.cn"}
    provider = runninghub_provider()
    if provider:
        free_key = os.getenv(provider_key_env(provider["id"]), "")
        wallet_key = os.getenv(runninghub_wallet_key_env(), "")
        api_key = wallet_key if use_wallet and wallet_key else free_key
        if api_key:
            headers["Authorization"] = bearer_auth_value(api_key)
    if json_body:
        headers["Content-Type"] = "application/json"
    return headers

def runninghub_local_asset_path(url):
    text = str(url or "").strip()
    if not text:
        return None
    if text.startswith("/assets/input/") or text.startswith("/input/"):
        clean = urllib.parse.unquote(text.split("?", 1)[0]).replace("\\", "/")
        rel = clean[len("/assets/input/"):] if clean.startswith("/assets/input/") else clean[len("/input/"):]
        root = OUTPUT_INPUT_DIR
    elif text.startswith("/assets/output/"):
        clean = urllib.parse.unquote(text.split("?", 1)[0]).replace("\\", "/")
        rel = clean[len("/assets/output/"):]
        root = OUTPUT_OUTPUT_DIR
    elif text.startswith("/output/") or text.startswith("/assets/"):
        return output_file_from_url(text)
    else:
        return None
    rel = rel.lstrip("/")
    if not rel:
        return None
    path = os.path.abspath(os.path.join(root, rel))
    root_abs = os.path.abspath(root)
    if os.path.commonpath([root_abs, path]) != root_abs or not os.path.exists(path):
        return None
    return path

def runninghub_output_ext(remote, content_type=""):
    tail = str(remote or "").split("?", 1)[0].split("#", 1)[0]
    ext = os.path.splitext(tail)[1].lower().strip(".")
    allowed = {"png","jpg","jpeg","webp","gif","bmp","mp4","webm","mov","m4v","mkv","mp3","wav","ogg","m4a","flac","aac"}
    if ext in allowed:
        return ext
    ct = str(content_type or "").lower()
    if "mp4" in ct:
        return "mp4"
    if "webm" in ct:
        return "webm"
    if "quicktime" in ct:
        return "mov"
    if "mpeg" in ct:
        return "mp3"
    if "wav" in ct:
        return "wav"
    if "ogg" in ct:
        return "ogg"
    if "webp" in ct:
        return "webp"
    if "jpeg" in ct:
        return "jpg"
    return "png"

def rewrite_runninghub_file_url(url):
    text = str(url or "")
    if not text:
        return text
    try:
        parsed = urllib.parse.urlsplit(text)
    except Exception:
        return text
    target = RUNNINGHUB_FILE_HOST_REWRITES.get((parsed.netloc or "").lower())
    return parsed._replace(netloc=target).geturl() if target else text

def runninghub_extract_outputs(data):
    arr = []
    if isinstance(data, list):
        arr = data
    elif isinstance(data, dict):
        for key in ("outputs", "results", "files", "data"):
            value = data.get(key)
            if isinstance(value, list):
                arr = value
                break
        if not arr and (data.get("fileUrl") or data.get("url")):
            arr = [data]
    outputs = []
    for item in arr:
        if isinstance(item, str):
            outputs.append(rewrite_runninghub_file_url(item))
        elif isinstance(item, dict):
            url = item.get("fileUrl") or item.get("file_url") or item.get("url") or item.get("downloadUrl") or item.get("download_url")
            if isinstance(url, list):
                outputs.extend([rewrite_runninghub_file_url(u) for u in url if u])
            elif url:
                outputs.append(rewrite_runninghub_file_url(url))
    return outputs

async def runninghub_store_remote_output(client, remote):
    remote = rewrite_runninghub_file_url(remote)
    if not str(remote or "").startswith(("http://", "https://")):
        return remote
    response = await client.get(remote, follow_redirects=True)
    if not response.is_success:
        return remote
    ext = runninghub_output_ext(remote, response.headers.get("content-type", ""))
    filename = f"rh_{uuid.uuid4().hex[:12]}.{ext}"
    path = output_path_for(filename, "output")
    with open(path, "wb") as f:
        f.write(response.content)
    return output_url_for(filename, "output")

def runninghub_fail_reason(raw):
    data = raw.get("data") if isinstance(raw, dict) else None
    values = []
    if isinstance(data, dict):
        values.extend([data.get("failedReason"), data.get("failReason"), data.get("message"), data.get("error")])
    if isinstance(raw, dict):
        values.extend([raw.get("msg"), raw.get("message"), raw.get("error")])
    for value in values:
        if not value:
            continue
        if isinstance(value, str):
            return value
        if isinstance(value, dict):
            return value.get("exception_message") or value.get("message") or json.dumps(value, ensure_ascii=False)
        return str(value)
    return ""

def runninghub_infer_workflow_field_type(field_name, field_value):
    key = f"{field_name or ''} {field_value or ''}".lower()
    if re.search(r"\b(image|img|mask|photo|picture)\b", key) or re.search(r"\.(png|jpe?g|webp|gif|bmp)(\?|$)", key, re.I):
        return "IMAGE"
    if re.search(r"\b(video|movie|mp4)\b", key) or re.search(r"\.(mp4|webm|mov|m4v|mkv)(\?|$)", key, re.I):
        return "VIDEO"
    if re.search(r"\b(audio|sound|music|voice)\b", key) or re.search(r"\.(mp3|wav|ogg|m4a|flac|aac)(\?|$)", key, re.I):
        return "AUDIO"
    text = str(field_value or "").strip()
    if text.lower() in {"true", "false"}:
        return "BOOLEAN"
    try:
        if text:
            float(text)
            return "NUMBER"
    except Exception:
        pass
    return "TEXT"

def runninghub_is_workflow_link_value(value):
    return (
        isinstance(value, list)
        and len(value) == 2
        and isinstance(value[0], str)
        and isinstance(value[1], int)
    )

def runninghub_workflow_node_info_list(workflow_json):
    result = []
    if not isinstance(workflow_json, dict):
        return result
    for node_id, node_content in workflow_json.items():
        inputs = node_content.get("inputs") if isinstance(node_content, dict) else None
        if not isinstance(inputs, dict):
            continue
        for field_name, raw_value in inputs.items():
            if runninghub_is_workflow_link_value(raw_value):
                continue
            if isinstance(raw_value, (dict, list)):
                field_value = json.dumps(raw_value, ensure_ascii=False)
            elif raw_value is None:
                field_value = ""
            else:
                field_value = str(raw_value)
            result.append({
                "nodeId": str(node_id),
                "fieldName": str(field_name),
                "fieldValue": field_value,
                "fieldType": runninghub_infer_workflow_field_type(field_name, field_value),
                "source": "workflow",
            })
    return result

def runninghub_task_endpoint(provider, model):
    raw_model_path = str(model or "").strip()
    model_path = raw_model_path.strip("/")
    if not model_path:
        model_path = RUNNINGHUB_DEFAULT_IMAGE_MODELS[0]
    if raw_model_path.startswith("/openapi/"):
        return runninghub_endpoint_url(provider, raw_model_path)
    if model_path.startswith("openapi/"):
        return runninghub_endpoint_url(provider, f"/{model_path}")
    return runninghub_openapi_url(provider, model_path)

def runninghub_endpoint_alias_for_model(model):
    model_id = str(model or "").strip().strip("/")
    if not model_id:
        return ""
    direct = RUNNINGHUB_MODEL_ENDPOINT_ALIASES.get(model_id)
    if direct:
        return direct
    lowered = model_id.lower()
    if lowered.startswith("gpt-image-2.0/") or lowered.startswith("gpt-image-2/"):
        if "/text-to-image-" in lowered or lowered.endswith("/text-to-image"):
            return "rhart-image-g-2/text-to-image"
        if "/edit-" in lowered or lowered.endswith("/edit"):
            return "rhart-image-g-2/image-to-image"
        if "/image-to-image-" in lowered or lowered.endswith("/image-to-image"):
            return "rhart-image-g-2/image-to-image"
    if lowered.startswith("nano-banana/"):
        if "/text-to-image-" in lowered or lowered.endswith("/text-to-image"):
            return "rhart-image-v1/text-to-image"
        if "/edit-" in lowered or lowered.endswith("/edit"):
            return "rhart-image-v1/edit"
    return ""

def runninghub_registry_fallback():
    image = [
        {"name_en": "gpt-image-2.0/text-to-image-channel-low-price", "endpoint": "rhart-image-g-2/text-to-image", "output_type": "image"},
        {"name_en": "gpt-image-2.0/edit-channel-low-price", "endpoint": "rhart-image-g-2/image-to-image", "output_type": "image"},
        {"name_en": "gpt-image-2/text-to-image-official-stable", "endpoint": "rhart-image-g-2-official/text-to-image", "output_type": "image"},
        {"name_en": "gpt-image-2/image-to-image-official-stable", "endpoint": "rhart-image-g-2-official/image-to-image", "output_type": "image"},
        {"name_en": "nano-banana/text-to-image-official-stable", "endpoint": "rhart-image-v1-official/text-to-image", "output_type": "image"},
        {"name_en": "nano-banana/edit-official-stable", "endpoint": "rhart-image-v1-official/edit", "output_type": "image"},
    ]
    video = [
        {"name_en": "google/veo3.1-fast/text-to-video-channel-low-price", "endpoint": "rhart-video-v3.1-fast/text-to-video", "output_type": "video"},
        {"name_en": "sora-2/text-to-video-official-stable", "endpoint": "rhart-video-s-official/text-to-video", "output_type": "video"},
        {"name_en": "seedance-2.0-global/text-to-video", "endpoint": "bytedance/seedance-2.0-global/text-to-video", "output_type": "video"},
        {"name_en": "seedance-2.0-global/image-to-video", "endpoint": "bytedance/seedance-2.0-global/image-to-video", "output_type": "video"},
    ]
    return image + video

def runninghub_registry_items_from_raw(raw):
    candidates = [raw]
    if isinstance(raw, dict):
        candidates.extend([
            raw.get("data"),
            raw.get("models"),
            raw.get("list"),
            raw.get("items"),
            raw.get("records"),
            raw.get("result"),
        ])
    for candidate in candidates:
        if isinstance(candidate, list):
            return [item for item in candidate if isinstance(item, dict)]
        if isinstance(candidate, dict):
            nested = (
                candidate.get("models")
                or candidate.get("list")
                or candidate.get("items")
                or candidate.get("records")
                or candidate.get("data")
            )
            if isinstance(nested, list):
                return [item for item in nested if isinstance(item, dict)]
    return []

def runninghub_registry_model_from_id(model_id, output_type=""):
    model_id = str(model_id or "").strip()
    if not model_id:
        return None
    output_type = str(output_type or "").strip().lower() or classify_upstream_model(model_id)
    return {"name_en": model_id, "endpoint": model_id, "output_type": output_type}

async def fetch_runninghub_llm_models(provider=None):
    headers = runninghub_api_headers(provider)
    errors = []
    async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=20, follow_redirects=True) as client:
        for url in RUNNINGHUB_LLM_MODELS_URLS:
            try:
                resp = await client.get(url, headers=headers)
                if resp.status_code >= 400 or looks_like_html_response(resp.text):
                    errors.append(f"{url}: HTTP {resp.status_code} {resp.text[:180]}")
                    continue
                raw = resp.json() if resp.text else {}
                grouped, ids, _meta = parse_upstream_models(raw, "openai")
                if ids:
                    return [runninghub_registry_model_from_id(mid, "chat") for mid in ids], {"source": url, "count": len(ids)}
                errors.append(f"{url}: empty")
            except Exception as exc:
                errors.append(f"{url}: {str(exc)[:180]}")
    return [], {"source": "", "count": 0, "errors": errors[-3:]}

async def fetch_runninghub_model_registry(provider=None, include_fallback=True, include_meta=False):
    urls = [
        ("openapi", runninghub_openapi_url(provider, "models")),
        ("github", RUNNINGHUB_MODEL_REGISTRY_URL),
    ]
    if os.path.exists(STATIC_RUNNINGHUB_MODEL_REGISTRY_FILE):
        urls.append(("local", STATIC_RUNNINGHUB_MODEL_REGISTRY_FILE))
    headers = runninghub_api_headers(provider)
    errors = []
    source = ""
    items = []
    async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=30, follow_redirects=True) as client:
        for source_name, url in urls:
            try:
                if source_name == "local":
                    with open(url, "r", encoding="utf-8") as f:
                        raw = json.load(f)
                else:
                    req_headers = headers if source_name == "openapi" else {"Accept": "application/json"}
                    resp = await client.get(url, headers=req_headers)
                    if resp.status_code >= 400 or looks_like_html_response(resp.text):
                        errors.append(f"{source_name}: HTTP {resp.status_code} {resp.text[:180]}")
                        continue
                    raw = resp.json() if resp.text else []
                parsed = runninghub_registry_items_from_raw(raw)
                if parsed:
                    items = parsed
                    source = source_name
                    break
                errors.append(f"{source_name}: empty")
            except Exception as exc:
                errors.append(f"{source_name}: {str(exc)[:180]}")
                continue
    llm_items, llm_meta = await fetch_runninghub_llm_models(provider)
    combined = [*items]
    seen = {runninghub_model_id(item) for item in combined if runninghub_model_id(item)}
    for item in llm_items:
        mid = runninghub_model_id(item)
        if mid and mid not in seen:
            combined.append(item)
            seen.add(mid)
    if combined:
        meta = {
            "source": source or "llm",
            "openapi_count": len(items),
            "llm_count": len(llm_items),
            "llm_source": llm_meta.get("source") or "",
            "errors": [*errors[-3:], *((llm_meta.get("errors") or [])[-3:])],
        }
        return (combined, meta) if include_meta else combined
    if include_fallback:
        fallback = runninghub_registry_fallback()
        meta = {
            "source": "fallback",
            "openapi_count": 0,
            "llm_count": 0,
            "llm_source": "",
            "errors": [*errors[-3:], *((llm_meta.get("errors") or [])[-3:])],
        }
        return (fallback, meta) if include_meta else fallback
    raise HTTPException(status_code=502, detail=f"拉取 RunningHub 模型注册表失败：{'; '.join(errors[-4:]) or 'unknown error'}")

def runninghub_model_id(item):
    if not isinstance(item, dict):
        return ""
    return str(item.get("name_en") or item.get("id") or item.get("name") or item.get("endpoint") or "").strip()

def runninghub_registry_payload(items):
    grouped = {"image": [], "chat": RUNNINGHUB_FALLBACK_CHAT_MODELS[:], "video": []}
    all_ids = []
    for item in items or []:
        mid = runninghub_model_id(item)
        if not mid:
            continue
        output_type = str(item.get("output_type") or item.get("outputType") or "").strip().lower()
        if output_type in ("image", "video"):
            grouped[output_type].append(mid)
            all_ids.append(mid)
    for model in RUNNINGHUB_DEFAULT_IMAGE_MODELS:
        if model not in grouped["image"]:
            grouped["image"].append(model)
            all_ids.append(model)
    for model in RUNNINGHUB_DEFAULT_VIDEO_MODELS:
        if model not in grouped["video"]:
            grouped["video"].append(model)
            all_ids.append(model)
    for model in RUNNINGHUB_FALLBACK_CHAT_MODELS:
        if model not in all_ids:
            all_ids.append(model)
    for key in grouped:
        grouped[key] = sorted(set(grouped[key]))
    return {
        "total": len(set(all_ids)),
        "image_models": grouped["image"],
        "chat_models": grouped["chat"],
        "video_models": grouped["video"],
        "all": sorted(set(all_ids)),
        "protocol": "runninghub",
    }

async def runninghub_models_payload(provider=None):
    registry, meta = await fetch_runninghub_model_registry(provider, include_fallback=True, include_meta=True)
    payload = runninghub_registry_payload(registry)
    payload["raw"] = {"registry_count": len(registry), **meta}
    if meta.get("source") == "fallback":
        payload["message"] = "RunningHub 模型接口未返回完整列表，当前显示内置兜底模型。"
    else:
        payload["message"] = f"RunningHub 模型列表来自 {meta.get('source')}"
    return payload

async def runninghub_model_definition(provider, model):
    requested = str(model or "").strip().strip("/")
    registry = await fetch_runninghub_model_registry(provider, include_fallback=True)
    for item in registry:
        mid = runninghub_model_id(item)
        endpoint = str(item.get("endpoint") or "").strip().strip("/")
        if requested and requested in {mid, endpoint, f"/openapi/v2/{endpoint}", f"openapi/v2/{endpoint}"}:
            if endpoint:
                return item
            alias = runninghub_endpoint_alias_for_model(mid or requested)
            if alias:
                patched = dict(item)
                patched["endpoint"] = alias
                return patched
            return item
    endpoint = requested
    if endpoint.startswith("/openapi/v2/"):
        endpoint = endpoint[len("/openapi/v2/"):]
    elif endpoint.startswith("openapi/v2/"):
        endpoint = endpoint[len("openapi/v2/"):]
    endpoint = runninghub_endpoint_alias_for_model(requested) or endpoint
    return {"name_en": requested, "endpoint": endpoint or RUNNINGHUB_DEFAULT_IMAGE_MODELS[0], "output_type": classify_upstream_model(requested), "params": []}

def runninghub_schema_options(field):
    values = []
    for item in (field or {}).get("options") or []:
        if isinstance(item, dict):
            value = item.get("value")
        else:
            value = item
        if value is not None and str(value) != "":
            values.append(str(value))
    return values

def runninghub_schema_value(field, preferred=None):
    preferred = "" if preferred is None else str(preferred).strip()
    options = runninghub_schema_options(field)
    if preferred and (not options or preferred in options):
        return preferred
    default = (field or {}).get("defaultValue")
    if default is not None and str(default) != "":
        return default
    return options[0] if options else preferred

def runninghub_schema_field(params, *keys):
    wanted = {str(k).lower() for k in keys if k}
    for field in params or []:
        if not isinstance(field, dict):
            continue
        names = {str(field.get("fieldKey") or "").lower(), str(field.get("label") or "").lower()}
        if names & wanted:
            return field
    return None

def runninghub_aspect_from_size(size, fallback="1:1"):
    width, height = parse_size_pair(size)
    if width and height:
        divisor = math.gcd(width, height) or 1
        return f"{width // divisor}:{height // divisor}"
    raw = str(size or "").strip().lower()
    if re.fullmatch(r"(auto|\d+\s*:\s*\d+)", raw):
        return raw.replace(" ", "")
    return fallback

# RunningHub 官方 workflow（seedream-v5-pro/text-to-image）的 resolution 枚举只有 1k/2k；
# 不能再按长边推出官方没有的 4k。工作流 schema 明确列出枚举时以 schema 为准，未声明时只到 2k。
RUNNINGHUB_IMAGE_RESOLUTION_LEVELS = ("1k", "2k")
RUNNINGHUB_RESOLUTION_ORDER = ("1k", "2k", "4k")
RUNNINGHUB_VIDEO_RESOLUTIONS = {"480p", "720p", "1080p", "native1080p"}

def runninghub_clamp_resolution(level, options=None):
    value = str(level or "").strip().lower()
    allowed = [str(item).strip().lower() for item in (options or []) if str(item).strip()]
    if not allowed:
        allowed = list(RUNNINGHUB_IMAGE_RESOLUTION_LEVELS)
    if value in allowed:
        return value
    if value in RUNNINGHUB_RESOLUTION_ORDER:
        index = RUNNINGHUB_RESOLUTION_ORDER.index(value)
        lower = [item for item in allowed if item in RUNNINGHUB_RESOLUTION_ORDER and RUNNINGHUB_RESOLUTION_ORDER.index(item) < index]
        if lower:
            return lower[-1]
    return allowed[0]

def runninghub_resolution_from_size(size, fallback="2k", options=None):
    width, height = parse_size_pair(size)
    if width and height:
        long_edge = max(width, height)
        if long_edge >= 3200:
            level = "4k"
        elif long_edge >= 1400:
            level = "2k"
        else:
            level = "1k"
    else:
        raw = str(size or "").strip().lower()
        level = raw if raw in {"1k", "2k", "4k"} or raw in RUNNINGHUB_VIDEO_RESOLUTIONS else str(fallback or "")
    if level in RUNNINGHUB_VIDEO_RESOLUTIONS:
        return level
    if not level:
        return ""
    return runninghub_clamp_resolution(level, options)

def runninghub_size_for_aspect(aspect_ratio, fallback="1280x720"):
    ratio = str(aspect_ratio or "").strip()
    return {
        "9:16": "720x1280",
        "16:9": "1280x720",
        "1:1": "1024x1024",
        "4:3": "1024x768",
        "3:4": "768x1024",
    }.get(ratio, fallback)

def runninghub_apply_schema_defaults(body, params):
    for field in params or []:
        if not isinstance(field, dict):
            continue
        key = str(field.get("fieldKey") or "").strip()
        if not key or key in body:
            continue
        default = field.get("defaultValue")
        options = runninghub_schema_options(field)
        if default is None or default == "":
            if field.get("required") is True and options:
                default = options[0]
            else:
                continue
        ftype = str(field.get("type") or "").upper()
        if ftype == "BOOLEAN":
            body[key] = bool(default) if not isinstance(default, str) else default.lower() == "true"
        elif ftype in {"INT", "INTEGER"}:
            try:
                body[key] = int(default)
            except Exception:
                body[key] = default
        elif ftype == "FLOAT":
            try:
                body[key] = float(default)
            except Exception:
                body[key] = default
        else:
            body[key] = default
    return body

def runninghub_query_status(raw):
    if not isinstance(raw, dict):
        return ""
    values = [
        raw.get("status"),
        raw.get("state"),
        raw.get("taskStatus"),
        raw.get("task_status"),
    ]
    data = raw.get("data")
    if isinstance(data, dict):
        values.extend([data.get("status"), data.get("state"), data.get("taskStatus"), data.get("task_status")])
    for value in values:
        if value is not None:
            return str(value).lower()
    return ""

def runninghub_extract_task_id(raw):
    if not isinstance(raw, dict):
        return ""
    for key in ("taskId", "task_id", "id"):
        if raw.get(key):
            return str(raw[key])
    data = raw.get("data")
    if isinstance(data, dict):
        for key in ("taskId", "task_id", "id"):
            if data.get(key):
                return str(data[key])
    return ""

def runninghub_extract_image(raw):
    if not isinstance(raw, dict):
        raise HTTPException(status_code=502, detail="RunningHub 返回格式不是 JSON 对象")
    containers = [raw]
    data = raw.get("data")
    if isinstance(data, dict):
        containers.append(data)
    for container in containers:
        results = container.get("results") or container.get("result") or container.get("outputs") or container.get("output")
        if isinstance(results, dict):
            results = [results]
        if isinstance(results, list):
            for item in results:
                if isinstance(item, str) and item.startswith(("http://", "https://")):
                    return {"type": "url", "value": rewrite_runninghub_file_url(item)}
                if not isinstance(item, dict):
                    continue
                if item.get("type") == "url" and item.get("value"):
                    return {"type": "url", "value": rewrite_runninghub_file_url(item["value"])}
                if item.get("type") == "b64" and item.get("value"):
                    return {"type": "b64", "value": item["value"], "mime_type": item.get("mime_type") or "image/png"}
                url = item.get("url") or item.get("fileUrl") or item.get("file_url") or item.get("download_url") or item.get("imageUrl") or item.get("image_url")
                if isinstance(url, list) and url:
                    url = url[0]
                if isinstance(url, str) and url:
                    return {"type": "url", "value": rewrite_runninghub_file_url(url)}
    image = extract_image(raw)
    if image.get("type") == "url":
        image["value"] = rewrite_runninghub_file_url(image.get("value"))
    return image

async def runninghub_upload_reference(client, provider, ref):
    path = output_file_from_url(ref.get("url", ""))
    if not path:
        value = ref.get("url", "")
        return value if str(value).startswith(("http://", "https://")) else ""
    upload_url = runninghub_openapi_url(provider, "media/upload/binary")
    headers = {"Authorization": bearer_auth_value(runninghub_api_key(provider)), "Accept": "application/json"}
    with open(path, "rb") as fh:
        files = {"file": (os.path.basename(path), fh, content_type_for_path(path))}
        response = await client.post(upload_url, headers=headers, files=files, timeout=120)
    response.raise_for_status()
    raw = response.json()
    data = raw.get("data") if isinstance(raw, dict) else None
    candidates = [raw, data] if isinstance(data, dict) else [raw]
    for item in candidates:
        if not isinstance(item, dict):
            continue
        value = item.get("download_url") or item.get("downloadUrl") or item.get("url") or item.get("fileUrl") or item.get("file_url")
        if value:
            return str(value)
    raise HTTPException(status_code=502, detail=f"RunningHub 上传图片未返回 download_url：{raw}")

async def wait_for_runninghub_image_task(client, provider, task_id):
    query_url = runninghub_openapi_url(provider, "query")
    deadline = time.monotonic() + 1800
    last_payload = None
    while time.monotonic() < deadline:
        await asyncio.sleep(2)
        response = await client.post(query_url, headers=runninghub_api_headers(provider), json={"taskId": task_id})
        response.raise_for_status()
        raw = response.json()
        last_payload = raw
        status = runninghub_query_status(raw)
        if status in {"success", "succeeded", "completed", "complete", "finished", "finish", "done", "3"}:
            return raw
        if status in {"failed", "fail", "error", "canceled", "cancelled", "4"}:
            raise HTTPException(status_code=502, detail=f"RunningHub 任务失败：{raw}")
        try:
            return {"data": {"results": [runninghub_extract_image(raw)]}}
        except HTTPException:
            pass
    raise HTTPException(status_code=504, detail=f"RunningHub 生图任务超时：{last_payload}")

RUNNINGHUB_ENTRY_MODEL_RE = re.compile(r"^(app|workflow):(.+)$")

def rh_field_kind(field):
    field = field or {}
    t = str(field.get("fieldType") or "").strip().upper()
    if t == "IMAGE":
        return "image"
    if t == "VIDEO":
        return "video"
    if t == "AUDIO":
        return "audio"
    if t == "SLIDER":
        return "slider"
    if t in ("NUMBER", "FLOAT", "INTEGER", "INT"):
        return "number"
    if t in ("BOOLEAN", "BOOL"):
        return "boolean"
    key = f"{field.get('fieldName') or ''} {field.get('fieldValue') or ''}".lower()
    if re.search(r"\b(image|img|mask|photo|picture)\b", key) or re.search(r"\.(png|jpe?g|webp|gif|bmp)(\?|$)", key, re.I):
        return "image"
    if re.search(r"\b(video|movie|mp4)\b", key) or re.search(r"\.(mp4|webm|mov|m4v|mkv)(\?|$)", key, re.I):
        return "video"
    if re.search(r"\b(audio|sound|music|voice)\b", key) or re.search(r"\.(mp3|wav|ogg|m4a|flac|aac)(\?|$)", key, re.I):
        return "audio"
    return "text"

def rh_field_role(field):
    kind = rh_field_kind(field)
    if kind in ("image", "video", "audio", "number", "slider", "boolean"):
        return kind
    field = field or {}
    text = f"{field.get('fieldName') or ''} {field.get('label') or ''} {field.get('group') or ''}".lower()
    if re.search(r"prompt|positive|negative|text|caption|description|关键词|提示词|正向|负向", text):
        return "prompt"
    return "text"

def _rh_natural_cmp(x, y):
    if x == y:
        return 0
    if x.isdigit() and y.isdigit():
        ix, iy = int(x), int(y)
        return (ix > iy) - (ix < iy)
    return (x > y) - (x < y)

def _rh_field_cmp(a, b):
    ak, bk = rh_field_kind(a), rh_field_kind(b)
    if ak == "image" and bk == "image":
        try:
            ao = int(a.get("imageOrder") or 0) or 9999
        except Exception:
            ao = 9999
        try:
            bo = int(b.get("imageOrder") or 0) or 9999
        except Exception:
            bo = 9999
        if ao != bo:
            return ao - bo
    if ak == "image" and bk != "image":
        return -1
    if ak != "image" and bk == "image":
        return 1
    node_cmp = _rh_natural_cmp(str(a.get("nodeId") or ""), str(b.get("nodeId") or ""))
    if node_cmp != 0:
        return node_cmp
    fa, fb = str(a.get("fieldName") or ""), str(b.get("fieldName") or "")
    return (fa > fb) - (fa < fb)

def rh_sort_fields(fields):
    return sorted(list(fields or []), key=functools.cmp_to_key(_rh_field_cmp))

def rh_field_indexes(fields):
    counters = {"image": 0, "video": 0, "audio": 0}
    mapping = {}
    for field in rh_sort_fields(fields):
        kind = rh_field_kind(field)
        if kind in counters:
            mapping[(str(field.get("nodeId") or ""), str(field.get("fieldName") or ""))] = counters[kind]
            counters[kind] += 1
    return mapping

def rh_default_value(field):
    value = (field or {}).get("fieldValue")
    if isinstance(value, list):
        value = value[0] if value else ""
    if value is None or isinstance(value, dict):
        return ""
    return str(value)

SEED_UINT32_MAX = 4294967295

def rh_is_seed_like_name(*parts) -> bool:
    text = " ".join(str(part or "") for part in parts).lower()
    return any(key in text for key in ("seed", "noise", "随机", "种子", "噪"))

def normalize_seed_uint32(value):
    try:
        if isinstance(value, bool):
            return value
        raw = str(value).strip()
        if not raw:
            return value
        num = int(float(raw))
    except Exception:
        return value
    if 0 <= num <= SEED_UINT32_MAX:
        return value
    safe = ((abs(num) - 1) % SEED_UINT32_MAX) + 1
    return str(safe) if isinstance(value, str) else safe

def sanitize_seed_like_workflow_values(value, parent_key=""):
    if isinstance(value, dict):
        result = {}
        for key, item in value.items():
            if rh_is_seed_like_name(key) and not isinstance(item, (dict, list)):
                result[key] = normalize_seed_uint32(item)
            else:
                result[key] = sanitize_seed_like_workflow_values(item, key)
        return result
    if isinstance(value, list):
        return [sanitize_seed_like_workflow_values(item, parent_key) for item in value]
    if rh_is_seed_like_name(parent_key):
        return normalize_seed_uint32(value)
    return value

def sanitize_runninghub_node_info_list(items):
    result = []
    for item in items or []:
        if not isinstance(item, dict):
            continue
        clean = dict(item)
        if rh_is_seed_like_name(clean.get("fieldName"), clean.get("label"), clean.get("note")):
            clean["fieldValue"] = normalize_seed_uint32(clean.get("fieldValue"))
        result.append(clean)
    return result

def rh_random_field_value(field):
    def _num(raw, default):
        try:
            s = str(raw).strip()
            if s == "" or s.lower() == "none":
                return default
            return float(s)
        except Exception:
            return default
    looks_seed = rh_is_seed_like_name((field or {}).get("fieldName"), (field or {}).get("label"), (field or {}).get("note"))
    lo = _num((field or {}).get("min"), 0.0)
    hi = _num((field or {}).get("max"), float(SEED_UINT32_MAX) if looks_seed else 999999.0)
    if looks_seed:
        hi = min(hi, float(SEED_UINT32_MAX))
        lo = max(0.0, min(lo, hi))
    if hi < lo:
        lo, hi = hi, lo
    step = _num((field or {}).get("step"), 1.0)
    value = random.uniform(lo, hi)
    if step and step > 0:
        value = lo + round((value - lo) / step) * step
    if float(step).is_integer() and float(lo).is_integer() and float(hi).is_integer():
        return str(int(round(value)))
    return str(value)

def runninghub_entry_config_from_model(provider, model):
    """解析 model=app:ID / workflow:ID，返回 {kind,id,fields,optionalImageMode,workflowJson} 或 None。"""
    text = str(model or "").strip()
    match = RUNNINGHUB_ENTRY_MODEL_RE.match(text)
    if not match:
        return None
    kind = match.group(1)
    entry_id = match.group(2).strip()
    if not entry_id:
        return None
    if kind == "workflow":
        key = runninghub_workflow_store_key(entry_id)
        with RUNNINGHUB_WORKFLOW_LOCK:
            store = load_runninghub_workflow_store()
        cfg = runninghub_select_workflow_config(store.get(key), runninghub_provider_workflow_config(key), key)
        if not isinstance(cfg, dict):
            # 退回到 provider 列表中的内联条目
            entry = next(
                (e for e in (provider.get("rh_workflows") or []) if runninghub_entry_id(e, "workflow") == entry_id),
                None,
            )
            if not entry:
                return None
            cfg = {
                "fields": entry.get("fields") or [],
                "optionalImageMode": entry.get("optionalImageMode") or "prune-workflow",
                "workflowJson": entry.get("workflowJson") if isinstance(entry.get("workflowJson"), dict) else {},
            }
        return {
            "kind": "workflow",
            "id": entry_id,
            "fields": cfg.get("fields") or [],
            "optionalImageMode": cfg.get("optionalImageMode") or "prune-workflow",
            "workflowJson": cfg.get("workflowJson") if isinstance(cfg.get("workflowJson"), dict) else {},
        }
    entry = next(
        (e for e in (provider.get("rh_apps") or []) if runninghub_entry_id(e, "app") == entry_id),
        None,
    )
    if not entry:
        return None
    return {
        "kind": "app",
        "id": entry_id,
        "fields": entry.get("fields") or [],
        "optionalImageMode": "",
        "workflowJson": {},
    }

async def runninghub_upload_local_to_filename(client, provider, url, use_wallet=False):
    """把本地/远程素材上传到 RunningHub /task/openapi/upload，返回 fileName（供 nodeInfoList 使用）。"""
    text = str(url or "").strip()
    if not text:
        return ""
    path = runninghub_local_asset_path(text)
    if path:
        filename = os.path.basename(path)
        content_type = content_type_for_path(path)
        with open(path, "rb") as fh:
            content = fh.read()
    elif text.startswith(("http://", "https://")):
        response = await client.get(text, follow_redirects=True)
        response.raise_for_status()
        content = response.content
        content_type = response.headers.get("content-type") or "application/octet-stream"
        filename = os.path.basename(urllib.parse.urlsplit(text).path) or "asset.bin"
    else:
        return ""
    if not content:
        return ""
    api_key = runninghub_api_key(provider, use_wallet=use_wallet)
    upload_url = runninghub_endpoint_url(provider, "/task/openapi/upload")
    files = {"file": (filename, content, content_type)}
    data = {"apiKey": api_key, "fileType": "input"}
    response = await client.post(upload_url, headers=runninghub_app_headers(False, use_wallet), data=data, files=files)
    raw = response.json()
    if isinstance(raw, dict) and raw.get("code") in (0, "0") and isinstance(raw.get("data"), dict) and raw["data"].get("fileName"):
        return raw["data"]["fileName"]
    raise HTTPException(status_code=502, detail=(raw.get("msg") if isinstance(raw, dict) else "") or f"RunningHub 上传素材失败：{raw}")

async def generate_runninghub_entry_image(prompt, size, model, reference_images, provider, entry):
    """运行 RunningHub 工作流 / AI 应用（与智能画布一致的运行方式），返回首张图片结果。"""
    kind = entry["kind"]
    entry_id = entry["id"]
    fields = rh_sort_fields([f for f in (entry.get("fields") or []) if isinstance(f, dict) and f.get("enabled") is True])
    idx_map = rh_field_indexes(fields)
    use_wallet = False
    timeout = httpx.Timeout(connect=20.0, read=1800.0, write=240.0, pool=20.0)
    aspect = runninghub_aspect_from_size(size, "")
    resolution_field = next((field for field in fields if "resolution" in {
        str(field.get("fieldName") or "").strip().lower(),
        str(field.get("fieldKey") or "").strip().lower(),
        str(field.get("label") or "").strip().lower(),
    }), None)
    resolution = runninghub_resolution_from_size(size, "", runninghub_schema_options(resolution_field))
    width, height = parse_size_pair(size)
    def requested_size_field_value(field):
        names = {
            str(field.get("fieldName") or "").strip().lower(),
            str(field.get("fieldKey") or "").strip().lower(),
            str(field.get("label") or "").strip().lower(),
        }
        if aspect and names & {"aspectratio", "aspect_ratio", "ratio"}:
            return runninghub_schema_value(field, aspect)
        if resolution and "resolution" in names:
            return runninghub_schema_value(field, resolution)
        if width and "width" in names:
            return width
        if height and "height" in names:
            return height
        return None
    async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=timeout) as client:
        uploaded = []
        for ref in (reference_images or [])[:ONLINE_IMAGE_REFERENCE_MAX]:
            ref_url = ref.get("url") if isinstance(ref, dict) else ref
            if not ref_url:
                continue
            file_name = await runninghub_upload_local_to_filename(client, provider, ref_url, use_wallet)
            if file_name:
                uploaded.append(file_name)

        node_info_list = []
        prompt_text = str(prompt or "").strip()
        for field in fields:
            node_id = str(field.get("nodeId") or "").strip()
            field_name = str(field.get("fieldName") or "").strip()
            if not node_id or not field_name:
                continue
            kind_f = rh_field_kind(field)
            if kind_f in ("image", "video", "audio"):
                if kind_f != "image":
                    continue  # 在线生图仅提供图片素材
                index = idx_map.get((node_id, field_name), 0)
                value = uploaded[index] if index < len(uploaded) else ""
                if not value:
                    # 工作流可选图（required!=True）无输入则跳过；必填图回退默认值
                    if field.get("required") is True:
                        value = rh_default_value(field)
                        if not value:
                            continue
                    else:
                        continue
                node_info_list.append({"nodeId": node_id, "fieldName": field_name, "fieldValue": value})
            elif rh_field_role(field) == "prompt":
                value = prompt_text or rh_default_value(field)
                node_info_list.append({"nodeId": node_id, "fieldName": field_name, "fieldValue": value})
            elif kind_f == "number" and field.get("random_enabled") is True:
                node_info_list.append({"nodeId": node_id, "fieldName": field_name, "fieldValue": rh_random_field_value(field)})
            else:
                value = requested_size_field_value(field)
                if value is None:
                    value = rh_default_value(field)
                node_info_list.append({"nodeId": node_id, "fieldName": field_name, "fieldValue": value})

        api_key = runninghub_api_key(provider, use_wallet=use_wallet)
        if kind == "workflow":
            submit_url = runninghub_endpoint_url(provider, "/task/openapi/create")
            body = {"apiKey": api_key, "workflowId": entry_id, "addMetadata": True}
            if node_info_list:
                body["nodeInfoList"] = node_info_list
        else:
            submit_url = runninghub_endpoint_url(provider, "/task/openapi/ai-app/run")
            body = {"apiKey": api_key, "webappId": entry_id, "nodeInfoList": node_info_list}

        response = await client.post(submit_url, headers=runninghub_app_headers(True, use_wallet), json=body)
        raw = response.json()
        if not (isinstance(raw, dict) and raw.get("code") in (0, "0")):
            raise HTTPException(status_code=502, detail=(raw.get("msg") if isinstance(raw, dict) else "") or f"RunningHub 提交失败：{raw}")
        task_id = raw.get("data", {}).get("taskId") if isinstance(raw.get("data"), dict) else ""
        if not task_id:
            raise HTTPException(status_code=502, detail=f"RunningHub 未返回 taskId：{raw}")

        query_url = runninghub_endpoint_url(provider, "/task/openapi/outputs")
        deadline = time.monotonic() + 1800
        last_payload = None
        while time.monotonic() < deadline:
            await asyncio.sleep(2.5)
            query_response = await client.post(query_url, headers=runninghub_app_headers(True), json={"apiKey": api_key, "taskId": task_id})
            query_raw = query_response.json()
            last_payload = query_raw
            code = query_raw.get("code") if isinstance(query_raw, dict) else None
            if code in (0, "0"):
                outputs = runninghub_extract_outputs(query_raw.get("data"))
                for remote in outputs:
                    if str(remote or "").startswith(("http://", "https://", "/output/", "/assets/")):
                        return {"type": "url", "value": str(remote)}, query_raw
                raise HTTPException(status_code=502, detail=f"RunningHub 任务无图片输出：{query_raw}")
            if code in (805, "805"):
                raise HTTPException(status_code=502, detail=f"RunningHub 任务失败：{runninghub_fail_reason(query_raw) or query_raw}")
            # 804 运行中 / 813 排队中 / 其他状态继续轮询
        raise HTTPException(status_code=504, detail=f"RunningHub 任务超时：{last_payload}")

async def generate_runninghub_provider_image(prompt, size, model, reference_images=None, provider=None):
    entry = runninghub_entry_config_from_model(provider, model)
    if entry:
        return await generate_runninghub_entry_image(prompt, size, model, reference_images, provider, entry)
    model_def = await runninghub_model_definition(provider, model)
    endpoint = runninghub_task_endpoint(provider, model_def.get("endpoint") or model)
    params = model_def.get("params") if isinstance(model_def.get("params"), list) else []
    aspect = runninghub_aspect_from_size(size, "1:1")
    resolution = runninghub_resolution_from_size(size, "2k", runninghub_schema_options(runninghub_schema_field(params, "resolution")))
    body = {"prompt": prompt}
    if runninghub_schema_field(params, "aspectRatio"):
        field = runninghub_schema_field(params, "aspectRatio")
        body["aspectRatio"] = runninghub_schema_value(field, aspect)
    elif runninghub_schema_field(params, "ratio"):
        field = runninghub_schema_field(params, "ratio")
        body["ratio"] = runninghub_schema_value(field, aspect)
    if runninghub_schema_field(params, "resolution"):
        field = runninghub_schema_field(params, "resolution")
        body["resolution"] = runninghub_schema_value(field, resolution)
    width, height = parse_size_pair(size)
    if width and height:
        if runninghub_schema_field(params, "width"):
            body["width"] = width
        if runninghub_schema_field(params, "height"):
            body["height"] = height
    quality_field = runninghub_schema_field(params, "quality")
    if quality_field:
        body["quality"] = runninghub_schema_value(quality_field, "medium")
    async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=httpx.Timeout(connect=20.0, read=1800.0, write=180.0, pool=20.0)) as client:
        image_urls = []
        for ref in (reference_images or [])[:ONLINE_IMAGE_REFERENCE_MAX]:
            url = await runninghub_upload_reference(client, provider, ref)
            if url:
                image_urls.append(url)
        if image_urls:
            image_field = runninghub_schema_field(params, "imageUrls", "imageUrl", "images", "image")
            key = str((image_field or {}).get("fieldKey") or "imageUrls")
            if key.endswith("s") or (image_field or {}).get("multipleInputs") is True:
                body[key] = image_urls
            else:
                body[key] = image_urls[0]
        runninghub_apply_schema_defaults(body, params)
        response = await client.post(endpoint, headers=runninghub_json_headers(provider), json=body)
        response.raise_for_status()
        raw = response.json()
        try:
            return runninghub_extract_image(raw), raw
        except HTTPException:
            task_id = runninghub_extract_task_id(raw)
            if not task_id:
                raise HTTPException(status_code=502, detail=f"RunningHub 未返回 taskId 或图片结果：{raw}")
        result = await wait_for_runninghub_image_task(client, provider, task_id)
        return runninghub_extract_image(result), result

async def wait_for_runninghub_openapi_task(client, provider, task_id, output_kind=""):
    query_url = runninghub_openapi_url(provider, "query")
    deadline = time.monotonic() + 1800
    last_payload = None
    while time.monotonic() < deadline:
        await asyncio.sleep(3)
        response = await client.post(query_url, headers=runninghub_json_headers(provider), json={"taskId": task_id})
        response.raise_for_status()
        raw = response.json()
        last_payload = raw
        status = runninghub_query_status(raw).upper()
        if status in {"SUCCESS", "SUCCEEDED", "COMPLETED", "COMPLETE", "FINISHED", "DONE", "3"}:
            return raw
        if status in {"FAILED", "FAIL", "ERROR", "CANCEL", "CANCELED", "CANCELLED", "4"}:
            raise HTTPException(status_code=502, detail=f"RunningHub 任务失败：{runninghub_fail_reason(raw) or raw}")
        if output_kind == "video" and video_output_urls(raw):
            return raw
    raise HTTPException(status_code=504, detail=f"RunningHub 任务超时：{last_payload or task_id}")

async def generate_runninghub_video(payload, provider):
    model_def = await runninghub_model_definition(provider, payload.model)
    endpoint = runninghub_task_endpoint(provider, model_def.get("endpoint") or payload.model)
    params = model_def.get("params") if isinstance(model_def.get("params"), list) else []
    body = {"prompt": str(payload.prompt or "")}
    aspect = str(payload.aspect_ratio or "16:9").strip() or "16:9"
    if runninghub_schema_field(params, "aspectRatio"):
        field = runninghub_schema_field(params, "aspectRatio")
        body["aspectRatio"] = runninghub_schema_value(field, aspect)
    if runninghub_schema_field(params, "ratio"):
        field = runninghub_schema_field(params, "ratio")
        body["ratio"] = runninghub_schema_value(field, aspect)
    if runninghub_schema_field(params, "size"):
        field = runninghub_schema_field(params, "size")
        body["size"] = runninghub_schema_value(field, runninghub_size_for_aspect(aspect))
    if runninghub_schema_field(params, "duration"):
        field = runninghub_schema_field(params, "duration")
        body["duration"] = runninghub_schema_value(field, str(max(1, min(60, int(payload.duration or 5)))))
    if runninghub_schema_field(params, "resolution"):
        field = runninghub_schema_field(params, "resolution")
        body["resolution"] = runninghub_schema_value(field, legacy_video_resolution(payload.resolution or "720p").lower())
    if runninghub_schema_field(params, "generateAudio"):
        body["generateAudio"] = bool(payload.generate_audio)
    if runninghub_schema_field(params, "watermark"):
        body["watermark"] = bool(payload.watermark)
    async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=VIDEO_POLL_TIMEOUT) as client:
        image_urls = []
        for ref in (payload.images or [])[:10]:
            ref_url = getattr(ref, "url", "") or ""
            if ref_url:
                up = await runninghub_upload_reference(client, provider, {"url": ref_url})
                if up:
                    image_urls.append(up)
        if image_urls:
            image_field = runninghub_schema_field(params, "imageUrls", "imageUrl", "firstFrameImage", "lastFrameImage", "referenceImages")
            key = str((image_field or {}).get("fieldKey") or "imageUrls")
            if key in {"firstFrameImage", "first_frame_image"}:
                body[key] = image_urls[0]
                last_field = runninghub_schema_field(params, "lastFrameImage", "last_frame_image")
                if len(image_urls) > 1 and last_field:
                    body[str(last_field.get("fieldKey"))] = image_urls[1]
            elif key.endswith("s") or (image_field or {}).get("multipleInputs") is True:
                body[key] = image_urls
            else:
                body[key] = image_urls[0]
        runninghub_apply_schema_defaults(body, params)
        response = await client.post(endpoint, headers=runninghub_json_headers(provider), json=body)
        response.raise_for_status()
        raw = response.json()
        task_id = runninghub_extract_task_id(raw)
        result = raw
        if task_id and not video_output_urls(raw):
            result = await wait_for_runninghub_openapi_task(client, provider, task_id, "video")
        urls = video_output_urls(result)
        if not urls:
            outputs = runninghub_extract_outputs(result.get("data") if isinstance(result, dict) else result)
            urls = [url for url in outputs if str(url).startswith(("http://", "https://", "/output/", "/assets/"))]
        if not urls:
            raise HTTPException(status_code=502, detail=f"RunningHub 视频生成成功但没有返回视频：{result}")
        local_urls = [await save_remote_video_to_output(url, prefix="rh_video_") for url in urls]
        return {**{"videos": local_urls, "task_id": task_id, "raw": result}, **build_canvas_meta(local_urls, payload, "video")}

async def generate_ai_image(prompt, size, quality, model, reference_images=None, provider_id="comfly", background="auto", size_notice_out=None, n=1, midjourney_version="", midjourney_hd=False, thinking_mode=None, output_format="", frame_count=0, frame_duration_ms=0, svg_model=""):
    async with provider_slot(get_api_provider(provider_id)):
        return await _generate_ai_image_unlimited(prompt, size, quality, model, reference_images, provider_id, background, size_notice_out, n, midjourney_version, midjourney_hd, thinking_mode, output_format, frame_count, frame_duration_ms, svg_model)

async def _generate_ai_image_unlimited(prompt, size, quality, model, reference_images=None, provider_id="comfly", background="auto", size_notice_out=None, n=1, midjourney_version="", midjourney_hd=False, thinking_mode=None, output_format="", frame_count=0, frame_duration_ms=0, svg_model=""):
    provider = get_api_provider(provider_id)
    if reference_images:
        # 私网素材（对方电脑 / 旧克隆漏网的局域网地址）先落本机，绝不把 http://192.168.x.x 发给上游
        reference_images = await _localize_private_reference_urls(reference_images)
    if str(model or "").strip().lower().startswith("pixverse-image"):
        # 拍我AI 的图片模版生成要 template_id + 参考图 id（专属接口 /openapi/v2/image/template/generate），
        # 画布没有模版选择项，列在模型里也跑不了，直接说清楚而不是发出去撞运气。
        raise HTTPException(status_code=400, detail="pixverse 图片模版生成需要模版 ID 和参考图 id（专属接口 /openapi/v2/image/template/generate），画布没有模版选项，先别选它。")
    background = normalize_image_background(background)
    # 原生透明只在真会下发 background 参数的 OpenAI /images/* 分支成立；keep 档上游没有对应参数，一律走提示词。
    native_background = background == "transparent" and image_supports_native_transparent_background(provider, model)
    if background != "auto" and not native_background:
        prompt = image_background_prompt(prompt, background)
    if provider["id"] == "modelscope":
        return await generate_modelscope_provider_image(prompt, size, model, reference_images, provider)
    if is_codex_provider(provider):
        return await generate_codex_provider_image(prompt, size, model, reference_images, provider)
    if is_gemini_cli_provider(provider):
        return await generate_gemini_cli_provider_image(prompt, size, model, reference_images, provider)
    if is_jimeng_provider(provider):
        return await generate_jimeng_provider_image(prompt, size, model, reference_images, provider)
    if is_runninghub_provider(provider):
        return await generate_runninghub_provider_image(prompt, size, model, reference_images, provider)
    if is_lovart_provider(provider):
        return await generate_lovart_provider_image(prompt, size, model, reference_images, provider)
    if effective_protocol(provider, model) == "gemini":
        return await generate_gemini_provider_image(prompt, size, model, reference_images, provider)
    if is_volcengine_provider(provider):
        return await generate_volcengine_provider_image(prompt, size, model, reference_images, provider)
    is_gpt2 = is_gpt_image_2_model(model)
    is_apimart = is_apimart_provider(provider)
    # 不对 GPT 尺寸做任何缩小/拦截：用户选什么尺寸就原样发给上游；
    # 若超过 GPT 的最大像素限制被上游拒绝，再由 friendly_image_error_detail 给出友好的像素上限提示。
    requested_quality = str(quality or "").strip().lower()
    quality = requested_quality if requested_quality in {"low", "medium", "high"} else ""
    base_url = (provider.get("base_url") or AI_BASE_URL).rstrip("/")
    if not base_url:
        raise HTTPException(status_code=400, detail=f"{provider.get('name') or provider['id']} 未配置 Base URL")
    gen_url = provider_endpoint_url(provider, "image_generation_endpoint", "/v1/images/generations")
    edit_url = provider_endpoint_url(provider, "image_edit_endpoint", "/v1/images/edits")
    refs = [ref for ref in (reference_images or []) if ref.get("url")]
    mask_refs = [ref for ref in refs if str(ref.get("role") or "").strip().lower() == "mask" or str(ref.get("name") or "").lower().endswith("_mask.png")]
    image_refs = [ref for ref in refs if ref not in mask_refs]
    if is_apimart and str(model or "").strip().lower() == "midjourney":
        return await generate_apimart_midjourney_provider_image(
            prompt, size, image_refs, provider, midjourney_version, midjourney_hd)
    image_request_mode = effective_image_request_mode(provider, model)
    # 到这里已经是「没有平台专属组装函数」的通用分支（apimart 的非默认 image_request_mode 也走这里）：
    # 用与助手链路同一套 caps 兜一次尺寸收敛，避免同一条尺寸在两条链路上被两套口径处理。
    # GIF 的尺寸按「每帧」重新收敛（见 APIMart 分支），不先按静态图口径缩一次。
    capped_size, caps_size_notice = (
        ("", "") if normalize_image_output_format(output_format) == "gif"
        else direct_image_size_caps(provider, model, size))
    if capped_size and str(capped_size) != str(size):
        if size_notice_out is not None and caps_size_notice and not size_notice_out.get("size_notice"):
            size_notice_out["size_notice"] = caps_size_notice
        size = capped_size
    request_timeout = httpx.Timeout(connect=30.0, read=1800.0, write=120.0, pool=20.0) if (is_gpt2 or is_apimart or image_request_mode in {"openai-json", "openai-video-proxy", "openai-responses"}) else AI_REQUEST_TIMEOUT
    retry_context = f"生图 provider={provider['id']} model={model}"
    async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env(provider), timeout=request_timeout) as client:
        response = None
        async def post_openai_edits(edit_files=None):
            data = {"model": model, "prompt": prompt, "size": size}
            if quality:
                data["quality"] = quality
            if native_background:
                data["background"] = "transparent"
            async def send_edits():
                # 连接阶段重试会重发同一批文件，先把句柄拨回开头，避免第二次发空文件
                for _field, (_name, _fh, _ctype) in (edit_files or []):
                    try:
                        _fh.seek(0)
                    except Exception:
                        pass
                return await client.post(
                    edit_url,
                    headers=api_headers(json_body=False, provider=provider, model=model),
                    data=data,
                    files=edit_files if edit_files is not None else {},
                )
            return await with_connect_retries(send_edits, context=retry_context)

        if image_request_mode == "openai-video-proxy":
            body = {
                "model": model,
                "prompt": prompt,
                "aspect_ratio": runninghub_aspect_from_size(size, "1:1"),
            }
            if image_refs:
                body["images"] = [await openai_video_proxy_public_reference_url(ref) for ref in image_refs[:6]]
            video_url = f"{base_url}/videos" if base_url.endswith("/v1") else f"{base_url}/v1/videos"
            response = await httpx_request_with_transient_retries(
                client,
                "POST",
                video_url,
                attempts=2,
                headers=api_headers(provider=provider, model=model),
                json=body,
            )
        elif image_request_mode == "openai-responses":
            tool = {"type": "image_generation"}
            tool["action"] = "edit" if image_refs else "generate"
            if size and str(size).strip().lower() != "auto":
                tool["size"] = responses_proxy_tool_size(size)
            if quality:
                tool["quality"] = quality
            size_instruction = responses_image_size_instruction(size)
            input_text = f"{size_instruction}\n\n{prompt}" if size_instruction else prompt
            content = [{"type": "input_text", "text": input_text}]
            for ref in image_refs[:ONLINE_IMAGE_REFERENCE_MAX]:
                image_url = await responses_input_image_url(ref)
                if image_url:
                    content.append({"type": "input_image", "image_url": image_url})
            body = {
                "model": model,
                "input": [{"role": "user", "content": content}],
                "tools": [tool],
            }
            responses_url = provider_endpoint_url(provider, "image_generation_endpoint", "/v1/responses")
            response = await with_connect_retries(
                lambda: post_openai_responses(client, responses_url, api_headers(provider=provider, model=model), body),
                context=retry_context,
            )
        elif image_request_mode == "openai-json":
            # Agnes 等“OpenAI JSON 图片接口”统一走 /images/generations：
            # 不使用 /images/edits，不传顶层 response_format/n/quality；
            # 文生图只传 extra_body.response_format，图生图把参考图放进 extra_body.image。
            extra_body = {"response_format": "url"}
            if image_refs:
                extra_body["image"] = [reference_to_data_url(ref, max_size=1536) for ref in image_refs[:ONLINE_IMAGE_REFERENCE_MAX]]
            body = {"model": model, "prompt": prompt, "size": size, "extra_body": extra_body}
            # Agnes 官方口径是「档位 1K/2K/3K/4K + ratio 8 个比例」，不是任意 WxH（无原生支持的精确尺寸会被标准化）。
            if is_agnes_image_model(model) or is_agnes_provider(provider):
                agnes_size, agnes_ratio = agnes_image_config(size)
                body["size"] = agnes_size
                body["ratio"] = agnes_ratio
            response = await with_connect_retries(
                lambda: client.post(gen_url, headers=api_headers(provider=provider, model=model), json=body),
                context=retry_context,
            )
        elif is_apimart:
            apimart_size, _base_resolution = apimart_size_resolution(size)
            # 能力表 + 协议更新包下发的参数覆盖（编辑器看到什么，生成就按什么收敛）
            apimart_caps = apimart_image_caps_for(provider, model) or {}
            resolution = apimart_image_resolution_from_size_for_model(size, model, caps=apimart_caps)
            apimart_requested_ratio = apimart_size
            apimart_requested_resolution = _base_resolution
            # GIF 的 size 是「每帧」像素：上游只收 16 的倍数，且按帧数拼版后整版仍要满足上限。
            # 透明背景会把输出格式强制回 png，这种组合按静态图口径走。
            gif_selected = (normalize_image_output_format(output_format) == "gif"
                            and not native_background)
            gif_frame_total = (gif_frame_count(frame_count, apimart_caps.get("gif_frames"))
                               if gif_selected else 0)
            # SVG 的文本模型必填（svg.model）；透明背景会把格式强制回 png，这种组合不算 SVG。
            svg_selected = (normalize_image_output_format(output_format) == "svg"
                            and not native_background)
            if mask_refs and gif_selected:
                raise HTTPException(
                    status_code=400,
                    detail="GIF 输出不支持蒙版局部重绘（上游 GIF 不接受 mask_url），请改用静态图，或去掉蒙版后重试。",
                )
            gif_size_notice = ""
            exact_width, exact_height = parse_size_pair(size)
            if gif_selected:
                requested_frame_size = str(size or "").strip()
                apimart_size = normalize_gif_frame_size(requested_frame_size, gif_frame_total)
                if (requested_frame_size and requested_frame_size.lower() != "auto"
                        and apimart_size != requested_frame_size):
                    gif_size_notice = (f"GIF 每帧尺寸 {requested_frame_size} → {apimart_size}"
                                       "（整版需 ≤3840/829 万像素）")
            elif apimart_caps.get("exact_size") and exact_width and exact_height:
                apimart_size = f"{exact_width}x{exact_height}"
            else:
                apimart_size = apimart_clamp_ratio(apimart_size, apimart_caps.get("ratios"))
            resolution = apimart_image_resolution_for_model(model, resolution, caps=apimart_caps)
            if size_notice_out is not None:
                if gif_selected:
                    gif_notices = [part for part in (size_notice_out.get("size_notice"), gif_size_notice) if part]
                    if gif_notices:
                        size_notice_out["size_notice"] = "；".join(gif_notices)
                else:
                    apimart_notice = apimart_size_notice(
                        apimart_requested_ratio, apimart_size, apimart_requested_resolution, resolution)
                    if apimart_notice:
                        size_notice_out["size_notice"] = apimart_notice
            apimart_official = is_apimart_official_image_model(model)
            request_model, request_version = apimart_image_request_identity(model)
            body = {"model": request_model, "prompt": prompt}
            if request_version:
                body["version"] = request_version
            body[apimart_caps.get("size_field") or "size"] = apimart_size
            if apimart_caps.get("send_resolution", True) and not gif_selected:
                body["resolution"] = resolution
            if apimart_caps.get("send_n", True):
                body["n"] = max(1, min(int(n or 1), int(apimart_caps.get("n_max") or 1)))
            body.update(apimart_output_format_fields(
                model, apimart_caps, output_format, n, bool(image_refs or mask_refs)))
            # 透明背景必须 png：原生透明下覆盖用户选的输出格式
            if native_background:
                body["background"] = "transparent"
                body["output_format"] = "png"
            if gif_selected:
                body["frame_count"] = gif_frame_total
                body["frame_duration_ms"] = gif_frame_duration(
                    frame_duration_ms, apimart_caps.get("gif_frames"))
            if svg_selected:
                body["svg"] = {"model": apimart_svg_model(apimart_caps, svg_model)}
            apimart_quality = apimart_quality_for_model(model, requested_quality, caps=apimart_caps)
            if apimart_quality and not (image_refs and apimart_caps.get("quality_text_only")):
                body["quality"] = apimart_quality
            # thinking_mode 只有文档确证的 wan2.7-image 家族才支持；None = 不发，跟随上游默认 true。
            apimart_thinking_mode = apimart_thinking_mode_value(model, thinking_mode, caps=apimart_caps)
            if apimart_thinking_mode is not None:
                body["thinking_mode"] = apimart_thinking_mode
            if not apimart_official:
                fallback = apimart_caps.get("official_fallback", False)
                if fallback is not None:
                    body["official_fallback"] = False
            if image_refs and apimart_caps.get("refs_none"):
                raise HTTPException(status_code=400, detail=f"{model} 仅支持文生图，请移除参考图或更换支持图生图的模型。")
            ref_max = int(apimart_caps.get("ref_max") or 0)
            if ref_max and len(image_refs) > ref_max:
                raise HTTPException(status_code=400, detail=f"{model} 最多支持 {ref_max} 张参考图，当前为 {len(image_refs)} 张。")
            apimart_remote_required = apimart_official or (
                bool(image_refs) and apimart_caps.get("base64_refs") is False)
            apimart_remote_inputs = False
            selected_refs = image_refs[:ONLINE_IMAGE_REFERENCE_MAX]
            if image_refs:
                if apimart_remote_required:
                    remote_urls = []
                    for ref in selected_refs:
                        up_url = await upload_image_for_apimart(client, provider, ref.get("url", ""))
                        if not str(up_url or "").strip().lower().startswith(("http://", "https://")):
                            reason = up_url[4:] if isinstance(up_url, str) and up_url.startswith("ERR:") else "上传后未返回公网 http/https 图片 URL"
                            raise HTTPException(
                                status_code=400,
                                detail=f"{model} 参考图必须上传成公网可访问的图片 URL：{invalid_video_image_preview(ref.get('url', ''))}\n原因：{reason}",
                            )
                        remote_urls.append(up_url)
                    body["image_urls"] = remote_urls
                else:
                    apimart_inputs = await apimart_image_reference_inputs(client, provider, selected_refs, body)
                    body["image_urls"] = apimart_inputs
                    apimart_remote_inputs = bool(apimart_inputs) and all(
                        str(url).startswith(("http://", "https://")) for url in apimart_inputs)
                body["image_urls"] = sanitize_apimart_image_urls(body["image_urls"], selected_refs)
            if mask_refs:
                if not apimart_caps.get("mask_url"):
                    raise HTTPException(status_code=400, detail=f"{model} 不支持 mask_url 蒙版局部重绘。")
                mask_ref = mask_refs[0]
                if apimart_remote_required:
                    mask_url = await upload_image_for_apimart(client, provider, mask_ref.get("url", ""))
                else:
                    mask_url = reference_to_data_url(mask_ref, max_size=2048)
                if not mask_url or str(mask_url).startswith("ERR:"):
                    raise HTTPException(status_code=400, detail="蒙版图片无法转换为上游可用的 mask_url。")
                body["mask_url"] = mask_url
            request_headers = api_headers(provider=provider, model=model)
            if apimart_caps.get("response_version"):
                request_headers["X-APIMart-Response-Version"] = apimart_caps["response_version"]
            if apimart_caps.get("idempotency"):
                request_headers["Idempotency-Key"] = str(uuid.uuid4())
            response = await with_connect_retries(
                lambda: client.post(gen_url, headers=request_headers, json=body),
                context=retry_context,
            )
            if (apimart_remote_inputs and not apimart_remote_required and response.status_code >= 400
                    and apimart_image_url_rejected(response.text)):
                print(f"APIMart 中转站可能取不到外部图片 URL（{response.status_code}），改用压缩 data URL 重试一次：{response.text[:200]}")
                body["image_urls"] = apimart_reference_data_urls(selected_refs, body)
                body["image_urls"] = sanitize_apimart_image_urls(body["image_urls"], selected_refs)
                if apimart_caps.get("idempotency"):
                    request_headers["Idempotency-Key"] = str(uuid.uuid4())
                response = await with_connect_retries(
                    lambda: client.post(gen_url, headers=request_headers, json=body),
                    context=retry_context,
                )
        elif is_gpt2 and not image_refs and not mask_refs:
            body = {"model": model, "prompt": prompt, "size": size}
            if quality:
                body["quality"] = quality
            if native_background:
                body["background"] = "transparent"
            # 走 post_openai_image_request 是为了复用「上游拒绝 background 就摘掉重试」的兜底（该 body 无 response_format）
            response = await with_connect_retries(
                lambda: post_openai_image_request(client, gen_url, api_headers(provider=provider, model=model), body),
                context=retry_context,
            )
            if response.status_code >= 400 and images_api_unsupported(response):
                response = await post_openai_edits()
        elif image_refs:
            # 1) OpenAI 协议的图生图/编辑用 multipart 提交到 /images/edits；
            # GPT-Image-2 参考图不能走 /images/generations JSON，否则部分平台会忽略原图或报 Images API unsupported。
            files = []
            opened = []
            edit_failed_status = None
            edit_failed_text = ""
            try:
                for ref in image_refs[:ONLINE_IMAGE_REFERENCE_MAX]:
                    path = output_file_from_url(ref.get("url", ""))
                    if not path:
                        continue
                    fh = open(path, "rb")
                    opened.append(fh)
                    files.append(("image", (os.path.basename(path), fh, content_type_for_path(path))))
                if mask_refs:
                    mask_path = output_file_from_url(mask_refs[0].get("url", ""))
                    if mask_path:
                        fh = open(mask_path, "rb")
                        opened.append(fh)
                        files.append(("mask", (os.path.basename(mask_path), fh, content_type_for_path(mask_path))))
                try:
                    response = await post_openai_edits(files)
                    if response.status_code >= 400:
                        edit_failed_status = response.status_code
                        edit_failed_text = response.text[:500]
                        response = None
                except httpx.HTTPError as e:
                    edit_failed_status = -1
                    edit_failed_text = str(e)
                    response = None
            finally:
                for fh in opened:
                    fh.close()
            # 2) edits 失败 → 非 GPT-Image-2 可回退到 /images/generations + JSON image:[urls/base64]（grsai 风格）
            if response is None:
                if is_gpt2:
                    raise HTTPException(
                        status_code=502,
                        detail=(friendly_image_error_detail(edit_failed_text, size, model)
                                or f"GPT-Image-2 编辑接口 /images/edits 调用失败：{edit_failed_text[:300] or edit_failed_status}。已停止自动重试，避免上游可能已扣费后再次请求。")
                    )
                print(f"/images/edits failed ({edit_failed_status}): {edit_failed_text[:200]} → 回退到 /images/generations + image:[] JSON")
                image_payload = [reference_to_data_url(ref, max_size=1536) for ref in image_refs[:ONLINE_IMAGE_REFERENCE_MAX]]
                extra = {"image": image_payload}
                if native_background:
                    extra["background"] = "transparent"
                body = openai_image_request_body(model, prompt, size, quality, extra)
                response = await with_connect_retries(
                    lambda: post_openai_image_request(client, gen_url, api_headers(provider=provider, model=model), body),
                    context=retry_context,
                )
                if response.status_code >= 400 and images_api_unsupported(response):
                    raise HTTPException(
                        status_code=502,
                        detail=f"编辑接口 /images/edits 调用失败，且该平台不支持 /images/generations：{edit_failed_text[:300] or edit_failed_status}"
                    )
        else:
            extra = {"background": "transparent"} if native_background else None
            body = openai_image_request_body(model, prompt, size, quality, extra)
            response = await with_connect_retries(
                lambda: post_openai_image_request(client, gen_url, api_headers(provider=provider, model=model), body),
                context=retry_context,
            )
            if response.status_code >= 400 and images_api_unsupported(response):
                response = await post_openai_edits()
        response.raise_for_status()
        raw = response.json()
        try:
            return extract_image(raw), raw
        except HTTPException as exc:
            if image_request_mode == "openai-responses":
                fallback_image = responses_output_text_image(raw)
                if fallback_image:
                    return fallback_image, raw
                try:
                    print(f"RS 响应中没有图片，原始返回（截断）：{json.dumps(raw, ensure_ascii=False)[:800]}")
                except Exception:
                    pass
                raise HTTPException(status_code=502, detail=responses_no_image_detail(raw) or exc.detail)
            task_id = extract_task_id(raw)
            if not task_id:
                raise
        try:
            task_result = await wait_for_image_task(client, task_id, provider)
            return extract_image(task_result), task_result
        except HTTPException as exc:
            setattr(exc, "upstream_task_id", task_id)
            raise

def upstream_message_from_record(item):
    role = item.get("role")
    if role not in {"user", "assistant"} or item.get("type") == "image":
        return None
    attachments = item.get("attachments") or []
    if attachments and role == "user":
        text = item.get("content", "")
        blocks = attachment_text_blocks(attachments)
        if blocks:
            text = f"{text}\n\n以下是用户上传附件的可读内容，请在回答时参考：\n\n" + "\n\n---\n\n".join(blocks)
        content = [{"type": "text", "text": text}]
        image_urls = []
        for ref in image_references(attachments[:CHAT_ATTACHMENT_MAX]):
            url = reference_to_data_url(ref)
            if url:
                image_urls.append(url)
        image_urls.extend(attachment_embedded_image_data_urls(attachments[:CHAT_ATTACHMENT_MAX], max_images=max(0, CHAT_ATTACHMENT_MAX - len(image_urls))))
        for url in image_urls[:CHAT_ATTACHMENT_MAX]:
            content.append({"type": "image_url", "image_url": {"url": url}})
        return {"role": role, "content": content}
    return {"role": role, "content": item.get("content", "")}

AGENT_ACTIONS = {"chat", "generate_image", "edit_image"}
AGENT_IMAGE_KEYWORDS = [
    "生成", "画", "出图", "生图", "图片", "图像", "海报", "头像", "壁纸",
    "插画", "照片", "photo", "image", "picture", "draw", "generate",
]
AGENT_EDIT_KEYWORDS = [
    "修改", "改成", "换成", "调整", "优化", "编辑", "重绘", "上一张", "刚才",
    "这张", "那张", "参考图", "改图", "edit", "modify", "change", "revise",
]
CN_NUMERAL_MAP = {
    "一": 1, "二": 2, "两": 2, "俩": 2, "三": 3, "四": 4,
}

def latest_chat_image_refs(conversation, limit=1):
    refs = []
    for item in reversed(conversation.get("messages") or []):
        url = item.get("image_url") if isinstance(item, dict) else ""
        if url:
            refs.append({"url": url, "name": item.get("content") or "上一张图片", "role": "source"})
        if len(refs) >= limit:
            break
    return refs

def image_size_from_reference(ref):
    path = output_file_from_url(ref)
    if not path:
        return ""
    try:
        with Image.open(path) as img:
            width, height = img.size
        if width > 0 and height > 0:
            return f"{width}x{height}"
    except Exception as exc:
        print(f"[chat-agent] failed to read reference image size: {exc}")
    return ""

def chat_requested_image_count(message):
    text = str(message or "")
    match = re.search(r"(?<!\d)([1-4])\s*(?:张|幅|个|组|套)(?!\d)", text)
    if match:
        return max(1, min(4, int(match.group(1))))
    match = re.search(r"([一二两俩三四])\s*(?:张|幅|个|组|套)", text)
    if match:
        return max(1, min(4, CN_NUMERAL_MAP.get(match.group(1), 1)))
    return 1

def chat_split_parallel_prompts(prompt, count):
    text = str(prompt or "").strip()
    if count <= 1:
        return [text]
    noun_match = re.search(r"(.+?)(?:的)?(海报|头像|壁纸|插画|照片|图片|图像)\s*$", text)
    if not noun_match:
        return [text] * count
    prefix = noun_match.group(1).strip()
    suffix = noun_match.group(2)
    prefix = re.sub(r"(?:再)?(?:生成|画|绘制|制作|创建)\s*[1-4一二两俩三四]?\s*(?:张|幅|个|组|套)?", "", prefix).strip()
    prefix = re.sub(r"[,，、\s]+$", "", prefix).strip()
    if not prefix:
        return [text] * count
    candidates = [
        item.strip(" ，,、")
        for item in re.split(r"\s*(?:和|与|、|，|,|\+|＋)\s*", prefix)
        if item.strip(" ，,、")
    ]
    if len(candidates) < count:
        return [text] * count
    return [f"{item}的{suffix}" for item in candidates[:count]]

def pick_chat_image_provider(provider_id="", fallback_id=""):
    providers = [p for p in load_api_providers() if p.get("enabled", True) and (p.get("image_models") or [])]
    for target in (provider_id, fallback_id):
        clean = str(target or "").strip().lower()
        if clean:
            matched = next((p for p in providers if p.get("id") == clean), None)
            if matched:
                return matched
    if providers:
        primary = next((p for p in providers if p.get("primary")), None)
        return primary or providers[0]
    return get_api_provider(provider_id or fallback_id or "comfly")

def heuristic_agent_decision(message, refs, has_previous_image):
    text = str(message or "").strip().lower()
    has_image_word = any(key.lower() in text for key in AGENT_IMAGE_KEYWORDS)
    has_edit_word = any(key.lower() in text for key in AGENT_EDIT_KEYWORDS)
    if refs and (has_edit_word or has_image_word):
        return {"action": "edit_image", "prompt": message, "reply": ""}
    if has_previous_image and has_edit_word:
        return {"action": "edit_image", "prompt": message, "reply": ""}
    if has_image_word and not has_edit_word:
        return {"action": "generate_image", "prompt": message, "reply": ""}
    return {"action": "chat", "prompt": message, "reply": ""}

def parse_agent_decision(raw_text, message, refs, has_previous_image):
    text = str(raw_text or "").strip()
    data = None
    if text:
        match = re.search(r"\{[\s\S]*\}", text)
        candidate = match.group(0) if match else text
        try:
            data = json.loads(candidate)
        except Exception:
            data = None
    heuristic = heuristic_agent_decision(message, refs, has_previous_image)
    if not isinstance(data, dict):
        return heuristic
    action = str(data.get("action") or "").strip()
    if action not in AGENT_ACTIONS:
        action = heuristic["action"]
    prompt = str(data.get("prompt") or message).strip() or message
    reply = str(data.get("reply") or "").strip()
    if action == "edit_image" and not (refs or has_previous_image):
        action = "generate_image" if any(key.lower() in str(message).lower() for key in AGENT_IMAGE_KEYWORDS) else "chat"
    return {"action": action, "prompt": prompt, "reply": reply}

def chat_agent_router_messages(payload, conversation, refs, has_previous_image):
    """意图路由的上游 messages（流式与非流式共用，保证提示词一字不差）。"""
    history = conversation["messages"][-MAX_HISTORY_MESSAGES:]
    custom_system_prompt = str(getattr(payload, "system_prompt", "") or "").strip()
    mem = memory_block(getattr(payload, "conversation_id", "") or "")
    system = (
        "你是图片创作聊天 Agent 的意图路由器。只返回 JSON，不要 Markdown。\n"
        "action 只能是 chat、generate_image、edit_image。\n"
        "chat: 普通问答或不需要调用图片工具。\n"
        "generate_image: 用户要求生成、绘制、创建新图片。\n"
        "edit_image: 用户要求修改参考图、上一张图、刚才生成的图，或上传了参考图并要求基于它变化。\n"
        "prompt 是交给生图/改图工具的完整中文提示词；普通聊天时也填用户原话。\n"
        "reply 是可选的短状态文本。"
    )
    upstream_messages = [{"role": "system", "content": system}]
    for item in history[-10:]:
        msg = upstream_message_from_record(item)
        if msg:
            upstream_messages.append(msg)
    mem_hint = f"用户长期记忆：\n{mem}\n" if mem else ""
    upstream_messages.append({
        "role": "user",
        "content": (
            f"当前用户输入：{payload.message}\n"
            f"用户设置的系统提示词：{custom_system_prompt or '无'}\n"
            f"{mem_hint}"
            f"本次上传参考图数量：{len(refs)}\n"
            f"对话中是否已有上一张生成图：{'是' if has_previous_image else '否'}\n"
            "请返回 JSON，例如 {\"action\":\"generate_image\",\"prompt\":\"...\",\"reply\":\"...\"}"
        )
    })
    return upstream_messages

async def decide_chat_agent_action(payload, conversation, refs):
    has_previous_image = bool(latest_chat_image_refs(conversation, 1))
    fallback = heuristic_agent_decision(payload.message, refs, has_previous_image)
    provider_cfg = get_api_provider(payload.provider) if payload.provider not in ("modelscope",) else {}
    if is_codex_provider(provider_cfg):
        fallback["router_model"] = selected_model(payload.model, (provider_cfg.get("chat_models") or CODEX_DEFAULT_CHAT_MODELS)[0])
        return fallback
    if is_gemini_cli_provider(provider_cfg):
        fallback["router_model"] = selected_model(payload.model, (provider_cfg.get("chat_models") or GEMINI_CLI_DEFAULT_CHAT_MODELS)[0])
        return fallback
    if is_lovart_provider(provider_cfg):
        fallback["router_model"] = selected_model(payload.model, (provider_cfg.get("chat_models") or LOVART_DEFAULT_CHAT_MODELS)[0])
        return fallback
    chat_base, chat_hdrs, model = resolve_chat_provider(payload.provider, payload.model, payload.ms_model)
    upstream_messages = chat_agent_router_messages(payload, conversation, refs, has_previous_image)
    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env(provider_cfg), timeout=AI_REQUEST_TIMEOUT) as client:
            req_body = {"model": model, "messages": upstream_messages}
            if is_apimart_provider(provider_cfg):
                req_body["stream"] = False
            response = await client.post(
                f"{chat_base}/chat/completions",
                headers=chat_hdrs,
                json=req_body,
            )
            response.raise_for_status()
            raw = response.json()
            decision = parse_agent_decision(text_from_chat_response(raw), payload.message, refs, has_previous_image)
            decision["router_model"] = model
            decision["reasoning"] = reasoning_from_chat_response(raw).strip()
            return decision
    except Exception as exc:
        print(f"[chat-agent] intent router fallback: {exc}")
        fallback["router_model"] = model
        return fallback

async def stream_chat_agent_decision(payload, conversation, refs, decision_out):
    """流式版意图路由：reasoning 增量实时 yield 出去，最终决策写进 decision_out。
    提示词 / JSON 解析 / heuristic 兜底与 decide_chat_agent_action 完全一致，只把上游调用改成流式。"""
    has_previous_image = bool(latest_chat_image_refs(conversation, 1))
    fallback = heuristic_agent_decision(payload.message, refs, has_previous_image)
    provider_cfg = get_api_provider(payload.provider) if payload.provider not in ("modelscope",) else {}
    if is_codex_provider(provider_cfg):
        fallback["router_model"] = selected_model(payload.model, (provider_cfg.get("chat_models") or CODEX_DEFAULT_CHAT_MODELS)[0])
        decision_out.update(fallback)
        return
    if is_gemini_cli_provider(provider_cfg):
        fallback["router_model"] = selected_model(payload.model, (provider_cfg.get("chat_models") or GEMINI_CLI_DEFAULT_CHAT_MODELS)[0])
        decision_out.update(fallback)
        return
    if is_lovart_provider(provider_cfg):
        fallback["router_model"] = selected_model(payload.model, (provider_cfg.get("chat_models") or LOVART_DEFAULT_CHAT_MODELS)[0])
        decision_out.update(fallback)
        return
    chat_base, chat_hdrs, model = resolve_chat_provider(payload.provider, payload.model, payload.ms_model)
    upstream_messages = chat_agent_router_messages(payload, conversation, refs, has_previous_image)
    content_parts = []
    reasoning_parts = []
    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env(provider_cfg), timeout=AI_REQUEST_TIMEOUT) as client:
            if is_apimart_provider(provider_cfg):
                # APIMart 不支持流式：仍然整包拿回来，拿到后一次性转发思考内容
                response = await client.post(
                    f"{chat_base}/chat/completions",
                    headers=chat_hdrs,
                    json={"model": model, "messages": upstream_messages, "stream": False},
                )
                response.raise_for_status()
                raw = response.json()
                content_parts.append(text_from_chat_response(raw))
                reasoning_text = reasoning_from_chat_response(raw).strip()
                if reasoning_text:
                    reasoning_parts.append(reasoning_text)
                    yield {"type": "reasoning", "delta": reasoning_text}
            else:
                async with client.stream(
                    "POST",
                    f"{chat_base}/chat/completions",
                    headers=chat_hdrs,
                    json={"model": model, "messages": upstream_messages, "stream": True},
                ) as response:
                    if response.status_code >= 400:
                        body = (await response.aread()).decode("utf-8", errors="ignore")
                        raise RuntimeError(f"上游接口错误：{body[:300]}")
                    async for line in response.aiter_lines():
                        if not line:
                            continue
                        if line.startswith("data:"):
                            line = line[5:].strip()
                        if line == "[DONE]":
                            break
                        try:
                            chunk = json.loads(line)
                        except json.JSONDecodeError:
                            continue
                        reasoning_delta = reasoning_delta_from_chat_chunk(chunk)
                        if reasoning_delta:
                            reasoning_parts.append(reasoning_delta)
                            yield {"type": "reasoning", "delta": reasoning_delta}
                        delta = text_delta_from_chat_chunk(chunk)
                        if delta:
                            content_parts.append(delta)
    except Exception as exc:
        print(f"[chat-agent] intent router fallback: {exc}")
        fallback["router_model"] = model
        decision_out.update(fallback)
        return
    decision = parse_agent_decision("".join(content_parts), payload.message, refs, has_previous_image)
    decision["router_model"] = model
    decision["reasoning"] = "".join(reasoning_parts).strip()
    decision_out.update(decision)

async def build_chat_text_reply(payload, conversation):
    provider_cfg = get_api_provider(payload.provider) if payload.provider not in ("modelscope",) else {}
    if is_codex_provider(provider_cfg):
        model = selected_model(payload.model, (provider_cfg.get("chat_models") or CODEX_DEFAULT_CHAT_MODELS)[0])
        payload.model = model
        text, raw = await codex_chat_text(payload, conversation["messages"][-MAX_HISTORY_MESSAGES:])
        return {
            "id": uuid.uuid4().hex,
            "role": "assistant",
            "content": text,
            "created_at": now_ms(),
            "model": model,
            "raw_usage": None,
            "raw": raw,
        }
    if is_gemini_cli_provider(provider_cfg):
        model = selected_model(payload.model, (provider_cfg.get("chat_models") or GEMINI_CLI_DEFAULT_CHAT_MODELS)[0])
        payload.model = model
        text, raw = await gemini_cli_chat_text(payload, conversation["messages"][-MAX_HISTORY_MESSAGES:])
        return {
            "id": uuid.uuid4().hex,
            "role": "assistant",
            "content": text,
            "created_at": now_ms(),
            "model": model,
            "raw_usage": None,
            "raw": raw,
        }
    if is_lovart_provider(provider_cfg):
        model = selected_model(payload.model, (provider_cfg.get("chat_models") or LOVART_DEFAULT_CHAT_MODELS)[0])
        payload.model = model
        text, raw = await lovart_chat_text(payload, conversation["messages"][-MAX_HISTORY_MESSAGES:])
        return {
            "id": uuid.uuid4().hex,
            "role": "assistant",
            "content": text,
            "created_at": now_ms(),
            "model": model,
            "raw_usage": None,
            "raw": raw,
        }
    chat_base, chat_hdrs, model = resolve_chat_provider(payload.provider, payload.model, payload.ms_model)
    is_apimart = is_apimart_provider(provider_cfg)
    upstream_messages = [{"role": "system", "content": chat_system_prompt(payload)}]
    for item in conversation["messages"][-MAX_HISTORY_MESSAGES:]:
        msg = upstream_message_from_record(item)
        if msg:
            upstream_messages.append(msg)
    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env(provider_cfg), timeout=AI_REQUEST_TIMEOUT) as client:
            req_body = {"model": model, "messages": upstream_messages}
            if is_apimart:
                req_body["stream"] = False
            response = await client.post(f"{chat_base}/chat/completions", headers=chat_hdrs, json=req_body)
            response.raise_for_status()
            raw = response.json()
    except httpx.HTTPStatusError as exc:
        body = exc.response.text or ""
        friendly = friendly_chat_error_detail(body, model, provider_cfg)
        raise HTTPException(status_code=exc.response.status_code, detail=friendly or f"上游接口错误：{body}") from exc
    except httpx.HTTPError as exc:
        raise HTTPException(status_code=502, detail=f"请求上游接口失败：{exc}") from exc
    raw_data = unwrap_apimart_response(raw) if isinstance(raw, dict) else raw
    message = {
        "id": uuid.uuid4().hex,
        "role": "assistant",
        "content": text_from_chat_response(raw).strip() or "接口返回了空回复。",
        "created_at": now_ms(),
        "model": model,
        "raw_usage": raw_data.get("usage") if isinstance(raw_data, dict) else None,
    }
    reasoning_text = reasoning_from_chat_response(raw).strip()
    if reasoning_text:
        message["reasoning"] = reasoning_text
    return message

