@app.get("/api/lan-info")
async def lan_info():
    """返回局域网访问地址 + 二维码 data URL，供前端显示「手机访问」通知条"""
    import os as _os
    import io as _io
    import base64 as _b64
    port = int(_os.environ.get("NOVAI_PORT", "3000"))
    lan_ip = _os.environ.get("NOVAI_LAN_IP")
    lan_url = _os.environ.get("NOVAI_LAN_URL")
    # dev 模式（直接跑 main.py）下环境变量没设，自己算
    if not lan_ip:
        import socket as _socket
        s = _socket.socket(_socket.AF_INET, _socket.SOCK_DGRAM)
        try:
            s.connect(("8.8.8.8", 80))
            lan_ip = s.getsockname()[0]
        except Exception:
            lan_ip = None
        finally:
            s.close()
        if lan_ip:
            lan_url = f"http://{lan_ip}:{port}"
    if not lan_url:
        return {"available": False, "url": None, "token": None, "ip": None, "port": port, "qr_data_url": None}
    # 分享地址带口令：扫码/打开即通过鉴权。本接口本身也走中间件，非本机调用需先有口令，不会把口令漏给未授权方。
    token = load_lan_token() if lan_auth_enabled() else ""
    if token:
        sep = "&" if "?" in lan_url else "?"
        share_url = f"{lan_url}{sep}token={urllib.parse.quote(token)}"
    else:
        share_url = lan_url
    # 生成二维码 data URL（二维码用带口令的地址）
    qr_data_url = None
    try:
        import qrcode as _qr
        qr = _qr.QRCode(version=1, box_size=6, border=2)
        qr.add_data(share_url)
        qr.make(fit=True)
        img = qr.make_image(fill_color="black", back_color="white")
        buf = _io.BytesIO()
        img.save(buf, format="PNG")
        qr_data_url = "data:image/png;base64," + _b64.b64encode(buf.getvalue()).decode()
    except Exception as e:
        print(f"[lan-info] qrcode gen failed: {e}")
    return {
        "available": True,
        "url": share_url,
        "token": token,
        "ip": lan_ip,
        "port": port,
        "qr_data_url": qr_data_url,
    }

