@app.get("/api/view")
def view_image(filename: str, type: str = "input", subfolder: str = ""):
    # 先按原逻辑去各 ComfyUI 后端找
    for addr in COMFYUI_INSTANCES:
        try:
            url = f"http://{addr}/view"
            params = {"filename": filename, "type": type, "subfolder": subfolder}
            r = _NO_PROXY_SESSION.get(url, params=params, timeout=1)
            if r.status_code == 200:
                return Response(content=r.content, media_type=r.headers.get('Content-Type'))
        except Exception:
            continue
    # 后端都拿不到时回退本地 assets/<input|output>/
    # 适用场景：画布通过 /api/ai/upload 把参考图直接落到本地 assets/input/，
    # 但 ComfyUI 的 input 可能因为重启/清理而丢失，导致 enhance/klein 等页面预览对比图 404
    if not subfolder and type in ("input", "output"):
        safe_name = os.path.basename(filename or "")
        if safe_name:
            local_path = output_path_for(safe_name, "input" if type == "input" else "output")
            if os.path.isfile(local_path):
                return FileResponse(local_path, media_type=content_type_for_path(local_path))
    raise HTTPException(status_code=404, detail="Image not found on any available backend")

@app.get("/api/download-output")
def download_output(request: Request, url: str, name: str = "", inline: bool = False):
    url = rewrite_runninghub_file_url(url)
    path = output_file_from_url(url)
    if not path:
        path = local_media_file_by_basename(filename_from_media_url(url, ""))
    if path:
        filename = sanitize_export_filename(os.path.basename(name) if name else os.path.basename(path), os.path.basename(path))
        return FileResponse(path, media_type=content_type_for_path(path), filename=None if inline else filename)
    # 远程文件：流式代理，绝不把整段视频/大文件读进内存（否则多个视频同时代理会撑爆内存、拖垮单进程服务）。
    parsed = urllib.parse.urlparse(str(url or "").strip())
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        raise HTTPException(status_code=400, detail="无效的下载地址")
    try:
        upstream_headers = {"User-Agent": "ComfyUI-API-Modelscope/1.0"}
        range_header = request.headers.get("range")
        if range_header:
            upstream_headers["Range"] = range_header
        upstream = _NO_PROXY_SESSION.get(
            url, stream=True, timeout=(10, 60),
            headers=upstream_headers,
        )
        upstream.raise_for_status()
    except requests.RequestException as exc:
        raise HTTPException(status_code=502, detail=f"远程文件下载失败：{exc}")
    content_type = upstream.headers.get("content-type") or "application/octet-stream"
    fallback = filename_from_media_url(url, "download.bin")
    filename = sanitize_export_filename(os.path.basename(name) if name else fallback, fallback)
    disposition = "inline" if inline else "attachment"
    headers = {"Content-Disposition": f"{disposition}; filename*=UTF-8''{urllib.parse.quote(filename)}"}
    content_length = upstream.headers.get("content-length")
    if content_length:
        headers["Content-Length"] = content_length
    for key in ("content-range", "accept-ranges"):
        value = upstream.headers.get(key)
        if value:
            headers["-".join(part.capitalize() for part in key.split("-"))] = value

    def stream_remote():
        try:
            for chunk in upstream.iter_content(chunk_size=256 * 1024):
                if chunk:
                    yield chunk
        finally:
            upstream.close()

    return StreamingResponse(stream_remote(), media_type=content_type, headers=headers, status_code=upstream.status_code)

@app.post("/api/upload")
async def upload_image(files: List[UploadFile] = File(...)):
    uploaded_files = []
    files_content = []
    for file in files:
        content = await file.read()
        files_content.append((file, content))

    for file, content in files_content:
        success_count = 0
        last_result = None
        for addr in COMFYUI_INSTANCES:
            try:
                files_data = {'image': (file.filename, content, file.content_type)}
                response = _NO_PROXY_SESSION.post(f"http://{addr}/upload/image", files=files_data, timeout=5)
                if response.status_code == 200:
                    last_result = response.json()
                    success_count += 1
            except Exception as e:
                print(f"Upload error for {addr}: {e}")

        if success_count > 0 and last_result:
            uploaded_files.append({"comfy_name": last_result.get("name", file.filename)})
        else:
            raise HTTPException(status_code=503, detail="Failed to upload to any backend")

    return {"files": uploaded_files}

UPLOAD_IMAGE_HARD_MAX_BYTES = 200 * 1024 * 1024
UPLOAD_OTHER_MAX_BYTES = 50 * 1024 * 1024
# 超过这个体积的图片先压小再存：画布无损改图会把整张合成图传上来，直接卡 50MB 用户只会看到「图片出不来」
UPLOAD_IMAGE_COMPRESS_TARGET_BYTES = 50 * 1024 * 1024
UPLOAD_IMAGE_SHRINK_SIDES = (8192, 6144, 4096, 2048)

def upload_size_mb(size_bytes) -> str:
    return f"{float(size_bytes) / 1024.0 / 1024.0:.1f}MB"

def encode_upload_image_bytes(img, image_format: str) -> bytes:
    """JPEG 没有透明通道，压平到白底再编码（和参考图转 JPEG 的处理一致），避免透明区域变黑。"""
    buf = BytesIO()
    if image_format == "JPEG":
        if img.mode in ("RGBA", "LA") or (img.mode == "P" and "transparency" in img.info):
            base = img.convert("RGBA")
            background = Image.new("RGB", base.size, (255, 255, 255))
            background.paste(base, mask=base.split()[-1])
            target = background
        else:
            target = img.convert("RGB")
        target.save(buf, format="JPEG", quality=92, optimize=True)
    else:
        target = img if img.mode in ("1", "L", "LA", "P", "RGB", "RGBA") else img.convert("RGBA")
        target.save(buf, format="PNG")
    return buf.getvalue()

def compress_oversized_image(content: bytes, ext: str, target_bytes: int) -> Tuple[bytes, str, Dict[str, Any]]:
    """把超过 target_bytes 的图片压到目标以内：先保尺寸转 JPEG q92；带透明先试 PNG（不丢透明），
    PNG 放不下再按 8192/6144/4096/2048 缩最长边（且 JPEG 兜底）。压到最小仍超限就抛 413 说明实际体积。"""
    original_bytes = len(content)
    original_dim = (0, 0)
    smallest = original_bytes
    smallest_dim = original_dim
    try:
        with Image.open(BytesIO(content)) as img:
            img.load()
            img = ImageOps.exif_transpose(img) if hasattr(ImageOps, "exif_transpose") else img
            original_dim = img.size
            smallest_dim = original_dim
            has_alpha = img.mode in ("RGBA", "LA") or (img.mode == "P" and "transparency" in img.info)
            formats = ["PNG", "JPEG"] if has_alpha else ["JPEG"]
            for image_format in formats:
                for max_side in (0, *UPLOAD_IMAGE_SHRINK_SIDES):
                    frame = img
                    if max_side and max(img.size) > max_side:
                        frame = img.copy()
                        frame.thumbnail((max_side, max_side), Image.LANCZOS)
                    data = encode_upload_image_bytes(frame, image_format)
                    if len(data) < smallest:
                        smallest = len(data)
                        smallest_dim = frame.size
                    if len(data) <= target_bytes:
                        return data, (".png" if image_format == "PNG" else ".jpg"), {
                            "before": original_bytes, "after": len(data),
                            "from_size": original_dim, "to_size": frame.size,
                            "format": image_format,
                        }
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=413, detail=(
            f"图片压缩失败（{exc}）。请先在本地把原图缩小到 50MB 以内"
            "（建议长边不超过 6144 像素、存为 JPEG）再上传。")) from exc
    raise HTTPException(status_code=413, detail=(
        f"原图 {upload_size_mb(original_bytes)}（{original_dim[0]}x{original_dim[1]}），"
        f"压缩后仍有 {upload_size_mb(smallest)}（{smallest_dim[0]}x{smallest_dim[1]}），"
        f"仍超过单文件 {upload_size_mb(target_bytes)} 上限，无法上传。请先把原图缩小"
        "（建议长边不超过 6144 像素，或另存为 JPEG）后重试。"))

@app.post("/api/ai/upload")
async def upload_ai_reference(files: List[UploadFile] = File(...)):
    uploaded = []
    image_exts = _LOCAL_UPLOAD_IMAGE_EXTS
    video_exts = {".mp4", ".webm", ".mov", ".m4v", ".flv"}
    audio_exts = {".mp3", ".wav", ".m4a", ".aac", ".ogg", ".flac"}
    doc_exts = {".pdf", ".txt", ".md", ".markdown", ".doc", ".docx", ".xls", ".xlsx", ".csv", ".json", ".zip", ".yaml", ".yml", ".log"}
    for file in files:
        content = await file.read()
        if not content:
            continue
        ext = os.path.splitext(file.filename or "")[1].lower()
        content_type = (file.content_type or "").lower()
        kind = "image"
        if ext in video_exts or content_type.startswith("video/"):
            kind = "video"
            if ext not in video_exts:
                ext = ".webm" if "webm" in content_type else ".mov" if "quicktime" in content_type else ".mp4"
        elif ext in audio_exts or content_type.startswith("audio/"):
            kind = "audio"
            if ext not in audio_exts:
                ext = ".wav" if "wav" in content_type else ".ogg" if "ogg" in content_type else ".m4a" if "mp4" in content_type else ".mp3"
        elif ext in image_exts or content_type.startswith("image/"):
            kind = "image"
            if ext not in image_exts:
                ext = _local_upload_image_ext_for(content_type)
                if not ext:
                    raise HTTPException(status_code=415, detail=(
                        f"{file.filename or '这个文件'} 的格式暂不支持，请另存为 PNG / JPG / WebP 后重试"))
        elif ext in doc_exts or content_type.startswith(("text/", "application/")):
            kind = "file"
            if not ext:
                ext = mimetypes.guess_extension(content_type) or ".bin"
        else:
            kind = "file"
            if not ext:
                ext = ".bin"
        display_name = file.filename or "文件"
        if kind == "image":
            if len(content) > UPLOAD_IMAGE_HARD_MAX_BYTES:
                raise HTTPException(status_code=413, detail=(
                    f"{display_name} 有 {upload_size_mb(len(content))}，超过图片单文件 "
                    f"{upload_size_mb(UPLOAD_IMAGE_HARD_MAX_BYTES)} 上限，无法上传。"
                    "请先缩小原图（建议长边不超过 6144 像素，或另存为 JPEG）后重试。"))
            if len(content) > UPLOAD_IMAGE_COMPRESS_TARGET_BYTES:
                original_bytes = len(content)
                content, ext, info = compress_oversized_image(content, ext, UPLOAD_IMAGE_COMPRESS_TARGET_BYTES)
                print(f"上传图片 {display_name} 超过 {upload_size_mb(UPLOAD_IMAGE_COMPRESS_TARGET_BYTES)}，已压缩："
                      f"{upload_size_mb(original_bytes)} → {upload_size_mb(len(content))}，"
                      f"{info['from_size'][0]}x{info['from_size'][1]} → {info['to_size'][0]}x{info['to_size'][1]}，{info['format']}")
        elif len(content) > UPLOAD_OTHER_MAX_BYTES:
            raise HTTPException(status_code=413, detail=f"{display_name} 超过 50MB，无法上传")
        filename = f"ai_ref_{uuid.uuid4().hex[:12]}{ext}"
        # 内容哈希去重：同一张图重复上传只保留一份物理文件（命中优先硬链，否则复用已有 URL）
        url = store_uploaded_bytes(content, filename, "input", file.filename or filename)
        uploaded.append({"url": url, "name": file.filename or filename, "kind": kind, "mime": content_type})
    return {"files": uploaded}

class VideoBlurFacesRequest(BaseModel):
    url: str = ""            # 本地视频 URL（/assets/ 或 /output/ 开头）
    strength: int = 60       # 高斯模糊核大小（20-100，越大越糊）

@app.post("/api/video/blur-faces")
async def video_blur_faces(payload: VideoBlurFacesRequest):
    """检测视频中的人脸并高斯模糊，规避平台真人审核拦截。
    返回模糊后的视频 URL（存 assets/input/blurred_*.mp4）。
    人脸检测用 YuNet 模型（assets/models/face_detection_yunet.onnx），
    无模型时返回 400 提示；无 ffmpeg 时返回 400 提示。"""
    raw_url = (payload.url or "").strip()
    if not raw_url:
        raise HTTPException(status_code=400, detail="缺少视频 URL")
    src_path = output_file_from_url(raw_url)
    if not src_path or not os.path.isfile(src_path):
        raise HTTPException(status_code=404, detail="视频文件不存在")
    if os.path.getsize(src_path) > 200 * 1024 * 1024:
        raise HTTPException(status_code=413, detail="视频超过 200MB，请先压缩")
    strength = max(20, min(100, int(payload.strength or 60)))
    ks = strength if strength % 2 == 1 else strength + 1

    model_path = os.path.join(BASE_DIR, "assets", "models", "face_detection_yunet.onnx")
    if not os.path.isfile(model_path):
        raise HTTPException(status_code=400, detail="人脸检测模型缺失（assets/models/face_detection_yunet.onnx）")
    try:
        import cv2
    except ImportError:
        raise HTTPException(status_code=400, detail="服务器缺少 opencv-python-headless，无法做人脸检测")

    def _blur():
        cap = cv2.VideoCapture(src_path)
        if not cap.isOpened():
            raise RuntimeError("无法读取视频")
        fps = cap.get(cv2.CAP_PROP_FPS) or 25
        width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))
        height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))
        detector = cv2.FaceDetectorYN_create(model_path, "", (width, height), 0.6, 0.3, 5000)
        tmp_path = src_path + ".blur_tmp.avi"
        writer = cv2.VideoWriter(tmp_path, cv2.VideoWriter_fourcc(*'MJPG'), fps, (width, height))
        faces_total = 0
        frames = 0
        while True:
            ok, frame = cap.read()
            if not ok:
                break
            frames += 1
            _, faces = detector.detect(frame)
            if faces is not None and len(faces):
                faces_total += len(faces)
                for face in faces:
                    x, y, w, h = [int(v) for v in face[:4]]
                    pad_x = int(w * 0.15); pad_y = int(h * 0.25)
                    x0 = max(0, x - pad_x); y0 = max(0, y - pad_y)
                    x1 = min(width, x + w + pad_x); y1 = min(height, y + h + pad_y)
                    roi = frame[y0:y1, x0:x1]
                    if roi.size:
                        frame[y0:y1, x0:x1] = cv2.GaussianBlur(roi, (ks, ks), 0)
            writer.write(frame)
        cap.release()
        writer.release()
        out_filename = f"blurred_{uuid.uuid4().hex[:12]}.mp4"
        out_path = output_path_for(out_filename, "input")
        ffmpeg_bin = ffmpeg_binary()
        if not ffmpeg_bin:
            raise RuntimeError("未找到 ffmpeg，无法把模糊后的视频编码为 mp4")
        subprocess.run(
            [ffmpeg_bin, "-y", "-i", tmp_path, "-c:v", "libx264", "-preset", "fast",
             "-crf", "20", "-pix_fmt", "yuv420p", "-movflags", "+faststart", out_path],
            check=True, capture_output=True)
        try:
            os.remove(tmp_path)
        except OSError:
            pass
        return out_filename, out_path, frames, faces_total

    try:
        out_filename, out_path, frames, faces_total = await asyncio.to_thread(_blur)
    except subprocess.CalledProcessError as exc:
        raise HTTPException(status_code=500, detail=f"视频编码失败：{(exc.stderr or b'').decode('utf-8', errors='replace')[:300]}")
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"人脸模糊处理失败：{exc}")
    return {
        "url": output_url_for(out_filename, "input"),
        "name": f"模糊人脸_{uuid.uuid4().hex[:6]}.mp4",
        "kind": "video",
        "frames": frames,
        "faces_detected": faces_total,
    }


# ===== 第 10 轮：数据备份与迁移 =====
# 把画布、素材、各类库和设置打成一个 zip，换电脑或重装后一键导回。
# zip 布局：manifest.json + data/<DATA_DIR 相对路径> + assets/<ASSETS_DIR 相对路径>
#          + output/<OUTPUT_DIR 相对路径> + root/history.json + root/API/.env
# 导入是「合并」：本机已有的素材不覆盖；同 id 画布内容不同时另存为副本；
# 设置与各类库默认只补本机缺的文件，勾选「用备份覆盖设置」才替换（替换前自动做一份恢复前备份）。
BACKUP_DIR = os.path.join(DATA_DIR, "backups")
BACKUP_FORMAT = "novai-backup/1"
BACKUP_MEDIA_EXTS = {".png", ".jpg", ".jpeg", ".webp", ".gif", ".mp4", ".mov", ".webm", ".m4v", ".mp3", ".wav", ".m4a", ".aac", ".ogg", ".zip", ".onnx", ".avif", ".heic"}
# 数据目录里不进备份的：机器相关（LAN 口令）、可再生（预览缓存、任务记录）、备份自身、更新回滚包
BACKUP_DATA_SKIP_DIRS = {"backups", "media_previews", "tasks", "update_backups", "canvas_versions"}
BACKUP_DATA_SKIP_FILES = {"security.json"}
# 含 Key 的文件：不勾「包含 API Key」时整份跳过
BACKUP_KEY_FILES = {"api_providers.json"}
BACKUP_ASSET_REF_RE = re.compile(r"/(assets|output)/([^\"'\s)?#<>]+)")
_backup_state_lock = Lock()
_backup_job: Dict[str, Any] = {"id": "", "kind": "", "status": "idle", "percent": 0, "message": "", "result": None, "error": ""}
_backup_imports: Dict[str, Dict[str, Any]] = {}


def _backup_set(**kw):
    with _backup_state_lock:
        _backup_job.update(kw)


def _backup_busy() -> bool:
    with _backup_state_lock:
        return _backup_job.get("status") == "running"


def _backup_dir_size(path: str) -> Tuple[int, int]:
    total = count = 0
    for dirpath, _dirs, files in os.walk(path):
        for name in files:
            try:
                total += os.path.getsize(os.path.join(dirpath, name))
                count += 1
            except OSError:
                pass
    return total, count


def _backup_asset_roots() -> Dict[str, List[str]]:
    roots = {"assets": [ASSETS_DIR], "output": [OUTPUT_DIR]}
    if ASSETS_FALLBACK_DIR:
        roots["assets"].append(ASSETS_FALLBACK_DIR)
    return roots


def _backup_safe_rel(rel: str) -> str:
    rel = urllib.parse.unquote(str(rel or "")).replace("\\", "/").lstrip("/")
    parts = [p for p in rel.split("/") if p not in ("", ".")]
    if not parts or any(p == ".." for p in parts):
        return ""
    return "/".join(parts)


def _backup_data_files(include_keys: bool, include_versions: bool) -> List[Tuple[str, str]]:
    """(绝对路径, zip 内路径) —— 数据目录里要备份的文件。"""
    out = []
    skip_dirs = set(BACKUP_DATA_SKIP_DIRS)
    if include_versions:
        skip_dirs.discard("canvas_versions")
    for dirpath, dirs, files in os.walk(DATA_DIR):
        rel_dir = os.path.relpath(dirpath, DATA_DIR).replace("\\", "/")
        top = rel_dir.split("/")[0] if rel_dir != "." else ""
        if top in skip_dirs:
            dirs[:] = []
            continue
        if rel_dir == ".":
            dirs[:] = [d for d in dirs if d not in skip_dirs]
        for name in files:
            if name.startswith(".") or name.endswith((".tmp", ".lock")):
                continue
            if rel_dir == "." and name in BACKUP_DATA_SKIP_FILES:
                continue
            if rel_dir == "." and name in BACKUP_KEY_FILES and not include_keys:
                continue
            rel = name if rel_dir == "." else f"{rel_dir}/{name}"
            out.append((os.path.join(dirpath, name), "data/" + rel))
    if os.path.isfile(HISTORY_FILE):
        out.append((HISTORY_FILE, "root/history.json"))
    if include_keys and os.path.isfile(API_ENV_FILE):
        out.append((API_ENV_FILE, "root/API/.env"))
    return out


def _backup_referenced_assets(data_files: List[Tuple[str, str]]) -> Dict[str, str]:
    """扫描画布 / 素材库 / 历史里出现过的 /assets/… 和 /output/… 地址 → {zip 路径: 绝对路径}。"""
    roots = _backup_asset_roots()
    found: Dict[str, str] = {}
    for abs_path, arc in data_files:
        if not abs_path.endswith(".json"):
            continue
        try:
            with open(abs_path, "r", encoding="utf-8", errors="ignore") as f:
                text = f.read()
        except Exception:
            continue
        for kind, raw in BACKUP_ASSET_REF_RE.findall(text):
            rel = _backup_safe_rel(raw)
            if not rel:
                continue
            key = f"{kind}/{rel}"
            if key in found:
                continue
            for root in roots.get(kind, []):
                candidate = os.path.join(root, *rel.split("/"))
                if os.path.isfile(candidate):
                    found[key] = candidate
                    break
    return found


def _backup_all_assets() -> Dict[str, str]:
    found: Dict[str, str] = {}
    for kind, roots in _backup_asset_roots().items():
        for root in roots:
            if not root or not os.path.isdir(root):
                continue
            for dirpath, dirs, files in os.walk(root):
                rel_dir = os.path.relpath(dirpath, root).replace("\\", "/")
                # 本地模型（抠图 / 高清）体积大、可以重新下载，不进备份
                if kind == "assets" and (rel_dir == "models" or rel_dir.startswith("models/")):
                    dirs[:] = []
                    continue
                for name in files:
                    if name.startswith("."):
                        continue
                    rel = name if rel_dir == "." else f"{rel_dir}/{name}"
                    found.setdefault(f"{kind}/{rel}", os.path.join(dirpath, name))
    return found


def _backup_canvas_count() -> int:
    n = 0
    try:
        for name in os.listdir(CANVAS_DIR):
            if name.endswith(".json"):
                n += 1
    except Exception:
        pass
    return n


def _backup_list() -> List[Dict[str, Any]]:
    items = []
    try:
        for name in os.listdir(BACKUP_DIR):
            if not name.endswith(".zip") or name.startswith("incoming-"):
                continue
            path = os.path.join(BACKUP_DIR, name)
            manifest = {}
            try:
                with zipfile.ZipFile(path) as zf:
                    manifest = json.loads(zf.read("manifest.json").decode("utf-8"))
            except Exception:
                manifest = {}
            items.append({
                "name": name,
                "size": os.path.getsize(path),
                "created_at": int(manifest.get("created_at") or os.path.getmtime(path) * 1000),
                "counts": manifest.get("counts") or {},
                "options": manifest.get("options") or {},
                "kind": manifest.get("kind") or "manual",
            })
    except FileNotFoundError:
        pass
    return sorted(items, key=lambda x: x["created_at"], reverse=True)


def _backup_name_path(name: str) -> str:
    clean = os.path.basename(str(name or ""))
    if not clean.endswith(".zip") or clean != name:
        raise HTTPException(status_code=400, detail="无效的备份文件名")
    path = os.path.join(BACKUP_DIR, clean)
    if not os.path.isfile(path):
        raise HTTPException(status_code=404, detail="备份不存在")
    return path


def _backup_write_zip(target: str, entries: List[Tuple[str, str]], manifest: Dict[str, Any], progress_from=0, progress_to=100, label="正在打包") -> int:
    total_bytes = sum((os.path.getsize(p) if os.path.isfile(p) else 0) for p, _ in entries) or 1
    done = 0
    tmp = target + ".part"
    try:
        with zipfile.ZipFile(tmp, "w", allowZip64=True) as zf:
            zf.writestr("manifest.json", json.dumps(manifest, ensure_ascii=False, indent=2), compress_type=zipfile.ZIP_DEFLATED)
            for i, (abs_path, arc) in enumerate(entries):
                ext = os.path.splitext(abs_path)[1].lower()
                method = zipfile.ZIP_STORED if ext in BACKUP_MEDIA_EXTS else zipfile.ZIP_DEFLATED
                try:
                    zf.write(abs_path, arc, compress_type=method)
                    done += os.path.getsize(abs_path)
                except FileNotFoundError:
                    continue
                if i % 20 == 0:
                    pct = progress_from + (progress_to - progress_from) * done / total_bytes
                    _backup_set(percent=round(min(progress_to, pct), 1), message=f"{label}（{i + 1}/{len(entries)}）")
        os.replace(tmp, target)
    finally:
        if os.path.exists(tmp):
            try:
                os.remove(tmp)
            except OSError:
                pass
    return os.path.getsize(target)


def _backup_build(opts: Dict[str, Any], kind="manual") -> Dict[str, Any]:
    os.makedirs(BACKUP_DIR, exist_ok=True)
    include_keys = bool(opts.get("include_keys"))
    include_versions = bool(opts.get("include_versions"))
    asset_mode = opts.get("assets") if opts.get("assets") in ("referenced", "all", "none") else "referenced"
    _backup_set(percent=2, message="正在整理要备份的文件")
    data_files = _backup_data_files(include_keys, include_versions)
    if asset_mode == "all":
        assets = _backup_all_assets()
    elif asset_mode == "referenced":
        assets = _backup_referenced_assets(data_files)
    else:
        assets = {}
    entries = list(data_files) + [(abs_path, arc) for arc, abs_path in sorted(assets.items())]
    stamp = time.strftime("%Y%m%d-%H%M%S")
    prefix = "novai-backup" if kind == "manual" else "novai-pre-restore"
    target = os.path.join(BACKUP_DIR, f"{prefix}-{stamp}.zip")
    manifest = {
        "format": BACKUP_FORMAT,
        "kind": kind,
        "app_version": current_app_version() if callable(globals().get("current_app_version")) else APP_VERSION,
        "created_at": now_ms(),
        "platform": sys.platform,
        "options": {"assets": asset_mode, "include_keys": include_keys, "include_versions": include_versions},
        "counts": {
            "canvases": sum(1 for _, arc in data_files if arc.startswith("data/canvases/") and arc.endswith(".json")),
            "assets": len(assets),
            "data_files": len(data_files),
        },
    }
    size = _backup_write_zip(target, entries, manifest, 5, 99)
    return {"name": os.path.basename(target), "size": size, "counts": manifest["counts"], "options": manifest["options"]}


def _backup_run(kind: str, fn, *args):
    job_id = uuid.uuid4().hex[:10]
    _backup_set(id=job_id, kind=kind, status="running", percent=0, message="准备中", result=None, error="")

    def worker():
        try:
            result = fn(*args)
            _backup_set(status="done", percent=100, message="完成", result=result)
        except Exception as exc:  # noqa: BLE001
            traceback.print_exc()
            _backup_set(status="error", message="失败", error=str(exc)[:300])
    Thread(target=worker, daemon=True).start()
    return job_id


class BackupExportRequest(BaseModel):
    assets: str = "referenced"
    include_keys: bool = False
    include_versions: bool = False


class BackupImportApplyRequest(BaseModel):
    token: str
    overwrite_settings: bool = False


class BackupNameRequest(BaseModel):
    name: str


@app.get("/api/backup/summary")
def backup_summary():
    data_files = _backup_data_files(True, False)
    referenced = _backup_referenced_assets(data_files)
    ref_bytes = 0
    for p in referenced.values():
        try:
            ref_bytes += os.path.getsize(p)
        except OSError:
            pass
    all_bytes = all_count = 0
    for kind, roots in _backup_asset_roots().items():
        for root in roots:
            if root and os.path.isdir(root):
                b, c = _backup_dir_size(root)
                all_bytes += b
                all_count += c
    models_bytes, _ = _backup_dir_size(_MODELS_DIR) if os.path.isdir(_MODELS_DIR) else (0, 0)
    data_bytes = sum(os.path.getsize(p) for p, _ in data_files if os.path.isfile(p))
    versions_bytes, _ = _backup_dir_size(CANVAS_VERSIONS_DIR) if os.path.isdir(CANVAS_VERSIONS_DIR) else (0, 0)
    has_keys = os.path.isfile(API_PROVIDERS_FILE) or os.path.isfile(API_ENV_FILE)
    return {
        "canvases": _backup_canvas_count(),
        "data_bytes": data_bytes,
        "referenced_assets": len(referenced),
        "referenced_bytes": ref_bytes,
        "all_assets_bytes": max(0, all_bytes - models_bytes),
        "versions_bytes": versions_bytes,
        "has_keys": has_keys,
        "backup_dir": BACKUP_DIR,
        "backups": _backup_list(),
        "job": dict(_backup_job),
    }


@app.post("/api/backup/export")
def backup_export(req: BackupExportRequest):
    if _backup_busy():
        raise HTTPException(status_code=409, detail="已有备份或恢复任务在进行")
    job = _backup_run("export", _backup_build, req.model_dump(), "manual")
    return {"job": job}


@app.get("/api/backup/progress")
def backup_progress():
    with _backup_state_lock:
        return dict(_backup_job)


@app.get("/api/backup/list")
def backup_list():
    return {"backups": _backup_list(), "backup_dir": BACKUP_DIR}


@app.get("/api/backup/download/{name}")
def backup_download(name: str):
    path = _backup_name_path(name)
    return FileResponse(path, media_type="application/zip", filename=os.path.basename(path))


@app.delete("/api/backup/{name}")
def backup_delete(name: str):
    if _backup_busy():
        raise HTTPException(status_code=409, detail="有任务在进行，稍后再删")
    os.remove(_backup_name_path(name))
    return {"ok": True, "backups": _backup_list()}


@app.post("/api/backup/reveal")
def backup_reveal(req: BackupNameRequest, request: Request):
    if not is_loopback_host(request.client.host if request.client else ""):
        raise HTTPException(status_code=403, detail="只能在本机打开文件夹")
    os.makedirs(BACKUP_DIR, exist_ok=True)
    target = BACKUP_DIR
    if req.name:
        try:
            target = _backup_name_path(req.name)
        except HTTPException:
            target = BACKUP_DIR
    try:
        if sys.platform == "darwin":
            subprocess.Popen(["open", "-R", target] if os.path.isfile(target) else ["open", target])
        elif sys.platform.startswith("win"):
            subprocess.Popen(["explorer", "/select,", target] if os.path.isfile(target) else ["explorer", target])
        else:
            subprocess.Popen(["xdg-open", os.path.dirname(target) if os.path.isfile(target) else target])
    except Exception as exc:  # noqa: BLE001
        raise HTTPException(status_code=500, detail=f"打开文件夹失败：{exc}")
    return {"ok": True}


def _backup_canvas_digest(data: Dict[str, Any]) -> str:
    clean = {k: v for k, v in (data or {}).items() if k not in ("updated_at",)}
    return hashlib.sha1(json.dumps(clean, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()


def _backup_analyze(path: str) -> Dict[str, Any]:
    try:
        zf = zipfile.ZipFile(path)
    except zipfile.BadZipFile:
        raise HTTPException(status_code=400, detail="不是有效的 zip 文件")
    with zf:
        try:
            manifest = json.loads(zf.read("manifest.json").decode("utf-8"))
        except Exception:
            raise HTTPException(status_code=400, detail="这不是 NOVAI 的备份文件（缺少 manifest.json）")
        if manifest.get("format") != BACKUP_FORMAT:
            raise HTTPException(status_code=400, detail=f"不支持的备份格式：{manifest.get('format')}")
        canvases_new = canvases_same = canvases_conflict = 0
        assets_new = assets_existing = 0
        assets_bytes = 0
        settings_files: List[str] = []
        settings_missing: List[str] = []
        roots = {"assets": ASSETS_DIR, "output": OUTPUT_DIR}
        for info in zf.infolist():
            arc = info.filename
            if info.is_dir() or arc == "manifest.json":
                continue
            if arc.startswith("data/canvases/") and arc.endswith(".json") and arc.count("/") == 2:
                local = os.path.join(CANVAS_DIR, os.path.basename(arc))
                if not os.path.isfile(local):
                    canvases_new += 1
                    continue
                try:
                    remote_digest = _backup_canvas_digest(json.loads(zf.read(arc).decode("utf-8")))
                    with open(local, "r", encoding="utf-8") as f:
                        local_digest = _backup_canvas_digest(json.load(f))
                except Exception:
                    local_digest, remote_digest = "a", "b"
                if local_digest == remote_digest:
                    canvases_same += 1
                else:
                    canvases_conflict += 1
            elif arc.startswith(("assets/", "output/")):
                kind, _, rel = arc.partition("/")
                rel = _backup_safe_rel(rel)
                if not rel:
                    continue
                if os.path.isfile(os.path.join(roots[kind], *rel.split("/"))):
                    assets_existing += 1
                else:
                    assets_new += 1
                    assets_bytes += info.file_size
            elif arc.startswith("data/") and arc.count("/") == 1:
                name = arc[5:]
                settings_files.append(name)
                if not os.path.isfile(os.path.join(DATA_DIR, name)):
                    settings_missing.append(name)
            elif arc.startswith("root/"):
                rel = arc[5:]
                settings_files.append(rel)
                local = HISTORY_FILE if rel == "history.json" else API_ENV_FILE if rel == "API/.env" else ""
                if local and not os.path.isfile(local):
                    settings_missing.append(rel)
        return {
            "manifest": manifest,
            "canvases_new": canvases_new,
            "canvases_same": canvases_same,
            "canvases_conflict": canvases_conflict,
            "assets_new": assets_new,
            "assets_existing": assets_existing,
            "assets_new_bytes": assets_bytes,
            "settings_files": settings_files,
            "settings_missing": settings_missing,
            "has_keys": any(n in ("api_providers.json", "API/.env") for n in settings_files),
            "local_canvases": _backup_canvas_count(),
        }


def _backup_register_import(path: str, temporary: bool) -> Dict[str, Any]:
    preview = _backup_analyze(path)
    token = uuid.uuid4().hex
    _backup_imports[token] = {"path": path, "temporary": temporary, "created": time.time()}
    # 只留最近几份待确认的上传，老的连文件一起清掉
    for old in sorted(_backup_imports, key=lambda k: _backup_imports[k]["created"])[:-3]:
        item = _backup_imports.pop(old, None)
        if item and item.get("temporary"):
            try:
                os.remove(item["path"])
            except OSError:
                pass
    return {"token": token, "preview": preview}


@app.post("/api/backup/import/upload")
async def backup_import_upload(file: UploadFile = File(...)):
    if _backup_busy():
        raise HTTPException(status_code=409, detail="已有备份或恢复任务在进行")
    os.makedirs(BACKUP_DIR, exist_ok=True)
    target = os.path.join(BACKUP_DIR, f"incoming-{uuid.uuid4().hex[:8]}.zip")
    try:
        with open(target, "wb") as out:
            while True:
                chunk = await file.read(4 * 1024 * 1024)
                if not chunk:
                    break
                out.write(chunk)
        return _backup_register_import(target, True)
    except HTTPException:
        try:
            os.remove(target)
        except OSError:
            pass
        raise


@app.post("/api/backup/import/existing")
def backup_import_existing(req: BackupNameRequest):
    if _backup_busy():
        raise HTTPException(status_code=409, detail="已有备份或恢复任务在进行")
    return _backup_register_import(_backup_name_path(req.name), False)


def _backup_merge_projects(zf: zipfile.ZipFile, overwrite: bool) -> int:
    try:
        remote = json.loads(zf.read("data/projects.json").decode("utf-8"))
    except KeyError:
        return 0
    remote_list = remote.get("projects") if isinstance(remote, dict) else remote
    if not isinstance(remote_list, list):
        return 0
    local = load_projects()
    ids = {p.get("id") for p in local}
    added = 0
    for p in remote_list:
        if isinstance(p, dict) and p.get("id") and p.get("id") not in ids:
            local.append(p)
            ids.add(p.get("id"))
            added += 1
    if added:
        save_projects(local)
    return added


def _backup_apply(token: str, overwrite_settings: bool) -> Dict[str, Any]:
    item = _backup_imports.get(token)
    if not item or not os.path.isfile(item["path"]):
        raise RuntimeError("备份文件已失效，请重新选择")
    # 1) 恢复前先给本机数据（不含素材）拍一份快照，出问题可以原样导回
    _backup_set(percent=1, message="正在给本机数据做恢复前备份")
    safety = _backup_build({"assets": "none", "include_keys": True, "include_versions": False}, "pre-restore")
    _backup_set(percent=8, message="正在恢复")
    roots = {"assets": ASSETS_DIR, "output": OUTPUT_DIR}
    stats = {"canvases_added": 0, "canvases_copied": 0, "canvases_skipped": 0, "assets_added": 0, "assets_skipped": 0,
             "files_added": 0, "files_replaced": 0, "projects_added": 0, "safety_backup": safety.get("name")}
    with zipfile.ZipFile(item["path"]) as zf:
        infos = [i for i in zf.infolist() if not i.is_dir() and i.filename != "manifest.json"]
        total = sum(i.file_size for i in infos) or 1
        done = 0

        def extract_to(info, dest):
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            tmp = dest + ".restore-part"
            with zf.open(info) as src, open(tmp, "wb") as out:
                shutil.copyfileobj(src, out, 4 * 1024 * 1024)
            os.replace(tmp, dest)

        for n, info in enumerate(infos):
            arc = info.filename
            done += info.file_size
            if n % 20 == 0:
                _backup_set(percent=round(8 + 90 * done / total, 1), message=f"正在恢复（{n + 1}/{len(infos)}）")
            if arc.startswith(("assets/", "output/")):
                kind, _, rel = arc.partition("/")
                rel = _backup_safe_rel(rel)
                if not rel:
                    continue
                dest = os.path.join(roots[kind], *rel.split("/"))
                if os.path.exists(dest):
                    stats["assets_skipped"] += 1
                    continue
                extract_to(info, dest)
                stats["assets_added"] += 1
            elif arc.startswith("data/canvases/") and arc.count("/") == 2 and arc.endswith(".json"):
                try:
                    data = json.loads(zf.read(info).decode("utf-8"))
                except Exception:
                    continue
                local = os.path.join(CANVAS_DIR, os.path.basename(arc))
                if os.path.isfile(local):
                    try:
                        with open(local, "r", encoding="utf-8") as f:
                            same = _backup_canvas_digest(json.load(f)) == _backup_canvas_digest(data)
                    except Exception:
                        same = False
                    if same:
                        stats["canvases_skipped"] += 1
                        continue
                    # 同一个画布两边都改过：不覆盖本机，另存一份副本
                    data["id"] = uuid.uuid4().hex
                    data["title"] = f"{data.get('title') or '画布'}（备份）"
                    with CANVAS_LOCK:
                        write_json_atomic(canvas_path(data["id"]), data, ensure_ascii=False, indent=_CANVAS_JSON_INDENT)
                    stats["canvases_copied"] += 1
                else:
                    with CANVAS_LOCK:
                        write_json_atomic(local, data, ensure_ascii=False, indent=2)
                    stats["canvases_added"] += 1
            elif arc.startswith("data/"):
                rel = _backup_safe_rel(arc[5:])
                if not rel or rel == "projects.json" or rel.split("/")[0] in BACKUP_DATA_SKIP_DIRS - {"canvas_versions"} or rel in BACKUP_DATA_SKIP_FILES:
                    continue
                dest = os.path.join(DATA_DIR, *rel.split("/"))
                top_level = "/" not in rel
                if os.path.exists(dest):
                    # 顶层的设置 / 库文件：勾了覆盖才替换；子目录里的记录文件（对话、分镜…）按文件名合并，不覆盖
                    if top_level and overwrite_settings:
                        extract_to(info, dest)
                        stats["files_replaced"] += 1
                    continue
                extract_to(info, dest)
                stats["files_added"] += 1
            elif arc.startswith("root/"):
                rel = arc[5:]
                dest = HISTORY_FILE if rel == "history.json" else API_ENV_FILE if rel == "API/.env" else ""
                if not dest:
                    continue
                if os.path.exists(dest) and not overwrite_settings:
                    continue
                replaced = os.path.exists(dest)
                extract_to(info, dest)
                stats["files_replaced" if replaced else "files_added"] += 1
        stats["projects_added"] = _backup_merge_projects(zf, overwrite_settings)
    try:
        ensure_default_project()
    except Exception:
        pass
    if item.get("temporary"):
        try:
            os.remove(item["path"])
        except OSError:
            pass
    _backup_imports.pop(token, None)
    return stats


@app.post("/api/backup/import/apply")
def backup_import_apply(req: BackupImportApplyRequest):
    if _backup_busy():
        raise HTTPException(status_code=409, detail="已有备份或恢复任务在进行")
    if req.token not in _backup_imports:
        raise HTTPException(status_code=404, detail="备份文件已失效，请重新选择")
    job = _backup_run("import", _backup_apply, req.token, req.overwrite_settings)
    return {"job": job}


class VideoFrameRequest(BaseModel):
    url: str = ""
    which: str = "last"  # first | last


def _video_probe_size(ffprobe, src):
    """ffprobe 取视频宽高；失败返回 (0, 0)。"""
    if not ffprobe:
        return 0, 0
    try:
        proc = subprocess.run(
            [ffprobe, "-v", "error", "-select_streams", "v:0", "-show_entries", "stream=width,height", "-of", "csv=p=0:s=x", src],
            capture_output=True, text=True, timeout=30,
        )
        w, h = (proc.stdout or "").strip().split("\n")[0].split("x")[:2]
        return int(w), int(h)
    except Exception:
        return 0, 0


@app.post("/api/video/frame")
async def video_extract_frame(payload: VideoFrameRequest):
    """取视频首帧 / 尾帧存成 PNG（尾帧接力、截帧成图用）。有 ffmpeg 用 ffmpeg，否则用 opencv 兜底。"""
    raw_url = (payload.url or "").strip()
    if not raw_url:
        raise HTTPException(status_code=400, detail="缺少视频 URL")
    src_path = output_file_from_url(raw_url)
    if not src_path or not os.path.isfile(src_path):
        raise HTTPException(status_code=404, detail="视频文件不存在（只支持画布里的本地视频）")
    which = "first" if str(payload.which or "").lower() == "first" else "last"
    out_filename = f"{which}_frame_{uuid.uuid4().hex[:12]}.png"
    out_path = output_path_for(out_filename, "input")

    def _grab():
        ffmpeg = ffmpeg_binary()
        if ffmpeg:
            if which == "first":
                cmd = [ffmpeg, "-hide_banner", "-loglevel", "error", "-y", "-i", src_path, "-frames:v", "1", out_path]
            else:
                # -sseof 从结尾往前 0.5 秒开始读，-update 1 持续覆盖同一张图，最后留下的就是最后一帧
                cmd = [ffmpeg, "-hide_banner", "-loglevel", "error", "-y", "-sseof", "-0.5", "-i", src_path, "-update", "1", out_path]
            proc = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
            if proc.returncode == 0 and os.path.isfile(out_path) and os.path.getsize(out_path) > 0:
                return
        import cv2
        cap = cv2.VideoCapture(src_path)
        try:
            if not cap.isOpened():
                raise RuntimeError("无法读取视频")
            frame = None
            if which == "first":
                ok, frame = cap.read()
                frame = frame if ok else None
            else:
                total = int(cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
                for back in (1, 2, 3, 5, 10):
                    if total - back < 0:
                        break
                    cap.set(cv2.CAP_PROP_POS_FRAMES, total - back)
                    ok, candidate = cap.read()
                    if ok and candidate is not None:
                        frame = candidate
                        break
                if frame is None:
                    cap.set(cv2.CAP_PROP_POS_FRAMES, 0)
                    while True:
                        ok, candidate = cap.read()
                        if not ok or candidate is None:
                            break
                        frame = candidate
            if frame is None:
                raise RuntimeError("没有读到视频帧")
            if not cv2.imwrite(out_path, frame):
                raise RuntimeError("保存帧图片失败")
        finally:
            cap.release()

    try:
        await asyncio.to_thread(_grab)
        with Image.open(out_path) as img:
            width, height = img.size
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"取{'首' if which == 'first' else '尾'}帧失败：{exc}")
    base = os.path.splitext(os.path.basename(src_path))[0][:40] or "video"
    return {
        "url": output_url_for(out_filename, "input"),
        "name": f"{base}-{'首帧' if which == 'first' else '尾帧'}.png",
        "kind": "image",
        "width": width,
        "height": height,
    }


class VideoConcatRequest(BaseModel):
    urls: List[str] = []
    filename: str = ""


@app.post("/api/video/concat")
async def video_concat(payload: VideoConcatRequest):
    """把画布里选中的多段视频按顺序拼成一条。分辨率统一成第一段的尺寸（等比缩放 + 补边），30fps；
    全部有音轨时保留音频，否则统一用静音轨，保证拼接时各段参数一致。"""
    ffmpeg = ffmpeg_binary()
    if not ffmpeg:
        raise HTTPException(status_code=400, detail="未找到 ffmpeg，无法拼接视频")
    urls = [str(u or "").strip() for u in (payload.urls or []) if str(u or "").strip()]
    if len(urls) < 2:
        raise HTTPException(status_code=400, detail="至少需要两段视频")
    if len(urls) > 30:
        raise HTTPException(status_code=400, detail="一次最多拼接 30 段")
    sources = []
    for url in urls:
        src = output_file_from_url(url)
        if not src or not os.path.isfile(src):
            raise HTTPException(status_code=400, detail="只支持画布里的本地视频（有一段找不到文件）")
        sources.append(src)
    ffprobe = ffprobe_binary()
    width, height = _video_probe_size(ffprobe, sources[0])
    if width <= 0 or height <= 0:
        width, height = 1280, 720
    width -= width % 2
    height -= height % 2
    preserve_audio = bool(ffprobe)
    if ffprobe:
        for src in sources:
            probe = await asyncio.to_thread(
                subprocess.run,
                [ffprobe, "-v", "error", "-select_streams", "a:0", "-show_entries", "stream=index", "-of", "csv=p=0", src],
                capture_output=True, text=True, timeout=30,
            )
            if probe.returncode != 0 or not (probe.stdout or "").strip():
                preserve_audio = False
                break
    vf = f"scale={width}:{height}:force_original_aspect_ratio=decrease,pad={width}:{height}:(ow-iw)/2:(oh-ih)/2,setsar=1,fps=30"
    tmpdir = tempfile.mkdtemp(prefix="video_concat_")
    try:
        parts = []
        for index, src in enumerate(sources):
            part = os.path.join(tmpdir, f"part_{index:03d}.mp4")
            if preserve_audio:
                cmd = [ffmpeg, "-hide_banner", "-loglevel", "error", "-y", "-i", src,
                       "-map", "0:v:0", "-map", "0:a:0", "-vf", vf,
                       "-c:v", "libx264", "-preset", "veryfast", "-pix_fmt", "yuv420p",
                       "-c:a", "aac", "-ar", "48000", "-ac", "2", "-movflags", "+faststart", part]
            else:
                cmd = [ffmpeg, "-hide_banner", "-loglevel", "error", "-y", "-i", src,
                       "-f", "lavfi", "-i", "anullsrc=channel_layout=stereo:sample_rate=48000",
                       "-map", "0:v:0", "-map", "1:a:0", "-vf", vf, "-shortest",
                       "-c:v", "libx264", "-preset", "veryfast", "-pix_fmt", "yuv420p",
                       "-c:a", "aac", "-ar", "48000", "-ac", "2", "-movflags", "+faststart", part]
            proc = await asyncio.to_thread(subprocess.run, cmd, capture_output=True, text=True, timeout=600)
            if proc.returncode != 0:
                raise HTTPException(status_code=500, detail=f"第 {index + 1} 段转码失败：{(proc.stderr or '').strip()[:240]}")
            parts.append(part)
        list_path = os.path.join(tmpdir, "concat.txt")
        with open(list_path, "w", encoding="utf-8") as fh:
            for part in parts:
                safe_part = part.replace("\\", "/").replace("'", "'\\''")
                fh.write(f"file '{safe_part}'\n")
        filename = sanitize_export_filename(payload.filename or f"拼接_{len(parts)}段.mp4", "video-concat.mp4")
        if not filename.lower().endswith(".mp4"):
            filename += ".mp4"
        filename = f"{os.path.splitext(filename)[0]}_{uuid.uuid4().hex[:6]}.mp4"
        output_path = output_path_for(filename, "output")
        cmd = [ffmpeg, "-hide_banner", "-loglevel", "error", "-y", "-f", "concat", "-safe", "0", "-i", list_path,
               "-c", "copy", "-movflags", "+faststart", output_path]
        proc = await asyncio.to_thread(subprocess.run, cmd, capture_output=True, text=True, timeout=600)
        if proc.returncode != 0:
            raise HTTPException(status_code=500, detail=f"视频拼接失败：{(proc.stderr or '').strip()[:240]}")
        return {"url": output_url_for(filename, "output"), "name": filename, "kind": "video", "width": width, "height": height, "segments": len(parts)}
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)


class TimelineRenderClip(BaseModel):
    id: str = ""
    url: str = ""
    track: str = "video"           # video | audio
    kind: str = ""                 # video | image | audio（空 = 按 track）
    timelineStartMs: int = 0
    durationMs: int = 0
    sourceInMs: int = 0
    sourceOutMs: int = 0
    speed: float = 1.0
    volume: float = 1.0
    fadeInMs: int = 0
    fadeOutMs: int = 0
    transitionIn: Optional[Dict[str, Any]] = None


class TimelineRenderRequest(BaseModel):
    clips: List[TimelineRenderClip] = []
    durationMs: int = 0
    width: int = 1280
    height: int = 720
    fps: int = 30
    srt: str = ""
    subStyle: Optional[Dict[str, Any]] = None
    filename: str = ""


def _timeline_atempo_chain(speed):
    """atempo 单级只支持 0.5–2：超出就串几级。"""
    speed = max(0.25, min(4.0, float(speed or 1)))
    parts = []
    while speed > 2.0:
        parts.append("atempo=2.0")
        speed /= 2.0
    while speed < 0.5:
        parts.append("atempo=0.5")
        speed /= 0.5
    if abs(speed - 1.0) > 1e-3:
        parts.append(f"atempo={speed:.4f}")
    return parts


def _timeline_has_audio(ffprobe, path):
    if not ffprobe:
        return False
    try:
        probe = subprocess.run([ffprobe, "-v", "error", "-select_streams", "a:0", "-show_entries", "stream=index",
                                "-of", "csv=p=0", path], capture_output=True, text=True, timeout=30)
        return probe.returncode == 0 and bool((probe.stdout or "").strip())
    except Exception:
        return False


def _timeline_render_sync(payload, sources, tmpdir):
    """按剪辑时间线渲染 MP4：画面按片段顺序拼接（交叉溶解用 xfade、黑场淡入用 fade），声音全部按时间轴位置混音。"""
    ffmpeg = ffmpeg_binary()
    ffprobe = ffprobe_binary()
    W = max(16, int(payload.width) // 2 * 2)
    H = max(16, int(payload.height) // 2 * 2)
    fps = max(10, min(60, int(payload.fps or 30)))
    total = max(0.1, payload.durationMs / 1000.0)
    vclips = sorted([c for c in payload.clips if c.track == "video"], key=lambda c: c.timelineStartMs)
    aclips = [c for c in payload.clips if c.track == "audio"]
    if not vclips:
        raise HTTPException(status_code=400, detail="视频轨上还没有片段")
    inputs, filters, audio_labels = [], [], []

    def add_input(args):
        inputs.extend(args)
        return sum(1 for a in inputs if a == "-i") - 1

    norm = f"scale={W}:{H}:force_original_aspect_ratio=decrease,pad={W}:{H}:(ow-iw)/2:(oh-ih)/2:color=black,setsar=1,fps={fps},format=yuv420p"
    vlabels = []
    for i, c in enumerate(vclips):
        path = sources[c.url]
        dur = max(0.1, c.durationMs / 1000.0)
        speed = max(0.25, min(4.0, float(c.speed or 1)))
        kind = c.kind or "video"
        if kind == "image":
            idx = add_input(["-loop", "1", "-framerate", str(fps), "-t", f"{dur:.3f}", "-i", path])
            filters.append(f"[{idx}:v]{norm},trim=duration={dur:.3f},setpts=PTS-STARTPTS[v{i}]")
        else:
            src_in = max(0.0, c.sourceInMs / 1000.0)
            src_len = dur * speed
            idx = add_input(["-ss", f"{src_in:.3f}", "-t", f"{src_len + 0.05:.3f}", "-i", path])
            filters.append(f"[{idx}:v]setpts=(PTS-STARTPTS)/{speed:.4f},{norm},trim=duration={dur:.3f},setpts=PTS-STARTPTS[v{i}]")
            if _timeline_has_audio(ffprobe, path) and float(c.volume or 0) > 0:
                chain = [f"[{idx}:a]atrim=duration={src_len:.3f}", "asetpts=PTS-STARTPTS"] + _timeline_atempo_chain(speed)
                chain += [f"volume={float(c.volume):.3f}"]
                if c.fadeInMs > 0:
                    chain.append(f"afade=t=in:st=0:d={c.fadeInMs / 1000.0:.3f}")
                if c.fadeOutMs > 0:
                    chain.append(f"afade=t=out:st={max(0.0, dur - c.fadeOutMs / 1000.0):.3f}:d={c.fadeOutMs / 1000.0:.3f}")
                delay = max(0, int(c.timelineStartMs))
                chain += [f"adelay={delay}|{delay}", "aformat=sample_rates=48000:channel_layouts=stereo"]
                filters.append(",".join(chain) + f"[av{i}]")
                audio_labels.append(f"[av{i}]")
        vlabels.append((f"[v{i}]", c, dur))
    # 画面：按顺序串起来
    acc, acc_end = None, 0.0
    for i, (label, c, dur) in enumerate(vlabels):
        tr = c.transitionIn or {}
        tdur = max(0.0, float(tr.get("durationMs") or 0) / 1000.0)
        ttype = str(tr.get("type") or "")
        if ttype == "fade" and tdur > 0:
            filters.append(f"{label}fade=t=in:st=0:d={min(tdur, dur):.3f}[vf{i}]")
            label = f"[vf{i}]"
        if acc is None:
            acc, acc_end = label, dur
            continue
        if ttype == "dissolve" and tdur > 0:
            offset = max(0.0, acc_end - tdur)
            filters.append(f"{acc}{label}xfade=transition=fade:duration={tdur:.3f}:offset={offset:.3f}[vx{i}]")
            acc, acc_end = f"[vx{i}]", offset + dur
        else:
            filters.append(f"{acc}{label}concat=n=2:v=1:a=0[vx{i}]")
            acc, acc_end = f"[vx{i}]", acc_end + dur
    if total > acc_end + 0.04:
        filters.append(f"{acc}tpad=stop_mode=add:stop_duration={total - acc_end:.3f}:color=black[vpad]")
        acc = "[vpad]"
    # 声音轨
    for j, c in enumerate(aclips):
        path = sources[c.url]
        if float(c.volume or 0) <= 0:
            continue
        dur = max(0.1, c.durationMs / 1000.0)
        speed = max(0.25, min(4.0, float(c.speed or 1)))
        src_in = max(0.0, c.sourceInMs / 1000.0)
        idx = add_input(["-ss", f"{src_in:.3f}", "-t", f"{dur * speed + 0.05:.3f}", "-i", path])
        chain = [f"[{idx}:a]atrim=duration={dur * speed:.3f}", "asetpts=PTS-STARTPTS"] + _timeline_atempo_chain(speed)
        chain += [f"volume={float(c.volume):.3f}"]
        tr = c.transitionIn or {}
        fin = max(c.fadeInMs / 1000.0, float(tr.get("durationMs") or 0) / 1000.0 if tr else 0)
        if fin > 0:
            chain.append(f"afade=t=in:st=0:d={fin:.3f}")
        if c.fadeOutMs > 0:
            chain.append(f"afade=t=out:st={max(0.0, dur - c.fadeOutMs / 1000.0):.3f}:d={c.fadeOutMs / 1000.0:.3f}")
        delay = max(0, int(c.timelineStartMs))
        chain += [f"adelay={delay}|{delay}", "aformat=sample_rates=48000:channel_layouts=stereo"]
        filters.append(",".join(chain) + f"[aa{j}]")
        audio_labels.append(f"[aa{j}]")
    if audio_labels:
        filters.append("".join(audio_labels) + f"amix=inputs={len(audio_labels)}:duration=longest:dropout_transition=0,"
                       f"volume={len(audio_labels)},atrim=duration={total:.3f}[aout]")
    else:
        idx = add_input(["-f", "lavfi", "-t", f"{total:.3f}", "-i", "anullsrc=channel_layout=stereo:sample_rate=48000"])
        filters.append(f"[{idx}:a]anull[aout]")
    vout = acc
    srt_path = ""
    if str(payload.srt or "").strip():
        srt_path = os.path.join(tmpdir, "subs.srt")
        with open(srt_path, "w", encoding="utf-8") as fh:
            fh.write(payload.srt)
    style = payload.subStyle or {}
    size_px = {"s": 0.036, "m": 0.048, "l": 0.064}.get(str(style.get("size") or "m"), 0.048) * min(W, H)
    align = {"top": 8, "middle": 5}.get(str(style.get("pos") or "bottom"), 2)
    out_name = sanitize_export_filename(payload.filename or "剪辑时间线.mp4", "timeline.mp4")
    if not out_name.lower().endswith(".mp4"):
        out_name += ".mp4"
    out_name = f"{os.path.splitext(out_name)[0]}_{uuid.uuid4().hex[:6]}.mp4"
    out_path = output_path_for(out_name, "output")

    def run(with_subs):
        graph = list(filters)
        final_v = vout
        if with_subs and srt_path:
            # libass 的字号按 PlayResY=288 换算：先换成这个基准下的字号
            fs = max(8, round(size_px * 288 / H))
            esc = srt_path.replace("\\", "/").replace(":", "\\:").replace("'", "\\'")
            graph.append(f"{vout}subtitles='{esc}':force_style='FontSize={fs},Alignment={align},Outline=2,Shadow=0,MarginV=18'[vsub]")
            final_v = "[vsub]"
        cmd = [ffmpeg, "-hide_banner", "-loglevel", "error", "-y", *inputs, "-filter_complex", ";".join(graph),
               "-map", final_v, "-map", "[aout]", "-t", f"{total:.3f}",
               "-c:v", "libx264", "-preset", "veryfast", "-crf", "20", "-pix_fmt", "yuv420p", "-r", str(fps),
               "-c:a", "aac", "-b:a", "192k", "-ar", "48000", "-ac", "2", "-movflags", "+faststart", out_path]
        return subprocess.run(cmd, capture_output=True, text=True, timeout=1800)

    proc = run(True)
    subtitles_dropped = False
    if proc.returncode != 0 and srt_path:
        proc = run(False)
        subtitles_dropped = proc.returncode == 0
    if proc.returncode != 0:
        raise HTTPException(status_code=500, detail=f"时间线渲染失败：{(proc.stderr or '').strip()[-400:]}")
    return {"url": output_url_for(out_name, "output"), "name": out_name, "kind": "video", "width": W, "height": H,
            "duration": round(total, 3), "subtitlesDropped": subtitles_dropped}


@app.post("/api/timeline/render")
async def timeline_render(payload: TimelineRenderRequest):
    """智能画布 剪辑时间线导出 MP4：片段位置 / 修剪 / 变速 / 音量 / 淡入淡出 / 转场 / 字幕 / 画幅全部按时间线渲染。"""
    if not ffmpeg_binary():
        raise HTTPException(status_code=400, detail="未找到 ffmpeg，无法导出 MP4（可以先用「导出 WebM」）")
    clips = [c for c in (payload.clips or []) if str(c.url or "").strip()]
    if not clips:
        raise HTTPException(status_code=400, detail="时间线上还没有片段")
    if len(clips) > 120:
        raise HTTPException(status_code=400, detail="一次最多导出 120 个片段")
    payload.clips = clips
    tmpdir = tempfile.mkdtemp(prefix="timeline_render_")
    try:
        sources = {}
        for c in clips:
            url = str(c.url).strip()
            if url in sources:
                continue
            src = output_file_from_url(url)
            if (not src or not os.path.isfile(src)) and (url.startswith("http://") or url.startswith("https://")):
                try:
                    src = await asyncio.to_thread(download_video_url_to_temp, url)
                except Exception as exc:
                    raise HTTPException(status_code=400, detail=f"下载片段素材失败：{exc}")
            if not src or not os.path.isfile(src):
                raise HTTPException(status_code=400, detail="有片段的素材文件找不到了（可能已被删除）")
            sources[url] = src
        return await asyncio.to_thread(_timeline_render_sync, payload, sources, tmpdir)
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)


class VideoSegmentsRequest(BaseModel):
    url: str = ""
    # seconds/max_segments 用宽松类型：非法值按接口约定回退缺省，Pydantic 严格校验会先拦成 422
    seconds: Any = None
    max_segments: Any = None

@app.post("/api/video/segments")
async def video_segments(payload: VideoSegmentsRequest):
    """参考视频按秒切分，供前端「视频分镜表」自动分解镜头（每段带一张首帧图）。
    产物存 assets/input/segments/<key>/；同源同参数重复请求复用已有片段，不重复转码。"""
    raw_url = str(payload.url or "").strip()
    if not raw_url:
        raise HTTPException(status_code=400, detail="缺少视频 URL")
    if raw_url.startswith("http://") or raw_url.startswith("https://"):
        try:
            src_path = await asyncio.to_thread(download_video_url_to_temp, raw_url)
        except Exception as exc:
            raise HTTPException(status_code=400, detail=f"下载远程视频失败：{exc}")
    else:
        src_path = output_file_from_url(raw_url)
        if not src_path or not os.path.isfile(src_path):
            raise HTTPException(status_code=400, detail=f"找不到视频文件：{raw_url}")
    if not ffprobe_binary():
        raise HTTPException(status_code=400, detail="服务器缺少 ffprobe，无法读取视频时长")
    if not ffmpeg_binary():
        raise HTTPException(status_code=400, detail="服务器缺少 ffmpeg，无法切分视频")
    duration = probe_video_file_duration_seconds(src_path)
    if not duration or duration <= 0:
        raise HTTPException(status_code=400, detail="读取视频时长失败，请确认是有效视频文件")
    try:
        result = await asyncio.to_thread(build_video_segments, src_path, duration, payload.seconds, payload.max_segments)
    except Exception as exc:
        raise HTTPException(status_code=400, detail=f"视频切分失败：{exc}")
    return {"ok": True, **result}


class ImageMattingRequest(BaseModel):
    url: str = ""            # 本地图片 URL（/assets/ 或 /output/ 开头）
    mode: str = "api"        # api=生图API绿幕抠图（默认）；local=本地 RMBG-2.0 推理


class ImageUpscaleRequest(BaseModel):
    url: str = ""            # 本地图片 URL（/assets/ 或 /output/ 开头）
    target: str              # 必填：2k=长边2048；4k=长边4096（给默认值会让漏传的请求白跑一次超分）


_MATTING_MODEL_PATH = os.path.join(_MODELS_DIR, "rmbg_2.0.onnx")
_MATTING_MODEL_URL = "https://modelscope.cn/models/briaai/RMBG-2.0/resolve/master/onnx/model_quantized.onnx"
_MATTING_MODEL_SIZE = 366087549  # 量化版约 349MB，用于无 Content-Length 时的进度估算
_OLD_MATTING_MODEL_PATH = os.path.join(_MODELS_DIR, "rmbg_1.4.onnx")
_MATTING_MODEL_SHA256 = "fcea23951a378f92634834888896cc1eec54655366ae6e949282646ce17c5420"  # 魔搭 LFS 的 X-Linked-Etag
_MATTING_SESSION = None
_MATTING_LOAD_ERROR = {"msg": ""}
_MODEL_DOWNLOAD_TASKS = {}


def _matting_unavailable_reason() -> str:
    if not _matting_model_downloaded():
        return "本地抠图模型未下载"
    return _MATTING_LOAD_ERROR.get("msg") or "本地抠图模型加载失败"


def _matting_runtime_ready() -> bool:
    """本地推理组件是否装了（只查 import，不加载 349MB 模型：状态接口要快）。"""
    try:
        import importlib.util
        return importlib.util.find_spec("onnxruntime") is not None
    except Exception:
        return False

def _matting_runtime_missing_message() -> str:
    """onnxruntime 缺失时的用户文案：开发态指路 venv/pip，安装包才提示更新包。"""
    try:
        frozen = bool(getattr(sys, "frozen", False))
    except Exception:
        frozen = False
    if frozen:
        return "缺少推理组件 onnxruntime，请更新到最新安装包"
    return ("缺少推理组件 onnxruntime：开发版请用项目 venv/bin/python3 启动，"
            "或执行 venv/bin/pip install onnxruntime")


def _cleanup_old_matting_model():
    if os.path.isfile(_OLD_MATTING_MODEL_PATH):
        try:
            os.remove(_OLD_MATTING_MODEL_PATH)
            print(f"[Matting] 已删除旧版 RMBG-1.4 模型：{_OLD_MATTING_MODEL_PATH}")
        except OSError:
            pass


def _matting_session():
    """RMBG-2.0 抠图推理会话（单例缓存）。模型未下载时返回 None，由接口层决定报 400。"""
    global _MATTING_SESSION
    if _MATTING_SESSION is not None:
        return _MATTING_SESSION
    model_path = _models_path("rmbg_2.0.onnx")
    if not os.path.isfile(model_path):
        return None
    try:
        import onnxruntime
    except ImportError as exc:
        _MATTING_LOAD_ERROR["msg"] = _matting_runtime_missing_message()
        # 真实异常打出来（缺 numpy / dylib / ABI 不匹配都长这样），否则只剩一句兜底文案没法排查
        print(f"[Matting] 导入 onnxruntime 失败：{type(exc).__name__}: {exc}", file=sys.stderr, flush=True)
        return None
    try:
        sess = onnxruntime.InferenceSession(model_path, providers=["CPUExecutionProvider"])
    except Exception as exc:
        _MATTING_LOAD_ERROR["msg"] = f"模型文件无法加载（可能已损坏，请在抠图时重新下载）：{str(exc)[:120]}"
        return None
    _MATTING_LOAD_ERROR["msg"] = ""
    _MATTING_SESSION = sess
    _cleanup_old_matting_model()
    return sess


def run_image_matting(src_path: str, out_path: str):
    """本地 RMBG-2.0 抠图：读图 → 1024 推理 → mask 放大 → 原图引导修边 + 前景色去污染（server/matting_refine.py）→ 透明 PNG。"""
    import numpy as np
    import cv2
    from server import matting_refine as _mr
    img = Image.open(src_path)
    img = ImageOps.exif_transpose(img) if hasattr(ImageOps, "exif_transpose") else img
    img = img.convert("RGB")
    orig_w, orig_h = img.size
    img_1024 = img.resize((1024, 1024), Image.BILINEAR)
    arr = np.array(img_1024).astype(np.float32) / 255.0
    arr = (arr - np.array([0.485, 0.456, 0.406], np.float32)) / np.array([0.229, 0.224, 0.225], np.float32)
    arr = arr.transpose(2, 0, 1)[None]
    sess = _matting_session()
    if sess is None:
        raise RuntimeError(_matting_unavailable_reason())
    out = sess.run(None, {sess.get_inputs()[0].name: arr})[-1]
    mask = np.clip(out[0, 0].astype(np.float32), 0.0, 1.0)  # 此 ONNX 导出已内置 sigmoid
    coarse = cv2.resize(mask, (orig_w, orig_h), interpolation=cv2.INTER_LINEAR)
    rgba = _mr.mask_to_rgba(np.array(img), coarse)
    Image.fromarray(rgba, "RGBA").save(out_path)


def _matting_model_downloaded() -> bool:
    path = _models_path("rmbg_2.0.onnx")
    return os.path.isfile(path) and os.path.getsize(path) >= _MATTING_MODEL_SIZE - 1024


def _friendly_download_error(exc) -> str:
    text = str(exc)
    if isinstance(exc, requests.exceptions.SSLError) or "CERTIFICATE" in text.upper():
        return "安全证书校验失败（可能是代理或系统时间不对），请检查网络设置后重试"
    if isinstance(exc, (requests.exceptions.ConnectionError, requests.exceptions.Timeout)) or "timed out" in text.lower():
        return "网络连接中断或超时，已下载的部分会保留，点重试会接着下"
    if isinstance(exc, requests.exceptions.HTTPError):
        code = getattr(getattr(exc, "response", None), "status_code", "")
        return f"下载源返回错误（HTTP {code}），请稍后重试"
    if isinstance(exc, OSError) and getattr(exc, "errno", None) in (28,):
        return "磁盘空间不足，模型需要约 350MB 空间"
    return text[:200] or "未知错误"


def _download_matting_model(task_id: str):
    """后台下载 RMBG-2.0：写 .part，支持断点续传（Range），失败自动重试（指数退避），
    下完校验大小与 SHA256 再改名；进度/速度/剩余时间写入 _MODEL_DOWNLOAD_TASKS。"""
    task = _MODEL_DOWNLOAD_TASKS[task_id]
    part = _MATTING_MODEL_PATH + ".part"
    os.makedirs(os.path.dirname(_MATTING_MODEL_PATH), exist_ok=True)
    for legacy in (_MATTING_MODEL_PATH + ".tmp",):
        try:
            if os.path.exists(legacy):
                os.remove(legacy)
        except OSError:
            pass
    total = _MATTING_MODEL_SIZE
    task["total"] = total
    max_attempts = 8
    last_exc = None
    for attempt in range(1, max_attempts + 1):
        if task.get("cancel"):
            break
        have = os.path.getsize(part) if os.path.exists(part) else 0
        if have > total:
            os.remove(part)
            have = 0
        if have == total:
            break
        task["attempt"] = attempt
        headers = {"Range": f"bytes={have}-"} if have else {}
        try:
            with requests.get(_MATTING_MODEL_URL, stream=True, timeout=(20, 60), headers=headers) as resp:
                if resp.status_code == 416:
                    break
                resp.raise_for_status()
                append = bool(have) and resp.status_code == 206
                if not append:
                    have = 0
                length = int(resp.headers.get("Content-Length") or 0)
                if length:
                    total = have + length
                    task["total"] = total
                done = have
                last_t, last_b = time.time(), done
                with open(part, "ab" if append else "wb") as fh:
                    for chunk in resp.iter_content(chunk_size=256 * 1024):
                        if task.get("cancel"):
                            break
                        if not chunk:
                            continue
                        fh.write(chunk)
                        done += len(chunk)
                        now = time.time()
                        if now - last_t >= 0.5:
                            speed = (done - last_b) / (now - last_t)
                            task["speed"] = speed if not task.get("speed") else task["speed"] * 0.6 + speed * 0.4
                            last_t, last_b = now, done
                        task["downloaded"] = done
                        task["progress"] = min(99, int(done * 100 / max(1, total)))
            task["error"] = ""
            if task.get("cancel"):
                break
            if os.path.getsize(part) >= total:
                break
        except Exception as exc:
            last_exc = exc
            task["error_hint"] = _friendly_download_error(exc)
            print(f"[Matting] 模型下载中断（第 {attempt}/{max_attempts} 次）: {exc}")
            wait = min(20, 2 ** attempt)
            for _ in range(wait * 2):
                if task.get("cancel"):
                    break
                time.sleep(0.5)
    if task.get("cancel"):
        task.update({"downloading": False, "cancelled": True, "speed": 0, "error": ""})
        print("[Matting] 用户取消了模型下载（已下载部分保留，下次接着下）")
        return
    try:
        size = os.path.getsize(part) if os.path.exists(part) else 0
        if size < total:
            raise RuntimeError(task.get("error_hint") or _friendly_download_error(last_exc) if last_exc else "下载未完成")
        task["verifying"] = True
        if total == _MATTING_MODEL_SIZE:
            h = hashlib.sha256()
            with open(part, "rb") as fh:
                for blk in iter(lambda: fh.read(4 * 1024 * 1024), b""):
                    h.update(blk)
            if h.hexdigest() != _MATTING_MODEL_SHA256:
                os.remove(part)
                raise RuntimeError("模型文件校验失败（下载内容损坏），已清除，请重试")
        os.replace(part, _MATTING_MODEL_PATH)
        global _MATTING_SESSION
        _MATTING_SESSION = None
        _cleanup_old_matting_model()
        task.update({"downloading": False, "verifying": False, "progress": 100, "done": True, "error": "", "speed": 0})
        print(f"[Matting] 本地抠图模型下载完成并通过校验：{_MATTING_MODEL_PATH}")
    except Exception as exc:
        task.update({"downloading": False, "verifying": False, "speed": 0, "error": str(exc)[:200]})
        print(f"[Matting] 模型下载失败: {exc}")


@app.get("/api/matting/model/status")
async def matting_model_status():
    """本地抠图模型状态：是否已下载、下载进度 / 速度 / 剩余时间、可读错误。"""
    task = _MODEL_DOWNLOAD_TASKS.get("matting_model_download") or {}
    downloaded = _matting_model_downloaded()
    part = _MATTING_MODEL_PATH + ".part"
    got = int(task.get("downloaded") or (os.path.getsize(part) if os.path.exists(part) else 0))
    total = int(task.get("total") or _MATTING_MODEL_SIZE)
    speed = float(task.get("speed") or 0)
    # 已下载完时进度按「满」算：以前 downloaded_mb 会显示 0 让人以为没下
    shown = total if downloaded else got
    eta = int((total - shown) / speed) if speed > 1024 and task.get("downloading") else 0
    size_mb = round(_MATTING_MODEL_SIZE / 1024 / 1024)
    runtime_ready = _matting_runtime_ready()
    load_error = _MATTING_LOAD_ERROR.get("msg") or ("" if runtime_ready or not downloaded else
                                                    _matting_runtime_missing_message())
    available = bool(downloaded and runtime_ready and not _MATTING_LOAD_ERROR.get("msg"))
    return {
        "downloaded": downloaded,
        "model_size": f"{size_mb} MB",
        "model_size_mb": size_mb,
        "downloading": bool(task.get("downloading")),
        "verifying": bool(task.get("verifying")),
        "progress": 100 if downloaded else int(task.get("progress") or (shown * 100 // max(1, total))),
        "downloaded_mb": round(shown / 1024 / 1024, 1),
        "total_mb": round(total / 1024 / 1024, 1),
        "speed_mbps": round(speed / 1024 / 1024, 2),
        "eta": eta,
        "eta_seconds": eta,
        "attempt": int(task.get("attempt") or 0),
        "retrying": bool(task.get("downloading") and task.get("error_hint")),
        "hint": task.get("error_hint") or "",
        "cancelled": bool(task.get("cancelled")),
        "error": task.get("error") or "",
        # 本地抠图到底能不能用：只看「模型在 + 推理组件在 + 没记过加载错误」，
        # 不在这里加载模型（349MB，状态接口要快）；真正的加载错误在第一次抠图后也会落到 load_error
        "runtime_ready": runtime_ready,
        "available": available,
        "load_error": load_error,
    }


@app.post("/api/matting/model/download")
async def matting_model_download():
    """下载本地抠图模型（RMBG-2.0 量化版，约 349MB）。已在下载/已下载时直接返回；中断过的会接着下。"""
    task_id = "matting_model_download"
    task = _MODEL_DOWNLOAD_TASKS.get(task_id)
    if task and task.get("downloading"):
        # 重复点下载：不重新起线程（避免两路同时在写同一个 .part）
        return {"ok": True, "task_id": task_id, "already": True,
                "progress": int(task.get("progress") or 0)}
    if _matting_model_downloaded():
        return {"ok": True, "downloaded": True, "model_size_mb": round(_MATTING_MODEL_SIZE / 1024 / 1024)}
    part = _MATTING_MODEL_PATH + ".part"
    resumed_from = os.path.getsize(part) if os.path.exists(part) else 0
    _MODEL_DOWNLOAD_TASKS[task_id] = {"downloading": True, "progress": 0, "error": "", "done": False,
                                      "cancel": False, "downloaded": resumed_from,
                                      "total": int(_MATTING_MODEL_SIZE)}
    Thread(target=_download_matting_model, args=(task_id,), daemon=True).start()
    return {"ok": True, "task_id": task_id, "resumed_from_mb": round(resumed_from / 1024 / 1024, 1)}


@app.post("/api/matting/model/cancel")
async def matting_model_cancel():
    """取消下载（已下载部分保留，下次接着下）。"""
    task = _MODEL_DOWNLOAD_TASKS.get("matting_model_download")
    if task and task.get("downloading"):
        task["cancel"] = True
    return {"ok": True}


_MATTING_EDIT_PROMPT = (
    "图像抠图任务：请把图片的背景完整替换为纯绿色背景（#00FF00，RGB 0,255,0），"
    "图片主体（{subject}）必须保持完全不变——外观、颜色、材质、纹理、细节与原始图片完全一致，"
    "不要添加任何新元素，不要改变主体形状。只改背景，主体不能有任何变化。"
)
_MATTING_EDIT_PROMPT_NO_SUBJECT = (
    "图像抠图任务：请把图片的背景完整替换为纯绿色背景（#00FF00，RGB 0,255,0），"
    "图片中的主体对象必须保持完全不变——外观、颜色、材质、纹理、细节与原始图片完全一致，"
    "不要添加任何新元素，不要改变主体形状。只改背景，主体不能有任何变化。"
)


def chroma_key_to_transparent(img_bytes: bytes, orig_path: str = "") -> bytes:
    """AI 绿幕图 → 透明 PNG（server/matting_refine.py）：
    色度距离抠绿（背景色自动取样）→ 生成图和原图对得上时用原图像素（主体不被重画）→ 原图引导修边 → 去绿边/前景色去污染。"""
    from PIL import Image
    import numpy as np
    from server import matting_refine as _mr
    gen = np.array(Image.open(io.BytesIO(img_bytes)).convert("RGB"))
    orig = None
    if orig_path and os.path.isfile(orig_path):
        try:
            orig = np.array(ImageOps.exif_transpose(Image.open(orig_path)).convert("RGB"))
        except Exception:
            orig = None
    rgba, used_original = _mr.greenscreen_to_rgba(gen, orig)
    print(f"[Matting] 绿幕转透明完成（{'原图像素' if used_original else '生成图像素'}）")
    out = io.BytesIO()
    Image.fromarray(rgba, "RGBA").save(out, "PNG")
    return out.getvalue()


async def analyze_image_subject(raw_url: str):
    """视觉模型分析图片主体：返回 {subject, position, multiple}。任何失败返回 None（不阻断抠图）。"""
    src_path = output_file_from_url(raw_url)
    if not src_path or not os.path.isfile(src_path):
        return None
    try:
        provider_id = "modelscope"
        # 不写死模型名（旧默认的 Qwen3-VL 上游已下线）：用用户在 ModelScope 配置的对话模型，
        # 优先挑名字里带视觉特征的；一个都没配就跳过这步分析（失败本来也只返回 None）。
        configured = [str(m or "").strip() for m in (MODELSCOPE_CHAT_MODELS or []) if str(m or "").strip()]
        vl_model = next((m for m in configured if looks_like_vision_chat_model(m)), configured[0] if configured else "")
        if not vl_model:
            return None
        chat_base, chat_hdrs, mdl = resolve_chat_provider(provider_id, vl_model, vl_model)
        ref_url = media_reference_to_url(raw_url, max_image_size=1024)
        if not ref_url:
            return None
        sys_p = ("你是图片主体分析助手。分析图片中的主体（抠图目标），返回 JSON 对象（不要任何其他文字），"
                 "字段：subject=主体简短描述（中文，如：一只红色的陶瓷杯子）；"
                 "position=主体在画面中的位置（九宫格，取值：center/center-left/center-right/top-center/bottom-center/top-left/top-right/bottom-left/bottom-right）；"
                 "multiple=是否多个主体（true/false）。")
        content = [
            {"type": "text", "text": "分析这张图片的主体，只返回 JSON。"},
            {"type": "image_url", "image_url": {"url": ref_url}},
        ]
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=AI_REQUEST_TIMEOUT) as client:
            response = await client.post(
                f"{chat_base}/chat/completions",
                headers=chat_hdrs,
                json={"model": mdl, "messages": [
                    {"role": "system", "content": sys_p},
                    {"role": "user", "content": content},
                ]},
            )
            response.raise_for_status()
            raw = response.json()
        text = text_from_chat_response(raw) or ""
        text = text.strip()
        # 提取 JSON（模型可能包裹 ```json ... ```）
        m = re.search(r"\{[^{}]*\}", text, re.S)
        if not m:
            return None
        info = json.loads(m.group(0))
        subject = str(info.get("subject") or "").strip()[:80]
        position = str(info.get("position") or "center").strip().lower()
        if position not in {"center", "center-left", "center-right", "top-center", "bottom-center", "top-left", "top-right", "bottom-left", "bottom-right"}:
            position = "center"
        return {"subject": subject, "position": position, "multiple": bool(info.get("multiple"))}
    except Exception as exc:
        print(f"[Matting] 主体分析失败（降级为通用抠图）: {exc}")
        return None


async def _api_matting(raw_url: str, subject: str):
    """API 抠图：复用生图编辑链路（Modelscope Qwen-Image-Edit），动态不写死。"""
    src_path = output_file_from_url(raw_url)
    from PIL import Image as PILImage
    try:
        with PILImage.open(src_path) as im:
            w, h = im.size
    except Exception:
        w, h = 1024, 1024
    # 尺寸：按原图比例选标准尺寸（上限 1536 内）
    ratio = w / max(h, 1)
    if ratio > 1.4:
        size = "1536x1024"
    elif ratio < 0.72:
        size = "1024x1536"
    else:
        size = "1024x1024"
    prompt = _MATTING_EDIT_PROMPT.format(subject=subject) if subject else _MATTING_EDIT_PROMPT_NO_SUBJECT
    # 不写死具体型号：用用户在 ModelScope 配置的生图模型，优先图像编辑模型（名字带 edit）
    try:
        _ms_prov = get_api_provider("modelscope")
    except HTTPException:
        _ms_prov = None
    _ms_models = [str(m or "").strip() for m in ((_ms_prov or {}).get("image_models") or []) if str(m or "").strip()]
    _edit_models = [m for m in _ms_models if "edit" in m.lower()]
    candidates = [("modelscope", m) for m in (_edit_models[:1] or _ms_models[:1])]
    last_err = ""
    for pid, mdl in candidates:
        prov = get_api_provider(pid)
        if not prov or not (prov.get("image_models") or []):
            continue
        try:
            result = await build_online_image_result(OnlineImageRequest(
                prompt=prompt,
                provider_id=pid,
                model=mdl,
                size=size,
                quality="high",
                n=1,
                reference_images=[{"url": raw_url}],
            ))
            urls = _agent_result_media_urls(result)
            if urls:
                return urls[0], pid
        except Exception as exc:
            last_err = str(getattr(exc, "detail", exc))[:200]
            print(f"[Matting] {pid}/{mdl} 抠图失败: {last_err}")
            continue
    raise HTTPException(status_code=502, detail=f"抠图失败（所有可用平台均失败）：{last_err or '无可用生图平台'}")


@app.post("/api/image/matting/analyze")
async def image_matting_analyze(payload: ImageMattingRequest):
    """抠图第一步：AI 分析图片主体（返回主体描述与位置）。无视觉模型时返回空 subject（前端跳过）。"""
    raw_url = (payload.url or "").strip()
    if not raw_url:
        raise HTTPException(status_code=400, detail="缺少图片 URL")
    src_path = output_file_from_url(raw_url)
    if not src_path or not os.path.isfile(src_path):
        raise HTTPException(status_code=400, detail="图片文件不存在")
    info = await analyze_image_subject(raw_url)
    return {"subject": info.get("subject", "") if info else "", "position": info.get("position", "center") if info else "center", "multiple": info.get("multiple", False) if info else False, "analyzed": bool(info)}


@app.post("/api/image/matting")
async def image_matting(payload: ImageMattingRequest):
    """图片抠图（透明 PNG）。mode=api（默认）：AI 分析主体 → 生图 API 绿幕 → 转透明；mode=local：本地 RMBG-2.0 推理。"""
    raw_url = (payload.url or "").strip()
    if not raw_url:
        raise HTTPException(status_code=400, detail="缺少图片 URL")
    src_path = output_file_from_url(raw_url)
    if not src_path or not os.path.isfile(src_path):
        raise HTTPException(status_code=400, detail="图片文件不存在")
    if os.path.getsize(src_path) > 100 * 1024 * 1024:
        raise HTTPException(status_code=413, detail="图片超过 100MB，请先压缩")
    ext = os.path.splitext(src_path)[1].lower()
    if ext not in (".png", ".jpg", ".jpeg", ".webp", ".bmp"):
        raise HTTPException(status_code=400, detail="仅支持 png/jpg/webp 图片抠图")
    if payload.mode == "local":
        if not _matting_model_downloaded():
            raise HTTPException(status_code=400, detail="本地抠图模型未下载")
        if _matting_session() is None:
            raise HTTPException(status_code=500, detail=_matting_unavailable_reason())
        out_filename = f"matting_{uuid.uuid4().hex}.png"
        out_path = os.path.join(ASSETS_DIR, "output", out_filename)
        try:
            await asyncio.to_thread(run_image_matting, src_path, out_path)
        except Exception as exc:
            raise HTTPException(status_code=500, detail=f"抠图失败：{exc}")
        return {
            "url": output_url_for(out_filename, "output"),
            "name": f"抠图_{uuid.uuid4().hex[:6]}.png",
            "kind": "image",
            "mime": "image/png",
        }
    # 第一步：主体分析（失败不影响）
    subject = ""
    try:
        info = await analyze_image_subject(raw_url)
        if info and info.get("subject"):
            subject = info["subject"]
    except Exception:
        subject = ""
    # 第二步：API 抠图（绿幕 → 本地转透明）
    result_url, used_provider = await _api_matting(raw_url, subject)
    # 结果下载 → 绿幕转透明 → 存 output/
    try:
        if str(result_url).startswith(("/output/", "/assets/")):
            result_path = output_file_from_url(result_url)
            with open(result_path, "rb") as f:
                img_bytes = f.read()
        else:
            async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=httpx.Timeout(connect=20.0, read=120.0, write=60.0, pool=20.0)) as client:
                resp = await client.get(result_url)
                resp.raise_for_status()
                img_bytes = resp.content
        transparent_bytes = await asyncio.to_thread(chroma_key_to_transparent, img_bytes, src_path)
        out_filename = f"matting_{uuid.uuid4().hex}.png"
        out_path = os.path.join(ASSETS_DIR, "output", out_filename)
        with open(out_path, "wb") as f:
            f.write(transparent_bytes)
        result_url = output_url_for(out_filename, "output")
    except Exception as exc:
        print(f"[Matting] 绿幕转透明失败: {exc}")
        raise HTTPException(status_code=502, detail=f"抠图结果处理失败：{str(exc)[:120]}")
    return {
        "url": result_url,
        "name": f"抠图_{uuid.uuid4().hex[:6]}.png",
        "kind": "image",
        "mime": "image/png",
        "subject": subject,
        "provider": used_provider,
    }


class ImageSelectRegionRequest(BaseModel):
    url: str = ""
    mode: str = "point"      # point=点选（点在哪就认哪个物体）；box=框内识别
    x: float = 0.0           # 归一化坐标：point 是点击点，box 是框左上角
    y: float = 0.0
    w: float = 0.0           # box 的归一化宽高（point 不用）
    h: float = 0.0


_GRABCUT_WORK_LONG_EDGE = 1600   # 大图先缩到这个长边再算 GrabCut，最后把掩码放大回去
_REGION_MIN_RATIO = 0.002        # 选区小于整图 0.2% 视为没识别到
_REGION_MAX_RATIO = 0.85         # 选区大于整图 85% 视为把整幅背景都框进来了
_REGION_MIN_EDGE_RATIO = 0.6     # 选区内平均边缘强度不到整图这个比例 → 点在一片纯色背景/白卡上，不算物体


def _read_image_bgr(path: str):
    import numpy as np
    import cv2
    with Image.open(path) as im:
        rgb = np.array(im.convert("RGB"))
    return cv2.cvtColor(rgb, cv2.COLOR_RGB2BGR)


def _largest_component(mask_bin):
    """二值图里最大的连通域；没有就返回 None。"""
    import numpy as np
    import cv2
    count, labels, stats, _ = cv2.connectedComponentsWithStats(mask_bin.astype(np.uint8), 8)
    if count <= 1:
        return None
    label = int(np.argmax(stats[1:, cv2.CC_STAT_AREA])) + 1
    if int(stats[label, cv2.CC_STAT_AREA]) <= 0:
        return None
    return (labels == label).astype(np.uint8)


def _component_at(mask_bin, point, min_area=0):
    """点击点所在的那个连通域（点落在背景/太小都返回 None）——多物体图只选被点的那一个靠它。"""
    import numpy as np
    import cv2
    count, labels, stats, _ = cv2.connectedComponentsWithStats(mask_bin.astype(np.uint8), 8)
    if count <= 1:
        return None
    px, py = point
    label = int(labels[py, px])
    if label == 0 or int(stats[label, cv2.CC_STAT_AREA]) < max(1, int(min_area)):
        return None
    return (labels == label).astype(np.uint8)


def _region_has_object(img_bgr, mask_bin):
    """选出来的是不是「物体」：纯色背景/白卡上跑 GrabCut 也会吐出一块区域，但里面几乎没有边缘。"""
    import numpy as np
    import cv2
    gray = cv2.cvtColor(img_bgr, cv2.COLOR_BGR2GRAY)
    grad = cv2.magnitude(cv2.Sobel(gray, cv2.CV_32F, 1, 0), cv2.Sobel(gray, cv2.CV_32F, 0, 1))
    sel = mask_bin > 0
    if not bool(sel.any()):
        return False
    return float(grad[sel].mean()) >= float(grad.mean()) * _REGION_MIN_EDGE_RATIO


def _local_subject_alpha(img_bgr):
    """本地 RMBG-2.0 主体 alpha（0~255）。模型没下载或推理失败都返回 None，交给 GrabCut 兜底。"""
    if not _matting_model_downloaded():
        return None
    try:
        import numpy as np
        import cv2
        sess = _matting_session()
        if sess is None:
            return None
        rgb = cv2.cvtColor(img_bgr, cv2.COLOR_BGR2RGB)
        small = cv2.resize(rgb, (1024, 1024), interpolation=cv2.INTER_LINEAR)
        arr = small.astype(np.float32) / 255.0
        arr = (arr - np.array([0.485, 0.456, 0.406], np.float32)) / np.array([0.229, 0.224, 0.225], np.float32)
        out = sess.run(None, {sess.get_inputs()[0].name: arr.transpose(2, 0, 1)[None]})[-1]
        alpha = out[0, 0]
        h, w = img_bgr.shape[:2]
        alpha_img = Image.fromarray((alpha * 255).astype(np.uint8)).resize((w, h), Image.LANCZOS)
        return np.array(alpha_img)
    except Exception as exc:
        print(f"[SelectRegion] 本地主体识别失败：{exc}")
        return None


def _grabcut_fg(img_bgr, rect):
    """以 rect 为初值跑 GrabCut，返回前景二值图。"""
    import numpy as np
    import cv2
    mask = np.zeros(img_bgr.shape[:2], np.uint8)
    bgd = np.zeros((1, 65), np.float64)
    fgd = np.zeros((1, 65), np.float64)
    cv2.grabCut(img_bgr, mask, rect, bgd, fgd, 5, cv2.GC_INIT_WITH_RECT)
    return ((mask == cv2.GC_FGD) | (mask == cv2.GC_PR_FGD)).astype(np.uint8)


def _grabcut_fg_masked(img_bgr, fg_rect, border_ratio=0.025):
    """FG=点击处的小方块、BG=画面最外一圈（其余当作「可能背景」）再跑 GrabCut：
    实测这样能把被点到的整个物体长出来（rect 初值只会在点击点附近咬下一小块）。"""
    import numpy as np
    import cv2
    height, width = img_bgr.shape[:2]
    mask = np.full((height, width), cv2.GC_PR_BGD, np.uint8)
    x, y, w, h = fg_rect
    mask[y:y + h, x:x + w] = cv2.GC_FGD
    border = max(1, int(round(min(width, height) * border_ratio)))
    mask[:border, :] = cv2.GC_BGD
    mask[-border:, :] = cv2.GC_BGD
    mask[:, :border] = cv2.GC_BGD
    mask[:, -border:] = cv2.GC_BGD
    bgd = np.zeros((1, 65), np.float64)
    fgd = np.zeros((1, 65), np.float64)
    cv2.grabCut(img_bgr, mask, None, bgd, fgd, 5, cv2.GC_INIT_WITH_MASK)
    return ((mask == cv2.GC_FGD) | (mask == cv2.GC_PR_FGD)).astype(np.uint8)


def _clamp_rect(rect, width, height, margin=2):
    x, y, w, h = (int(round(v)) for v in rect)
    x = max(margin, min(x, width - margin - 1))
    y = max(margin, min(y, height - margin - 1))
    w = max(8, min(w, width - margin - x))
    h = max(8, min(h, height - margin - y))
    return (x, y, w, h)


def _select_region_mask(img_bgr, mode, x, y, w, h):
    """点选/框选识别。返回 (mask, method, area)：mask 是 uint8 白底选区；识别不到是 (None, 原因, 0)。"""
    import numpy as np
    import cv2
    height, width = img_bgr.shape[:2]
    scale = 1.0
    work = img_bgr
    long_edge = max(width, height)
    if long_edge > _GRABCUT_WORK_LONG_EDGE:
        scale = _GRABCUT_WORK_LONG_EDGE / float(long_edge)
        work = cv2.resize(img_bgr, (max(8, int(width * scale)), max(8, int(height * scale))), interpolation=cv2.INTER_AREA)
    wh, ww = work.shape[:2]

    def back(mask_small):
        if scale == 1.0:
            return mask_small
        return cv2.resize(mask_small, (width, height), interpolation=cv2.INTER_NEAREST)

    def ratio_of(mask_small):
        return float(mask_small.sum()) / float(ww * wh)

    if mode == "point":
        px = int(round(min(max(x, 0.0), 1.0) * (ww - 1)))
        py = int(round(min(max(y, 0.0), 1.0) * (wh - 1)))
        min_area = max(16, int(ww * wh * _REGION_MIN_RATIO))
        alpha = _local_subject_alpha(work)
        if alpha is not None:
            comp = _component_at(alpha > 127, (px, py), min_area)
            if comp is not None and _REGION_MIN_RATIO <= ratio_of(comp) <= _REGION_MAX_RATIO:
                return comp * 255, "subject", int(comp.sum()) / (scale * scale)
        # 点到背景 / 没有本地主体模型：以点击点当种子再识别一次
        seed = max(24, min(int(round(min(ww, wh) * 0.12)), min(ww, wh) - 8))
        seed_rect = _clamp_rect((px - seed / 2, py - seed / 2, seed, seed), ww, wh)
        fg = _grabcut_fg_masked(work, seed_rect)
        comp = _component_at(fg, (px, py), min_area)
        if comp is None:
            comp = _largest_component(fg)
        if comp is not None and _REGION_MIN_RATIO <= ratio_of(comp) <= _REGION_MAX_RATIO and _region_has_object(work, comp):
            return comp * 255, "grabcut", int(comp.sum()) / (scale * scale)
        # 再退一步：只用点击处的小方块当边框初值（贴边物体长不出来时兜底）
        side = max(24, min(int(round(min(ww, wh) * 0.28)), min(ww, wh) - 8))
        rect = _clamp_rect((px - side / 2, py - side / 2, side, side), ww, wh)
        fg = _grabcut_fg(work, rect)
        comp = _component_at(fg, (px, py), min_area) 
        if comp is None:
            comp = _largest_component(fg)
        if comp is not None and _REGION_MIN_RATIO <= ratio_of(comp) <= _REGION_MAX_RATIO and _region_has_object(work, comp):
            return comp * 255, "grabcut-rect", int(comp.sum()) / (scale * scale)
        return None, "not_found", 0

    bx = int(round(min(max(x, 0.0), 1.0) * ww))
    by = int(round(min(max(y, 0.0), 1.0) * wh))
    bw = int(round(max(0.0, w) * ww))
    bh = int(round(max(0.0, h) * wh))
    rect = _clamp_rect((bx, by, bw, bh), ww, wh)
    box_area = float(rect[2] * rect[3])
    fg = _grabcut_fg(work, rect)
    inside = np.zeros_like(fg)
    inside[rect[1]:rect[1] + rect[3], rect[0]:rect[0] + rect[2]] = fg[rect[1]:rect[1] + rect[3], rect[0]:rect[0] + rect[2]]
    comp = _largest_component(inside)
    if comp is not None:
        area = float(comp.sum())
        if box_area * 0.03 <= area <= box_area * 0.98 and _region_has_object(work, comp):
            return comp * 255, "grabcut-box", area / (scale * scale)
    return None, "keep_rect", 0


def _region_mask_data_url(mask):
    """选区掩码转 PNG data URL：白色=选中，其余全透明（前端直接 source-over 画进涂抹层就是叠加）。"""
    import numpy as np
    rgba = np.zeros(mask.shape + (4,), np.uint8)
    rgba[mask > 0] = (255, 255, 255, 255)
    buf = io.BytesIO()
    Image.fromarray(rgba, "RGBA").save(buf, format="PNG", optimize=True)
    return "data:image/png;base64," + base64.b64encode(buf.getvalue()).decode("ascii")


@app.post("/api/image/select-region")
async def image_select_region(payload: ImageSelectRegionRequest):
    """元素编辑的「点选 / 框选」识别：识别得出物体就返回贴合物体的选区掩码，识别不到返回 ok=false，
    前端据此弹「未识别到主体，请尝试框选或画笔」或退回矩形填充。全程本地 cv2，不联网、不调生图。"""
    raw_url = (payload.url or "").strip()
    if not raw_url:
        raise HTTPException(status_code=400, detail="缺少图片 URL")
    src_path = output_file_from_url(raw_url)
    if not src_path or not os.path.isfile(src_path):
        raise HTTPException(status_code=400, detail="图片文件不存在")
    mode = "box" if str(payload.mode) == "box" else "point"
    try:
        img_bgr = await asyncio.to_thread(_read_image_bgr, src_path)
    except Exception as exc:
        raise HTTPException(status_code=400, detail=f"图片读取失败：{exc}") from exc
    height, width = img_bgr.shape[:2]
    mask, method, area = await asyncio.to_thread(
        _select_region_mask, img_bgr, mode, float(payload.x), float(payload.y), float(payload.w), float(payload.h)
    )
    if mask is None:
        return {"ok": False, "reason": method, "width": width, "height": height}
    return {
        "ok": True,
        "method": method,
        "area": int(round(area)),
        "width": width,
        "height": height,
        "mask_png": await asyncio.to_thread(_region_mask_data_url, mask),
    }


# ===== HD 高清放大（本地 Real-ESRGAN ncnn-vulkan，免费离线，2K/4K） =====
# 实测：只有 -s 4 的输出是正确的，-s 2 / -s 3 会把画面切成矩形块且块内错位（换 tile、换
# 架构都一样）；所以统一按 4 倍超分，再 LANCZOS 缩到目标长边。
_UPSCALE_TARGET_LONG = {"2k": 2048, "4k": 4096}
_UPSCALE_MODEL_NAME = "realesrgan-x4plus"
_UPSCALE_RUNTIME_DIR = os.path.join(_MODELS_DIR, "realesrgan-ncnn-vulkan")
_UPSCALE_RELEASE_TAG = "v0.2.5.0"
# 二进制挂在主仓库 xinntao/Real-ESRGAN 的 release 上（不是 -ncnn-vulkan 那个仓库）
_UPSCALE_RELEASE_API = f"https://api.github.com/repos/xinntao/Real-ESRGAN/releases/tags/{_UPSCALE_RELEASE_TAG}"
_UPSCALE_RELEASE_BASE = f"https://github.com/xinntao/Real-ESRGAN/releases/download/{_UPSCALE_RELEASE_TAG}"
# GitHub 直连实测 36KB/s，走 gh-proxy 前缀 49MB 约 3 秒；代理失败再回落直连原地址
_UPSCALE_PROXY_PREFIX = "https://gh-proxy.com/"
_UPSCALE_ASSET_FALLBACK = {
    "macos": "realesrgan-ncnn-vulkan-20220424-macos.zip",
    "windows": "realesrgan-ncnn-vulkan-20220424-windows.zip",
    "ubuntu": "realesrgan-ncnn-vulkan-20220424-ubuntu.zip",
}
_UPSCALE_DOWNLOAD_TASK_ID = "upscale_runtime_download"


def _upscale_runtime_platform() -> str:
    """当前平台对应的发布资产后缀（macos / windows / ubuntu）。"""
    if sys.platform == "darwin":
        return "macos"
    if sys.platform.startswith("win"):
        return "windows"
    if sys.platform.startswith("linux"):
        return "ubuntu"
    return ""


def _upscale_binary_name() -> str:
    return "realesrgan-ncnn-vulkan.exe" if sys.platform.startswith("win") else "realesrgan-ncnn-vulkan"


def _upscale_binary_path() -> str:
    return os.path.join(_models_path("realesrgan-ncnn-vulkan"), _upscale_binary_name())


def _upscale_runtime_installed() -> bool:
    """二进制 + x4plus 模型都在才算装好（缺一个都跑不起来）。"""
    runtime_dir = _models_path("realesrgan-ncnn-vulkan")
    binary = os.path.join(runtime_dir, _upscale_binary_name())
    if not os.path.isfile(binary) or os.path.getsize(binary) < 1024 * 1024:
        return False
    models_dir = os.path.join(runtime_dir, "models")
    return all(
        os.path.isfile(os.path.join(models_dir, _UPSCALE_MODEL_NAME + ext))
        for ext in (".param", ".bin")
    )


def _resolve_upscale_asset_name(plat: str) -> str:
    """优先问 GitHub API 拿真实资产名（换版本时文件名会变），失败回落到内置名字。"""
    if not plat:
        return ""
    try:
        resp = requests.get(_UPSCALE_RELEASE_API, timeout=(10, 30))
        resp.raise_for_status()
        for asset in (resp.json().get("assets") or []):
            name = str(asset.get("name") or "")
            if name.endswith(f"-{plat}.zip") and "ncnn-vulkan" in name:
                return name
    except Exception as exc:
        print(f"[Upscale] 查询发布资产名失败，改用内置文件名：{exc}")
    return _UPSCALE_ASSET_FALLBACK.get(plat, "")


def _extract_upscale_runtime(zip_path: str, stage_dir: str):
    """解压到临时目录再搬进运行时目录；zip 里可能有顶层目录，两种都兼容。"""
    shutil.rmtree(stage_dir, ignore_errors=True)
    os.makedirs(stage_dir, exist_ok=True)
    with zipfile.ZipFile(zip_path) as zf:
        zf.extractall(stage_dir)
    binary_name = _upscale_binary_name()
    root = stage_dir
    if not os.path.isfile(os.path.join(root, binary_name)):
        root = ""
        for entry in os.listdir(stage_dir):
            candidate = os.path.join(stage_dir, entry)
            if os.path.isdir(candidate) and os.path.isfile(os.path.join(candidate, binary_name)):
                root = candidate
                break
        if not root:
            raise RuntimeError("压缩包里找不到 realesrgan-ncnn-vulkan 可执行文件")
    os.makedirs(_UPSCALE_RUNTIME_DIR, exist_ok=True)
    for entry in os.listdir(root):
        src = os.path.join(root, entry)
        dst = os.path.join(_UPSCALE_RUNTIME_DIR, entry)
        if os.path.isdir(src):
            shutil.rmtree(dst, ignore_errors=True)
            shutil.copytree(src, dst)
        else:
            shutil.copy2(src, dst)
    # zipfile 不保留可执行位，macOS 上不解 chmod 会 Permission denied
    os.chmod(_upscale_binary_path(), 0o755)


def _download_upscale_runtime(task_id: str):
    """后台下载 Real-ESRGAN 运行时：流式写 .tmp，解压后 chmod +x，进度写 _MODEL_DOWNLOAD_TASKS。"""
    task = _MODEL_DOWNLOAD_TASKS[task_id]
    plat = _upscale_runtime_platform()
    asset = _resolve_upscale_asset_name(plat)
    if not asset:
        task.update({"downloading": False, "error": f"当前平台暂不支持：{sys.platform}"})
        return
    zip_tmp = _UPSCALE_RUNTIME_DIR + ".zip.tmp"
    stage_dir = _UPSCALE_RUNTIME_DIR + ".extract.tmp"
    direct_url = f"{_UPSCALE_RELEASE_BASE}/{asset}"
    for url in (f"{_UPSCALE_PROXY_PREFIX}{direct_url}", direct_url):
        try:
            downloaded = 0
            os.makedirs(os.path.dirname(_UPSCALE_RUNTIME_DIR), exist_ok=True)
            with requests.get(url, stream=True, timeout=(30, 120)) as resp:
                resp.raise_for_status()
                total = int(resp.headers.get("Content-Length") or 0)
                with open(zip_tmp, "wb") as f:
                    for chunk in resp.iter_content(chunk_size=1024 * 1024):
                        if chunk:
                            f.write(chunk)
                            downloaded += len(chunk)
                            if total > 0:
                                task["progress"] = min(90, int(downloaded * 90 / total))
            if downloaded < 20 * 1024 * 1024:
                raise RuntimeError("压缩包不完整")
            task["progress"] = 92
            _extract_upscale_runtime(zip_tmp, stage_dir)
            task.update({"downloading": False, "progress": 100, "done": True, "error": ""})
            print(f"[Upscale] 本地高清放大运行时安装完成：{_UPSCALE_RUNTIME_DIR}")
            return
        except Exception as exc:
            task["error"] = str(exc)[:200]
            print(f"[Upscale] 运行时下载/解压失败（{url}）: {exc}")
        finally:
            try:
                os.remove(zip_tmp)
            except OSError:
                pass
            shutil.rmtree(stage_dir, ignore_errors=True)
    task["downloading"] = False


def _upscale_target_size(size, target_long: int):
    """等比缩到长边 = target_long（四舍五入取整，至少 1px）。"""
    width, height = size
    scale = target_long / max(width, height)
    if width >= height:
        return (target_long, max(1, int(round(height * scale))))
    return (max(1, int(round(width * scale))), target_long)


def run_local_upscale(src_path: str, out_path: str, target_long: int) -> dict:
    """本地 Real-ESRGAN 超分到目标长边。
    - 长边已达目标 → 不落文件、直接用原图（out_path 不写）
    - 长边 > 目标/2（预缩要砍掉原图一半以上细节）→ 只做 LANCZOS，不跑 AI。实测这类图
      GAN 只能把丢掉的细节"编"回来：相对原图 MAE 3.344 vs 纯 LANCZOS 0.245（差 13.6 倍），
      高频细节只剩 22.1%（LANCZOS 83.3%），logo/文字会糊成色块。
    - 其余 → 长边 > 目标/4 时先 LANCZOS 缩到 ceil(目标/4) 再 4 倍超分（送进模型的图恒
      ≤ 目标尺寸，不会出现 16384² 那种爆内存），最后与"源图直接 LANCZOS 到目标尺寸"的
      基线各 50% 混合。GAN 本身过度锐化：实测偏离保真基线 MAE 2.017、高频 10.1 倍、
      边缘有 halo，混合后降到 ~1.0 / 3.7 倍。
    返回 {skipped, method, width, height, source_width, source_height, elapsed_ms}。"""
    started = time.time()
    with Image.open(src_path) as opened:
        out_mode = "RGBA" if "A" in opened.getbands() else "RGB"
        src = opened.convert(out_mode)
    src_w, src_h = src.size
    long_edge = max(src_w, src_h)
    if long_edge >= target_long:
        return {
            "skipped": True, "width": src_w, "height": src_h,
            "source_width": src_w, "source_height": src_h,
            "elapsed_ms": int((time.time() - started) * 1000),
        }
    pre_long = int(math.ceil(target_long / 4))
    if long_edge > 2 * pre_long:
        result = src.resize(_upscale_target_size(src.size, target_long), Image.LANCZOS)
        result.save(out_path, "PNG")
        final_w, final_h = result.size
        return {
            "skipped": False, "method": "lanczos", "width": final_w, "height": final_h,
            "source_width": src_w, "source_height": src_h,
            "elapsed_ms": int((time.time() - started) * 1000),
        }
    feed = src
    if long_edge > pre_long:
        ratio = pre_long / long_edge
        feed = src.resize(
            (max(1, int(round(src_w * ratio))), max(1, int(round(src_h * ratio)))),
            Image.LANCZOS,
        )
    binary = _upscale_binary_path()
    try:
        os.chmod(binary, 0o755)
    except OSError:
        pass
    work_dir = tempfile.mkdtemp(prefix="novai_hd_")
    try:
        in_path = os.path.join(work_dir, "in.png")
        up_path = os.path.join(work_dir, "up.png")
        feed.save(in_path, "PNG")
        cmd = [binary, "-i", in_path, "-o", up_path, "-s", "4", "-t", "0",
               "-n", _UPSCALE_MODEL_NAME, "-f", "png"]
        # cwd 必须在运行时目录：模型是按 cwd 下的 models/ 找的（兼容兜底到老位置时要跟着走）
        try:
            proc = subprocess.run(cmd, cwd=os.path.dirname(binary), capture_output=True, timeout=180)
        except subprocess.TimeoutExpired:
            raise RuntimeError("超分超时（超过 180 秒），请换小一点的图片")
        if proc.returncode != 0 or not os.path.isfile(up_path):
            message = (proc.stderr or b"").decode("utf-8", errors="replace").strip()
            if not message:
                message = (proc.stdout or b"").decode("utf-8", errors="replace").strip()[-300:]
            raise RuntimeError(f"超分进程失败（退出码 {proc.returncode}）：{message[:300] or '无输出'}")
        with Image.open(up_path) as up:
            result = up.convert(out_mode)
        final_size = _upscale_target_size(result.size, target_long)
        if result.size != final_size:
            result = result.resize(final_size, Image.LANCZOS)
        # 先各自缩到最终尺寸再混，避免尺寸不一致；基线 = 源图直接 LANCZOS 到目标尺寸
        result = Image.blend(result, src.resize(final_size, Image.LANCZOS), 0.5)
        result.save(out_path, "PNG")
        final_w, final_h = result.size
        return {
            "skipped": False, "method": "ai-blend", "width": final_w, "height": final_h,
            "source_width": src_w, "source_height": src_h,
            "elapsed_ms": int((time.time() - started) * 1000),
        }
    finally:
        shutil.rmtree(work_dir, ignore_errors=True)


@app.get("/api/image/upscale/runtime")
async def image_upscale_runtime():
    """本地高清放大运行时（Real-ESRGAN ncnn-vulkan）状态：是否已安装、下载进度。"""
    task = _MODEL_DOWNLOAD_TASKS.get(_UPSCALE_DOWNLOAD_TASK_ID) or {}
    installed = _upscale_runtime_installed()
    downloading = bool(task.get("downloading"))
    progress = 100 if installed else int(task.get("progress") or 0)
    if installed:
        message = "已安装"
    elif downloading:
        message = f"正在下载…{progress}%"
    elif task.get("error"):
        message = f"下载失败：{task['error']}"
    else:
        message = "未安装"
    return {
        "installed": installed,
        "downloading": downloading,
        "progress": progress,
        "message": message,
        "platform": _upscale_runtime_platform(),
    }


@app.post("/api/image/upscale/runtime/download")
async def image_upscale_runtime_download():
    """下载本地高清放大运行时（Real-ESRGAN ncnn-vulkan，约 50MB）。下载中/已安装时直接返回。"""
    task = _MODEL_DOWNLOAD_TASKS.get(_UPSCALE_DOWNLOAD_TASK_ID)
    if task and task.get("downloading"):
        return {"ok": True, "task_id": _UPSCALE_DOWNLOAD_TASK_ID, "already": True}
    if _upscale_runtime_installed():
        return {"ok": True, "installed": True}
    _MODEL_DOWNLOAD_TASKS[_UPSCALE_DOWNLOAD_TASK_ID] = {"downloading": True, "progress": 0, "error": "", "done": False}
    Thread(target=_download_upscale_runtime, args=(_UPSCALE_DOWNLOAD_TASK_ID,), daemon=True).start()
    return {"ok": True, "task_id": _UPSCALE_DOWNLOAD_TASK_ID}


@app.post("/api/image/upscale")
async def image_upscale(payload: ImageUpscaleRequest):
    """本地 AI 高清放大：2k=长边2048 / 4k=长边4096，结果落 assets/output/hd_*.png。"""
    raw_url = (payload.url or "").strip()
    if not raw_url:
        raise HTTPException(status_code=400, detail="缺少图片 URL")
    target = (payload.target or "").strip().lower()
    if target not in _UPSCALE_TARGET_LONG:
        raise HTTPException(status_code=400, detail="target 仅支持 2k / 4k")
    src_path = output_file_from_url(raw_url)
    if not src_path or not os.path.isfile(src_path):
        raise HTTPException(status_code=400, detail="图片文件不存在")
    if os.path.getsize(src_path) > 100 * 1024 * 1024:
        raise HTTPException(status_code=413, detail="图片超过 100MB，请先压缩")
    ext = os.path.splitext(src_path)[1].lower()
    if ext not in (".png", ".jpg", ".jpeg", ".webp", ".bmp"):
        raise HTTPException(status_code=400, detail="仅支持 png/jpg/webp 图片超分")
    if not _upscale_runtime_installed():
        raise HTTPException(status_code=400, detail="本地高清放大组件未安装")
    out_filename = f"hd_{uuid.uuid4().hex}.png"
    out_path = os.path.join(ASSETS_DIR, "output", out_filename)
    try:
        info = await asyncio.to_thread(run_local_upscale, src_path, out_path, _UPSCALE_TARGET_LONG[target])
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"高清放大失败：{exc}")
    if info["skipped"]:
        # 已经是这个精度：直接指回原图，不再写一份内容相同的 hd_*.png
        return {
            "url": raw_url,
            "name": os.path.basename(src_path),
            "kind": "image",
            "mime": mimetypes.guess_type(src_path)[0] or "image/png",
            "width": info["width"],
            "height": info["height"],
            "source_width": info["source_width"],
            "source_height": info["source_height"],
            "target": target,
            "skipped": True,
            "elapsed_ms": info["elapsed_ms"],
        }
    return {
        "url": output_url_for(out_filename, "output"),
        "name": f"高清放大_{uuid.uuid4().hex[:6]}.png",
        "kind": "image",
        "mime": "image/png",
        "method": info["method"],
        "width": info["width"],
        "height": info["height"],
        "source_width": info["source_width"],
        "source_height": info["source_height"],
        "target": target,
        "skipped": False,
        "elapsed_ms": info["elapsed_ms"],
    }


class Base64UploadRequest(BaseModel):
    data: str = ""            # 纯 base64 或 data:URL
    name: str = ""
    content_type: str = ""

@app.post("/api/ai/upload-base64")
async def upload_ai_base64(payload: Base64UploadRequest):
    """以 base64 JSON 方式上传字节到 assets/input，返回 /assets 地址。
    给不便用 multipart/FormData 的客户端（如 PS UXP 面板）用——UXP 的 fetch+FormData 经常发不出有效 multipart。"""
    raw = (payload.data or "").strip()
    ct = (payload.content_type or "").split(";", 1)[0].strip().lower()
    if raw.startswith("data:"):
        header, _, raw = raw.partition(",")
        if not ct:
            ct = header[5:].split(";", 1)[0].strip().lower()
    try:
        content = base64.b64decode(raw, validate=False)
    except Exception:
        raise HTTPException(status_code=400, detail="数据无法解码")
    if not content:
        raise HTTPException(status_code=400, detail="内容为空")
    if len(content) > 50 * 1024 * 1024:
        raise HTTPException(status_code=413, detail="超过 50MB")
    kind, ext = _local_upload_kind_ext(payload.name or "", ct or "image/png")
    if kind is None:
        raise HTTPException(status_code=415, detail=(
            f"{payload.name or '这个文件'} 的格式暂不支持，请另存为 PNG / JPG / WebP 后重试"))
    filename = f"ai_ref_{uuid.uuid4().hex[:12]}{ext}"
    url = store_uploaded_bytes(content, filename, "input", payload.name or filename)
    return {"files": [{"url": url, "name": payload.name or filename, "kind": kind}]}

@app.post("/api/comfyui/upload-base64")
async def upload_comfyui_base64(payload: Base64UploadRequest):
    """base64 方式把图片传到 ComfyUI 各后端的 input 目录，返回 comfy 用文件名（供 UXP 做 ComfyUI 图生图）。"""
    raw = (payload.data or "").strip()
    ct = (payload.content_type or "").split(";", 1)[0].strip().lower()
    if raw.startswith("data:"):
        header, _, raw = raw.partition(",")
        if not ct:
            ct = header[5:].split(";", 1)[0].strip().lower()
    try:
        content = base64.b64decode(raw, validate=False)
    except Exception:
        raise HTTPException(status_code=400, detail="数据无法解码")
    if not content:
        raise HTTPException(status_code=400, detail="内容为空")
    _, ext = _local_upload_kind_ext(payload.name or "", ct or "image/png")
    filename = f"dx_{uuid.uuid4().hex[:12]}{ext or '.png'}"
    comfy_name = None
    for addr in COMFYUI_INSTANCES:
        try:
            resp = _NO_PROXY_SESSION.post(f"http://{addr}/upload/image",
                                 files={'image': (filename, content, ct or 'image/png')}, timeout=10)
            if resp.status_code == 200:
                comfy_name = resp.json().get("name", filename)
        except Exception as exc:
            print(f"ComfyUI base64 upload error for {addr}: {exc}")
    if not comfy_name:
        raise HTTPException(status_code=502, detail="上传到 ComfyUI 失败")
    return {"name": comfy_name}

# 已知图片扩展名：原样保留，不要统一改成 .png（字节不转码却叫 .png 就是「坏文件」，节点既不显示也不报错）
_LOCAL_UPLOAD_IMAGE_EXTS = {".png", ".jpg", ".jpeg", ".webp", ".gif", ".svg", ".bmp", ".avif", ".tif", ".tiff", ".heic", ".heif"}
# content_type → 扩展名；mimetypes 表里没有 image/x-ms-bmp、image/jpg 这类常见写法，这里补上
_LOCAL_UPLOAD_IMAGE_CT_EXTS = {
    "image/png": ".png",
    "image/jpeg": ".jpg",
    "image/jpg": ".jpg",
    "image/webp": ".webp",
    "image/gif": ".gif",
    "image/svg+xml": ".svg",
    "image/bmp": ".bmp",
    "image/x-ms-bmp": ".bmp",
    "image/avif": ".avif",
    "image/tiff": ".tiff",
    "image/heic": ".heic",
    "image/heif": ".heif",
}

def _local_upload_image_ext_for(content_type):
    """扩展名缺失时按 content_type 推图片扩展名；推不出返回空串（调用方据此明确报错，不再兜成 .png）。"""
    ct = (content_type or "").split(";", 1)[0].strip().lower()
    if not ct:
        return ""
    ext = _LOCAL_UPLOAD_IMAGE_CT_EXTS.get(ct) or mimetypes.guess_extension(ct) or ""
    ext = ext.lower()
    return ext if ext in _LOCAL_UPLOAD_IMAGE_EXTS else ""

def _local_upload_kind_ext(filename, content_type):
    image_exts = _LOCAL_UPLOAD_IMAGE_EXTS
    video_exts = {".mp4", ".webm", ".mov", ".m4v", ".flv"}
    audio_exts = {".mp3", ".wav", ".m4a", ".aac", ".ogg", ".flac"}
    ext = os.path.splitext(filename or "")[1].lower()
    ct = (content_type or "").split(";", 1)[0].strip().lower()
    if ext in video_exts or ct.startswith("video/"):
        if ext not in video_exts:
            ext = ".webm" if "webm" in ct else ".mov" if "quicktime" in ct else ".mp4"
        return "video", ext
    if ext in audio_exts or ct.startswith("audio/"):
        if ext not in audio_exts:
            ext = ".wav" if "wav" in ct else ".ogg" if "ogg" in ct else ".m4a" if "mp4" in ct else ".mp3"
        return "audio", ext
    if ext in image_exts:
        return "image", ext
    if ct.startswith("image/"):
        guessed = _local_upload_image_ext_for(ct)
        if guessed:
            return "image", guessed
        return None, ext
    return None, ext

def _local_upload_display_name(filename):
    # 文件名形如 up_<hex>_<原始名>；去掉前缀还原展示名
    base = os.path.basename(str(filename or ""))
    m = re.match(r"^up_[0-9a-f]{12}_(.+)$", base)
    return m.group(1) if m else base

def _local_upload_rel_path(value):
    text = str(value or "").replace("\\", "/").strip().lstrip("/")
    if not text:
        return ""
    norm = os.path.normpath(text).replace("\\", "/")
    if norm in {".", ""}:
        return ""
    if norm.startswith("../") or norm == ".." or os.path.isabs(norm):
        raise HTTPException(status_code=400, detail="非法路径")
    return norm

def _local_upload_abs(rel):
    rel_path = _local_upload_rel_path(rel)
    path = os.path.abspath(os.path.join(LOCAL_UPLOAD_DIR, rel_path))
    root = os.path.abspath(LOCAL_UPLOAD_DIR)
    try:
        common = os.path.commonpath([root, path])
    except ValueError:
        raise HTTPException(status_code=400, detail="非法路径")
    if common != root:
        raise HTTPException(status_code=400, detail="非法路径")
    return rel_path, path

def _local_upload_safe_path(name):
    filename, path = _local_upload_abs(name)
    if not filename:
        raise HTTPException(status_code=400, detail="文件名不能为空")
    return filename, path

def _local_upload_safe_folder(path_value):
    rel, path = _local_upload_abs(path_value)
    return rel, path

def _local_upload_safe_folder_name(name):
    cleaned = sanitize_asset_name(os.path.basename(str(name or "").strip()), "")
    cleaned = re.sub(r"[\\/]+", "_", cleaned).strip(" ._")
    if not cleaned:
        raise HTTPException(status_code=400, detail="文件夹名称不能为空")
    return cleaned[:60]

def _local_upload_safe_file_stem(name):
    raw = os.path.splitext(os.path.basename(str(name or "").strip()))[0]
    cleaned = sanitize_asset_name(raw, "")
    cleaned = re.sub(r"[\\/]+", "_", cleaned).strip(" ._")
    if not cleaned:
        raise HTTPException(status_code=400, detail="文件名称不能为空")
    return cleaned[:120]

def _local_upload_caption_path(filename):
    return os.path.splitext(os.path.join(LOCAL_UPLOAD_DIR, filename))[0] + ".txt"

def _read_local_upload_caption(filename):
    caption_path = _local_upload_caption_path(filename)
    if not os.path.isfile(caption_path):
        return "", ""
    try:
        with open(caption_path, "r", encoding="utf-8-sig") as f:
            text = f.read()
    except UnicodeDecodeError:
        with open(caption_path, "r", encoding="gb18030", errors="replace") as f:
            text = f.read()
    except OSError:
        return "", ""
    return text, os.path.basename(caption_path)

def _local_upload_item(filename):
    path = os.path.join(LOCAL_UPLOAD_DIR, filename)
    rel = _local_upload_rel_path(filename)
    try:
        stat = os.stat(path)
        size = stat.st_size
        created_at = stat.st_mtime
    except OSError:
        size = 0
        created_at = 0
    kind, _ = _local_upload_kind_ext(filename, "")
    item = {
        "id": rel,
        "file": rel,
        "name": _local_upload_display_name(rel),
        "url": f"/assets/uploads/{urllib.parse.quote(rel, safe='/')}",
        "kind": kind or "image",
        "size": size,
        "created_at": created_at,
        "folder": os.path.dirname(rel).replace("\\", "/"),
    }
    if kind == "image":
        try:
            with Image.open(path) as img:
                item["natural_w"], item["natural_h"] = img.size
                item["width"], item["height"] = img.size
        except Exception:
            pass
        caption, caption_file = _read_local_upload_caption(filename)
        item["caption"] = caption
        item["caption_file"] = caption_file
        classification = _read_local_upload_classification(filename)
        if classification:
            item["classification"] = classification
    generation = _read_local_upload_generation(filename)
    if generation:
        item["generation"] = generation
    return item

def _local_upload_folder_node(path="", name="全部上传"):
    rel = _local_upload_rel_path(path)
    return {
        "id": rel or "__root__",
        "path": rel,
        "name": name if not rel else os.path.basename(rel),
        "items": [],
        "children": [],
    }

LOCAL_OUTPUT_FOLDER = "画布生成"

# ── 本地素材扫描硬上限 ──
# 素材库每次请求都会扫一遍本地素材目录。用户可能把存储位置指到很大的盘、或者目录里塞了
# symlink / Windows junction（指向整个系统），递归下去会把接口拖死。这里只扫 NOVAI 管理的
# assets/uploads 与 assets/output，且不跟链接、带深度/条目硬上限，超限截断并回传 truncated。
LOCAL_SCAN_MAX_DEPTH = 8
LOCAL_SCAN_MAX_ENTRIES = 20000

def _local_scan_new_meta():
    return {
        "truncated": False,
        "skipped_links": 0,
        "skipped_depth": 0,
        "max_depth": LOCAL_SCAN_MAX_DEPTH,
        "max_entries": LOCAL_SCAN_MAX_ENTRIES,
    }

def _local_scan_is_link(path):
    """符号链接 / Windows junction（reparse point）一律不跟：素材库只读 NOVAI 管理的真实文件。
    读不到（权限、刚被删）也按「忽略」处理，避免扫描因为单个坏条目整个失败。"""
    try:
        if os.path.islink(path):
            return True
        isjunction = getattr(os.path, "isjunction", None)
        if callable(isjunction) and isjunction(path):
            return True
        st = os.lstat(path)
        reparse = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)
        if getattr(st, "st_file_attributes", 0) & reparse:
            return True
    except OSError:
        return True
    return False

def _local_output_item(filename):
    """assets/output 里的画布生成物：作为「本地素材」的只读条目（不改名 / 不删除 / 不移动）。
    生成物和上传物放一起，用户才能在素材库里看到 BEAT / 旧画布生成出来的图片和视频。"""
    path = os.path.join(OUTPUT_OUTPUT_DIR, filename)
    kind, _ = _local_upload_kind_ext(filename, "")
    if kind is None:
        return None
    try:
        stat = os.stat(path)
        size = stat.st_size
        created_at = stat.st_mtime
    except OSError:
        size = 0
        created_at = 0
    return {
        "id": "output:" + filename,
        "file": "",
        "name": filename,
        "url": "/assets/output/" + urllib.parse.quote(filename, safe=""),
        "kind": kind,
        "size": size,
        "created_at": created_at,
        "folder": LOCAL_OUTPUT_FOLDER,
        "readonly": True,
        "source": "output",
    }

def _local_output_items(limit=LOCAL_SCAN_MAX_ENTRIES, scan=None):
    """assets/output 只扫一层（生成物都落在这一层），同样跳过链接并按剩余预算截断。"""
    try:
        names = sorted(os.listdir(OUTPUT_OUTPUT_DIR), key=str.lower)
    except OSError:
        return []
    out = []
    for name in names:
        if name.startswith(".") or name.startswith("._"):
            continue
        if limit and len(out) >= limit:
            if scan is not None:
                scan["truncated"] = True
            break
        full = os.path.join(OUTPUT_OUTPUT_DIR, name)
        if _local_scan_is_link(full):
            if scan is not None:
                scan["skipped_links"] += 1
            continue
        if not os.path.isfile(full):
            continue
        item = _local_output_item(name)
        if item:
            out.append(item)
    return out

def _append_local_output_items(root_node, items, scan=None):
    budget = max(0, LOCAL_SCAN_MAX_ENTRIES - len(items))
    if budget <= 0:
        if scan is not None:
            scan["truncated"] = True
        return
    output_items = _local_output_items(limit=budget, scan=scan)
    if not output_items:
        return
    folder = _local_upload_folder_node(LOCAL_OUTPUT_FOLDER)
    folder["name"] = LOCAL_OUTPUT_FOLDER
    folder["items"] = output_items
    root_node["children"].append(folder)
    items.extend(output_items)

def local_output_readonly_name(name):
    """「画布生成」里的条目 / 文件夹是只读的：改名、删除、移动、往里上传都要拒绝。
    条目 id 形如 output:<文件名>，文件夹路径就是 LOCAL_OUTPUT_FOLDER。"""
    text = str(name or "").replace("\\", "/").strip().strip("/")
    if not text:
        return False
    if text.startswith("output:"):
        return True
    return text == LOCAL_OUTPUT_FOLDER or text.startswith(LOCAL_OUTPUT_FOLDER + "/")

def _local_upload_tree_and_items():
    """扫 NOVAI 管理的素材目录（assets/uploads 递归 + assets/output 一层），返回 (tree, items)。

    安全/性能硬约束（素材库每次请求都会走这里）：
    · 只扫 assets/uploads 与 assets/output，绝不遍历其它系统目录；
    · 不跟随 symlink / Windows junction（目录级、文件级都跳过，并计数）；
    · 深度上限 LOCAL_SCAN_MAX_DEPTH、条目上限 LOCAL_SCAN_MAX_ENTRIES，超限截断；
    · 截断/跳过信息写进 tree["scan"]，接口层原样回传（前端可提示「素材过多，已截断」）。
    """
    scan = _local_scan_new_meta()
    root_node = _local_upload_folder_node("", "全部上传")
    root_node["scan"] = scan
    folder_map = {"": root_node}
    items = []
    uploads_root = LOCAL_UPLOAD_DIR
    if os.path.isdir(uploads_root):
        for current, dirs, files in os.walk(uploads_root, followlinks=False):
            if len(items) >= LOCAL_SCAN_MAX_ENTRIES:
                scan["truncated"] = True
                break
            rel_dir = os.path.relpath(current, uploads_root).replace("\\", "/")
            if rel_dir == ".":
                rel_dir = ""
            depth = 0 if not rel_dir else rel_dir.count("/") + 1
            keep_dirs = []
            for dirname in sorted(dirs, key=str.lower):
                if dirname.startswith(".") or dirname.startswith("._"):
                    continue
                if _local_scan_is_link(os.path.join(current, dirname)):
                    scan["skipped_links"] += 1
                    continue
                keep_dirs.append(dirname)
            if keep_dirs and depth >= LOCAL_SCAN_MAX_DEPTH:
                scan["truncated"] = True
                scan["skipped_depth"] += 1
                keep_dirs = []
            dirs[:] = keep_dirs
            node = folder_map.get(rel_dir)
            if node is None:
                node = _local_upload_folder_node(rel_dir)
                folder_map[rel_dir] = node
            for dirname in dirs:
                child_rel = f"{rel_dir}/{dirname}".lstrip("/")
                child = _local_upload_folder_node(child_rel)
                folder_map[child_rel] = child
                node["children"].append(child)
            for name in sorted(files, key=str.lower):
                if name.startswith(".") or name.startswith("._"):
                    continue
                if len(items) >= LOCAL_SCAN_MAX_ENTRIES:
                    scan["truncated"] = True
                    dirs[:] = []
                    break
                full = os.path.join(current, name)
                if _local_scan_is_link(full):
                    scan["skipped_links"] += 1
                    continue
                rel_file = f"{rel_dir}/{name}".lstrip("/")
                kind, _ = _local_upload_kind_ext(name, "")
                if kind is None:
                    continue
                item = _local_upload_item(rel_file)
                node["items"].append(item)
                items.append(item)
    _append_local_output_items(root_node, items, scan)

    def fill_counts(node):
        total = len(node.get("items") or [])
        for child in node.get("children") or []:
            total += fill_counts(child)
        node["count"] = total
        return total
    fill_counts(root_node)
    items.sort(key=lambda it: it.get("created_at") or 0, reverse=True)
    scan["count"] = len(items)
    scan["upload_count"] = len([it for it in items if str(it.get("source") or "") != "output"])
    scan["output_count"] = scan["count"] - scan["upload_count"]
    return root_node, items

_DOUBLE_EXT_RE = re.compile(r'(\.[A-Za-z0-9]{1,5})\1$', re.IGNORECASE)
_DOUBLE_EXT_MEDIA = {".png", ".jpg", ".jpeg", ".webp", ".gif", ".bmp", ".avif",
                     ".mp4", ".webm", ".mov", ".m4v", ".flv"}

def migrate_double_extension_uploads():
    """修复历史遗留的双重扩展名（如 foo.png.png）：去掉重复的一层，并同步重命名 caption/classification 旁车文件。
    旧版 URL 导入会把自带扩展名的 entry.name 又拼一次 ext，导致文件名重复后缀、URL 对不上而无法显示。"""
    if not os.path.isdir(LOCAL_UPLOAD_DIR):
        return
    renamed = 0
    for current, _dirs, files in os.walk(LOCAL_UPLOAD_DIR):
        for name in files:
            m = _DOUBLE_EXT_RE.search(name)
            if not m or m.group(1).lower() not in _DOUBLE_EXT_MEDIA:
                continue
            old_path = os.path.join(current, name)
            new_path = os.path.join(current, name[:-len(m.group(1))])  # 去掉末尾重复的一层扩展名
            if os.path.exists(new_path):
                continue
            try:
                os.rename(old_path, new_path)
            except OSError:
                continue
            renamed += 1
            # caption/classification 旁车以「去掉一层扩展名」为基名，需同步改名以保留标注
            old_base = os.path.splitext(old_path)[0]
            new_base = os.path.splitext(new_path)[0]
            for suffix in (".classification.json", ".generation.json", ".txt"):
                src_side, dst_side = old_base + suffix, new_base + suffix
                if os.path.exists(src_side) and not os.path.exists(dst_side):
                    try:
                        os.rename(src_side, dst_side)
                    except OSError:
                        pass
    if renamed:
        print(f"修复双重扩展名素材: {renamed} 个")

def _sniff_image_ext_bytes(head):
    """按文件头魔数判断真实图片格式，返回规范扩展名（含点），无法识别返回 None。"""
    head = head or b""
    if head.startswith(b"\x89PNG\r\n\x1a\n"):
        return ".png"
    if head.startswith(b"\xff\xd8\xff"):
        return ".jpg"
    if head[:4] == b"RIFF" and head[8:12] == b"WEBP":
        return ".webp"
    if head[:6] in (b"GIF87a", b"GIF89a"):
        return ".gif"
    if head[:2] == b"BM":
        return ".bmp"
    return None

def _sniff_image_ext(path):
    try:
        with open(path, "rb") as f:
            return _sniff_image_ext_bytes(f.read(16))
    except OSError:
        return None

def migrate_mislabeled_image_extensions():
    """有些采集来的图片内容与扩展名不符（例如 WebP 内容却叫 .png），导致服务端按错误 content-type 返回、
    严格的客户端（PS UXP）解不出来。这里按真实魔数纠正扩展名，并同步重命名 caption/classification 旁车。"""
    if not os.path.isdir(LOCAL_UPLOAD_DIR):
        return
    img_exts = {".png", ".jpg", ".jpeg", ".webp", ".gif", ".bmp"}
    fixed = 0
    for current, _dirs, files in os.walk(LOCAL_UPLOAD_DIR):
        for name in files:
            ext = os.path.splitext(name)[1].lower()
            if ext not in img_exts:
                continue
            path = os.path.join(current, name)
            real = _sniff_image_ext(path)
            if not real:
                continue
            # .jpg/.jpeg 视为同一种，不互相纠正
            if real == ext or (real == ".jpg" and ext == ".jpeg"):
                continue
            new_name = os.path.splitext(name)[0] + real
            new_path = os.path.join(current, new_name)
            if os.path.exists(new_path):
                continue
            try:
                os.rename(path, new_path)
            except OSError:
                continue
            fixed += 1
            old_base = os.path.splitext(path)[0]
            new_base = os.path.splitext(new_path)[0]
            for suffix in (".classification.json", ".generation.json", ".txt"):
                src_side, dst_side = old_base + suffix, new_base + suffix
                if os.path.isfile(src_side) and not os.path.exists(dst_side):
                    try:
                        os.rename(src_side, dst_side)
                    except OSError:
                        pass
    if fixed:
        print(f"纠正图片扩展名(内容与后缀不符): {fixed} 个")


