# --- 在线生图 (COMFLY) ---

class TestConnectionPayload(BaseModel):
    base_url: str = ""
    api_key: str = ""
    use_proxy: str = "auto"
    provider_id: str = ""
    protocol: str = "openai"
    image_request_mode: str = "openai"
    lovart_access_key: str = ""
    lovart_secret_key: str = ""

def protocol_from_payload(payload):
    provider_id = str(getattr(payload, "provider_id", "") or "").strip().lower()
    if provider_id == "volcengine":
        return "volcengine"
    if provider_id == "runninghub":
        return "runninghub"
    if provider_id == "jimeng":
        return "jimeng"
    if provider_id == "lovart":
        return "lovart"
    base_url = str(getattr(payload, "base_url", "") or "").strip().lower()
    if "runninghub.cn" in base_url or "runninghub.ai" in base_url:
        return "runninghub"
    protocol = str(getattr(payload, "protocol", "") or "openai").strip().lower()
    return protocol if protocol in SUPPORTED_PROVIDER_PROTOCOLS else "openai"

def api_key_from_payload(payload, protocol: str = ""):
    explicit = str(getattr(payload, "api_key", "") or "").strip()
    provider_id = str(getattr(payload, "provider_id", "") or "").strip().lower()
    protocol = str(protocol or protocol_from_payload(payload) or "").strip().lower()
    if explicit:
        return explicit
    if provider_id:
        if provider_id == "runninghub":
            value = os.getenv(runninghub_wallet_key_env(), "")
            if value:
                return value
        value = provider_env_key_value(provider_id)
        if value:
            return value
    if protocol == "volcengine":
        return volcengine_provider_api_key("")
    return ""

def upstream_models_url(base_url: str, protocol: str):
    if protocol == "gemini":
        return f"{base_url}/models" if base_url.endswith("/v1beta") else f"{base_url}/v1beta/models"
    if protocol == "volcengine":
        return f"{base_url}/models" if base_url.endswith("/api/v3") else f"{base_url}/api/v3/models"
    if protocol == "runninghub":
        return runninghub_openapi_url({"base_url": base_url}, "models")
    url = f"{base_url}/models" if base_url.endswith("/v1") else f"{base_url}/v1/models"
    # APIMart 文档：expand=category 给每个模型附带 category（向后兼容，旧格式不变），
    # 其它 OpenAI 兼容站不认这个参数，只对 APIMart 主机携带
    if protocol == "apimart" or is_apimart_models_host(base_url):
        return f"{url}?expand=category"
    return url

def upstream_model_headers(api_key: str, protocol: str):
    if protocol == "gemini":
        return {"x-goog-api-key": api_key, "Accept": "application/json"}
    if protocol == "runninghub":
        return {"Authorization": bearer_auth_value(api_key), "Accept": "application/json"}
    return {"Authorization": bearer_auth_value(api_key), "Accept": "application/json"}

def volcengine_default_model_payload(status=200, message="", raw=None):
    return {
        "ok": True,
        "protocol": "volcengine",
        "status": status,
        "message": message or "方舟任务接口可用，模型列表接口未返回模型。请按实际方舟控制台模型名称手动填写视频模型。",
        "model_count": 0,
        "image_models": [],
        "chat_models": [],
        "video_models": [],
        "all": [],
        "raw": raw,
    }

def volcengine_task_probe_url(base_url: str):
    base = str(base_url or "").strip().rstrip("/")
    if not base:
        return ""
    if base.endswith("/api/v3"):
        return f"{base}/contents/generations/tasks/healthcheck_probe_do_not_submit"
    return f"{base}/api/v3/contents/generations/tasks/healthcheck_probe_do_not_submit"

async def probe_volcengine_task_endpoint(client, base_url: str, api_key: str):
    probe_url = volcengine_task_probe_url(base_url)
    if not probe_url:
        return False, {"status": 0, "message": "Base URL 为空"}
    response = await client.get(probe_url, headers=upstream_model_headers(api_key, "volcengine"))
    try:
        raw = response.json() if response.text else {}
    except Exception:
        raw = response.text[:500]
    if response.status_code in (401, 403):
        return False, {"status": response.status_code, "message": "方舟 API Key 无效或无权限", "raw": raw}
    if looks_like_html_response(response.text):
        return False, {"status": response.status_code, "message": "任务接口返回 HTML，Base URL 可能不是 API 地址", "raw": raw}
    if response.status_code < 500:
        return True, {"status": response.status_code, "message": "方舟任务查询端点可达", "raw": raw}
    return False, {"status": response.status_code, "message": f"方舟任务接口服务端错误 {response.status_code}", "raw": raw}

def openai_compat_root_for_probe(base_url: str):
    base = str(base_url or "").strip().rstrip("/")
    if base.endswith("/api/v3"):
        base = base[: -len("/api/v3")]
    if base.endswith("/v1"):
        return base
    return f"{base}/v1" if base else ""

async def probe_openai_compat_bearer_endpoint(client, base_url: str, api_key: str):
    root = openai_compat_root_for_probe(base_url)
    if not root:
        return False, {"status": 0, "message": "Base URL 为空"}
    url = f"{root}/chat/completions"
    response = await client.post(
        url,
        headers={**upstream_model_headers(api_key, "openai"), "Content-Type": "application/json"},
        json={"messages": []},
    )
    try:
        raw = response.json() if response.text else {}
    except Exception:
        raw = response.text[:500]
    if response.status_code in (401, 403):
        return False, {"status": response.status_code, "message": "API Key 无效或无权限", "raw": raw}
    if looks_like_html_response(response.text):
        return False, {"status": response.status_code, "message": "OpenAI 兼容入口返回 HTML，Base URL 可能不是 API 地址", "raw": raw}
    if response.status_code < 500:
        return True, {"status": response.status_code, "message": "OpenAI 兼容 Bearer 鉴权入口可达", "raw": raw}
    return False, {"status": response.status_code, "message": f"OpenAI 兼容入口服务端错误 {response.status_code}", "raw": raw}

async def probe_openai_models_endpoint(client, base_url: str, api_key: str):
    url = upstream_models_url(base_url, "openai")
    response = await client.get(url, headers=upstream_model_headers(api_key, "openai"))
    try:
        raw = response.json() if response.text else {}
    except Exception:
        raw = response.text[:500]
    if response.status_code in (301, 302, 303, 307, 308):
        location = response.headers.get("Location") or response.headers.get("location") or ""
        suffix = f"：{location}" if location else ""
        return False, {"status": response.status_code, "message": f"OpenAI /v1/models 发生跳转{suffix}，请填写 API Base URL，不要填写网页登录地址", "raw": raw}
    if response.status_code in (401, 403):
        return False, {"status": response.status_code, "message": "OpenAI API Key 无效或无权限", "raw": raw}
    if looks_like_html_response(response.text):
        return False, {"status": response.status_code, "message": "OpenAI /v1/models 返回网页 HTML，请检查请求地址是否为 API Base URL", "raw": raw}
    if response.status_code < 300:
        grouped, ids, meta = parse_upstream_models(raw, "openai") if isinstance(raw, dict) else ({"image": [], "chat": [], "video": [], "audio": []}, [], {})
        grouped, ids = apply_agnes_model_defaults(base_url, grouped, ids)
        grouped, ids = apply_provider_registry_model_defaults(base_url, grouped, ids)
        grouped = apply_locked_recommended_model_rules(base_url, grouped)
        skipped_note = upstream_models_skipped_note(meta)
        return True, {
            "status": response.status_code,
            "message": f"OpenAI 兼容模型列表端点可用{f'，找到 {len(ids)} 个模型' if ids else ''}{f'（{skipped_note}）' if skipped_note else ''}",
            "raw": raw,
            "model_count": len(ids),
            "image_models": grouped["image"],
            "chat_models": grouped["chat"],
            "video_models": grouped["video"],
            "audio_models": grouped["audio"],
            "all": ids,
        }
    if 400 <= response.status_code < 500:
        return False, {"status": response.status_code, "message": f"OpenAI /v1/models 不可用 (HTTP {response.status_code})", "raw": raw}
    return False, {"status": response.status_code, "message": f"OpenAI /v1/models 服务端错误 {response.status_code}", "raw": raw}

async def probe_volcengine_auto_detect(client, base_url: str, api_key: str):
    task_ok, task_probe = await probe_volcengine_task_endpoint(client, base_url, api_key)
    if task_ok:
        return True, {
            "status": task_probe.get("status") or 200,
            "message": "检测到方舟/Ark 任务协议",
            "raw": {"task_probe": task_probe.get("raw")},
        }
    compat_ok, compat_probe = await probe_openai_compat_bearer_endpoint(client, base_url, api_key)
    if compat_ok:
        return True, {
            "status": compat_probe.get("status") or 200,
            "message": "检测到方舟/Ark Bearer 鉴权入口（OpenAI 兼容透传）",
            "raw": {"task_probe": task_probe, "openai_compat_probe": compat_probe.get("raw")},
        }
    return False, {
        "status": compat_probe.get("status") or task_probe.get("status") or 0,
        "message": compat_probe.get("message") or task_probe.get("message") or "未检测到方舟/Ark 兼容入口",
        "raw": {"task_probe": task_probe, "openai_compat_probe": compat_probe.get("raw")},
    }

def classify_upstream_model(mid):
    lc = str(mid or "").lower()
    video_keys = ["veo", "sora", "wan2", "wanx", "doubao-seedance", "doubao-1", "kling", "hailuo", "video", "t2v-", "i2v-", "s2v"]
    if any(k in lc for k in video_keys):
        return "video"
    image_keys = ["banana", "image", "dalle", "dall-e", "imagen", "flux", "stable", "sdxl", "midjourney", "nano-banana", "ideogram", "fal-ai", "z-image", "qwen-image", "klein", "seedream", "doubao-seedream", "text-to-image", "image-to-image"]
    if any(k in lc for k in image_keys):
        return "image"
    return "chat"

APIMART_MODEL_CATEGORIES = ("chat", "image", "video", "audio", "unknown")

def parse_upstream_models(raw, protocol="openai"):
    items = raw.get("data") if isinstance(raw, dict) else None
    if not items and isinstance(raw, dict):
        items = raw.get("models") or raw.get("list") or []
    if not isinstance(items, list):
        items = []
    grouped = {"image": [], "chat": [], "video": [], "audio": []}
    ids = []
    meta_counts = {"guessed_unknown": 0}
    for it in items:
        category = ""
        if isinstance(it, str):
            mid = it
        elif isinstance(it, dict):
            mid = it.get("id") or it.get("name") or it.get("model")
            category = str(it.get("category") or "").strip().lower()
        else:
            mid = ""
        if not mid:
            continue
        mid = str(mid)
        if protocol == "gemini" and mid.startswith("models/"):
            mid = mid[len("models/"):]
        # 带 expand=category 时以上游分类为准（audio 也收，画布音频节点用）；
        # unknown 只是「平台暂未收录分类元数据」，模型本身可用，按名称猜测归类；
        # 没有 category 的旧格式同样走启发式
        if category in grouped:
            grouped[category].append(mid)
        else:
            if category == "unknown":
                meta_counts["guessed_unknown"] += 1
            grouped[classify_upstream_model(mid)].append(mid)
        ids.append(mid)
    for key in grouped:
        grouped[key] = sorted(set(grouped[key]))
    ids = sorted(set(ids))
    meta = {"guessed_unknown": meta_counts["guessed_unknown"]}
    return grouped, ids, meta

def upstream_models_skipped_note(meta):
    guessed = int((meta or {}).get("guessed_unknown") or 0)
    return f"未知分类 {guessed} 个已按名称归类" if guessed else ""

def apply_agnes_model_defaults(base_url, grouped, ids):
    if "apihub.agnes-ai.com" not in str(base_url or "").strip().lower():
        return grouped, ids
    grouped = {key: list(value or []) for key, value in (grouped or {}).items()}
    ids = list(ids or [])
    for model in AGNES_DEFAULT_VIDEO_MODELS:
        if model not in ids:
            ids.append(model)
        if model not in grouped.setdefault("video", []):
            grouped["video"].append(model)
    ids = sorted(set(ids))
    grouped["video"] = sorted(set(grouped.get("video") or []))
    return grouped, ids

def apply_provider_registry_model_defaults(base_url, grouped, ids):
    """把注册表里该供应商的默认模型补进 /v1/models 的结果里。

    有些中转站的 /v1/models 会按令牌分组过滤模型：部分模型拿不到列表，但用同一个 Key 可以直接
    调用（文本走 /v1/chat/completions，图像走 /v1beta/models/{model}:generateContent）。
    默认清单来自 config/providers.json 的 default_models（可自行增删），代码不写死模型名。"""
    provider = {"base_url": str(base_url or "").strip()}
    defaults = {kind: provider_registry_default_models(provider, kind) for kind in ("image", "chat", "video", "audio")}
    if not any(defaults.values()):
        return grouped, ids
    grouped = {key: list(value or []) for key, value in (grouped or {}).items()}
    ids = list(ids or [])
    for key, models in defaults.items():
        bucket = grouped.setdefault(key, [])
        for model in models:
            if model not in ids:
                ids.append(model)
            if model not in bucket:
                bucket.append(model)
        grouped[key] = sorted(set(bucket))
    ids = sorted(set(ids))
    return grouped, ids

@app.post("/api/providers/test-connection")
async def test_provider_connection(payload: TestConnectionPayload):
    """测试请求地址是否可用：调上游 /v1/models。验证通过时同时把模型清单按类别返回，避免再调一次拉取接口。"""
    protocol = protocol_from_payload(payload)
    if protocol == "codex":
        status = await codex_status()
        payload_models = codex_models_payload(raw={"status": status})
        payload_models.update({
            "ok": bool(status.get("installed")),
            "status": 200 if status.get("installed") else 0,
            "message": status.get("message") or ("OpenAI Codex CLI 可用" if status.get("installed") else "未找到 OpenAI Codex CLI"),
        })
        return payload_models
    if protocol == "gemini-cli":
        status = await gemini_cli_status()
        payload_models = gemini_cli_models_payload(raw={"status": status})
        payload_models.update({
            "ok": bool(status.get("installed")),
            "status": 200 if status.get("installed") else 0,
            "message": status.get("message") or ("Antigravity CLI 可用" if status.get("installed") else "未找到 Antigravity CLI"),
        })
        return payload_models
    if protocol == "jimeng":
        status = await jimeng_status()
        return {
            "ok": bool(status.get("installed") and status.get("logged_in")),
            "status": 200 if status.get("logged_in") else 0,
            "message": status.get("message") or "即梦 CLI 已登录",
            "model_count": len(JIMENG_DEFAULT_IMAGE_MODELS) + len(JIMENG_DEFAULT_VIDEO_MODELS),
            "image_models": JIMENG_DEFAULT_IMAGE_MODELS,
            "chat_models": [],
            "video_models": JIMENG_DEFAULT_VIDEO_MODELS,
            "all": [*JIMENG_DEFAULT_IMAGE_MODELS, *JIMENG_DEFAULT_VIDEO_MODELS],
            "raw": status.get("raw"),
        }
    if protocol == "runninghub":
        provider = {"id": "runninghub", "name": "RunningHub", "base_url": (payload.base_url or RUNNINGHUB_DEFAULT_BASE_URL).strip().rstrip("/"), "protocol": "runninghub", "api_key": api_key_from_payload(payload, protocol)}
        payload_models = await runninghub_models_payload(provider)
        return {
            "ok": True,
            "status": 200,
            "message": "RunningHub OpenAPI 可用，已拉取官方直连模型注册表。",
            "model_count": payload_models["total"],
            "image_models": payload_models["image_models"],
            "chat_models": payload_models["chat_models"],
            "video_models": payload_models["video_models"],
            "all": payload_models["all"],
            "protocol": "runninghub",
            "raw": payload_models.get("raw"),
        }
    if protocol == "lovart":
        provider = {"id": payload.provider_id or "lovart", "name": "Lovart", "base_url": (payload.base_url or LOVART_DEFAULT_BASE_URL).strip().rstrip("/"), "protocol": "lovart", "use_proxy": payload.use_proxy}
        try:
            async with lovart_http_client(provider, 20) as client:
                data = await lovart_request(
                    client, provider, "POST", "/mode/query", body={},
                    access_key=str(payload.api_key or "").strip() or str(getattr(payload, "lovart_access_key", "") or "").strip(),
                    secret_key=str(getattr(payload, "lovart_secret_key", "") or "").strip(),
                )
        except httpx.HTTPError as e:
            reason = str(e) or type(e).__name__
            return {"ok": False, "status": 0, "protocol": "lovart", "message": f"Lovart 连通性测试失败：{reason[:300]}"}
        data = data if isinstance(data, dict) else {}
        details = []
        for key in ("mode", "current_mode"):
            value = data.get(key)
            if value not in (None, ""):
                details.append(f"模式：{value}")
                break
        if data.get("unlimited") is not None:
            details.append(f"unlimited={bool(data.get('unlimited'))}")
        for key in ("credits", "credit", "balance", "quota", "points"):
            value = data.get(key)
            if value not in (None, ""):
                details.append(f"额度：{value}")
                break
        message = "Lovart 密钥有效，签名鉴权通过"
        if details:
            message = f"{message}（{'，'.join(str(item) for item in details)}）"
        return {
            "ok": True,
            "status": 200,
            "protocol": "lovart",
            "message": message,
            "model_count": len(LOVART_DEFAULT_IMAGE_MODELS) + len(LOVART_DEFAULT_CHAT_MODELS) + len(LOVART_DEFAULT_VIDEO_MODELS),
            "image_models": LOVART_DEFAULT_IMAGE_MODELS,
            "chat_models": LOVART_DEFAULT_CHAT_MODELS,
            "video_models": LOVART_DEFAULT_VIDEO_MODELS,
            "all": [*LOVART_DEFAULT_IMAGE_MODELS, *LOVART_DEFAULT_CHAT_MODELS, *LOVART_DEFAULT_VIDEO_MODELS],
            "raw": data,
        }
    base_url = (payload.base_url or "").strip().rstrip("/")
    if not base_url:
        raise HTTPException(status_code=400, detail="请先填写请求地址")
    if not re.match(r"^https?://", base_url):
        raise HTTPException(status_code=400, detail="请求地址必须以 http:// 或 https:// 开头")
    api_key = api_key_from_payload(payload, protocol)
    if not api_key:
        key_name = "方舟 API Key" if protocol == "volcengine" else "API Key"
        raise HTTPException(status_code=400, detail=f"请先填写或保存 {key_name}")
    url = upstream_models_url(base_url, protocol)
    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env({"use_proxy": payload.use_proxy}), timeout=15) as client:
            resp = await client.get(url, headers=upstream_model_headers(api_key, protocol))
            if resp.status_code in (301, 302, 303, 307, 308):
                location = resp.headers.get("Location") or resp.headers.get("location") or ""
                suffix = f"：{location}" if location else ""
                endpoint_label = "/v1beta/models" if protocol == "gemini" else "/api/v3/models" if protocol == "volcengine" else "/openapi/v2/models" if protocol == "runninghub" else "/v1/models"
                return {"ok": False, "status": resp.status_code, "message": f"上游 {endpoint_label} 发生跳转{suffix}，请填写 API Base URL，不要填写网页登录地址"}
            if looks_like_html_response(resp.text):
                endpoint_label = "/v1beta/models" if protocol == "gemini" else "/api/v3/models" if protocol == "volcengine" else "/openapi/v2/models" if protocol == "runninghub" else "/v1/models"
                return {"ok": False, "status": resp.status_code, "message": f"上游 {endpoint_label} 返回网页 HTML，请检查请求地址是否为 API Base URL"}
            if resp.status_code >= 400:
                if protocol == "volcengine":
                    detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                    if detected:
                        message = f"{probe.get('message') or '方舟任务接口可达'}；但 /api/v3/models 不可用。请按实际方舟控制台模型名称手动填写视频模型。"
                        return volcengine_default_model_payload(status=probe.get("status") or resp.status_code, message=message, raw={"models_error": resp.text[:300], **(probe.get("raw") or {})})
                elif protocol == "openai":
                    detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                    if detected:
                        message = f"{probe.get('message') or '检测到方舟/Ark 兼容入口'}；OpenAI /v1/models 不可用，已自动切换为方舟协议。请按实际方舟控制台模型名称手动填写视频模型。"
                        return volcengine_default_model_payload(status=probe.get("status") or resp.status_code, message=message, raw={"models_error": resp.text[:300], **(probe.get("raw") or {})})
                return {"ok": False, "status": resp.status_code, "message": resp.text[:300]}
            data = resp.json() if resp.text else {}
            grouped, ids, meta = parse_upstream_models(data, protocol)
            grouped, ids = apply_agnes_model_defaults(base_url, grouped, ids)
            grouped, ids = apply_provider_registry_model_defaults(base_url, grouped, ids)
            grouped = apply_locked_recommended_model_rules(base_url, grouped)
            if protocol == "volcengine" and not ids:
                detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                if detected:
                    return volcengine_default_model_payload(status=resp.status_code, raw=data)
            skipped_note = upstream_models_skipped_note(meta)
            return {
                "ok": True,
                "status": resp.status_code,
                "model_count": len(ids),
                "image_models": grouped["image"],
                "chat_models": grouped["chat"],
                "video_models": grouped["video"],
                "audio_models": grouped["audio"],
                "all": ids,
                "image_request_mode": detect_image_request_mode(base_url, ids) or normalize_image_request_mode(getattr(payload, "image_request_mode", "")),
                "skipped": meta,
                "message": f"已连通，找到 {len(ids)} 个模型（图像 {len(grouped['image'])} / 对话 {len(grouped['chat'])} / 视频 {len(grouped['video'])} / 音频 {len(grouped['audio'])}）{f'（{skipped_note}）' if skipped_note else ''}",
            }
    except httpx.HTTPError as e:
        if protocol == "volcengine":
            try:
                async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env({"use_proxy": payload.use_proxy}), timeout=15) as client:
                    detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                    if detected:
                        message = f"{probe.get('message') or '方舟任务接口可达'}；但模型列表请求失败。请按实际方舟控制台模型名称手动填写视频模型。"
                        return volcengine_default_model_payload(status=probe.get("status") or 0, message=message, raw={"models_error": str(e)[:300], **(probe.get("raw") or {})})
            except Exception:
                pass
        return {"ok": False, "status": 0, "message": (str(e) or f"连接上游失败（{type(e).__name__}），请检查请求地址与网络")[:300]}

@app.post("/api/providers/probe-async")
async def probe_async_endpoint(payload: TestConnectionPayload):
    """验证异步协议：用假 task_id 请求 GET /v1/tasks/{fake_id}。
    收到 400 Invalid task ID = 端点存在且 Key 有效；401/403 = Key 无效；404/连接失败 = 不支持异步端点。"""
    base_url = (payload.base_url or "").strip().rstrip("/")
    protocol = protocol_from_payload(payload)
    if protocol == "codex":
        status = await codex_status()
        return {
            "ok": bool(status.get("installed")),
            "protocol": "codex",
            "status_code": 200 if status.get("installed") else 0,
            "message": status.get("message") or "OpenAI Codex CLI 本机检测完成",
            "raw": status,
        }
    if protocol == "gemini-cli":
        status = await gemini_cli_status()
        return {
            "ok": bool(status.get("installed")),
            "protocol": "gemini-cli",
            "status_code": 200 if status.get("installed") else 0,
            "message": status.get("message") or "Antigravity CLI 本机检测完成",
            "raw": status,
        }
    if not base_url:
        raise HTTPException(status_code=400, detail="请先填写请求地址")
    api_key = api_key_from_payload(payload, protocol)
    if not api_key:
        raise HTTPException(status_code=400, detail="请先填写或保存 API Key")
    if protocol == "volcengine":
        try:
            async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env({"use_proxy": payload.use_proxy}), timeout=15) as client:
                task_ok, task_probe = await probe_volcengine_task_endpoint(client, base_url, api_key)
                if task_ok:
                    return {
                        "ok": True,
                        "protocol": "volcengine",
                        "status_code": task_probe.get("status") or 200,
                        "message": "方舟/Ark 任务协议可用",
                        "raw": task_probe.get("raw"),
                    }
                compat_ok, compat_probe = await probe_openai_compat_bearer_endpoint(client, base_url, api_key)
                if compat_ok:
                    return {
                        "ok": True,
                        "protocol": "volcengine",
                        "status_code": compat_probe.get("status") or 200,
                        "message": "方舟/Ark Bearer 鉴权入口可用（OpenAI 兼容透传）",
                        "raw": {"task_probe": task_probe, "openai_compat_probe": compat_probe.get("raw")},
                    }
                return {
                    "ok": False,
                    "protocol": "volcengine",
                    "status_code": compat_probe.get("status") or task_probe.get("status") or 0,
                    "message": compat_probe.get("message") or task_probe.get("message") or "方舟/Ark 任务协议不可用",
                    "raw": {"task_probe": task_probe, "openai_compat_probe": compat_probe.get("raw")},
                }
        except httpx.HTTPError as e:
            raise HTTPException(status_code=502, detail=str(e)[:300])
    tasks_base = base_url if base_url.endswith("/v1") else f"{base_url}/v1"
    probe_url = f"{tasks_base}/tasks/healthcheck_probe_do_not_submit"
    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env({"use_proxy": payload.use_proxy}), timeout=15) as client:
            resp = await client.get(probe_url, headers={"Authorization": bearer_auth_value(api_key), "Accept": "application/json"})
            try:
                body = resp.json()
            except Exception:
                body = resp.text[:500]
            sc = resp.status_code
            # 判断结果
            err_msg = ""
            if isinstance(body, dict):
                err = body.get("error") or {}
                if isinstance(err, dict):
                    err_msg = str(err.get("message") or "").lower()
                else:
                    err_msg = str(err).lower()
            # 400 + "invalid task id" → 端点存在，Key 有效
            if sc == 400 and "invalid task id" in err_msg:
                return {"ok": True, "protocol": "apimart", "status_code": sc, "message": "APIMart 异步任务端点可用，API Key 已通过认证", "raw": body}

            async_probe = {"status": sc, "message": "", "raw": body}
            if sc in (301, 302, 303, 307, 308):
                location = resp.headers.get("Location") or resp.headers.get("location") or ""
                async_probe["message"] = f"/v1/tasks/ 发生跳转{f'：{location}' if location else ''}"
            elif looks_like_html_response(resp.text):
                async_probe["message"] = "/v1/tasks/ 返回网页 HTML"
            elif sc in (401, 403):
                async_probe["message"] = "/v1/tasks/ 返回鉴权失败"
            elif sc == 404:
                async_probe["message"] = "平台不支持 /v1/tasks/ 端点，可能不是 APIMart 异步协议"
            elif 400 <= sc < 500:
                async_probe["message"] = f"/v1/tasks/ 返回 {sc}"
            elif sc < 300:
                async_probe["message"] = f"/v1/tasks/ 返回 {sc}（意外成功）"
            else:
                async_probe["message"] = f"/v1/tasks/ 服务端错误 {sc}"

            if protocol == "apimart":
                return {"ok": False, "protocol": "apimart", "status_code": sc, "message": async_probe["message"], "raw": body}

            openai_ok, openai_probe = await probe_openai_models_endpoint(client, base_url, api_key)
            if not openai_ok and protocol == "openai":
                # /v1/models 不可用，先确认是不是“没实现 models 接口的 OpenAI 兼容站”：探一下 /v1/chat/completions。
                # 可达就判定为 OpenAI 兼容（很多网关不暴露 /v1/models），避免被下面的方舟探测（404 也算可达）误判成方舟。
                compat_ok, compat_probe = await probe_openai_compat_bearer_endpoint(client, base_url, api_key)
                # 仅当 /v1/chat/completions 确实存在（返回 2xx 或我们发空 messages 触发的 400 等，而非 404 路径不存在）
                # 才判为 OpenAI 兼容；404 说明该路径不存在，留给后面的方舟探测。
                if compat_ok and (compat_probe.get("status") or 0) != 404:
                    return {
                        "ok": True,
                        "protocol": "openai",
                        "status_code": compat_probe.get("status") or openai_probe.get("status") or sc,
                        "message": "OpenAI 兼容入口可达（该站未提供 /v1/models，模型请手动填写）",
                        "raw": {"async_probe": async_probe, "openai_probe": openai_probe.get("raw"), "openai_compat_probe": compat_probe.get("raw")},
                        "model_count": 0,
                        "image_models": [],
                        "chat_models": [],
                        "video_models": [],
                        "all": [],
                    }
                detected, volc_probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                if detected:
                    return {
                        "ok": True,
                        "protocol": "volcengine",
                        "status_code": volc_probe.get("status") or openai_probe.get("status") or sc,
                        "message": f"{volc_probe.get('message') or '检测到方舟/Ark 兼容入口'}，已自动切换为方舟/Ark 任务协议",
                        "raw": {"async_probe": async_probe, "openai_probe": openai_probe.get("raw"), **(volc_probe.get("raw") or {})},
                    }
            return {
                "ok": openai_ok,
                "protocol": "openai",
                "status_code": openai_probe.get("status") or sc,
                "message": openai_probe.get("message") or "OpenAI 兼容验证完成",
                "raw": {"async_probe": async_probe, "openai_probe": openai_probe.get("raw")},
                "model_count": openai_probe.get("model_count") or 0,
                "image_models": openai_probe.get("image_models") or [],
                "chat_models": openai_probe.get("chat_models") or [],
                "video_models": openai_probe.get("video_models") or [],
                "audio_models": openai_probe.get("audio_models") or [],
                "all": openai_probe.get("all") or [],
                "image_request_mode": detect_image_request_mode(base_url, openai_probe.get("all") or []) or normalize_image_request_mode(getattr(payload, "image_request_mode", "")),
            }
    except httpx.HTTPError as e:
        raise HTTPException(status_code=502, detail=str(e)[:300])

async def fetch_models_from_upstream(base_url: str, api_key: str, protocol: str = "openai", image_request_mode: str = "openai"):
    """从上游模型列表端点拉取模型，并按名称做轻量分类。"""
    protocol = protocol if protocol in SUPPORTED_PROVIDER_PROTOCOLS else "openai"
    if protocol == "codex":
        status = await codex_status()
        payload = codex_models_payload(raw={"status": status})
        payload["message"] = status.get("message") or payload["message"]
        return payload
    if protocol == "gemini-cli":
        status = await gemini_cli_status()
        payload = gemini_cli_models_payload(raw={"status": status})
        payload["message"] = status.get("message") or payload["message"]
        return payload
    if protocol == "jimeng":
        return {
            "total": len(JIMENG_DEFAULT_IMAGE_MODELS) + len(JIMENG_DEFAULT_VIDEO_MODELS),
            "image_models": JIMENG_DEFAULT_IMAGE_MODELS,
            "chat_models": [],
            "video_models": JIMENG_DEFAULT_VIDEO_MODELS,
            "all": [*JIMENG_DEFAULT_IMAGE_MODELS, *JIMENG_DEFAULT_VIDEO_MODELS],
        }
    if protocol == "runninghub":
        provider = {"id": "runninghub", "name": "RunningHub", "base_url": base_url or RUNNINGHUB_DEFAULT_BASE_URL, "protocol": "runninghub", "api_key": api_key}
        return await runninghub_models_payload(provider)
    if protocol == "lovart":
        return {
            "total": len(LOVART_DEFAULT_IMAGE_MODELS) + len(LOVART_DEFAULT_CHAT_MODELS) + len(LOVART_DEFAULT_VIDEO_MODELS),
            "protocol": "lovart",
            "image_models": LOVART_DEFAULT_IMAGE_MODELS,
            "chat_models": LOVART_DEFAULT_CHAT_MODELS,
            "video_models": LOVART_DEFAULT_VIDEO_MODELS,
            "all": [*LOVART_DEFAULT_IMAGE_MODELS, *LOVART_DEFAULT_CHAT_MODELS, *LOVART_DEFAULT_VIDEO_MODELS],
            "message": "Lovart OpenAPI 使用平台内置模型清单。",
            "raw": {},
        }
    base_url = (base_url or "").strip().rstrip("/")
    if not base_url:
        raise HTTPException(status_code=400, detail="请先填写请求地址")
    if not re.match(r"^https?://", base_url):
        raise HTTPException(status_code=400, detail="请求地址必须以 http:// 或 https:// 开头")
    api_key = volcengine_provider_api_key(api_key) if protocol == "volcengine" else (api_key or "").strip()
    if not api_key:
        key_name = "方舟 API Key" if protocol == "volcengine" else "API Key"
        raise HTTPException(status_code=400, detail=f"请先填写或保存 {key_name}")
    url = upstream_models_url(base_url, protocol)
    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=30) as client:
            resp = await client.get(url, headers=upstream_model_headers(api_key, protocol))
            endpoint_label = "/v1beta/models" if protocol == "gemini" else "/api/v3/models" if protocol == "volcengine" else "/openapi/v2/models" if protocol == "runninghub" else "/v1/models"
            if resp.status_code in (301, 302, 303, 307, 308):
                location = resp.headers.get("Location") or resp.headers.get("location") or ""
                suffix = f"：{location}" if location else ""
                raise HTTPException(status_code=400, detail=f"上游 {endpoint_label} 发生跳转{suffix}，请填写 API Base URL，不要填写网页登录地址")
            if looks_like_html_response(resp.text):
                raise HTTPException(status_code=400, detail=f"上游 {endpoint_label} 返回网页 HTML，请检查请求地址是否为 API Base URL")
            if resp.status_code >= 400:
                if protocol == "volcengine":
                    detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                    if detected:
                        payload = volcengine_default_model_payload(
                            status=probe.get("status") or resp.status_code,
                            message=f"{probe.get('message') or '方舟任务接口可达'}；但 /api/v3/models 不可用。请按实际方舟控制台模型名称手动填写视频模型。",
                            raw={"models_error": resp.text[:300], **(probe.get("raw") or {})},
                        )
                        return {
                            "total": payload["model_count"],
                            "protocol": payload["protocol"],
                            "image_models": payload["image_models"],
                            "chat_models": payload["chat_models"],
                            "video_models": payload["video_models"],
                            "all": payload["all"],
                            "message": payload["message"],
                            "raw": payload["raw"],
                        }
                elif protocol == "openai":
                    detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                    if detected:
                        payload = volcengine_default_model_payload(
                            status=probe.get("status") or resp.status_code,
                            message=f"{probe.get('message') or '检测到方舟/Ark 兼容入口'}；OpenAI /v1/models 不可用，已自动切换为方舟协议。请按实际方舟控制台模型名称手动填写视频模型。",
                            raw={"models_error": resp.text[:300], **(probe.get("raw") or {})},
                        )
                        return {
                            "total": payload["model_count"],
                            "protocol": payload["protocol"],
                            "image_models": payload["image_models"],
                            "chat_models": payload["chat_models"],
                            "video_models": payload["video_models"],
                            "all": payload["all"],
                            "message": payload["message"],
                            "raw": payload["raw"],
                        }
                raise HTTPException(status_code=resp.status_code, detail=f"上游 {endpoint_label} 失败：{resp.text[:300]}")
            raw = resp.json()
    except httpx.HTTPError as e:
        if protocol == "volcengine":
            try:
                async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=15) as client:
                    detected, probe = await probe_volcengine_auto_detect(client, base_url, api_key)
                    if detected:
                        payload = volcengine_default_model_payload(
                            status=probe.get("status") or 0,
                            message=f"{probe.get('message') or '方舟任务接口可达'}；但模型列表请求失败。请按实际方舟控制台模型名称手动填写视频模型。",
                            raw={"models_error": str(e)[:300], **(probe.get("raw") or {})},
                        )
                        return {
                            "total": payload["model_count"],
                            "protocol": payload["protocol"],
                            "image_models": payload["image_models"],
                            "chat_models": payload["chat_models"],
                            "video_models": payload["video_models"],
                            "all": payload["all"],
                            "message": payload["message"],
                            "raw": payload["raw"],
                        }
            except Exception:
                pass
        raise HTTPException(status_code=502, detail=f"请求上游模型列表失败：{e}")
    grouped, ids, meta = parse_upstream_models(raw, protocol)
    grouped, ids = apply_agnes_model_defaults(base_url, grouped, ids)
    grouped, ids = apply_provider_registry_model_defaults(base_url, grouped, ids)
    grouped = apply_locked_recommended_model_rules(base_url, grouped)
    if protocol == "volcengine" and not ids:
        payload = volcengine_default_model_payload(raw=raw)
        return {
            "total": payload["model_count"],
            "image_models": payload["image_models"],
            "chat_models": payload["chat_models"],
            "video_models": payload["video_models"],
            "all": payload["all"],
            "message": payload["message"],
            "raw": payload["raw"],
        }
    skipped_note = upstream_models_skipped_note(meta)
    return {
        "total": len(ids),
        "image_models": grouped["image"],
        "chat_models": grouped["chat"],
        "video_models": grouped["video"],
        "audio_models": grouped["audio"],
        "all": ids,
        "image_request_mode": detect_image_request_mode(base_url, ids) or normalize_image_request_mode(image_request_mode),
        "skipped": meta,
        "message": f"找到 {len(ids)} 个模型（图像 {len(grouped['image'])} / 对话 {len(grouped['chat'])} / 视频 {len(grouped['video'])} / 音频 {len(grouped['audio'])}）{f'（{skipped_note}）' if skipped_note else ''}",
    }

@app.post("/api/providers/fetch-models")
async def fetch_upstream_models_from_payload(payload: TestConnectionPayload):
    """按页面当前表单值拉取模型，支持新增平台未保存时直接使用临时 Base URL / Key。"""
    protocol = protocol_from_payload(payload)
    api_key = api_key_from_payload(payload, protocol)
    return await fetch_models_from_upstream(payload.base_url, api_key, protocol, payload.image_request_mode)

@app.get("/api/providers/{provider_id}/fetch-models")
async def fetch_upstream_models(provider_id: str):
    """从已保存的上游 OpenAI 兼容接口拉取 /v1/models 列表，按名称智能分类为 image/chat/video。"""
    provider = get_api_provider_exact(provider_id)
    if is_codex_provider(provider):
        return await fetch_models_from_upstream("", "", "codex", provider.get("image_request_mode") or "openai")
    if is_gemini_cli_provider(provider):
        return await fetch_models_from_upstream("", "", "gemini-cli", provider.get("image_request_mode") or "openai")
    if is_lovart_provider(provider):
        return await fetch_models_from_upstream(provider.get("base_url") or "", "", "lovart", provider.get("image_request_mode") or "openai")
    api_key = os.getenv(runninghub_wallet_key_env(), "") if provider["id"] == "runninghub" else ""
    if not api_key:
        api_key = provider_env_key_value(provider["id"])
    if not api_key:
        raise HTTPException(status_code=400, detail=f"{provider.get('name') or provider_id} 未配置 API Key")
    return await fetch_models_from_upstream(provider.get("base_url") or "", api_key, provider_protocol(provider), provider.get("image_request_mode") or "openai")

class LovartModePayload(BaseModel):
    unlimited: bool = False
    base_url: str = ""
    lovart_access_key: str = ""
    lovart_secret_key: str = ""

@app.post("/api/providers/lovart/mode")
async def set_lovart_mode(payload: LovartModePayload):
    provider = lovart_provider_config()
    base_url = str(payload.base_url or "").strip().rstrip("/")
    if base_url:
        provider = {**provider, "base_url": base_url}
    access_key = str(payload.lovart_access_key or "").strip()
    secret_key = str(payload.lovart_secret_key or "").strip()
    # unlimited=true 是排队模式（不消耗积分），false 是快速模式（消耗积分）
    unlimited = bool(payload.unlimited)
    try:
        async with lovart_http_client(provider, 20) as client:
            await lovart_request(client, provider, "POST", "/mode/set", body={"unlimited": unlimited}, access_key=access_key, secret_key=secret_key)
            data = await lovart_request(client, provider, "POST", "/mode/query", body={}, access_key=access_key, secret_key=secret_key)
    except httpx.HTTPError as exc:
        raise HTTPException(status_code=502, detail=f"请求 Lovart 接口失败：{exc}") from exc
    data = data if isinstance(data, dict) else {}
    mode = ""
    for key in ("mode", "current_mode"):
        value = data.get(key)
        if value not in (None, ""):
            mode = str(value)
            break
    credits = None
    for key in ("credits", "credit", "balance", "quota", "points"):
        value = data.get(key)
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            credits = value
            break
        text = str(value or "").strip()
        if re.fullmatch(r"-?\d+(?:\.\d+)?", text):
            credits = float(text) if "." in text else int(text)
            break
    effective = unlimited if data.get("unlimited") is None else bool(data.get("unlimited"))
    lovart_store_unlimited(effective)
    label = "排队模式（不消耗积分）" if effective else "快速模式（消耗积分）"
    message = f"Lovart 已切换为{label}"
    if mode:
        message = f"{message}，当前模式：{mode}"
    if credits is not None:
        message = f"{message}，剩余额度：{credits}"
    return {"ok": True, "unlimited": effective, "mode": mode, "credits": credits, "message": message}

_HTTP_ERROR_READABLE = {
    "ReadTimeout": "上游在规定时间内没有返回（读取超时）",
    "ConnectTimeout": "连接上游超时（网络或上游网关无响应）",
    "WriteTimeout": "把请求发送到上游时超时",
    "PoolTimeout": "连接池排队超时",
    "ConnectError": "连接上游失败（网络不可达或 TLS 握手失败）",
    "RemoteProtocolError": "上游提前断开了连接",
}

def http_error_detail(exc):
    """网络/超时类异常的可读原因。

    httpx 的超时异常 str(exc) 往往是空串，直接拼进 detail 会让用户只看到「请求上游生图接口失败：」，
    看不到任何原因。空串就退回异常类型名 + 一句人话。"""
    text = str(exc or "").strip()
    if text:
        return text
    name = type(exc).__name__
    readable = _HTTP_ERROR_READABLE.get(name)
    return f"{name}（{readable}）" if readable else name

async def build_online_image_result(payload: OnlineImageRequest):
    provider = get_api_provider(payload.provider_id)
    model = preferred_image_model(provider, payload.model)
    refs = [ref.dict() for ref in payload.reference_images if ref.url]
    image_refs = image_references(refs)
    # 输出格式：静态图下发 ''（不发字段）；非 APIMart 平台没有这个能力，直接拒绝而不是悄悄忽略。
    # refs 已包含蒙版（role=mask / name 以 _mask.png 结尾同样在 reference_images 里），SVG 有引用即提前 400。
    output_format = normalize_image_output_format(getattr(payload, "output_format", ""))
    if output_format:
        if not is_apimart_provider(provider):
            raise HTTPException(
                status_code=400,
                detail=f"{provider.get('name') or provider['id']} 不支持选择输出格式，请改用默认输出。",
            )
        apimart_output_format_fields(
            model, apimart_image_caps_for(provider, model), output_format, has_refs=bool(refs))
    # 张数上限与助手链路同一套 caps：按模型单次上限拆批，请求几张就生成几张（不吞总数）
    request_batches = direct_image_request_batches(provider, model, payload.n)
    requested_n = sum(request_batches)
    count = request_batches[0] if request_batches else 1
    model_caps = model_caps_for(provider, model, "image") or {}
    native_n_max = int(model_caps.get("n_max") or 1)
    # 「原图比例」：size 是 auto/空、或请求显式带原图比例时，按源图（参考图/原图）真实比例算尺寸；
    # 没有源图才退回方图，并把原因写进 size_notice 让前端能提示
    effective_size = str(payload.size or "").strip()
    # 显式像素尺寸优先；只有尺寸是 auto/空、或显式声明了自适应比例且没给像素尺寸时才按源图算
    has_pixel_size = bool(re.fullmatch(r"\d+\s*[x×]\s*\d+", effective_size))
    ratio_hint = str(getattr(payload, "ratio", "") or "").strip()
    auto_size = (_agent_auto_ratio(effective_size)
                 or (bool(ratio_hint) and _agent_auto_ratio(ratio_hint) and not has_pixel_size))
    auto_size_note = ""
    if auto_size:
        source_size, _source_ratio, source_note = _agent_auto_ratio_image_size(provider, model, image_refs)
        if source_size:
            effective_size = source_size
            auto_size_note = source_note
        else:
            effective_size = "1024x1024"
            auto_size_note = ("参考图尺寸读不到（远程或非本地素材），按方图尺寸生成" if image_refs
                              else "没有参考图，按方图尺寸生成")
    async def generate_one(request_n=1):
        notice = {}
        image_data, raw_item = await generate_ai_image(
            payload.prompt, effective_size, payload.quality, model, image_refs,
            provider["id"], payload.background, notice, request_n,
            payload.midjourney_version, payload.midjourney_hd,
            getattr(payload, "thinking_mode", None), output_format,
            payload.frame_count, payload.frame_duration_ms, payload.svg_model)
        try:
            image_items = extract_images(raw_item) if isinstance(raw_item, dict) else [image_data]
        except HTTPException:
            image_items = [image_data]
        local_urls = []
        local_items = []
        for item in image_items:
            local_url = await save_ai_image_to_output(item, prefix="online_")
            if local_url:
                local_urls.append(local_url)
                local_items.append(image_output_meta(local_url, item))
        return local_urls, local_items, raw_item, notice
    try:
        # 每批按模型上限发；请求 4 张、模型一次只能 1 张时就是 4 次单张请求，不是 1 张
        generated = await asyncio.gather(*(generate_one(step) for step in request_batches))
    except httpx.HTTPStatusError as exc:
        log_net_error(f"生图 HTTP状态错误 provider={provider.get('id')} model={model} size={payload.size}", exc)
        text = exc.response.text or ''
        friendly = friendly_image_error_detail(text, payload.size, model)
        detail = friendly or f"上游生图接口错误：{text[:300]}"
        raise HTTPException(status_code=exc.response.status_code, detail=detail) from exc
    except httpx.HTTPError as exc:
        log_net_error(f"生图 网络/TLS错误 provider={provider.get('id')} model={model}", exc)
        retried = int(getattr(exc, "connect_retry_count", 0) or 0)
        suffix = f"（已重试 {retried} 次）" if retried else ""
        raise HTTPException(status_code=502, detail=f"请求上游生图接口失败{suffix}：{http_error_detail(exc)}") from exc

    local_urls = [url for urls, _items, _raw, _notice in generated for url in (urls or []) if url]
    local_items = [item for _urls, items, _raw, _notice in generated for item in (items or []) if item.get("url")]
    raw = generated[0][2] if generated else {}
    size_notice = auto_size_note or next((notice.get("size_notice") for *_rest, notice in generated if notice.get("size_notice")), "")
    if not local_urls:
        provider_name = provider.get("name") or provider["id"]
        raw_text = json.dumps(raw, ensure_ascii=False)[:800] if isinstance(raw, (dict, list)) else str(raw)[:800]
        raise HTTPException(status_code=502, detail=f"{provider_name} 没有返回图片：{raw_text}")
    result = {
        "prompt": payload.prompt,
        "images": local_urls,
        "image_items": local_items,
        "timestamp": time.time(),
        "type": "online",
        "model": model,
        "provider_id": provider["id"],
        "provider_name": provider.get("name") or provider["id"],
        "task_id": extract_task_id(raw) if isinstance(raw, dict) else None,
        "request_id": raw.get("id") if isinstance(raw, dict) else None,
        "requested_n": requested_n,
        "batch_n": count,
        "requests": len(request_batches),
        "model_max_batch": int(native_n_max or 0),
        "params": {"provider_id": provider["id"], "model": model, "size": effective_size, "quality": payload.quality, "background": normalize_image_background(payload.background), "n": requested_n, "batch_n": count, "requests": len(request_batches), "output_format": output_format, "reference_images": refs},
        "raw_usage": raw.get("usage") if isinstance(raw, dict) else None,
    }
    _attach_upstream_cost(result, raw)
    if size_notice:
        result["size_notice"] = size_notice
    save_to_history(result)
    if GLOBAL_LOOP:
        asyncio.run_coroutine_threadsafe(manager.broadcast_new_image(result), GLOBAL_LOOP)
    return result

@app.post("/api/online-image")
async def online_image(payload: OnlineImageRequest):
    payload.provider_id = member_provider(payload.provider_id)
    provider = get_api_provider(payload.provider_id)
    try:
        model = preferred_image_model(provider, payload.model)
    except HTTPException:
        model = str(payload.model or "")
    charge = credits_charge_start("image", model, _credits_image_params(payload),
                                 provider=payload.provider_id)
    try:
        result = await build_online_image_result(payload)
    except Exception:
        credits_charge_refund(charge, "image_failed")
        raise
    credits = credits_charge_settle(charge, result=result)
    return credits_attach(result, credits)

@app.post("/api/image-task-query")
async def query_image_task(payload: ImageTaskQueryRequest):
    provider = get_api_provider(payload.provider_id)
    task_id = str(payload.task_id or "").strip()
    if is_runninghub_provider(provider):
        api_key = runninghub_api_key(provider)
        url = runninghub_endpoint_url(provider, "/task/openapi/outputs")
        try:
            async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env(provider), timeout=httpx.Timeout(connect=20.0, read=240.0, write=30.0, pool=20.0)) as client:
                response = await client.post(url, headers=runninghub_app_headers(True), json={"apiKey": api_key, "taskId": task_id})
                response.raise_for_status()
                raw = response.json()
                code = raw.get("code") if isinstance(raw, dict) else None
                if code in (0, "0"):
                    local_urls = []
                    local_items = []
                    for remote in runninghub_extract_outputs(raw.get("data")):
                        try:
                            local_url = await runninghub_store_remote_output(client, remote)
                        except Exception:
                            local_url = rewrite_runninghub_file_url(remote)
                        if local_url:
                            local_urls.append(local_url)
                            local_items.append(image_output_meta(local_url))
                    result = {
                        "status": "succeeded",
                        "prompt": "",
                        "images": local_urls,
                        "image_items": local_items,
                        "timestamp": time.time(),
                        "type": "online",
                        "model": "",
                        "provider_id": provider["id"],
                        "provider_name": provider.get("name") or provider["id"],
                        "task_id": task_id,
                        "request_id": "",
                        "params": {"provider_id": provider["id"]},
                        "raw": raw,
                    }
                    save_to_history(result)
                    if GLOBAL_LOOP:
                        asyncio.run_coroutine_threadsafe(manager.broadcast_new_image(result), GLOBAL_LOOP)
                    return result
                if code in (805, "805"):
                    return {
                        "status": "failed",
                        "task_id": task_id,
                        "provider_id": provider["id"],
                        "provider_name": provider.get("name") or provider["id"],
                        "error": runninghub_fail_reason(raw),
                        "raw": raw,
                    }
                return {
                    "status": "running",
                    "task_id": task_id,
                    "provider_id": provider["id"],
                    "provider_name": provider.get("name") or provider["id"],
                    "message": "RunningHub 任务仍在生成中",
                    "raw": raw,
                }
        except httpx.HTTPStatusError as exc:
            text = exc.response.text or ""
            raise HTTPException(status_code=exc.response.status_code, detail=f"查询 RunningHub 任务失败：{text[:300]}") from exc
        except httpx.HTTPError as exc:
            raise HTTPException(status_code=502, detail=f"查询 RunningHub 任务失败：{exc}") from exc
    timeout = httpx.Timeout(connect=20.0, read=300.0, write=60.0, pool=20.0)
    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env(provider), timeout=timeout, follow_redirects=True) as client:
            raw = await fetch_image_task_payload(client, task_id, provider)
    except httpx.HTTPStatusError as exc:
        log_net_error(f"查询生图任务 HTTP状态错误 provider={provider.get('id')} task_id={task_id}", exc)
        text = exc.response.text or ""
        raise HTTPException(status_code=exc.response.status_code, detail=f"查询上游生图任务失败：{text[:300]}") from exc
    except httpx.HTTPError as exc:
        log_net_error(f"查询生图任务 网络/TLS错误 provider={provider.get('id')} task_id={task_id}", exc)
        raise HTTPException(status_code=502, detail=f"查询上游生图任务失败：{exc}") from exc

    status = image_task_status(raw)
    image_items = []
    try:
        image_items = extract_images(raw)
    except HTTPException:
        image_items = []
    if image_items:
        local_urls = []
        local_items = []
        for item in image_items:
            local_url = await save_ai_image_to_output(item, prefix="online_")
            if local_url:
                local_urls.append(local_url)
                local_items.append(image_output_meta(local_url, item))
        result = {
            "status": "succeeded",
            "prompt": "",
            "images": local_urls,
            "image_items": local_items,
            "timestamp": time.time(),
            "type": "online",
            "model": "",
            "provider_id": provider["id"],
            "provider_name": provider.get("name") or provider["id"],
            "task_id": task_id,
            "request_id": raw.get("id") if isinstance(raw, dict) else "",
            "params": {"provider_id": provider["id"]},
            "raw": raw,
        }
        save_to_history(result)
        if GLOBAL_LOOP:
            asyncio.run_coroutine_threadsafe(manager.broadcast_new_image(result), GLOBAL_LOOP)
        return result
    if status in IMAGE_TASK_FAILED_STATUSES:
        return {
            "status": "failed",
            "task_id": task_id,
            "provider_id": provider["id"],
            "provider_name": provider.get("name") or provider["id"],
            "error": image_task_fail_reason(raw),
            "raw": raw,
        }
    return {
        "status": "running",
        "task_id": task_id,
        "provider_id": provider["id"],
        "provider_name": provider.get("name") or provider["id"],
        "message": "任务仍在生成中",
        "raw": raw,
    }

async def run_canvas_image_task(task_id: str, payload: OnlineImageRequest):
    """图片生成任务执行器（Task Engine worker 调用）。
    阶段：running → provider_processing（上游提交/生成/产物下载）→ saving（结果登记）→ succeeded/failed。"""
    task_set_status(task_id, "running")
    # 进入上游调用（含素材上传与生成）：此后不允许自动重试（防重复扣费）
    task_set_status(task_id, "provider_processing", extra={"submitted_to_provider": True})
    try:
        result = await build_online_image_result(payload)
    except JimengPendingError as exc:
        # 即梦云端还在排队：标记为 jimeng_pending，前端据 submit_id 持久续查（任务未丢失）
        info = jimeng_pending_payload(exc)
        task_set_status(task_id, "jimeng_pending", extra={
            "jimeng_pending": True,
            "submit_id": exc.submit_id,
            "kind_legacy": exc.kind,
            "queue_info": exc.queue_info,
            "message": info["message"],
        })
        return
    except Exception as exc:
        detail = getattr(exc, "detail", None) or str(exc)
        status_code = getattr(exc, "status_code", 500)
        upstream_task_id = getattr(exc, "upstream_task_id", "") or extract_task_id_from_text(str(detail))
        # 自动重试仅限：网络层错误 且 未提交上游 且 次数未超限（提交标记在上游调用前已置位，
        # 因此真实生成链路几乎不触发自动重试——这正是防重复扣费策略的预期行为）
        cur = task_get(task_id) or {}
        if _is_transport_error(exc) and not cur.get("submitted_to_provider") and (cur.get("retry_count") or 0) < TASK_AUTO_RETRY_MAX:
            task_set_status(task_id, "retry", error=str(detail)[:2000], status_code=status_code)
        else:
            task_set_status(task_id, "failed", error=str(detail)[:2000], status_code=status_code,
                            extra={"upstream_task_id": upstream_task_id or ""})
            _task_credit_refund(task_id, "image_task_failed")
            await _agent_writeback_and_broadcast(task_id, "image", [], str(detail)[:300])
        return
    task_set_status(task_id, "saving")
    upstream = ""
    request_id = ""
    if isinstance(result, dict):
        raw = result.get("raw")
        upstream = str(extract_task_id(raw) or "") if isinstance(raw, dict) else str(result.get("task_id") or "")
        request_id = str(raw.get("id") or "") if isinstance(raw, dict) else str(result.get("request_id") or "")
    result = _attach_upstream_cost(result, result.get("raw") if isinstance(result, dict) else None)
    credits = _task_credit_settle(task_id, result=result)
    task_set_status(task_id, "succeeded", extra={
        "result": result,
        "provider_task_id": upstream,
        "request_id": request_id,
        "credits": credits,
    })
    # Agent 发起的生成：任务完成后把结果写回画布节点（加锁、追加不覆盖、写完广播）
    await _agent_writeback_and_broadcast(task_id, "image", _agent_result_media_urls(result))

def _agent_result_media_urls(result):
    """从任务 result 提取媒体 URL 列表（兼容 image_items/images/raw 结构）。"""
    urls = []
    if not isinstance(result, dict):
        return urls
    items = result.get("image_items") or []
    if not items:
        items = result.get("images") or []
    for it in items:
        if isinstance(it, str):
            urls.append(it)
        elif isinstance(it, dict):
            u = it.get("url") or ""
            if u:
                urls.append(u)
    if not urls:
        raw = result.get("raw")
        if isinstance(raw, dict):
            for it in (raw.get("image_items") or raw.get("images") or []):
                if isinstance(it, str):
                    urls.append(it)
                elif isinstance(it, dict) and it.get("url"):
                    urls.append(it["url"])
    return urls


def _agent_result_video_urls(result):
    """从任务 result 提取视频 URL 列表（兼容 videos/video_items/raw 结构）。"""
    urls = []
    if not isinstance(result, dict):
        return urls
    items = result.get("video_items") or []
    if not items:
        items = result.get("videos") or []
    for it in items:
        if isinstance(it, str):
            urls.append(it)
        elif isinstance(it, dict):
            u = it.get("url") or ""
            if u:
                urls.append(u)
    if not urls:
        raw = result.get("raw")
        if isinstance(raw, dict):
            for it in (raw.get("video_items") or raw.get("videos") or []):
                if isinstance(it, str):
                    urls.append(it)
                elif isinstance(it, dict) and it.get("url"):
                    urls.append(it["url"])
    return urls


class CanvasAudioRequest(BaseModel):
    provider_id: str = "comfly"
    model: str = "suno"
    prompt: str = ""
    custom: bool = False
    instrumental: bool = False
    title: str = ""
    style: str = ""
    duration: Optional[int] = None
    bpm: Optional[int] = None
    length: Optional[int] = None
    audio_format: str = ""


class CanvasTTSRequest(BaseModel):
    provider_id: str = "comfly"
    model: str = "gpt-4o-mini-tts"
    input: str = ""
    voice: str = "alloy"
    response_format: str = "wav"
    speed: float = 1.0


APIMART_SUNO_VERSION = "v6"
APIMART_MUSIC_FIRST_DELAY = 3.0
APIMART_MUSIC_POLL_INTERVAL = 5.0
APIMART_MUSIC_TIMEOUT = 900.0
APIMART_MUSIC_SUCCESS_STATUSES = {"COMPLETED", "COMPLETE", "SUCCESS", "SUCCEEDED", "SUCCEED", "DONE", "FINISHED", "OK", "READY"}
APIMART_MUSIC_FAILED_STATUSES = {"FAILED", "FAILURE", "FAIL", "ERROR", "ERRORED", "CANCELED", "CANCELLED", "TIMEOUT", "REJECTED", "EXPIRED"}
APIMART_AUDIO_EXTS = {".mp3", ".m4a", ".wav", ".aac", ".ogg", ".flac"}
APIMART_TTS_DEFAULT_MODEL = "gpt-4o-mini-tts"
APIMART_TTS_MAX_INPUT = 4096
APIMART_TTS_VOICES = ("alloy", "echo", "fable", "onyx", "nova", "shimmer")
APIMART_TTS_FORMATS = ("wav", "opus", "aac", "flac", "pcm")
APIMART_TTS_FORMAT_EXTS = {"wav": ".wav", "opus": ".opus", "aac": ".aac", "flac": ".flac", "pcm": ".pcm"}
APIMART_TTS_SPEED_MIN = 0.25
APIMART_TTS_SPEED_MAX = 4.0


def apimart_audio_submit_body(model, payload):
    """按上游音乐接口的字段口径组装提交体（suno / flowmusic / 通用兜底）。"""
    name = str(model or "").strip().lower()
    prompt = str(getattr(payload, "prompt", "") or "").strip()
    title = str(getattr(payload, "title", "") or "").strip()
    style = str(getattr(payload, "style", "") or "").strip()
    audio_format = str(getattr(payload, "audio_format", "") or "").strip()
    if "suno" in name:
        body = {"model": "suno", "version": APIMART_SUNO_VERSION, "custom": bool(getattr(payload, "custom", False))}
        if prompt:
            body["prompt"] = prompt
        if title:
            body["title"] = title
        if style:
            body["style"] = style
        if getattr(payload, "instrumental", False):
            body["instrumental"] = True
        if getattr(payload, "duration", None):
            body["duration"] = int(payload.duration)
        if audio_format:
            body["audio_format"] = audio_format
        return body
    if "flowmusic" in name:
        body = {"model": "flowmusic", "sound_prompt": prompt}
        if title:
            body["title"] = title
        if getattr(payload, "bpm", None):
            body["bpm"] = int(payload.bpm)
        if getattr(payload, "length", None):
            body["length"] = int(payload.length)
        return body
    # 未知音频模型：只发文档里最通用的 model + prompt，错误按上游原文展示
    body = {"model": model}
    if prompt:
        body["prompt"] = prompt
    if title:
        body["title"] = title
    return body


def apimart_music_url(base_url, path):
    base = str(base_url or "").strip().rstrip("/")
    return f"{base}{path}" if base.endswith("/v1") else f"{base}/v1{path}"


def apimart_music_task_url(base_url, task_id):
    quoted = urllib.parse.quote(str(task_id or "").strip(), safe="")
    return f"{apimart_music_url(base_url, '/music/tasks/' + quoted)}?language=zh"


def apimart_music_data(raw):
    if not isinstance(raw, dict):
        return {}
    data = raw.get("data")
    if isinstance(data, list):
        data = next((item for item in data if isinstance(item, dict)), {})
    if isinstance(data, dict):
        return data
    return raw


def apimart_music_task_id(raw):
    data = apimart_music_data(raw)
    return str(data.get("task_id") or data.get("id") or (raw.get("task_id") if isinstance(raw, dict) else "") or "").strip()


def apimart_music_items(raw):
    data = apimart_music_data(raw)
    result = data.get("result") if isinstance(data.get("result"), dict) else {}
    music = result.get("music")
    return [item for item in (music or []) if isinstance(item, dict)]


def apimart_music_audio_urls(raw):
    urls = []
    for item in apimart_music_items(raw):
        for key in ("audio_url", "wav_url", "url", "audioUrl"):
            value = item.get(key)
            candidates = value if isinstance(value, list) else ([value] if isinstance(value, str) else [])
            for candidate in candidates:
                text = str(candidate or "").strip()
                if text.startswith(("http://", "https://")) and text not in urls:
                    urls.append(text)
            if any(str(c or "").strip().startswith(("http://", "https://")) for c in candidates):
                break
    return urls


APIMART_MUSIC_PLACEHOLDER_TITLES = {"untitled", "untitled track", "audio"}

def apimart_music_title(raw, payload=None, fallback="Audio"):
    # 上游没给标题时会回 "Untitled"；画布节点标签是「Audio」，别把英文占位标题带出去
    for item in apimart_music_items(raw):
        title = str(item.get("title") or "").strip()
        if title and title.lower() not in APIMART_MUSIC_PLACEHOLDER_TITLES:
            return title
    title = str(getattr(payload, "title", "") or "").strip()
    return title or fallback


def apimart_music_cost(raw):
    """上游任务 data 里有 cost / credits_cost 就带出来，没有就返回空 dict（Boss 要看实际花费）。"""
    data = apimart_music_data(raw)
    cost = {}
    for key in ("cost", "credits_cost"):
        value = data.get(key)
        if value not in (None, ""):
            cost[key] = value
    return cost


def apimart_music_fail_reason(raw):
    data = apimart_music_data(raw)
    error = data.get("error") if isinstance(data.get("error"), dict) else {}
    return str(data.get("fail_reason") or data.get("message") or error.get("message")
               or (raw.get("message") if isinstance(raw, dict) else "") or "音频任务失败")


def apimart_audio_error_text(response):
    try:
        raw = response.json()
    except Exception:
        raw = None
    if isinstance(raw, dict):
        error = raw.get("error") if isinstance(raw.get("error"), dict) else {}
        message = error.get("message") or raw.get("message")
        if message:
            return str(message)[:300]
    return (getattr(response, "text", "") or "")[:300]


def apimart_tts_speed(value):
    """语速夹到官方区间 0.25–4.0；非法值回落 1.0。"""
    try:
        speed = float(value)
    except (TypeError, ValueError):
        return 1.0
    if not math.isfinite(speed):
        return 1.0
    return max(APIMART_TTS_SPEED_MIN, min(APIMART_TTS_SPEED_MAX, round(speed, 2)))


def apimart_tts_input(payload):
    text = str(getattr(payload, "input", "") or "").strip()
    if not text:
        raise HTTPException(status_code=400, detail="要朗读的文本不能为空。")
    if len(text) > APIMART_TTS_MAX_INPUT:
        raise HTTPException(status_code=400, detail=f"文本太长：最多 {APIMART_TTS_MAX_INPUT} 字，当前 {len(text)} 字。")
    return text


def apimart_tts_voice(value):
    voice = str(value or "").strip().lower() or "alloy"
    if voice not in APIMART_TTS_VOICES:
        raise HTTPException(status_code=400, detail=f"不支持的音色：{voice}。可选：{'、'.join(APIMART_TTS_VOICES)}")
    return voice


def apimart_tts_format(value):
    fmt = str(value or "").strip().lower() or "wav"
    if fmt not in APIMART_TTS_FORMATS:
        raise HTTPException(status_code=400, detail=f"不支持的音频格式：{fmt}。可选：{'、'.join(APIMART_TTS_FORMATS)}")
    return fmt


def apimart_tts_submit_body(payload):
    """按 APIMart /v1/audio/speech 官方字段组装提交体。"""
    text = apimart_tts_input(payload)
    voice = apimart_tts_voice(getattr(payload, "voice", ""))
    fmt = apimart_tts_format(getattr(payload, "response_format", ""))
    model = str(getattr(payload, "model", "") or "").strip() or APIMART_TTS_DEFAULT_MODEL
    speed = apimart_tts_speed(getattr(payload, "speed", 1.0))
    return {"model": model, "input": text, "voice": voice, "response_format": fmt, "speed": speed}


def apimart_tts_extension(fmt, content_type=""):
    """落盘扩展名：先认上游 Content-Type，认不出再按请求的 response_format。"""
    type_text = str(content_type or "").lower()
    if "mpeg" in type_text or "mp3" in type_text:
        return ".mp3"
    if "wav" in type_text or "wave" in type_text:
        return ".wav"
    if "opus" in type_text:
        return ".opus"
    if "aac" in type_text or "m4a" in type_text or "mp4" in type_text:
        return ".aac"
    if "flac" in type_text:
        return ".flac"
    if "ogg" in type_text:
        return ".ogg"
    if "pcm" in type_text or "l16" in type_text:
        return ".pcm"
    return APIMART_TTS_FORMAT_EXTS.get(fmt, ".wav")


def apimart_tts_title(text, fallback="语音"):
    first = " ".join(str(text or "").split())
    if not first:
        return fallback
    return first[:20] + ("…" if len(first) > 20 else "")


def normalize_streaming_wav_bytes(content):
    """把流式 WAV 的未知长度（0xFFFFFFFF / 0）改写为真实长度。

    APIMart TTS 返回的 WAV 头里 RIFF/data 两个 size 都是 0xFFFFFFFF：浏览器能播，
    但 wave 等解析器会把时长算成几万秒。只修这一种情况，合法 WAV 原样返回（幂等）。
    """
    data = bytes(content or b"")
    if len(data) < 12 or data[0:4] != b"RIFF" or data[8:12] != b"WAVE":
        return data
    total = len(data)
    riff_size = int.from_bytes(data[4:8], "little")
    data_offset = -1
    pos = 12
    while pos + 8 <= total:
        chunk_id = data[pos:pos + 4]
        chunk_size = int.from_bytes(data[pos + 4:pos + 8], "little")
        if chunk_id == b"data":
            data_offset = pos
            break
        next_pos = pos + 8 + chunk_size + (chunk_size & 1)
        if chunk_size in (0, 0xFFFFFFFF) or next_pos <= pos:
            break
        pos = next_pos
    if data_offset < 0 and total >= 44 and data[36:40] == b"data":
        data_offset = 36
    if data_offset < 0:
        return data
    data_size = int.from_bytes(data[data_offset + 4:data_offset + 8], "little")
    patch_riff = riff_size in (0, 0xFFFFFFFF)
    patch_data = data_size in (0, 0xFFFFFFFF)
    if not patch_riff and not patch_data:
        return data
    out = bytearray(data)
    if patch_riff:
        out[4:8] = max(0, total - 8).to_bytes(4, "little")
    if patch_data:
        out[data_offset + 4:data_offset + 8] = max(0, total - data_offset - 8).to_bytes(4, "little")
    return bytes(out)


def save_tts_audio_to_output(content, ext=".wav", prefix="tts_"):
    """把二进制语音写进输出目录，返回本地 /assets/output/ 地址。"""
    if str(ext or "").lower() == ".wav":
        content = normalize_streaming_wav_bytes(content)
    filename = f"{prefix}{uuid.uuid4().hex[:10]}{ext}"
    path = output_path_for(filename)
    with open(path, "wb") as f:
        f.write(content)
    if os.path.getsize(path) <= 0:
        raise HTTPException(status_code=502, detail="语音接口返回了空音频。")
    return output_url_for(filename)


async def apimart_wait_music_task(client, provider, base_url, task_id):
    url = apimart_music_task_url(base_url, task_id)
    deadline = time.monotonic() + APIMART_MUSIC_TIMEOUT
    delay = APIMART_MUSIC_FIRST_DELAY
    last_payload = {}
    while time.monotonic() < deadline:
        await asyncio.sleep(min(delay, max(0.0, deadline - time.monotonic())))
        delay = APIMART_MUSIC_POLL_INTERVAL
        response = await client.get(url, headers=api_headers(provider=provider))
        if response.status_code >= 400:
            raise HTTPException(status_code=response.status_code, detail=f"查询音频任务失败：{apimart_audio_error_text(response)}")
        try:
            raw = response.json()
        except ValueError:
            raw = {"message": response.text[:300]}
        last_payload = raw
        data = apimart_music_data(raw)
        status = str(data.get("status") or "").upper()
        if status in APIMART_MUSIC_SUCCESS_STATUSES:
            return raw
        if status in APIMART_MUSIC_FAILED_STATUSES:
            raise HTTPException(status_code=502, detail=f"音频任务失败：{apimart_music_fail_reason(raw)}")
        if apimart_music_audio_urls(raw) and status not in APIMART_MUSIC_FAILED_STATUSES:
            return raw
    raise HTTPException(status_code=504, detail=f"音频任务超时（已等待 {int(APIMART_MUSIC_TIMEOUT)} 秒），task_id={task_id}")


def audio_extension_for_url(url):
    ext = os.path.splitext(urllib.parse.urlparse(str(url or "")).path)[1].lower()
    return ext if ext in APIMART_AUDIO_EXTS else ""


async def save_remote_audio_to_output(url, prefix="audio_"):
    """下载上游音频到输出目录，返回本地 /assets/output/ 地址；失败抛 HTTPException。"""
    value = str(url or "").strip()
    if value.startswith(("/output/", "/assets/")):
        return value
    ext = audio_extension_for_url(value) or ".mp3"
    filename = f"{prefix}{uuid.uuid4().hex[:10]}{ext}"
    path = output_path_for(filename)
    try:
        timeout = httpx.Timeout(connect=20.0, read=300.0, write=60.0, pool=20.0)
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=timeout, follow_redirects=True) as client:
            response = await client.get(value)
            response.raise_for_status()
            content_type = (response.headers.get("Content-Type") or "").lower()
            if "mpeg" in content_type or "mp3" in content_type:
                ext = ".mp3"
            elif "mp4" in content_type or "m4a" in content_type or "aac" in content_type:
                ext = ".m4a"
            elif "wav" in content_type or "x-wav" in content_type:
                ext = ".wav"
            elif "ogg" in content_type:
                ext = ".ogg"
            if ext != os.path.splitext(filename)[1].lower():
                filename = f"{prefix}{uuid.uuid4().hex[:10]}{ext}"
                path = output_path_for(filename)
            with open(path, "wb") as f:
                f.write(response.content)
            if os.path.getsize(path) <= 0:
                raise RuntimeError("empty audio response")
            return output_url_for(filename)
    except Exception as exc:
        print(f"保存上游音频失败: {exc}; url={value}")
        raise HTTPException(status_code=502, detail=f"保存音频失败：{exc}") from exc


async def generate_canvas_audio(payload: CanvasAudioRequest):
    provider = get_api_provider(payload.provider_id)
    if not is_apimart_provider(provider):
        raise HTTPException(status_code=400, detail="音频节点目前只支持 APIMart 协议的平台，请在 API 设置里把平台协议改成 APIMart。")
    base_url = str(provider.get("base_url") or "").strip().rstrip("/")
    if not base_url:
        raise HTTPException(status_code=400, detail=f"{provider.get('name') or provider['id']} 未配置 Base URL")
    model = str(payload.model or "").strip() or "suno"
    body = apimart_audio_submit_body(model, payload)
    submit_url = apimart_music_url(base_url, "/music/generations")
    timeout = httpx.Timeout(connect=20.0, read=180.0, write=60.0, pool=20.0)
    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env(provider), timeout=timeout, follow_redirects=True) as client:
            response = await client.post(submit_url, headers=api_headers(provider=provider), json=body)
            if response.status_code >= 400:
                raise HTTPException(status_code=response.status_code, detail=f"音频提交失败：{apimart_audio_error_text(response)}")
            try:
                raw = response.json()
            except ValueError as exc:
                raise HTTPException(status_code=502, detail=f"音频接口返回了非 JSON 内容：{response.text[:300]}") from exc
            task_id = apimart_music_task_id(raw)
            if not task_id:
                preview = json.dumps(raw, ensure_ascii=False)[:300] if isinstance(raw, (dict, list)) else str(raw)[:300]
                raise HTTPException(status_code=502, detail=f"音频接口没有返回任务 ID：{preview}")
            result = await apimart_wait_music_task(client, provider, base_url, task_id)
    except httpx.HTTPStatusError as exc:
        raise HTTPException(status_code=exc.response.status_code, detail=f"音频接口错误：{apimart_audio_error_text(exc.response)}") from exc
    except httpx.HTTPError as exc:
        raise HTTPException(status_code=502, detail=f"请求音频接口失败：{type(exc).__name__}: {exc}") from exc
    urls = apimart_music_audio_urls(result)
    if not urls:
        preview = json.dumps(result, ensure_ascii=False)[:300] if isinstance(result, (dict, list)) else str(result)[:300]
        raise HTTPException(status_code=502, detail=f"音频任务完成但没有返回音频地址：{preview}")
    audios = [await save_remote_audio_to_output(url) for url in urls[:4]]
    title = apimart_music_title(result, payload)
    cost = apimart_music_cost(result)
    first = audios[0]
    response = {
        "audios": audios,
        "task_id": task_id,
        "model": model,
        "canvas_meta": {"node_type": "audio", "title": title, "media_url": first, "auto_place": True},
    }
    response.update(cost)
    return response


@app.post("/api/canvas-audio")
async def canvas_audio(payload: CanvasAudioRequest):
    payload.provider_id = member_provider(payload.provider_id)
    model = str(payload.model or "").strip() or "suno"
    charge = credits_charge_start("audio", model, _credits_audio_params(payload),
                                 provider=payload.provider_id)
    try:
        result = await generate_canvas_audio(payload)
    except Exception:
        credits_charge_refund(charge, "audio_failed")
        raise
    credits = credits_charge_settle(charge, result=result)
    return credits_attach(result, credits)

def apimart_tts_duration_seconds(content, fmt=""):
    """WAV 直接从文件头读时长；其它格式返回 None（后付费估算会用字符数兜底并标 estimated）。"""
    try:
        if str(fmt or "").lower() == "wav" or (content or b"")[:4] == b"RIFF":
            import wave
            with wave.open(io.BytesIO(content), "rb") as handle:
                frames = handle.getnframes()
                rate = handle.getframerate()
                if rate:
                    # APIMart 流式 WAV 的 data size 可能是 0x7FFFFFFF（边生成边下发）：
                    # 用真实字节数兜底，避免算出 89478 秒这种离谱时长。
                    frame_size = max(1, int(handle.getnchannels()) * int(handle.getsampwidth()))
                    max_frames = max(0, len(content) - 44) // frame_size
                    if max_frames and (frames <= 0 or frames > max_frames * 1.01):
                        frames = max_frames
                    return round(float(frames) / float(rate), 3)
    except Exception:
        return None
    return None


async def generate_canvas_tts(payload: CanvasTTSRequest):
    provider = get_api_provider(payload.provider_id)
    if not is_apimart_provider(provider):
        raise HTTPException(status_code=400, detail="语音合成只支持 APIMart 协议的平台，请在 API 设置里把平台协议改成 APIMart。")
    base_url = str(provider.get("base_url") or "").strip().rstrip("/")
    if not base_url:
        raise HTTPException(status_code=400, detail=f"{provider.get('name') or provider['id']} 未配置 Base URL")
    body = apimart_tts_submit_body(payload)
    url = apimart_music_url(base_url, "/audio/speech")
    timeout = httpx.Timeout(connect=20.0, read=300.0, write=60.0, pool=20.0)
    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env(provider), timeout=timeout, follow_redirects=True) as client:
            upstream = await client.post(url, headers=api_headers(provider=provider), json=body)
            if upstream.status_code >= 400:
                raise HTTPException(status_code=upstream.status_code, detail=f"语音合成失败：{apimart_audio_error_text(upstream)}")
            content_type = str(upstream.headers.get("Content-Type") or "")
            content = upstream.content or b""
    except httpx.TimeoutException as exc:
        raise HTTPException(status_code=504, detail=f"语音合成超时（上游 {int(timeout.read)} 秒内没有返回音频），请缩短文本后重试。") from exc
    except httpx.HTTPError as exc:
        raise HTTPException(status_code=502, detail=f"请求语音接口失败：{type(exc).__name__}: {exc}") from exc
    if not content:
        raise HTTPException(status_code=502, detail="语音接口返回了空内容。")
    if "json" in content_type.lower() or "text/" in content_type.lower():
        preview = content[:300].decode("utf-8", "replace")
        raise HTTPException(status_code=502, detail=f"语音接口没有返回音频：{preview}")
    fmt = body["response_format"]
    ext = apimart_tts_extension(fmt, content_type)
    try:
        local_url = save_tts_audio_to_output(content, ext=ext)
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"保存语音失败：{exc}") from exc
    result = {
        "audios": [local_url],
        "model": body["model"],
        "voice": body["voice"],
        "response_format": fmt,
        "speed": body["speed"],
        "characters": len(body["input"]),
        "audio_bytes": len(content),
        "usage": {
            "characters": len(body["input"]),
            "bytes": len(content),
            "seconds": apimart_tts_duration_seconds(content, fmt),
        },
        "canvas_meta": {"node_type": "audio", "title": apimart_tts_title(body["input"]), "media_url": local_url, "auto_place": True},
    }
    if fmt == "pcm":
        result["notice"] = "PCM 是裸音频流，浏览器不能直接播放；需要可播放文件请改用 wav / opus / aac / flac。"
    return result


@app.post("/api/canvas-tts")
async def canvas_tts(payload: CanvasTTSRequest):
    payload.provider_id = member_provider(payload.provider_id)
    model = str(payload.model or "").strip() or APIMART_TTS_DEFAULT_MODEL
    params = {"rows": 1, "text": str(payload.input or ""), "characters": len(str(payload.input or ""))}
    charge = credits_charge_start("audio", model, params, provider=payload.provider_id)
    try:
        result = await generate_canvas_tts(payload)
    except Exception:
        credits_charge_refund(charge, "tts_failed")
        raise
    credits = credits_charge_settle(charge, result=result)
    return credits_attach(result, credits)

# ── 音频智能切分：自然语言 / 语义 → 时间段 ────────────────────────────────────
# 前端拿到时间段只做「预览 + 确认」，真正的切片在浏览器本地完成；这里只负责让模型把
# 自然语言变成 [start, end] 列表，并把模型输出清洗成一定能落地的区间。
AUDIO_SPLIT_MIN_SEC = 0.5
AUDIO_SPLIT_MAX_SEGMENTS = 12
AUDIO_SPLIT_MODES = ("smart", "custom")
AUDIO_SPLIT_READ_TIMEOUT = 120.0
# 切分只要模型吐一小段 JSON：优先便宜快的小模型（字符串精确匹配，不做模糊）。
# 顺序即优先级；都不在该平台的 chat_models 里，才退回平台第一个对话模型。
AUDIO_SPLIT_PREFERRED_MODELS = (
    "gemini-3.1-flash-lite-preview",
    "gpt-4o-mini",
    "gemini-3.5-flash-lite",
    "deepseek-v4.1-flash",
)


class CanvasAudioSplitRequest(BaseModel):
    provider_id: str = ""
    model: str = ""
    text: str = ""
    duration_sec: float = 0.0
    max_segments: int = AUDIO_SPLIT_MAX_SEGMENTS
    mode: str = "smart"


def audio_split_duration(value):
    """总时长（秒）：必须是有限正数，否则 400。前端只会拿解码后的真实时长来问。"""
    try:
        duration = float(value)
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="音频时长不合法：需要大于 0 的秒数。") from None
    if not math.isfinite(duration) or duration <= 0:
        raise HTTPException(status_code=400, detail="音频时长不合法：需要大于 0 的秒数。")
    if duration > 24 * 3600:
        raise HTTPException(status_code=400, detail="音频时长超出可处理范围（最长 24 小时）。")
    return duration


def audio_split_max_segments(value):
    try:
        count = int(value)
    except (TypeError, ValueError):
        return AUDIO_SPLIT_MAX_SEGMENTS
    return max(1, min(AUDIO_SPLIT_MAX_SEGMENTS, count))


def audio_split_mode(value):
    mode = str(value or "").strip().lower()
    return mode if mode in AUDIO_SPLIT_MODES else "smart"


def audio_split_chat_models(provider):
    return [str(item or "").strip() for item in ((provider or {}).get("chat_models") or []) if str(item or "").strip()]


def audio_split_preferred_model(provider):
    """按偏好顺序挑一个便宜的对话模型；都不在列表里就返回空串（由调用方退回第一个）。"""
    models = audio_split_chat_models(provider)
    return next((name for name in AUDIO_SPLIT_PREFERRED_MODELS if name in models), "")


def audio_split_resolve_provider(providers, provider_id="", model=""):
    """挑平台和模型（纯函数，便于单测）：

    - 请求里给了 provider_id 就用它，必须存在且 enabled，否则 400；
    - 没给就优先挑 chat_models 非空的，apimart 更优先（它就是本项目的音频/文本默认通道）；
    - model 没给就先按 AUDIO_SPLIT_PREFERRED_MODELS 的偏好顺序找便宜快的小模型，
      一个都不在列表里才退回该平台第一个对话模型（preferred_chat_model 里还有平台差异规则）。
    """
    items = [p for p in (providers or []) if isinstance(p, dict) and str(p.get("id") or "").strip()]
    requested = str(provider_id or "").strip().lower()
    if requested:
        provider = next((p for p in items if str(p.get("id") or "").strip().lower() == requested), None)
        if provider is None:
            raise HTTPException(status_code=400, detail=f"未找到 API 平台：{requested}。请先在「设置 → API 设置」里添加并保存。")
        if not provider.get("enabled", True):
            raise HTTPException(status_code=400, detail=f"API 平台已禁用：{provider.get('name') or requested}")
    else:
        enabled = [p for p in items if p.get("enabled", True)]
        with_chat = [p for p in enabled if audio_split_chat_models(p)]
        apimart_first = [p for p in with_chat if is_apimart_provider(p)]
        provider = next(iter(apimart_first or with_chat or enabled), None)
        if provider is None:
            raise HTTPException(status_code=400, detail="没有可用的 API 平台：请先在「设置 → API 设置」里配置平台和对话模型。")
    chosen = str(model or "").strip()
    if not chosen:
        if not audio_split_chat_models(provider):
            raise HTTPException(
                status_code=400,
                detail="平台「%s」没有配置对话模型（chat_models），无法用模型切分音频。"
                       % (provider.get("name") or provider.get("id") or "未命名"),
            )
        chosen = audio_split_preferred_model(provider) or preferred_chat_model(provider)
    return provider, chosen


def audio_split_system_prompt(mode, duration, max_segments, text=""):
    """硬约束系统提示词：只让模型吐 JSON，把边界/最短/排序/不重叠/段数全部写死。"""
    total = float(duration)
    lines = [
        "你是音频切分助手。只输出一个 JSON 对象，不要解释，不要 Markdown 代码块。",
        '输出格式：{"segments":[{"start":0.0,"end":3.2}],"note":"一句话说明"}',
        f"这段音频总时长 {total:.2f} 秒。",
        "硬约束（违反任何一条结果都不可用）：",
        f"1. start / end 的单位是秒，必须满足 0 <= start < end <= {total:.2f}；",
        f"2. 每段时长必须 >= {AUDIO_SPLIT_MIN_SEC} 秒；",
        f"3. 最少 1 段、最多 {max_segments} 段；",
        "4. 按 start 从小到大排列，段与段之间不能重叠；",
        "5. 只输出 JSON，不能有任何额外文字。",
    ]
    instruction = " ".join(str(text or "").split())
    if audio_split_mode(mode) == "custom":
        lines.append("用户指令（必须完整覆盖它要求的操作，例如删除/保留某段、在第几秒处切开）：")
        lines.append(instruction or "按自然语义把音频切开。")
    else:
        lines.append("切分要求：按语义和对话停顿自然切分，每段是一句话或一个完整语义单元；句间停顿处优先作为切点。")
    return "\n".join(lines)


def audio_split_user_text(mode, duration, max_segments, text=""):
    total = float(duration)
    instruction = " ".join(str(text or "").split())
    if audio_split_mode(mode) == "custom" and instruction:
        return f"音频总时长 {total:.2f} 秒，最多 {max_segments} 段。用户指令：{instruction}"
    return f"音频总时长 {total:.2f} 秒，最多 {max_segments} 段，请按语义/对话停顿自然切分。"


def audio_split_chat_body(model, system_prompt, user_text):
    """OpenAI 兼容 chat 提交体。

    必须带 stream=false：APIMart 默认按 SSE 流式返回，不显式关掉拿到的是
    「data: {...}」文本块，response.json() 直接解析失败。
    """
    return {
        "model": model,
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_text},
        ],
        "stream": False,
    }


# 各平台 base_url 的版本段写法差很多：APIMart 没有版本段（https://api.apimart.ai），
# Volcengine 是 /api/v3，Agnes / ModelScope 是 /v1，还有 /v1beta、/openai/v1、/v4 这些。
# 以前统一套 apimart_music_url（只认 /v1）会把 /api/v3 拼成 /api/v3/v1/chat/completions → 上游 404。
AUDIO_SPLIT_VERSION_SUFFIX_RE = re.compile(r"/(?:api|openai)/v[0-9]+(?:beta)?$|/v[0-9]+(?:beta)?$", re.I)


def audio_split_chat_url(base_url):
    """平台 base_url → chat/completions 完整地址。

    - 已经带完整 /chat/completions：原样返回；
    - base 以版本段结尾（/v1、/v1beta、/v3、/v4、/api/v1、/api/v3、/openai/v1 …）：直接拼 /chat/completions；
    - 其它（APIMart 这类没有版本段的）：拼 /v1/chat/completions。
    """
    base = str(base_url or "").strip().rstrip("/")
    if not base:
        return ""
    if base.lower().endswith("/chat/completions"):
        return base
    if AUDIO_SPLIT_VERSION_SUFFIX_RE.search(base):
        return base + "/chat/completions"
    return base + "/v1/chat/completions"


def audio_split_extract_json(text):
    """从模型回复里掏 JSON：去掉 ``` 代码块，再取第一个 { 到最后一个 }。"""
    raw = str(text or "").strip()
    if not raw:
        return None
    if "```" in raw:
        raw = re.sub(r"```[A-Za-z0-9_-]*", "", raw).replace("```", "")
    start = raw.find("{")
    end = raw.rfind("}")
    if start < 0 or end <= start:
        return None
    try:
        return json.loads(raw[start:end + 1])
    except (TypeError, ValueError):
        return None


def audio_split_clean_segments(entries, duration, max_segments=AUDIO_SPLIT_MAX_SEGMENTS):
    """把模型给的时间段洗成能直接切片的区间：

    夹到 [0, duration] → 丢弃 < 0.5s → 按 start 升序 → 重叠合并 → 最多 max_segments 段。
    返回 [{"start":float,"end":float}]（三位小数，避免下游出现 3.0000000000000004）。
    """
    total = max(0.0, float(duration))
    limit = audio_split_max_segments(max_segments)
    min_span = AUDIO_SPLIT_MIN_SEC
    cleaned = []
    for entry in (entries or []):
        if not isinstance(entry, dict):
            continue
        try:
            start = float(entry.get("start"))
            end = float(entry.get("end"))
        except (TypeError, ValueError):
            continue
        if not math.isfinite(start) or not math.isfinite(end):
            continue
        if end < start:
            start, end = end, start
        start = min(total, max(0.0, start))
        end = min(total, max(0.0, end))
        if end - start < min_span - 1e-9:
            continue
        cleaned.append([start, end])
    cleaned.sort(key=lambda item: (item[0], item[1]))
    merged = []
    for start, end in cleaned:
        if merged and start < merged[-1][1] - 1e-9:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    merged = [item for item in merged if item[1] - item[0] >= min_span - 1e-9]
    return [{"start": round(item[0], 3), "end": round(item[1], 3)} for item in merged[:limit]]


def audio_split_parse_segments(content, duration, max_segments=AUDIO_SPLIT_MAX_SEGMENTS):
    """模型回复 → 清洗后的时间段；结构不对 / 清洗后为空都抛 502（前端会退本地兜底）。"""
    raw = audio_split_extract_json(content)
    if not isinstance(raw, dict) or not isinstance(raw.get("segments"), list):
        preview = str(content or "").strip()[:120]
        raise HTTPException(status_code=502, detail=f"模型没有返回可解析的切分结果：{preview or '空内容'}")
    segments = audio_split_clean_segments(raw.get("segments"), duration, max_segments)
    if not segments:
        raise HTTPException(status_code=502, detail="模型返回的时间段都不可用（越界或短于 0.5 秒），请重试或改用本地切分。")
    note = str(raw.get("note") or "").strip()[:200]
    return segments, note


async def generate_canvas_audio_split(payload: CanvasAudioSplitRequest):
    duration = audio_split_duration(payload.duration_sec)
    limit = audio_split_max_segments(payload.max_segments)
    mode = audio_split_mode(payload.mode)
    provider, model = audio_split_resolve_provider(load_api_providers(), payload.provider_id, payload.model)
    url = audio_split_chat_url(provider.get("base_url") or "")
    if not url:
        raise HTTPException(status_code=400, detail=f"{provider.get('name') or provider['id']} 未配置 Base URL")
    body = audio_split_chat_body(
        model,
        audio_split_system_prompt(mode, duration, limit, getattr(payload, "text", "")),
        audio_split_user_text(mode, duration, limit, getattr(payload, "text", "")),
    )
    timeout = httpx.Timeout(connect=20.0, read=AUDIO_SPLIT_READ_TIMEOUT, write=60.0, pool=20.0)
    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env(provider), timeout=timeout, follow_redirects=True) as client:
            upstream = await client.post(url, headers=api_headers(provider=provider, model=model), json=body)
            if upstream.status_code >= 400:
                raise HTTPException(
                    status_code=502,
                    detail=f"智能切分失败：上游返回 {upstream.status_code} {apimart_audio_error_text(upstream)}",
                )
            try:
                raw = upstream.json()
            except ValueError as exc:
                raise HTTPException(status_code=502, detail=f"智能切分失败：上游返回了非 JSON 内容：{(upstream.text or '')[:200]}") from exc
    except HTTPException:
        raise
    except httpx.TimeoutException as exc:
        raise HTTPException(
            status_code=504,
            detail=f"智能切分超时（上游 {int(AUDIO_SPLIT_READ_TIMEOUT)} 秒内没有返回），可以重试或改用本地切分。",
        ) from exc
    except httpx.HTTPError as exc:
        raise HTTPException(status_code=502, detail=f"请求智能切分接口失败：{type(exc).__name__}: {exc}") from exc
    content = text_from_chat_response(raw) if isinstance(raw, dict) else ""
    if not str(content or "").strip():
        raise HTTPException(status_code=502, detail="智能切分失败：模型返回了空内容。")
    segments, note = audio_split_parse_segments(content, duration, limit)
    data = unwrap_apimart_response(raw) if isinstance(raw, dict) else {}
    usage = data.get("usage") if isinstance(data.get("usage"), dict) else {}
    return {
        "segments": segments,
        "note": note,
        "source": "llm",
        "provider": str(provider.get("id") or ""),
        "model": model,
        "usage": usage,
    }


@app.post("/api/canvas-audio-split")
async def canvas_audio_split(payload: CanvasAudioSplitRequest):
    payload.provider_id = member_provider(payload.provider_id)
    # 切分本质是一次文本 LLM 调用：按对话模型 token 价计费（上游 usage 返回时按实际 token 结算）
    try:
        _provider, split_model = audio_split_resolve_provider(load_api_providers(), payload.provider_id, payload.model)
    except HTTPException:
        split_model = str(payload.model or "")
    split_params = {"text": str(payload.text or ""), "duration": float(payload.duration_sec or 0),
                    "tokens_out": 300}
    charge = credits_charge_start("text", split_model, split_params,
                                 provider=payload.provider_id)
    try:
        result = await generate_canvas_audio_split(payload)
    except Exception:
        credits_charge_refund(charge, "audio_split_failed")
        raise
    credits = credits_charge_settle(charge, result=result)
    return credits_attach(result, credits)


