# 真机 /v1/models 里该模型的 id 是文档目录名 Omni-Flash-Ext（不是文档示例的 gemini-omni-1.1-flash-ext），
# 两个 id 都指向同一套文档参数
APIMART_VIDEO_MODEL_CAPS["omni-flash-ext"] = APIMART_VIDEO_MODEL_CAPS["gemini-omni-1-1-flash-ext"]

APIMART_VIDEO_RESOLUTION_RANK = {
    "360p": 360, "480p": 480, "512p": 512, "540p": 540, "720p": 720, "768p": 768,
    "1080p": 1080, "1440p": 1440, "2k": 1440, "2048p": 2048, "4k": 2160, "2160p": 2160,
    "hd": 720, "fhd": 1080,
}

def apimart_video_normalized_name(model):
    return re.sub(r"[^a-z0-9]+", "-", str(model or "").strip().lower()).strip("-")

def apimart_video_model_caps(model):
    name = apimart_video_normalized_name(model)
    if not name:
        return None
    for key in sorted(APIMART_VIDEO_MODEL_CAPS, key=len, reverse=True):
        if key in name:
            return APIMART_VIDEO_MODEL_CAPS[key]
    return None

def apimart_video_closest_resolution(value, levels):
    target = APIMART_VIDEO_RESOLUTION_RANK.get(str(value or "").strip().lower())
    if target is None:
        return str(levels[0])
    return min(levels, key=lambda item: (abs(APIMART_VIDEO_RESOLUTION_RANK.get(str(item).strip().lower(), 0) - target),
                                         APIMART_VIDEO_RESOLUTION_RANK.get(str(item).strip().lower(), 0)))

def apimart_video_duration_value(model, duration, caps=None):
    caps = caps if caps is not None else apimart_video_model_caps(model)
    if caps is None:
        return apimart_video_duration(duration, model)
    if not caps.get("durations"):
        if "durations" in caps:
            return None
        low, high = caps.get("duration") or (4, 15)
        try:
            value = int(duration)
        except Exception:
            value = 5
        return max(low, min(high, value))
    try:
        value = int(duration)
    except Exception:
        value = 5
    return min(caps["durations"], key=lambda item: abs(int(item) - value))

APIMART_VIDEO_DURATION_ERROR_RE = re.compile(
    r"duration\s+must\s+be\s+an\s+integer\s+between\s+(\d+)\s+and\s+(\d+)\s+seconds",
    re.IGNORECASE,
)

def apimart_video_duration_error_bounds(text):
    """上游 400 会自报 duration 合法区间（MiniMax-H3-Max 实测 5-15，本地能力表曾写成 4）。"""
    matched = APIMART_VIDEO_DURATION_ERROR_RE.search(str(text or ""))
    if not matched:
        return None
    low, high = int(matched.group(1)), int(matched.group(2))
    return (low, high) if low <= high else None

def apimart_video_duration_clamp(value, low, high):
    try:
        number = int(value)
    except Exception:
        number = int(low)
    return max(low, min(high, number))

def apimart_video_duration_retry_body(body, text):
    """按上游区间改写 body 的 duration 后返回 True；调用方原样重试一次即可（图片已上传好）。"""
    bounds = apimart_video_duration_error_bounds(text)
    if not bounds or not isinstance(body, dict) or "duration" not in body:
        return False
    low, high = bounds
    before = body.get("duration")
    after = apimart_video_duration_clamp(before, low, high)
    if after == before:
        return False
    body["duration"] = after
    print(f"[apimart-video] duration {before} 被上游拒绝，按上游区间 {low}-{high} 自动改为 {after} 重试", flush=True)
    return True

def apimart_video_resolution_value(model, resolution, caps):
    key = caps.get("resolution_key")
    levels = caps.get("resolutions") or ()
    if not key or not levels:
        return None
    if key == "mode":
        mode = apimart_kling_video_params(model, resolution).get("mode", "std")
        if mode in levels:
            return mode
        order = {"std": 0, "pro": 1, "4k": 2}
        target = order.get(mode, 0)
        return min(levels, key=lambda item: abs(order.get(item, 0) - target))
    value = str(resolution or "").strip()
    aliases = caps.get("resolution_aliases") or {}
    mapped = aliases.get(value.lower(), aliases.get(value, value))
    lowered = {str(item).strip().lower(): item for item in levels}
    if str(mapped).strip().lower() in lowered:
        return lowered[str(mapped).strip().lower()]
    if not value or value.lower() == "auto":
        for preferred in ("720p", "768p", "hd", "720P", "768P"):
            if preferred.lower() in lowered:
                return lowered[preferred.lower()]
        return str(levels[0])
    return apimart_video_closest_resolution(value, levels)

def apimart_video_ratio_value(ratio, caps):
    key = caps.get("ratio_key")
    levels = caps.get("ratios") or ()
    if not key:
        return None, None
    if not levels:
        return key, ratio
    value = str(ratio or "").strip().lower()
    if value == "keep_ratio":
        return key, ("adaptive" if "adaptive" in levels else apimart_clamp_ratio("1:1", levels))
    if value in [str(item).strip().lower() for item in levels]:
        return key, value
    return key, apimart_clamp_ratio(value or "16:9", levels)

def apimart_video_watermark_allowed(model="", resolution=""):
    """MiniMax-H3-Max 在 1080P 下不能带 watermark/aigc_watermark（连 false 都不行）。"""
    name = apimart_video_normalized_name(model)
    level = str(resolution or "").strip().lower()
    if "minimax-h3-max" in name and level == "1080p":
        return False
    return True


def apimart_video_body_params(model, duration, ratio, resolution):
    """按官方文档把画布入参收敛成该模型认的字段；文档未收录的模型保持旧的 size + resolution 口径。"""
    caps = apimart_video_model_caps(model)
    if caps is None:
        return {
            "duration": apimart_video_duration(duration, model),
            "ratio_key": "size",
            "ratio_value": apimart_video_size(ratio),
            "resolution_key": "resolution",
            "resolution_value": apimart_video_resolution(resolution),
        }
    ratio_key, ratio_value = apimart_video_ratio_value(ratio, caps)
    return {
        "duration": apimart_video_duration_value(model, duration, caps),
        "ratio_key": ratio_key,
        "ratio_value": ratio_value,
        "resolution_key": caps.get("resolution_key"),
        "resolution_value": apimart_video_resolution_value(model, resolution, caps),
    }

def apimart_kling_video_params(model: str, resolution) -> dict:
    """APIMart Kling 分辨率字段取官方口径：v3 / o1 用 mode(std/pro/4k)，
    3.0-turbo 仍用 resolution(720p/1080p)；入参沿用旧画布 resolution 字段（兼容读取）。"""
    name = str(model or "").strip().lower().replace("_", "-").replace(".", "-")
    value = str(resolution or "").strip().lower()
    if value == "780p":
        value = "720p"
    if "turbo" in name:
        return {"resolution": "1080p" if value in {"1080p", "4k"} else "720p"}
    mode = {"": "std", "auto": "std", "480p": "std", "720p": "std", "1080p": "pro", "4k": "4k"}.get(value, "std")
    return {"mode": mode}

def agnes_video_dimensions(aspect_ratio="", resolution=""):
    ratio = str(aspect_ratio or "16:9").strip()
    width, height = {
        "16:9": (1152, 648),
        "9:16": (648, 1152),
        "4:3": (1024, 768),
        "3:4": (768, 1024),
        "1:1": (768, 768),
        "21:9": (1280, 544),
        "9:21": (544, 1280),
    }.get(ratio, (1152, 768))
    scale = {"480p": 0.625, "720p": 1.0, "780p": 1.0, "1080p": 1.5}.get(str(resolution or "").strip().lower(), 1.0)
    width = max(64, int(round(width * scale / 8) * 8))
    height = max(64, int(round(height * scale / 8) * 8))
    return width, height

def agnes_video_frame_count(duration, fps=24):
    try:
        seconds = max(1, min(18, int(duration or 5)))
    except Exception:
        seconds = 5
    try:
        frame_rate = max(1, min(60, int(fps or 24)))
    except Exception:
        frame_rate = 24
    target = min(441, max(9, seconds * frame_rate))
    n = max(1, round((target - 1) / 8))
    return min(441, max(9, 8 * n + 1)), frame_rate

async def agnes_video_image_url(ref):
    url = str(getattr(ref, "url", "") or "").strip()
    if not url:
        return ""
    if url.startswith("http://") or url.startswith("https://"):
        return url
    uploaded = await upload_local_video_to_cloud(url, "auto")
    return uploaded.get("url") or ""

async def wait_for_agnes_video_task(client, provider, video_id, model):
    base_url = video_api_root(provider)
    if not base_url:
        raise HTTPException(status_code=400, detail=f"{provider.get('name') or provider['id']} 未配置 Base URL")
    query_url = f"{base_url}/agnesapi?{urllib.parse.urlencode({'video_id': video_id, 'model_name': model})}"
    legacy_url = f"{base_url}/v1/videos/{urllib.parse.quote(str(video_id), safe='')}"
    deadline = time.monotonic() + VIDEO_POLL_TIMEOUT
    # 官方建议 1–2 秒查询一次；首个间隔 1.5s，之后仍按 1.35 倍退避 + 12s 封顶，避免长任务把上游打爆。
    delay = 1.5
    last_payload = {}
    while time.monotonic() < deadline:
        await asyncio.sleep(delay)
        raw = None
        last_error = None
        for url in (query_url, legacy_url):
            try:
                response = await client.get(url, headers=api_headers(provider=provider, model=model))
                response.raise_for_status()
                raw = response.json()
                break
            except Exception as exc:
                last_error = exc
        if raw is None:
            if last_error:
                raise last_error
            raise HTTPException(status_code=502, detail=f"Agnes 视频任务查询失败：{video_id}")
        last_payload = raw
        task_data = raw.get("data") if isinstance(raw.get("data"), dict) else raw
        status = str(task_data.get("status") or raw.get("status") or "").upper()
        if status in VIDEO_TASK_SUCCESS_STATUSES or video_output_urls(raw):
            return raw
        if status in VIDEO_TASK_FAILURE_STATUSES:
            error = task_data.get("error") if isinstance(task_data.get("error"), dict) else {}
            reason = task_data.get("message") or error.get("message") or raw.get("error") or raw.get("message") or str(raw)
            raise HTTPException(status_code=502, detail=humanize_video_task_failure(reason))
        delay = min(delay * 1.35, 12)
    raise HTTPException(status_code=504, detail=f"Agnes 视频生成任务超时：{last_payload or video_id}")

def agnes_video_uses_openai_protocol(model):
    """Agnes Video 2.5 系列改用 OpenAI Videos 兼容协议：
    POST /v1/videos 带 model/prompt/mode/seconds/size/aspect_ratio，再按 video_id 轮询。
    v2.0 仍走原生协议（width/height/num_frames/frame_rate），两条路径互不影响。
    """
    return str(model or "").strip().lower().startswith("agnes-video-2.5")

def agnes_video_size_tier(resolution="", model=""):
    """2.5 的 size 是档位（720P/1080P/1K/2K）；Flash 固定 720P。
    UI 的 480p / 4k 不是官方档位：480p 收敛到 720P，4k 收敛到官方最高档 2K。"""
    if str(model or "").strip().lower().startswith("agnes-video-2.5-flash"):
        return "720P"
    value = str(resolution or "").strip().lower()
    if "2k" in value or value == "4k":
        return "2K"
    if "1k" in value:
        return "1K"
    if "1080" in value:
        return "1080P"
    return "720P"

def agnes_video_seconds(duration):
    """2.5 的 seconds 是字符串且限制在 4–12 秒。"""
    try:
        value = int(duration or 5)
    except Exception:
        value = 5
    return str(max(4, min(12, value)))

def agnes_video_aspect_ratio(aspect):
    """Agnes 2.5 官方画幅白名单（21:9/16:9/4:3/1:1/3:4/9:16）；
    非官方输入（keep_ratio/adaptive/auto/9:21 等）收敛到最接近的官方值。"""
    value = str(aspect or "").strip()
    if value in {"21:9", "16:9", "4:3", "1:1", "3:4", "9:16"}:
        return value
    if value == "9:21":
        return "9:16"
    return "16:9"

def agnes_video_reference_image_limit(model):
    """官方 reference 模式参考图上限按型号区分：2.5 标准版 8 张、Flash 5 张。"""
    return 5 if str(model or "").strip().lower().startswith("agnes-video-2.5-flash") else 8

def build_agnes_openai_video_body(payload, model, image_urls, image_roles):
    """构造 Agnes 2.5 的 OpenAI Videos 请求体（纯函数，不发网络请求）。"""
    body = {
        "model": model,
        "prompt": str(payload.prompt or ""),
        "seconds": agnes_video_seconds(payload.duration),
        "size": agnes_video_size_tier(payload.resolution, model),
        "aspect_ratio": agnes_video_aspect_ratio(payload.aspect_ratio),
    }
    urls = [str(url) for url in (image_urls or []) if url]
    roles = [str(role or "").strip().lower() for role in (image_roles or [])]
    has_frame_roles = any(role in {"first_frame", "last_frame"} for role in roles)
    if urls and has_frame_roles:
        body["mode"] = "keyframe"
        first = next((url for url, role in zip(urls, roles) if role == "first_frame"), "")
        last = next((url for url, role in zip(urls, roles) if role == "last_frame"), "")
        if not first:
            first = urls[0]
        if not last and len(urls) > 1:
            last = urls[1]
        if first and first != last:
            body["first_frame"] = first
        if last and last != first:
            body["last_frame"] = last
        if "first_frame" not in body and "last_frame" not in body:
            body["mode"] = "reference"
            body["images"] = urls[:agnes_video_reference_image_limit(model)]
    elif urls:
        body["mode"] = "reference"
        body["images"] = urls[:agnes_video_reference_image_limit(model)]
    else:
        body["mode"] = "text"
    # 调用方明确指定生成方式时按它走，不再靠输入自动推断
    forced = _agent_video_mode(getattr(payload, "mode", ""))
    if forced and urls:
        if forced == "text_to_video":
            body["mode"] = "text"
            body.pop("first_frame", None)
            body.pop("last_frame", None)
            body.pop("images", None)
        elif forced == "image_to_video":
            body["mode"] = "keyframe"
            body["first_frame"] = urls[0]
            body.pop("last_frame", None)
            body.pop("images", None)
        elif forced == "start_end_to_video":
            body["mode"] = "keyframe"
            body["first_frame"] = urls[0]
            if len(urls) > 1:
                body["last_frame"] = urls[1]
            else:
                body.pop("last_frame", None)
            body.pop("images", None)
        elif forced == "reference_to_video":
            body["mode"] = "reference"
            body["images"] = urls[:agnes_video_reference_image_limit(model)]
            body.pop("first_frame", None)
            body.pop("last_frame", None)
    if payload.seed is not None:
        body["seed"] = payload.seed
    return body

def agnes_upstream_video_model(provider, model):
    """把历史遗留的 Agnes 视频模型名归一到上游真实存在的名字。

    apihub.agnes-ai.com 的 /v1/models 只有 agnes-video-2.5 / agnes-video-2.5-flash，
    旧名 agnes-video-v2.0 会被网关判成 model_not_found。只对官方 hub 归一：
    自建/别家中转如果自己提供了 v2.0，就按原样发，不替它做主。"""
    name = str(model or "").strip()
    base_url = str((provider or {}).get("base_url") or "").strip().lower()
    if "apihub.agnes-ai.com" not in base_url:
        return name
    mapped = AGNES_VIDEO_MODEL_ALIASES.get(name.lower(), "")
    if mapped and mapped != name:
        print(f"[agnes-video] 模型名归一：{name} → {mapped}（上游已无该模型）", flush=True)
        return mapped
    return name

def agnes_video_error_detail(body, provider, model):
    """把 Agnes 网关错误翻成能照着排查的中文提示。

    网关（new-api / one-api 风格）在「该分组没有这个模型的通道」时回的是
    {"error":{"code":"model_not_found","message":"No available channel for model ... (request id: ...)"}}，
    原文甩到画布上没人看得懂；而且 request id 每次请求都不一样，批量 3 行会把同一个原因
    数成「共 3 种原因」。展示文案里去掉 request id，完整 body 仍然打到服务端日志。"""
    raw = str(body or "").strip()
    try:
        data = json.loads(raw)
    except Exception:
        data = None
    code = ""
    message = ""
    if isinstance(data, dict):
        error = data.get("error")
        if isinstance(error, dict):
            code = str(error.get("code") or "").strip()
            message = str(error.get("message") or error.get("msg") or "").strip()
        elif isinstance(error, str):
            message = error.strip()
        if not code:
            code = str(data.get("code") or "").strip()
        if not message:
            message = str(data.get("message") or data.get("detail") or "").strip()
    if not message:
        message = raw
    message = re.sub(r"\s*[（(]request id:[^)）]*[)）]", "", message).strip()
    lowered = message.lower()
    unavailable = (code == "model_not_found"
                   or "no available channel" in lowered
                   or "model_not_found" in raw.lower())
    no_quota = (code == "insufficient_user_quota"
                or "pre-consume quota" in lowered
                or "insufficient quota" in lowered)
    provider_name = str((provider or {}).get("name") or (provider or {}).get("id") or "Agnes")
    if unavailable:
        alternatives = "、".join(item for item in AGNES_DEFAULT_VIDEO_MODELS if item != model)
        return (
            f"Agnes 视频接口错误：供应商「{provider_name}」当前分组下没有模型 {model} 的可用通道。"
            "请在供应商后台为该分组开通这个视频模型"
            + (f"，或在画布上改选 {alternatives}" if alternatives else "")
            + f"。上游原始信息：{message}"
        )
    if no_quota:
        return (
            f"Agnes 视频接口错误：供应商「{provider_name}」账户余额不足，本次生成无法扣费。"
            f"请先到供应商后台充值再生成。上游原始信息：{message}"
        )
    return f"Agnes 视频接口错误：{message}"

async def generate_agnes_video(client, payload, provider, base_url, requested_model):
    model = agnes_upstream_video_model(provider, selected_model(requested_model, "agnes-video-2.5"))
    is_openai_video = agnes_video_uses_openai_protocol(model)
    # 2.5 reference 模式参考图上限按型号区分（标准版 8 张、Flash 5 张）；v2.0 仍只取前 4 张。
    image_urls = []
    image_roles = []
    max_images = agnes_video_reference_image_limit(model) if is_openai_video else 4
    for ref in (payload.images or [])[:max_images]:
        url = await agnes_video_image_url(ref)
        if url:
            image_urls.append(url)
            image_roles.append(str(getattr(ref, "role", "") or "").strip().lower())
    if is_openai_video:
        body = build_agnes_openai_video_body(payload, model, image_urls, image_roles)
    else:
        width, height = agnes_video_dimensions(payload.aspect_ratio, payload.resolution)
        num_frames, frame_rate = agnes_video_frame_count(payload.duration, 24)
        body = {
            "model": model,
            "prompt": str(payload.prompt or ""),
            "width": width,
            "height": height,
            "num_frames": num_frames,
            "frame_rate": frame_rate,
        }
        if len(image_urls) == 1:
            body["image"] = image_urls[0]
        elif len(image_urls) > 1:
            body["extra_body"] = {"image": image_urls}
            has_frame_roles = any(role in {"first_frame", "last_frame"} for role in image_roles)
            if payload.multimodal or has_frame_roles:
                body["extra_body"]["mode"] = "keyframes"
        if payload.seed is not None:
            body["seed"] = payload.seed
    submit_url = f"{base_url}/v1/videos"
    response = await client.post(submit_url, headers=api_headers(provider=provider, model=model), json=body)
    response.raise_for_status()
    raw = response.json()
    video_id = str(raw.get("video_id") or "").strip()
    task_id = str(raw.get("task_id") or raw.get("id") or "").strip()
    result = raw
    if video_id and not video_output_urls(raw):
        result = await wait_for_agnes_video_task(client, provider, video_id, model)
    elif task_id and not video_output_urls(raw):
        result = await wait_for_video_task(client, provider, task_id, submit_url)
    urls = video_output_urls(result)
    if not urls:
        raise HTTPException(status_code=502, detail=f"Agnes 视频生成成功但没有返回视频：{result}")
    local_urls = [await save_remote_video_to_output(url) for url in urls]
    return {"videos": local_urls, "task_id": task_id or video_id, "video_id": video_id or None, "raw": result}

# ---- 玉玉API（yuli.host）OpenAI 视频格式：/v1/videos（multipart，支持 seconds 时长）----
def _yuli_model_norm(model: str) -> str:
    return str(model or "").strip().lower().replace("_", "").replace(".", "").replace("-", "")

def yuli_is_veo_openai_model(model: str) -> bool:
    # OpenAI multipart 格式当前只支持 veo_3_1 和 veo_3_1-fast
    return _yuli_model_norm(model) in {"veo31", "veo31fast"}

def yuli_openai_model_name(model: str) -> str:
    return "veo_3_1-fast" if _yuli_model_norm(model) == "veo31fast" else "veo_3_1"

def yuli_openai_size(aspect_ratio: str) -> str:
    value = str(aspect_ratio or "").strip()
    if value == "9:16":
        return "9x16"
    return "16x9"

def yuli_video_seconds(duration) -> str:
    try:
        value = int(duration)
    except Exception:
        value = 8
    if value <= 0:
        value = 8
    return str(value)

async def yuli_fetch_reference_bytes(client, ref_url):
    """把参考图（input_reference 垫图）取成 (filename, bytes, mime)，
    支持 /output、/assets 本地文件、data URL、http(s) URL。失败返回 None。"""
    ref_url = str(ref_url or "").strip()
    if not ref_url:
        return None
    if ref_url.startswith("data:"):
        header, _, b64 = ref_url.partition(",")
        mime = (header[5:].split(";")[0] or "image/png").strip()
        try:
            raw = base64.b64decode(b64)
        except Exception:
            return None
        ext = (mime.split("/")[-1] or "png").split("+")[0]
        return (f"input_reference.{ext}", raw, mime)
    path = output_file_from_url(ref_url)
    if path:
        try:
            with open(path, "rb") as f:
                raw = f.read()
        except Exception:
            return None
        mime = content_type_for_path(path)
        return (os.path.basename(path) or "input_reference", raw, mime)
    if ref_url.startswith("http://") or ref_url.startswith("https://"):
        try:
            resp = await client.get(ref_url)
            resp.raise_for_status()
            raw = resp.content
        except Exception:
            return None
        mime = (resp.headers.get("content-type") or "image/png").split(";")[0].strip()
        ext = (mime.split("/")[-1] or "png").split("+")[0]
        return (f"input_reference.{ext}", raw, mime)
    return None

async def generate_yuli_openai_video(client, payload, provider, base_url, requested_model):
    """玉玉API veo3.1 走 OpenAI multipart 格式 /v1/videos，支持 seconds 时长控制。"""
    submit_url = f"{base_url}/v1/videos"
    data = {
        "model": yuli_openai_model_name(requested_model),
        "prompt": str(payload.prompt or ""),
        "seconds": yuli_video_seconds(payload.duration),
        "size": yuli_openai_size(payload.aspect_ratio),
        "watermark": "true" if payload.watermark else "false",
    }
    files = {}
    for ref in (payload.images or [])[:1]:
        ref_file = await yuli_fetch_reference_bytes(client, getattr(ref, "url", ""))
        if ref_file:
            files["input_reference"] = ref_file
            break
    headers = api_headers(json_body=False, provider=provider)
    if files:
        response = await client.post(submit_url, headers=headers, data=data, files=files)
    else:
        # 文生视频无垫图时，仍以 multipart/form-data 提交（把文本字段作为表单分块），
        # 避免 httpx 在只有 data 时退化成 application/x-www-form-urlencoded。
        multipart_fields = {key: (None, value) for key, value in data.items()}
        response = await client.post(submit_url, headers=headers, files=multipart_fields)
    response.raise_for_status()
    try:
        raw = response.json()
    except Exception as exc:
        resp_text = (response.text or "")[:500]
        raise HTTPException(status_code=502, detail=f"玉玉API 视频接口返回非 JSON 响应（状态 {response.status_code}）：{resp_text}") from exc
    task_id = raw.get("id") or extract_task_id(raw) or raw.get("task_id")
    result = raw
    if task_id and not video_output_urls(raw):
        result = await wait_for_video_task(client, provider, task_id, submit_url)
    urls = video_output_urls(result)
    if not urls:
        raise HTTPException(status_code=502, detail=f"视频生成成功但没有返回视频：{result}")
    local_urls = [await save_remote_video_to_output(url) for url in urls]
    return {"videos": local_urls, "task_id": task_id, "raw": result}

def volcengine_video_prompt_text(prompt, aspect_ratio="", duration=None):
    text = str(prompt or "").strip()
    suffixes = []
    ratio = str(aspect_ratio or "").strip()
    if ratio:
        suffixes.append(f"--ratio {ratio}")
    if not suffixes:
        return text
    suffix_text = " ".join(suffixes)
    return f"{text} {suffix_text}".strip() if text else suffix_text

async def run_canvas_video_task(task_id: str, payload: CanvasVideoRequest):
    """视频生成任务执行器（Task Engine 调用；同步模式下由请求内联执行，异步模式由 worker 执行）。
    阶段：provider_processing（含素材上传/提交/轮询/下载）→ saving → succeeded/failed/jimeng_pending。
    平台分发逻辑不动（canvas_video_run 原样）。"""
    task_set_status(task_id, "provider_processing", extra={"submitted_to_provider": True})
    try:
        result = await canvas_video_run(payload)
    except Exception as exc:
        detail = getattr(exc, "detail", None) or str(exc)
        task_set_status(task_id, "failed", error=str(detail)[:2000], status_code=getattr(exc, "status_code", 500))
        _task_credit_refund(task_id, "video_task_failed")
        await _agent_writeback_and_broadcast(task_id, "video", [], str(detail)[:300])
        raise
    if isinstance(result, dict) and result.get("jimeng_pending"):
        # 即梦云端还在排队：标记为 jimeng_pending，前端据 submit_id 持久续查
        task_set_status(task_id, "jimeng_pending", extra={
            "jimeng_pending": True,
            "submit_id": result.get("submit_id") or "",
            "kind_legacy": result.get("kind") or "video",
            "queue_info": result.get("queue_info"),
            "message": result.get("message") or "",
        })
        return result
    upstream = ""
    request_id = ""
    if isinstance(result, dict):
        raw = result.get("raw")
        upstream = str(extract_task_id(raw) or "") if isinstance(raw, dict) else str(result.get("task_id") or "")
        request_id = str(raw.get("id") or "") if isinstance(raw, dict) else ""
    task_set_status(task_id, "saving")
    result = _attach_upstream_cost(result, result.get("raw") if isinstance(result, dict) else None)
    credits = _task_credit_settle(task_id, result=result)
    task_set_status(task_id, "succeeded", extra={
        "result": result,
        "provider_task_id": upstream,
        "request_id": request_id,
        "credits": credits,
    })
    # Agent 发起的生成：任务完成后把视频写回画布节点（加锁、追加不覆盖、写完广播）
    await _agent_writeback_and_broadcast(task_id, "video", _agent_result_video_urls(result))
    return result

TASK_RUNNERS["run_canvas_video_task"] = run_canvas_video_task

@app.post("/api/canvas-video")
async def canvas_video(payload: CanvasVideoRequest, async_mode: bool = Query(False, alias="async")):
    payload.provider_id = member_provider(payload.provider_id)
    """视频生成入口（V2 Phase 1 任务化适配，平台分发逻辑不动）。
    默认同步模式：请求内联执行并返回原响应结构（前端零改动），同时记录完整任务证据链；
    ?async=1 时进入 Task Engine 队列，立即返回 {task_id, status: "queued"}。"""
    video_model = str(payload.model or "").strip() or "veo3-fast"
    # 先预扣再建任务：余额不足直接 402，不创建 task，不走异常删除路径。
    charge = credits_charge_start("video", video_model, _credits_video_params(payload),
                                 provider=payload.provider_id)
    try:
        task = task_create(kind="video", payload=payload, runner_name="run_canvas_video_task",
                           provider_id=payload.provider_id, model_id=payload.model or "")
    except Exception:
        credits_charge_refund(charge, "task_create_failed")
        raise
    if charge:
        credits_charge_attach_task(charge, task["id"])
        task_set_status(task["id"], "queued", extra={"credits_charge_id": charge["id"],
                                                     "credits": charge.get("credits")})
    if async_mode:
        await task_enqueue(task["id"])
        response = {"task_id": task["id"], "status": "queued", "async_mode": True}
        if charge:
            response["credits"] = charge.get("credits")
        return response
    task_set_status(task["id"], "running")
    result = await run_canvas_video_task(task["id"], payload)
    if isinstance(result, dict) and result.get("jimeng_pending"):
        if charge:
            result = {**result, "credits": charge.get("credits")}
        return result
    credits = (task_get(task["id"]) or {}).get("credits") or (charge.get("credits") if charge else None)
    return credits_attach({**result, "task_id": task["id"]}, credits)

async def canvas_video_run(payload: CanvasVideoRequest):
    async with provider_slot(get_api_provider(payload.provider_id)):
        return await _canvas_video_run_unlimited(payload)

def is_pixverse_provider(provider) -> bool:
    return str(provider.get("id") or "").strip().lower() == "pixverse" or str(provider.get("protocol") or "").strip().lower() == "pixverse"


def _pixverse_local_or_public_media(value):
    value = str(value or "").strip()
    path = output_file_from_url(value)
    if path:
        if os.path.getsize(path) > 100 * 1024 * 1024:
            raise HTTPException(status_code=400, detail="PixVerse 媒体文件不能超过 100MB")
        return path, ""
    if value.startswith(("http://", "https://")):
        return "", value
    raise HTTPException(status_code=400, detail="媒体必须是画布内已有文件或公网 http/https 地址")


async def _pixverse_prepare_upload_video(path):
    if not path or os.path.getsize(path) <= 900_000:
        return "", path
    ffmpeg = ffmpeg_binary()
    if not ffmpeg:
        raise HTTPException(status_code=400, detail="上传副本超过 APIMart 网关限制，需要 FFmpeg 压缩后再上传")
    folder = tempfile.mkdtemp(prefix="novai-pixverse-upload-")
    output = os.path.join(folder, "upload.mp4")
    proc = await asyncio.to_thread(subprocess.run, [ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
                                                   "-i", path, "-vf", "scale=540:-2", "-c:v", "libx264",
                                                   "-b:v", "400k", "-maxrate", "440k", "-bufsize", "880k",
                                                   "-c:a", "aac", "-b:a", "48k", "-movflags", "+faststart", output],
                                   stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if proc.returncode != 0 or not os.path.isfile(output):
        shutil.rmtree(folder, ignore_errors=True)
        raise HTTPException(status_code=400, detail="无法压缩上传副本，请缩短视频或手动压缩后重试")
    if os.path.getsize(output) > 950_000:
        shutil.rmtree(folder, ignore_errors=True)
        raise HTTPException(status_code=400, detail="压缩后仍超过 APIMart 网关限制，请缩短视频后重试")
    return folder, output


async def _pixverse_extract_voice_sample(video_url):
    path, public_url = _pixverse_local_or_public_media(video_url)
    if public_url:
        saved = await save_remote_video_to_output(public_url, prefix="lipsync_source_")
        path = output_file_from_url(saved)
    if not path:
        raise HTTPException(status_code=400, detail="无法读取原视频以提取人声样本")
    ffmpeg = ffmpeg_binary()
    if not ffmpeg:
        raise HTTPException(status_code=400, detail="提取原视频人声需要 FFmpeg；也可以直接上传声音样本或成品音频")
    folder = tempfile.mkdtemp(prefix="novai-pixverse-voice-")
    output = os.path.join(folder, "voice-sample.wav")
    proc = await asyncio.to_thread(subprocess.run, [ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
                                                   "-i", path, "-t", "15", "-vn", "-ac", "1", "-ar", "16000", output],
                                   stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if proc.returncode != 0 or not os.path.isfile(output):
        shutil.rmtree(folder, ignore_errors=True)
        raise HTTPException(status_code=400, detail="无法从原视频提取人声，请上传清晰的声音样本")
    return folder, output


async def generate_pixverse_lipsync(payload: CanvasVideoRequest, provider):
    from server.integrations import pixverse

    if not payload.videos:
        raise HTTPException(status_code=400, detail="LipSync 需要选择一个原视频")
    video_url = str(payload.videos[0].get("url") if isinstance(payload.videos[0], dict) else payload.videos[0] or "").strip()
    if not video_url:
        raise HTTPException(status_code=400, detail="LipSync 原视频地址为空")
    duration = probe_local_video_duration_seconds(video_url)
    if duration is not None and duration > 60:
        raise HTTPException(status_code=400, detail="首版 LipSync 支持 60 秒以内的视频，请先裁剪后再试")
    direct_audio = str(payload.audios[0] if payload.audios else "").strip()
    if not direct_audio and not payload.voice_consent:
        raise HTTPException(status_code=400, detail="克隆或复用自定义声音前，请确认你拥有该声音的使用授权")
    if not direct_audio and len(str(payload.prompt or "").strip()) > 200:
        raise HTTPException(status_code=400, detail="PixVerse 新台词不能超过 200 个字符")
    base_url = str(os.getenv("PIXVERSE_BASE_URL") or provider.get("base_url") or pixverse.DEFAULT_BASE_URL).rstrip("/")
    api_key = provider_env_key_value(provider["id"])
    auth_mode = "bearer" if str(provider.get("id") or "") == "apimart" else "api-key"
    video_path, video_public_url = _pixverse_local_or_public_media(video_url)
    upload_folder, video_path = await _pixverse_prepare_upload_video(video_path)
    voice_folder = ""
    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env(provider), timeout=VIDEO_POLL_TIMEOUT) as client:
            uploaded_video = await pixverse.upload_media(client, base_url, api_key, auth_mode, file_path=video_path or None,
                                                        file_url=video_public_url, content_type="video/mp4")
            audio_media_id = None
            speaker_id = str(payload.speaker_id or "").strip()
            if direct_audio:
                audio_path, audio_public_url = _pixverse_local_or_public_media(direct_audio)
                uploaded_audio = await pixverse.upload_media(client, base_url, api_key, auth_mode, file_path=audio_path or None,
                                                             file_url=audio_public_url, content_type="audio/mpeg")
                audio_media_id = uploaded_audio["media_id"]
            elif not speaker_id:
                sample_url = str(payload.voice_sample or "").strip()
                if sample_url:
                    sample_path, sample_public_url = _pixverse_local_or_public_media(sample_url)
                else:
                    voice_folder, sample_path = await _pixverse_extract_voice_sample(video_url)
                    sample_public_url = ""
                uploaded_sample = await pixverse.upload_media(client, base_url, api_key, auth_mode, file_path=sample_path or None,
                                                              file_url=sample_public_url, content_type="audio/wav")
                speaker_id = await pixverse.create_custom_voice(client, base_url, api_key, auth_mode, uploaded_sample["media_id"])
            submitted = await pixverse.generate_lipsync(client, base_url, api_key, auth_mode,
                                                        video_media_id=uploaded_video["media_id"],
                                                        audio_media_id=audio_media_id, speaker_id=speaker_id,
                                                        script=payload.prompt)
            video_id = pixverse._resp(submitted)["video_id"]
            result = await pixverse.wait_for_video(client, base_url, api_key, auth_mode, video_id)
    except pixverse.PixverseError as exc:
        raise HTTPException(status_code=exc.status_code, detail=str(exc)) from exc
    finally:
        if upload_folder:
            shutil.rmtree(upload_folder, ignore_errors=True)
        if voice_folder:
            shutil.rmtree(voice_folder, ignore_errors=True)
    result_url = str(pixverse._resp(result).get("url") or "").strip()
    if not result_url:
        raise HTTPException(status_code=502, detail="PixVerse 未返回可下载的视频地址")
    local_url = await save_remote_video_to_output(result_url, prefix="lipsync_")
    return {**{"videos": [local_url], "task_id": video_id, "speaker_id": speaker_id, "raw": result},
            **build_canvas_meta([local_url], payload, "video")}


async def _canvas_video_run_unlimited(payload: CanvasVideoRequest):
    provider = get_api_provider(payload.provider_id)
    # 视频的参考帧 / 参考视频同样可能是对方电脑的局域网地址：先落本机再走上游
    if payload.images:
        localized_images = await _localize_private_reference_urls([ref.dict() for ref in payload.images])
        payload.images = [AIReference(**item) for item in localized_images]
    if payload.videos:
        localized_videos: List[Any] = []
        for item in payload.videos:
            url = str(item.get("url") if isinstance(item, dict) else item or "").strip()
            if not url:
                localized_videos.append(item)
                continue
            local = await _localize_private_media_url(url)
            localized_videos.append(dict(item, url=local) if isinstance(item, dict) else local)
        payload.videos = localized_videos
    # 「原图比例」：视频 ratio=adaptive/auto 且带首帧/参考图时，按参考图真实比例定画幅；
    # 编辑/动作迁移（duration=-1）保持 adaptive，交给上游跟随输入视频
    if _agent_auto_ratio(payload.aspect_ratio or payload.size) and payload.images:
        try:
            is_edit = int(payload.duration or 0) == -1
        except (TypeError, ValueError):
            is_edit = False
        # 首帧/首尾帧：输出画幅跟随帧图本身，保持 adaptive 交给下游按 first_frame/last_frame 契约处理
        # （上游首帧任务只接受 adaptive，这里若改成具体比例会被拒绝）
        if not is_edit and any(str(getattr(ref, "role", "") or "") in ("first_frame", "last_frame")
                               for ref in payload.images):
            is_edit = True
        if not is_edit:
            ref_list = [{"url": str(getattr(ref, "url", "") or "")}
                        for ref in payload.images if str(getattr(ref, "url", "") or "").strip()]
            source_ratio, ratio_note = _agent_auto_ratio_video_ratio(provider, payload.model, ref_list)
            if source_ratio:
                payload.aspect_ratio = source_ratio
                print(f"[Video] {ratio_note}", flush=True)
    # 生成方式明确指定时，按这种方式走（校验输入 + 路由），不再靠输入自动推断；
    # 不传 mode 的调用保持原来的推断行为。
    explicit_mode = _agent_video_mode(getattr(payload, "mode", ""))
    if explicit_mode:
        min_images, need_video, hint = video_mode_required_inputs(explicit_mode)
        image_count = sum(1 for ref in (payload.images or []) if str(getattr(ref, "url", "") or "").strip())
        video_count = sum(1 for item in (payload.videos or [])
                          if str(item.get("url") if isinstance(item, dict) else item or "").strip())
        if image_count < min_images or (need_video and not video_count):
            raise HTTPException(
                status_code=400,
                detail=f"生成方式 {explicit_mode} 输入不足：{hint}"
                       f"（当前 {image_count} 张图 / {video_count} 段视频）")
        if explicit_mode == "digital_human":
            if not (is_pixverse_provider(provider) or str(payload.model or "").strip().lower() == "pixverse-lipsync"):
                raise HTTPException(
                    status_code=400,
                    detail="数字人（口型同步）只在 PixVerse 口播通道可用：请选 PixVerse 平台的 pixverse-lipsync",
                )
            return await generate_pixverse_lipsync(payload, provider)
        if explicit_mode in ("video_edit", "video_extend") and video_count:
            # 上游用 duration=-1 表示「跟随输入视频」（编辑/续写），沿用既有约定
            payload.duration = -1
    if is_pixverse_provider(provider) or str(payload.model or "").strip().lower() == "pixverse-lipsync":
        return await generate_pixverse_lipsync(payload, provider)
    if is_jimeng_provider(provider):
        return await generate_jimeng_video(payload, provider)
    if is_runninghub_provider(provider):
        try:
            return await generate_runninghub_video(payload, provider)
        except httpx.HTTPStatusError as exc:
            text = exc.response.text
            raise HTTPException(status_code=exc.response.status_code, detail=f"RunningHub 视频接口错误：{text}") from exc
        except httpx.HTTPError as exc:
            log_net_error(f"视频(RunningHub) 网络/TLS错误 model={payload.model}", exc)
            raise HTTPException(status_code=502, detail=f"请求 RunningHub 视频接口失败：{exc}") from exc
    if is_lovart_provider(provider):
        try:
            return await generate_lovart_video(payload, provider)
        except httpx.HTTPStatusError as exc:
            text = exc.response.text
            raise HTTPException(status_code=exc.response.status_code, detail=f"Lovart 视频接口错误：{text[:300]}") from exc
        except httpx.HTTPError as exc:
            log_net_error(f"视频(Lovart) 网络/TLS错误 model={payload.model}", exc)
            raise HTTPException(status_code=502, detail=f"请求 Lovart 视频接口失败：{exc}") from exc
    base_url = video_api_root(provider)
    if not base_url:
        raise HTTPException(status_code=400, detail=f"{provider.get('name') or provider['id']} 未配置 Base URL")
    api_key = provider_env_key_value(provider["id"])
    if not api_key:
        raise HTTPException(status_code=400, detail=f"未配置 {provider.get('name') or provider['id']} 的 API Key，请在 API 设置中填写。")
    is_apimart = is_apimart_provider(provider)
    is_volcengine = is_volcengine_provider(provider)
    is_yuli = is_yuli_provider(provider)
    is_agnes = is_agnes_provider(provider, payload.model)
    volc_is_proxy = bool(is_volcengine and urllib.parse.urlparse(base_url).path.rstrip("/"))
    submit_urls = video_submit_url_candidates(provider, base_url)
    submit_url = submit_urls[0]
    requested_model = selected_model(payload.model, "agnes-video-2.5" if is_agnes else "veo3-fast")
    if is_agnes:
        requested_model = agnes_upstream_video_model(provider, requested_model)
    is_veo31 = is_apimart and is_apimart_veo31_model(requested_model)
    if is_agnes:
        try:
            async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env(provider), timeout=VIDEO_POLL_TIMEOUT) as agnes_client:
                return await generate_agnes_video(agnes_client, payload, provider, base_url, requested_model)
        except httpx.HTTPStatusError as exc:
            text = exc.response.text
            print(f"[agnes-video] 上游 {exc.response.status_code} model={requested_model} body={text[:1000]}", flush=True)
            raise HTTPException(status_code=exc.response.status_code, detail=agnes_video_error_detail(text, provider, requested_model)) from exc
        except httpx.HTTPError as exc:
            log_net_error(f"视频(Agnes) 网络/TLS错误 model={requested_model}", exc)
            raise HTTPException(status_code=502, detail=f"请求 Agnes 视频接口失败：{exc}") from exc
    # 玉玉API veo3.1 走 OpenAI multipart 格式（支持 seconds 时长）；其余模型（doubao 等）
    # 沿用下方原生 /v1/video/create JSON 流程。
    if is_yuli and yuli_is_veo_openai_model(requested_model):
        try:
            async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env(provider), timeout=VIDEO_POLL_TIMEOUT) as yuli_client:
                return await generate_yuli_openai_video(yuli_client, payload, provider, base_url, requested_model)
        except httpx.HTTPStatusError as exc:
            text = exc.response.text
            raise HTTPException(status_code=exc.response.status_code, detail=f"上游视频接口错误：{text}") from exc
        except httpx.HTTPError as exc:
            log_net_error(f"视频(玉玉) 网络/TLS错误 model={requested_model}", exc)
            raise HTTPException(status_code=502, detail=f"请求上游视频接口失败：{exc}") from exc
    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env(provider), timeout=VIDEO_POLL_TIMEOUT) as client:
            # --- 构造图片载荷 ---
            if is_apimart:
                # APIMart 只接受 http/https 或 asset:// URL，先上传本地图片取回网络 URL
                image_with_roles = []
                invalid_images = []  # 每项为 (原始 URL, 失败原因)
                video_payload = []
                invalid_videos = []
                for ref_url in payload.videos[:3]:
                    ref_url = ref_url.get("url") if isinstance(ref_url, dict) else ref_url
                    ref_url = str(ref_url or "").strip()
                    if not ref_url:
                        continue
                    normalized_video_url = await upload_video_for_apimart(client, provider, ref_url)
                    if valid_apimart_video_image_input(normalized_video_url):
                        video_payload.append(normalized_video_url)
                    else:
                        reason = normalized_video_url[4:] if isinstance(normalized_video_url, str) and normalized_video_url.startswith("ERR:") else apimart_video_reference_error(ref_url)
                        invalid_videos.append((ref_url, reason))
                if invalid_videos:
                    first_url, first_reason = invalid_videos[0]
                    sample = invalid_video_image_preview(first_url)
                    raise HTTPException(
                        status_code=400,
                        detail=f"输入视频无法转换为 APIMart 支持的格式：{sample}\n原因：{first_reason}"
                    )
                apimart_model = apimart_veo31_model(requested_model) if is_veo31 else ""
                if apimart_model == "veo3.1-lite" and payload.images:
                    raise HTTPException(status_code=400, detail="veo3.1-lite 不支持图片输入，请改用 veo3.1-fast 或 veo3.1-quality。")
                image_limit = 0 if apimart_model == "veo3.1-lite" else (3 if is_veo31 else 9)
                veo31_body = None
                if is_veo31:
                    veo31_body = {
                        "prompt": payload.prompt,
                        "model": apimart_model,
                        "duration": apimart_veo31_duration(payload.duration),
                        "aspect_ratio": apimart_veo31_aspect(payload.aspect_ratio),
                        "resolution": apimart_veo31_resolution(payload.resolution),
                    }
                    if apimart_model != "veo3.1-lite":
                        veo31_body["official_fallback"] = False
                for ref in payload.images[:image_limit]:
                    if not ref.url:
                        continue
                    role = str(ref.role or "").strip()
                    if not is_veo31 and role in {"first_frame", "last_frame", "reference_image"}:
                        up_url = await upload_video_image_for_apimart(client, provider, ref.url)
                        if valid_apimart_video_image_input(up_url):
                            image_with_roles.append({"url": up_url, "role": role})
                        else:
                            reason = up_url[4:] if isinstance(up_url, str) and up_url.startswith("ERR:") else "未知错误"
                            invalid_images.append((ref.url, reason))
                image_payload = []
                if not image_with_roles:
                    image_refs = [ref for ref in payload.images[:image_limit] if ref.url]
                    direct_inputs = apimart_direct_data_urls(
                        [{"url": ref.url} for ref in image_refs], veo31_body
                    ) if is_veo31 else None
                    quota_reason = ""
                    if direct_inputs is not None:
                        print(f"APIMart VEO3.1 图片 data URL 直发 {len(direct_inputs)} 张，不调用上传接口")
                        image_payload = direct_inputs
                    else:
                        for ref in image_refs:
                            up_url = await upload_video_image_for_apimart(client, provider, ref.url)
                            if valid_apimart_video_image_input(up_url):
                                image_payload.append(up_url)
                            else:
                                reason = up_url[4:] if isinstance(up_url, str) and up_url.startswith("ERR:") else "未知错误"
                                invalid_images.append((ref.url, reason))
                                if apimart_error_is_quota(up_url):
                                    quota_reason = reason
                    if quota_reason and not image_payload and is_veo31 and veo31_body:
                        fallback, fit = apimart_reference_data_urls_with_fit(
                            [{"url": ref.url} for ref in image_refs], veo31_body
                        )
                        if fit:
                            print(f"APIMart 上传额度用尽，VEO3.1 改用压缩 data URL（data-url）{len(fallback)} 张")
                            image_payload = fallback
                        else:
                            sample = invalid_video_image_preview(image_refs[0].url if image_refs else "")
                            raise HTTPException(
                                status_code=400,
                                detail=f"输入图片无法转换为视频接口支持的格式：{sample}\n原因："
                                       f"{quota_reason}{apimart_data_url_over_budget_reason(fallback, veo31_body)}"
                            )
                if payload.images and not image_with_roles and not image_payload:
                    first_url, first_reason = invalid_images[0] if invalid_images else ("", "未知错误")
                    sample = invalid_video_image_preview(first_url)
                    raise HTTPException(status_code=400, detail=f"输入图片无法转换为视频接口支持的格式：{sample}\n原因：{first_reason}\n本地图片会自动压缩后上传；仍失败请换一张更小的图。VEO3.1 需要图片是 APIMart 可访问的 http/https / asset:// / data URL。")
                # --- APIMart 请求体 ---
                if is_veo31:
                    model = apimart_model
                    body = veo31_body
                    if image_payload and model != "veo3.1-lite":
                        video_images = image_payload[:3]
                        if model == "veo3.1-quality" and len(video_images) > 2:
                            video_images = video_images[:2]
                        body["image_urls"] = video_images
                        if len(video_images) == 2:
                            body["generation_type"] = "frame"
                        elif len(video_images) >= 3 and model != "veo3.1-quality":
                            body["generation_type"] = "reference"
                else:
                    apimart_seedance_model = selected_model(payload.model, "doubao-seedance-2.0")
                    apimart_video_caps = apimart_video_model_caps(apimart_seedance_model)
                    video_params = apimart_video_body_params(
                        apimart_seedance_model, payload.duration,
                        payload.aspect_ratio or payload.size, payload.resolution)
                    body = {"prompt": payload.prompt, "model": apimart_seedance_model}
                    if video_params.get("duration") is not None:
                        body["duration"] = video_params["duration"]
                    if video_params.get("ratio_key"):
                        body[video_params["ratio_key"]] = video_params["ratio_value"]
                    if video_params.get("resolution_key") and video_params.get("resolution_value"):
                        body[video_params["resolution_key"]] = video_params["resolution_value"]
                    if image_with_roles and video_payload:
                        raise HTTPException(status_code=400, detail="APIMart Seedance 的 image_with_roles 不能和 video_urls 同时使用，请只保留图片首尾帧或参考视频其中一种。")
                    if image_with_roles:
                        body["image_with_roles"] = image_with_roles
                    elif image_payload:
                        body["image_urls"] = image_payload[:9]
                    if video_payload:
                        if int(payload.duration or 0) == -1:
                            body["duration"] = -1
                        if str(payload.aspect_ratio or "").strip().lower() == "adaptive" and video_params.get("ratio_key"):
                            body[video_params["ratio_key"]] = "adaptive"
                        body["video_urls"] = video_payload
                    # 首尾帧输出跟随首帧比例。能力表未登记 adaptive 时，body_params 会先吸附成 1:1，
                    # 这里按上游 first_frame/last_frame 契约恢复 adaptive，不能再改成固定画幅。
                    if (str(payload.aspect_ratio or "").strip().lower() == "adaptive" and video_params.get("ratio_key")
                            and any(str(item.get("role") or "") in {"first_frame", "last_frame"} for item in image_with_roles)):
                        body[video_params["ratio_key"]] = "adaptive"
                    audio_payload = []
                    invalid_audios = []
                    for ref_url in (payload.audios or [])[:3]:
                        ref_url = str(ref_url or "").strip()
                        if not ref_url:
                            continue
                        normalized_audio_url = await upload_audio_for_apimart(client, provider, ref_url)
                        if valid_apimart_video_image_input(normalized_audio_url):
                            audio_payload.append(normalized_audio_url)
                        else:
                            reason = normalized_audio_url[4:] if isinstance(normalized_audio_url, str) and normalized_audio_url.startswith("ERR:") else "未知错误"
                            invalid_audios.append((ref_url, reason))
                    if invalid_audios:
                        first_url, first_reason = invalid_audios[0]
                        raise HTTPException(status_code=400, detail=f"参考音频无法转换为 APIMart 支持的地址：{invalid_video_image_preview(first_url)}\n原因：{first_reason}")
                    if audio_payload:
                        body["audio_urls"] = audio_payload
                    if payload.trusted_asset:
                        img_count = len(body.get("image_urls") or []) or len(image_with_roles)
                        body["prompt"] = apply_trusted_asset_prompt_index(
                            body["prompt"], img_count, len(video_payload), len(audio_payload)
                        )
                    if payload.seed is not None and (apimart_video_caps is None or apimart_video_caps.get("seed")):
                        body["seed"] = payload.seed
                    if payload.return_last_frame:
                        body["return_last_frame"] = True
                    if (apimart_video_caps is not None and apimart_video_caps.get("generate_audio")
                            and "seedance" in str(apimart_seedance_model or "").lower()):
                        # 能出声音的模型（Seedance 2.x 等）上游默认 generate_audio=true：关声音必须显式发 false，
                        # 否则节点上「声音」关着、出来的片段照样带一段随机配乐，剪到一起音乐一段一段地跳
                        body["generate_audio"] = bool(payload.generate_audio)
                    elif payload.generate_audio and (apimart_video_caps is None or apimart_video_caps.get("generate_audio")):
                        body["generate_audio"] = True
                    # 水印：H3-Max 1080P 一律不发（连 false 都不能带）；其余模型按 caps.watermark 且用户显式开启才发
                    body.pop("aigc_watermark", None)
                    if not apimart_video_watermark_allowed(apimart_seedance_model, payload.resolution):
                        body.pop("watermark", None)
                    elif payload.watermark and (apimart_video_caps is None or apimart_video_caps.get("watermark")):
                        body["watermark"] = True
            else:
                # 非 APIMart：data URL 方式（OpenAI / ComflyAI 接口）
                if is_volcengine and not volc_is_proxy:
                    text = str(payload.prompt or "").strip()
                    volc_model = selected_model(payload.model, "doubao-seedance-2-0-fast-260128")
                    body = {
                        "model": volc_model,
                        "content": [
                            {
                                "type": "text",
                                "text": text,
                            }
                        ],
                    }
                    # 火山方舟视频接口（含 Seedance 2.0 图生视频）均通过 body 的 duration 字段控制时长；
                    # 之前对 seedance-2.0 + 参考图的情况省略了 duration，导致接口回退到默认 5s。
                    body["duration"] = volcengine_video_duration(payload.duration, volc_model)
                    if payload.aspect_ratio:
                        body["ratio"] = volcengine_video_ratio(payload.aspect_ratio)
                    resolution = volcengine_video_resolution(payload.resolution, volc_model)
                    if resolution:
                        body["resolution"] = resolution
                    if payload.watermark:
                        body["watermark"] = True
                    if payload.generate_audio:
                        body["generate_audio"] = True
                    elif "seedance-2" in str(volc_model or "").lower():
                        body["generate_audio"] = False   # Seedance 2.x 默认带声音：关声音要显式发 false
                    if payload.camerafixed:
                        body["camerafixed"] = True
                    image_like_urls = set()
                    frame_roles_used = {"first_frame": False, "last_frame": False}
                    volc_video_count = 0

                    def append_volcengine_image(url: str, role: str):
                        if role in {"first_frame", "last_frame"}:
                            if frame_roles_used.get(role):
                                return False
                            frame_roles_used[role] = True
                        elif role != "reference_image":
                            return False
                        body["content"].append({
                            "type": "image_url",
                            "image_url": {"url": url},
                            "role": role,
                        })
                        image_like_urls.add(url)
                        return True

                    # 编辑任务判定：prompt 含编辑/替换关键词，或前端显式标记了 role=video/edit/target
                    def _volc_edit_task_flag():
                        if is_volcengine_edit_prompt(text):
                            return True
                        for v in (payload.videos or [])[:3]:
                            if isinstance(v, dict):
                                r = str(v.get("role") or "").strip().lower()
                                if r in ("video", "edit", "target"):
                                    return True
                        return False
                    is_edit_task = _volc_edit_task_flag()
                    for ref in payload.images[:9]:
                        url = volcengine_media_reference_url(ref.url, max_image_size=1536)
                        if not url:
                            continue
                        role = volcengine_content_role(ref.role, "image")
                        if role in {"first_frame", "last_frame"}:
                            # 编辑任务：首尾帧与编辑目标视频互斥（火山组合限制），降级为参考图，
                            # 参考图（如新鞋外观）必须全部保留，不能只取第一张。
                            if is_edit_task:
                                append_volcengine_image(url, "reference_image")
                            else:
                                append_volcengine_image(url, role)
                        elif payload.multimodal or is_edit_task:
                            # 智能多帧/多参模式或编辑任务：多张图作为参考图提交，不能伪装成首帧。
                            append_volcengine_image(url, "reference_image")
                        elif not frame_roles_used["first_frame"]:
                            # 普通图生视频没有显式 role 时，只取第一张作为首帧。
                            append_volcengine_image(url, "first_frame")
                    for url in (payload.videos or [])[:3]:
                        if isinstance(url, dict):
                            text_url = str(url.get("url") or "").strip()
                            explicit_role = str(url.get("role") or "").strip().lower()
                        else:
                            text_url = str(url or "").strip()
                            explicit_role = ""
                        if not text_url:
                            continue
                        # 火山 r2v 模式限制参考视频时长 ≤15.2s，超限自动截取前 15s（本地文件操作，更新 text_url）
                        # 必须先截取再公网化：截取产物是本地 /assets/ 文件，后续统一走公网 URL 检查，
                        # 否则 data URL 会绕过检查直接提交，火山报 "reference_video must be provided as a web url"。
                        video_duration = probe_local_video_duration_seconds(text_url)
                        # 编辑目标视频有 4 秒下限：先把本条视频的编辑目标判定算好，短素材在发请求前就拦下，
                        # 否则要等上游回一段看不懂的参数错误。
                        is_edit_target = is_volcengine_edit_prompt(text) or explicit_role in ("video", "edit", "target")
                        ensure_volcengine_edit_video_duration(video_duration, is_edit_target)
                        if video_duration is not None and video_duration > 15.2:
                            trimmed = volcengine_trim_video_to_seconds(text_url)
                            if trimmed and trimmed != text_url:
                                print(f"[volc] 参考视频 {video_duration:.1f}s 超限，自动截取为 {trimmed}")
                                text_url = trimmed
                            else:
                                raise HTTPException(
                                    status_code=400,
                                    detail=f"视频时长 {video_duration:.1f}s 超过火山引擎限制（≤15.2s），且自动截取失败，请手动截取前 15 秒后重试。当前视频: {text_url[:80]}"
                                )
                        # 火山输出音频版权检测：参考视频带背景音乐会报 copyright restrictions，
                        # 自动静音（去音轨）后提交，画面/动作参考不受影响。
                        muted = volcengine_mute_video(text_url)
                        if muted and muted != text_url:
                            print(f"[volc] 参考视频含音轨，自动静音为 {muted}")
                            text_url = muted
                        media_url = volcengine_media_reference_url(text_url, max_image_size=1536 if looks_like_image_media_url(text_url) else None)
                        if not media_url:
                            continue
                        if media_url in image_like_urls or looks_like_image_media_url(media_url):
                            append_volcengine_image(media_url, "reference_image" if payload.multimodal else "first_frame")
                            continue
                        # 视频 URL 必须公网可访问（data: URL 不适用于视频，火山要求 https:// URL）
                        if not media_url.startswith(("http://", "https://")):
                            # 本地素材公网化：云上传（Litterbox/temp.sh，72h 短链）优先——公网直链稳定、
                            # 火山可访问；PUBLIC_MEDIA_BASE_URL 隧道直链仅作兜底（免费隧道易失效）。
                            public_url = ""
                            try:
                                uploaded = await upload_local_video_to_cloud(text_url)
                                public_url = str((uploaded or {}).get("url") or "")
                            except Exception as e:
                                print(f"火山视频上传云失败，尝试隧道直链: {e}")
                            if not public_url:
                                public_url = local_asset_public_url(text_url)
                            if public_url and public_url.startswith(("http://", "https://")):
                                media_url = public_url
                            else:
                                raise HTTPException(
                                    status_code=400,
                                    detail=f"视频必须可通过公网 URL 访问（火山引擎限制）。请确保视频可被云上传服务处理。当前视频: {text_url[:80]}"
                                )
                        # 视频编辑/局部替换：目标视频 role 用 reference_video（火山要求），
                        # 编辑目标判定已在上方时长校验处提前算好（时长截取也在公网化前完成）。
                        as_target = is_edit_target
                        video_items = await volcengine_video_reference_content_items(media_url, as_target=as_target)
                        body["content"].extend(video_items)
                        volc_video_count += 1
                    if any(item.get("type") == "video_url" for item in body["content"]):
                        # Seedance 视频编辑任务（提交了真实参考视频）：输出比例和时长必须跟随输入视频，
                        # 接口强制要求 ratio=adaptive、duration=-1，否则报参数不合法。
                        body["ratio"] = "adaptive"
                        body["duration"] = -1
                    for url in (payload.audios or [])[:3]:
                        duration = probe_local_audio_duration_seconds(url)
                        if duration is not None and (duration < 1.8 or duration > 15.2):
                            raise HTTPException(
                                status_code=400,
                                detail=f"参考音频时长 {duration:.2f} 秒超出范围：方舟 Seedance 参考音频要求在 1.8 ~ 15.2 秒之间，请裁剪后再插入。"
                            )
                        audio_url = await volcengine_audio_reference_url(url, max_image_size=None)
                        if not audio_url:
                            continue
                        body["content"].append({
                            "type": "audio_url",
                            "audio_url": {"url": audio_url},
                            "role": volcengine_content_role("", "audio"),
                        })
                    if payload.trusted_asset and body["content"] and body["content"][0].get("type") == "text":
                        body["content"][0]["text"] = apply_trusted_asset_prompt_index(
                            body["content"][0].get("text") or "", len(image_like_urls), volc_video_count, 0
                        )
                    if payload.seed is not None:
                        body["seed"] = payload.seed
                elif is_yuli:
                    # 玉玉API（yuli.host）视频走自有 veo 统一格式：POST /v1/video/create。
                    # 字段：model / prompt / images[]（http(s) URL）/ enhance_prompt /
                    # enable_upsample / aspect_ratio（仅 16:9、9:16）。无 duration 字段，
                    # 时长由模型本身决定，所以这里不传 duration/seconds。
                    yuli_images = []
                    for ref in payload.images[:3]:
                        ref_url = str(getattr(ref, "url", "") or "").strip()
                        if not ref_url:
                            continue
                        if ref_url.startswith("http://") or ref_url.startswith("https://"):
                            yuli_images.append(ref_url)
                        else:
                            # 本地/dataURL 图片转成 data URL 兜底传递
                            data_url = reference_to_data_url(ref.dict(), max_size=1536)
                            if data_url:
                                yuli_images.append(data_url)
                    prompt_text = str(payload.prompt or "")
                    # veo 只支持英文提示词：仅在含中文等非 ASCII 字符时才开启翻译增强，
                    # 纯英文原样传递（避免增强改写时引入人物等触发安全过滤的描述）。
                    needs_enhance = any(ord(ch) > 127 for ch in prompt_text)
                    body = {
                        "model": selected_model(payload.model, "veo3.1-fast"),
                        "prompt": prompt_text,
                        "enhance_prompt": needs_enhance,
                    }
                    if yuli_images:
                        body["images"] = yuli_images
                    ratio = str(payload.aspect_ratio or "").strip()
                    if ratio in {"16:9", "9:16"}:
                        body["aspect_ratio"] = ratio
                    if payload.enable_upsample:
                        body["enable_upsample"] = True
                else:
                    image_payload = []
                    for ref in payload.images[:4]:
                        if ref.url:
                            image_payload.append(reference_to_data_url(ref.dict(), max_size=1536))
                    body = {
                        "prompt": payload.prompt,
                        "model": selected_model(payload.model, "veo3-fast"),
                        "duration": payload.duration,
                        "watermark": payload.watermark,
                    }
                    if payload.aspect_ratio:
                        body["aspect_ratio"] = payload.aspect_ratio
                        body["ratio"] = payload.aspect_ratio
                    if payload.size:
                        body["size"] = payload.size
                    if payload.resolution:
                        body["resolution"] = legacy_video_resolution(payload.resolution)
                    if image_payload:
                        body["images"] = image_payload
                    if payload.videos:
                        body["videos"] = [v.get("url") if isinstance(v, dict) else v for v in payload.videos if v]
                    if payload.enhance_prompt:
                        body["enhance_prompt"] = True
                    if payload.enable_upsample:
                        body["enable_upsample"] = True
                    if payload.seed is not None:
                        body["seed"] = payload.seed
                    if payload.camerafixed:
                        body["camerafixed"] = True
                    if payload.return_last_frame:
                        body["return_last_frame"] = True
                    if payload.generate_audio:
                        body["generate_audio"] = True
            # --- 发起视频生成请求 ---
            raw = None
            html_response = None
            last_response = None
            last_json_error = None
            total_candidates = len(submit_urls)
            duration_retried = False
            for idx, candidate_url in enumerate(submit_urls):
                submit_url = candidate_url
                is_last = idx == total_candidates - 1
                response = await client.post(submit_url, headers=api_headers(provider=provider), json=body)
                last_response = response
                # 上游时长区间可能比本地能力表更严；图片已经上传好，复用同一个 body 重试一次不会重复上传或重复建视频
                if (is_apimart and not duration_retried and response.status_code == 400
                        and apimart_video_duration_retry_body(body, response.text)):
                    duration_retried = True
                    response = await client.post(submit_url, headers=api_headers(provider=provider), json=body)
                    last_response = response
                if response.status_code >= 400:
                    # 404/405（或直接返回网页 HTML）通常表示该平台不支持这个端点路径——
                    # 例如有的站点只实现了统一格式的 /v2/videos/generations，而我们先试了 /v1。
                    # 这种情况要继续尝试下一个候选端点（关键修复：以前在这里直接 raise_for_status，
                    # 第一个 /v1 报错就抛出，永远轮不到 /v2，表现为“接口错误”）。
                    # 其它错误（模型不支持/时长/额度等请求被拒）说明端点是存在的，直接抛出交给外层友好提示。
                    endpoint_missing = response.status_code in (404, 405) or looks_like_html_response(response.text)
                    if endpoint_missing and not is_last:
                        continue
                    response.raise_for_status()
                try:
                    raw = response.json()
                    break
                except Exception as exc:
                    last_json_error = exc
                    if looks_like_html_response(response.text):
                        html_response = response
                        continue
                    if not is_last:
                        continue
                    resp_text = response.text[:500]
                    raise HTTPException(status_code=502, detail=f"上游视频接口返回非 JSON 响应（状态 {response.status_code}）：{resp_text}")
            if raw is None:
                resp = html_response or last_response
                status_code = getattr(resp, "status_code", 200)
                resp_text = (getattr(resp, "text", "") or "")[:500]
                raise HTTPException(
                    status_code=502,
                    detail=(
                        f"上游视频接口返回了网页 HTML，而不是 JSON（状态 {status_code}）。\n\n"
                        f"这通常表示 API 设置里的 Base URL 指到了第三方聚合平台的管理后台/网页入口，"
                        f"或该平台不支持当前视频接口路径。请确认 Base URL 是接口地址，例如以 /v1 结尾的 OpenAI 兼容地址，"
                        f"并确认该平台实际支持视频生成端点。\n\n原始响应：{resp_text}"
                    )
                ) from last_json_error
            task_id = extract_task_id(raw) or raw.get("task_id") or raw.get("id")
            result = raw
            if task_id and not video_output_urls(raw):
                result = await wait_for_video_task(client, provider, task_id, submit_url)
            urls = video_output_urls(result)
            if not urls:
                raise HTTPException(status_code=502, detail=f"视频生成成功但没有返回视频：{result}")
            local_urls = [await save_remote_video_to_output(url) for url in urls]
            return {**{"videos": local_urls, "task_id": task_id, "raw": result}, **build_canvas_meta(local_urls, payload, "video")}
    except httpx.HTTPStatusError as exc:
        text = exc.response.text
        try:
            requested_model = body.get("model", "") or payload.model or ""
        except NameError:
            requested_model = payload.model or ""
        provider_name = provider.get('name') or provider['id']
        # 1) 模型名不在上游支持范围 → 从错误信息里抽取合法列表展示
        valid_models_match = re.search(r"not in\s*\[([^\]]+)\]", text)
        if valid_models_match:
            valid_models = [m.strip() for m in valid_models_match.group(1).split(",") if m.strip()]
            sample = valid_models[:30]
            more = f"（共 {len(valid_models)} 个，仅显示前 {len(sample)} 个）" if len(valid_models) > len(sample) else ""
            hint = (
                f"上游「{provider_name}」不识别模型「{requested_model}」。\n\n"
                f"上游支持的视频模型清单{more}：\n  {', '.join(sample)}\n\n"
                f"请到「API 设置」里把视频模型改成上面列表中的一个。"
            )
            raise HTTPException(status_code=exc.response.status_code, detail=hint) from exc
        # 2) 模型名合法但账号没开通通道
        if "channel not found" in text or "model_not_found" in text:
            hint = (
                f"上游「{provider_name}」识别了模型「{requested_model}」，但你的 API Key 账号下**没有该模型的可用通道**。\n\n"
                f"原因：你的账号没开通这个模型的访问权限（付费/订阅相关）。\n\n"
                f"解决方法：\n"
                f"  1. 登录 {provider.get('base_url') or '上游平台'} 控制台，开通该模型 / 充值；\n"
                f"  2. 或在「API 设置」里把视频模型改成你账号已开通的型号（如 veo3-fast / veo2-fast / sora-2 等）。"
            )
            raise HTTPException(status_code=exc.response.status_code, detail=hint) from exc
        if "text.duration" in text or "specified duration is not supported" in text:
            hint = (
                f"上游「{provider_name}」模型「{requested_model}」不支持当前时长参数。\n\n"
                f"不同视频模型支持的时长不一样；如果选择了模型不支持的时长，上游可能报错，"
                f"也可能自动按平台默认时长生成，例如 5 秒。\n\n"
                f"请把视频时长切回该模型支持的值，或改用支持更长时长的视频模型。"
            )
            raise HTTPException(status_code=exc.response.status_code, detail=hint) from exc
        if "audio duration" in text.lower():
            too_long = "less than or equal" in text.lower() or "15.2" in text
            bound_hint = "太长（超过 15.2 秒）" if too_long else "太短（不足 1.8 秒）"
            hint = (
                f"上游「{provider_name}」模型「{requested_model}」拒绝了参考音频：时长{bound_hint}。\n\n"
                f"方舟 Seedance 的参考音频时长必须在 1.8 ~ 15.2 秒之间，"
                f"请把音频裁剪到这个区间后再作为参考音频输入。"
            )
            raise HTTPException(status_code=exc.response.status_code, detail=hint) from exc
        if "inputimagesensitivecontentdetected" in text.lower() or "privacyinformation" in text.lower() or "may contain real person" in text.lower():
            hint = (
                f"上游「{provider_name}」拦截了输入参考图，原因是图片里可能包含真人身份/隐私信息。\n\n"
                f"这不是代码协议错误，而是火山视频模型的内容安全策略。\n\n"
                f"建议你这样处理：\n"
                f"  1. 改用非真人参考图，例如插画、AI 头像、商品图、场景图；\n"
                f"  2. 先把真人脸做模糊、遮挡、裁掉，或转成明显的二次元/插画风；\n"
                f"  3. 如果只是想做文生视频，先去掉参考图只保留文字提示词测试。"
            )
            raise HTTPException(status_code=exc.response.status_code, detail=hint) from exc
        raise HTTPException(status_code=exc.response.status_code, detail=f"上游视频接口错误：{text}") from exc
    except httpx.HTTPError as exc:
        log_net_error(f"视频 网络/TLS错误 provider={provider.get('id')} model={payload.model}", exc)
        raise HTTPException(status_code=502, detail=f"请求上游视频接口失败：{exc}") from exc

# --- Canvas LLM ---

# —— Prompt Intelligence（v1）：独立模块，失败自动降级，绝不破坏原流程 ——
PromptIntelligence = None  # type: ignore[assignment]  # 下方 try 内真实导入
HAS_PROMPT_INTELLIGENCE = False
try:
    from prompt_intelligence import PromptIntelligence
    HAS_PROMPT_INTELLIGENCE = True
except Exception as _pi_import_err:
    print(f"[prompt-intelligence] module import failed, feature disabled: {_pi_import_err}")


async def _pi_llm_call(payload, message, system_prompt, images, videos):
    """Prompt Intelligence 内部 LLM 调用：与 /api/canvas-llm 使用同一 Provider 分支逻辑，
    保证普通画布/智能画布/Codex/Gemini CLI 行为一致。"""
    fake = SimpleNamespace(
        message=message,
        model=payload.model or "",
        ms_model=payload.ms_model or "",
        provider=payload.provider,
        system_prompt=system_prompt or "",
        messages=[],
        images=images or [],
        videos=videos or [],
        reference_images=[],
    )
    prov = get_api_provider(payload.provider)
    if is_codex_provider(prov):
        text, _raw = await codex_chat_text(fake, [])
        return text
    if is_gemini_cli_provider(prov):
        text, _raw = await gemini_cli_chat_text(fake, [])
        return text
    if is_lovart_provider(prov):
        text, _raw = await lovart_chat_text(fake, [])
        return text
    chat_base, chat_hdrs, mdl = resolve_chat_provider(payload.provider, payload.model, payload.ms_model)
    content_parts: list = [{"type": "text", "text": message}]
    for img in (images or [])[:8]:
        ref_url = media_reference_to_url(img, max_image_size=1024)
        if ref_url:
            content_parts.append({"type": "image_url", "image_url": {"url": ref_url}})
    for video in (videos or [])[:3]:
        frame_urls = await video_reference_to_frame_data_urls(video, max_frames=6, max_size=768)
        if frame_urls:
            content_parts.append({"type": "text", "text": "视频关键帧(按时间顺序):"})
            for frame_url in frame_urls:
                content_parts.append({"type": "image_url", "image_url": {"url": frame_url}})
        else:
            ref_url = media_reference_to_url(video)
            if ref_url:
                content_parts.append({"type": "video_url", "video_url": {"url": ref_url}})
    upstream_messages = [{"role": "system", "content": system_prompt}] if system_prompt else []
    upstream_messages.append({"role": "user", "content": content_parts})
    async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=AI_REQUEST_TIMEOUT) as client:
        response = await client.post(
            f"{chat_base}/chat/completions",
            headers=chat_hdrs,
            json={"model": mdl, "messages": upstream_messages},
        )
        response.raise_for_status()
        raw = response.json()
    return text_from_chat_response(raw) or ""


async def _run_prompt_intelligence(payload):
    """Prompt Intelligence 调度入口：任何异常都返回 None（走原流程）。"""
    if not HAS_PROMPT_INTELLIGENCE:
        return None
    images = [img for img in (payload.images or []) if is_image_reference_value(img)]
    videos = [v for v in (payload.videos or []) if is_video_reference_value(v)]
    pi = PromptIntelligence(  # type: ignore[call-overload]  # HAS_PROMPT_INTELLIGENCE 已保证非 None
        llm_call=lambda text, sys_p, imgs, vids: _pi_llm_call(payload, text, sys_p, imgs, vids),
        message=payload.message,
        images=images,
        videos=videos,
        reverse=bool(getattr(payload, "reverse", False)),
        target_type=str(getattr(payload, "target_type", "") or ""),
        target_model=str(getattr(payload, "target_model", "") or ""),
        provider=payload.provider,
        model=payload.model,
    )
    pi.video_frames_cb = lambda vid: video_reference_to_frame_data_urls(vid, max_frames=6, max_size=768)
    return await pi.run()


def apimart_chat_request_bytes(body):
    return len(json.dumps(body, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))


def fit_apimart_chat_request_to_gateway(body):
    """文本生成的图片与视频抽帧也算入 APIMart 的 1MB JSON 限制，发送前整体逐级压缩。"""
    parts = []
    for message in body.get("messages") or []:
        content = message.get("content") if isinstance(message, dict) else None
        if not isinstance(content, list):
            continue
        for part in content:
            if not isinstance(part, dict) or part.get("type") != "image_url":
                continue
            image_url = part.get("image_url")
            url = str(image_url.get("url") or "") if isinstance(image_url, dict) else ""
            if url.startswith("data:image/") and ";base64," in url:
                parts.append(part)
    total = apimart_chat_request_bytes(body)
    if total <= APIMART_JSON_BODY_BUDGET:
        return body
    originals = [str(part["image_url"].get("url") or "") for part in parts]
    for max_size, quality in apimart_fallback_compression_ladder(len(parts)):
        for part, source in zip(parts, originals):
            compressed = apimart_data_url_to_jpeg(source, max_size=max_size, quality=quality)
            part["image_url"]["url"] = compressed or source
        total = apimart_chat_request_bytes(body)
        if total <= APIMART_JSON_BODY_BUDGET:
            print(
                f"[canvas-llm] APIMart 聊天参考素材压缩：{len(parts)} 张，"
                f"max_size={max_size} quality={quality}，请求体 {total} 字节"
            )
            return body
    raise HTTPException(
        status_code=413,
        detail="参考图片或视频帧压缩后，文本生成请求仍超过上游 1MB 限制，请减少参考素材后重试。",
    )


async def _canvas_llm_upstream_messages(payload, model):
    """把 /api/canvas-llm 的 system + 历史 + 多模态 user 消息拼出来。
    普通（非流式）和流式两个入口共用，保证两条路发出去的内容一字不差。"""
    system_prompt = (payload.system_prompt or "").strip()
    upstream_messages = [{"role": "system", "content": system_prompt}] if system_prompt else []
    for item in payload.messages[-MAX_HISTORY_MESSAGES:]:
        role = item.get("role")
        content = item.get("content")
        if role in {"user", "assistant"} and content:
            upstream_messages.append({"role": role, "content": content})
    image_inputs = [img for img in (payload.images or []) if is_image_reference_value(img)]
    video_inputs = [video for video in (payload.videos or []) if is_video_reference_value(video)]
    if image_inputs or video_inputs:
        content_parts = [{"type": "text", "text": payload.message}]
        ok_imgs = 0
        for img in image_inputs[:8]:
            if not img or not isinstance(img, str):
                continue
            ref_url = media_reference_to_url(img, max_image_size=1024)
            if not ref_url:
                continue
            content_parts.append({"type": "image_url", "image_url": {"url": ref_url}})
            ok_imgs += 1
        ok_videos = 0
        for video in video_inputs[:3]:
            if not video or not isinstance(video, str):
                continue
            frame_urls = await video_reference_to_frame_data_urls(video, max_frames=6, max_size=768)
            if frame_urls:
                ok_videos += 1
                content_parts.append({"type": "text", "text": f"以下是视频 {ok_videos} 按时间顺序抽取的关键帧，请结合这些画面理解视频内容。"})
                for frame_url in frame_urls:
                    content_parts.append({"type": "image_url", "image_url": {"url": frame_url}})
            else:
                ref_url = media_reference_to_url(video)
                if not ref_url:
                    continue
                content_parts.append({"type": "video_url", "video_url": {"url": ref_url}})
                ok_videos += 1
        print(f"[canvas-llm] model={model} provider={payload.provider} text_len={len(payload.message)} images={ok_imgs}/{len(payload.images)} videos={ok_videos}/{len(payload.videos)}")
        upstream_messages.append({"role": "user", "content": content_parts})
    else:
        upstream_messages.append({"role": "user", "content": payload.message})
    return upstream_messages


async def _canvas_llm_apply_prompt_intelligence(payload):
    """Prompt Intelligence 前置分析（失败自动回退原 message）。两个入口共用。

    反推（reverse）**不跑 PI**：反推本质就是「看一眼图，把提示词写出来」——一次带图调用就够，
    再套意图判断/审计/编译那 4~5 步，只会把「点一下」拖成几分钟（Lovart 这类 agent 供应商更夸张）。
    开源同类（Naizei 的「反推提示词」节点、ComfyUI 的 LLM 节点）也都是一次调用。"""
    if payload.reverse:
        print("[prompt-intelligence] skipped: reverse uses a single multimodal call")
        return payload
    if HAS_PROMPT_INTELLIGENCE and not payload.no_prompt_intelligence and (payload.images or payload.videos):
        try:
            _pi_result = await _run_prompt_intelligence(payload)
            if _pi_result and _pi_result.get("ok") and _pi_result.get("final_prompt"):
                payload.message = _pi_result["final_prompt"]
                print(
                    f"[prompt-intelligence] applied reverse={payload.reverse} "
                    f"steps={_pi_result.get('steps_used')} compiler={_pi_result.get('compiler')}"
                )
            elif _pi_result and not _pi_result.get("ok"):
                print(f"[prompt-intelligence] skipped: {_pi_result.get('reason')}")
        except Exception as exc:
            print(f"[prompt-intelligence] dispatch failed, fallback to original flow: {exc}")
    return payload


async def _canvas_llm_impl(payload: CanvasLLMRequest):
    _provider = get_api_provider(payload.provider)
    # —— Prompt Intelligence（v1）：有参考素材或反推 ON 时启用；失败自动回退原流程 ——
    await _canvas_llm_apply_prompt_intelligence(payload)
    if is_codex_provider(_provider):
        model = selected_model(payload.model, (_provider.get("chat_models") or CODEX_DEFAULT_CHAT_MODELS)[0])
        payload.model = model
        text, raw = await codex_chat_text(payload, payload.messages)
        return {"text": text, "model": model, "raw_usage": None, "raw": raw}
    if is_gemini_cli_provider(_provider):
        model = selected_model(payload.model, (_provider.get("chat_models") or GEMINI_CLI_DEFAULT_CHAT_MODELS)[0])
        payload.model = model
        text, raw = await gemini_cli_chat_text(payload, payload.messages)
        return {"text": text, "model": model, "raw_usage": None, "raw": raw}
    if is_lovart_provider(_provider):
        model = selected_model(payload.model, (_provider.get("chat_models") or LOVART_DEFAULT_CHAT_MODELS)[0])
        payload.model = model
        text, raw = await lovart_chat_text(payload, payload.messages)
        return {"text": text, "model": model, "raw_usage": None, "raw": raw}
    chat_base, chat_hdrs, model = resolve_chat_provider(payload.provider, payload.model, payload.ms_model)
    # 判断协议：APIMart 异步 vs 标准 OpenAI
    _llm_provider = get_api_provider(payload.provider) if payload.provider not in ("modelscope",) else {}
    _is_apimart = is_apimart_provider(_llm_provider)
    upstream_messages = await _canvas_llm_upstream_messages(payload, model)
    raw = None
    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=AI_REQUEST_TIMEOUT) as client:
            req_body = {"model": model, "messages": upstream_messages}
            if int(payload.max_tokens or 0) > 0:
                req_body["max_tokens"] = int(payload.max_tokens)
            think_fields = chat_think_fields(_llm_provider, model, payload.think_level)
            if think_fields:
                req_body.update(think_fields)
            if _is_apimart:
                req_body["stream"] = False   # APIMart 默认流式，强制关闭
                fit_apimart_chat_request_to_gateway(req_body)
            response = await post_chat_with_think(
                client,
                f"{chat_base}/chat/completions",
                chat_hdrs,
                req_body,
                think_fields,
            )
            response.raise_for_status()
            if not response.content:
                raise HTTPException(status_code=502, detail="上游接口返回了空响应")
            raw = response.json()
    except httpx.HTTPStatusError as exc:
        body = exc.response.text or ""
        friendly = friendly_chat_error_detail(body, model, _llm_provider)
        raise HTTPException(status_code=exc.response.status_code, detail=friendly or f"上游接口错误：{body}") from exc
    except httpx.HTTPError as exc:
        raise HTTPException(status_code=502, detail=f"请求上游接口失败：{exc}") from exc
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"解析上游响应失败：{exc}") from exc
    try:
        text = text_from_chat_response(raw).strip() if isinstance(raw, dict) else ""
        text = text or "接口返回了空回复。"
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"解析回复内容失败：{exc}") from exc
    raw_data = unwrap_apimart_response(raw) if isinstance(raw, dict) else {}
    return {"text": text, "model": model, "raw_usage": raw_data.get("usage")}


@app.post("/api/canvas-llm")
async def canvas_llm(payload: CanvasLLMRequest):
    payload.provider = member_provider(payload.provider)
    model = _credits_llm_model(payload)
    charge = credits_charge_start("text", model, _credits_llm_params(payload),
                                 provider=payload.provider)
    try:
        result = await _canvas_llm_impl(payload)
    except Exception:
        credits_charge_refund(charge, "llm_failed")
        raise
    settled = credits_charge_settle(charge, result=result)
    return credits_attach(result, settled)


async def _canvas_llm_stream_impl(payload: CanvasLLMRequest, charge=None):
    """流式版 /api/canvas-llm：token 一到就往前端推（SSE），节点上边生成边显示。
    支持标准 OpenAI 兼容供应商与 APIMart；codex / gemini-cli / lovart 这些 agent 型供应商
    直接回 409，前端退回普通接口（行为与之前一致）。

    积分结算放在这个单层 generator 自己的 finally 里，不再套一层 "async for body_iterator"
    的包装 generator —— 嵌套 async generator 在客户端断开时会被层层 throw/close，极端情况下
    触发递归 finalize 把事件循环卡死。"""
    _provider = get_api_provider(payload.provider)
    if is_codex_provider(_provider) or is_gemini_cli_provider(_provider) or is_lovart_provider(_provider):
        raise HTTPException(status_code=409, detail="stream_unsupported")
    await _canvas_llm_apply_prompt_intelligence(payload)
    chat_base, chat_hdrs, model = resolve_chat_provider(payload.provider, payload.model, payload.ms_model)
    _llm_provider = get_api_provider(payload.provider) if payload.provider not in ("modelscope",) else {}
    upstream_messages = await _canvas_llm_upstream_messages(payload, model)

    async def stream():
        failed = False
        completed = False
        try:
            yield sse_event({"type": "meta", "model": model, "provider": payload.provider})
            parts = []
            async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=AI_REQUEST_TIMEOUT) as client:
                req_body = {"model": model, "messages": upstream_messages, "stream": True}
                if int(payload.max_tokens or 0) > 0:
                    req_body["max_tokens"] = int(payload.max_tokens)
                think_fields = chat_think_fields(_llm_provider, model, payload.think_level)
                req_body.update(think_fields)
                if is_apimart_provider(_llm_provider):
                    fit_apimart_chat_request_to_gateway(req_body)
                async with chat_stream_with_think(client, f"{chat_base}/chat/completions", chat_hdrs, req_body, think_fields) as (response, _sent_body):
                    if response.status_code >= 400:
                        body = (await response.aread()).decode("utf-8", errors="ignore")
                        friendly = friendly_chat_error_detail(body, model, _llm_provider)
                        failed = True
                        yield sse_event({"type": "error", "detail": friendly or f"上游接口错误：{body}"})
                        return
                    # 有些供应商/模型不吃 stream=true，直接回一整块 JSON：
                    # 那就一次性当 delta 推下去 —— 否则前端要等到 idle 超时才报错。
                    content_type = (response.headers.get("content-type") or "").lower()
                    if "text/event-stream" not in content_type:
                        raw_body = (await response.aread()).decode("utf-8", errors="ignore")
                        try:
                            whole = json.loads(raw_body) if raw_body.strip() else {}
                        except json.JSONDecodeError:
                            whole = {}
                        whole_text = text_from_chat_response(whole).strip() if isinstance(whole, dict) else ""
                        if not whole_text:
                            failed = True
                            yield sse_event({"type": "error", "detail": "上游没有按流式返回，整块补全也是空的。"})
                            return
                        parts.append(whole_text)
                        yield sse_event({"type": "delta", "delta": whole_text})
                        completed = True
                        yield sse_event({"type": "done", "text": "".join(parts).strip(), "model": model})
                        return
                    async for line in response.aiter_lines():
                        line = (line or "").strip()
                        if not line:
                            continue
                        if line.startswith("data:"):
                            line = line[5:].strip()
                        if line == "[DONE]":
                            break
                        try:
                            chunk = json.loads(line)
                        except json.JSONDecodeError:
                            continue
                        # 思考型模型（gpt-5.5 / o 系列）前几十秒只在 reasoning 里吐字：
                        # 也要往下推，否则前端 idle 等到发呆（用户看到的「120 秒没有新内容」就是这么来的）。
                        reasoning_delta = reasoning_delta_from_chat_chunk(chunk) if isinstance(chunk, dict) else ""
                        if reasoning_delta:
                            yield sse_event({"type": "reasoning", "delta": reasoning_delta})
                        delta = text_delta_from_chat_chunk(chunk) if isinstance(chunk, dict) else ""
                        if delta:
                            parts.append(delta)
                            yield sse_event({"type": "delta", "delta": delta})
            completed = True
            text = "".join(parts).strip() or "接口返回了空回复。"
            yield sse_event({"type": "done", "text": text, "model": model})
        except httpx.HTTPError as exc:
            log_net_error("画布LLM(流式) 网络/TLS错误", exc)
            failed = True
            yield sse_event({"type": "error", "detail": f"请求上游接口失败：{exc}"})
        finally:
            if charge:
                if failed or not completed:
                    credits_charge_refund(charge, "llm_stream_interrupted" if not failed else "llm_stream_failed")
                else:
                    credits_charge_settle(charge, result=None)

    return StreamingResponse(stream(), media_type="text/event-stream", headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"})


@app.post("/api/canvas-llm/stream")
async def canvas_llm_stream(payload: CanvasLLMRequest):
    payload.provider = member_provider(payload.provider)
    """流式入口：预扣积分；结算/退款在 _canvas_llm_stream_impl 的单层 generator 里完成。"""
    model = _credits_llm_model(payload)
    charge = credits_charge_start("text", model, _credits_llm_params(payload),
                                 provider=payload.provider)
    try:
        return await _canvas_llm_stream_impl(payload, charge=charge)
    except Exception:
        credits_charge_refund(charge, "llm_stream_rejected")
        raise


