@app.post("/api/chat")
async def chat(payload: ChatRequest, request: Request, x_user_id: str = Header(default="")):
    payload.provider = member_provider(payload.provider)
    payload.image_provider = member_provider(payload.image_provider)
    user_id = safe_user_id(x_user_id, request)
    conversation = (
        load_conversation(user_id, payload.conversation_id)
        if payload.conversation_id
        else new_conversation(user_id, display_title(payload.message))
    )
    if not conversation.get("messages"):
        conversation["title"] = display_title(payload.message)

    refs = [ref.dict() for ref in payload.reference_images if ref.url]
    image_refs = image_references(refs)
    user_message = {
        "id": uuid.uuid4().hex,
        "role": "user",
        "content": payload.message,
        "created_at": now_ms(),
        "attachments": refs,
        "mode": payload.mode,
    }
    if payload.capability:
        user_message["capability"] = dict(payload.capability)
    conversation["messages"].append(user_message)
    conversation["updated_at"] = now_ms()
    save_conversation(user_id, conversation)

    if payload.mode == "image":
        image_provider_id = payload.provider if payload.provider not in {"modelscope"} else "comfly"
        provider = get_api_provider(image_provider_id)
        model = preferred_image_model(provider, payload.image_model or payload.model)
        image_size = chat_prompt_size_override(payload.message, payload.size) or payload.size
        try:
            image_data, raw = await generate_ai_image(payload.message, image_size, payload.quality, model, image_refs, provider["id"])
            local_url = await save_ai_image_to_output(image_data, prefix="chat_")
        except httpx.HTTPStatusError as exc:
            text = exc.response.text or ""
            detail = friendly_image_error_detail(text, image_size, model) or f"上游生图接口错误：{text[:300]}"
            raise HTTPException(status_code=exc.response.status_code, detail=detail) from exc
        except httpx.HTTPError as exc:
            log_net_error(f"对话生图 网络/TLS错误 model={model}", exc)
            raise HTTPException(status_code=502, detail=f"请求上游生图接口失败：{http_error_detail(exc)}") from exc
        assistant_message = {
            "id": uuid.uuid4().hex,
            "role": "assistant",
            "type": "image",
            "content": payload.message,
            "image_url": local_url,
            "created_at": now_ms(),
            "model": model,
            "size": image_size,
            "raw_usage": raw.get("usage") if isinstance(raw, dict) else None,
        }
    else:
        _codex_provider = get_api_provider(payload.provider)
        if is_codex_provider(_codex_provider):
            model = selected_model(payload.model, (_codex_provider.get("chat_models") or CODEX_DEFAULT_CHAT_MODELS)[0])
            payload.model = model
            text, raw = await codex_chat_text(payload, conversation["messages"][-MAX_HISTORY_MESSAGES:])
            assistant_message = {
                "id": uuid.uuid4().hex,
                "role": "assistant",
                "content": text,
                "created_at": now_ms(),
                "model": model,
                "raw_usage": None,
                "raw": raw,
            }
            conversation["messages"].append(assistant_message)
            conversation["updated_at"] = now_ms()
            save_conversation(user_id, conversation)
            return {"conversation": conversation, "message": assistant_message}
        if is_gemini_cli_provider(_codex_provider):
            model = selected_model(payload.model, (_codex_provider.get("chat_models") or GEMINI_CLI_DEFAULT_CHAT_MODELS)[0])
            payload.model = model
            text, raw = await gemini_cli_chat_text(payload, conversation["messages"][-MAX_HISTORY_MESSAGES:])
            assistant_message = {
                "id": uuid.uuid4().hex,
                "role": "assistant",
                "content": text,
                "created_at": now_ms(),
                "model": model,
                "raw_usage": None,
                "raw": raw,
            }
            conversation["messages"].append(assistant_message)
            conversation["updated_at"] = now_ms()
            save_conversation(user_id, conversation)
            return {"conversation": conversation, "message": assistant_message}
        if is_lovart_provider(_codex_provider):
            model = selected_model(payload.model, (_codex_provider.get("chat_models") or LOVART_DEFAULT_CHAT_MODELS)[0])
            payload.model = model
            text, raw = await lovart_chat_text(payload, conversation["messages"][-MAX_HISTORY_MESSAGES:])
            assistant_message = {
                "id": uuid.uuid4().hex,
                "role": "assistant",
                "content": text,
                "created_at": now_ms(),
                "model": model,
                "raw_usage": None,
                "raw": raw,
            }
            conversation["messages"].append(assistant_message)
            conversation["updated_at"] = now_ms()
            save_conversation(user_id, conversation)
            return {"conversation": conversation, "message": assistant_message}
        chat_base, chat_hdrs, model = resolve_chat_provider(payload.provider, payload.model, payload.ms_model)
        _conv_provider = get_api_provider(payload.provider) if payload.provider not in ("modelscope",) else {}
        _conv_is_apimart = is_apimart_provider(_conv_provider)
        history = conversation["messages"][-MAX_HISTORY_MESSAGES:]
        upstream_messages = [{"role": "system", "content": chat_system_prompt(payload)}]
        for item in history:
            msg = upstream_message_from_record(item)
            if msg:
                upstream_messages.append(msg)
        try:
            async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=AI_REQUEST_TIMEOUT) as client:
                conv_req_body = {"model": model, "messages": upstream_messages}
                conv_think_fields = chat_think_fields(_conv_provider, model, payload.think_level)
                conv_req_body.update(conv_think_fields)
                if _conv_is_apimart:
                    conv_req_body["stream"] = False
                response = await post_chat_with_think(
                    client,
                    f"{chat_base}/chat/completions",
                    chat_hdrs,
                    conv_req_body,
                    conv_think_fields,
                )
                response.raise_for_status()
                raw = response.json()
        except httpx.HTTPStatusError as exc:
            body = exc.response.text or ""
            friendly = friendly_chat_error_detail(body, model, _conv_provider)
            raise HTTPException(status_code=exc.response.status_code, detail=friendly or f"上游接口错误：{body}") from exc
        except httpx.HTTPError as exc:
            raise HTTPException(status_code=502, detail=f"请求上游接口失败：{exc}") from exc
        raw_data = unwrap_apimart_response(raw) if isinstance(raw, dict) else raw
        assistant_message = {
            "id": uuid.uuid4().hex,
            "role": "assistant",
            "content": text_from_chat_response(raw).strip() or "接口返回了空回复。",
            "created_at": now_ms(),
            "model": model,
            "raw_usage": raw_data.get("usage") if isinstance(raw_data, dict) else None,
        }
        reasoning_text = reasoning_from_chat_response(raw).strip()
        if reasoning_text:
            assistant_message["reasoning"] = reasoning_text

    conversation["messages"].append(assistant_message)
    conversation["updated_at"] = now_ms()
    save_conversation(user_id, conversation)
    return {"conversation": conversation, "message": assistant_message}

@app.post("/api/chat/agent")
async def chat_agent(payload: ChatRequest, request: Request, x_user_id: str = Header(default="")):
    payload.provider = member_provider(payload.provider)
    payload.image_provider = member_provider(payload.image_provider)
    user_id = safe_user_id(x_user_id, request)
    conversation = (
        load_conversation(user_id, payload.conversation_id)
        if payload.conversation_id
        else new_conversation(user_id, display_title(payload.message))
    )
    if not conversation.get("messages"):
        conversation["title"] = display_title(payload.message)

    refs = [ref.dict() for ref in payload.reference_images if ref.url]
    image_refs = image_references(refs)
    user_message = {
        "id": uuid.uuid4().hex,
        "role": "user",
        "content": payload.message,
        "created_at": now_ms(),
        "attachments": refs,
        "mode": "agent",
    }
    conversation["messages"].append(user_message)
    conversation["updated_at"] = now_ms()
    save_conversation(user_id, conversation)

    decision = await decide_chat_agent_action(payload, conversation, image_refs)
    action = decision.get("action") or "chat"
    tool_refs = image_refs[:]
    inherited_size = ""
    if action == "edit_image" and not tool_refs:
        tool_refs = latest_chat_image_refs(conversation, 1)
        inherited_size = image_size_from_reference(tool_refs[0]) if tool_refs else ""
    if action == "edit_image" and not tool_refs:
        action = "generate_image"

    if action in {"generate_image", "edit_image"}:
        image_provider = pick_chat_image_provider(payload.image_provider or payload.provider, payload.provider)
        model = preferred_image_model(image_provider, payload.image_model)
        prompt = decision.get("prompt") or payload.message
        prompt_size = chat_prompt_size_override(payload.message, payload.size) or chat_prompt_size_override(prompt, payload.size)
        image_size = agent_image_size(image_provider, model, prompt_size or inherited_size or payload.size, "")
        requested_count = 1 if action == "edit_image" else chat_requested_image_count(payload.message)
        prompts = chat_split_parallel_prompts(prompt, requested_count)
        local_urls = []
        raw_items = []
        try:
            for item_prompt in prompts:
                image_data, raw = await generate_ai_image(item_prompt, image_size, payload.quality, model, tool_refs, image_provider["id"])
                local_urls.append(await save_ai_image_to_output(image_data, prefix="chat_"))
                raw_items.append(raw)
        except httpx.HTTPStatusError as exc:
            text = exc.response.text or ""
            detail = friendly_image_error_detail(text, image_size, model) or f"上游生图接口错误：{text[:300]}"
            raise HTTPException(status_code=exc.response.status_code, detail=detail) from exc
        except httpx.HTTPError as exc:
            log_net_error(f"对话生图 网络/TLS错误 model={model}", exc)
            raise HTTPException(status_code=502, detail=f"请求上游生图接口失败：{http_error_detail(exc)}") from exc
        local_url = local_urls[0] if local_urls else ""
        assistant_message = {
            "id": uuid.uuid4().hex,
            "role": "assistant",
            "type": "image",
            "content": prompt,
            "image_url": local_url,
            "image_urls": local_urls,
            "created_at": now_ms(),
            "model": model,
            "provider": image_provider["id"],
            "size": image_size,
            "image_count": len(local_urls),
            "prompts": prompts,
            "agent_action": action,
            "agent_reply": decision.get("reply") or "",
            "used_references": tool_refs,
            "raw_usage": raw_items[0].get("usage") if raw_items and isinstance(raw_items[0], dict) else None,
        }
    else:
        assistant_message = await build_chat_text_reply(payload, conversation)
        assistant_message["agent_action"] = "chat"

    reasoning_text = str(decision.pop("reasoning", "") or "").strip()
    if reasoning_text and not assistant_message.get("reasoning"):
        assistant_message["reasoning"] = reasoning_text
    conversation["messages"].append(assistant_message)
    conversation["updated_at"] = now_ms()
    save_conversation(user_id, conversation)
    return {"conversation": conversation, "message": assistant_message, "agent": {"action": action, "decision": decision}}

@app.post("/api/chat/agent/stream")
async def chat_agent_stream(payload: ChatRequest, request: Request, x_user_id: str = Header(default="")):
    payload.provider = member_provider(payload.provider)
    payload.image_provider = member_provider(payload.image_provider)
    """agent 模式的流式版：决策阶段的 reasoning 实时转发、动作阶段发 status，落盘与 /api/chat/agent 一致。"""
    user_id = safe_user_id(x_user_id, request)
    started_at = time.monotonic()
    conversation = (
        load_conversation(user_id, payload.conversation_id)
        if payload.conversation_id
        else new_conversation(user_id, display_title(payload.message))
    )
    if not conversation.get("messages"):
        conversation["title"] = display_title(payload.message)

    refs = [ref.dict() for ref in payload.reference_images if ref.url]
    image_refs = image_references(refs)
    user_message = {
        "id": uuid.uuid4().hex,
        "role": "user",
        "content": payload.message,
        "created_at": now_ms(),
        "attachments": refs,
        "mode": "agent",
    }
    conversation["messages"].append(user_message)
    conversation["updated_at"] = now_ms()
    save_conversation(user_id, conversation)

    async def stream():
        yield sse_event({"type": "meta", "conversation": conversation})
        decision = {}
        try:
            async for event in stream_chat_agent_decision(payload, conversation, image_refs, decision):
                yield sse_event(event)
        except HTTPException as exc:
            yield sse_event({"type": "error", "detail": exc.detail})
            return
        except Exception as exc:
            yield sse_event({"type": "error", "detail": f"请求上游接口失败：{exc}"})
            return

        action = decision.get("action") or "chat"
        tool_refs = image_refs[:]
        inherited_size = ""
        if action == "edit_image" and not tool_refs:
            tool_refs = latest_chat_image_refs(conversation, 1)
            inherited_size = image_size_from_reference(tool_refs[0]) if tool_refs else ""
        if action == "edit_image" and not tool_refs:
            action = "generate_image"

        if action in {"generate_image", "edit_image"}:
            try:
                image_provider = pick_chat_image_provider(payload.image_provider or payload.provider, payload.provider)
                model = preferred_image_model(image_provider, payload.image_model)
            except HTTPException as exc:
                yield sse_event({"type": "error", "detail": exc.detail})
                return
            prompt = decision.get("prompt") or payload.message
            prompt_size = chat_prompt_size_override(payload.message, payload.size) or chat_prompt_size_override(prompt, payload.size)
            image_size = agent_image_size(image_provider, model, prompt_size or inherited_size or payload.size, "")
            requested_count = 1 if action == "edit_image" else chat_requested_image_count(payload.message)
            prompts = chat_split_parallel_prompts(prompt, requested_count)
            yield sse_event({"type": "status", "detail": "正在修改图片…" if action == "edit_image" else "正在生成图片…"})
            local_urls = []
            raw_items = []
            try:
                for item_prompt in prompts:
                    image_data, raw = await generate_ai_image(item_prompt, image_size, payload.quality, model, tool_refs, image_provider["id"])
                    local_urls.append(await save_ai_image_to_output(image_data, prefix="chat_"))
                    raw_items.append(raw)
            except httpx.HTTPStatusError as exc:
                text = exc.response.text or ""
                detail = friendly_image_error_detail(text, image_size, model) or f"上游生图接口错误：{text[:300]}"
                yield sse_event({"type": "error", "detail": detail})
                return
            except httpx.HTTPError as exc:
                log_net_error(f"对话生图 网络/TLS错误 model={model}", exc)
                yield sse_event({"type": "error", "detail": f"请求上游生图接口失败：{http_error_detail(exc)}"})
                return
            local_url = local_urls[0] if local_urls else ""
            assistant_message = {
                "id": uuid.uuid4().hex,
                "role": "assistant",
                "type": "image",
                "content": prompt,
                "image_url": local_url,
                "image_urls": local_urls,
                "created_at": now_ms(),
                "model": model,
                "provider": image_provider["id"],
                "size": image_size,
                "image_count": len(local_urls),
                "prompts": prompts,
                "agent_action": action,
                "agent_reply": decision.get("reply") or "",
                "used_references": tool_refs,
                "raw_usage": raw_items[0].get("usage") if raw_items and isinstance(raw_items[0], dict) else None,
            }
        else:
            try:
                assistant_message = await build_chat_text_reply(payload, conversation)
            except HTTPException as exc:
                yield sse_event({"type": "error", "detail": exc.detail})
                return
            except Exception as exc:
                yield sse_event({"type": "error", "detail": f"请求上游接口失败：{exc}"})
                return
            assistant_message["agent_action"] = "chat"

        reasoning_text = str(decision.pop("reasoning", "") or "").strip()
        if reasoning_text and not assistant_message.get("reasoning"):
            assistant_message["reasoning"] = reasoning_text
        assistant_message["elapsed_ms"] = int((time.monotonic() - started_at) * 1000)
        conversation["messages"].append(assistant_message)
        conversation["updated_at"] = now_ms()
        save_conversation(user_id, conversation)
        if action not in {"generate_image", "edit_image"}:
            yield sse_event({"type": "delta", "delta": assistant_message.get("content") or ""})
        yield sse_event({"type": "done", "conversation": conversation, "message": assistant_message})

    return StreamingResponse(stream(), media_type="text/event-stream")

@app.post("/api/chat/stream")
async def chat_stream(payload: ChatRequest, request: Request, x_user_id: str = Header(default="")):
    payload.provider = member_provider(payload.provider)
    payload.image_provider = member_provider(payload.image_provider)
    if payload.mode == "image":
        raise HTTPException(status_code=400, detail="图片模式请使用 /api/chat")

    user_id = safe_user_id(x_user_id, request)
    conversation = (
        load_conversation(user_id, payload.conversation_id)
        if payload.conversation_id
        else new_conversation(user_id, display_title(payload.message))
    )
    if not conversation.get("messages"):
        conversation["title"] = display_title(payload.message)

    refs = [ref.dict() for ref in payload.reference_images if ref.url]
    user_message = {
        "id": uuid.uuid4().hex,
        "role": "user",
        "content": payload.message,
        "created_at": now_ms(),
        "attachments": refs,
        "mode": payload.mode,
    }
    if payload.capability:
        user_message["capability"] = dict(payload.capability)
    conversation["messages"].append(user_message)
    conversation["updated_at"] = now_ms()
    save_conversation(user_id, conversation)

    # 默认使用用户在 NOVAI 配置的模型；只有显式选择 openclaw 时才走外部网关
    if (os.environ.get("NOVAI_CHAT_BACKEND", "local") or "local").strip().lower() == "openclaw":
        from server.integrations.openclaw import stream_openclaw_chat
        return StreamingResponse(
            stream_openclaw_chat(payload, conversation, user_id, save_conversation),
            media_type="text/event-stream",
        )

    _codex_provider = get_api_provider(payload.provider)
    if is_codex_provider(_codex_provider):
        model = selected_model(payload.model, (_codex_provider.get("chat_models") or CODEX_DEFAULT_CHAT_MODELS)[0])
        payload.model = model

        async def codex_stream():
            yield sse_event({"type": "meta", "conversation": conversation})
            try:
                text, raw = await codex_chat_text(payload, conversation["messages"][-MAX_HISTORY_MESSAGES:])
            except HTTPException as exc:
                yield sse_event({"type": "error", "detail": exc.detail})
                return
            assistant_message = {
                "id": uuid.uuid4().hex,
                "role": "assistant",
                "content": text,
                "created_at": now_ms(),
                "model": model,
                "raw_usage": None,
                "raw": raw,
            }
            conversation["messages"].append(assistant_message)
            conversation["updated_at"] = now_ms()
            save_conversation(user_id, conversation)
            yield sse_event({"type": "delta", "delta": text})
            yield sse_event({"type": "done", "conversation": conversation, "message": assistant_message})

        return StreamingResponse(codex_stream(), media_type="text/event-stream")

    if is_gemini_cli_provider(_codex_provider):
        model = selected_model(payload.model, (_codex_provider.get("chat_models") or GEMINI_CLI_DEFAULT_CHAT_MODELS)[0])
        payload.model = model

        async def gemini_cli_stream():
            yield sse_event({"type": "meta", "conversation": conversation})
            try:
                text, raw = await gemini_cli_chat_text(payload, conversation["messages"][-MAX_HISTORY_MESSAGES:])
            except HTTPException as exc:
                yield sse_event({"type": "error", "detail": exc.detail})
                return
            assistant_message = {
                "id": uuid.uuid4().hex,
                "role": "assistant",
                "content": text,
                "created_at": now_ms(),
                "model": model,
                "raw_usage": None,
                "raw": raw,
            }
            conversation["messages"].append(assistant_message)
            conversation["updated_at"] = now_ms()
            save_conversation(user_id, conversation)
            yield sse_event({"type": "delta", "delta": text})
            yield sse_event({"type": "done", "conversation": conversation, "message": assistant_message})

        return StreamingResponse(gemini_cli_stream(), media_type="text/event-stream")

    if is_lovart_provider(_codex_provider):
        model = selected_model(payload.model, (_codex_provider.get("chat_models") or LOVART_DEFAULT_CHAT_MODELS)[0])
        payload.model = model

        async def lovart_stream():
            yield sse_event({"type": "meta", "conversation": conversation})
            try:
                text, raw = await lovart_chat_text(payload, conversation["messages"][-MAX_HISTORY_MESSAGES:])
            except HTTPException as exc:
                yield sse_event({"type": "error", "detail": exc.detail})
                return
            assistant_message = {
                "id": uuid.uuid4().hex,
                "role": "assistant",
                "content": text,
                "created_at": now_ms(),
                "model": model,
                "raw_usage": None,
                "raw": raw,
            }
            conversation["messages"].append(assistant_message)
            conversation["updated_at"] = now_ms()
            save_conversation(user_id, conversation)
            yield sse_event({"type": "delta", "delta": text})
            yield sse_event({"type": "done", "conversation": conversation, "message": assistant_message})

        return StreamingResponse(lovart_stream(), media_type="text/event-stream")

    chat_base, chat_hdrs, model = resolve_chat_provider(payload.provider, payload.model, payload.ms_model)
    _stream_provider = get_api_provider(payload.provider) if payload.provider not in ("modelscope",) else {}
    history = conversation["messages"][-MAX_HISTORY_MESSAGES:]
    upstream_messages = [{"role": "system", "content": chat_system_prompt(payload)}]
    for item in history:
        msg = upstream_message_from_record(item)
        if msg:
            upstream_messages.append(msg)
    stream_think_fields = chat_think_fields(_stream_provider, model, payload.think_level)
    stream_body = {"model": model, "messages": upstream_messages, "stream": True}
    stream_body.update(stream_think_fields)

    async def stream():
        content_parts = []
        reasoning_parts = []
        raw_usage = None
        yield sse_event({"type": "meta", "conversation": conversation})
        try:
            async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=AI_REQUEST_TIMEOUT) as client:
                async with chat_stream_with_think(
                    client,
                    f"{chat_base}/chat/completions",
                    chat_hdrs,
                    stream_body,
                    stream_think_fields,
                ) as (response, _sent_body):
                    if response.status_code >= 400:
                        detail = await response.aread()
                        body = detail.decode("utf-8", errors="ignore")
                        friendly = friendly_chat_error_detail(body, model, _stream_provider)
                        yield sse_event({"type": "error", "detail": friendly or f"上游接口错误：{body}"})
                        return
                    async for line in response.aiter_lines():
                        if not line:
                            continue
                        if line.startswith("data:"):
                            line = line[5:].strip()
                        if line == "[DONE]":
                            break
                        try:
                            chunk = json.loads(line)
                        except json.JSONDecodeError:
                            continue
                        if isinstance(chunk, dict) and chunk.get("usage"):
                            raw_usage = chunk.get("usage")
                        reasoning_delta = reasoning_delta_from_chat_chunk(chunk)
                        if reasoning_delta:
                            reasoning_parts.append(reasoning_delta)
                            yield sse_event({"type": "reasoning", "delta": reasoning_delta})
                        delta = text_delta_from_chat_chunk(chunk)
                        if delta:
                            content_parts.append(delta)
                            yield sse_event({"type": "delta", "delta": delta})
        except httpx.HTTPError as exc:
            log_net_error("对话(流式) 网络/TLS错误", exc)
            yield sse_event({"type": "error", "detail": f"请求上游接口失败：{exc}"})
            return

        assistant_message = {
            "id": uuid.uuid4().hex,
            "role": "assistant",
            "content": "".join(content_parts).strip() or "接口返回了空回复。",
            "created_at": now_ms(),
            "model": model,
            "raw_usage": raw_usage,
        }
        reasoning_text = "".join(reasoning_parts).strip()
        if reasoning_text:
            assistant_message["reasoning"] = reasoning_text
        conversation["messages"].append(assistant_message)
        conversation["updated_at"] = now_ms()
        save_conversation(user_id, conversation)
        yield sse_event({"type": "done", "conversation": conversation, "message": assistant_message})

    return StreamingResponse(stream(), media_type="text/event-stream")

# --- 历史记录 ---

@app.get("/api/history")
async def get_history_api(type: str = None):
    if os.path.exists(HISTORY_FILE):
        try:
            with open(HISTORY_FILE, 'r', encoding='utf-8') as f:
                data = json.load(f)
                if type:
                    data = [item for item in data if item.get("type", "zimage") == type]
                data = [item for item in data if item.get("images") and len(item["images"]) > 0]

                def sort_key(item):
                    ts = item.get("timestamp", 0)
                    if isinstance(ts, (int, float)):
                        return float(ts)
                    return 0

                data.sort(key=sort_key, reverse=True)
                return data
        except Exception as e:
            print(f"读取历史文件失败: {e}")
            return []
    return []

@app.get("/api/queue_status")
async def get_queue_status(client_id: str):
    with QUEUE_LOCK:
        total = len(QUEUE)
        positions = [i + 1 for i, t in enumerate(QUEUE) if t["client_id"] == client_id]
        position = positions[0] if positions else 0
    return {"total": total, "position": position}

@app.post("/api/history/delete")
async def delete_history(req: DeleteHistoryRequest):
    if not os.path.exists(HISTORY_FILE):
        return {"success": False, "message": "History file not found"}
    try:
        with HISTORY_LOCK:
            with open(HISTORY_FILE, 'r', encoding='utf-8') as f:
                history = json.load(f)
            target_record = None
            new_history = []
            for item in history:
                is_match = False
                item_ts = item.get("timestamp", 0)
                if isinstance(req.timestamp, (int, float)) and isinstance(item_ts, (int, float)):
                    if abs(float(item_ts) - float(req.timestamp)) < 0.001:
                        is_match = True
                elif str(item_ts) == str(req.timestamp):
                    is_match = True
                if is_match:
                    target_record = item
                else:
                    new_history.append(item)
            if target_record:
                write_json_atomic(HISTORY_FILE, new_history, ensure_ascii=False, indent=4)

        if target_record:
            for img_url in target_record.get("images", []):
                file_path = output_file_from_url(img_url)
                if file_path and os.path.exists(file_path):
                    try:
                        os.remove(file_path)
                    except Exception as e:
                        print(f"Failed to delete file {file_path}: {e}")
            return {"success": True}
        else:
            return {"success": False, "message": "Record not found"}
    except Exception as e:
        print(f"Delete history error: {e}")
        return {"success": False, "message": str(e)}

# --- ModelScope 角度控制 ---

@app.post("/api/angle/poll_status")
async def poll_angle_cloud(req: CloudPollRequest):
    api_root = modelscope_image_api_root()
    clean_token = modelscope_api_key(req.api_key)
    if not clean_token:
        raise HTTPException(status_code=400, detail="未提供 ModelScope API Key")

    headers = {
        "Authorization": f"Bearer {clean_token}",
        "Content-Type": "application/json",
        "X-ModelScope-Async-Mode": "true"
    }
    task_id = req.task_id
    print(f"Resuming polling for Angle Task: {task_id}")

    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=30) as client:
            for i in range(300):
                await asyncio.sleep(2)
                result = await client.get(
                    f"{api_root}/tasks/{task_id}",
                    headers={**headers, "X-ModelScope-Task-Type": "image_generation"},
                )
                result.raise_for_status()
                data = result.json()
                status = str(data.get("task_status") or "").upper()

                if status == "SUCCEED":
                    img_url = data["output_images"][0]
                    local_path = ""
                    try:
                        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, ) as dl_client:
                            img_res = await dl_client.get(img_url)
                            if img_res.status_code == 200:
                                filename = f"cloud_angle_{int(time.time())}.png"
                                file_path = output_path_for(filename, "output")
                                with open(file_path, "wb") as f:
                                    f.write(img_res.content)
                                local_path = output_url_for(filename, "output")
                            else:
                                local_path = img_url
                    except Exception:
                        local_path = img_url

                    record = {"timestamp": time.time(), "prompt": f"Resumed {task_id}", "images": [local_path], "type": "angle"}
                    save_to_history(record)
                    if req.client_id:
                        await manager.send_personal_message({"type": "cloud_status", "status": "SUCCEED", "task_id": task_id}, req.client_id)
                    return {"url": local_path}

                elif status in {"FAILED", "FAIL", "ERROR", "CANCELED", "CANCELLED", "TIMEOUT", "REVOKED"}:
                    if req.client_id:
                        await manager.send_personal_message({"type": "cloud_status", "status": "FAILED", "task_id": task_id}, req.client_id)
                    raise HTTPException(status_code=502, detail=f"ModelScope task failed: {data}")

                if i % 5 == 0 and req.client_id:
                    await manager.send_personal_message({
                        "type": "cloud_status", "status": f"{status} ({i}/300)",
                        "task_id": task_id, "progress": i, "total": 300
                    }, req.client_id)

            if req.client_id:
                await manager.send_personal_message({"type": "cloud_status", "status": "TIMEOUT", "task_id": task_id}, req.client_id)
            return {"status": "timeout", "task_id": task_id, "message": "Task still pending"}

    except HTTPException:
        raise
    except Exception as e:
        print(f"Angle polling error: {e}")
        raise HTTPException(status_code=400, detail=str(e))

@app.post("/api/angle/generate")
async def generate_angle_cloud(req: CloudGenRequest):
    api_root = modelscope_image_api_root()
    clean_token = modelscope_api_key(req.api_key)
    if not clean_token:
        raise HTTPException(status_code=400, detail="未提供 ModelScope API Key")

    headers = {
        "Authorization": f"Bearer {clean_token}",
        "Content-Type": "application/json",
        "X-ModelScope-Async-Mode": "true"
    }
    model = selected_model(req.model, "Qwen/Qwen-Image-Edit-2511")
    payload = {
        "model": model,
        "prompt": req.prompt.strip(),
        "image_url": [modelscope_image_url(url, max_size=1536) for url in req.image_urls]
    }
    if req.resolution:
        payload["size"] = modelscope_size(req.resolution, model=model)
    if req.loras is not None:
        payload["loras"] = req.loras

    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=30) as client:
            submit_res = await client.post(f"{api_root}/images/generations", headers=headers, json=payload)
            if submit_res.status_code != 200:
                try:
                    detail = submit_res.json()
                except:
                    detail = submit_res.text
                raise HTTPException(status_code=submit_res.status_code, detail=detail)

            task_id = submit_res.json().get("task_id")
            print(f"Angle Task submitted, ID: {task_id}")

            for i in range(300):
                await asyncio.sleep(2)
                result = await client.get(
                    f"{api_root}/tasks/{task_id}",
                    headers={**headers, "X-ModelScope-Task-Type": "image_generation"},
                )
                result.raise_for_status()
                data = result.json()
                status = str(data.get("task_status") or "").upper()

                if status == "SUCCEED":
                    img_url = data["output_images"][0]
                    local_path = ""
                    try:
                        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, ) as dl_client:
                            img_res = await dl_client.get(img_url)
                            if img_res.status_code == 200:
                                filename = f"cloud_angle_{int(time.time())}.png"
                                file_path = output_path_for(filename, "output")
                                with open(file_path, "wb") as f:
                                    f.write(img_res.content)
                                local_path = output_url_for(filename, "output")
                            else:
                                local_path = img_url
                    except Exception:
                        local_path = img_url

                    record = {"timestamp": time.time(), "prompt": req.prompt, "images": [local_path], "type": "angle"}
                    save_to_history(record)
                    if req.client_id:
                        await manager.send_personal_message({"type": "cloud_status", "status": "SUCCEED", "task_id": task_id}, req.client_id)
                    if GLOBAL_LOOP:
                        asyncio.run_coroutine_threadsafe(manager.broadcast_new_image(record), GLOBAL_LOOP)
                    return {"url": local_path, "task_id": task_id}

                elif status in {"FAILED", "FAIL", "ERROR", "CANCELED", "CANCELLED", "TIMEOUT", "REVOKED"}:
                    if req.client_id:
                        await manager.send_personal_message({"type": "cloud_status", "status": "FAILED", "task_id": task_id}, req.client_id)
                    raise HTTPException(status_code=502, detail=f"ModelScope task failed: {data}")

                if i % 5 == 0 and req.client_id:
                    await manager.send_personal_message({
                        "type": "cloud_status", "status": f"{status} ({i}/300)",
                        "task_id": task_id, "progress": i, "total": 300
                    }, req.client_id)

            if req.client_id:
                await manager.send_personal_message({"type": "cloud_status", "status": "TIMEOUT", "task_id": task_id}, req.client_id)
            return {"status": "timeout", "task_id": task_id, "message": "Task still pending"}

    except HTTPException:
        raise
    except Exception as e:
        print(f"Angle generation error: {e}")
        raise HTTPException(status_code=400, detail=str(e))

# --- ModelScope Z-Image 云端生图 ---

@app.post("/generate")
async def generate_cloud(req: CloudGenRequest):
    api_root = modelscope_image_api_root()
    clean_token = modelscope_api_key(req.api_key)
    if not clean_token:
        raise HTTPException(status_code=400, detail="未提供 ModelScope API Key")

    headers = {
        "Authorization": f"Bearer {clean_token}",
        "Content-Type": "application/json",
    }
    payload = {
        "model": "Tongyi-MAI/Z-Image-Turbo",
        "prompt": req.prompt.strip(),
        "size": modelscope_size(req.resolution, model="Tongyi-MAI/Z-Image-Turbo"),
        "n": 1
    }
    if req.loras is not None:
        payload["loras"] = req.loras

    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=30) as client:
            submit_res = await client.post(
                f"{api_root}/images/generations",
                headers={**headers, "X-ModelScope-Async-Mode": "true"},
                json=payload
            )
            if submit_res.status_code != 200:
                try:
                    detail = submit_res.json()
                except:
                    detail = submit_res.text
                raise HTTPException(status_code=submit_res.status_code, detail=detail)

            task_id = submit_res.json().get("task_id")
            print(f"Z-Image Task submitted, ID: {task_id}")

            for i in range(200):
                await asyncio.sleep(3)
                result = await client.get(
                    f"{api_root}/tasks/{task_id}",
                    headers={**headers, "X-ModelScope-Task-Type": "image_generation"},
                )
                result.raise_for_status()
                data = result.json()
                status = str(data.get("task_status") or "").upper()

                if i % 5 == 0:
                    print(f"Task {task_id} status check {i}: {status}")

                if status == "SUCCEED":
                    img_url = data["output_images"][0]
                    local_path = ""
                    try:
                        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, ) as dl_client:
                            img_res = await dl_client.get(img_url)
                            if img_res.status_code == 200:
                                filename = f"cloud_{int(time.time())}.png"
                                file_path = output_path_for(filename, "output")
                                with open(file_path, "wb") as f:
                                    f.write(img_res.content)
                                local_path = output_url_for(filename, "output")
                            else:
                                local_path = img_url
                    except Exception as dl_e:
                        print(f"Download error: {dl_e}")
                        local_path = img_url

                    record = {"timestamp": time.time(), "prompt": req.prompt, "images": [local_path], "type": "cloud"}
                    save_to_history(record)
                    try:
                        await manager.broadcast_new_image(record)
                    except Exception:
                        pass
                    return {"url": local_path}

                elif status in {"FAILED", "FAIL", "ERROR", "CANCELED", "CANCELLED", "TIMEOUT", "REVOKED"}:
                    raise HTTPException(status_code=502, detail=f"ModelScope task failed: {data}")

            raise Exception("Cloud generation timeout")

    except HTTPException:
        raise
    except Exception as e:
        print(f"Cloud generation error: {e}")
        raise HTTPException(status_code=400, detail=str(e))

# --- ModelScope 通用图片生成（支持图生图） ---

@app.post("/api/ms/generate")
async def ms_generate(req: MsGenerateRequest):
    member_provider("modelscope")   # 普通成员不允许绕过 APIMart 走 ModelScope
    api_root = modelscope_image_api_root()
    clean_token = modelscope_api_key(req.api_key)
    if not clean_token:
        raise HTTPException(status_code=400, detail="未配置 ModelScope API Key，请在 API 设置中填写，或重新保存 ModelScope Token。")

    headers = {
        "Authorization": f"Bearer {clean_token}",
        "Content-Type": "application/json",
        "X-ModelScope-Async-Mode": "true"
    }
    payload = {
        "model": req.model,
        "prompt": req.prompt.strip(),
    }
    if req.width and req.height:
        constrained = modelscope_size(req.size or f"{req.width}x{req.height}", model=req.model)
        payload["width"], payload["height"] = parse_size_pair(constrained)
        payload["size"] = constrained
    elif req.size:
        payload["size"] = modelscope_size(req.size, model=req.model)
    if req.image_urls:
        payload["image_url"] = [modelscope_image_url(url, max_size=1536) for url in req.image_urls]
    if req.loras is not None:
        payload["loras"] = req.loras

    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=30) as client:
            submit_res = await client.post(
                f"{api_root}/images/generations",
                headers=headers,
                json=payload
            )
            if submit_res.status_code != 200:
                try:
                    detail = submit_res.json()
                except:
                    detail = submit_res.text
                raise HTTPException(status_code=submit_res.status_code, detail=detail)

            task_id = submit_res.json().get("task_id")
            print(f"MS Generate Task submitted ({req.model}), ID: {task_id}")

            TERMINAL_FAILED_STATUSES = {"FAILED", "FAIL", "ERROR", "CANCELED", "CANCELLED", "TIMEOUT", "REVOKED"}

            for i in range(300):
                await asyncio.sleep(2)
                try:
                    result = await client.get(
                        f"{api_root}/tasks/{task_id}",
                        headers={**headers, "X-ModelScope-Task-Type": "image_generation"},
                    )
                    data = result.json()
                    status = data.get("task_status")
                    print(f"MS Task {task_id} poll {i}: status={status}")

                    if status == "SUCCEED":
                        img_url = data["output_images"][0]
                        local_path = ""
                        try:
                            async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, ) as dl_client:
                                img_res = await dl_client.get(img_url)
                                if img_res.status_code == 200:
                                    filename = f"ms_{req.model.replace('/', '_').replace(':', '_')}_{int(time.time())}.png"
                                    file_path = output_path_for(filename, "output")
                                    with open(file_path, "wb") as f:
                                        f.write(img_res.content)
                                    local_path = output_url_for(filename, "output")
                                else:
                                    local_path = img_url
                        except Exception:
                            local_path = img_url

                        record = {
                            "timestamp": time.time(),
                            "prompt": req.prompt,
                            "images": [local_path],
                            "type": "klein",
                            "model": req.model,
                        }
                        save_to_history(record)
                        if GLOBAL_LOOP:
                            asyncio.run_coroutine_threadsafe(manager.broadcast_new_image(record), GLOBAL_LOOP)
                        return {"url": local_path, "task_id": task_id}

                    elif status in TERMINAL_FAILED_STATUSES:
                        error_info = data.get("error_info") or data.get("message") or data.get("detail") or str(data)
                        raise HTTPException(status_code=502, detail=f"MS task {status}: {error_info}")

                except HTTPException:
                    raise
                except Exception as loop_e:
                    print(f"MS polling error: {loop_e}")
                    continue

            raise HTTPException(status_code=504, detail="MS 生图超时")

    except HTTPException:
        raise
    except Exception as e:
        print(f"MS generate error: {e}")
        raise HTTPException(status_code=400, detail=str(e))

# --- 本地 ComfyUI 生图 ---

@app.post("/api/generate")
def generate(req: GenerateRequest):
    global NEXT_TASK_ID
    current_task = None
    target_backend = None
    with QUEUE_LOCK:
        task_id = NEXT_TASK_ID
        NEXT_TASK_ID += 1
        current_task = {"task_id": task_id, "client_id": req.client_id}
        QUEUE.append(current_task)

    try:
        required_images = collect_required_comfy_media(req.params)

        target_backend = reserve_best_backend(required_images)

        for image_name in required_images:
            need_sync = False
            try:
                check_url = f"http://{target_backend}/view?filename={urllib.parse.quote(image_name)}&type=input"
                resp = _NO_PROXY_SESSION.get(check_url, stream=True, timeout=0.5)
                resp.close()
                if resp.status_code != 200:
                    need_sync = True
            except:
                need_sync = True

            if need_sync:
                image_content = None
                image_type = "image/png"
                for addr in COMFYUI_INSTANCES:
                    if addr == target_backend: continue
                    try:
                        src_url = f"http://{addr}/view?filename={urllib.parse.quote(image_name)}&type=input"
                        r = _NO_PROXY_SESSION.get(src_url, timeout=5)
                        if r.status_code == 200:
                            image_content = r.content
                            image_type = r.headers.get("Content-Type", "image/png")
                            break
                    except: continue

                if image_content:
                    try:
                        files = {'image': (image_name, image_content, image_type)}
                        _NO_PROXY_SESSION.post(f"http://{target_backend}/upload/image", files=files, timeout=10)
                    except Exception as e:
                        print(f"Sync upload failed: {e}")

        workflow_path = os.path.join(WORKFLOW_DIR, req.workflow_json)
        if not os.path.exists(workflow_path) and req.workflow_json == "Z-Image.json":
            workflow_path = WORKFLOW_PATH
        if not os.path.exists(workflow_path):
            raise Exception(f"Workflow file not found: {req.workflow_json}")

        with open(workflow_path, 'r', encoding='utf-8') as f:
            workflow = json.load(f)

        seed = random.randint(1, 4294967295)

        if "23" in workflow and req.prompt:
            workflow["23"]["inputs"]["text"] = req.prompt
        if "144" in workflow:
            workflow["144"]["inputs"]["width"] = req.width
            workflow["144"]["inputs"]["height"] = req.height
        if "22" in workflow:
            workflow["22"]["inputs"]["seed"] = seed
        if "158" in workflow:
            workflow["158"]["inputs"]["noise_seed"] = seed
        for node_id in ["146", "181"]:
            if node_id in workflow and "inputs" in workflow[node_id] and "seed" in workflow[node_id]["inputs"]:
                workflow[node_id]["inputs"]["seed"] = seed
        if "184" in workflow and "inputs" in workflow["184"] and "seed" in workflow["184"]["inputs"]:
            workflow["184"]["inputs"]["seed"] = seed
        if "172" in workflow and "inputs" in workflow["172"] and "seed" in workflow["172"]["inputs"]:
            workflow["172"]["inputs"]["seed"] = seed
        if "14" in workflow and "inputs" in workflow["14"] and "seed" in workflow["14"]["inputs"]:
            workflow["14"]["inputs"]["seed"] = seed

        for node_id, node_inputs in req.params.items():
            if node_id in workflow:
                if "inputs" not in workflow[node_id]:
                    workflow[node_id]["inputs"] = {}
                for input_name, value in node_inputs.items():
                    workflow[node_id]["inputs"][input_name] = value

        p = {"prompt": workflow, "client_id": CLIENT_ID}
        data = json.dumps(p).encode('utf-8')
        try:
            post_req = urllib.request.Request(f"http://{target_backend}/prompt", data=data)
            prompt_id = json.loads(urllib.request.urlopen(post_req, timeout=10).read())['prompt_id']
        except urllib.error.HTTPError as e:
            error_body = e.read().decode('utf-8')
            raise Exception(f"HTTP Error {e.code}: {error_body}")

        history_data = None
        for i in range(COMFYUI_HISTORY_TIMEOUT):
            try:
                res = get_comfy_history(target_backend, prompt_id)
                if prompt_id in res:
                    history_data = res[prompt_id]
                    break
            except Exception:
                pass
            time.sleep(1)

        if not history_data:
            raise Exception("ComfyUI 渲染超时")

        local_images = []
        local_videos = []
        local_audios = []
        local_texts = []
        local_files = []
        local_items = []
        local_urls = []
        current_timestamp = time.time()
        if 'outputs' in history_data:
            # 先把所有节点的输出收集为候选（带上 class_type），再决定下载哪些，
            # 避免把冗余的预览/对比图、调试文本一起下载进结果（后端层过滤，历史记录也更干净）。
            workflow_nodes = workflow if isinstance(workflow, dict) else {}
            def _class_type_of(nid):
                node_def = workflow_nodes.get(str(nid))
                return str(node_def.get("class_type") or "") if isinstance(node_def, dict) else ""
            file_candidates = []   # (node_id, class_type, output_key, item, kind)
            text_candidates = []   # (node_id, class_type, text, name)
            for node_id in history_data['outputs']:
                node_output = history_data['outputs'][node_id]
                class_type = _class_type_of(node_id)
                for output_key, item in collect_comfy_file_items(node_output):
                    file_candidates.append((node_id, class_type, output_key, item, comfy_output_kind(item)))
                for text, name in comfy_text_values_from_output(node_output):
                    text_candidates.append((node_id, class_type, text, name))

            # 只要存在“非预览节点”产出的图片，就把 PreviewImage/对比节点的图片视为冗余丢弃；
            # 若整个工作流只有预览图（没有 SaveImage 等），则保留预览图作为唯一结果，避免零输出。
            has_primary_image = any(
                kind == "image" and not comfy_class_is_preview(ct)
                for (_nid, ct, _ok, _it, kind) in file_candidates
            )
            prefix = f"{req.type}_{int(current_timestamp)}_"
            for node_id, class_type, output_key, item, kind in file_candidates:
                if kind == "image" and has_primary_image and comfy_class_is_preview(class_type):
                    continue  # 跳过冗余的预览/对比图
                local_path = download_comfy_output(target_backend, item, prefix=prefix)
                if kind == "image" and req.convert_to_jpg:
                    local_path = convert_output_to_jpg(local_path)
                name = os.path.basename(str(item.get("filename") or "")) or os.path.basename(str(local_path).split("?", 1)[0])
                entry = {
                    "url": local_path,
                    "kind": kind,
                    "name": name,
                    "node_id": str(node_id),
                    "output_key": str(output_key),
                    "class_type": class_type,
                }
                if kind == "image":
                    local_images.append(local_path)
                elif kind == "video":
                    local_videos.append(local_path)
                elif kind == "audio":
                    local_audios.append(local_path)
                elif kind == "text":
                    local_texts.append(local_path)
                else:
                    local_files.append(local_path)
                local_items.append(entry)
                local_urls.append(local_path)

            # 默认抑制 show/utility 类节点的调试文本，避免 .txt 噪声混入结果。
            for node_id, class_type, text, name in text_candidates:
                if comfy_class_is_debug_text(class_type):
                    continue
                local_path = save_comfy_text_output(text, prefix=prefix, name=name)
                entry = {
                    "url": local_path,
                    "kind": "text",
                    "name": os.path.basename(str(local_path).split("?", 1)[0]),
                    "node_id": str(node_id),
                    "output_key": "text",
                    "class_type": class_type,
                }
                local_texts.append(local_path)
                local_items.append(entry)
                local_urls.append(local_path)

        result = {
            "prompt": req.prompt if req.prompt else "Detail Enhance",
            "images": local_images,
            "videos": local_videos,
            "audios": local_audios,
            "texts": local_texts,
            "files": local_files,
            "items": local_items,
            "outputs": local_urls,
            "seed": seed,
            "timestamp": current_timestamp,
            "type": req.type,
            "workflow_json": req.workflow_json,
            "task_id": task_id,
            "prompt_id": prompt_id,
            "backend": target_backend,
            "params": req.params
        }
        save_to_history(result)
        if GLOBAL_LOOP:
            asyncio.run_coroutine_threadsafe(manager.broadcast_new_image(result), GLOBAL_LOOP)
        return result

    except Exception as e:
        return {"images": [], "error": str(e)}
    finally:
        if target_backend:
            with LOAD_LOCK:
                if BACKEND_LOCAL_LOAD.get(target_backend, 0) > 0:
                    BACKEND_LOCAL_LOAD[target_backend] -= 1
        if current_task:
            with QUEUE_LOCK:
                if current_task in QUEUE:
                    QUEUE.remove(current_task)

# --- ComfyUI 工作流管理 ---

BUILTIN_WORKFLOWS = {"Z-Image.json", "Z-Image-Enhance.json", "2511.json", "klein-enhance.json", "Flux2-Klein.json", "upscale.json"}
CUSTOM_WORKFLOW_FOLDER = "custom"
LEGACY_CUSTOM_WORKFLOW_FOLDER = "自定义"
WORKFLOW_NAME_RE = re.compile(rf"^(?:(?:{CUSTOM_WORKFLOW_FOLDER}|{LEGACY_CUSTOM_WORKFLOW_FOLDER})/)?[a-zA-Z0-9_一-龥\.\-]+\.json$")

class WorkflowField(BaseModel):
    id: str
    node: str = ""
    input: str = ""
    name: str = ""
    type: str = "text"
    default: Any = None
    min: Optional[float] = None
    max: Optional[float] = None
    step: Optional[float] = None
    options: List[str] = []
    random_enabled: bool = False

class WorkflowConfig(BaseModel):
    title: str = ""
    fields: List[WorkflowField] = []
    mini_cards: Dict[str, Any] = {}

class WorkflowUploadRequest(BaseModel):
    name: str
    workflow: Dict[str, Any]

class WorkflowRunRequest(BaseModel):
    fields: Dict[str, Any] = {}
    config: WorkflowConfig
    client_id: str = ""

def workflow_path_from_name(name: str) -> str:
    if not WORKFLOW_NAME_RE.match(name):
        raise HTTPException(status_code=400, detail="Invalid workflow name")
    path = os.path.abspath(os.path.join(WORKFLOW_DIR, *name.split("/")))
    workflow_root = os.path.abspath(WORKFLOW_DIR)
    if os.path.commonpath([workflow_root, path]) != workflow_root:
        raise HTTPException(status_code=400, detail="Invalid workflow name")
    return path

def workflow_config_path(name: str) -> str:
    return workflow_path_from_name(name).replace(".json", ".config.json")

def is_builtin_workflow(name: str) -> bool:
    return "/" not in name and os.path.basename(name) in BUILTIN_WORKFLOWS

def runninghub_workflow_store_path() -> str:
    return RUNNINGHUB_WORKFLOW_STORE_FILE

def load_runninghub_workflow_store():
    if not os.path.exists(RUNNINGHUB_WORKFLOW_STORE_FILE):
        return {}
    try:
        with open(RUNNINGHUB_WORKFLOW_STORE_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}

def save_runninghub_workflow_store(store):
    os.makedirs(DATA_DIR, exist_ok=True)
    write_json_atomic(RUNNINGHUB_WORKFLOW_STORE_FILE, store, ensure_ascii=False, indent=2)

def runninghub_workflow_config_has_payload(cfg):
    if not isinstance(cfg, dict):
        return False
    return bool(cfg.get("fields") or cfg.get("workflowJson") or cfg.get("raw"))

def runninghub_static_workflow_entry(workflow_id: str):
    key = runninghub_workflow_store_key(workflow_id)
    if not key:
        return None
    static_provider = load_static_runninghub_provider()
    for entry in (static_provider or {}).get("rh_workflows", []) or []:
        if runninghub_workflow_store_key(entry.get("workflowId") or entry.get("id")) == key:
            return entry
    return None

def runninghub_static_workflow_config(workflow_id: str):
    entry = runninghub_static_workflow_entry(workflow_id)
    if not isinstance(entry, dict):
        return None
    key = runninghub_workflow_store_key(entry.get("workflowId") or entry.get("id"))
    cfg = {
        "workflowId": key,
        "title": entry.get("title") or key,
        "description": entry.get("note") or entry.get("description") or "",
        "fields": [
            field for field in (runninghub_normalize_field(item) for item in (entry.get("fields") or []))
            if not runninghub_is_saved_link_field(field)
        ],
        "workflowJson": entry.get("workflowJson") if isinstance(entry.get("workflowJson"), dict) else {},
        "optionalImageMode": entry.get("optionalImageMode") or "prune-workflow",
        "raw": entry.get("raw") if isinstance(entry.get("raw"), dict) else {},
        "updatedAt": entry.get("updatedAt") or 0,
        "source": "static_template",
    }
    return cfg if runninghub_workflow_config_has_payload(cfg) else None

def runninghub_workflow_entry_from_config(cfg, fallback=None):
    fallback = fallback if isinstance(fallback, dict) else {}
    key = runninghub_workflow_store_key((cfg or {}).get("workflowId") or fallback.get("workflowId") or fallback.get("id"))
    if not key:
        return None
    return normalize_runninghub_entry({
        "id": key,
        "workflowId": key,
        "title": (cfg or {}).get("title") or fallback.get("title") or fallback.get("name") or f"工作流 {key[-6:]}",
        "note": (cfg or {}).get("description") or fallback.get("note") or fallback.get("description") or "",
        "thumbnail": fallback.get("thumbnail") or "",
        "enabled": fallback.get("enabled", True),
        "fields": (cfg or {}).get("fields") or fallback.get("fields") or [],
        "workflowJson": (cfg or {}).get("workflowJson") if isinstance((cfg or {}).get("workflowJson"), dict) else fallback.get("workflowJson") or {},
        "optionalImageMode": (cfg or {}).get("optionalImageMode") or fallback.get("optionalImageMode") or "prune-workflow",
        "raw": (cfg or {}).get("raw") if isinstance((cfg or {}).get("raw"), dict) else fallback.get("raw") or {},
        "updatedAt": (cfg or {}).get("updatedAt") or fallback.get("updatedAt") or 0,
    }, "workflow")

def runninghub_saved_hidden_workflow_ids():
    if not os.path.exists(API_PROVIDERS_FILE):
        return set()
    try:
        with open(API_PROVIDERS_FILE, "r", encoding="utf-8") as f:
            raw = json.load(f)
    except Exception:
        return set()
    hidden = set()
    for provider in raw if isinstance(raw, list) else []:
        if not isinstance(provider, dict) or str(provider.get("id") or "").strip().lower() != "runninghub":
            continue
        for entry in provider.get("rh_workflows") or []:
            if not isinstance(entry, dict) or entry.get("hidden") is not True:
                continue
            key = runninghub_workflow_store_key(entry.get("workflowId") or entry.get("id"))
            if key:
                hidden.add(key)
    return hidden

def runninghub_provider_with_workflow_store(provider):
    if not isinstance(provider, dict) or provider.get("id") != "runninghub":
        return provider
    store = load_runninghub_workflow_store()
    if not store:
        return provider
    merged = dict(provider)
    workflows = [dict(item) for item in (merged.get("rh_workflows") or []) if isinstance(item, dict)]
    hidden_ids = {
        runninghub_workflow_store_key(item.get("workflowId") or item.get("id"))
        for item in workflows
        if item.get("hidden") is True and runninghub_workflow_store_key(item.get("workflowId") or item.get("id"))
    }
    hidden_ids.update(runninghub_saved_hidden_workflow_ids())
    by_id = {
        runninghub_workflow_store_key(item.get("workflowId") or item.get("id")): item
        for item in workflows
        if runninghub_workflow_store_key(item.get("workflowId") or item.get("id"))
    }
    for workflow_id, cfg in store.items():
        if workflow_id in hidden_ids:
            continue
        if not isinstance(cfg, dict) or not runninghub_workflow_config_has_payload(cfg):
            continue
        existing = by_id.get(workflow_id)
        selected = runninghub_select_workflow_config(existing, cfg, workflow_id)
        entry = runninghub_workflow_entry_from_config(selected, existing)
        if not entry:
            continue
        if existing is None:
            workflows.append(entry)
        else:
            existing.update(entry)
    merged["rh_workflows"] = normalize_runninghub_entries(workflows, "workflow")
    return merged

def runninghub_provider_workflow_config(workflow_id: str):
    key = runninghub_workflow_store_key(workflow_id)
    if not key:
        return None
    if key in runninghub_saved_hidden_workflow_ids():
        return None
    providers = load_api_providers()
    provider = next((item for item in providers if item.get("id") == "runninghub"), None)
    if not provider:
        return None
    for entry in provider.get("rh_workflows") or []:
        entry_key = runninghub_workflow_store_key(entry.get("workflowId") or entry.get("id"))
        if entry_key != key:
            continue
        if entry.get("hidden") is True:
            return None
        cfg = {
            "workflowId": key,
            "title": entry.get("title") or key,
            "description": entry.get("note") or entry.get("description") or "",
            "fields": [
                field for field in (runninghub_normalize_field(item) for item in (entry.get("fields") or []))
                if not runninghub_is_saved_link_field(field)
            ],
            "workflowJson": entry.get("workflowJson") if isinstance(entry.get("workflowJson"), dict) else {},
            "optionalImageMode": entry.get("optionalImageMode") or "prune-workflow",
            "raw": entry.get("raw") if isinstance(entry.get("raw"), dict) else {},
            "updatedAt": entry.get("updatedAt") or 0,
            "source": "api_providers",
        }
        return cfg if runninghub_workflow_config_has_payload(cfg) else None
    return None

def runninghub_select_workflow_config(local_cfg, provider_cfg, workflow_id: str = ""):
    static_cfg = runninghub_static_workflow_config(workflow_id)
    if isinstance(local_cfg, dict) and isinstance(provider_cfg, dict):
        try:
            local_updated = int(local_cfg.get("updatedAt") or 0)
        except Exception:
            local_updated = 0
        try:
            provider_updated = int(provider_cfg.get("updatedAt") or 0)
        except Exception:
            provider_updated = 0
        return provider_cfg if provider_updated > local_updated else local_cfg
    if isinstance(local_cfg, dict):
        return local_cfg
    if isinstance(provider_cfg, dict):
        return provider_cfg
    if static_cfg:
        return static_cfg
    return None

def sync_runninghub_workflow_to_provider(cfg):
    if not isinstance(cfg, dict):
        return
    key = runninghub_workflow_store_key(cfg.get("workflowId"))
    if not key:
        return
    providers = load_api_providers()
    provider = next((item for item in providers if item.get("id") == "runninghub"), None)
    if not provider:
        provider = {
            "id": "runninghub",
            "name": "RunningHub",
            "base_url": RUNNINGHUB_DEFAULT_BASE_URL,
            "protocol": "runninghub",
            "image_generation_endpoint": "",
            "image_edit_endpoint": "",
            "enabled": True,
            "primary": False,
            "image_models": [],
            "chat_models": [],
            "video_models": [],
            "ms_loras": [],
            "ms_defaults_version": 0,
            "rh_apps": RUNNINGHUB_DEFAULT_APPS,
            "rh_workflows": [],
        }
        providers.append(provider)
    workflows = provider.setdefault("rh_workflows", [])
    entry = None
    for item in workflows:
        item_key = runninghub_workflow_store_key(item.get("workflowId") or item.get("id"))
        if item_key == key:
            entry = item
            break
    if entry is None:
        entry = {
            "id": key,
            "workflowId": key,
            "title": cfg.get("title") or f"工作流 {key[-6:]}",
            "note": cfg.get("description") or "",
            "thumbnail": "",
            "enabled": True,
        }
        workflows.append(entry)
    entry.update({
        "id": key,
        "workflowId": key,
        "title": cfg.get("title") or entry.get("title") or f"工作流 {key[-6:]}",
        "note": cfg.get("description") or "",
        "fields": [
            field for field in (runninghub_normalize_field(item) for item in (cfg.get("fields") or []))
            if not runninghub_is_saved_link_field(field)
        ],
        "workflowJson": cfg.get("workflowJson") if isinstance(cfg.get("workflowJson"), dict) else {},
        "optionalImageMode": cfg.get("optionalImageMode") or "prune-workflow",
        "raw": cfg.get("raw") if isinstance(cfg.get("raw"), dict) else {},
        "updatedAt": cfg.get("updatedAt") or now_ms(),
    })
    if "enabled" not in entry:
        entry["enabled"] = True
    if "thumbnail" not in entry:
        entry["thumbnail"] = ""
    save_api_providers([normalize_provider(item) for item in providers])

def remove_runninghub_workflow_from_provider(workflow_id: str):
    key = runninghub_workflow_store_key(workflow_id)
    if not key:
        return
    providers = load_api_providers()
    changed = False
    for provider in providers:
        if provider.get("id") != "runninghub":
            continue
        workflows = provider.get("rh_workflows") or []
        removed = next((
            item for item in workflows
            if runninghub_workflow_store_key(item.get("workflowId") or item.get("id")) == key
        ), None)
        kept = [
            item for item in workflows
            if runninghub_workflow_store_key(item.get("workflowId") or item.get("id")) != key
        ]
        static_provider = load_static_runninghub_provider()
        static_workflow = next((
            item for item in (static_provider or {}).get("rh_workflows", [])
            if runninghub_workflow_store_key(item.get("workflowId") or item.get("id")) == key
        ), None)
        if static_workflow:
            tombstone = normalize_runninghub_entry({**static_workflow, **(removed or {}), "enabled": False, "hidden": True}, "workflow")
            if tombstone:
                kept.append(tombstone)
        if static_workflow or len(kept) != len(workflows):
            provider["rh_workflows"] = kept
            changed = True
    if changed:
        save_api_providers([normalize_provider(item) for item in providers])

def runninghub_workflow_store_key(workflow_id: str) -> str:
    return str(workflow_id or "").strip()

def runninghub_normalize_field(raw, fallback=None):
    fallback = fallback or {}
    if hasattr(raw, "dict"):
        raw = raw.dict()
    if not isinstance(raw, dict):
        raw = {}
    options = raw.get("options", fallback.get("options", []))
    if isinstance(options, str):
        options = [item.strip() for item in re.split(r"[\r\n,]+", options) if item.strip()]
    elif isinstance(options, list):
        options = [str(item).strip() for item in options if str(item).strip()]
    else:
        options = []
    field_id = str(raw.get("id") or raw.get("fieldId") or raw.get("key") or raw.get("nodeId") or fallback.get("id") or "").strip()
    node_id = str(raw.get("nodeId") or fallback.get("nodeId") or raw.get("node_id") or "").strip()
    field_name = str(raw.get("fieldName") or raw.get("inputName") or raw.get("name") or fallback.get("fieldName") or "").strip()
    field_value = raw.get("fieldValue")
    if field_value is None:
        field_value = raw.get("defaultValue")
    if field_value is None:
        field_value = raw.get("value")
    if field_value is None:
        field_value = fallback.get("fieldValue", "")
    if isinstance(field_value, (dict, list)):
        field_value = json.dumps(field_value, ensure_ascii=False)
    elif field_value is None:
        field_value = ""
    else:
        field_value = str(field_value)
    return {
        "id": field_id or f"{node_id}::{field_name}",
        "nodeId": node_id,
        "fieldName": field_name,
        "fieldValue": field_value,
        "fieldType": str(raw.get("fieldType") or fallback.get("fieldType") or "TEXT"),
        "label": str(raw.get("label") or raw.get("title") or field_name or fallback.get("label") or ""),
        "enabled": bool(raw.get("enabled", fallback.get("enabled", True))),
        "sourceFromUpstream": bool(raw.get("sourceFromUpstream", fallback.get("sourceFromUpstream", True))),
        "group": str(raw.get("group") or fallback.get("group") or ""),
        "note": str(raw.get("note") or fallback.get("note") or ""),
        "options": options,
        "random_enabled": bool(raw.get("random_enabled", fallback.get("random_enabled", False))),
        "min": raw.get("min", fallback.get("min", "")),
        "max": raw.get("max", fallback.get("max", "")),
        "step": raw.get("step", fallback.get("step", "")),
        "imageOrder": int(raw.get("imageOrder") or raw.get("image_order") or fallback.get("imageOrder") or 0),
        "required": bool(raw.get("required", fallback.get("required", False))),
    }

def runninghub_is_saved_link_field(field):
    if not isinstance(field, dict):
        return False
    value = field.get("fieldValue")
    if not isinstance(value, str):
        return False
    text = value.strip()
    if not (text.startswith("[") and text.endswith("]")):
        return False
    try:
        parsed = json.loads(text)
    except Exception:
        return False
    return runninghub_is_workflow_link_value(parsed)

def runninghub_collect_workflow_fields(workflow_json):
    fields = []
    if not isinstance(workflow_json, dict):
        return fields
    for node_id, node_content in workflow_json.items():
        if not isinstance(node_content, dict):
            continue
        inputs = node_content.get("inputs")
        if not isinstance(inputs, dict):
            continue
        for field_name, raw_value in inputs.items():
            if runninghub_is_workflow_link_value(raw_value):
                continue
            if isinstance(raw_value, (dict, list)):
                field_value = json.dumps(raw_value, ensure_ascii=False)
            elif raw_value is None:
                field_value = ""
            else:
                field_value = str(raw_value)
            field_type = runninghub_infer_workflow_field_type(field_name, field_value)
            fields.append({
                "id": f"{node_id}::{field_name}",
                "nodeId": str(node_id),
                "fieldName": str(field_name),
                "fieldValue": field_value,
                "fieldType": field_type,
                "label": str(field_name),
                "enabled": False,
                "sourceFromUpstream": True,
                "group": str(
                    (node_content.get("_meta") or {}).get("title")
                    or node_content.get("class_type")
                    or node_content.get("_class")
                    or node_content.get("type")
                    or ""
                ),
                "note": "",
                "imageOrder": 0,
                "required": field_type == "IMAGE",
            })
    return fields

class ComfyInstancesPayload(BaseModel):
    instances: List[str] = []

@app.get("/api/comfyui/instances")
def get_comfyui_instances():
    return {"instances": COMFYUI_INSTANCES}

@app.put("/api/comfyui/instances")
def save_comfyui_instances(payload: ComfyInstancesPayload):
    # 宽容校验：去前后空白、去 http(s):// 前缀、去尾部斜杠；要求形如 host:port
    cleaned = []
    for item in payload.instances:
        s = str(item or "").strip()
        if not s:
            continue
        s = re.sub(r"^https?://", "", s)
        s = s.rstrip("/")
        if ":" not in s:
            raise HTTPException(status_code=400, detail=f"地址缺少端口号：{item}（应为 host:port，例如 127.0.0.1:8188）")
        host, _, port = s.rpartition(":")
        if not host or not port.isdigit():
            raise HTTPException(status_code=400, detail=f"地址不合法：{item}（应为 host:port，例如 127.0.0.1:8188）")
        if s in cleaned:
            continue
        cleaned.append(s)
    if not cleaned:
        raise HTTPException(status_code=400, detail="至少保留一个 ComfyUI 后端地址")
    # 写入 env 文件
    try:
        update_env_values({"COMFYUI_INSTANCES": ",".join(cleaned)})
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"写入 env 失败：{e}")
    # 更新进程中的全局变量
    global COMFYUI_INSTANCES, COMFYUI_ADDRESS, BACKEND_LOCAL_LOAD
    COMFYUI_INSTANCES = cleaned
    COMFYUI_ADDRESS = cleaned[0]
    new_load = {addr: 0 for addr in cleaned}
    for addr, n in (BACKEND_LOCAL_LOAD or {}).items():
        if addr in new_load:
            new_load[addr] = n
    BACKEND_LOCAL_LOAD = new_load
    return {"instances": COMFYUI_INSTANCES}

@app.get("/api/workflows")
def list_workflows():
    if not os.path.isdir(WORKFLOW_DIR):
        return {"workflows": []}
    items = []
    for root, dirs, files in os.walk(WORKFLOW_DIR):
        if os.path.abspath(root) == os.path.abspath(WORKFLOW_DIR):
            dirs[:] = [d for d in dirs if d in {CUSTOM_WORKFLOW_FOLDER, LEGACY_CUSTOM_WORKFLOW_FOLDER}]
        for fn in sorted(files):
            if not fn.endswith(".json") or fn.endswith(".config.json"):
                continue
            rel = os.path.relpath(os.path.join(root, fn), WORKFLOW_DIR).replace("\\", "/")
            if is_builtin_workflow(rel):
                continue
            cfg = {}
            cfg_path = workflow_config_path(rel)
            if os.path.exists(cfg_path):
                try:
                    with open(cfg_path, "r", encoding="utf-8") as f:
                        cfg = json.load(f) or {}
                except Exception:
                    cfg = {}
            items.append({
                "name": rel,
                "title": cfg.get("title") or fn.replace(".json", ""),
                "builtin": False,
                "field_count": len(cfg.get("fields") or []),
            })
    items.sort(key=lambda item: (0 if item["name"].startswith(f"{CUSTOM_WORKFLOW_FOLDER}/") else 1, item["title"]))
    return {"workflows": items}

@app.get("/api/workflows/{name:path}")
def get_workflow(name: str):
    if not WORKFLOW_NAME_RE.match(name):
        raise HTTPException(status_code=400, detail="Invalid workflow name")
    workflow_path = workflow_path_from_name(name)
    if not os.path.exists(workflow_path):
        raise HTTPException(status_code=404, detail="Workflow not found")
    with open(workflow_path, "r", encoding="utf-8") as f:
        workflow = json.load(f)
    cfg = {"title": name.replace(".json", ""), "fields": []}
    cfg_path = workflow_config_path(name)
    if os.path.exists(cfg_path):
        try:
            with open(cfg_path, "r", encoding="utf-8") as f:
                cfg = json.load(f) or cfg
        except Exception:
            pass
    return {"name": name, "workflow": workflow, "config": cfg, "builtin": is_builtin_workflow(name)}

@app.post("/api/workflows")
def upload_workflow(payload: WorkflowUploadRequest):
    name = os.path.basename(payload.name.strip())
    if not name.endswith(".json"):
        name = name + ".json"
    if not WORKFLOW_NAME_RE.match(name):
        raise HTTPException(status_code=400, detail="工作流名称不合法，请使用中文/英文/数字/_-.")
    if not isinstance(payload.workflow, dict) or not payload.workflow:
        raise HTTPException(status_code=400, detail="工作流 JSON 为空")
    # 简单校验：是 API 格式（节点 id 为 key，含 class_type）
    sample = next(iter(payload.workflow.values()), None)
    if not isinstance(sample, dict) or "class_type" not in sample:
        raise HTTPException(status_code=400, detail="不是有效的 ComfyUI API 工作流 JSON（需包含 class_type）")
    custom_dir = os.path.join(WORKFLOW_DIR, CUSTOM_WORKFLOW_FOLDER)
    os.makedirs(custom_dir, exist_ok=True)
    stored_name = f"{CUSTOM_WORKFLOW_FOLDER}/{name}"
    path = workflow_path_from_name(stored_name)
    write_json_atomic(path, payload.workflow, ensure_ascii=False, indent=2)
    return {"name": stored_name}

@app.put("/api/workflows/{name:path}/config")
def save_workflow_config(name: str, payload: WorkflowConfig):
    if not WORKFLOW_NAME_RE.match(name):
        raise HTTPException(status_code=400, detail="Invalid workflow name")
    workflow_path = workflow_path_from_name(name)
    if not os.path.exists(workflow_path):
        raise HTTPException(status_code=404, detail="Workflow not found")
    cfg_path = workflow_config_path(name)
    write_json_atomic(cfg_path, payload.dict(), ensure_ascii=False, indent=2)
    return {"config": payload.dict()}

@app.delete("/api/workflows/{name:path}")
def delete_workflow(name: str):
    if not WORKFLOW_NAME_RE.match(name):
        raise HTTPException(status_code=400, detail="Invalid workflow name")
    if is_builtin_workflow(name):
        raise HTTPException(status_code=400, detail="内置工作流不可删除")
    workflow_path = workflow_path_from_name(name)
    cfg_path = workflow_config_path(name)
    if not os.path.exists(workflow_path):
        raise HTTPException(status_code=404, detail="Workflow not found")
    os.remove(workflow_path)
    if os.path.exists(cfg_path):
        os.remove(cfg_path)
    return {"ok": True}

@app.post("/api/workflows/{name:path}/run")
def run_workflow(name: str, payload: WorkflowRunRequest):
    if not WORKFLOW_NAME_RE.match(name):
        raise HTTPException(status_code=400, detail="Invalid workflow name")
    if not os.path.exists(workflow_path_from_name(name)):
        raise HTTPException(status_code=404, detail="Workflow not found")
    # 根据 config 的字段把值映射成 params 节点覆盖
    params: Dict[str, Dict[str, Any]] = {}
    for field in payload.config.fields:
        if not field.node or not field.input:
            continue
        if field.id in payload.fields:
            value = payload.fields[field.id]
            # 类型转换
            if field.type in ("number", "slider"):
                try:
                    value = float(value) if (field.step and field.step < 1) else int(float(value))
                except Exception:
                    pass
            elif field.type == "boolean":
                value = bool(value)
            elif field.type == "dropdown":
                # 下拉值如果看起来是数字（如 "1024" / "2048" / "0.8"），自动转成 int/float
                if isinstance(value, str):
                    s = value.strip()
                    try:
                        if s and ('.' in s or 'e' in s.lower()):
                            value = float(s)
                        elif s and (s.lstrip('-').isdigit()):
                            value = int(s)
                    except (ValueError, TypeError):
                        pass
            params.setdefault(field.node, {})[field.input] = value
    req = GenerateRequest(
        prompt="",
        workflow_json=name,
        params=params,
        type="workflow-test",
        client_id=payload.client_id or str(uuid.uuid4()),
    )
    return generate(req)

# ═══ 存储位置（数据根目录）：数据库 / 画布 / 素材库 / 生成物都在这下面 ═══
# 设置写进稳定位置的 config.json（Windows %APPDATA%\NOVAI，其它 ~/.NOVAI），
# 不写进数据目录本身——否则数据目录一搬走，下次启动就读不到"数据在哪"了。
# 迁移策略：先完整复制到新位置并校验，再改配置；旧目录一个字节都不删，
# 失败时只清理这次新建的内容 → 随时可以回滚 / 手动搬回去。

def _human_bytes(size) -> str:
    try:
        value = float(size or 0)
    except (TypeError, ValueError):
        value = 0.0
    for unit in ("B", "KB", "MB", "GB"):
        if value < 1024:
            return f"{value:.0f} {unit}" if unit == "B" else f"{value:.1f} {unit}"
        value /= 1024.0
    return f"{value:.1f} TB"

def path_inside(root: str, path: str) -> bool:
    """path 是否在 root 里面（含相等）。跨盘 / 相对路径异常一律当 False。"""
    if not root or not path:
        return False
    try:
        root_abs = os.path.abspath(root)
        return os.path.commonpath([root_abs, os.path.abspath(path)]) == root_abs
    except Exception:
        return False

# ── 迁移范围：只搬 NOVAI 自己写的东西 ──────────────────────────────────
# 素材目录可能被旧版 storage_path 指到很宽的用户目录甚至整块盘 —— 所以 assets / output
# 只按已知子路径取；data / API 是数据根下 NOVAI 自己的固定目录，整目录搬（将来新增子
# 目录也不会漏），但仍跳过符号链接/junction 和明显无关的大目录，避免扫全盘、带走别人的文件。
_STORAGE_MAX_FILES = 200000
_STORAGE_SKIP_JUNK_FILES = {"thumbs.db", "desktop.ini"}
_STORAGE_SKIP_HEAVY_DIRS = {
    ".git", ".hg", ".svn", "node_modules", "__pycache__", ".venv", "venv", "env",
    ".idea", ".vscode", "system volume information", "$recycle.bin", ".trash",
    ".spotlight-v100", ".fseventsd", ".documentrevisions-v100",
}
_STORAGE_ASSETS_SUBDIRS = ("input", "output", "library", "uploads", "models", "users")
_STORAGE_ASSETS_FILES = ("asset_library.json", "assets_registry.json", "asset_hashes.json")
_STORAGE_OUTPUT_SUBDIRS = ("smart-groups",)
_STORAGE_MEDIA_EXTS = {
    ".png", ".jpg", ".jpeg", ".webp", ".gif", ".bmp", ".avif", ".svg", ".tif", ".tiff",
    ".mp4", ".mov", ".webm", ".mkv", ".avi", ".m4v", ".wmv",
    ".mp3", ".wav", ".m4a", ".aac", ".flac", ".ogg", ".opus",
}

class StorageScanTooLarge(RuntimeError):
    """要迁移的内容异常庞大：宁可停下来提示，也不静默扫全盘。"""

def _is_link_path(path: str) -> bool:
    """符号链接 / Windows junction 一律当链接：统计与复制都不跟随（避免越界到系统目录）。"""
    try:
        if os.path.islink(path):
            return True
        isjunction = getattr(os.path, "isjunction", None)
        if isjunction is not None and isjunction(path):
            return True
    except OSError:
        return True
    return False

def _storage_skip_entry(path: str, name: str) -> bool:
    """迁移时跳过的条目：链接/junction、系统垃圾文件、明显无关的大目录。"""
    raw_name = str(name or "")
    lowered = raw_name.lower()
    if _is_link_path(path):
        return True
    if lowered in _STORAGE_SKIP_JUNK_FILES or raw_name.startswith("._"):
        return True
    try:
        is_dir = os.path.isdir(path)
    except OSError:
        return True
    return bool(is_dir and lowered in _STORAGE_SKIP_HEAVY_DIRS)

def _tree_stats(path: str, limit: int = None) -> Dict[str, Any]:
    """统计一个迁移单位（文件/目录/白名单子项）的文件数与字节数。

    跳过链接/junction 与无关大目录；文件数超过 limit 直接抛 StorageScanTooLarge，
    不静默递归扫描（素材目录指到整块盘时会非常慢，必须尽早停）。
    """
    limit = _STORAGE_MAX_FILES if limit is None else limit
    stats: Dict[str, Any] = {"files": 0, "bytes": 0, "skipped_links": 0, "skipped_dirs": 0}
    if not path or not os.path.exists(path):
        return stats
    if os.path.isfile(path):
        if _is_link_path(path):
            stats["skipped_links"] += 1
            return stats
        try:
            stats["files"] = 1
            stats["bytes"] = os.path.getsize(path)
        except OSError:
            pass
        return stats
    pending = [path]
    while pending:
        current = pending.pop()
        try:
            names = os.listdir(current)
        except OSError:
            continue
        for name in names:
            full = os.path.join(current, name)
            if _storage_skip_entry(full, name):
                if _is_link_path(full):
                    stats["skipped_links"] += 1
                else:
                    stats["skipped_dirs"] += 1
                continue
            try:
                if os.path.isdir(full):
                    pending.append(full)
                    continue
                stats["bytes"] += os.path.getsize(full)
            except OSError:
                continue
            stats["files"] += 1
            if stats["files"] > limit:
                raise StorageScanTooLarge(
                    f"要迁移的内容超过 {limit} 个文件，已经停止统计。"
                    "素材目录或生成目录可能指到了整块盘/很大的用户目录，请换一个更具体的文件夹。"
                )
    return stats

def _storage_subpath_includes(root: str, subdirs, files=()) -> List[Dict[str, str]]:
    """已知子目录 + 已知文件（只做一层判断，不递归枚举 → 宽目录也很快）。"""
    items: List[Dict[str, str]] = []
    for name in list(subdirs) + list(files):
        full = os.path.join(root, name)
        if _is_link_path(full) or not os.path.exists(full):
            continue
        items.append({"rel": name, "path": full, "kind": "file" if os.path.isfile(full) else "dir"})
    return items

def _storage_media_includes(root: str) -> List[Dict[str, str]]:
    """自定义生成目录的顶层只认生成媒体文件（图片/视频/音频），其它目录不递归。"""
    items: List[Dict[str, str]] = []
    try:
        names = sorted(os.listdir(root), key=str.lower)
    except OSError:
        return items
    for name in names:
        full = os.path.join(root, name)
        if _is_link_path(full) or not os.path.isfile(full):
            continue
        if os.path.splitext(name)[1].lower() in _STORAGE_MEDIA_EXTS:
            items.append({"rel": name, "path": full, "kind": "file"})
    return items

def _entry_stats(entry: Dict[str, Any]) -> Dict[str, Any]:
    """一个迁移单位实际要搬的统计：full=整目录，includes=白名单子项之和。"""
    if entry.get("mode") == "full":
        return _tree_stats(entry["source"])
    stats: Dict[str, Any] = {"files": 0, "bytes": 0, "skipped_links": 0, "skipped_dirs": 0}
    for item in entry.get("includes") or []:
        part = _tree_stats(item["path"])
        for key in ("files", "bytes", "skipped_links", "skipped_dirs"):
            stats[key] += part[key]
    return stats

def _explain_os_error(exc: BaseException) -> str:
    """把系统错误翻成用户看得懂的中文（原始错误塞在括号里，方便我们排查）。"""
    if isinstance(exc, PermissionError):
        where = str(getattr(exc, "filename", "") or "").strip()
        return "没有写入权限" + (f"（{where}）" if where else "") + "，请换一个有写权限的文件夹"
    if isinstance(exc, OSError) and getattr(exc, "errno", None) in (28, 112):
        return "磁盘空间不足"
    text = str(exc).strip()
    return text[:300] if text else type(exc).__name__

def _free_bytes_for(path: str) -> int:
    probe = os.path.abspath(path)
    while probe and not os.path.exists(probe):
        parent = os.path.dirname(probe)
        if parent == probe:
            return 0
        probe = parent
    try:
        return int(shutil.disk_usage(probe).free)
    except Exception:
        return 0

def storage_location_entries() -> List[Dict[str, Any]]:
    """会跟着数据根目录搬走的条目：目标结构不变（新根/data、assets、output、API、history.json）。

    - data / API：数据根下 NOVAI 自己的固定目录 → 整目录搬（新版本加子目录也不会漏），
      只跳过链接/junction 与明显无关的大目录；
    - assets / output：可能被旧版 storage_path 或自定义输出目录指到很宽的位置 → 只取已知子项。
    """
    entries: List[Dict[str, Any]] = []
    seen = set()

    def add(name: str, source: str, mode: str, includes=None, origin: str = "") -> None:
        if not name or name in seen or not os.path.exists(source):
            return
        seen.add(name)
        entries.append({
            "name": name,
            "source": os.path.abspath(source),
            "kind": "file" if os.path.isfile(source) else "dir",
            "mode": mode,
            "includes": list(includes or []),
            "origin": origin,
        })

    add("data", DATA_DIR, "full", origin="data")
    add("API", os.path.join(_DATA_ROOT, "API"), "full", origin="api")
    if path_inside(_DATA_ROOT, OUTPUT_DIR):
        # 输出目录在数据根之外时它有自己的设置，界面口径仍把它算作迁移项（只是内容过滤）
        add("output", OUTPUT_DIR, "includes",
            includes=_storage_subpath_includes(OUTPUT_DIR, _STORAGE_OUTPUT_SUBDIRS) + _storage_media_includes(OUTPUT_DIR),
            origin="output")
    assets_inside = path_inside(_DATA_ROOT, ASSETS_DIR)
    if not (assets_inside and same_fs_path(ASSETS_DIR, _DATA_ROOT)):
        add(os.path.relpath(ASSETS_DIR, _DATA_ROOT) if assets_inside else "assets",
            ASSETS_DIR, "includes",
            includes=_storage_subpath_includes(ASSETS_DIR, _STORAGE_ASSETS_SUBDIRS, _STORAGE_ASSETS_FILES),
            origin="assets")
    add("history.json", HISTORY_FILE, "full", origin="history")
    return entries

# ── 老用户首次启动：是否把用户目录里的旧数据迁到安装目录（只问一次）──────────
# 回答写进稳定配置 config.json 的 install_migration_prompt，之后不再问。
# 只在「数据根还在用户目录、安装目录可写、安装目录没有已有数据、还没回答过」时 offer；
# 新装用户由默认数据根逻辑直接落在安装目录，不需要问。
_INSTALL_MIGRATION_ANSWER_KEY = "install_migration_prompt"

def _user_home_dir() -> str:
    try:
        return os.path.expanduser("~")
    except Exception:
        return ""

def _install_migration_target_root() -> str:
    """安装目录（迁移目标）。只认 NOVAI_INSTALL_DIR（桌面壳在打包态注入）。

    不用 NOVAI_APP_DIR：它是程序资源目录（mac 的 .app 包内 / resources/backend），
    升级会被整体替换，绝不能把用户数据放进去。
    """
    return absolute_path(os.environ.get("NOVAI_INSTALL_DIR", ""))

def _install_root_has_user_data(root: str) -> bool:
    """安装目录里是否已经有用户数据：有就绝不 offer，避免覆盖或和已有数据合并。"""
    if not root or not os.path.isdir(root):
        return False
    checks = (
        os.path.isdir(os.path.join(root, "data", "canvases")),
        os.path.isfile(os.path.join(root, "data", "users.db")),
        os.path.isfile(os.path.join(root, "data", "settings.json")),
        os.path.isfile(os.path.join(root, "data", "asset_library.json")),
        os.path.isfile(os.path.join(root, "history.json")),
        os.path.isfile(os.path.join(root, "API", ".env")),
    )
    return any(checks)

def _install_migration_answered(cfg: Optional[Dict[str, Any]] = None) -> bool:
    cfg = cfg if isinstance(cfg, dict) else load_storage_config()
    answer = cfg.get(_INSTALL_MIGRATION_ANSWER_KEY)
    return bool(isinstance(answer, dict) and answer.get("answered"))

def _install_migration_offer(cfg: Optional[Dict[str, Any]] = None,
                             total: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """启动提示的判定 + 说明（当前路径 / 目标路径 / 占用）。占用复用 info 已经算好的
    扫描结果，不为了弹窗再扫一遍盘。"""
    cfg = cfg if isinstance(cfg, dict) else load_storage_config()
    target = _install_migration_target_root()
    home = _user_home_dir()
    offer: Dict[str, Any] = {
        "offer": False,
        "reason": "",
        "current_root": _DATA_ROOT,
        "target_root": target,
        "target_writable": False,
        "target_has_data": _install_root_has_user_data(target) if target else False,
        "total": dict(total or {}),
        "free_bytes": _free_bytes_for(target or _DATA_ROOT),
        "restart_required": True,
    }

    def deny(reason: str) -> Dict[str, Any]:
        offer["reason"] = reason
        return offer

    if _install_migration_answered(cfg):
        return deny("answered")
    if not target:
        return deny("no_install_dir")
    if same_fs_path(_DATA_ROOT, target) or path_inside(target, _DATA_ROOT):
        return deny("already_installed")
    if not home or not path_inside(home, _DATA_ROOT):
        return deny("not_in_user_home")
    # 配置里的位置和"现在正在用的位置"不一样（用户自己选的别处，或外置盘没插上）：
    # 尊重既有选择，不拿它当旧默认位置劝迁移。反过来，老用户被自动钉在用户目录
    # （配置里就是当前这个路径）仍要 offer —— 那正是这次提示的目标人群。
    configured = absolute_path(cfg.get("data_root", ""))
    if configured and not same_fs_path(configured, _DATA_ROOT):
        return deny("configured")
    if offer["target_has_data"]:
        return deny("target_has_data")
    if not _dir_writable(target):
        return deny("target_not_writable")
    offer["target_writable"] = True
    offer["offer"] = True
    offer["reason"] = "ok"
    return offer

def _write_install_migration_answer(choice: str) -> None:
    cfg = load_storage_config()
    cfg[_INSTALL_MIGRATION_ANSWER_KEY] = {
        "answered": True,
        "choice": choice,
        "answered_at": datetime.datetime.now().isoformat(timespec="seconds"),
    }
    _write_storage_config(cfg)

def storage_install_offer_answer(payload: Dict[str, Any]) -> Dict[str, Any]:
    """回答「要不要把数据迁到安装目录」：keep 只记回答；migrate 先迁移、成功后才记回答。

    迁移复用设置页同一套实现（复制 + 逐项校验 + 失败撤回 + 写 data_root）；失败会抛
    HTTPException，此时 config.json 里不会留下 install_migration_prompt，下次启动还能再问。
    """
    choice = str((payload or {}).get("choice") or "").strip().lower()
    if choice not in ("migrate", "keep"):
        raise HTTPException(status_code=400, detail="choice 只能是 migrate 或 keep")
    if choice == "keep":
        _write_install_migration_answer("keep")
        return {
            "ok": True,
            "choice": "keep",
            "answered": True,
            "message": "好的，数据继续留在当前目录，之后不再提示。",
            "restart_required": False,
            "install_migration_offer": _install_migration_offer(),
        }
    target = _install_migration_target_root()
    if not target:
        raise HTTPException(status_code=400, detail="找不到安装目录，无法迁移")
    # allow_install_root 只放行「安装目录本身」；用户在设置页手选的目录仍要求是空的
    result = storage_location_move({"path": target}, allow_install_root=True)
    _write_install_migration_answer("migrated")
    result["choice"] = "migrated"
    result["answered"] = True
    result["install_migration_offer"] = _install_migration_offer()
    return result

def storage_location_info() -> Dict[str, Any]:
    """当前实际存储位置 + 可迁移内容清单。前端设置页 / 素材库路径条共用。"""
    cfg = load_storage_config()
    configured = absolute_path(cfg.get("data_root", ""))
    previous = absolute_path(cfg.get("data_root_previous", ""))
    legacy_assets = absolute_path(cfg.get("storage_path", ""))
    legacy_import = legacy_assets_imported(cfg) or {}
    items = []
    too_large_entries = []
    for entry in storage_location_entries():
        try:
            stats = _entry_stats(entry)
            too_large = False
        except StorageScanTooLarge:
            stats = {"files": 0, "bytes": 0, "skipped_links": 0, "skipped_dirs": 0}
            too_large = True
            too_large_entries.append(entry["name"])
        item = {
            "name": entry["name"],
            "kind": entry["kind"],
            "source": entry["source"],
            "origin": entry["origin"],
            "mode": entry["mode"],
            "files": stats["files"],
            "bytes": stats["bytes"],
            "skipped_links": stats["skipped_links"],
            "skipped_dirs": stats["skipped_dirs"],
            "too_large": too_large,
        }
        if entry["mode"] == "includes":
            item["includes"] = [sub["rel"] for sub in entry["includes"]]
        items.append(item)
    warning = _STORAGE_CONFIG_WARNING
    if too_large_entries:
        warning = (warning + " " if warning else "") + (
            "这些目录文件数异常庞大（" + "、".join(too_large_entries)
            + "），已停止统计、迁移会被拒绝：请检查素材/生成目录是否指到了整块盘或过大的用户目录。")
    if ASSETS_DIR_SOURCE == "install_legacy":
        warning = (warning + " " if warning else "") + (
            "素材库还是升级前的位置（当初新装时放在安装目录旁）：" + ASSETS_DIR
            + "。画布和素材都照常可用；想统一到数据目录，在下面迁移一次即可。")
    elif ASSETS_DIR_SOURCE == "legacy_imported":
        warning = (warning + " " if warning else "") + (
            "已把旧版素材搬到 " + ASSETS_DIR + "，旧位置保留未删"
            + ("（" + str(legacy_import.get("from")) + "）" if legacy_import.get("from") else "")
            + "。")
    elif not path_inside(_DATA_ROOT, ASSETS_DIR):
        warning = (warning + " " if warning else "") + (
            "素材目录是旧版单独设置的位置（" + ASSETS_DIR + "），迁移时只带走其中的 "
            "input/output/library/uploads/models/users 等 NOVAI 内容，其它文件留在原位置。")
    if not path_inside(_DATA_ROOT, OUTPUT_DIR):
        warning = (warning + " " if warning else "") + (
            "生成目录是单独设置的位置（" + OUTPUT_DIR + "），迁移时只带走生成媒体和已知子目录（smart-groups）。")
    if legacy_assets and os.path.isdir(legacy_assets):
        warning = (warning + " " if warning else "") + (
            "素材目录仍是旧版单独设置的位置：" + legacy_assets
            + "。在下面迁移一次即可统一到新位置。")
    if _DATA_ROOT_SOURCE == "env" and not same_fs_path(_DATA_DIR_OVERRIDE, configured):
        warning = (warning + " " if warning else "") + (
            "当前进程的数据目录由环境变量 NOVAI_DATA_DIR 指定（" + _DATA_DIR_OVERRIDE
            + "）。界面里的设置会写进配置，但要等环境变量去掉后重启才会生效。")
    total = {
        "files": sum(item["files"] for item in items),
        "bytes": sum(item["bytes"] for item in items),
    }
    return {
        "path": _DATA_ROOT,
        "data_root": _DATA_ROOT,
        "data_root_source": _DATA_ROOT_SOURCE,
        "configured_data_root": configured,
        "previous_data_root": previous,
        # 回滚是把「配置」指回上一次的位置：只要它和当前配置不同、目录还在，就有意义
        # （进程还没重启时实际路径仍是旧的，所以不能拿 _DATA_ROOT 比较）。
        "can_rollback": bool(previous) and os.path.isdir(previous) and not same_fs_path(previous, configured),
        "default_data_root": default_data_root(),
        "config_file": STORAGE_CONFIG_FILE,
        "config_dir": STABLE_CONFIG_DIR,
        "restart_required": bool(configured) and not same_fs_path(configured, _DATA_ROOT),
        "env_data_dir": _DATA_DIR_OVERRIDE,
        "legacy_storage_path": legacy_assets,
        "warning": warning,
        "assets_dir": ASSETS_DIR,
        # 素材到底在哪：data_root / config（配过 data_root）/ install_legacy（升级前就在
        # 安装目录旁）/ legacy_config（旧版 storage_path 设置）/ legacy_imported（macOS 已把
        # 旧版 .app 包内素材复制到数据根）。设置页据此如实说明。
        "assets_source": ASSETS_DIR_SOURCE,
        "assets_install_legacy": ASSETS_DIR_SOURCE == "install_legacy",
        "assets_legacy_imported": ASSETS_DIR_SOURCE == "legacy_imported",
        "assets_legacy_imported_from": str(legacy_import.get("from") or "") if legacy_import else "",
        "assets_input": OUTPUT_INPUT_DIR,
        "assets_output": OUTPUT_OUTPUT_DIR,
        "library_dir": ASSET_LIBRARY_DIR,
        "uploads_dir": LOCAL_UPLOAD_DIR,
        "output_dir": OUTPUT_DIR,
        "data_dir": DATA_DIR,
        "canvas_dir": CANVAS_DIR,
        "conversation_dir": CONVERSATION_DIR,
        "items": items,
        "total": total,
        # 设置页 / 素材库都用这个 info；老用户启动提示也读它（answered 后恒为 offer=False）
        "install_migration_offer": _install_migration_offer(cfg, total),
        "free_bytes": _free_bytes_for(_DATA_ROOT),
    }

def _looks_like_novai_data_root(path: str) -> bool:
    """判断一个目录是不是以前用过的 NOVAI 数据根（切换过去之前用来确认，避免把无关目录当数据目录）。"""
    checks = (
        os.path.isdir(os.path.join(path, "data", "canvases")),
        os.path.isfile(os.path.join(path, "data", "asset_library.json")),
        os.path.isfile(os.path.join(path, "data", "settings.json")),
        os.path.isfile(os.path.join(path, "history.json")),
        os.path.isfile(os.path.join(path, "API", ".env")),
        os.path.isdir(os.path.join(path, "assets", "library")),
        os.path.isdir(os.path.join(path, "assets", "output")),
    )
    return sum(1 for matched in checks if matched) >= 2

def _storage_target_plan(target: str, allow_install_root: bool = False) -> Dict[str, Any]:
    """校验新位置并给出方案：copy（空目录，复制过去）或 adopt（已有 NOVAI 数据，直接切过去）。

    allow_install_root 只给「迁到安装目录」用：安装目录里本来就有程序文件，不可能为空，
    但它没有用户数据（调用方已检查），复制进去是安全的；用户在设置页手选的目录仍必须是空的。
    """
    raw = str(target or "").strip()
    if not raw:
        raise HTTPException(status_code=400, detail="路径不能为空")
    expanded = os.path.expanduser(os.path.expandvars(raw))
    # 必须是绝对路径：相对路径会被 abspath 解析到进程工作目录（源码版就是仓库），
    # 真的往那儿迁移/复制会让用户以为选的是别处。
    if not os.path.isabs(expanded):
        raise HTTPException(
            status_code=400,
            detail="请填写完整的绝对路径（例如 D:\\NOVAI 或 /Volumes/Data/NOVAI），不要只写文件夹名",
        )
    target_abs = absolute_path(raw)
    if not target_abs:
        raise HTTPException(status_code=400, detail="路径不能为空")
    if same_fs_path(target_abs, _DATA_ROOT):
        raise HTTPException(status_code=400, detail="新位置和当前数据目录是同一个文件夹，不用迁移")
    if path_inside(_DATA_ROOT, target_abs):
        raise HTTPException(status_code=400, detail="新位置不能放在当前数据目录里面，请选另一个文件夹")
    if path_inside(target_abs, _DATA_ROOT):
        raise HTTPException(status_code=400, detail="新位置不能把当前数据目录包在里面，请选另一个文件夹")
    if os.path.exists(target_abs) and not os.path.isdir(target_abs):
        raise HTTPException(status_code=400, detail=f"目标路径上已有同名文件，不能当目录用：{target_abs}")
    # 先探写入权限：别等复制到一半才失败（失败也不会丢数据，但让用户白等）
    writable_probe = target_abs if os.path.isdir(target_abs) else (os.path.dirname(target_abs) or target_abs)
    if os.path.exists(writable_probe) and not os.access(writable_probe, os.W_OK):
        raise HTTPException(status_code=400, detail=f"没有写入权限：{writable_probe}。请换一个有写权限的文件夹，或换一个盘。")
    entries = storage_location_entries()
    for entry in entries:
        to_check = [entry["source"]] if entry["mode"] == "full" else [item["path"] for item in entry["includes"]]
        for candidate in to_check:
            if path_inside(candidate, target_abs):
                raise HTTPException(status_code=400, detail=f"新位置不能放在要迁移的「{entry['name']}」目录里面")
    try:
        # 隐藏文件（.DS_Store / .localized 等）不算占用：用户在访达/资源管理器里新建的空文件夹
        existing = [name for name in os.listdir(target_abs) if not name.startswith(".")] if os.path.isdir(target_abs) else []
    except OSError as exc:
        raise HTTPException(status_code=400, detail=f"读不到目标文件夹：{_explain_os_error(exc)}") from exc
    install_root = _install_migration_target_root() if allow_install_root else ""
    allow_non_empty = bool(install_root) and same_fs_path(target_abs, install_root)
    if existing and not _looks_like_novai_data_root(target_abs) and not allow_non_empty:
        raise HTTPException(status_code=400, detail=(
            f"目标文件夹不是空的（{len(existing)} 项），也不是 NOVAI 的数据目录，所以不会往里搬"
            "（避免和你的其它文件混在一起）。请新建一个空文件夹再选（只有隐藏文件不影响），"
            "或者选择以前用过的 NOVAI 数据文件夹——那种情况会直接切换过去，不会和现有数据合并、也不会覆盖。"))
    action = "adopt" if existing and _looks_like_novai_data_root(target_abs) else "copy"
    warnings: List[str] = []
    total_files = 0
    total_bytes = 0
    for entry in entries:
        try:
            stats = _entry_stats(entry)
        except StorageScanTooLarge as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        entry["files"] = stats["files"]
        entry["bytes"] = stats["bytes"]
        entry["skipped_links"] = stats["skipped_links"]
        entry["skipped_dirs"] = stats["skipped_dirs"]
        total_files += stats["files"]
        total_bytes += stats["bytes"]
        if stats["skipped_links"]:
            warnings.append(f"{entry['name']} 里有 {stats['skipped_links']} 个符号链接/junction，已跳过（不会跟到新位置）")
        if entry["mode"] == "full" and stats["skipped_dirs"]:
            warnings.append(f"{entry['name']} 里跳过了 {stats['skipped_dirs']} 个无关大目录（如 node_modules/.git）")
    if total_files > _STORAGE_MAX_FILES:
        raise HTTPException(status_code=400, detail=(
            f"要迁移的文件超过 {_STORAGE_MAX_FILES} 个（{total_files} 个），已拒绝执行。"
            "素材目录或生成目录可能指到了整块盘/很大的用户目录，请换一个更具体的文件夹。"))
    if not path_inside(_DATA_ROOT, ASSETS_DIR):
        warnings.append("素材目录是旧版单独设置的位置，只迁移 input/output/library/uploads/models/users 等 NOVAI 内容，其它文件保持原位")
    if not path_inside(_DATA_ROOT, OUTPUT_DIR):
        warnings.append("生成目录是单独设置的位置，只迁移生成媒体和已知子目录（smart-groups），其它文件保持原位")
    free = _free_bytes_for(os.path.dirname(target_abs) or target_abs)
    if action == "copy" and total_bytes and free and free < total_bytes:
        raise HTTPException(status_code=400, detail=(
            f"新位置剩余空间不够：需要约 {_human_bytes(total_bytes)}，只剩 {_human_bytes(free)}。"
            "请换一个盘或先清理空间。"))
    return {
        "action": action,
        "target": target_abs,
        "entries": entries,
        "total": {"files": total_files, "bytes": total_bytes},
        "free_bytes": free,
        "warnings": warnings,
    }

def _storage_copy_ignore(directory: str, names) -> List[str]:
    """copytree 的 ignore 回调：链接/junction、系统垃圾、无关大目录都不复制。"""
    return [name for name in names if _storage_skip_entry(os.path.join(directory, name), name)]

def _copy_tree_filtered(src: str, dst: str) -> None:
    os.makedirs(dst, exist_ok=True)
    # symlinks=False 是要求"遇到链接跟着内容"，我们已经在 ignore 里剔掉了，所以不会发生
    shutil.copytree(src, dst, dirs_exist_ok=True, symlinks=False, ignore=_storage_copy_ignore)

def _copy_storage_entry(entry: Dict[str, Any], target_abs: str) -> None:
    """按迁移单位复制：full=整目录（过滤链接/无关大目录），includes=白名单子项。"""
    dst_root = os.path.join(target_abs, entry["name"])
    if entry["kind"] == "file":
        os.makedirs(os.path.dirname(dst_root), exist_ok=True)
        shutil.copy2(entry["source"], dst_root)
        return
    if entry["mode"] == "full":
        _copy_tree_filtered(entry["source"], dst_root)
        return
    os.makedirs(dst_root, exist_ok=True)
    for item in entry["includes"]:
        dst = os.path.join(dst_root, item["rel"])
        if item["kind"] == "file":
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            shutil.copy2(item["path"], dst)
        else:
            _copy_tree_filtered(item["path"], dst)

def _verify_tree(src: str, dst: str) -> bool:
    """逐文件比对大小（同样跳过链接/无关大目录）；缺失或大小不一致都算失败。"""
    if os.path.isfile(src):
        try:
            return os.path.getsize(dst) == os.path.getsize(src)
        except OSError:
            return False
    bad = 0
    pending = [("", src)]
    while pending:
        rel_base, current = pending.pop()
        try:
            names = os.listdir(current)
        except OSError:
            return False
        for name in names:
            full = os.path.join(current, name)
            if _storage_skip_entry(full, name):
                continue
            rel = os.path.join(rel_base, name) if rel_base else name
            target = os.path.join(dst, rel)
            try:
                if os.path.isdir(full):
                    pending.append((rel, full))
                    continue
                if os.path.getsize(target) != os.path.getsize(full):
                    bad += 1
            except OSError:
                bad += 1
            if bad > 5:
                return False
    return bad == 0

def _verify_storage_copy(entry: Dict[str, Any], target_abs: str) -> bool:
    """校验复制结果：full 整目录比对，includes 逐个白名单子项比对。"""
    dst_root = os.path.join(target_abs, entry["name"])
    if entry["kind"] == "file" or entry["mode"] == "full":
        return _verify_tree(entry["source"], dst_root)
    for item in entry["includes"]:
        if not _verify_tree(item["path"], os.path.join(dst_root, item["rel"])):
            return False
    return True

def _rewrite_copied_paths(target_abs: str, entries: List[Dict[str, Any]]) -> List[str]:
    """把复制过去的数据里存的绝对路径改到新根（否则重启后自定义输出/素材子目录仍指旧位置）。"""
    warnings: List[str] = []

    def remap(value: str) -> str:
        path = absolute_path(value)
        if not path:
            return ""
        for entry in entries:
            # 指向目录本身（例如自定义输出目录 = 整个 output）→ 直接映射到新根同名目录
            if same_fs_path(path, entry["source"]):
                return os.path.join(target_abs, entry["name"])
            if entry["mode"] == "full":
                if path_inside(entry["source"], path):
                    rel = os.path.relpath(path, entry["source"])
                    return os.path.join(target_abs, entry["name"], rel)
                continue
            for item in entry["includes"]:
                if path_inside(item["path"], path):
                    rel = os.path.relpath(path, item["path"])
                    base = os.path.join(target_abs, entry["name"], item["rel"])
                    return base if rel == "." else os.path.join(base, rel)
        return ""

    settings_path = os.path.join(target_abs, "data", "settings.json")
    try:
        if os.path.isfile(settings_path):
            with open(settings_path, "r", encoding="utf-8-sig") as f:
                settings = json.load(f)
            if isinstance(settings, dict):
                custom = absolute_path(settings.get("output_dir", ""))
                if custom:
                    mapped = remap(custom)
                    if mapped:
                        settings["output_dir"] = mapped
                        write_json_atomic(settings_path, settings, ensure_ascii=False, indent=2)
                    else:
                        warnings.append(f"生成文件目录仍是单独设置的位置（{custom}），没有跟着迁移。")
    except Exception as exc:
        warnings.append(f"更新 settings.json 里的路径失败：{exc}")

    storage_settings_path = os.path.join(target_abs, "data", "storage_settings.json")
    try:
        if os.path.isfile(storage_settings_path):
            with open(storage_settings_path, "r", encoding="utf-8-sig") as f:
                dirs = json.load(f)
            if isinstance(dirs, dict):
                changed = False
                for key in ("upload", "generated", "local"):
                    current = absolute_path(dirs.get(key, ""))
                    if not current:
                        continue
                    mapped = remap(current)
                    if mapped:
                        dirs[key] = mapped
                        changed = True
                    else:
                        warnings.append(f"素材子目录 {key} 仍是单独设置的位置（{current}），没有跟着迁移。")
                if changed:
                    write_json_atomic(storage_settings_path, dirs, ensure_ascii=False, indent=2)
    except Exception as exc:
        warnings.append(f"更新 storage_settings.json 里的路径失败：{exc}")
    return warnings

def _checkpoint_sqlite(db_path: str) -> int:
    """连接库做一次 wal_checkpoint(TRUNCATE)，返回 busy 标记（0 = 全部落盘）。"""
    import sqlite3
    conn = sqlite3.connect(db_path, timeout=15)
    try:
        row = conn.execute("PRAGMA wal_checkpoint(TRUNCATE)").fetchone() or (0, 0, 0)
        return int(row[0] or 0)
    finally:
        conn.close()

def _storage_sync_sqlite_before_copy() -> List[str]:
    """复制 data 之前把 users.db 的 WAL 落盘：直接拷一个带未 checkpoint 写入的库，
    拿到的可能是缺最近事务的快照（WAL 模式下数据在 -wal 里）。同步不了就中止迁移。"""
    db_path = os.path.join(DATA_DIR, "users.db")
    if not os.path.isfile(db_path):
        return []
    try:
        busy = _checkpoint_sqlite(db_path)
    except Exception as exc:
        raise RuntimeError(
            "同步数据库失败（users.db 可能被占用），已中止迁移，数据没有改动："
            + _explain_os_error(exc)
        ) from exc
    if busy:
        raise RuntimeError("同步数据库失败：users.db 还有写入没落盘，请等生成/保存任务停下来再试一次")
    wal_path = db_path + "-wal"
    try:
        if os.path.isfile(wal_path) and os.path.getsize(wal_path) > 0:
            raise RuntimeError("同步数据库失败：WAL 文件还没清空，请稍后重试")
    except OSError:
        pass
    return ["数据库已同步（WAL checkpoint TRUNCATE）"]

def _verify_sqlite_quick_check(db_path: str) -> bool:
    """只读打开复制过来的库跑 PRAGMA quick_check；不是 ok 就判复制失败、按迁移失败回滚。"""
    import sqlite3
    uri = "file:" + urllib.parse.quote(os.path.abspath(db_path)) + "?mode=ro"
    conn = None
    try:
        conn = sqlite3.connect(uri, uri=True, timeout=15)
        rows = conn.execute("PRAGMA quick_check").fetchall()
    except Exception:
        return False
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
    return bool(rows) and all(str(row[0]).strip().lower() == "ok" for row in rows)

def _write_storage_config(config: Dict[str, Any]) -> None:
    os.makedirs(STABLE_CONFIG_DIR, exist_ok=True)
    write_json_atomic(STORAGE_CONFIG_FILE, config, ensure_ascii=False, indent=2)

def storage_location_move(payload: Dict[str, Any], allow_install_root: bool = False) -> Dict[str, Any]:
    """设置新的存储位置：dry_run 只算方案；否则复制 + 校验 + 写配置（旧目录保留）。

    allow_install_root 仅供「迁到安装目录」的一次性提示复用，透传给 _storage_target_plan。
    """
    payload = payload or {}
    dry_run = bool(payload.get("dry_run"))
    target = str(payload.get("path") or payload.get("data_root") or "").strip()
    if not target:
        cfg = load_storage_config()
        cfg.pop("data_root", None)
        cfg.pop("storage_path", None)
        cfg.pop("data_root_previous", None)
        _write_storage_config(cfg)
        return {
            "ok": True,
            "reset": True,
            "path": default_data_root(),
            "data_root": default_data_root(),
            "message": "已恢复默认存储位置，重启 NOVAI 后生效。",
            "restart_required": True,
        }
    plan = _storage_target_plan(target, allow_install_root=allow_install_root)
    if dry_run:
        result = {"ok": True, "dry_run": True, "restart_required": True}
        result.update(plan)
        return result

    target_abs = plan["target"]
    old_root = _DATA_ROOT
    created_target = not os.path.exists(target_abs)
    copied: List[Tuple[Dict[str, Any], str, bool]] = []
    db_notes: List[str] = []
    try:
        os.makedirs(target_abs, exist_ok=True)
        if plan["action"] == "copy":
            # 先把 users.db 的 WAL 落盘，再复制：不然拷到的是缺最近写入的快照
            db_notes = _storage_sync_sqlite_before_copy()
            for entry in plan["entries"]:
                dst = os.path.join(target_abs, entry["name"])
                copied.append((entry, dst, os.path.exists(dst)))
                _copy_storage_entry(entry, target_abs)
            for entry, _dst, _existed in copied:
                if not _verify_storage_copy(entry, target_abs):
                    raise RuntimeError(f"复制校验没通过：{entry['name']}")
            target_db = os.path.join(target_abs, "data", "users.db")
            if os.path.isfile(target_db):
                if not _verify_sqlite_quick_check(target_db):
                    raise RuntimeError("数据库校验没通过（quick_check 不是 ok），复制时库可能还在写")
                db_notes.append("目标数据库 quick_check 正常")
        warnings = list(plan.get("warnings") or []) + _rewrite_copied_paths(target_abs, plan["entries"])
        if plan["action"] != "copy":
            existing_db = os.path.join(target_abs, "data", "users.db")
            if os.path.isfile(existing_db) and not _verify_sqlite_quick_check(existing_db):
                warnings.append("目标位置的 users.db 校验没通过（quick_check 不是 ok），切换后请检查账号数据")
    except Exception as exc:
        # 回滚：只清理这次复制出来的内容，旧目录完全不碰
        for entry, dst, existed in reversed(copied):
            if existed:
                continue
            try:
                if os.path.isdir(dst):
                    shutil.rmtree(dst, ignore_errors=True)
                elif os.path.isfile(dst):
                    os.remove(dst)
            except Exception:
                pass
        if created_target:
            try:
                if not os.listdir(target_abs):
                    os.rmdir(target_abs)
            except Exception:
                pass
        raise HTTPException(
            status_code=500,
            detail=f"迁移失败，已经撤回改动，原数据完好：{_explain_os_error(exc)}",
        ) from exc

    cfg = load_storage_config()
    cfg["data_root"] = target_abs
    if not same_fs_path(old_root, target_abs):
        cfg["data_root_previous"] = old_root
    cfg.pop("storage_path", None)
    cfg["updated_at"] = datetime.datetime.now().isoformat(timespec="seconds")
    _write_storage_config(cfg)
    summary = "；".join(
        f"{entry['name']} {entry['files']} 个文件（{_human_bytes(entry['bytes'])}）"
        for entry in plan["entries"]
    ) or "没有需要复制的内容"
    if plan["action"] == "adopt":
        message = (f"已切换到已有的数据目录 {target_abs}。当前数据没有删除，仍保留在 {old_root}。"
                   "重启 NOVAI 后生效。")
    else:
        database_note = ("；" + "，".join(db_notes)) if db_notes else ""
        message = (f"已复制到 {target_abs}：{summary}{database_note}。只搬 NOVAI 自己的数据，"
                   "无关文件、符号链接/junction 都留在原位置。"
                   f"旧目录 {old_root} 保留作备份，确认没问题后可以自己删掉。重启 NOVAI 后生效。")
    return {
        "ok": True,
        "path": target_abs,
        "data_root": target_abs,
        "action": plan["action"],
        "database": "；".join(db_notes),
        "migrated": plan["total"],
        "entries": [{"name": entry["name"], "mode": entry["mode"], "files": entry["files"], "bytes": entry["bytes"]}
                    for entry in plan["entries"]],
        "kept_old": plan["action"] == "copy",
        "old_root": old_root,
        "warnings": warnings,
        "message": message,
        "restart_required": True,
    }

def storage_location_rollback() -> Dict[str, Any]:
    """回滚到上一次迁移前的位置（旧数据从来没删，所以只是把配置指回去）。"""
    cfg = load_storage_config()
    previous = absolute_path(cfg.get("data_root_previous", ""))
    if not previous or not os.path.isdir(previous):
        raise HTTPException(status_code=400, detail="没有可回滚的上一次位置（或那个文件夹已经不在了）")
    current = absolute_path(cfg.get("data_root", ""))
    cfg["data_root"] = previous
    if current and not same_fs_path(current, previous):
        cfg["data_root_previous"] = current
    else:
        cfg.pop("data_root_previous", None)
    cfg.pop("storage_path", None)
    cfg["updated_at"] = datetime.datetime.now().isoformat(timespec="seconds")
    _write_storage_config(cfg)
    return {
        "ok": True,
        "path": previous,
        "data_root": previous,
        "message": f"已回滚到 {previous}，重启 NOVAI 后生效。",
        "restart_required": True,
    }

@app.get("/api/config/storage")
async def get_storage_path():
    return await asyncio.to_thread(storage_location_info)

@app.post("/api/config/storage")
async def set_storage_path(data: dict):
    return await asyncio.to_thread(storage_location_move, data or {})

@app.post("/api/config/storage/rollback")
async def rollback_storage_path():
    return await asyncio.to_thread(storage_location_rollback)

# 老用户首次启动的一次性提示：回答「要不要把数据迁到安装目录」（keep / migrate）。
# 回答写进稳定配置，迁移失败不写 → 下次启动还能再问。
@app.post("/api/config/storage/install-offer")
async def answer_storage_install_offer(data: dict):
    return await asyncio.to_thread(storage_install_offer_answer, data or {})


