def _agent_tool_get_canvas_validate(args):
    canvas_id = str(args.get("canvas_id") or "").strip()
    if not canvas_id:
        raise AgentToolError("canvas_id 不能为空", code="invalid_args")
    load_canvas(canvas_id)  # 404 校验（含软删除）
    return {"canvas_id": canvas_id}


