_AGENT_NODE_TYPE_MAP = {
    "smart": {"image": "smart-image", "prompt": "smart-prompt", "video": "smart-video"},
    "classic": {"image": "image", "prompt": "prompt", "video": "video"},
}


def _agent_tool_create_node_validate_classic(args):
    canvas_id = str(args.get("canvas_id") or "").strip()
    if not canvas_id:
        raise AgentToolError("canvas_id 不能为空", code="invalid_args")
    node_type = str(args.get("type") or "").strip().lower()
    # BEAT（classic）画布没有独立的 text 节点：文本一律落成 prompt 节点（前端把它渲染成文本节点），
    # 否则模型按工具目录里的 enum 选 text 会被这里拒掉，用户说「建个文字节点」就永远失败。
    if node_type == "text":
        node_type = "prompt"
    if node_type in ("table", "batch"):
        canvas = load_canvas(canvas_id)
        if not _agent_is_beat_canvas(canvas):
            raise AgentToolError("多维表格 / 批量生成节点只支持「智能画布BEAT」；当前画布是旧版经典画布",
                                 code="invalid_args")
        return _agent_beat_create_table_batch_validate(args, canvas, canvas_id, node_type)
    if node_type in ("audio", "timeline"):
        if not _agent_is_beat_canvas(load_canvas(canvas_id)):
            raise AgentToolError("配音 / 剪辑时间线节点只在智能画布里可用", code="invalid_args")
        return _agent_beat_create_validate(args, canvas_id, node_type)
    if node_type not in ("image", "prompt", "video"):
        raise AgentToolError("type 必须是 image|prompt|video|text|audio|timeline", code="invalid_args")
    load_canvas(canvas_id)
    norm = {"canvas_id": canvas_id, "type": node_type}
    norm["title"] = str(args.get("title") or "")[:120]
    try:
        norm["x"] = float(args["x"]) if args.get("x") is not None else None
        norm["y"] = float(args["y"]) if args.get("y") is not None else None
    except (TypeError, ValueError):
        raise AgentToolError("x/y 必须是数字", code="invalid_args")
    # 正文可能写在 prompt / text / content 任一个字段里（模型三种写法都见过），统一收回 prompt
    norm["prompt"] = str(args.get("prompt") or args.get("text") or args.get("content") or "")
    params = args.get("params") or {}
    if params is not None and not isinstance(params, dict):
        raise AgentToolError("params 必须是对象", code="invalid_args")
    norm["params"] = dict(params or {})
    norm["inputs"] = _agent_parse_inputs(args.get("inputs"))
    return norm


def _agent_tool_create_node_run_classic(args):
    canvas_id = args["canvas_id"]
    if args.get("type") in ("table", "batch") and args.get("beat"):
        return _agent_beat_create_table_batch_run(args)
    if args.get("type") in ("audio", "timeline"):
        return _agent_beat_create_audio(args) if args["type"] == "audio" else _agent_beat_create_timeline(args)
    if _agent_is_beat_canvas(load_canvas(canvas_id)):
        kind = {"prompt": "text"}.get(args["type"], args["type"])
        params = dict(args.get("params") or {})
        url = str(params.pop("url", "") or "")
        text = str(args.get("prompt") or "")
        title = args.get("title") or (text.strip().splitlines()[0][:16] if kind == "text" and text.strip() else "")
        state = {}

        def _mutate_beat(canvas):
            w, h = _AGENT_BEAT_SIZE.get(kind, (240, 240))
            # inputs 之前对 BEAT 是静默忽略的：模型以为连好了，实际画布上没有线；分组/堆叠还会被拆成组员
            explicit_inputs = _agent_beat_normalize_inputs(canvas, args.get("inputs"))
            x, y = (args["x"], args["y"]) if args.get("x") is not None and args.get("y") is not None else _agent_beat_place(canvas, explicit_inputs, w, h)
            # 生成类节点的提示词按真实连线补 @ 引用；文本节点正文是文档本身，不塞记号（画布只解析提示词里的引用）
            prompt_text = text if kind in ("image", "video") else ""
            if prompt_text:
                prompt_text = _agent_beat_prompt_with_mentions(prompt_text, canvas, explicit_inputs)
            node = _agent_beat_new_node(kind, x, y, title=title, prompt=prompt_text,
                                        text=text if kind == "text" else "", url=url, uploaded=bool(url),
                                        manual=(kind == "text"))
            canvas.setdefault("nodes", []).append(node)
            conns = canvas.setdefault("connections", [])
            for src in explicit_inputs:
                conns.append(_agent_beat_edge(src, node["id"]))
            state["node"] = node
            return None

        canvas, _ = _agent_mutate_canvas(canvas_id, _mutate_beat)
        node = state["node"]
        return {"node": _agent_beat_node_summary(node, canvas), "node_id": node["id"],
                "node_count": len(canvas.get("nodes") or [])}
    canvas_kind = "smart" if load_canvas(canvas_id).get("kind") == "smart" else "classic"
    node_type = _AGENT_NODE_TYPE_MAP[canvas_kind][args["type"]]
    node = {
        "id": f"agent_{uuid.uuid4().hex[:16]}",
        "type": node_type,
        "x": args["x"] if args["x"] is not None else 0,
        "y": args["y"] if args["y"] is not None else 0,
        "created_at": now_ms(),
    }
    if node_type in ("smart-image", "image"):
        node["title"] = args["title"] or ("Image" if node_type == "smart-image" else "图片")
        if node_type == "smart-image":
            node["images"] = []
        else:
            node["url"] = str(args["params"].get("url") or "")
            node["name"] = str(args["params"].get("name") or "")
    elif node_type in ("smart-prompt", "prompt"):
        # 没给标题时用正文首行当标题，别让画布上出现一排叫 Prompt 的节点
        text = str(args["prompt"] or "")
        lines = text.strip().splitlines()
        node["title"] = args["title"] or (lines[0][:40] if lines else "Prompt")
        node["text"] = text
        if node_type == "smart-prompt":
            node.update({"w": 316, "h": 240, "promptSeparator": ";", "promptSplitEnabled": False,
                         "llmEnabled": False, "llmSystemEnabled": False, "llmInstruction": ""})
    else:  # smart-video / video
        node["title"] = args["title"] or "视频"
        node["model"] = str(args["params"].get("model") or "")
        node["duration"] = int(args["params"].get("duration") or 5)
        node["aspectRatio"] = str(args["params"].get("aspectRatio") or "16:9")
        node["inputs"] = []
    for k, v in args["params"].items():
        if k not in ("url", "name", "model", "duration", "aspectRatio"):
            node[k] = v

    def _mutate(canvas):
        # 模型没给坐标时不能落在 (0,0)：所有新节点会叠成一个点，用户看起来就是「画布没变化」
        if args["x"] is None or args["y"] is None:
            x, y = _agent_default_position(canvas, [], 320, 320)
            node["x"], node["y"] = round(x), round(y)
        canvas.setdefault("nodes", []).append(node)
        return None

    canvas, _ = _agent_mutate_canvas(canvas_id, _mutate)
    _agent_snapshot(canvas, note=f"agent:create_node {node['id']}")
    return {"node": node, "node_id": node["id"], "node_count": len(canvas.get("nodes") or [])}


def _agent_create_table_batch_validate(args, canvas, canvas_id, node_type):
    norm = {"canvas_id": canvas_id, "type": node_type, "smart": True, "prompt": "",
            "title": str(args.get("title") or "")[:60], "settings": {}}
    try:
        norm["x"] = float(args["x"]) if args.get("x") is not None else None
        norm["y"] = float(args["y"]) if args.get("y") is not None else None
    except (TypeError, ValueError):
        raise AgentToolError("x/y 必须是数字", code="invalid_args")
    norm["inputs"] = _agent_parse_inputs(args.get("inputs"))
    if node_type == "table":
        norm["columns"], norm["rows"] = _agent_table_rows_from_args(args.get("rows"), args.get("columns"))
    else:
        media = str(args.get("media") or "image").strip().lower()
        if media not in ("image", "video"):
            raise AgentToolError("batch 节点的 media 只能是 image 或 video", code="invalid_args")
        settings = dict(args.get("settings") or {}) if isinstance(args.get("settings"), dict) else {}
        settings.pop("count", None)
        norm["media"] = media
        norm["settings"] = _agent_validate_settings(settings, media)
    by_id = _agent_nodes_by_id(canvas)
    missing = [i for i in norm["inputs"] if i not in by_id and not _agent_args_have_step_refs(i)]
    if missing:
        raise AgentToolError(f"inputs 里的节点不存在：{'、'.join(missing)}", code="node_not_found", status_code=404)
    if node_type == "batch":
        tables = [i for i in norm["inputs"] if _agent_node_type(by_id.get(i) or {}) == "table"]
        if not norm["inputs"]:
            raise AgentToolError("type=batch 必须把上游表格放进 inputs：先 create_node(type=table) 建表，"
                                 "再把表格放进 inputs（例如 inputs:[{\"step\": 0}] 或直接填表格 node_id）", code="invalid_args")
        if not tables and not any(_agent_args_have_step_refs(i) for i in norm["inputs"]):
            raise AgentToolError("type=batch 的 inputs 里必须有一个多维表格节点（smart-batch 只接表格）；"
                                 "例如 inputs:[{\"step\": 0}]（表格是第 0 步）或填表格 node_id", code="invalid_args")
    return norm


def _agent_tool_create_node_preview(args, canvas):
    return f"将在画布「{canvas.get('title')}」新建 1 个 {args.get('type')} 节点" + \
           (f"（标题：{args.get('title')}）" if args.get("title") else "") + \
           (f"，提示词：{args.get('prompt', '')[:40]}…" if args.get("prompt") else "")


