def agent_image_size(provider, model, size="", ratio=""):
    """助手生图统一尺寸出口：显式 size 优先，否则按比例取最保守的 1k 档，最后统一过尺寸策略。

    provider 传平台 id 或平台配置；model 为空时按执行链同样规则落到平台首个生图模型，
    保证策略用的是本次真正下发的 provider/model，而不是默认供应商。
    """
    if isinstance(provider, dict):
        provider_config = provider
    else:
        try:
            provider_config = get_api_provider(provider)
        except HTTPException:
            provider_config = {"id": str(provider or "").strip().lower()}
    default_model = (provider_config.get("image_models") or provider_config.get("models") or [""])[0]
    try:
        effective_model = selected_model(model, default_model)
    except HTTPException:
        effective_model = str(model or "").strip()
    requested = str(size or "").strip()
    if not requested:
        options = CHAT_RATIO_SIZE_OPTIONS.get(str(ratio or "").strip().lower())
        requested = options[0] if options else "1024x1024"
    return nova_protocols.constrain_size(provider_config, effective_model, requested)


def _agent_tool_run_generation_validate_classic(args):
    canvas_id = str(args.get("canvas_id") or "").strip()
    node_id = str(args.get("node_id") or "").strip()
    if not canvas_id or not node_id:
        raise AgentToolError("canvas_id 与 node_id 不能为空", code="invalid_args")
    canvas = load_canvas(canvas_id)
    node = _agent_find_node(canvas, node_id)
    if not node:
        raise AgentToolError(f"节点 {node_id} 不存在", code="node_not_found", status_code=404)
    provider = str(args.get("provider") or "comfly").strip() or "comfly"
    model = str(args.get("model") or "").strip()
    # settings 与 update_node 同口径：先写进节点再运行（文档承诺的行为，经典画布以前直接丢掉了）
    settings = {}
    settings_kind = _agent_settings_kind(node) or "image"
    if args.get("settings") is not None:
        if not isinstance(args["settings"], dict):
            raise AgentToolError("settings 必须是对象", code="invalid_args")
        settings = _agent_validate_settings(dict(args["settings"]), settings_kind)
        if "ratio" in settings:
            settings["ratio"] = _agent_classic_ratio(settings["ratio"])
        provider = settings.get("provider") or provider
        model = settings.get("model") or model
    ratio = _agent_classic_ratio(settings.get("ratio") or args.get("ratio") or "")
    size_hint = args.get("size")
    if not size_hint and settings.get("resolution") and settings_kind == "image":
        # settings 里的分辨率是档位（2k）；换算成该比例对应的像素尺寸，别把 "2K" 当尺寸发下去
        tier = str(settings["resolution"]).strip().upper()
        options = CHAT_RATIO_SIZE_OPTIONS.get(ratio or "")
        tier_index = {"1K": 0, "2K": 1, "4K": 2}.get(tier)
        if options and tier_index is not None and len(options) > tier_index:
            size_hint = options[tier_index]
        else:
            size_hint = ""
    norm = {"canvas_id": canvas_id, "node_id": node_id,
            "provider": provider,
            "model": model,
            "size": agent_image_size(provider, model, size_hint, ratio),
            "quality": str(args.get("quality") or settings.get("quality") or "auto").strip() or "auto",
            "exclude_self_refs": bool(args.get("exclude_self_refs"))}
    if settings:
        norm["settings"] = settings
        norm["settings_kind"] = settings_kind
    refs = args.get("reference_images") or []
    if refs is not None and not isinstance(refs, list):
        raise AgentToolError("reference_images 必须是数组", code="invalid_args")
    norm["reference_images"] = []
    for ref in (refs or [])[:10]:
        if isinstance(ref, str) and ref.strip():
            norm["reference_images"].append({"url": ref.strip()})
        elif isinstance(ref, dict) and str(ref.get("url") or "").strip():
            norm["reference_images"].append({"url": str(ref["url"]).strip()})
    return norm


async def _agent_tool_run_generation_run_classic(args):
    canvas = load_canvas(args["canvas_id"])
    if _agent_is_beat_canvas(canvas):
        return _agent_beat_mark_run(args["canvas_id"], args["node_id"], args.get("settings"),
                                    args.get("settings_kind") or "image",
                                    exclude_self_refs=bool(args.get("exclude_self_refs")))
    node = _agent_find_node(canvas, args["node_id"])
    if not node:
        raise AgentToolError(f"节点 {args['node_id']} 不存在", code="node_not_found", status_code=404)
    prompt = _agent_node_text(node)
    if not prompt:
        raise AgentToolError(
            f"节点 {args['node_id']} 没有提示词（text/prompt 为空），请先用 update_node 写入提示词",
            code="empty_prompt")
    review_rerun = bool(args.get("exclude_self_refs"))
    # 节点自带图片（images[] / url）自动作为参考图（不覆盖显式传入的 reference_images）
    refs = list(args["reference_images"])
    if not refs and not review_rerun:
        for img in (node.get("images") or [])[:10]:
            if isinstance(img, dict) and str(img.get("url") or "").strip():
                refs.append({"url": str(img["url"]).strip()})
        if not refs and str(node.get("url") or "").strip():
            refs.append({"url": str(node["url"]).strip()})
    if review_rerun:
        # 服务端强制过滤：显式参考图里夹着节点自己的产物也不许用（问题图不能再进下一版）
        self_urls = _agent_self_output_urls(canvas, node)
        refs = [ref for ref in refs if str(ref.get("url") or "").strip() not in self_urls]
    if args.get("settings"):
        def _apply(canvas):
            n = _agent_find_node(canvas, args["node_id"])
            if n is not None:
                _agent_classic_apply_settings(n, args.get("settings_kind") or "image", args["settings"])
            return None
        _agent_mutate_canvas(args["canvas_id"], _apply)
    payload = {
        "prompt": prompt,
        "provider_id": args["provider"],
        "model": args["model"],
        "size": args["size"],
        "quality": args["quality"],
        "n": 1,
        "reference_images": refs,
    }
    record = _agent_generation_request_record(
        _agent_node_kind(node), prompt, refs,
        {"provider": args["provider"], "model": args["model"],
         "size": args["size"], "quality": args["quality"]})
    blocked = _agent_regen_guard(_agent_regen_state_node(canvas, node), record,
                                 review_rerun=review_rerun)
    if blocked:
        return _agent_regen_guard_result(blocked, args["node_id"], _agent_node_kind(node))
    task = task_create(
        kind="online-image", payload=payload, runner_name="run_canvas_image_task",
        provider_id=args["provider"], model_id=args["model"],
        extra={"agent": True, "canvas_id": args["canvas_id"], "node_id": args["node_id"]})
    await task_enqueue(task["id"])

    def _mutate(canvas):
        n = _agent_find_node(canvas, args["node_id"])
        if n is not None:
            n["task_id"] = task["id"]
            n["lastTaskStatus"] = "queued"
            _agent_regen_record(n, record, review_rerun=review_rerun)
        return None

    try:
        _agent_mutate_canvas(args["canvas_id"], _mutate)
    except Exception as exc:
        print(f"[Agent] 记录 task_id 到节点失败（不影响任务）: {exc}")
    return {
        "task_id": task["id"], "status": "queued", "node_id": args["node_id"],
        "provider": args["provider"], "model": args["model"], "size": args["size"],
        "prompt": prompt[:160] + ("…" if len(prompt) > 160 else ""),
    }


def _agent_tool_run_generation_preview_classic(args, canvas):
    node = _agent_find_node(canvas, str(args.get("node_id") or ""))
    name = (node.get("title") or node.get("id")) if node else args.get("node_id")
    prompt = _agent_node_text(node) if node else ""
    size = agent_image_size(args.get("provider") or "comfly", args.get("model") or "", args.get("size"), "")
    return f"将对节点 {name} 发起真实图片生成任务（provider={args.get('provider') or 'comfly'}, model={args.get('model') or '默认'}, size={size}）" + \
           (f"，提示词：{prompt[:40]}…" if prompt else "；⚠️ 节点当前无提示词，执行会失败")


# ---------------------------------------------------------------------------
# 工具 7b: generate_image（一句话出图：建节点 + 真实生成 + 结果落画布）
# ---------------------------------------------------------------------------

_AGENT_AUTO_RATIOS = ("", "auto", "自适应", "自动", "adaptive", "keep_ratio", "source", "context")
_AGENT_SOURCE_LONG_SIDE = {"0.5K": 512, "768SQ": 768, "1K": 1536, "1.5K": 1792, "2K": 2048, "3K": 3072, "4K": 3840}


def _agent_auto_ratio(value):
    """ratio 是否表示「按原图/自适应」：auto / 自适应 / adaptive / 空（没给比例）等。"""
    return str(value or "").strip().lower() in _AGENT_AUTO_RATIOS


def _agent_first_reference_size(refs):
    """参考图真实像素（本地文件能读才返回；远程/读不到返回空，不猜）。"""
    for ref in (refs or []):
        raw = image_size_from_reference(ref if isinstance(ref, dict) else {"url": str(ref or "")})
        if re.fullmatch(r"\d+x\d+", str(raw or "")):
            return raw
    return ""


def _agent_auto_ratio_image_size(provider, model, refs, tier=""):
    """ratio=auto/自适应 + 有参考图：按参考图真实比例 + 模型支持的档位算尺寸（16 对齐）。

    返回 (size, ratio_label, note)；读不到参考图尺寸时返回空串，调用方退回方图并说明。"""
    raw = _agent_first_reference_size(refs)
    width, height = parse_size_pair(raw)
    if not width or not height:
        return "", "", ""
    caps = model_caps_for(provider, model, "image") or {}
    tiers = [str(item).upper() for item in (caps.get("resolutions") or [])]
    chosen = str(tier or "").upper()
    if chosen not in _AGENT_SOURCE_LONG_SIDE:
        chosen = tiers[0] if tiers and tiers[0] in _AGENT_SOURCE_LONG_SIDE else "1K"
    long_side = _AGENT_SOURCE_LONG_SIDE.get(chosen, 1536)
    if width >= height:
        out_w, out_h = long_side, round(long_side * height / width)
    else:
        out_w, out_h = round(long_side * width / height), long_side
    size = f"{max(64, out_w // 16 * 16)}x{max(64, out_h // 16 * 16)}"
    label = _caps_ratio_label(f"{width}:{height}") or raw
    note = f"按参考图比例 {label}（{raw}）算尺寸 {size}"
    ratios = caps.get("ratios") or []
    if ratios and label:
        legal = model_caps_nearest_ratio(label, ratios)
        if legal and legal.lower() not in ("auto", "adaptive") and legal.lower() != label.lower():
            size = _caps_size_for_tier(legal, chosen, size) or size
            label = legal
            note = f"按参考图比例 {label} 算尺寸 {size}（已收敛到该模型支持的比例）"
    return size, label, note


def _agent_auto_ratio_video_ratio(provider, model, refs):
    """ratio=adaptive/auto + 有参考图：按参考图真实比例取该模型支持的最近视频比例。"""
    raw = _agent_first_reference_size(refs)
    width, height = parse_size_pair(raw)
    if not width or not height:
        return "", ""
    label = _caps_ratio_label(f"{width}:{height}") or raw
    caps = model_caps_for(provider, model, "video") or {}
    ratios = [str(item) for item in (caps.get("ratios") or [])
              if str(item).strip().lower() not in ("auto", "adaptive")]
    if not ratios:
        ratios = [item for item in _AGENT_VIDEO_ASPECTS if item not in ("adaptive", "auto")]
    if not ratios:
        return "", ""
    legal = model_caps_nearest_ratio(label, ratios) or ratios[0]
    return legal, f"按参考图比例 {label} → 视频比例 {legal}"


def _agent_tool_generate_image_validate(args):
    canvas_id = str(args.get("canvas_id") or "").strip()
    prompt = str(args.get("prompt") or args.get("text") or "").strip()
    if not canvas_id:
        raise AgentToolError("canvas_id 不能为空", code="invalid_args")
    if not prompt:
        raise AgentToolError("prompt 不能为空（描述你想生成的图）", code="invalid_args")
    load_canvas(canvas_id)  # 404 校验
    refs = args.get("reference_urls")
    if refs is None:
        refs = args.get("reference_images")
    if refs is not None and not isinstance(refs, list):
        raise AgentToolError("reference_urls 必须是数组", code="invalid_args")
    norm_refs = []
    for ref in (refs or [])[:10]:
        if isinstance(ref, str) and ref.strip():
            norm_refs.append({"url": ref.strip()})
        elif isinstance(ref, dict) and str(ref.get("url") or "").strip():
            norm_refs.append({"url": str(ref["url"]).strip()})
    size = str(args.get("size") or "").strip()
    ratio = str(args.get("ratio") or "").strip().lower()
    provider, model, model_note = _agent_resolve_media_target(args, "image_models", _agent_pick_image_provider)
    if model_note:
        print(f"[Agent] generate_image 换模型：{model_note}", flush=True)
    notes = []
    # 「原图比例」：ratio 是 auto/自适应（或没给）时，有参考图就按参考图真实比例 + 模型档位算尺寸，
    # 不再一律落 1024x1024 方图；没有参考图才退回方图，并把原因写进 caps_notes（工具结果里能看到）
    if _agent_auto_ratio(ratio):
        if norm_refs:
            source_size, source_ratio, source_note = _agent_auto_ratio_image_size(provider, model, norm_refs)
            if source_size:
                size = source_size
                if source_ratio:
                    ratio = source_ratio
                if source_note:
                    notes.append(source_note)
            else:
                notes.append("参考图尺寸读不到（远程或非本地素材），暂按方图尺寸生成")
        else:
            notes.append("没有参考图，按方图尺寸生成")
    norm = {
        "canvas_id": canvas_id,
        "prompt": prompt,
        "reference_urls": norm_refs,
        "provider": provider,
        "model": model,
        "size": agent_image_size(provider, model, size, ratio),
        "ratio": ratio,
        "title": str(args.get("title") or "")[:120],
        "count": _agent_clamp_count(args.get("count"), 8),
    }
    # 模型有权威规格时先收敛（比例 / 分辨率），张数不在这里吞：请求几张就保留几张，
    # 模型单次上限只用 max_batch 如实告诉调用方 / 模型（执行端与前端据此分批）。
    requested_count = norm["count"]
    converged = model_caps_converge(provider, model, "image",
                                    ratio=norm["ratio"], size=norm["size"], count=norm["count"])
    norm["ratio"] = converged["ratio"] or norm["ratio"]
    norm["size"] = converged["size"] or norm["size"]
    converged_count = converged["count"] or requested_count
    if converged_count != requested_count:
        norm["max_batch"] = int(converged_count)
        norm["batch_note"] = (f"该模型一次最多 {int(converged_count)} 张，已保留请求的 {int(requested_count)} 张，"
                              "执行端会分批请求；不要改小张数")
        notes = [note for note in notes if not str(note).startswith("张数 ")]
        notes.append(norm["batch_note"])
    norm["count"] = requested_count
    # caps 里「张数 4 → 1」这条是收敛计数时产生的，不再保留（张数由 max_batch / batch_note 如实说明）
    notes.extend(note for note in converged["notes"] if not str(note).startswith("张数 "))
    if notes:
        norm["caps_notes"] = notes
    if model_note:
        norm["model_note"] = model_note
    beat_inputs = _agent_beat_inputs_arg(args, canvas_id)
    if beat_inputs is not None:
        norm["inputs"] = beat_inputs
    return norm


def _agent_clamp_count(value, high):
    try:
        return max(1, min(int(value or 1), high))
    except (TypeError, ValueError):
        return 1


def _agent_available_providers():
    """动态返回可用的 provider 列表（按用户配置顺序：启用的、有 key 的优先）。
    不做任何平台硬编码——用户配了什么用什么。"""
    providers = load_api_providers()
    ordered = []
    seen = set()
    for p in providers:
        pid = str((p or {}).get("id") or "").strip().lower()
        if not pid or pid in seen:
            continue
        seen.add(pid)
        if (p or {}).get("enabled") is False:
            continue
        try:
            base, _, _ = resolve_chat_provider(pid, "", "", require_model=False)
            if base:
                ordered.append(pid)
        except HTTPException:
            continue
    # 保证 comfly 在最后兜底（如果配置里有）
    return [p for p in ordered if p != "comfly"] + [p for p in ordered if p == "comfly"]


def _agent_provider_declares_image_models(provider):
    """平台是否声明了生图模型：单数 image_model 或 image_models 清单（沿用 models 兜底）。"""
    if not isinstance(provider, dict):
        return False
    if str(provider.get("image_model") or "").strip():
        return True
    return bool(_agent_declared_models(provider, "image_models")
                or [str(i or "").strip() for i in (provider.get("models") or []) if str(i or "").strip()])


def _agent_image_provider_candidates():
    """按用户配置顺序（comfly 垫底）返回启用的平台；不要求密钥，供「是否声明生图模型」与兜底判定用。"""
    ordered, seen = [], set()
    for p in load_api_providers():
        if not isinstance(p, dict) or p.get("enabled") is False:
            continue
        pid = str(p.get("id") or "").strip().lower()
        if not pid or pid in seen:
            continue
        seen.add(pid)
        ordered.append((pid, p))
    return [i for i in ordered if i[0] != "comfly"] + [i for i in ordered if i[0] == "comfly"]


def _agent_pick_image_provider_detailed(preferred=""):
    """生图平台选择 + 可验证依据：返回 (provider_id, reason, skipped)。
    优先级：显式指定（可解析）>
    配置顺序第一个「启用、声明生图模型、有可用密钥」> 兜底配置顺序第一个可用 > comfly。"""
    pref = str(preferred or "").strip().lower()
    skipped = []
    if pref and pref != "comfly":
        try:
            base, _, _ = resolve_chat_provider(pref, "", "", require_model=False)
            if base:
                return pref, "显式指定平台", skipped
        except HTTPException:
            pass
        skipped.append("%s（无可用密钥或 Base URL）" % pref)
    keyed = set(_agent_available_providers())
    candidates = _agent_image_provider_candidates()
    for pid, p in candidates:
        if not _agent_provider_declares_image_models(p):
            skipped.append("%s（未声明生图模型）" % pid)
            continue
        if pid not in keyed:
            skipped.append("%s（无可用密钥）" % pid)
            continue
        return pid, "用户配置顺序里第一个可用平台（有密钥且声明生图模型）", skipped
    for pid, _p in candidates:
        if pid in keyed:
            return pid, "兜底：配置顺序第一个可用平台（没有平台声明生图模型）", skipped
        skipped.append("%s（无可用密钥）" % pid)
    return "comfly", "兜底 comfly（没有可用平台）", skipped


def _agent_pick_image_provider(preferred=""):
    """生图 provider 自动探测：用户指定 > 动态可用平台（按用户配置顺序）> comfly。"""
    return _agent_pick_image_provider_detailed(preferred)[0]


def _agent_declared_models(provider, model_field):
    return [str(item or "").strip() for item in (provider.get(model_field) or []) if str(item or "").strip()]


def _agent_media_provider_for_model(model, model_field):
    """模型归属平台：按用户配置顺序取第一个在 image_models/video_models（或 models）里声明了该模型的
    启用平台；命中多个时优先能解析出密钥的。都没密钥时退回配置顺序第一个命中——宁可报「平台缺 key」，
    也不要把模型打到不声明它的上游。没有平台声明该模型则返回空串。"""
    target = str(model or "").strip().lower()
    if not target:
        return ""
    hits = []
    for provider in load_api_providers():
        if not isinstance(provider, dict) or provider.get("enabled") is False:
            continue
        pid = str(provider.get("id") or "").strip().lower()
        if not pid or pid in hits:
            continue
        declared = _agent_declared_models(provider, model_field) + \
            [str(item or "").strip() for item in (provider.get("models") or [])]
        if model_field == "image_models":
            declared.append(str(provider.get("image_model") or "").strip())
        if target in {item.lower() for item in declared if item}:
            hits.append(pid)
    for pid in hits:
        try:
            base, _, _ = resolve_chat_provider(pid, "", "", require_model=False)
        except HTTPException:
            continue
        if base:
            return pid
    return hits[0] if hits else ""


def _agent_image_provider_for_model(model):
    return _agent_media_provider_for_model(model, "image_models")


def _agent_video_provider_for_model(model):
    return _agent_media_provider_for_model(model, "video_models")


def _agent_provider_media_models(provider_id, model_field):
    """某个平台在 API 设置里配置的生图/生视频模型（生图没单独配时用它的 models）。"""
    try:
        cfg = get_api_provider_exact(provider_id)
    except HTTPException:
        return None, []
    declared = _agent_declared_models(cfg, model_field)
    if model_field == "image_models":
        single = str(cfg.get("image_model") or "").strip()
        if single:
            declared = [single] + [m for m in declared if m.lower() != single.lower()]
        if not declared:
            declared = [str(i or "").strip() for i in (cfg.get("models") or []) if str(i or "").strip()]
    return cfg, list(dict.fromkeys(declared))


def _agent_fit_media_model(provider_id, declared, model):
    """模型落到这个平台配置的清单里：没写就用清单第一个；写了清单里没有的就换成清单第一个并说明。"""
    if not declared:
        return provider_id, model, ""
    if not model:
        return provider_id, declared[0], ""
    for item in declared:
        if item.lower() == model.lower():
            return provider_id, item, ""
    return provider_id, declared[0], f"平台 {provider_id} 没配置模型 {model}，已改用它配置里的 {declared[0]}"


def _agent_resolve_media_target(args, model_field, picker, trace=None):
    """定 generate_image / generate_video 最终下发的 (provider, model, note)。
    优先级：前端显式 image_provider（可解析）> 模型归属平台 > 现有自动探测；
    LLM 自写的 args.model 优先于前端缺省 image_model。前端平台不声明该模型时换成该平台默认模型，
    换模型原因写进 note（进 digest + 打日志），不做静默改写。
    trace 传入 dict 时回填 {source, reason, skipped}，用于把选择依据写进能力运行 note。"""
    def _record(source, reason, skipped=None):
        if isinstance(trace, dict):
            trace["source"] = source
            trace["reason"] = reason
            trace["skipped"] = list(skipped or [])

    llm_model = str(args.get("model") or "").strip()
    llm_provider = str(args.get("provider") or "").strip().lower()
    explicit_provider = str(args.get("image_provider") or "").strip().lower()
    explicit_model = str(args.get("image_model") or "").strip()
    # 第 46 轮：模型名一律来自 API 设置（平台配置的模型清单），代码里不写死任何模型
    if explicit_provider:
        cfg, declared = _agent_provider_media_models(explicit_provider, model_field)
        if cfg and declared:   # 界面上选定的平台（且有这类模型）：只能用它配置里的模型
            _record("explicit", "显式指定平台 %s" % cfg["id"])
            return _agent_fit_media_model(cfg["id"], declared, llm_model or explicit_model)
    model = llm_model or explicit_model
    owner = _agent_media_provider_for_model(model, model_field)
    if owner:
        _record("model_owner", "模型 %s 归属平台 %s" % (model, owner))
        return owner, model, ""
    cfg, declared = _agent_provider_media_models(llm_provider, model_field) if llm_provider else (None, [])
    if cfg and declared:
        pid = cfg["id"]
        _record("provider_arg", "参数指定平台 %s" % pid)
    elif model_field == "image_models" and picker is _agent_pick_image_provider:
        pid, reason, skipped = _agent_pick_image_provider_detailed("")
        _record("auto", reason, skipped)
    else:
        pid = picker("")
        _record("auto", "自动探测平台 %s" % pid)
    cfg, declared = _agent_provider_media_models(pid, model_field)
    return _agent_fit_media_model(pid, declared, model)


def _agent_media_selection_note(provider_id, model_id, trace, note=""):
    """能力运行可验证信息：最终平台 / 模型 / 选择依据 / 跳过了哪些平台及原因。"""
    parts = ["平台 %s / 模型 %s" % (provider_id or "无", model_id or "无")]
    origin = str((trace or {}).get("origin") or "").strip()
    if origin:
        parts.append("来源：%s" % origin)
    reason = str((trace or {}).get("reason") or "").strip()
    if reason:
        parts.append("选择依据：%s" % reason)
    if note:
        parts.append(str(note))
    skipped = [str(item) for item in ((trace or {}).get("skipped") or []) if str(item).strip()]
    if skipped:
        parts.append("跳过：" + "；".join(skipped))
    return "；".join(parts)


async def _agent_tool_generate_image_run_classic(args):
    """建「提示词节点 → 图片节点」完整工作流（含连线，ComfyUI 式管线）
    → 真实生成任务（Task Engine）→ 结果自动落画布图片节点。"""
    canvas_id = args["canvas_id"]
    count = len(load_canvas(canvas_id).get("nodes") or [])
    rx = 220 + (count % 5) * 70
    ry = 160 + (count % 4) * 70
    # 1) 建提示词节点（结果节点左侧，作为工作流起点）
    prompt_args = _agent_tool_create_node_validate({
        "canvas_id": canvas_id, "type": "prompt",
        "prompt": args["prompt"],
        "title": (args["title"] or "Image") + " 提示词",
        "x": rx - 280, "y": ry,
    })
    prompt_res = _agent_tool_create_node_run(prompt_args)
    prompt_node_id = prompt_res["node_id"]
    # 2) 建图片结果节点（复用 create_node 工具，保证节点结构与画布类型一致 smart-image / image）
    node_args = _agent_tool_create_node_validate({
        "canvas_id": canvas_id, "type": "image",
        "prompt": args["prompt"],
        "title": args["title"] or "Image",
        "x": rx, "y": ry,
    })
    node_res = _agent_tool_create_node_run(node_args)
    node_id = node_res["node_id"]
    # 3) 连线：提示词节点 → 图片节点（用户可见完整管线）
    conn_args = _agent_tool_connect_nodes_validate({
        "canvas_id": canvas_id, "from": prompt_node_id, "to": node_id, "kind": "input",
    })
    _agent_tool_connect_nodes_run(conn_args)
    # 4) 参考图挂到图片节点 images（画布上可见）+ 记录提示词
    refs = args["reference_urls"]

    def _attach(canvas):
        n = _agent_find_node(canvas, node_id)
        if n is not None:
            n["images"] = [{"url": r["url"], "name": f"ref-{i + 1}.png", "kind": "image"}
                           for i, r in enumerate(refs)]
            n["text"] = args["prompt"]
        return None

    _agent_mutate_canvas(canvas_id, _attach)
    # 3) 真实生成：与 run_generation 同构，进 Task Engine（run_canvas_image_task runner）
    # 请求几张就建几个任务（每个 n=1）：以前这里写死 n=1，会把「生成 4 张」静默吞成 1 张。
    try:
        requested_count = max(1, min(int(args.get("count") or 1), 8))
    except (TypeError, ValueError):
        requested_count = 1
    payload = {
        "prompt": args["prompt"],
        "provider_id": args["provider"],
        "model": args["model"],
        "size": args["size"],
        "quality": "auto",
        "n": 1,
        "reference_images": refs,
    }
    tasks = [task_create(
        kind="online-image", payload=payload, runner_name="run_canvas_image_task",
        provider_id=args["provider"], model_id=args["model"],
        extra={"agent": True, "canvas_id": canvas_id, "node_id": node_id})
        for _ in range(requested_count)]
    for item in tasks:
        await task_enqueue(item["id"])
    task = tasks[-1]

    def _mark(canvas):
        n = _agent_find_node(canvas, node_id)
        if n is not None:
            n["task_id"] = task["id"]
            n["lastTaskStatus"] = "queued"
        return None

    try:
        _agent_mutate_canvas(canvas_id, _mark)
    except Exception as exc:
        print(f"[Agent] 记录 task_id 到节点失败（不影响任务）: {exc}")
    result = {
        "prompt_node_id": prompt_node_id,
        "node_id": node_id,
        "task_id": task["id"],
        "task_ids": [item["id"] for item in tasks],
        "count": requested_count,
        "status": "queued",
        "provider": args["provider"],
        "model": args["model"],
        "size": args["size"],
        "reference_count": len(refs),
        "prompt": args["prompt"][:160] + ("…" if len(args["prompt"]) > 160 else ""),
        "message": (f"已在画布创建提示词节点+图片节点并连线（{args['provider']}，size={args['size']}），"
                    f"已提交 {requested_count} 个生成任务，出图后自动落到图片节点"),
    }
    if args.get("model_note"):
        result["model_note"] = args["model_note"]
    if args.get("caps_notes"):
        result["caps_notes"] = args["caps_notes"]
        result["message"] += "（已按模型规格收敛：" + "；".join(args["caps_notes"]) + "）"
    return result


def _agent_tool_generate_image_preview(args, canvas):
    refs = args.get("reference_urls") or []
    size = agent_image_size(args.get("provider") or "comfly", args.get("model") or "", args.get("size"), args.get("ratio"))
    return f"将在画布创建提示词节点 + 图片节点并连线，立即发起真实生成（provider={args.get('provider') or 'comfly'}, " + \
           f"model={args.get('model') or '默认'}, size={size}，参考图 {len(refs)} 张）" + \
           f"，提示词：{str(args.get('prompt') or '')[:40]}…"


# ---------------------------------------------------------------------------
# 工具 7c: generate_video（一句话生成视频：建节点 + 真实生成 + 结果落画布）
# ---------------------------------------------------------------------------

def _agent_pick_video_provider(preferred=""):
    """生视频 provider 自动探测：用户指定 > 配置了 video_models 的动态平台 > comfly。"""
    pref = str(preferred or "").strip().lower()
    if pref and pref != "comfly":
        try:
            base, _, _ = resolve_chat_provider(pref, "", "", require_model=False)
            if base:
                return pref
        except HTTPException:
            pass
    avail = _agent_available_providers()
    for cand in avail:
        p = get_api_provider(cand)
        if p and (p.get("video_models") or []):
            return cand
    for cand in avail:
        return cand
    return "comfly"


def _agent_tool_generate_video_validate(args):
    canvas_id = str(args.get("canvas_id") or "").strip()
    prompt = str(args.get("prompt") or args.get("text") or "").strip()
    if not canvas_id:
        raise AgentToolError("canvas_id 不能为空", code="invalid_args")
    if not prompt:
        raise AgentToolError("prompt 不能为空（描述你想生成的视频）", code="invalid_args")
    load_canvas(canvas_id)  # 404 校验
    # 参考媒体：reference_urls（图片）可字符串或 {url}；reference_video（视频）同理
    refs = args.get("reference_urls")
    if refs is None:
        refs = args.get("reference_images")
    if refs is not None and not isinstance(refs, list):
        raise AgentToolError("reference_urls 必须是数组", code="invalid_args")
    norm_refs = []
    for ref in (refs or [])[:10]:
        if isinstance(ref, str) and ref.strip():
            norm_refs.append({"url": ref.strip()})
        elif isinstance(ref, dict) and str(ref.get("url") or "").strip():
            norm_refs.append({"url": str(ref["url"]).strip()})
    vids = args.get("reference_video")
    norm_vids = []
    if vids is not None:
        if not isinstance(vids, list):
            vids = [vids]
        for v in vids[:3]:
            if isinstance(v, str) and v.strip():
                norm_vids.append({"url": v.strip()})
            elif isinstance(v, dict) and str(v.get("url") or "").strip():
                norm_vids.append({"url": str(v["url"]).strip()})
    provider, model, model_note = _agent_resolve_media_target(args, "video_models", _agent_pick_video_provider)
    if model_note:
        print(f"[Agent] generate_video 换模型：{model_note}", flush=True)
    # 生成方式（可选）：明确指定时按该模型的能力表校验，不支持直接报错并列出支持项；
    # 不传就保持原来的「按输入自动推断」行为，不破坏既有调用。
    raw_mode = str(args.get("mode") or "").strip()
    video_mode = _agent_video_mode(raw_mode)
    if raw_mode and not video_mode:
        raise AgentToolError(f"不认识的生成方式 {raw_mode}；可选：{'、'.join(VIDEO_MODE_VALUES)}", code="invalid_args")
    if video_mode:
        mode_caps = model_caps_for(provider, model, "video") or {}
        supported_modes = mode_caps.get("modes") or []
        if supported_modes and video_mode not in supported_modes:
            raise AgentToolError(
                f"{model} 不支持生成方式 {video_mode}；该模型支持：{'、'.join(supported_modes)}",
                code="invalid_args")
    motion_transfer = bool(args.get("motion_transfer"))
    if motion_transfer:
        # 动作迁移：参考视频=动作骨架，参考图=外观；火山编辑任务强制 duration=-1 / ratio=adaptive
        if not norm_vids:
            raise AgentToolError("动作迁移需要 reference_video（动作参考视频，至少 1 个）", code="invalid_args")
        if not norm_refs:
            raise AgentToolError("动作迁移需要 reference_urls（角色图/外观参考，至少 1 张）", code="invalid_args")
        norm = {
            "canvas_id": canvas_id,
            "prompt": prompt,
            "reference_urls": norm_refs,
            "reference_video": norm_vids,
            "motion_transfer": True,
            "provider": provider,
            "model": model,
            "duration": -1,
            "ratio": "adaptive",
            "mode": video_mode,
            "title": str(args.get("title") or "")[:120],
        }
        if model_note:
            norm["model_note"] = model_note
        beat_inputs = _agent_beat_inputs_arg(args, canvas_id)
        if beat_inputs is not None:
            norm["inputs"] = beat_inputs
        return norm
    duration = int(args.get("duration") or 5)
    if duration < 1:
        duration = 5
    if duration > 15:
        duration = 15  # 火山约束 ≤15.2s
    ratio = str(args.get("ratio") or "").strip().lower() or "adaptive"
    notes = []
    # 「原图比例」：ratio=adaptive/auto 且带参考图（首帧/参考图）时，按参考图真实比例取该模型支持的最近比例，
    # 不再把方图/1:1 当默认；读不到参考图尺寸才沿用 adaptive（交给上游跟随首帧）并说明
    if _agent_auto_ratio(ratio):
        if norm_refs:
            source_ratio, ratio_note = _agent_auto_ratio_video_ratio(provider, model, norm_refs)
            if source_ratio:
                ratio = source_ratio
                notes.append(ratio_note)
            else:
                notes.append("参考图尺寸读不到，视频比例沿用 adaptive（跟随首帧）")
        else:
            notes.append("没有参考图，视频比例沿用 adaptive")
    norm = {
        "canvas_id": canvas_id,
        "prompt": prompt,
        "reference_urls": norm_refs,
        "reference_video": norm_vids,
        "motion_transfer": False,
        "provider": provider,
        "model": model,
        "duration": duration,
        "ratio": ratio,
        "mode": video_mode,
        "title": str(args.get("title") or "")[:120],
        "count": _agent_clamp_count(args.get("count"), 4),
    }
    # 模型有权威规格时先收敛（比例 / 时长 / 张数），别等到上游 400
    converged = model_caps_converge(provider, model, "video",
                                    ratio=norm["ratio"], duration=norm["duration"], count=norm["count"])
    norm["ratio"] = converged["ratio"] or norm["ratio"]
    if converged["duration"] is not None:
        norm["duration"] = converged["duration"]
    norm["count"] = converged["count"] or norm["count"]
    notes.extend(converged["notes"])
    if notes:
        norm["caps_notes"] = notes
    if model_note:
        norm["model_note"] = model_note
    beat_inputs = _agent_beat_inputs_arg(args, canvas_id)
    if beat_inputs is not None:
        norm["inputs"] = beat_inputs
    return norm


async def _agent_tool_generate_video_run_classic(args):
    """建「提示词节点 → 视频节点」完整工作流（含连线，ComfyUI 式管线）
    → 真实视频生成任务（Task Engine）→ 结果自动落画布视频节点。
    motion_transfer=true 时自动组装动作迁移提示词（参考视频=动作骨架，参考图=外观）。"""
    canvas_id = args["canvas_id"]
    # 动作迁移：按模板组装提示词，明确编辑边界（只换动作，其余保持不变）
    eff_prompt = args["prompt"]
    if args.get("motion_transfer"):
        user_note = eff_prompt.strip()
        if len(user_note) > 200:
            user_note = user_note[:200]
        eff_prompt = (
            f"动作迁移：让画面中的主体严格按照参考视频的动作骨架表演，"
            f"外观保持参考图一致（身份、服装、造型、材质等不变）。"
            f"场景、镜头、光影、构图等其他一切内容保持不变，仅替换动作。"
            f"用户补充：{user_note}"
        )
    count = len(load_canvas(canvas_id).get("nodes") or [])
    rx = 220 + (count % 5) * 70
    ry = 160 + (count % 4) * 70
    # 1) 建提示词节点（结果节点左侧，作为工作流起点）
    prompt_args = _agent_tool_create_node_validate({
        "canvas_id": canvas_id, "type": "prompt",
        "prompt": eff_prompt,
        "title": (args["title"] or "Video") + " 提示词",
        "x": rx - 280, "y": ry,
    })
    prompt_res = _agent_tool_create_node_run(prompt_args)
    prompt_node_id = prompt_res["node_id"]
    # 2) 建视频结果节点（复用 create_node 工具，保证节点结构与画布类型一致 smart-video / video）
    node_args = _agent_tool_create_node_validate({
        "canvas_id": canvas_id, "type": "video",
        "prompt": eff_prompt,
        "title": args["title"] or "Video",
        "x": rx, "y": ry,
    })
    node_res = _agent_tool_create_node_run(node_args)
    node_id = node_res["node_id"]
    # 3) 连线：提示词节点 → 视频节点（用户可见完整管线）
    conn_args = _agent_tool_connect_nodes_validate({
        "canvas_id": canvas_id, "from": prompt_node_id, "to": node_id, "kind": "input",
    })
    _agent_tool_connect_nodes_run(conn_args)
    refs = args["reference_urls"]
    vids = args["reference_video"]

    def _attach(canvas):
        n = _agent_find_node(canvas, node_id)
        if n is not None:
            n["images"] = [{"url": r["url"], "name": f"ref-{i + 1}.png", "kind": "image"}
                           for i, r in enumerate(refs)]
            n["text"] = eff_prompt
            n["duration"] = args["duration"]
            n["aspectRatio"] = args["ratio"]
            if args.get("mode"):
                n["videoMode"] = args["mode"]
        return None

    _agent_mutate_canvas(canvas_id, _attach)
    # 真实生成：进 Task Engine（run_canvas_video_task runner）
    payload = {
        "prompt": eff_prompt,
        "provider_id": args["provider"],
        "model": args["model"],
        "duration": args["duration"],
        "aspect_ratio": args["ratio"],
        # 生成方式透传到任务组装：留空=按输入自动推断（老行为）
        "mode": str(args.get("mode") or ""),
        "images": refs,
        "videos": vids,
        "audios": args.get("audios") or [],
        "speaker_id": str(args.get("speaker_id") or ""),
        "voice_sample": str(args.get("voice_sample") or ""),
        "voice_consent": bool(args.get("voice_consent")),
        "generate_audio": False,
    }
    task = task_create(
        kind="video", payload=payload, runner_name="run_canvas_video_task",
        provider_id=args["provider"], model_id=args["model"],
        extra={"agent": True, "canvas_id": canvas_id, "node_id": node_id})
    await task_enqueue(task["id"])

    def _mark(canvas):
        n = _agent_find_node(canvas, node_id)
        if n is not None:
            n["task_id"] = task["id"]
            n["lastTaskStatus"] = "queued"
        return None

    try:
        _agent_mutate_canvas(canvas_id, _mark)
    except Exception as exc:
        print(f"[Agent] 记录 task_id 到节点失败（不影响任务）: {exc}")
    mode_note = "动作迁移（参考视频=动作骨架，参考图=外观，duration=-1/adaptive）" if args.get("motion_transfer") else f"duration={args['duration']}s，ratio={args['ratio']}"
    result = {
        "prompt_node_id": prompt_node_id,
        "node_id": node_id,
        "task_id": task["id"],
        "status": "queued",
        "provider": args["provider"],
        "model": args["model"],
        "duration": args["duration"],
        "reference_count": len(refs) + len(vids),
        "motion_transfer": bool(args.get("motion_transfer")),
        "mode": str(args.get("mode") or ""),
        "prompt": eff_prompt[:160] + ("…" if len(eff_prompt) > 160 else ""),
        "message": "已在画布创建提示词节点+视频节点并连线（" + str(args["provider"]) + "，" + mode_note
                   + ("，方式 " + str(args["mode"]) if args.get("mode") else "")
                   + "），生成任务已提交，完成后自动落到视频节点",
    }
    if args.get("model_note"):
        result["model_note"] = args["model_note"]
    if args.get("caps_notes"):
        result["caps_notes"] = args["caps_notes"]
        result["message"] += "（已按模型规格收敛：" + "；".join(args["caps_notes"]) + "）"
    return result


def _agent_tool_lipsync_video_validate(args):
    if not str(args.get("reference_video") or "").strip() and not isinstance(args.get("reference_video"), list):
        raise AgentToolError("reference_video 不能为空（需要原视频）", code="invalid_args")
    normalized = _agent_tool_generate_video_validate(dict(args, provider="pixverse", model="pixverse-lipsync"))
    if not normalized.get("reference_video"):
        raise AgentToolError("reference_video 不能为空（需要原视频）", code="invalid_args")
    normalized.update({
        "provider": "pixverse", "model": "pixverse-lipsync",
        "speaker_id": str(args.get("speaker_id") or "").strip(),
        "voice_sample": str(args.get("voice_sample") or "").strip(),
        "voice_consent": bool(args.get("voice_consent")),
        "audios": [str(args.get("audio") or "").strip()] if str(args.get("audio") or "").strip() else [],
    })
    if not normalized["audios"] and not normalized["voice_consent"]:
        raise AgentToolError("克隆或复用自定义声音前必须确认声音使用授权（voice_consent=true）", code="invalid_args")
    return normalized


async def _agent_tool_lipsync_video_run(args):
    result = await _agent_tool_generate_video_run_classic(args)
    result["mode"] = "lipsync"
    result["message"] = "已提交声音克隆与 LipSync 任务，完成后新视频自动落到画布节点"
    return result


