# ---------------------------------------------------------------------------
# 多维表格 + 批量生成（第 38 轮）：用户说「用表格 / 批量 / 每行一张 / 出 N 个不同版本」时，
# 助手建「多维表格 → 批量生成」这条线，而不是拆成 N 次点对点出图。
# 表格一行 = 一次生成：该行所有非空单元格按列顺序换行拼成提示词，上游提示词节点的文字放在最前面。
# 逐行出图由画布页面执行（和用户点批量节点的「运行」完全一样），服务端只建节点、连线，
# 并在步骤结果里带一个 client_action，让页面在这一轮结束、画布合并好之后开跑。
# ---------------------------------------------------------------------------

AGENT_TABLE_MAX_ROWS = 50
# 旧公开常量（行为快照会收集 AGENT_*，值保持不变）；实际列上限见 _AGENT_TABLE_MAX_COLUMNS。
AGENT_TABLE_MAX_COLUMNS = 8
# 列上限：表格 UI 支持横向滚动，8 列对「场景 / 文案 / 卖点 / 风格 / 尺寸…」这类对象行太紧；
# 12 列覆盖常见多字段批量，再多容易把模型和渲染拖慢。超过 12 仍明确报错、不静默丢键。
_AGENT_TABLE_MAX_COLUMNS = 12
# 单元格上限：表格里经常放整段提示词/分镜，2000 字正常使用就会被踩到；8000 字覆盖常见长提示词，
# 又不至于让单行过大拖慢记忆索引 / 检索 / 前端渲染。超限仍然明确报错，不静默截断。
_AGENT_TABLE_CELL_MAX_CHARS = 8000
AGENT_TABLE_WIDTH = 520
AGENT_BATCH_WIDTH = 420


_AGENT_TABLE_CELL_NOTES = contextvars.ContextVar("agent_table_cell_notes", default=None)


def _agent_table_note(text):
    notes = _AGENT_TABLE_CELL_NOTES.get()
    if isinstance(notes, list):
        notes.append(str(text))


def _agent_table_rows_from_args(rows, columns=None):
    """rows 支持三种写法：["提示词1", ...]、[["列1", "列2"], ...]、[{"键": "值"}, ...]。

    - 对象行：有 columns 就按 columns 顺序取值（缺的填空），额外键按出现顺序补成新列；
      没有 columns 就用对象键顺序生成列名。列/键放不下（超过 12 列）时明确报错并点名哪些键。
    - 单元格允许字符串 / 数字 / 布尔；嵌套 list / dict 自动序列化成紧凑 JSON 文本（保留内容并提示）。
    - 行上限 50、列上限 12、单元格 8000 字；不合法一律报错，绝不静默丢数据。
    - 行宽不齐按最宽行补齐（空单元格是合法值，不算丢数据）。
    """
    if not isinstance(rows, list) or not rows:
        raise AgentToolError("rows 至少要有一行（每行一条提示词、单元格数组，或键对应 columns 的对象）", code="invalid_args")
    if len(rows) > AGENT_TABLE_MAX_ROWS:
        raise AgentToolError(f"一次最多 {AGENT_TABLE_MAX_ROWS} 行，现在是 {len(rows)} 行", code="invalid_args")
    raw_cols = columns if isinstance(columns, list) else []
    if len(raw_cols) > _AGENT_TABLE_MAX_COLUMNS:
        raise AgentToolError(f"columns 最多 {_AGENT_TABLE_MAX_COLUMNS} 列，现在是 {len(raw_cols)} 列；超出的列放不下，请合并或拆成多张表", code="invalid_args")
    cols = [str(c if c is not None else "").strip()[:40] for c in raw_cols]
    cols = [c for c in cols if c]
    key_order, normalized_rows, width = [], [], 1
    for i, row in enumerate(rows):
        if isinstance(row, dict):
            if not row:
                raise AgentToolError(f"第 {i + 1} 行是空对象；每行都要有内容", code="invalid_args")
            mapping = {}
            for raw_key, value in row.items():
                key = str(raw_key if raw_key is not None else "").strip()
                if not key:
                    raise AgentToolError(f"第 {i + 1} 行有空的列名；对象行的键就是列名", code="invalid_args")
                if key in mapping:
                    raise AgentToolError(f"第 {i + 1} 行有两列同名「{key}」；请合并成一列", code="invalid_args")
                mapping[key] = value
                if key not in key_order:
                    key_order.append(key)
            normalized_rows.append((i, "dict", mapping))
            width = max(width, len(mapping))
        elif isinstance(row, (list, tuple)):
            if len(row) > _AGENT_TABLE_MAX_COLUMNS:
                raise AgentToolError(f"第 {i + 1} 行有 {len(row)} 个单元格，超过最多 {_AGENT_TABLE_MAX_COLUMNS} 列；请把这一行拆成多行或缩短", code="invalid_args")
            normalized_rows.append((i, "list", list(row)))
            width = max(width, len(row))
        elif isinstance(row, str):
            normalized_rows.append((i, "list", [row]))
        else:
            raise AgentToolError(f"第 {i + 1} 行必须是字符串、单元格数组或对象（键对应 columns）；收到 {type(row).__name__}", code="invalid_args")
    # 对象行多出来的键：按出现顺序补成新列；放不下就点名报错，绝不静默丢键。
    for key in key_order:
        if key in cols:
            continue
        if len(cols) >= _AGENT_TABLE_MAX_COLUMNS:
            extra = [k for k in key_order if k not in cols]
            raise AgentToolError("行对象的键放不下（最多 %d 列），多出来的：%s；请减少字段或拆成多张表"
                                 % (_AGENT_TABLE_MAX_COLUMNS, "、".join(extra[:8])), code="invalid_args")
        cols.append(key)
    if not cols:
        cols = ["提示词"] if width == 1 else [f"第{i + 1}列" for i in range(width)]
    while len(cols) < width:
        cols.append(f"第{len(cols) + 1}列")
    base_cols = list(cols)          # 重名改名只影响展示列名；对象行按原始键取值，别因改名丢数据
    seen, uniq = {}, []
    for c in cols:
        seen[c] = seen.get(c, 0) + 1
        uniq.append(c if seen[c] == 1 else f"{c}({seen[c]})")
    out = []
    for i, kind, payload in normalized_rows:
        if kind == "dict":
            cells = [payload.get(base_cols[j]) for j in range(len(uniq))]
        else:
            cells = list(payload)
        converted = []
        for j, cell in enumerate(cells):
            if isinstance(cell, (dict, list, tuple)):
                # 模型给结构化内容时不要把整轮打回：序列化成紧凑 JSON 文本保留内容，并在步骤结果里提示
                try:
                    cell = json.dumps(cell, ensure_ascii=False, separators=(",", ":"))
                except Exception:
                    cell = str(cell)
                _agent_table_note(f"第 {i + 1} 行第 {j + 1} 列是嵌套"
                                  f"{'对象' if isinstance(cell, dict) else '数组'}，已序列化为紧凑 JSON 文本")
            text = str(cell if cell is not None else "").strip()
            if len(text) > _AGENT_TABLE_CELL_MAX_CHARS:
                raise AgentToolError(f"第 {i + 1} 行第 {j + 1} 列太长（{len(text)} 字，最多 {_AGENT_TABLE_CELL_MAX_CHARS} 字）；请精简或拆成多行", code="invalid_args")
            converted.append(text)
        converted += [""] * (len(uniq) - len(converted))
        if not any(converted):
            raise AgentToolError(f"第 {i + 1} 行是空的；每行都要有内容", code="invalid_args")
        out.append(converted)
    return uniq, out


def _agent_table_payload(columns, rows):
    return {"kind": "table", "version": 1, "columns": list(columns), "rows": [list(r) for r in rows],
            "selectedRows": list(range(len(rows))), "mergedGroups": []}


def _agent_table_row_count(node):
    table = (node or {}).get("table") if isinstance((node or {}).get("table"), dict) else {}
    rows = table.get("rows") if isinstance(table.get("rows"), list) else []
    selected = table.get("selectedRows")
    if isinstance(selected, list) and selected and (node or {}).get("tableSelectionInitialized"):
        return len([i for i in selected if isinstance(i, int) and 0 <= i < len(rows)])
    return len(rows)


def _agent_table_height(rows):
    return 120 + 44 * min(len(rows or []), 12)


def _agent_new_table_node(columns, rows, title="", x=0, y=0):
    return {"id": f"agent_tbl_{uuid.uuid4().hex[:12]}", "type": "table", "x": x, "y": y,
            "w": AGENT_TABLE_WIDTH, "h": 0, "title": title or "多维表格",
            "table": _agent_table_payload(columns, rows), "tableSelectionInitialized": True,
            "created_at": now_ms()}


def _agent_new_batch_node(media="image", title="", x=0, y=0):
    node = {"id": f"agent_batch_{uuid.uuid4().hex[:12]}", "type": "smart-batch", "x": x, "y": y,
            "w": AGENT_BATCH_WIDTH, "h": 0, "title": title or "生成输入", "created_at": now_ms()}
    if media == "video":
        node["tableBatchVideo"] = True
        node["runSettings"] = {"engine": "api", "apiKind": "video"}
    return node


def _agent_batch_media(node):
    return "video" if (node or {}).get("tableBatchVideo") else "image"


def _agent_batch_tables(canvas, batch_id):
    by_id = _agent_nodes_by_id(canvas)
    return [by_id[i] for i in _agent_upstream_ids(canvas, batch_id) if _agent_node_type(by_id.get(i)) == "table"]


def _agent_table_batches(canvas, table_id):
    by_id = _agent_nodes_by_id(canvas)
    out = []
    for conn in (canvas.get("connections") or []):
        if isinstance(conn, dict) and conn.get("from") == table_id and (conn.get("kind") or "flow") == "input":
            node = by_id.get(conn.get("to"))
            if node is not None and _agent_node_type(node) == "smart-batch" and node not in out:
                out.append(node)
    return out


def _agent_table_summary_extra(node):
    table = node.get("table") if isinstance(node.get("table"), dict) else {}
    rows = table.get("rows") if isinstance(table.get("rows"), list) else []
    preview = []
    for row in rows[:4]:
        cells = [str(c) for c in (row if isinstance(row, list) else []) if isinstance(c, str) and c.strip()]
        preview.append(" / ".join(cells)[:80])
    return {"columns": table.get("columns") or [], "rows": len(rows), "rows_preview": preview}


# ── batch_generate：一步建好「表格 → 批量生成」并开跑 ──────────────────────

def _agent_tool_batch_generate_validate(args):
    canvas_id = str(args.get("canvas_id") or "").strip()
    if not canvas_id:
        raise AgentToolError("canvas_id 不能为空", code="invalid_args")
    canvas = load_canvas(canvas_id)
    if not _agent_is_smart_canvas(canvas):
        if _agent_is_beat_canvas(canvas):
            return _agent_beat_batch_generate_validate(args, canvas, canvas_id)
        raise AgentToolError("多维表格批量生成只在智能画布里可用", code="invalid_args")
    if args.get("input_modes") is not None:
        raise AgentToolError("input_modes 只在「智能画布BEAT」支持；智能画布的表格请在画布上设置通道",
                             code="invalid_args")
    media = str(args.get("media") or "image").strip().lower()
    if media not in ("image", "video"):
        raise AgentToolError("media 只能是 image 或 video", code="invalid_args")
    columns, rows = _agent_table_rows_from_args(args.get("rows"), args.get("columns"))
    settings = dict(args.get("settings") or {}) if isinstance(args.get("settings"), dict) else {}
    settings.pop("count", None)  # 批量是一行一张，张数由行数决定
    norm = {"canvas_id": canvas_id, "media": media, "columns": columns, "rows": rows,
            "common_prompt": str(args.get("common_prompt") or "").strip()[:2000],
            "title": str(args.get("title") or "").strip()[:60],
            "settings": _agent_validate_settings(settings, media),
            "inputs": _agent_parse_inputs(args.get("inputs")),
            "run": args.get("run") is not False}
    by_id = _agent_nodes_by_id(canvas)
    missing = [i for i in norm["inputs"] if i not in by_id and not _agent_args_have_step_refs(i)]
    if missing:
        raise AgentToolError(f"inputs 里的节点不存在：{'、'.join(missing)}", code="node_not_found", status_code=404)
    for nid in norm["inputs"]:
        node = by_id.get(nid)
        if node is not None and _agent_node_type(node) not in _AGENT_SMART_CONNECT_RULES["table"]:
            raise AgentToolError(f"{_agent_node_ref(node)} 不能接到表格（表格可接：参考图/图片组/提示词/文本节点）",
                                 code="invalid_connection")
    return norm


def _agent_tool_batch_generate_run(args):
    if args.get("beat"):
        return _agent_beat_batch_generate_run(args)
    canvas_id = args["canvas_id"]

    def _mutate(canvas):
        rows = args["rows"]
        th = _agent_table_height(rows)
        made = {}
        anchors = list(args["inputs"])
        if args["common_prompt"]:
            px, py = _agent_default_position(canvas, anchors, 316, 240)
            prompt = _agent_new_smart_node("prompt", "统一要求", args["common_prompt"], px, py)
            canvas.setdefault("nodes", []).append(prompt)
            made["prompt"] = prompt
            anchors = anchors + [prompt["id"]]
        tx, ty = _agent_default_position(canvas, anchors, AGENT_TABLE_WIDTH, th)
        table = _agent_new_table_node(args["columns"], rows, args["title"], tx, ty)
        canvas.setdefault("nodes", []).append(table)
        bx, by = _agent_free_position(canvas, tx + AGENT_TABLE_WIDTH + 130, ty, AGENT_BATCH_WIDTH, 300)
        batch = _agent_new_batch_node(args["media"], "", bx, by)
        if args["settings"]:
            _agent_apply_settings(batch, args["media"], args["settings"])
        canvas["nodes"].append(batch)
        sources = list(args["inputs"]) + ([made["prompt"]["id"]] if "prompt" in made else [])
        for src in sources:
            err = _agent_connect_check(canvas, src, table["id"])
            if err:
                raise AgentToolError("表格的上游连不上：" + err, code="invalid_connection")
            _agent_connect_apply(canvas, src, table["id"])
        _agent_connect_apply(canvas, table["id"], batch["id"])
        return {"table": table, "batch": batch, "prompt": made.get("prompt")}

    canvas, made = _agent_mutate_canvas(canvas_id, _mutate)
    _agent_snapshot(canvas, note=f"agent:batch_generate {made['batch']['id']}")
    by_id = _agent_nodes_by_id(canvas)
    table, batch = by_id.get(made["table"]["id"], made["table"]), by_id.get(made["batch"]["id"], made["batch"])
    n = len(args["rows"])
    out = {"node_id": batch["id"], "table_node_id": table["id"], "batch_node_id": batch["id"],
           "table_alias": table.get("alias") or "", "batch_alias": batch.get("alias") or "",
           "rows": n, "kind": args["media"], "generation_units": n if args["run"] else 0}
    if made.get("prompt"):
        out["prompt_node_id"] = made["prompt"]["id"]
    if args["run"]:
        out["client_action"] = {"type": "run_batch", "node_id": batch["id"], "rows": n}
        out["message"] = f"已建好表格和批量生成节点，{n} 行会在画布上逐行出{'视频' if args['media'] == 'video' else '图'}"
    return out


def _agent_tool_batch_generate_preview(args, canvas):
    rows = args.get("rows") if isinstance(args.get("rows"), list) else []
    media = "视频" if str(args.get("media") or "") == "video" else "图"
    return f"新建多维表格（{len(rows)} 行）→ 批量生成，逐行出{media}，共 {len(rows)} 次生成"


# ── run_batch：跑已有的批量生成节点（或某张表格后面的批量节点）──────────────

def _agent_tool_run_batch_validate(args):
    canvas_id = str(args.get("canvas_id") or "").strip()
    node_id = str(args.get("node_id") or "").strip()
    if not canvas_id or not node_id:
        raise AgentToolError("canvas_id 与 node_id 不能为空", code="invalid_args")
    canvas = load_canvas(canvas_id)
    if not _agent_is_smart_canvas(canvas):
        if _agent_is_beat_canvas(canvas):
            return _agent_beat_run_batch_validate(args, canvas, canvas_id)
        raise AgentToolError("批量生成只在智能画布里可用", code="invalid_args")
    node = _agent_find_node(canvas, node_id)
    if not node:
        raise AgentToolError(f"节点 {node_id} 不存在", code="node_not_found", status_code=404)
    t = _agent_node_type(node)
    if t == "table":
        batches = _agent_table_batches(canvas, node_id)
        if not batches:
            raise AgentToolError(f"{_agent_node_ref(node)} 后面还没接批量生成节点；先用 create_node(type=batch, inputs=[表格]) 接一个",
                                 code="invalid_args")
        node = batches[0]
    elif t != "smart-batch":
        raise AgentToolError(f"{_agent_node_ref(node)} 不是表格/批量节点；单个图片/视频节点用 run_generation", code="invalid_args")
    tables = _agent_batch_tables(canvas, node["id"])
    if not tables:
        raise AgentToolError(f"{_agent_node_ref(node)} 上游没有接多维表格", code="invalid_args")
    rows = _agent_table_row_count(tables[0])
    if not rows:
        raise AgentToolError(f"{_agent_node_ref(tables[0])} 没有可生成的行", code="invalid_args")
    norm = {"canvas_id": canvas_id, "node_id": node["id"], "rows": rows, "table_id": tables[0]["id"]}
    if args.get("row_numbers") is not None:
        total = len(((tables[0].get("table") or {}).get("rows")) or [])
        try:
            picked = sorted({int(n) for n in (args.get("row_numbers") or [])})
        except (TypeError, ValueError):
            raise AgentToolError("row_numbers 必须是行号数组（从 1 开始）", code="invalid_args")
        bad = [n for n in picked if not 1 <= n <= total]
        if not picked or bad:
            raise AgentToolError(f"row_numbers 要在 1-{total} 之间", code="invalid_args")
        norm["row_numbers"], norm["rows"] = picked, len(picked)
    return norm


def _agent_tool_run_batch_run(args):
    if args.get("beat"):
        return _agent_beat_run_batch_run(args)
    if args.get("row_numbers"):
        def _mutate(canvas):
            table = _agent_find_node(canvas, args["table_id"])
            if table is None:
                raise AgentToolError("表格不见了", code="node_not_found", status_code=404)
            table.setdefault("table", {})["selectedRows"] = [n - 1 for n in args["row_numbers"]]
            table["tableSelectionInitialized"] = True
            table["tableBatchManualSelection"] = False
        _agent_mutate_canvas(args["canvas_id"], _mutate)
    return {"node_id": args["node_id"], "rows": args["rows"], "generation_units": args["rows"],
            "client_action": {"type": "run_batch", "node_id": args["node_id"], "rows": args["rows"]},
            "message": f"{args['rows']} 行会在画布上逐行生成"}


def _agent_tool_run_batch_preview(args, canvas):
    return f"运行批量生成 {args.get('node_id')}（按表格逐行生成）"


# ── review_table：表格 / 批量节点的确定性自检（只读，不调模型、不改画布）────────────

_AGENT_BEAT_MEDIA_EXT_RE = re.compile(
    r"\.(?:png|jpe?g|webp|gif|avif|mp4|webm|mov|m4v|mp3|wav|m4a|aac|ogg)(?:[?#]\S*)?$", re.I)


def _agent_beat_is_media_cell(value):
    """单元格是不是素材地址（与前端 isMediaRef 同口径：单行、无空格、已知前缀或媒体扩展名）。"""
    text = str(value or "").strip()
    if not text or re.search(r"\s", text):
        return False
    if re.match(r"^(?:novai|openarc)-asset:|^openarc-resource:|^blob:|^data:(?:image|video|audio)/"
                r"|^/(?:assets|output)/", text, re.I):
        return True
    if re.match(r"^https?://", text, re.I):
        return bool(_AGENT_BEAT_MEDIA_EXT_RE.search(text))
    return bool(_AGENT_BEAT_MEDIA_EXT_RE.search(text)) and (
        "/" in text or "\\" in text or not re.search(r"[\u4e00-\u9fff]", text))


_AGENT_BEAT_ALL_HINT_RE = re.compile(r"整组|全部|全组|所有|整列|每一张|每张|都用")
_AGENT_BEAT_REF_RE = re.compile(r"输入\s*(\d+)(?!\d)")
_AGENT_BEAT_PARALLEL_RE = re.compile(r"^\s*(?:、|和|与|及|,|，|/|\+)\s*$")


def _agent_beat_row_all_channels(text):
    """行文本里明确要「整组 / 全部 / 所有 / 每张 / 都用」的输入通道号（与前端 inferChannelModesFromRows 同口径）。"""
    out = set()
    for seg in re.split(r"[\n；;。！!？?]", str(text or "")):
        refs = [{"n": int(m.group(1)), "start": m.start(), "end": m.end()}
                for m in _AGENT_BEAT_REF_RE.finditer(seg)]

        def tail_of(index):
            tail = seg[refs[index]["end"]:refs[index]["end"] + 16]
            stop = _AGENT_BEAT_REF_RE.search(tail)
            return tail[:stop.start()] if stop else tail

        for index, ref in enumerate(refs):
            if _AGENT_BEAT_ALL_HINT_RE.search(tail_of(index)):
                out.add(ref["n"])
        # 并列：「输入 1、输入 2 整组」共享最后一个输入组后面的说法
        i = 0
        while i < len(refs):
            j = i
            while (j + 1 < len(refs)
                   and _AGENT_BEAT_PARALLEL_RE.match(seg[refs[j]["end"]:refs[j + 1]["start"]])):
                j += 1
            if j > i and _AGENT_BEAT_ALL_HINT_RE.search(tail_of(j)):
                for k in range(i, j + 1):
                    out.add(refs[k]["n"])
            i = j + 1
    return out


def _agent_beat_review_model(batch):
    """批量节点用的模型与参考图上限（来自 /api/model-caps 的同一份权威规格；拿不到就返回空表，不猜）。"""
    if not isinstance(batch, dict):
        return {}
    data = batch.get("data") if isinstance(batch.get("data"), dict) else {}
    gen = data.get("gen") if isinstance(data.get("gen"), dict) else {}
    params = gen.get("params") if isinstance(gen.get("params"), dict) else {}
    raw = str(params.get("model") or "").strip()
    provider, _, model = raw.partition("::")
    if not model:
        model, provider = raw, ""
    if not model:
        return {}
    kind = "video" if str(batch.get("kind")) == "video" else "image"
    try:
        caps = model_caps_for(provider, model, kind) or {}
    except Exception:
        caps = {}
    try:
        ref_max = int(caps.get("ref_max") or 0)
    except (TypeError, ValueError):
        ref_max = 0
    return {"provider": provider, "model": model, "kind": kind, "ref_max": ref_max}


def _agent_tool_review_table_preview(args, canvas):
    return f"只读检查表格 / 批量节点 {args.get('node_id')} 的通道、行数、输入编号和参考图上限（不改画布）"


def _agent_tool_review_table_validate(args):
    canvas_id = str(args.get("canvas_id") or "").strip()
    node_id = str(args.get("node_id") or "").strip()
    if not canvas_id or not node_id:
        raise AgentToolError("canvas_id 与 node_id 不能为空", code="invalid_args")
    canvas = load_canvas(canvas_id)
    if not _agent_is_beat_canvas(canvas):
        raise AgentToolError("review_table 只支持「智能画布BEAT」的多维表格 / 批量节点", code="invalid_args")
    node = _agent_find_node(canvas, node_id)
    if node is None:
        raise AgentToolError(f"节点 {node_id} 不存在", code="node_not_found", status_code=404)
    kind = str(node.get("kind") or "")
    if kind == "table":
        table_id = node_id
        batches = _agent_beat_downstream_batches(canvas, table_id)
        batch_id = str(batches[0].get("id") or "") if batches else ""
    elif kind in ("image", "video"):
        tables = _agent_beat_upstream_tables(canvas, node_id)
        if not tables:
            raise AgentToolError(f"{_agent_node_ref(node)} 上游没有多维表格；review_table 检查的是表格批量节点",
                                 code="invalid_args")
        table_id, batch_id = str(tables[0].get("id") or ""), node_id
    else:
        raise AgentToolError(f"{_agent_node_ref(node)} 不是多维表格或表格下游的批量节点", code="invalid_args")
    return {"canvas_id": canvas_id, "node_id": node_id, "table_id": table_id, "batch_id": batch_id}


def _agent_beat_review_table_result(canvas, node_id, table_id, batch_id="", ignore_journal=False):
    """review_table 的公共实现：给三个建表 / 批量工具内部复用，避免它们再读一次画布。
    ignore_journal=True 时把「上次批量有失败行」降成 info：重试时历史失败不该挡住这次开跑。"""
    by_id = _agent_nodes_by_id(canvas)
    table = by_id.get(table_id) or {}
    batch = by_id.get(batch_id or "") or None
    data = table.get("data") if isinstance(table.get("data"), dict) else {}
    table_data = data.get("table") if isinstance(data.get("table"), dict) else {}
    columns = [str(c) for c in (table_data.get("columns") or [])]
    rows = [list(row) for row in (table_data.get("rows") or []) if isinstance(row, list)]
    rows = [[str(cell if cell is not None else "") for cell in row] for row in rows]
    channels = _agent_beat_table_channels(canvas, table_id)
    findings, seen_texts = [], set()

    def add(level, text):
        if text and text not in seen_texts:
            seen_texts.add(text)
            findings.append({"level": level, "text": text})

    def row_list(numbers, limit=8):
        shown = "、".join(str(n) for n in numbers[:limit])
        return shown + (" 等" if len(numbers) > limit else "")

    sequence_channels = [ch for ch in channels if ch["mode"] == "sequence"]
    row_capacity = max([len(ch["items"]) for ch in sequence_channels] or [0])
    if sequence_channels and len(rows) != row_capacity:
        widest = max(sequence_channels, key=lambda ch: len(ch["items"]))
        if len(rows) < row_capacity:
            add("error", f"表格只有 {len(rows)} 行，但「逐行」通道「{widest['title']}」有 {row_capacity} 张素材："
                         f"第 {len(rows) + 1}-{row_capacity} 行没有对应素材，后 {row_capacity - len(rows)} 张用不上")
        else:
            add("warn", f"表格有 {len(rows)} 行，但「逐行」通道「{widest['title']}」只有 {row_capacity} 张素材："
                        f"第 {row_capacity + 1} 行起这一列没有图（会缺参考）")
    for index, ch in enumerate(channels):
        if not ch["items"]:
            add("error", f"输入 {index + 1}「{ch['title']}」没有素材：上游还没出结果或素材节点是空的，这一列不会发任何图")
    modes = table_data.get("inputModes") if isinstance(table_data.get("inputModes"), dict) else {}
    for key in modes:
        hit = re.match(r"^input-(\d+)$", str(key))
        if not hit or not 1 <= int(hit.group(1)) <= len(channels):
            add("warn", f"表格记着通道 {key} 的模式，但实际只有 {len(channels)} 条输入通道（可能删过连线）")

    bad_refs, empty_refs = {}, {}
    for ri, row in enumerate(rows):
        for cell in row:
            for hit in re.finditer(r"输入\s*(\d+)", str(cell)):
                n = int(hit.group(1))
                if n < 1 or n > len(channels):
                    bad_refs.setdefault(n, []).append(ri + 1)
                elif not channels[n - 1]["items"]:
                    empty_refs.setdefault(n, []).append(ri + 1)
    for n in sorted(bad_refs):
        add("error", f"第 {row_list(bad_refs[n])} 行写着「输入 {n}」，但表格只有 {len(channels)} 条输入通道："
                     "行文本里的编号过期，模型会照着错号找图")
    for n in sorted(empty_refs):
        add("warn", f"第 {row_list(empty_refs[n])} 行引用「输入 {n}」，但这条通道没有素材")

    wants_all = {}
    for ri, row in enumerate(rows):
        for number in _agent_beat_row_all_channels("\n".join(row)):
            if 1 <= number <= len(channels):
                wants_all.setdefault(number, []).append(ri + 1)
    for number in sorted(wants_all):
        channel = channels[number - 1]
        mode_label = _AGENT_BEAT_CHANNEL_MODE_LABELS.get(channel["mode"], channel["mode"])
        if channel["mode"] == "shared":
            add("error", f"第 {row_list(wants_all[number])} 行写着「输入 {number} 整组/全部」，但通道「{channel['title']}」"
                         f"是「{mode_label}」：每行只发 1 张，整组不会带上。建表时写 "
                         f"input_modes {{\"input-{number}\": \"all\"}}，或把表头这一列改成「全部」")
        elif channel["mode"] == "sequence":
            add("warn", f"第 {row_list(wants_all[number])} 行要「输入 {number} 整组」，但通道「{channel['title']}」"
                        f"是「{mode_label}」：每行只会取这一组的一张，要整组参考请改成「全部」")

    channel_counts = {len(ch["items"]) for ch in channels if ch["items"]}
    if len(rows) > 1 and not modes and len(channel_counts) > 1:
        add("warn", "表格没有设置任何通道模式（全是「沿用」）：每条通道每行只发 1 张，张数多的组"
                    "（产品多角度 / 三视图 / 姿势）整组不会带上；要整组参考请建表时写 input_modes"
                    "（如 {\"input-2\": \"all\"}）或点表头设「全部」")

    empty_rows = [i + 1 for i, row in enumerate(rows) if not any(str(cell).strip() for cell in row)]
    if empty_rows:
        add("warn", f"有 {len(empty_rows)} 行是空的：第 {row_list(empty_rows)} 行不会参与批量生成")
    no_text_rows = [i + 1 for i, row in enumerate(rows)
                    if any(str(cell).strip() for cell in row)
                    and not any(str(cell).strip() and not _agent_beat_is_media_cell(cell) for cell in row)]
    if no_text_rows:
        add("warn", f"有 {len(no_text_rows)} 行只有素材、没有任何提示词文字：第 {row_list(no_text_rows)} 行"
                    "生成时没有可用的提示词，容易出一堆一样的图")

    journal_failed = 0
    if batch is not None:
        batch_data = batch.get("data") if isinstance(batch.get("data"), dict) else {}
        batch_state = batch_data.get("batch") if isinstance(batch_data.get("batch"), dict) else {}
        journal = batch_state.get("journal") if isinstance(batch_state.get("journal"), dict) else {}
        journal_rows = [r for r in (journal.get("rows") or []) if isinstance(r, dict)]
        failed = [r for r in journal_rows if r.get("status") == "failed"]
        journal_failed = len(failed)
        if failed:
            detail = "；".join("第 %s 行" % r.get("row") + (f"（{str(r.get('error'))[:50]}）" if r.get("error") else "")
                              for r in failed[:6])
            if ignore_journal:
                add("info", f"上次批量有 {len(failed)} 行失败（{detail}）；这次重跑会继续跑没完成的行")
            else:
                add("error", f"上次批量有 {len(failed)} 行失败：{detail}" + (" 等" if len(failed) > 6 else "")
                             + "；改好后 run_batch 只会重跑失败的行")
        warned = [r for r in journal_rows if r.get("warn")]
        if warned:
            add("info", f"上次批量有 {len(warned)} 行提醒（参考图被截 / 参数降级）：第 "
                        + row_list([r.get("row") for r in warned]) + "，可以对照下面的通道检查")

    model_info = _agent_beat_review_model(batch) if batch is not None else {}
    ref_max = int(model_info.get("ref_max") or 0)
    own_refs = 0
    if batch is not None and str(batch.get("kind")) == "image":
        for conn in (canvas.get("connections") or []):
            if not isinstance(conn, dict) or conn.get("to") != batch.get("id"):
                continue
            source = by_id.get(str(conn.get("from") or ""))
            if isinstance(source, dict) and str(source.get("kind")) == "image" and _agent_beat_url(source):
                own_refs += 1
    if batch is None:
        add("info", "这张表格后面还没接批量生成节点，参考图上限检查先跳过（接上 create_node type=batch 再复查）")
    elif not model_info:
        add("info", "批量节点还没选模型，参考图上限检查跳过；选好模型后可以再 review_table 一次")
    elif not ref_max:
        add("info", f"拿不到模型 {model_info.get('model')} 的参考图上限，截断检查跳过")
    else:
        cap = max(0, ref_max - min(own_refs, ref_max))
        cut_rows, sample = [], {}
        for ri in range(len(rows)):
            media = []
            for ch in channels:
                for item in _agent_beat_channel_items_for_row(ch, ri):
                    if item.get("kind") == "image":
                        media.append((ch, item))
            if len(media) <= cap:
                continue
            cut_rows.append(ri + 1)
            if not sample:
                for index, (ch, _item) in enumerate(media):
                    key = ch["title"] or ch["id"]
                    stat = sample.setdefault(key, {"total": 0, "sent": 0})
                    stat["total"] += 1
                    if index < cap:
                        stat["sent"] += 1
        if cut_rows:
            detail = "、".join(f"「{title}」{stat['total']} 张只发送 {stat['sent']} 张"
                               for title, stat in sample.items() if stat["sent"] < stat["total"])
            add("warn", f"批量模型最多 {ref_max} 张参考图" + (f"（节点自己连了 {own_refs} 张，也占名额）" if own_refs else "")
                         + f"：第 {row_list(cut_rows)} 行会被截（以第 {cut_rows[0]} 行为例：{detail or '多出的图不会发送'}）")

    order = {"error": 0, "warn": 1, "info": 2}
    findings.sort(key=lambda item: order.get(item["level"], 3))
    errors = [f for f in findings if f["level"] == "error"]
    warns = [f for f in findings if f["level"] == "warn"]
    mode_counts = {"sequence": 0, "all": 0, "shared": 0}
    for ch in channels:
        mode_counts[ch["mode"]] = mode_counts.get(ch["mode"], 0) + 1
    stats = {"rows": len(rows), "columns": len(columns), "channels": len(channels),
             "modes": mode_counts, "items": sum(len(ch["items"]) for ch in channels),
             "row_capacity": row_capacity,
             "empty_channels": [i + 1 for i, ch in enumerate(channels) if not ch["items"]],
             "batch_node_id": str((batch or {}).get("id") or ""),
             "model": model_info.get("model") or "", "ref_max": ref_max,
             "journal_failed": journal_failed,
             "input_modes": dict(modes),
             "input_modes_auto": [str(x) for x in (table_data.get("inputModesAuto") or [])],
             "channels_info": [{"id": ch["id"], "title": ch["title"], "mode": ch["mode"],
                                "items": len(ch["items"])} for ch in channels]}
    summary = {"errors": len(errors), "warns": len(warns),
               "infos": len(findings) - len(errors) - len(warns), "ok": not errors}
    parts = [f"{len(rows)} 行 × {len(columns)} 列", f"{len(channels)} 条输入通道"]
    parts.append("模式：" + " / ".join(f"{label}{mode_counts[key]} 条" for key, label in
                                     (("sequence", "逐行"), ("all", "全部"), ("shared", "沿用"))))
    if row_capacity:
        parts.append(f"逐行通道最多 {row_capacity} 张")
    if model_info and ref_max:
        parts.append(f"批量模型参考图上限 {ref_max} 张")
    head = "表格自检通过：" + "，".join(parts) + "。可以开跑。"
    if findings:
        top = "；".join(f["text"] for f in findings[:3])
        more = f"（共 {len(findings)} 条，见 findings）" if len(findings) > 3 else ""
        if errors:
            message = f"表格自检发现 {len(errors)} 个错误、{len(warns)} 个提醒：{top}{more}。先把错误改掉再 run_batch。"
        elif warns:
            message = f"表格自检有 {len(warns)} 个提醒：{top}{more}。不影响开跑，可以按提醒微调后再 run_batch。"
        else:
            message = head + "提示：" + top
    else:
        message = head
    return {"summary": summary, "findings": findings, "stats": stats, "message": message,
            "node_id": node_id, "table_id": table_id, "batch_id": batch_id or ""}


def _agent_tool_review_table_run(args):
    canvas = load_canvas(args["canvas_id"])
    return _agent_beat_review_table_result(canvas, args["node_id"], args["table_id"], args.get("batch_id") or "")


def _agent_beat_review_blocks(review):
    """审查结果里有没有阻断自动开跑的 error（journal 历史已由 ignore_journal 降成 info）。"""
    return any(isinstance(item, dict) and item.get("level") == "error"
               for item in ((review or {}).get("findings") or []))


def _agent_beat_review_brief(review):
    """给三个建表 / 批量工具用的一句话审查结论（附录在 message 末尾）。"""
    review = review if isinstance(review, dict) else {}
    summary = review.get("summary") if isinstance(review.get("summary"), dict) else {}
    stats = review.get("stats") if isinstance(review.get("stats"), dict) else {}
    text = (f"表格审查：{int(stats.get('rows') or 0)} 行 × {int(stats.get('channels') or 0)} 输入，"
            f"{int(summary.get('errors') or 0)} 个 error / {int(summary.get('warns') or 0)} 个 warn")
    errors = [str(item.get("text") or "") for item in (review.get("findings") or [])
              if isinstance(item, dict) and item.get("level") == "error" and str(item.get("text") or "")]
    if errors:
        text += "。先修这几条再跑：① " + errors[0] + (("；② " + errors[1]) if len(errors) > 1 else "")
    return text


def _agent_beat_with_review(result, review):
    """把内部审查结果挂到工具返回：review={summary,findings,stats}，message 末尾补一句话结论。"""
    if not isinstance(result, dict) or not isinstance(review, dict):
        return result
    result["review"] = {key: review.get(key) for key in ("summary", "findings", "stats")}
    brief = _agent_beat_review_brief(review)
    if brief:
        base = str(result.get("message") or "").rstrip("。；;，, ")
        result["message"] = (base + "。" if base else "") + brief
    return result


# ---------------------------------------------------------------------------
# 生成后自检（P2-1，第 39 轮）：结果出来后，让能看图的模型对照用户原话逐张看，
# 只指出明显问题并给修正后的提示词；服务端据此拼好「改提示词 → 重跑」步骤，
# 但绝不自己执行 —— 页面上用户点「按建议重做」才走正常的批准执行（受生成次数约束）。
# ---------------------------------------------------------------------------

AGENT_REVIEW_MAX_IMAGES = 6


class AgentReviewItem(BaseModel):
    url: str
    node_id: str = ""
    label: str = ""
    prompt: str = ""
    row: int = 0


class AgentReviewRequest(BaseModel):
    canvas_id: str
    instruction: str = ""
    items: list[AgentReviewItem] = []
    batch_node_id: str = ""
    provider: str = ""
    model: str = ""


_AGENT_REVIEW_PROMPT = (
    "你是出图质检员。用户的原话是：「{instruction}」。\n"
    "下面每张图都标了名字和生成它用的提示词。逐张对照用户原话检查：主体对不对、数量对不对、"
    "用户点名的颜色/构图/留白/文字/风格有没有做到、有没有明显的画面错误（多出来的肢体、乱码文字、主体被裁掉）。\n"
    "只指出明显的问题，不要吹毛求疵；拿不准就算合格。每条问题用一句中文大白话写，说清楚哪里不对。\n"
    "不合格的图，revised_prompt 给一条修正后的完整提示词（在原提示词基础上改，保留用户要的东西，只改出问题的部分）；合格的留空。\n"
    "只返回 JSON，不要代码围栏，不要别的文字："
    "{{\"summary\": \"一句话总评\", \"items\": [{{\"label\": \"图名\", \"ok\": true, \"issues\": [], \"revised_prompt\": \"\"}}]}}"
)


def _agent_review_pick_chat(provider, model):
    """优先用用户当前的对话模型（它看得了图的话），否则在已配置平台里找一个能看图的模型。"""
    provider, model = str(provider or "").strip(), str(model or "").strip()
    # 审查失败本来就是可降级的：不要因为「上次看图失败」就把当前模型当硬门槛，
    # 仍然先试当前模型一次（失败记忆只在选其它候选 / 提示文案里用）。
    if provider and model and _agent_model_maybe_vision(model):
        try:
            base, headers, mdl = resolve_chat_provider(provider, model, "")
            if base:
                return {"provider": provider, "base": base, "headers": headers, "model": mdl or model,
                        "provider_cfg": get_api_provider(provider) or {}}
        except HTTPException:
            pass
    return _agent_pick_caption_model()


def _agent_review_unavailable_text(provider, model):
    """审查没模型可用时，把原因说清楚：是当前模型看图失败被暂时跳过，还是它根本没声明支持看图。"""
    provider, model = str(provider or "").strip(), str(model or "").strip()
    key = f"{provider}:{model}" if provider and model else ""
    entry = _agent_vision_failure_entry(key) if key else {}
    if entry:
        head = f"当前模型「{model}」{_agent_vision_deny_note(key)}"
    elif model and not _agent_model_maybe_vision(model):
        head = f"当前模型「{model}」未声明支持看图"
    elif model:
        head = f"当前模型「{model}」看不了图（可能不支持图片输入或没有权限）"
    else:
        head = "没有找到可用的看图模型"
    tried = []
    for failed_key, info in list(_AGENT_VISION_FAILURES.items())[-3:]:
        if isinstance(info, dict) and str(info.get("reason") or "").strip():
            tried.append(f"{failed_key}（{info['reason']}）")
    if tried and not entry:
        head += "；最近失败的看图模型：" + "、".join(tried)
    return head + "。可以在 API 设置里换一个能看图的对话模型，或稍后自动重试。"


def _agent_review_parse(text):
    try:
        data = _agent_json_loads(_agent_extract_json(text) or "{}")
    except Exception:
        return None
    if not isinstance(data, dict) or not isinstance(data.get("items"), list):
        return None
    return data


# 智能画布：生成结果回来后自动审查（图片直接看，视频抽开头 / 中间 / 结尾 3 帧），结论回灌给助手并显示在对话里
AGENT_BEAT_REVIEW_ENABLED = str(os.environ.get("NOVAI_AGENT_BEAT_REVIEW", "1")).strip().lower() not in ("0", "false", "off", "no")
AGENT_BEAT_REVIEW_MAX_ITEMS = 8
AGENT_BEAT_REVIEW_PER_NODE = 2          # 同一个节点最多审两次（第一次 + 重做后复查）
_AGENT_BEAT_REVIEW_PROMPT = (
    "你是严格但讲道理的出片质检员。用户的要求：「{instruction}」。{plan}\n"
    "下面每个结果都标了名字、种类和生成它用的提示词；视频给的是开头 / 中间 / 结尾 3 帧。逐个对照用户要求和提示词检查："
    "主体 / 产品对不对、外观是否和参考一致、数量、画幅比例与构图、风格与色调、用户点名的文字和元素有没有做到、"
    "有没有明显的画面错误（畸形肢体、乱码文字、主体被裁掉、产品变形、画面崩坏）；视频还要看内容是否符合这个镜头该拍的、前后帧是否连贯。\n"
    "只指出明显问题，拿不准就算合格。每条问题用一句中文大白话说清哪里不对。不合格的给 revised_prompt"
    "（在原提示词基础上改，保留用户要的东西，只改出问题的部分）；合格的留空。\n"
    "只返回 JSON，不要代码围栏，不要别的文字："
    "{{\"summary\": \"一句话总评\", \"items\": [{{\"label\": \"名字\", \"ok\": true, \"issues\": [], \"revised_prompt\": \"\"}}]}}"
)


def _agent_video_frame_urls(url, count=3, max_side=768):
    """本地视频按 10% / 50% / 90% 位置抽帧，返回 JPEG data URL 列表；外链或读不出来返回空表。"""
    path = output_file_from_url(url)
    if not path or not os.path.isfile(path):
        return []
    frames = []
    try:
        import cv2
        cap = cv2.VideoCapture(path)
        try:
            total = int(cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
            positions = [0] if total <= 1 else [int(total * f) for f in ((0.1, 0.5, 0.9) if count >= 3 else (0.5,))]
            for pos in positions:
                cap.set(cv2.CAP_PROP_POS_FRAMES, max(0, min(pos, max(total - 1, 0))))
                ok, frame = cap.read()
                if not ok or frame is None:
                    continue
                img = Image.fromarray(cv2.cvtColor(frame, cv2.COLOR_BGR2RGB))
                img.thumbnail((max_side, max_side), Image.LANCZOS)
                buf = io.BytesIO()
                img.convert("RGB").save(buf, format="JPEG", quality=82)
                frames.append("data:image/jpeg;base64," + base64.b64encode(buf.getvalue()).decode("ascii"))
        finally:
            cap.release()
    except Exception as exc:
        print(f"[Agent] 视频抽帧失败 {url}: {exc}")
    return frames


async def _agent_beat_review(chat, instruction, roadmap, outcomes):
    """审查一批 BEAT 生成结果。返回 {summary, model, items:[{label,node_id,url,kind,ok,issues,revised_prompt}]}；
    没有能看图的模型 / 没东西可审 / 模型没回应时返回 None（不挡流程）。"""
    items = [o for o in outcomes if o.get("ok") and o.get("url") and o.get("kind") in ("image", "video", "timeline")]
    items = items[:AGENT_BEAT_REVIEW_MAX_ITEMS]
    if not items:
        return None
    review_chat = _agent_review_pick_chat((chat or {}).get("provider"), (chat or {}).get("model"))
    if review_chat is None:
        return {"summary": _agent_review_unavailable_text((chat or {}).get("provider"),
                                                          (chat or {}).get("model")),
                "model": "", "items": [], "skipped": True}
    plan = ("整体方案：" + "；".join(x.get("stage", "") for x in (roadmap or []))) if roadmap else ""
    parts = [{"type": "text", "text": _AGENT_BEAT_REVIEW_PROMPT.format(instruction=str(instruction or "")[:800], plan=plan[:400])}]
    sent = []
    for o in items:
        is_video = o["kind"] in ("video", "timeline") or is_video_reference_value(o["url"])
        pics = _agent_video_frame_urls(o["url"]) if is_video else [_agent_image_payload_url(o["url"])]
        pics = [x for x in pics if x]
        if not pics:
            continue
        label = str(o.get("name") or o["node_id"])[:30]
        parts.append({"type": "text", "text": f"【{label}】（{'视频，3 帧' if is_video else '图片'}）提示词：{o.get('prompt') or '（无）'}"})
        for pic in pics:
            parts.append({"type": "image_url", "image_url": {"url": pic}})
        sent.append(dict(o, label=label))
    if not sent:
        return None
    data, tried = None, []
    for attempt in range(3):
        try:
            text = await _agent_run_chat(review_chat, [{"role": "user", "content": parts}])
        except AgentRunError as exc:
            print(f"[Agent] BEAT 结果审查失败（{review_chat.get('model')}）: {exc.message}")
            tried.append(str(review_chat.get("model") or ""))
            _agent_vision_record_failure(_agent_chat_vision_key(review_chat),
                                         _agent_clean_error_text(exc.message))
            if attempt == 0:
                continue        # 第一次失败只是暂时跳过：先给当前模型再试一次（审查失败可降级）
            review_chat = _agent_pick_caption_model(_agent_chat_vision_key(review_chat)) if attempt < 2 else None
            if review_chat is None:
                break
            continue
        _agent_vision_clear(_agent_chat_vision_key(review_chat))
        data = _agent_review_parse(text)
        if data is not None:
            break
    if data is None:
        # 审查没做成要说出来，不能悄悄当成合格
        why = ("能看图的模型都没回应（试过：" + "、".join(t for t in tried if t) + "），可能是令牌过期或没有权限"
               if tried else "看图模型的回复解析不了")
        return {"summary": "这批结果没审查成：" + why + "。可以在 API 设置里检查看图模型。",
                "model": "", "items": [], "skipped": True}
    raw = {str(v.get("label") or "").strip(): v for v in data["items"] if isinstance(v, dict)}
    verdicts = []
    for idx, it in enumerate(sent):
        v = raw.get(it["label"]) or (data["items"][idx] if idx < len(data["items"]) and isinstance(data["items"][idx], dict) else {})
        issues = [str(x).strip()[:120] for x in (v.get("issues") or []) if str(x).strip()][:4]
        ok = bool(v.get("ok", not issues)) and not issues
        verdicts.append({"label": it["label"], "node_id": it["node_id"], "url": it["url"], "kind": it["kind"],
                         "ok": ok, "issues": issues,
                         "revised_prompt": "" if ok else str(v.get("revised_prompt") or "").strip()[:1500]})
    return {"summary": str(data.get("summary") or "").strip()[:200], "model": review_chat.get("model") or "",
            "items": verdicts}


def _agent_review_prompt_holder(canvas, node):
    """改提示词改哪个节点：节点自己写了提示词就改它；否则改它唯一的上游提示词节点；都没有就写在它自己身上。"""
    if _agent_node_own_prompt(node).strip():
        return node
    by_id = _agent_nodes_by_id(canvas)
    ups = [by_id[i] for i in _agent_upstream_ids(canvas, node.get("id")) if _agent_node_kind(by_id.get(i)) == "prompt"]
    return ups[0] if len(ups) == 1 else node


def _agent_review_fix_plan(canvas, req, verdicts):
    """不合格的图 → 批准后要跑的步骤、生成次数，以及「允许 / 未变化 / 到上限」三类状态。

    规则 3 / 4：审查触发的重跑先比对新旧请求、再看这个节点自动重跑过几次；
    timeline / 批量行不在护栏范围（它们不带参考图），照旧给步骤。"""
    steps, units = [], 0
    allowed, unchanged, capped = [], [], []
    by_id = _agent_nodes_by_id(canvas)
    bad = [v for v in verdicts if not v["ok"] and v["revised_prompt"]]
    if not bad:
        return {"steps": steps, "units": units, "allowed": allowed,
                "unchanged": unchanged, "capped": capped}
    if req.batch_node_id:
        batch = by_id.get(req.batch_node_id)
        tables = _agent_batch_tables(canvas, req.batch_node_id) if batch is not None else []
        table = tables[0] if tables else None
        cols = ((table or {}).get("table") or {}).get("columns") or []
        rows = [list(r) for r in (((table or {}).get("table") or {}).get("rows") or []) if isinstance(r, list)]
        fix_rows = sorted({v["row"] for v in bad if 0 < v["row"] <= len(rows)})
        if table is None or len(cols) != 1 or not fix_rows:
            return {"steps": steps, "units": units, "allowed": allowed,
                    "unchanged": unchanged, "capped": capped}   # 多列表格不替用户猜该改哪一列，只给结论
        for v in bad:
            if 0 < v["row"] <= len(rows):
                rows[v["row"] - 1] = [v["revised_prompt"]]
        steps.append({"tool": "update_node", "args": {"canvas_id": req.canvas_id, "node_id": table["id"], "rows": rows},
                      "description": "改好第 " + "、".join(map(str, fix_rows)) + " 行的文案"})
        steps.append({"tool": "run_batch", "args": {"canvas_id": req.canvas_id, "node_id": req.batch_node_id,
                                                     "row_numbers": fix_rows},
                      "description": "只重跑这 " + str(len(fix_rows)) + " 行"})
        return {"steps": steps, "units": len(fix_rows), "allowed": [req.batch_node_id],
                "unchanged": unchanged, "capped": capped}
    for v in bad:
        node = by_id.get(v["node_id"])
        if node is None or _agent_node_kind(node) not in ("image", "video"):
            continue
        holder = _agent_review_prompt_holder(canvas, node)
        # 「改完提示词之后会发什么」：用画布副本算，既不改真实节点，也能拿到上游提示词的影响
        sim_canvas = json.loads(json.dumps(canvas, ensure_ascii=False, default=str))
        sim_by_id = _agent_nodes_by_id(sim_canvas)
        sim_node = sim_by_id.get(node["id"])
        sim_holder = sim_by_id.get(holder["id"])
        if sim_node is None:
            continue
        if sim_holder is not None:
            _agent_node_set_prompt(sim_holder, v["revised_prompt"])
        prospective_prompt = _agent_node_effective_prompt(sim_canvas, sim_node)
        self_urls = _agent_self_output_urls(sim_canvas, sim_node)
        refs = [r for r in _agent_node_reference_items(sim_canvas, sim_node, exclude_self=True)
                if str(r.get("url") or "") not in self_urls]
        record = _agent_generation_request_record(
            _agent_node_kind(sim_node), prospective_prompt, refs,
            _agent_effective_run_settings(sim_canvas, sim_node))
        blocked = _agent_regen_guard(_agent_regen_state_node(canvas, node), record, review_rerun=True)
        if blocked == "review_rerun_limit":
            capped.append(node["id"])
            continue
        if blocked == "unchanged":
            unchanged.append(node["id"])
            continue
        steps.append({"tool": "update_node", "args": {"canvas_id": req.canvas_id, "node_id": holder["id"],
                                                       "prompt": v["revised_prompt"]},
                      "description": "按检查建议改提示词"})
        steps.append({"tool": "run_generation", "args": {"canvas_id": req.canvas_id, "node_id": node["id"],
                                                        "exclude_self_refs": True},
                      "description": "按新提示词重新生成，原图保留"})
        allowed.append(node["id"])
        units += 1
    return {"steps": steps, "units": units, "allowed": allowed,
            "unchanged": unchanged, "capped": capped}


def _agent_review_fix_steps(canvas, req, verdicts):
    """不合格的图 → 批准后要跑的步骤与生成次数（_agent_review_fix_plan 的简化返回）。"""
    plan = _agent_review_fix_plan(canvas, req, verdicts)
    return plan["steps"], plan["units"]


@app.post("/api/agent/review")
async def agent_review(req: AgentReviewRequest):
    canvas = load_canvas(req.canvas_id)
    if not _agent_is_smart_canvas(canvas):
        raise HTTPException(status_code=400, detail="只有智能画布支持生成后检查")
    by_id = _agent_nodes_by_id(canvas)
    items = []
    for item in req.items[:AGENT_REVIEW_MAX_IMAGES]:
        url = str(item.url or "").strip()
        if not url or is_video_reference_value(url):
            continue
        node = by_id.get(item.node_id) if item.node_id else None
        label = str(item.label or "").strip() or (_agent_node_ref(node) if node else "") or f"图{len(items) + 1}"
        prompt = str(item.prompt or "").strip() or (_agent_node_effective_prompt(canvas, node) if node else "")
        items.append({"url": url, "node_id": item.node_id, "label": label[:20], "prompt": prompt[:1200], "row": int(item.row or 0)})
    if not items:
        return {"mode": "skip", "text": "这次没有可检查的图片"}
    chat = _agent_review_pick_chat(req.provider, req.model)
    if chat is None:
        return {"mode": "none", "text": _agent_review_unavailable_text(req.provider, req.model)}
    parts = [{"type": "text", "text": _AGENT_REVIEW_PROMPT.format(instruction=str(req.instruction or "（用户没写要求，按提示词检查）")[:600])}]
    sent = []
    for it in items:
        data_url = _agent_image_payload_url(it["url"])
        if not data_url:
            continue
        parts.append({"type": "text", "text": f"【{it['label']}】提示词：{it['prompt'] or '（无）'}"})
        parts.append({"type": "image_url", "image_url": {"url": data_url}})
        sent.append(it)
    if not sent:
        return {"mode": "skip", "text": "图片读不出来，这次没法检查"}
    data = None
    for attempt in range(2):
        try:
            text = await _agent_run_chat(chat, [{"role": "user", "content": parts}])
        except AgentRunError as exc:
            print(f"[Agent] 生成后检查失败（{chat.get('model')}）: {exc.message}")
            failed_key = _agent_chat_vision_key(chat)
            _agent_vision_record_failure(failed_key, _agent_clean_error_text(exc.message))
            if attempt == 0:
                continue        # 先给当前模型再试一次，失败才换候选
            chat = _agent_pick_caption_model(failed_key)
            if chat is None:
                return {"mode": "error",
                        "text": "看图的模型这次没回应，结果没检查成（" + _agent_vision_deny_note(failed_key) + "）"}
            continue
        data = _agent_review_parse(text)
        if data is not None:
            break
    if data is None:
        return {"mode": "error", "text": "检查结果没解析出来，这次先跳过"}
    raw = {str(v.get("label") or "").strip(): v for v in data["items"] if isinstance(v, dict)}
    verdicts = []
    for idx, it in enumerate(sent):
        v = raw.get(it["label"]) or (data["items"][idx] if idx < len(data["items"]) and isinstance(data["items"][idx], dict) else {})
        issues = [str(x).strip()[:120] for x in (v.get("issues") or []) if str(x).strip()][:4]
        ok = bool(v.get("ok", not issues)) and not issues
        verdicts.append({"label": it["label"], "node_id": it["node_id"], "url": it["url"], "row": it["row"],
                         "ok": ok, "issues": issues,
                         "revised_prompt": "" if ok else str(v.get("revised_prompt") or "").strip()[:1500]})
    plan = _agent_review_fix_plan(canvas, req, verdicts)
    # 审查通过的结果：清零「自动重跑」计数（这个节点已经好了，下一次不合格重新从 0 数）
    passed = [str(v.get("node_id") or "").strip() for v in verdicts if v.get("ok")]
    if passed:
        _agent_regen_reset_review_reruns(canvas.get("id") or req.canvas_id, passed)
    status = ("review_rerun_limit" if plan["capped"]
              else ("unchanged" if plan["unchanged"] else ""))
    return {"mode": "ok", "model": chat.get("model") or "", "summary": str(data.get("summary") or "").strip()[:200],
            "items": verdicts, "steps": plan["steps"], "units": plan["units"],
            "batch_node_id": req.batch_node_id, "status": status,
            "regen": {"allowed": plan["allowed"], "unchanged": plan["unchanged"], "capped": plan["capped"]}}


# ---------------------------------------------------------------------------
# 流程模板（P2-2，第 40 轮）：模板 = 资产库「工作流」分类里的条目，
# 和画布「工作流 → 导出到资产库」存的是同一种东西（workflow.json / zip 带资源）。
# 助手能列出、把选中的节点存成模板、按模板一键搭出整套节点（换素材 / 换提示词 / 改参数 / 接着出图）。
# ---------------------------------------------------------------------------

def _agent_tpl_copy(value):
    return json.loads(json.dumps(value, ensure_ascii=False))


_AGENT_TEMPLATE_STRIP_KEYS = (
    "alias", "pendingTasks", "task_id", "lastTaskId", "lastTaskStatus", "lastTaskError", "generationBatchJournal",
    "tableBatchRunning", "batchRowStates", "batchRowOrder", "batchRunExpected", "pending", "promptHistory",
)


def _agent_template_items():
    """资产库里所有工作流条目（跨资产库）。"""
    lib = load_asset_library()
    out, seen = [], set()
    libraries = lib.get("libraries") or [{"id": "", "categories": lib.get("categories") or []}]
    for library in libraries:
        for cat in (library.get("categories") or []):
            if not isinstance(cat, dict) or str(cat.get("type") or "") != "workflow":
                continue
            for item in (cat.get("items") or []):
                if not isinstance(item, dict) or not item.get("url") or item.get("id") in seen:
                    continue
                seen.add(item.get("id"))
                out.append({**item, "_library_id": library.get("id") or "", "_category_id": cat.get("id") or ""})
    return out


def _agent_template_find(name):
    text = str(name or "").strip().strip("「」\"'")
    items = _agent_template_items()
    if not items:
        raise AgentToolError("资产库里还没有流程模板；先选中一组节点，说「存成模板」", code="template_not_found", status_code=404)
    for rule in (lambda it: it.get("id") == text, lambda it: str(it.get("name") or "") == text,
                 lambda it: text and text.lower() in str(it.get("name") or "").lower()):
        hits = [it for it in items if rule(it)]
        if len(hits) == 1:
            return hits[0]
        if len(hits) > 1:
            raise AgentToolError("有几个模板都叫这个名字：" + "、".join(str(h.get("name")) for h in hits[:6]) + "，说清楚用哪个",
                                 code="template_ambiguous")
    raise AgentToolError(f"没找到模板「{text}」；现有：" + "、".join(str(it.get("name")) for it in items[:12]),
                         code="template_not_found", status_code=404)


def _agent_template_path(item):
    return os.path.join(ASSET_LIBRARY_DIR, os.path.basename(str(item.get("url") or "")))


def _agent_template_read(item, extract=False):
    """读出模板的节点和连线；extract=True 时把 zip 里打包的素材放到 assets/input 并改写地址（与「导入工作流」同一套）。"""
    path = _agent_template_path(item)
    if not os.path.isfile(path):
        raise AgentToolError(f"模板「{item.get('name')}」的文件不见了", code="template_not_found", status_code=404)
    mapping = {}
    try:
        with open(path, "rb") as f:
            raw = f.read()
        if raw[:2] == b"PK":
            with zipfile.ZipFile(BytesIO(raw), "r") as zf:
                names = zf.namelist()
                wf_name = "workflow.json" if "workflow.json" in names else next((n for n in names if n.lower().endswith("workflow.json")), "")
                if not wf_name:
                    raise AgentToolError("模板压缩包里没有 workflow.json", code="template_invalid")
                workflow = json.loads(zf.read(wf_name).decode("utf-8-sig"))
                if extract:
                    import_dir = os.path.join(OUTPUT_INPUT_DIR, f"template_{uuid.uuid4().hex[:8]}")
                    for res in workflow.get("resources") or []:
                        archive = str(res.get("archive") or "").replace("\\", "/").lstrip("/")
                        if not archive or archive not in names:
                            continue
                        os.makedirs(import_dir, exist_ok=True)
                        base = sanitize_export_filename(res.get("name") or os.path.basename(archive), "resource.bin")
                        target = os.path.join(import_dir, f"{uuid.uuid4().hex[:8]}_{base}")
                        with zf.open(archive) as src, open(target, "wb") as dst:
                            shutil.copyfileobj(src, dst)
                        new_url = "/assets/" + os.path.relpath(target, ASSETS_DIR).replace("\\", "/")
                        for key in (str(res.get("url") or "").strip(), archive, f"./{archive}"):
                            if key:
                                mapping[key] = new_url
        else:
            workflow = json.loads(raw.decode("utf-8-sig"))
    except AgentToolError:
        raise
    except Exception as exc:
        raise AgentToolError(f"模板「{item.get('name')}」读不出来：{exc}", code="template_invalid")
    if isinstance(workflow, list):
        workflow = {"nodes": workflow, "connections": []}
    nodes = [n for n in (workflow.get("nodes") or []) if isinstance(n, dict) and n.get("id")]
    conns = [c for c in (workflow.get("connections") or []) if isinstance(c, dict)]
    if mapping:
        nodes = canvas_workflow_replace_strings(nodes, mapping)
        conns = canvas_workflow_replace_strings(conns, mapping)
    if not nodes:
        raise AgentToolError(f"模板「{item.get('name')}」里没有节点", code="template_invalid")
    return _agent_tpl_copy(nodes), _agent_tpl_copy(conns)


def _agent_template_roles(nodes, conns):
    """把模板节点分成：素材位（没有上游、也不是生成节点的图片/视频节点）、生成节点、第一层生成节点（上游里没有生成节点）。"""
    ids = {n["id"] for n in nodes}
    ups = {}
    for c in conns:
        if c.get("from") in ids and c.get("to") in ids and (c.get("kind") or "flow") == "input":
            ups.setdefault(c["to"], []).append(c["from"])
    gen, slots = [], []
    for n in nodes:
        if _agent_node_type(n) not in _AGENT_SMART_MEDIA_NODE_TYPES:
            continue
        rs = n.get("runSettings") if isinstance(n.get("runSettings"), dict) else {}
        is_gen = bool(ups.get(n["id"])) or bool(str(n.get("promptDraftText") or "").strip()) or bool(rs)
        (gen if is_gen else slots).append(n["id"])
    gen_set = set(gen)
    first = [g for g in gen if not any(u in gen_set for u in ups.get(g, []))]
    return {"gen": gen, "slots": slots, "first": first, "ups": ups}


def _agent_template_summary(nodes, conns):
    kinds = {}
    for n in nodes:
        k = AGENT_TEMPLATE_KIND_LABEL.get(_agent_node_kind(n), "其他")
        kinds[k] = kinds.get(k, 0) + 1
    return "、".join(f"{k}×{v}" if v > 1 else k for k, v in kinds.items())


AGENT_TEMPLATE_KIND_LABEL = {"prompt": "提示词", "text": "文本", "image": "图片", "video": "视频", "group": "组",
                             "table": "表格", "batch": "批量"}


# ── list_templates ────────────────────────────────────────────────────────

def _agent_tool_list_templates_validate(args):
    return {"query": str(args.get("query") or "").strip()}


def _agent_tool_list_templates_run(args):
    out = []
    for item in _agent_template_items():
        name = str(item.get("name") or "")
        if args["query"] and args["query"].lower() not in name.lower():
            continue
        entry = {"template": name, "id": item.get("id")}
        try:
            nodes, conns = _agent_template_read(item)
            entry["nodes"] = len(nodes)
            entry["contains"] = _agent_template_summary(nodes, conns)
        except AgentToolError as exc:
            entry["error"] = exc.message if hasattr(exc, "message") else str(exc)
        out.append(entry)
    return {"templates": out[:40], "total": len(out)}


def _agent_tool_list_templates_preview(args, canvas):
    return "列出资产库里的流程模板"


# ── save_template ─────────────────────────────────────────────────────────

def _agent_tool_save_template_validate(args):
    canvas_id = str(args.get("canvas_id") or "").strip()
    name = str(args.get("name") or "").strip().strip("「」\"'")[:60]
    if not canvas_id or not name:
        raise AgentToolError("canvas_id 与 name（模板名）不能为空", code="invalid_args")
    canvas = load_canvas(canvas_id)
    ids = _agent_parse_inputs(args.get("node_ids"))
    if not ids:
        raise AgentToolError("node_ids 至少一个（要存进模板的节点，通常是用户选中的节点）", code="invalid_args")
    by_id = _agent_nodes_by_id(canvas)
    missing = [i for i in ids if i not in by_id]
    if missing:
        raise AgentToolError(f"节点不存在：{'、'.join(missing)}", code="node_not_found", status_code=404)
    if any(str(it.get("name") or "") == name for it in _agent_template_items()) and not args.get("overwrite"):
        raise AgentToolError(f"已经有模板叫「{name}」了；换个名字，或说明要覆盖（overwrite=true）", code="template_exists")
    return {"canvas_id": canvas_id, "name": name, "node_ids": ids, "overwrite": bool(args.get("overwrite"))}


def _agent_template_clean_node(node, roles):
    n = {k: v for k, v in _agent_tpl_copy(node).items() if k not in _AGENT_TEMPLATE_STRIP_KEYS and not str(k).startswith("_")}
    if n.get("id") in roles["gen"]:
        n["images"] = []          # 生成节点不带上次的结果，模板是干净的
    return n


def _agent_tool_save_template_run(args):
    canvas = load_canvas(args["canvas_id"])
    by_id = _agent_nodes_by_id(canvas)
    picked = [by_id[i] for i in args["node_ids"]]
    ids = {n["id"] for n in picked}
    conns = [_agent_tpl_copy(c) for c in (canvas.get("connections") or [])
             if isinstance(c, dict) and c.get("from") in ids and c.get("to") in ids]
    roles = _agent_template_roles(picked, conns)
    nodes = [_agent_template_clean_node(n, roles) for n in picked]
    for n in nodes:
        if isinstance(n.get("inputNodeIds"), list):
            n["inputNodeIds"] = [i for i in n["inputNodeIds"] if i in ids]
    req = CanvasWorkflowExportRequest(nodes=nodes, connections=conns, include_resources=True,
                                      filename=f"{args['name']}.zip", name=args["name"])
    archive, meta = build_canvas_workflow_archive(req)
    lib = load_asset_library()
    _, cat = asset_library_workflow_category(lib)
    if args["overwrite"]:
        cat["items"] = [it for it in (cat.get("items") or []) if str(it.get("name") or "") != args["name"]]
    item = make_workflow_library_item_from_bytes(archive, f"{args['name']}.zip", args["name"])
    item["node_count"] = len(nodes)
    item["connection_count"] = len(conns)
    item["resource_count"] = len(meta.get("resources") or [])
    item["source"] = "agent"
    cat.setdefault("items", []).append(item)
    save_asset_library(lib)
    return {"template": args["name"], "template_id": item["id"], "nodes": len(nodes), "connections": len(conns),
            "resources": item["resource_count"], "contains": _agent_template_summary(picked, conns),
            "message": f"已存成模板「{args['name']}」（{len(nodes)} 个节点），在资产库「工作流」里也能看到"}


def _agent_tool_save_template_preview(args, canvas):
    return f"把 {len(args.get('node_ids') or [])} 个节点存成模板「{args.get('name')}」"


# ── apply_template ────────────────────────────────────────────────────────

def _agent_tool_apply_template_validate(args):
    canvas_id = str(args.get("canvas_id") or "").strip()
    if not canvas_id:
        raise AgentToolError("canvas_id 不能为空", code="invalid_args")
    canvas = load_canvas(canvas_id)
    if not _agent_is_smart_canvas(canvas):
        raise AgentToolError("流程模板只在智能画布里可用", code="invalid_args")
    item = _agent_template_find(args.get("template"))
    nodes, conns = _agent_template_read(item)
    roles = _agent_template_roles(nodes, conns)
    inputs = _agent_parse_inputs(args.get("inputs"))
    by_id = _agent_nodes_by_id(canvas)
    missing = [i for i in inputs if i not in by_id and not _agent_args_have_step_refs(i)]
    if missing:
        raise AgentToolError(f"inputs 里的节点不存在：{'、'.join(missing)}", code="node_not_found", status_code=404)
    if inputs and not roles["slots"]:
        raise AgentToolError(f"模板「{item.get('name')}」里没有空的素材位，没法换素材；不带 inputs 直接用", code="invalid_args")
    settings = args.get("settings") if isinstance(args.get("settings"), dict) else {}
    kinds = {_agent_node_kind(n) for n in nodes if n["id"] in roles["gen"]}
    norm_settings = {}
    if settings:
        norm_settings = _agent_validate_settings(settings, "video" if kinds == {"video"} else "image")
    run = args.get("run") is not False and bool(roles["first"])
    count = int(norm_settings.get("count") or 1)
    return {"canvas_id": canvas_id, "template_id": item["id"], "template": str(item.get("name") or ""),
            "inputs": inputs, "prompt": str(args.get("prompt") or "").strip(), "settings": norm_settings,
            "run": run, "node_count": len(nodes), "first_count": len(roles["first"]),
            "later_count": len(roles["gen"]) - len(roles["first"]),
            "units": (len(roles["first"]) * count + len(roles["gen"]) - len(roles["first"])) if run else 0}


async def _agent_tool_apply_template_run(args):
    item = next((it for it in _agent_template_items() if it.get("id") == args["template_id"]), None)
    if item is None:
        raise AgentToolError("模板不见了", code="template_not_found", status_code=404)
    src_nodes, src_conns = _agent_template_read(item, extract=True)
    roles = _agent_template_roles(src_nodes, src_conns)

    def _mutate(canvas):
        by_id = _agent_nodes_by_id(canvas)
        boxes = [_agent_node_box(n) for n in src_nodes]
        min_x, min_y = min(b[0] for b in boxes), min(b[1] for b in boxes)
        width = max(b[0] + b[2] for b in boxes) - min_x
        height = max(b[1] + b[3] for b in boxes) - min_y
        anchors = [i for i in args["inputs"] if i in by_id]
        x0, y0 = _agent_default_position(canvas, anchors, width, height)
        id_map = {n["id"]: f"agent_tpl_{uuid.uuid4().hex[:12]}" for n in src_nodes}
        media = []
        for nid in anchors:
            media.extend(_agent_tpl_copy(i) for i in _agent_media_items(by_id[nid]))
        new_nodes = []
        for n in src_nodes:
            node = _agent_template_clean_node(n, roles)
            old = node["id"]
            node["id"] = id_map[old]
            x, y, _, _ = _agent_node_box(n)
            node["x"], node["y"] = round(x - min_x + x0), round(y - min_y + y0)
            node["created_at"] = now_ms()
            if isinstance(node.get("inputNodeIds"), list):
                node["inputNodeIds"] = [id_map[i] for i in node["inputNodeIds"] if i in id_map]
            if old in roles["slots"] and media:
                node["images"] = [media.pop(0)] if len(roles["slots"]) > 1 else media[:]
            new_nodes.append(node)
        new_ids = {id_map[k]: v for k, v in zip([n["id"] for n in src_nodes], new_nodes)}
        if args["prompt"]:
            prompts = [new_ids[id_map[n["id"]]] for n in src_nodes if _agent_node_kind(n) == "prompt"]
            targets = prompts[:1] or [new_ids[id_map[g]] for g in roles["first"]]
            for t in targets:
                _agent_node_set_prompt(t, args["prompt"])
        if args["settings"]:
            for g in roles["gen"]:
                node = new_ids[id_map[g]]
                _agent_apply_settings(node, _agent_node_kind(node), args["settings"])
        canvas.setdefault("nodes", []).extend(new_nodes)
        conns = canvas.get("connections") if isinstance(canvas.get("connections"), list) else []
        for c in src_conns:
            if c.get("from") in id_map and c.get("to") in id_map:
                conns.append({**_agent_tpl_copy(c), "from": id_map[c["from"]], "to": id_map[c["to"]]})
        canvas["connections"] = conns
        return {"ids": [n["id"] for n in new_nodes], "first": [id_map[g] for g in roles["first"]],
                "later": [id_map[g] for g in roles["gen"] if g not in roles["first"]],
                "slots": [id_map[s] for s in roles["slots"]]}

    canvas, made = _agent_mutate_canvas(args["canvas_id"], _mutate)
    _agent_snapshot(canvas, note=f"agent:apply_template {args['template']}")
    by_id = _agent_nodes_by_id(canvas)
    out = {"template": args["template"], "node_ids": made["ids"], "node_id": (made["first"] or made["ids"])[0],
           "aliases": [by_id[i].get("alias") for i in made["ids"] if i in by_id and by_id[i].get("alias")],
           "node_count": len(made["ids"]), "tasks": [], "task_ids": []}
    if args["run"]:
        for nid in made["first"]:
            try:
                res = await _agent_start_node_generation(args["canvas_id"], nid)
            except AgentToolError as exc:
                out.setdefault("run_errors", []).append(f"{_agent_node_ref(by_id.get(nid))}：{exc}")
                continue
            if isinstance(res, dict) and res.get("task_id"):
                out["tasks"].append({"node_id": res.get("node_id") or nid, "task_id": res["task_id"],
                                     "kind": res.get("kind") or _agent_node_kind(by_id.get(nid) or {})})
                out["task_ids"].append(res["task_id"])
        if made["later"]:
            _agent_chain_register(args["canvas_id"], made["later"], label=args["template"])
        out["generation_units"] = len(out["task_ids"]) + len(made["later"])
    later = args["later_count"]
    out["message"] = (f"已按模板「{args['template']}」搭出 {len(made['ids'])} 个节点"
                      + (f"，{len(out['task_ids'])} 个节点开始出图" if args["run"] else "")
                      + (f"；后面 {later} 个节点等前面出结果后自动接着跑" if later and args["run"] else ""))
    return out


def _agent_tool_apply_template_preview(args, canvas):
    return f"按模板「{args.get('template')}」搭出整套节点" + ("并运行" if args.get("run") is not False else "")


class CanvasTemplateApplyRequest(BaseModel):
    canvas_id: str
    inputs: List[str] = []
    prompt: str = ""


def _canvas_template_cover_urls(nodes):
    covers = []
    for node in nodes:
        for media in (node.get("images") or []):
            url = str(media.get("url") or "").strip() if isinstance(media, dict) else str(media or "").strip()
            if url and url not in covers:
                covers.append(url)
            if len(covers) >= 3:
                return covers
    return covers


@app.get("/api/canvas-templates")
async def list_canvas_templates(query: str = ""):
    templates = []
    text = str(query or "").strip().lower()
    for item in _agent_template_items():
        name = str(item.get("name") or "")
        if text and text not in name.lower():
            continue
        entry = {"id": item.get("id"), "name": name}
        try:
            nodes, conns = _agent_template_read(item)
            roles = _agent_template_roles(nodes, conns)
            entry.update({
                "node_count": len(nodes),
                "connection_count": len(conns),
                "contains": _agent_template_summary(nodes, conns),
                "input_count": len(roles["slots"]),
                "generation_count": len(roles["gen"]),
                "covers": _canvas_template_cover_urls(nodes),
            })
        except AgentToolError as exc:
            entry["error"] = str(exc)
        templates.append(entry)
    return {"templates": templates, "total": len(templates)}


@app.post("/api/canvas-templates/{template_id}/apply")
async def apply_canvas_template(template_id: str, payload: CanvasTemplateApplyRequest):
    args = _agent_tool_apply_template_validate({
        "canvas_id": payload.canvas_id,
        "template": template_id,
        "inputs": payload.inputs,
        "prompt": payload.prompt,
        "run": False,
    })
    result = await _agent_tool_apply_template_run(args)
    return {**result, "canvas_id": payload.canvas_id, "run": False}


# ---------------------------------------------------------------------------
# 项目记忆（P2-4，第 42 轮）：用户明确要求记住的长期偏好（比例、模型、品牌色、固定风格…）。
# 两层：这张画布（data/agent_memory/{canvas_id}.json）、所有画布（data/agent_memory/_global.json）。
# 每轮对话都把记忆放进给模型的上下文，默认照做；用户这次另有说法以这次为准。
# 只在用户明确说「记住 / 以后都 / 默认」时才记，平常的话不偷偷记；可在面板里改、删、手动加。
# ---------------------------------------------------------------------------

AGENT_MEMORY_DIR = os.path.join(DATA_DIR, "agent_memory")
AGENT_MEMORY_LIMIT = 60
AGENT_MEMORY_TEXT_MAX = 300
_AGENT_MEMORY_LOCK = Lock()


def _agent_memory_path(canvas_id, scope):
    if scope == "global":
        return os.path.join(AGENT_MEMORY_DIR, "_global.json")
    cleaned = re.sub(r"[^a-zA-Z0-9_-]", "", str(canvas_id or ""))
    if not cleaned:
        raise HTTPException(status_code=400, detail="无效的画布 ID")
    return os.path.join(AGENT_MEMORY_DIR, f"{cleaned}.json")


def _agent_memory_scope(value):
    return "global" if str(value or "").strip().lower() in ("global", "all", "所有画布", "全局") else "canvas"


def agent_memory_load(canvas_id, scope):
    try:
        path = _agent_memory_path(canvas_id, scope)
    except HTTPException:
        return []
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        items = data.get("items") if isinstance(data, dict) else []
        return [i for i in (items or []) if isinstance(i, dict) and str(i.get("text") or "").strip()]
    except FileNotFoundError:
        return []
    except Exception as exc:
        print(f"[Agent] 读取记忆失败 {scope}:{canvas_id}: {exc}")
        return []


def _agent_memory_save(canvas_id, scope, items):
    os.makedirs(AGENT_MEMORY_DIR, exist_ok=True)
    write_json_atomic(_agent_memory_path(canvas_id, scope), {"items": items[-AGENT_MEMORY_LIMIT:], "updated_at": time.time()},
                      ensure_ascii=False, indent=2)


# 「记住：主色是墨绿色」和「主色是墨绿色」是同一条：去重时把开头的指令词去掉再比
_AGENT_MEMORY_PREFIX_RE = re.compile(r"^\s*(?:请|帮我)?\s*(?:记住|记下|记得|以后都|今后都)\s*[：:，,、]?\s*")


def _agent_memory_text_key(text):
    body = _AGENT_MEMORY_PREFIX_RE.sub("", re.sub(r"\s+", " ", str(text or "")).strip())
    return body.strip("。.!！?？;；")


def agent_memory_add(canvas_id, scope, texts, source="user", extra=None):
    """加几条；同样的话不重复记。返回新加的条目。

    extra：给新条目附加字段（记忆候选确认时用 type / hits / last_used）；id / text / created_at 不许被覆盖。"""
    added = []
    with _AGENT_MEMORY_LOCK:
        items = agent_memory_load(canvas_id, scope)
        known = {_agent_memory_text_key(i.get("text")) for i in items}
        for text in texts:
            text = re.sub(r"\s+", " ", str(text or "")).strip()[:AGENT_MEMORY_TEXT_MAX]
            key = _agent_memory_text_key(text)
            if not text or not key or key in known:
                continue
            now = time.time()
            item = {"id": f"mem_{uuid.uuid4().hex[:10]}", "text": text, "source": source, "created_at": now, "updated_at": now}
            for key, value in (extra or {}).items():
                if key in ("id", "text", "created_at"):
                    continue
                item[key] = value
            items.append(item)
            known.add(key)
            added.append(item)
        if added:
            _agent_memory_save(canvas_id, scope, items)
            _agent_v2_memory_index_memory(canvas_id, scope, added)
    if added and canvas_id:
        # K1 / L1：记住的东西同时进项目档案（新对话开场 + 档案正文都能看到），不必等下一次摘要；
        # 全局偏好也进这张画布的档案（面板里「记住：…」默认写全局）
        _agent_profile_refresh_memories(canvas_id)
    return added


def agent_memory_remove(canvas_id, scope, item_id="", text=""):
    """按 id 删；没给 id 就删内容里包含 text 的那几条。返回删掉的条目。"""
    with _AGENT_MEMORY_LOCK:
        items = agent_memory_load(canvas_id, scope)
        needle = str(text or "").strip()
        gone = [i for i in items if (item_id and i.get("id") == item_id) or (not item_id and needle and needle in str(i.get("text")))]
        if gone:
            _agent_memory_save(canvas_id, scope, [i for i in items if i not in gone])
            _agent_v2_memory_index_forget_items(canvas_id, scope, gone)
    if gone and canvas_id:
        _agent_profile_refresh_memories(canvas_id)
    return gone


def agent_memory_update(canvas_id, scope, item_id, text):
    text = re.sub(r"\s+", " ", str(text or "")).strip()[:AGENT_MEMORY_TEXT_MAX]
    with _AGENT_MEMORY_LOCK:
        items = agent_memory_load(canvas_id, scope)
        hit = next((i for i in items if i.get("id") == item_id), None)
        if hit is None:
            return None
        old = dict(hit)      # 改前的那份：索引里的旧条目要删掉
        if not text:
            items = [i for i in items if i is not hit]
        else:
            hit["text"], hit["updated_at"] = text, time.time()
        _agent_memory_save(canvas_id, scope, items)
        _agent_v2_memory_index_forget_items(canvas_id, scope, [old])
        if text:
            _agent_v2_memory_index_memory(canvas_id, scope, [hit])
    if canvas_id:
        _agent_profile_refresh_memories(canvas_id)
    return hit


def _agent_memory_prompt(canvas_id):
    own, common = agent_memory_load(canvas_id, "canvas"), agent_memory_load(canvas_id, "global")
    if not own and not common:
        return ""
    lines = ["项目记忆（用户明确要求记住的长期偏好：做方案时默认照做；用户这次另有说法以这次为准；回复里简单说按哪条来的）："]
    if own:
        lines.append("这张画布：")
        lines += [f"- {i['text']}" for i in own[-20:]]
    if common:
        lines.append("所有画布：")
        lines += [f"- {i['text']}" for i in common[-20:]]
    return "\n" + "\n".join(lines)


class AgentMemoryItemRequest(BaseModel):
    canvas_id: str = ""
    scope: str = "canvas"
    text: str = ""


# ── 记忆候选（阶段二·3）：摘要顺带提炼的偏好，用户勾选后才写长期记忆 ──────────

class AgentMemoryCandidateIdsRequest(BaseModel):
    canvas_id: str = ""
    thread_id: str = ""
    ids: List[str] = []


def _agent_memory_v2_store():
    """记忆候选 / recall 这类阶段二·3 功能：开关关闭时如实 400，不静默降级。"""
    if not _agent_v2_memory_enabled():
        raise HTTPException(status_code=400, detail="记忆候选需要打开 NOVAI_AGENT_V2_MEMORY=1")
    return _agent_memory_store


def _agent_memory_candidate_request(payload_or_canvas, thread_id="", default=""):
    """路由参数收敛：canvas_id 必填；ids 去重、限 50 条（路由层只管形状，不碰线程）。"""
    canvas_id = getattr(payload_or_canvas, "canvas_id", payload_or_canvas)
    canvas_id = str(canvas_id or "").strip()
    if not canvas_id:
        raise HTTPException(status_code=400, detail="canvas_id 不能为空")
    ids = getattr(payload_or_canvas, "ids", None)
    resolved_ids = []
    if ids is not None:
        resolved_ids = list(dict.fromkeys(str(x).strip() for x in ids if str(x or "").strip()))[:50]
    return canvas_id, resolved_ids or default, str(getattr(payload_or_canvas, "thread_id", thread_id) or "").strip()


@app.get("/api/agent/memory/candidates")
async def agent_memory_candidates(request: Request, canvas_id: str = "", thread_id: str = ""):
    """待确认的记忆候选（摘要那次模型调用顺带产出的；勾选后才写长期记忆）。"""
    store = _agent_memory_v2_store()
    canvas_id = str(canvas_id or "").strip()
    if not canvas_id:
        raise HTTPException(status_code=400, detail="canvas_id 不能为空")
    require_canvas_access(load_canvas(canvas_id), request, "view")
    with _AGENT_THREAD_LOCK:
        doc = _agent_thread_doc_load(canvas_id)
        resolved = str(thread_id or "").strip() or str((_agent_thread_active(doc) or {}).get("id") or "")
        thread = _agent_thread_find(doc, resolved) if resolved else None
    rows = store.thread_candidates(thread) if thread else []
    # 候选卡片关掉：卡片不出现（摘要照跑）；已有候选留在线程文档里，重新打开开关会再出现
    if not _agent_v2_memory_settings(canvas_id).get("candidate_cards", True):
        rows = []
    pending = [{"id": row["id"], "text": row["text"], "scope": row["scope"], "reason": row["reason"]}
               for row in rows if row.get("status") == "pending"]
    return {"canvas_id": canvas_id, "thread_id": resolved, "items": pending,
            "confirmed_ids": [row["id"] for row in rows if row.get("status") == "confirmed"],
            "pending": len(pending)}


@app.post("/api/agent/memory/confirm")
async def agent_memory_confirm(payload: AgentMemoryCandidateIdsRequest, request: Request):
    """勾选的候选写进长期记忆（幂等：同文本已经记过就不再写，但状态照样标已确认）。"""
    store = _agent_memory_v2_store()
    canvas_id, ids, thread_id = _agent_memory_candidate_request(payload)
    if not ids:
        raise HTTPException(status_code=400, detail="ids 不能为空")
    require_canvas_access(load_canvas(canvas_id), request, "edit")
    confirmed, skipped, written = [], [], []
    with _AGENT_THREAD_LOCK:
        doc = _agent_thread_doc_load(canvas_id)
        resolved = thread_id or str((_agent_thread_active(doc) or {}).get("id") or "")
        thread = _agent_thread_find(doc, resolved) if resolved else None
        if thread is None:
            raise HTTPException(status_code=404, detail="线程不存在")
        rows = store.thread_candidates(thread)
        by_id = {row["id"]: row for row in rows}
        changed = False
        for candidate_id in ids:
            row = by_id.get(candidate_id)
            if row is None or row.get("status") == "dismissed":
                skipped.append(candidate_id)
                continue
            if row.get("status") == "confirmed":
                confirmed.append(candidate_id)
                skipped.append(candidate_id)      # 之前已确认过：不重复写长期记忆
                continue
            written.extend(agent_memory_add(canvas_id, row["scope"], [row["text"]],
                                            source="memory_candidate",
                                            extra={"type": "preference", "hits": 0,
                                                   "last_used": time.time()}))
            row["status"] = "confirmed"
            row["confirmed_at"] = time.time()
            confirmed.append(candidate_id)
            changed = True
        if changed:
            thread["memory_candidates"] = rows
            _agent_thread_doc_save(canvas_id, doc)
    return {"canvas_id": canvas_id, "thread_id": resolved, "confirmed": confirmed,
            "skipped": skipped, "memory": written}


@app.post("/api/agent/memory/candidates/dismiss")
async def agent_memory_candidates_dismiss(payload: AgentMemoryCandidateIdsRequest, request: Request):
    """忽略选中的候选：只改状态，不写长期记忆；已确认的不允许再忽略。"""
    store = _agent_memory_v2_store()
    canvas_id, ids, thread_id = _agent_memory_candidate_request(payload)
    if not ids:
        raise HTTPException(status_code=400, detail="ids 不能为空")
    require_canvas_access(load_canvas(canvas_id), request, "edit")
    dismissed, skipped = [], []
    with _AGENT_THREAD_LOCK:
        doc = _agent_thread_doc_load(canvas_id)
        resolved = thread_id or str((_agent_thread_active(doc) or {}).get("id") or "")
        thread = _agent_thread_find(doc, resolved) if resolved else None
        if thread is None:
            raise HTTPException(status_code=404, detail="线程不存在")
        rows = store.thread_candidates(thread)
        by_id = {row["id"]: row for row in rows}
        changed = False
        for candidate_id in ids:
            row = by_id.get(candidate_id)
            if row is None or row.get("status") == "confirmed":
                skipped.append(candidate_id)
                continue
            if row.get("status") == "dismissed":
                dismissed.append(candidate_id)
                continue
            row["status"] = "dismissed"
            row["dismissed_at"] = time.time()
            dismissed.append(candidate_id)
            changed = True
        if changed:
            thread["memory_candidates"] = rows
            _agent_thread_doc_save(canvas_id, doc)
    return {"canvas_id": canvas_id, "thread_id": resolved, "dismissed": dismissed,
            "skipped": skipped}


class AgentMemorySettingsRequest(BaseModel):
    canvas_id: str = ""
    auto_summary: Optional[bool] = None
    candidate_cards: Optional[bool] = None
    cross_canvas_recall: Optional[bool] = None
    # 阶段四：画布级「主动消息」总开关（只在事件触发开关打开时暴露/生效）
    proactive_messages: Optional[bool] = None


@app.get("/api/agent/memory/settings")
async def agent_memory_settings_get(request: Request, canvas_id: str = ""):
    """这张画布的三把记忆开关（自动摘要 / 记忆候选卡片 / 跨画布检索），缺省全开。"""
    store = _agent_memory_v2_store()
    canvas_id = str(canvas_id or "").strip()
    if not canvas_id:
        raise HTTPException(status_code=400, detail="canvas_id 不能为空")
    require_canvas_access(load_canvas(canvas_id), request, "view")
    settings = _agent_v2_memory_settings(canvas_id)
    defaults = dict(store.DEFAULT_SETTINGS)
    if _agent_v2_triggers_enabled():
        settings["proactive_messages"] = _agent_v2_trigger_settings(canvas_id)["proactive_messages"]
        defaults["proactive_messages"] = True
    return {"canvas_id": canvas_id, "settings": settings, "defaults": defaults}


@app.put("/api/agent/memory/settings")
async def agent_memory_settings_put(payload: AgentMemorySettingsRequest, request: Request,
                                    canvas_id: str = ""):
    """改这张画布的记忆开关（只改请求里带的字段，其余保持不变）。"""
    store = _agent_memory_v2_store()
    key = str(canvas_id or payload.canvas_id or "").strip()
    if not key:
        raise HTTPException(status_code=400, detail="canvas_id 不能为空")
    require_canvas_access(load_canvas(key), request, "edit")
    current = store.load_settings(AGENT_MEMORY_DIR, key)
    for field in store.SETTINGS_KEYS:
        value = getattr(payload, field, None)
        if value is not None:
            current[field] = bool(value)
    saved = store.save_settings(AGENT_MEMORY_DIR, key, current)
    defaults = dict(store.DEFAULT_SETTINGS)
    if _agent_v2_triggers_enabled():
        if payload.proactive_messages is not None:
            _agent_set_proactive_messages(key, bool(payload.proactive_messages))
        saved["proactive_messages"] = _agent_v2_trigger_settings(key)["proactive_messages"]
        defaults["proactive_messages"] = True
    return {"canvas_id": key, "settings": saved, "defaults": defaults}


@app.get("/api/agent/memory/{canvas_id}")
async def agent_memory_get(canvas_id: str):
    return {"canvas": agent_memory_load(canvas_id, "canvas"), "global": agent_memory_load(canvas_id, "global")}


@app.post("/api/agent/memory")
async def agent_memory_post(req: AgentMemoryItemRequest):
    scope = _agent_memory_scope(req.scope)
    if not req.text.strip():
        raise HTTPException(status_code=400, detail="内容不能为空")
