# ---------------------------------------------------------------------------
# analyze_video：读参考视频（关键帧网格 + 带时间戳口播），视频复刻类技能的第一步。
# 只读、不改画布；挂在字面量之后（同 review_table），不进通用画布 CLI 命令表。
# 实现在 server/agent_core/video_reader.py；这里只做「节点 / 地址 → 本地文件」与转写通道接线。
# ---------------------------------------------------------------------------

AGENT_VIDEO_READER_SUBDIR = "agent_video_reader"
AGENT_VIDEO_READER_MAX_BYTES = 500 * 1024 * 1024
_AGENT_VIDEO_EXTS = (".mp4", ".mov", ".m4v", ".webm", ".mkv", ".avi")


def _agent_tool_analyze_video_validate(args):
    args = dict(args or {})
    node_id = str(args.get("node_id") or "").strip()
    url = str(args.get("url") or "").strip()
    if not node_id and not url:
        raise AgentToolError("node_id 和 url 至少给一个（要读哪个视频）", code="invalid_args")
    try:
        frames = int(args.get("frames") or 12)
    except (TypeError, ValueError):
        frames = 12
    try:
        start = max(0.0, float(args.get("start") or 0))
        end = max(0.0, float(args.get("end") or 0))
    except (TypeError, ValueError):
        raise AgentToolError("start / end 必须是秒数", code="invalid_args")
    if end and end <= start:
        raise AgentToolError("end 必须大于 start", code="invalid_args")
    canvas_id = str(args.get("canvas_id") or "").strip() or str(_AGENT_RUN_CANVAS_ID.get() or "").strip()
    return {"canvas_id": canvas_id, "node_id": node_id, "url": url,
            "frames": max(4, min(24, frames)), "start": start, "end": end,
            "transcript": args.get("transcript", True) is not False,
            "clip": bool(args.get("clip")), "audio": bool(args.get("audio"))}


def _agent_tool_analyze_video_preview(args, canvas=None):
    target = args.get("node_id") or args.get("url") or "视频"
    span = ""
    if args.get("start") or args.get("end"):
        span = "（%s–%s 秒）" % (args.get("start") or 0, args.get("end") or "结尾")
    return "读取参考视频 %s%s：抽 %s 帧关键帧网格%s，只读不改画布。" % (
        target, span, args.get("frames") or 12, "，并转写口播（带时间戳）" if args.get("transcript", True) else "")


def _agent_video_node_url(canvas, node_id):
    from server.agent_core.read_tools import CanvasAccess, resolve_node

    access = CanvasAccess()
    node = resolve_node(canvas, node_id, access)
    if node is None:
        raise AgentToolError("节点 %s 不存在" % node_id, code="node_not_found", status_code=404)
    kind = access.kind(node)
    if kind != "video":
        raise AgentToolError("「%s」是 %s 节点，不是视频节点" % (access.title(node) or node_id, kind or "未知"),
                             code="invalid_args")
    url = access.url(node)
    if not url:
        raise AgentToolError("「%s」这个视频节点还没有视频（未上传 / 未生成）" % (access.title(node) or node_id),
                             code="invalid_args")
    return url, access.title(node) or str(node.get("id"))


async def _agent_video_download(url, target):
    """外链视频下载到本地（流式 + 体积上限，不跟随重定向到内网由 net_proxy / httpx 默认行为兜）。"""
    from server import net_proxy

    total = 0
    async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=120.0,
                                 follow_redirects=True,
                                 **net_proxy.httpx_proxy(net_proxy.resolve_web_proxy())) as client:
        async with client.stream("GET", url, headers={"User-Agent": "Mozilla/5.0 NOVAI"}) as response:
            if response.status_code >= 400:
                raise AgentToolError("下载视频失败：HTTP %s" % response.status_code, code="video_download_failed")
            tmp = target + ".part"
            with open(tmp, "wb") as fh:
                async for chunk in response.aiter_bytes(1024 * 256):
                    total += len(chunk)
                    if total > AGENT_VIDEO_READER_MAX_BYTES:
                        fh.close()
                        os.remove(tmp)
                        raise AgentToolError("视频超过 500MB，太大了，先剪短再读", code="video_too_large")
                    fh.write(chunk)
            os.replace(tmp, target)
    return target


async def _agent_video_transcribe(audio_path, prompt):
    """复用语音输入那条转写通道（设置 → 通用 → 语音转写；没配借画布助手对话模型；本地命令优先）。"""
    from server.integrations import asr as _asr
    from server.integrations import video_sources as _video_sources

    command = (os.environ.get("NOVAI_ASR_COMMAND") or "").strip()
    if command:
        return await asyncio.to_thread(_asr._run_local_command, command, audio_path)
    settings = _asr.resolve_asr_settings()
    if not (settings.get("provider") and settings.get("model")):
        return {"ok": False, "text": "", "error": "未配置语音转写：请在「设置 → 通用 → 语音转写」选择平台和模型"
                                                 "（需要支持音频输入的模型，例如 Gemini），配好后再读一次即可拿到口播"}
    ok, message = _asr._resolve_provider(settings["provider"], settings["model"])
    if not ok:
        return {"ok": False, "text": "", "error": message}
    return await _video_sources._provider_transcript(audio_path, settings["provider"], settings["model"],
                                                     prompt=prompt)


async def _agent_tool_analyze_video_run(args):
    from server.agent_core import video_reader

    url = args.get("url") or ""
    label = "参考视频"
    canvas = None
    if args.get("canvas_id"):
        try:
            canvas = load_canvas(args["canvas_id"])
        except HTTPException:
            canvas = None
    if args.get("node_id"):
        if canvas is None:
            raise AgentToolError("读不到当前画布，没法按 node_id 找视频", code="canvas_not_found", status_code=404)
        url, label = _agent_video_node_url(canvas, args["node_id"])
    url = str(url or "").strip()
    key = hashlib.sha1(url.encode("utf-8", "ignore")).hexdigest()[:16]
    out_dir = os.path.join(OUTPUT_DIR, AGENT_VIDEO_READER_SUBDIR, key)
    os.makedirs(out_dir, exist_ok=True)
    local_path = _agent_local_image_path(url)
    if not local_path:
        if url.startswith(("/assets/", "/output/", "/uploads/")):
            raise AgentToolError("本地视频文件不存在或路径不合法", code="video_not_found", status_code=404)
        if not url.startswith(("http://", "https://")):
            raise AgentToolError("视频地址只能是画布上的视频节点、本地素材路径或 http(s) 直链", code="invalid_args")
        # 外链只读画布里真实出现过的地址（防止被诱导去请求任意地址）
        if canvas is None or url not in json.dumps(canvas, ensure_ascii=False):
            raise AgentToolError("这个外链不在当前画布上：请先把视频上传 / 拖进画布，再用 node_id 读", code="invalid_args")
        ext = os.path.splitext(urllib.parse.urlsplit(url).path)[1].lower()
        local_path = os.path.join(out_dir, "source" + (ext if ext in _AGENT_VIDEO_EXTS else ".mp4"))
        if not os.path.isfile(local_path):
            await _agent_video_download(url, local_path)
    if not os.path.isfile(local_path):
        raise AgentToolError("视频文件不存在", code="video_not_found", status_code=404)
    try:
        result = await video_reader.read_video(
            local_path, out_dir, "/output/%s/%s" % (AGENT_VIDEO_READER_SUBDIR, key),
            ffmpeg=ffmpeg_binary() or "", ffprobe=ffprobe_binary() or "",
            transcribe=_agent_video_transcribe, frames=args.get("frames") or 12,
            start=args.get("start") or 0, end=args.get("end") or 0,
            want_transcript=bool(args.get("transcript", True)), want_clip=bool(args.get("clip")),
            want_audio=bool(args.get("audio")))
    except video_reader.VideoReadError as exc:
        raise AgentToolError(exc.message, code=exc.code)
    result["video"] = label
    result["source_url"] = url
    if result.get("grid_url"):
        result["view_images"] = [{"url": result["grid_url"], "label": "%s 关键帧网格" % label}]
    transcript = result.get("transcript") or {}
    notes = ["已抽 %d 帧（网格图会在下一轮给你看，每格左上角是 #序号 和时间）" % len(result.get("frames") or [])]
    if transcript.get("ok"):
        notes.append("口播已转写（[mm:ss] 是全片时间）")
    elif not transcript.get("skipped"):
        notes.append("口播没拿到：%s" % (transcript.get("error") or "未知原因"))
    if result.get("cuts"):
        notes.append("检测到 %d 个硬切点（cuts），分镜按真实切点划分" % len(result["cuts"]))
    if result.get("last_frame_url"):
        notes.append("first_frame_url / last_frame_url 是整条视频真正的首帧 / 尾帧：接下一个连续镜头时，用上一个镜头的 last_frame_url 当下一个镜头的首帧")
    if result.get("audio_url"):
        notes.append("已导出这段原声 audio_url（可作为时间线的 music；原片音乐有版权，确认用户有权使用才用）")
    if result.get("clip_url"):
        notes.append("已截出参考片段 clip_url，可直接当 generate_video 的 reference_video（复刻这段动作 / 运镜 / 特效）")
    notes.append("grid_url 只是给你看的多格拼图，不要当参考图；"
                 "frames[].url（单帧）可直接当 generate_image / generate_video 的 reference_urls（复刻构图、场景）；"
                 "想细看某一段就用 start/end 缩小区间再读一次")
    result["message"] = "；".join(notes)
    return result


AGENT_TOOLS["analyze_video"] = {
    "description": "读懂一个参考视频（只读、不改画布）：在指定区间均匀抽 4–24 帧，拼成带「#序号 时间」标注的关键帧网格图并在下一轮交给你看；"
                   "同时转写口播，按句带 [mm:ss] 时间戳（走设置里的语音转写，没配会明确说明）。"
                   "返回时长、分辨率/画幅、硬切点 cuts、每帧地址（可直接当参考图）、整条视频真正的首帧 / 尾帧 first_frame_url / last_frame_url（接镜头用）和口播；"
                   "clip=true 时把 start–end 这段（2–15 秒）截成 clip_url，可直接当 generate_video 的 reference_video。"
                   "视频复刻 / 拆解爆款 / 分析节奏和分镜时先用它读全片，再用 start/end 缩小到某一段细看；"
                   "不要只看封面帧就下结论。node_id 填画布上的视频节点（用户上传或生成的）。",
    "schema": {"type": "object", "properties": {
        "canvas_id": {"type": "string", "description": "不填就用当前画布"},
        "node_id": {"type": "string", "description": "视频节点 id"},
        "url": {"type": "string", "description": "没有节点时直接给视频地址（本地素材路径，或画布上真实出现过的直链）"},
        "frames": {"type": "integer", "default": 12, "description": "抽几帧（4–24，默认 12）"},
        "start": {"type": "number", "description": "区间开始秒数（默认 0）"},
        "end": {"type": "number", "description": "区间结束秒数（默认到结尾）"},
        "transcript": {"type": "boolean", "default": True, "description": "是否转写口播（默认 true；同一区间只转写一次，有缓存）"},
        "clip": {"type": "boolean", "default": False, "description": "把 start–end 截成参考片段（2–15 秒）返回 clip_url，给 generate_video.reference_video 用"},
        "audio": {"type": "boolean", "default": False, "description": "把 start–end 的原声导出成 audio_url（时间线 music 用；原片音乐有版权，用户确认有权使用才用）"}}},
    "validate": _agent_tool_analyze_video_validate,
    "run": _agent_tool_analyze_video_run,
    "preview": _agent_tool_analyze_video_preview,
    "mutates_canvas": False,
}


# ---------------------------------------------------------------------------
# depth_capture：本机深度动作捕捉（Depth Anything V2，本地推理、不上传、不花额度）。
# 实现在 server/split_engine/depth_capture.py（和 /api/video/depth-capture 同一套）；
# 模块或模型不在时只返回「不可用 + 原因」，不报错，技能据此走备选来源。
# ---------------------------------------------------------------------------

AGENT_DEPTH_CAPTURE_MAX_SECONDS = 30.0


def _agent_depth_capture_module():
    try:
        from server.split_engine import depth_capture
    except Exception as exc:  # 模块没合入 / onnxruntime 没装
        return None, "本机深度动作捕捉没有安装（%s）" % (str(exc)[:120] or type(exc).__name__)
    return depth_capture, ""


def _agent_tool_depth_capture_validate(args):
    args = dict(args or {})
    node_id = str(args.get("node_id") or "").strip()
    url = str(args.get("url") or "").strip()
    check_only = bool(args.get("check_only"))
    if not check_only and not node_id and not url:
        raise AgentToolError("node_id 和 url 至少给一个（要转哪个视频）；只查能不能用就传 check_only=true", code="invalid_args")
    canvas_id = str(args.get("canvas_id") or "").strip() or str(_AGENT_RUN_CANVAS_ID.get() or "").strip()
    return {"canvas_id": canvas_id, "node_id": node_id, "url": url, "check_only": check_only,
            "keep_audio": bool(args.get("keep_audio"))}


def _agent_tool_depth_capture_preview(args, canvas=None):
    if args.get("check_only"):
        return "检查本机深度动作捕捉是否可用。"
    return "把 %s 在本机逐帧转成深度通道视频（最长 30 秒，不花额度）。" % (args.get("node_id") or args.get("url") or "视频")


async def _agent_tool_depth_capture_run(args):
    module, reason = _agent_depth_capture_module()
    ffmpeg = ffmpeg_binary() or ""
    if module is not None:
        ready, reason = module.available(ffmpeg)
    else:
        ready = False
    if args.get("check_only") or not ready:
        return {"ready": bool(ready), "reason": reason or "",
                "message": "本机深度动作捕捉可用" if ready else
                           "本机深度动作捕捉不可用：%s。按技能里的备选来源继续（画布上已有的深度视频 / 请用户上传）" % reason}
    url, label = str(args.get("url") or "").strip(), "视频"
    if args.get("node_id"):
        try:
            canvas = load_canvas(args["canvas_id"]) if args.get("canvas_id") else None
        except HTTPException:
            canvas = None
        if canvas is None:
            raise AgentToolError("读不到当前画布，没法按 node_id 找视频", code="canvas_not_found", status_code=404)
        url, label = _agent_video_node_url(canvas, args["node_id"])
    src = output_file_from_url(url)
    if not src or not os.path.isfile(src):
        raise AgentToolError("深度捕捉只支持画布里的本地视频（上传或生成到本机的 /output、/assets 文件）",
                             code="invalid_args")
    filename = "depth_capture_%s.mp4" % uuid.uuid4().hex[:12]
    output_path = output_path_for(filename, "output")
    result, error = await asyncio.to_thread(module.capture_video, ffmpeg, src, output_path,
                                            max_seconds=AGENT_DEPTH_CAPTURE_MAX_SECONDS,
                                            keep_audio=bool(args.get("keep_audio")))
    if error or not result:
        raise AgentToolError(error or "深度视频生成失败", code="depth_capture_failed")
    depth_url = output_url_for(filename, "output")
    return {"ready": True, "video": label, "source_url": url, "depth_url": depth_url,
            "width": result.get("width", 0), "height": result.get("height", 0),
            "frames": result.get("frames", 0), "duration": result.get("duration", 0),
            "message": "已生成深度通道 depth_url（灰度，越近越亮，和原片等长）。先用 analyze_video(url=depth_url) 抽帧审查，"
                       "再按段 analyze_video(url=depth_url, start, end, clip=true) 截出片段当 reference_video"}


AGENT_TOOLS["depth_capture"] = {
    "description": "本机深度动作捕捉：把画布上的本地视频（最长 30 秒）逐帧转成灰度深度通道视频，去掉颜色、纹理、人物长相，只留动作和空间层次；"
                   "本地推理、不花额度。check_only=true 只查本机能不能用（模型 / 依赖是否就绪）。"
                   "注意：深度里仍保留原物体轮廓（产品形状会被锁住）；平面内容（画、文字、屏幕）在深度里是一片平灰；"
                   "暗片整体偏暗；快切和粒子转场处深度是糊的。",
    "schema": {"type": "object", "properties": {
        "canvas_id": {"type": "string", "description": "不填就用当前画布"},
        "node_id": {"type": "string", "description": "视频节点 id"},
        "url": {"type": "string", "description": "没有节点时直接给本地视频地址（/output 或 /assets）"},
        "check_only": {"type": "boolean", "default": False, "description": "只检查本机深度捕捉是否可用，不转换"},
        "keep_audio": {"type": "boolean", "default": False, "description": "是否保留原声（当参考视频用时一般不要）"}}},
    "validate": _agent_tool_depth_capture_validate,
    "run": _agent_tool_depth_capture_run,
    "preview": _agent_tool_depth_capture_preview,
    "mutates_canvas": False,
}


# ---------------------------------------------------------------------------
# 技能级生成闸门：技能里写的「审查关卡」对模型只是建议，实测会被跳过（不写结构对比、
# 不问用户就直接生成）。挂了带闸门的技能时，服务端在 generate_image / generate_video
# 执行前硬检查：①画布上有技能要求的分析节点 ②用户已在问答卡里确认过方案。
# 确认状态按画布存（问答卡的回答在下一次运行才到），模型自己写「已确认」不算。
# ---------------------------------------------------------------------------

AGENT_SKILL_GATES = {
    "product-motion-recast": {
        "title": "动作复刻换产品",
        "nodes": (("产品结构对比", "产品结构对比与节拍映射"), ("分镜表", "分镜表")),
        "confirm": True,
    },
}
_AGENT_SKILL_GATE_TOOLS = ("generate_image", "generate_video")
_AGENT_SKILL_GATE_YES = ("按方案做", "先只做第一段", "确认", "同意", "开始做", "开始生成", "可以", "没问题", "就这样", "ok", "好的", "行")
_AGENT_SKILL_GATE_NO = ("改方案", "我来改", "修改", "不要", "先别", "不行", "不对")
_AGENT_RUN_SKILL_GATE = contextvars.ContextVar("novai_agent_run_skill_gate", default="")
_AGENT_SKILL_GATE_LOCK = Lock()


def _agent_skill_gate_path():
    return os.path.join(DATA_DIR, "agent_skill_gates.json")


def _agent_skill_gate_load():
    try:
        with open(_agent_skill_gate_path(), "r", encoding="utf-8") as fh:
            data = json.load(fh)
        return data if isinstance(data, dict) else {}
    except (OSError, ValueError):
        return {}


def _agent_skill_gate_update(canvas_id, skill_id, **fields):
    if not canvas_id or not skill_id:
        return
    with _AGENT_SKILL_GATE_LOCK:
        data = _agent_skill_gate_load()
        key = "%s::%s" % (canvas_id, skill_id)
        entry = data.get(key) if isinstance(data.get(key), dict) else {}
        entry.update(fields)
        data[key] = entry
        os.makedirs(os.path.dirname(_agent_skill_gate_path()), exist_ok=True)
        tmp = _agent_skill_gate_path() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(data, fh, ensure_ascii=False, indent=1)
        os.replace(tmp, _agent_skill_gate_path())


def _agent_skill_gate_state(canvas_id, skill_id):
    entry = _agent_skill_gate_load().get("%s::%s" % (canvas_id, skill_id))
    return entry if isinstance(entry, dict) else {}


def _agent_skill_gate_activate(skill_id):
    skill_id = str(skill_id or "").strip()
    if skill_id in AGENT_SKILL_GATES:
        _AGENT_RUN_SKILL_GATE.set(skill_id)


def _agent_skill_gate_answer_confirms(text):
    text = str(text or "").strip()
    if not text:
        return False
    low = text.lower()
    if any(word in text for word in _AGENT_SKILL_GATE_NO):
        return False
    return any(word in low for word in _AGENT_SKILL_GATE_YES)


def _agent_skill_gate_begin(ctx, instruction):
    """运行开始：选中了带闸门的技能就挂上；上次问过方案、这次是用户的回答 → 记下是否确认。"""
    canvas_id = str(getattr(ctx, "canvas_id", "") or "")
    _agent_skill_gate_activate(getattr(ctx, "skill_id", ""))
    if not canvas_id:
        return
    for skill_id in AGENT_SKILL_GATES:
        state = _agent_skill_gate_state(canvas_id, skill_id)
        if state.get("asked_at") and not state.get("answered_at"):
            confirmed = _agent_skill_gate_answer_confirms(instruction)
            _agent_skill_gate_update(canvas_id, skill_id, answered_at=time.time(),
                                     answer=str(instruction or "")[:200],
                                     confirmed_at=time.time() if confirmed else 0)
            if confirmed:
                _agent_skill_gate_activate(skill_id)


def _agent_skill_gate_record_ask(questions, message=""):
    skill_id = _AGENT_RUN_SKILL_GATE.get()
    canvas_id = str(_AGENT_RUN_CANVAS_ID.get() or "")
    if not skill_id or not canvas_id or not questions:
        return
    _agent_skill_gate_update(canvas_id, skill_id, asked_at=time.time(), answered_at=0, confirmed_at=0,
                             question=(str(message or "") + " " + json.dumps(questions, ensure_ascii=False))[:400])


def _agent_skill_gate_missing(canvas, skill_id):
    from server.agent_core.read_tools import CanvasAccess

    gate = AGENT_SKILL_GATES.get(skill_id) or {}
    access = CanvasAccess()
    heads = []
    for node in access.nodes(canvas or {}):
        if access.kind(node) not in ("text", "label"):
            continue
        heads.append((access.title(node) + "\n" + (access.text(node) or str(node.get("text") or ""))[:200]))
    return [label for keyword, label in gate.get("nodes") or () if not any(keyword in h for h in heads)]


def _agent_skill_gate_check(tool_name, args):
    """生成前的硬检查；返回 None 放行，否则返回拦下时给模型的结果。"""
    skill_id = _AGENT_RUN_SKILL_GATE.get()
    if tool_name not in _AGENT_SKILL_GATE_TOOLS or not skill_id:
        return None
    gate = AGENT_SKILL_GATES.get(skill_id) or {}
    canvas_id = str((args or {}).get("canvas_id") or _AGENT_RUN_CANVAS_ID.get() or "")
    try:
        canvas = load_canvas(canvas_id) if canvas_id else {}
    except HTTPException:
        canvas = {}
    missing = _agent_skill_gate_missing(canvas, skill_id)
    state = _agent_skill_gate_state(canvas_id, skill_id) if canvas_id else {}
    need_confirm = bool(gate.get("confirm")) and not state.get("confirmed_at")
    if not missing and not need_confirm:
        return None
    todo = []
    if missing:
        todo.append("先用 create_node(type=text) 写好%s（标题要带这几个字），按技能逐项写出判定和依据" %
                    "、".join("「%s」" % m for m in missing))
    if need_confirm:
        if state.get("answered_at") and not state.get("confirmed_at"):
            todo.append("用户上次没有确认方案（回答：%s），按用户意见改分镜表后再用 ask_user 确认一次" %
                        (state.get("answer") or "空"))
        else:
            todo.append("再用 ask_user 把方案交给用户确认（选项至少有「按方案做」「先只做第一段试试」「我来改方案」），"
                        "用户确认之前不生成任何图片和视频")
    return {"ok": False, "tool": tool_name, "code": "skill_gate_blocked", "status_code": 409,
            "error": "技能「%s」的生成闸门：还不能生成。%s。不花钱的步骤（读视频、写分析、本机深度、审查）可以继续做。" %
                     (gate.get("title") or skill_id, "；".join(todo))}


# ---------------------------------------------------------------------------
# 阶段一（NOVAI_AGENT_V2_READ_TOOLS）：六个按需读取工具
#   read_node / search_canvas / read_table / canvas_diff / view_image / recall_step
#   纯只读、不花钱、不进确认闸门。和 review_table 一样挂在 AGENT_TOOLS 字面量之后：
#   tests/test_novai_cli.py 会解析字面量逐条比对命令表，挂在这里才不会被当成通用画布工具。
# ---------------------------------------------------------------------------

# 当前运行（run）的转录：recall_step 用它按步骤编号取回被折叠的结果原文。
_AGENT_RUN_TRANSCRIPT = contextvars.ContextVar("agent_run_transcript", default=None)
# 本次运行开始时的画布快照：canvas_diff 用它回答「自这次对话以来用户手动改了什么」。
_AGENT_RUN_BASELINE = contextvars.ContextVar("agent_run_baseline", default=None)
# 本次运行所属的画布 ID：读工具没给 canvas_id、或给的加载不到（模型常把画布标题当 ID）时回落到它。
_AGENT_RUN_CANVAS_ID = contextvars.ContextVar("agent_run_canvas_id", default="")
# 阶段二：本次运行所属的对话线程（recall 的 scope=thread 靠它；路由则由请求参数给）
_AGENT_RUN_THREAD_ID = contextvars.ContextVar("agent_run_thread_id", default="")
# B3：发起人这次能看的画布集合（运行开始时由路由固定）；recall 的 scope=all 与模型给的 canvas_id
# 都要过同一套可见性检查，默认 None = 未提供（不额外收紧，保持旧调用方行为）
_AGENT_RUN_ALLOWED_CANVASES = contextvars.ContextVar("agent_run_allowed_canvases", default=None)


def _agent_v2_canvas_baseline(canvas_id):
    """canvas_diff 的对比基线：优先用本次运行开始时的快照，其次用该画布最后一个版本快照。
    都没有就返回 None（工具会如实回答「没有可对比的旧快照」）。"""
    canvas_id = str(canvas_id or "").strip()
    scoped = _AGENT_RUN_BASELINE.get()
    if isinstance(scoped, dict) and str(scoped.get("canvas_id") or "") == canvas_id:
        canvas = scoped.get("canvas")
        if isinstance(canvas, dict):
            return canvas
    try:
        versions = list_canvas_versions(canvas_id)
    except Exception:
        versions = []
    for meta in reversed(versions):
        try:
            rec = read_canvas_version(canvas_id, meta.get("version"))
        except Exception:
            continue
        snap = rec.get("canvas_snapshot") if isinstance(rec, dict) else None
        if isinstance(snap, dict):
            return snap
    return None


def _agent_v2_merged_read_table(canvas_entry, file_entry):
    """read_table 一名两用：给了 node_id / canvas_id 读画布上的表格节点，否则读用户上传的 xlsx/csv。
    两个功能都保留（文件工具的 read_table 是既有能力，不能被画布版覆盖掉）。"""
    def _canvas_args(args):
        args = args if isinstance(args, dict) else {}
        return bool(str(args.get("node_id") or "").strip()) or bool(str(args.get("canvas_id") or "").strip())

    def validate(args):
        return canvas_entry["validate"](args) if _canvas_args(args) else file_entry["validate"](args)

    def run(args):
        return canvas_entry["run"](args) if _canvas_args(args) else file_entry["run"](args)

    def preview(args, canvas=None):
        if _canvas_args(args):
            return canvas_entry["preview"](args, canvas if canvas is not None else {})
        return file_entry["preview"](args)

    schema = {"type": "object", "properties": {}}
    schema["properties"].update(file_entry.get("schema", {}).get("properties") or {})
    schema["properties"].update(canvas_entry.get("schema", {}).get("properties") or {})
    return {
        "description": (canvas_entry.get("description") or "").rstrip("。") + "。"
                       "不给 node_id（也就没有画布节点）时，它读的是用户上传的 xlsx/csv：用 name / sheet / max_rows / offset。",
        "schema": schema,
        "validate": validate,
        "run": run,
        "preview": preview,
        "mutates_canvas": False,
    }


def _agent_v2_resolve_read_canvas(entry):
    """读工具执行器的 canvas_id 兜底：没填、或填了但加载不到（模型常把画布标题当画布 ID），
    都回落到本次运行所属的画布，并把真实 ID 写回参数——工具结果里的 canvas_id 也就变成了对的，
    模型下一轮照抄这个结果就不会再错。真给了别的画布且确实存在时照旧读那张。"""
    def _resolve(arguments):
        args = dict(arguments) if isinstance(arguments, dict) else {}
        current = str(_AGENT_RUN_CANVAS_ID.get() or "").strip()
        if not current:
            return args
        value = str(args.get("canvas_id") or "").strip()
        if not value:
            args["canvas_id"] = current
            return args
        if value != current:
            try:
                load_canvas(value)     # 能加载就尊重模型给的另一张画布
            except HTTPException:
                args["canvas_id"] = current
        return args

    def validate(arguments):
        return entry["validate"](_resolve(arguments))

    def preview(arguments, canvas=None):
        return entry["preview"](_resolve(arguments), canvas)

    return {"description": entry["description"], "schema": entry["schema"],
            "validate": validate, "run": entry["run"], "preview": preview,
            "mutates_canvas": bool(entry.get("mutates_canvas"))}


def _agent_v2_read_tool_entries():
    """read_tools.tool_entries(...) → AGENT_TOOLS 形状的六条注册项（接线全部由 main 注入）。"""
    if _agent_read_tools is None:
        return {}
    entries = _agent_read_tools.tool_entries(
        load_canvas=lambda canvas_id: load_canvas(canvas_id),
        get_transcript=lambda: _AGENT_RUN_TRANSCRIPT.get(),
        load_baseline=_agent_v2_canvas_baseline,
        access=_agent_read_tools.CanvasAccess(),
        error_cls=AgentToolError,
    )
    entries = {name: _agent_v2_resolve_read_canvas(entry) for name, entry in entries.items()}
    merged = _agent_v2_merged_read_table(entries.get("read_table") or {}, _AGENT_FILE_TOOLS.get("read_table") or {})
    if merged.get("validate") and merged.get("run"):
        entries["read_table"] = merged
    return entries


if _agent_v2_read_tools_enabled():
    AGENT_TOOLS.update(_agent_v2_read_tool_entries())


def _agent_args_have_step_refs(args):
    """args 中是否含 {stepN...} 前序步骤引用占位符（预览时跳过存在性校验）。"""
    if isinstance(args, str):
        return args.startswith("{step") and args.endswith("}")
    if isinstance(args, dict):
        return any(_agent_args_have_step_refs(v) for v in args.values())
    if isinstance(args, list):
        return any(_agent_args_have_step_refs(v) for v in args)
    return False


