# 画布助手额外可用的文件工具：只读表格 + 写 HTML/Excel 交付物（不建画布节点）。
_AGENT_CANVAS_FILE_TOOL_NAMES = ("read_table", "write_html_report", "write_xlsx")
_AGENT_FILE_WRITE_EXTS = {"write_html_report": (".html", ".htm"), "write_xlsx": (".xlsx",)}


def _agent_canvas_file_tools():
    return {name: _AGENT_FILE_TOOLS[name] for name in _AGENT_CANVAS_FILE_TOOL_NAMES
            if name in _AGENT_FILE_TOOLS}


def _agent_file_write_error(tool, args):
    """写文件类工具的前置闸门：只允许纯文件名 + 白名单扩展名（写盘位置固定为 DATA_DIR 下）。

    违规返回可读错误（交给 agent_execute_step 回灌模型），不抛异常。
    """
    allowed = _AGENT_FILE_WRITE_EXTS.get(str(tool or ""))
    if not allowed:
        return ""
    args = args if isinstance(args, dict) else {}
    name = str(args.get("name") or "").strip()
    if not name:
        return ""      # 不写名字时由工具用默认文件名（仍在 DATA_DIR 下）
    if name != os.path.basename(name) or "\\" in name or "/" in name or ".." in name:
        return "产物文件名只能是纯文件名（不能带目录/..）：%s" % name
    ext = os.path.splitext(name)[1].lower()
    if ext and ext not in allowed:
        return "产物扩展名不支持：%s（%s 只允许 %s）" % (ext, tool, "、".join(allowed))
    return ""


async def agent_execute_step(tool_name, args):
    """执行单个工具步骤。返回统一结构 {ok, tool, result/error, code, ...}，绝不吞错误。"""
    guard_error = _agent_file_write_error(tool_name, args or {})
    if guard_error:
        return {"ok": False, "tool": tool_name, "error": guard_error,
                "code": "artifact_path_rejected", "status_code": 400}
    if str(tool_name or "").startswith(_mcp_registry.AGENT_TOOL_PREFIX):
        if not _mcp_registry.enabled():
            # env_override 为 on 时 enabled() 必为真、走不到这里；能到这里只有「界面没开」和「环境变量显式 off」
            override = _mcp_registry.config.env_override()
            if override == "off":
                hint = ("MCP 未启用：环境变量 NOVAI_MCP_ENABLED=off 强制关闭；"
                        "去掉该环境变量后可在 设置 → 插件 → MCP 服务 里打开总开关")
            else:
                hint = "MCP 未启用：请到 设置 → 插件 → MCP 服务 打开总开关"
            return {"ok": False, "tool": tool_name, "error": hint,
                    "code": "mcp_disabled", "status_code": 400}
        # stdio 子进程调用是阻塞的，丢到线程里跑，别卡事件循环
        return await asyncio.to_thread(_mcp_registry.execute_agent_step, tool_name, args or {})
    if tool_name in ("web_search", "fetch_url", "search_images", "find_similar_images", \
                     "add_image_to_canvas") and not agent_web_enabled():
        return {"ok": False, "tool": tool_name, "error": "画布助手联网功能未开启，请在设置 → 通用中开启后再试。",
                "code": "web_access_disabled", "status_code": 403}
    entry = AGENT_TOOLS.get(tool_name) or _AGENT_FILE_TOOLS.get(tool_name) or _agent_web_tool_entries().get(tool_name)
    if not entry:
        return {"ok": False, "tool": tool_name, "error": f"未知工具：{tool_name}",
                "code": "unknown_tool", "status_code": 400}
    gate_block = _agent_skill_gate_check(tool_name, args or {})
    if gate_block:
        return gate_block
    notes_token = _AGENT_TABLE_CELL_NOTES.set([])
    try:
        norm_args = entry["validate"](_agent_resolve_aliases_in_args(args or {}))
        fn = entry["run"]
        result = await fn(norm_args) if asyncio.iscoroutinefunction(fn) else fn(norm_args)
        notes = list(_AGENT_TABLE_CELL_NOTES.get() or [])
        _AGENT_TABLE_CELL_NOTES.reset(notes_token)
        payload = {"ok": True, "tool": tool_name, "result": result, "message": "执行成功"}
        if notes:
            payload["message"] = "执行成功（" + "；".join(notes[:4]) + "）"
            payload["warnings"] = notes
        return payload
    except AgentToolError as exc:
        return {"ok": False, "tool": tool_name, "error": exc.message, "code": exc.code,
                "status_code": exc.status_code, "warnings": exc.warnings,
                "requires_force": exc.requires_force}
    except _AgentFileToolError as exc:
        return {"ok": False, "tool": tool_name, "error": exc.message, "code": exc.code,
                "status_code": exc.status_code}
    except HTTPException as exc:
        detail = exc.detail if isinstance(exc.detail, str) else str(exc.detail)
        return {"ok": False, "tool": tool_name, "error": detail, "code": "http_error",
                "status_code": exc.status_code}
    except Exception as exc:
        return {"ok": False, "tool": tool_name,
                "error": _agent_clean_error_text(f"{type(exc).__name__}: {exc}", fallback="执行出错，未返回具体原因"),
                "code": "internal_error", "status_code": 500}


def _agent_resolve_step_refs(args, results):
    """把 args 里的 {stepN.path} 引用替换为前序步骤结果值（计划状态机的轻量实现）。
    容错：① 路径中 result/results 键跳过（兼容 {stepN.results[0].url} 与 {stepN.result.items[0].url}）；
    ② 方括号下标先拆成点路径（{step0.results[0].url} → step0.results.0.url）。"""
    if isinstance(args, str):
        if args.startswith("{step") and args.endswith("}"):
            raw = args[1:-1].replace("[", ".").replace("]", "")
            path = [p for p in raw.split(".") if p]
            try:
                idx = int(path[0][4:])
            except (ValueError, IndexError):
                return args
            if idx < len(results) and results[idx].get("ok"):
                cur = results[idx].get("result")
                for part in path[1:]:
                    if part in ("result", "results") and isinstance(cur, dict) and part not in cur:
                        continue  # 兼容：跳过结果包装键
                    if isinstance(cur, dict):
                        cur = cur.get(part)
                    elif isinstance(cur, list) and part.isdigit() and int(part) < len(cur):
                        cur = cur[int(part)]
                    else:
                        return args
                return cur if cur is not None else args
        return args
    if isinstance(args, dict):
        return {k: _agent_resolve_step_refs(v, results) for k, v in args.items()}
    if isinstance(args, list):
        return [_agent_resolve_step_refs(v, results) for v in args]
    return args


# ---------------------------------------------------------------------------
# Agent 会话持久化（data/agent_sessions/*.json）
# ---------------------------------------------------------------------------

def agent_session_path(session_id):
    cleaned = re.sub(r"[^a-zA-Z0-9_-]", "", session_id or "")
    if not cleaned:
        raise HTTPException(status_code=400, detail="无效的会话 ID")
    return os.path.join(AGENT_SESSIONS_DIR, f"{cleaned}.json")


def agent_session_save(session):
    try:
        os.makedirs(AGENT_SESSIONS_DIR, exist_ok=True)
        tmp = agent_session_path(session["session_id"]) + f".tmp{os.getpid()}"
        write_json_atomic(tmp, session, ensure_ascii=False, indent=2)
        os.replace(tmp, agent_session_path(session["session_id"]))
    except Exception as exc:
        print(f"[Agent] 会话持久化失败: {exc}")


def agent_session_load(session_id):
    path = agent_session_path(session_id)
    if not os.path.exists(path):
        return None
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def agent_session_list():
    sessions = []
    if os.path.isdir(AGENT_SESSIONS_DIR):
        for filename in sorted(os.listdir(AGENT_SESSIONS_DIR), reverse=True):
            if not filename.endswith(".json"):
                continue
            try:
                with open(os.path.join(AGENT_SESSIONS_DIR, filename), "r", encoding="utf-8") as f:
                    rec = json.load(f)
                sessions.append({
                    "session_id": rec.get("session_id"),
                    "canvas_id": rec.get("canvas_id"),
                    "instruction": (rec.get("instruction") or "")[:200],
                    "intent": (rec.get("intent") or "")[:200],
                    "status": rec.get("status") or "planned",
                    "step_count": len((rec.get("plan") or {}).get("steps") or []),
                    "version": rec.get("version"),
                    "created_at": rec.get("created_at"),
                    "updated_at": rec.get("updated_at"),
                })
            except Exception:
                continue
    return sessions


def _agent_new_session(canvas_id, instruction, context, plan):
    now = time.time()
    return {
        "session_id": f"agent_{uuid.uuid4().hex}",
        "canvas_id": canvas_id,
        "instruction": instruction,
        "context": context or "",
        "intent": plan.get("intent") or "",
        "plan": plan,
        "execution_log": [],
        "status": "planned",
        "version": None,
        "created_at": now,
        "updated_at": now,
    }


