def _agent_build_tools_catalog():
    catalog = [{"name": name, "description": entry["description"], "schema": entry["schema"]}
               for name, entry in AGENT_TOOLS.items()]
    if agent_web_enabled():
        catalog.extend({"name": name, "description": entry["description"], "schema": entry["schema"]}
                       for name, entry in _agent_web_tool_entries().items())
    # MCP 工具（mcp__<server>__<tool>）：未启用时 registry 返回空列表，目录与原来逐字一致
    catalog.extend({"name": item["name"], "description": item["description"], "schema": item["schema"]}
                   for item in _mcp_registry.agent_tool_entries())
    return catalog


# ---------------------------------------------------------------------------
# 联网图片 HTTP 接口（前端画布助手直接调；鉴权沿用现有 /api/agent/* 的做法）
# ---------------------------------------------------------------------------

class AgentImagesImportPayload(BaseModel):
    urls: List[str] = []
    # 契约增量：items=[{url, source_page}]，有 items 时优先用它（source_page 的 origin 当 Referer，治防盗链）
    items: List[Dict[str, Any]] = []
    name: str = ""


class AgentImagesAddToCanvasPayload(BaseModel):
    canvas_id: str
    url: str
    title: str = ""


class AgentImagesReversePayload(BaseModel):
    image_url: str
    count: int = 24


def _agent_images_web_disabled_response():
    return _agent_web_http_error(
        403, "web_access_disabled",
        "画布助手联网功能未开启：请到「设置 › 通用」打开「画布助手联网」后再试")


@app.post("/api/agent/images/import")
async def agent_images_import(payload: AgentImagesImportPayload):
    """把外链原图逐条下载落库到素材库（agent-web/），返回本地 url + 真实宽高。"""
    if not agent_web_enabled():
        return _agent_images_web_disabled_response()
    entries = payload.items or payload.urls        # items 优先，兼容只传 urls 的老调用
    try:
        return await _agent_import_web_images(entries, payload.name)
    except AgentToolError as exc:
        return _agent_web_http_error(exc.status_code or 400, exc.code, exc.message)
    except Exception as exc:
        return _agent_web_http_error(500, "internal_error",
                                     _agent_clean_error_text(f"{type(exc).__name__}: {exc}",
                                                             fallback="导入图片出错，未返回具体原因"))


@app.post("/api/agent/images/add-to-canvas")
async def agent_images_add_to_canvas(payload: AgentImagesAddToCanvasPayload):
    """把一张图（外链原图或本地素材）落成本地素材并建成画布 image 节点。"""
    if not agent_web_enabled():
        return _agent_images_web_disabled_response()
    try:
        return await _agent_add_image_to_canvas(payload.canvas_id, payload.url, payload.title)
    except AgentToolError as exc:
        return _agent_web_http_error(exc.status_code or 400, exc.code, exc.message)
    except HTTPException as exc:
        return _agent_web_http_error(exc.status_code or 400, "invalid_request",
                                     exc.detail if isinstance(exc.detail, str) else str(exc.detail))
    except Exception as exc:
        return _agent_web_http_error(500, "internal_error",
                                     _agent_clean_error_text(f"{type(exc).__name__}: {exc}",
                                                             fallback="把图片加入画布出错，未返回具体原因"))


@app.post("/api/agent/images/reverse")
async def agent_images_reverse(payload: AgentImagesReversePayload):
    """反图：视觉模型读图 → 检索词 → 图搜（与 find_similar_images 工具同一份实现）。"""
    if not agent_web_enabled():
        return _agent_images_web_disabled_response()
    try:
        return await _agent_reverse_image_search(payload.image_url, payload.count)
    except AgentToolError as exc:
        return _agent_web_http_error(exc.status_code or 400, exc.code, exc.message)
    except Exception as exc:
        return _agent_web_http_error(500, "internal_error",
                                     _agent_clean_error_text(f"{type(exc).__name__}: {exc}",
                                                             fallback="反图出错，未返回具体原因"))


@app.get("/api/agent/images/thumb")
async def agent_images_thumb(url: str = "", w: str = ""):
    """缩略图服务端代理：浏览器 <img> 的 Referer 不受控（花瓣带 Referer 会返回反爬 HTML），
    这里不带 Referer 拉图（≤8MB、只认图片），可按 w（200-1200，默认 480）等比缩放并转 JPEG，内存 LRU 缓存。"""
    if not agent_web_enabled():
        return _agent_images_web_disabled_response()
    from server import web_access, web_image_search

    target = str(url or "").strip()
    if not target:
        return _agent_web_http_error(400, "invalid_args", "缺少图片地址参数 url")
    try:
        thumb = await web_image_search.fetch_thumb_bytes(
            target, w, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV)
    except web_access.WebAccessError as exc:
        return _agent_web_http_error(400, "invalid_url", str(exc))
    except web_image_search.WebImageSearchError as exc:
        message = str(exc)
        if "MB 上限" in message:
            return _agent_web_http_error(413, "too_large", message)
        if message.startswith("下载到的不是图片"):
            return _agent_web_http_error(400, "not_image", message)
        return _agent_web_http_error(400, "thumb_failed", message)
    except Exception as exc:
        return _agent_web_http_error(500, "internal_error",
                                     _agent_clean_error_text(f"{type(exc).__name__}: {exc}",
                                                             fallback="缩略图代理出错，未返回具体原因"))
    return Response(content=thumb["data"], media_type=thumb["content_type"],
                    headers={"Cache-Control": "public, max-age=86400",
                             "X-Novai-Thumb-Width": str(thumb.get("width") or ""),
                             "X-Novai-Thumb-Height": str(thumb.get("height") or ""),
                             "X-Novai-Thumb-Scaled": "1" if thumb.get("scaled") else "0",
                             "X-Novai-Thumb-Cache": "1" if thumb.get("cache") else "0"})


def agent_reference_image_count(reference_images):
    """本次请求的参考图数量：去重、排除视频。纯函数，便于直测。
    生产传进来的是 [{"url": ...}]（字典数组），同时兼容旧的纯 URL 字符串写法。"""
    seen = set()
    for value in (reference_images or []):
        url = value.get("url") if isinstance(value, dict) else value
        url = str(url or "").strip()
        if not url or url in seen or is_video_reference_value(url):
            continue
        seen.add(url)
    return len(seen)


def agent_plan_reference_hint(reference_images):
    """参考图 ≥2 张时给规划模型的确定性提示（追加进用户消息）；否则返回空串。纯函数。"""
    count = agent_reference_image_count(reference_images)
    if count < 2:
        return ""
    return (f"本次有 {count} 张参考图（≥2），必须规划为 table → batch 批量线："
            "先 create_node(type=table, rows=[...]) 把每个版本 / 每张图写成一行完整提示词，"
            "再用 create_node(type=batch, media=image, inputs=[表格节点]) 逐行出图，"
            "settings 写全 provider/model/ratio/resolution；不要用单个 image 节点逐张出图。")


def _agent_run_media_platforms_text(selected_provider=""):
    """给模型看的「可用生图/生视频平台 → 模型清单」，全部来自 API 设置；从源头减少乱写平台不认识的模型名。
    selected_provider：用户在界面上选定的生图平台（空＝自动）。"""
    selected = str(selected_provider or "").strip().lower()
    lines = []
    selected_ok = False
    for provider in load_api_providers():
        if not isinstance(provider, dict) or provider.get("enabled") is False:
            continue
        pid = str(provider.get("id") or "").strip().lower()
        if not pid:
            continue
        try:
            base, _, _ = resolve_chat_provider(pid, "", "", require_model=False)
        except HTTPException:
            continue
        if not base:
            continue
        images = _agent_declared_models(provider, "image_models") + \
            [str(item or "").strip() for item in (provider.get("models") or [])]
        videos = _agent_declared_models(provider, "video_models")
        images = [item for item in dict.fromkeys(images) if item]
        parts = []
        if images:
            # 如实告诉模型「这个模型一次最多几张」，它就不会把 4 张写成 1 张；
            # 没有声明规格的模型保持原样（不加提示）。
            annotated = []
            for name in images:
                try:
                    n_max = int((model_caps_for(pid, name, "image") or {}).get("n_max") or 0)
                except Exception:
                    n_max = 0
                annotated.append("%s（一次最多 %d 张）" % (name, n_max) if n_max else name)
            parts.append("生图模型：" + "、".join(annotated))
        if videos:
            parts.append("生视频模型：" + "、".join(videos))
        if parts:
            mark = "【用户选定】" if pid == selected else ""
            selected_ok = selected_ok or bool(mark and images)
            lines.append(f"- {mark}{pid}（" + "；".join(parts) + "）")
    if not lines:
        return "（当前没有配置可用的生图/生视频平台）"
    if selected_ok:
        head = (f"用户在界面上选定了生图平台 {selected}：生图只用它的模型，按这次任务从它的清单里挑最合适的一个写进 model；"
                "生视频它没有就按下面清单自动挑。")
    else:
        head = ("用户没有指定平台（自动）：按这次任务从下面清单里挑最合适的平台和模型（写实人像/产品、文字排版、插画风格等各有所长，"
                "按模型名判断），provider 和 model 都要写上；拿不准时用清单里靠前的。")
    return head + "\n" + "\n".join(lines)


def _agent_json_loads(text):
    """容错解析模型写的 JSON。有的平台把流式分片拼回来时会在字符串中间插入真实换行
    （「提取图\n89」），标准 JSON 里字符串不允许出现真实换行——这种换行一定是拼接带进来的，去掉即可；
    字符串外的换行本来就是空白，去掉也不影响。正常的换行在 JSON 里是转义的 \\n，不受影响。"""
    try:
        return json.loads(text)
    except Exception as first:
        cleaned = (text or "").replace("\r", "").replace("\n", "")
        try:
            return json.loads(cleaned, strict=False)
        except Exception:
            raise first


def _agent_looks_like_plan_json(text):
    t = text or ""
    return ("\"steps\"" in t and "\"tool\"" in t) or t.lstrip().startswith("```json")


def _agent_extract_json(text):
    """容错提取 JSON：去代码围栏，取第一对 { } 之间的内容。"""
    cleaned = (text or "").strip()
    if cleaned.startswith("```"):
        cleaned = re.sub(r"^```[a-zA-Z]*\s*", "", cleaned)
        cleaned = re.sub(r"\s*```$", "", cleaned)
    start = cleaned.find("{")
    end = cleaned.rfind("}")
    if start == -1 or end <= start:
        return None
    return cleaned[start:end + 1]




def _agent_json_first_balanced(text):
    """取文本里第一个「括号配平」的 {...}（字符串 / 转义感知），返回 (json_text, 剩余文本)。

    模型有时会输出「决策 JSON + 另一个 JSON / 尾随说明」，json.loads 整段会报 Extra data；
    这里只取第一个完整对象，尾巴交给调用方决定合并或忽略。"""
    s = str(text or "")
    start = s.find("{")
    if start < 0:
        return "", s
    depth, in_string, escaped = 0, False, False
    for index in range(start, len(s)):
        ch = s[index]
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
            continue
        if ch == '"':
            in_string = True
        elif ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                return s[start:index + 1], s[index + 1:]
    return "", s


def _agent_strip_balanced_json(text):
    """去掉文本里所有完整的 {...} 对象（保留对象之间的说明文字）。"""
    s = str(text or "")
    parts = []
    while True:
        start = s.find("{")
        if start < 0:
            parts.append(s)
            break
        parts.append(s[:start])
        body, tail = _agent_json_first_balanced(s)
        if not body:
            parts.append(s)
            break
        s = tail
    return "".join(parts).strip()


def _agent_parse_decision_json(text):
    """解析一轮决策 JSON：取第一个平衡对象；尾随对象里的 suggestions 并进决策，其余尾随内容忽略并记日志。"""
    cleaned = str(text or "").strip()
    if cleaned.startswith("```"):
        cleaned = re.sub(r"^```[a-zA-Z]*\s*", "", cleaned)
        cleaned = re.sub(r"\s*```$", "", cleaned)
    body, tail = _agent_json_first_balanced(cleaned)
    if not body:
        raise AgentRunError(f"模型返回的不是合法 JSON：{cleaned[:200]}", code="bad_model_json")
    try:
        data = _agent_json_loads(body)
    except Exception as exc:
        raise AgentRunError(f"模型 JSON 解析失败：{exc}", code="bad_model_json")
    if not isinstance(data, dict):
        raise AgentRunError("模型返回的不是 JSON 对象", code="bad_model_json")
    extra_suggestions, skipped = [], []
    rest = tail
    while True:
        extra_body, rest_after = _agent_json_first_balanced(rest)
        if not extra_body:
            break
        try:
            extra = _agent_json_loads(extra_body)
        except Exception:
            skipped.append(extra_body[:120])
            extra = None
        if isinstance(extra, dict) and isinstance(extra.get("suggestions"), list):
            for item in extra["suggestions"]:
                if item not in extra_suggestions:
                    extra_suggestions.append(item)
        elif extra is not None:
            skipped.append(str(extra)[:120])
        rest = rest_after
    if extra_suggestions:
        current = data.get("suggestions")
        current = list(current) if isinstance(current, list) else []
        data["suggestions"] = current + [item for item in extra_suggestions if item not in current]
    trailing = str(rest or "").strip()
    if trailing or skipped:
        ignored = "；".join(skipped[:2]) if skipped else trailing[:120]
        print(f"[Agent] 决策 JSON 后还有尾随内容（已忽略）: {ignored!r}", flush=True)
    return data


# ── 对话选型（三处入口共用：Agent run / 方案生成 plan / 智能体广场）────────────
# 口径：用户在输入框选的平台+模型优先且**原样**使用；该平台不可用才回退到别的已配置平台，
# 回退时 model 传空（用那个平台自己的默认模型），并标 fallback。provider 为空时只走可用平台列表。
def _agent_chat_requested(provider, model):
    """把用户点名的平台/模型归一：平台去空格转小写，模型只去前后空格（原样保留）。"""
    return str(provider or "").strip().lower(), str(model or "").strip()


def _agent_chat_candidates(requested_provider):
    """候选顺序：用户点名的平台（含历史别名 comfly）第一 → 其余可用平台（comfly 垫底），去重保序。"""
    candidates = [requested_provider] if requested_provider else []
    candidates += _agent_available_providers()
    seen = set()
    return [p for p in candidates if not (p in seen or seen.add(p))]


def _agent_chat_candidate_model(requested_provider, requested_model, cand):
    """只有「用户点名的那个候选」才带用户选的模型；回退一律空串 = 用该平台自己的默认模型。
    绝不把用户的（或别的平台的）模型名硬塞给回退平台，避免必然失败。"""
    return requested_model if (requested_provider and cand == requested_provider) else ""


def _agent_chat_selection(cand, base, headers, mdl, requested_provider, requested_model):
    """统一的 chat 字典。旧字段（provider/model/base/headers/provider_cfg）保持不变，
    另加本次选型的来龙去脉，供上层展示：
      requested_provider/requested_model：用户点的（可能为空）
      resolved_provider/resolved_model：实际选中的候选与其模型
      resolved_platform：真正生效的平台 id（"comfly" 是历史别名，会映射到当前首选平台）
      fallback：是否发生了回退（请求的平台没被用上）"""
    provider_cfg = get_api_provider(cand) if cand not in ("modelscope",) else {}
    return {
        "provider": cand,
        "base": base,
        "headers": headers,
        "model": mdl,
        "provider_cfg": provider_cfg,
        "requested_provider": requested_provider,
        "requested_model": requested_model,
        "resolved_provider": cand,
        "resolved_model": mdl,
        "resolved_platform": str((provider_cfg or {}).get("id") or cand),
        "fallback": bool(requested_provider) and cand != requested_provider,
    }


def _agent_chat_log_fallback(chat, log_tag="Agent", reason=""):
    """回退时打一行日志：用户选的是谁、为什么没用上、实际用了谁。"""
    if not isinstance(chat, dict) or not chat.get("fallback"):
        return
    print(f"[{log_tag}] 对话模型回退：用户选的是 {chat.get('requested_provider')}/"
          f"{chat.get('requested_model') or '(平台默认)'}，不可用（{reason or '未知原因'}），"
          f"改用 {chat.get('resolved_platform')}/{chat.get('resolved_model')}", flush=True)


def _resolve_chat_with_preference(provider, model, ms_model, *, log_tag="Agent",
                                  error_prefix="无法运行 Agent（对话模型不可用）",
                                  allow_auto_model=False, require_model=False, joined_detail=False):
    """公共选型（三处入口共用）。

    候选顺序：
      1) 用户显式选的 provider（含历史值 "comfly"）——用它，并且**原样**用用户选的 model；
      2) 其余已配置的可用平台（_agent_available_providers 的顺序，comfly 垫底）——model 传空，
         让该平台用自己的默认对话模型。
    provider 为空时只走 2，与历史行为一致。全都不可用则 400（错误文案由 error_prefix 定制）。

    allow_auto_model=True：用户没给模型时按该平台声明的 chat_models 自动挑（智能体广场用）；
    require_model=True：解析结果里模型为空也算不可用（智能体广场用）；
    joined_detail=True：错误详情汇总每个候选的原因（智能体广场用），否则沿用最后一个原因。
    返回体额外带 tried / reasons，调用方要自己组织错误文案时可以直接用。"""
    requested_provider, requested_model = _agent_chat_requested(provider, model)
    tried, reasons, last_detail = [], [], ""
    for cand in _agent_chat_candidates(requested_provider):
        tried.append(cand)
        cand_model = _agent_chat_candidate_model(requested_provider, requested_model, cand)
        if allow_auto_model and not cand_model:
            cand_model = _agent_auto_chat_model(cand)
            if not cand_model:
                last_detail = f"{cand} 未配置对话模型"
                reasons.append(last_detail)
                continue
        try:
            chat_base, chat_hdrs, mdl = resolve_chat_provider(
                cand, cand_model, ms_model if cand == "modelscope" else "")
        except HTTPException as exc:
            last_detail = str(exc.detail)
            reasons.append(f"{cand}：{exc.detail}")
            continue
        if not chat_base:
            last_detail = f"{cand} 未配置 Base URL"
            reasons.append(last_detail)
            continue
        if require_model and not mdl:
            last_detail = f"{cand} 未配置可用的对话模型"
            reasons.append(last_detail)
            continue
        chat = _agent_chat_selection(cand, chat_base, chat_hdrs, mdl, requested_provider, requested_model)
        _agent_chat_log_fallback(chat, log_tag, last_detail)
        chat["tried"] = tried
        chat["reasons"] = reasons
        return chat
    if not tried:
        # 候选列表为空 = 没有任何「启用且有 Key」的平台：不是网络问题，给出配置指引
        detail = "尚未配置可用的对话平台：请到「设置 › API 设置」为平台填写 API Key 并拉取对话模型"
        raise HTTPException(status_code=400, detail=f"{error_prefix}：{detail}")
    if joined_detail:
        detail = "；".join(reasons) if reasons else "无可用 provider"
    else:
        detail = last_detail or "无可用 provider"
    raise HTTPException(status_code=400,
                        detail=f"{error_prefix}：{detail}（已尝试: {'、'.join(tried)}）")


async def agent_generate_plan(canvas_id, instruction, context, provider="comfly", model="", ms_model=""):
    """调用对话模型生成结构化计划。LLM 不可用时抛 HTTPException（400/502），绝不 mock。
    provider 不可用时自动回退到用户配置的可用 provider（动态顺序）。"""
    canvas = load_canvas(canvas_id)  # 404 校验
    summary = _agent_canvas_summary(canvas)
    # 选型：用户点名的平台（含 comfly）第一候选、原样用它的模型；不可用才按配置顺序回退
    # （回退那一轮 model 传空 = 用该平台自己的默认模型）。上游报错也会继续试下一个平台。
    requested_provider, requested_model = _agent_chat_requested(provider, model)
    tried = []
    last_detail = ""
    for cand in _agent_chat_candidates(requested_provider):
        tried.append(cand)
        try:
            chat_base, chat_hdrs, mdl = resolve_chat_provider(
                cand, _agent_chat_candidate_model(requested_provider, requested_model, cand),
                ms_model if cand == "modelscope" else "")
        except HTTPException as exc:
            last_detail = str(exc.detail)
            continue
        if not chat_base:
            last_detail = f"{cand} 未配置 Base URL"
            continue
        selection = _agent_chat_selection(cand, chat_base, chat_hdrs, mdl, requested_provider, requested_model)
        provider_cfg = selection["provider_cfg"]
        _agent_chat_log_fallback(selection, "AgentPlan", last_detail)
        system = _AGENT_PLAN_SYSTEM_PROMPT.format(
            tools_json=json.dumps(_agent_build_tools_catalog(), ensure_ascii=False),
            canvas_summary=json.dumps(summary, ensure_ascii=False))
        user_text = f"用户指令：{instruction}"
        if context:
            user_text += f"\n补充上下文：{context}"
        user_text += "\n请返回计划 JSON。"
        upstream_messages = [{"role": "system", "content": system}, {"role": "user", "content": user_text}]
        try:
            async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=provider_trust_env(provider_cfg),
                                         timeout=AI_REQUEST_TIMEOUT) as client:
                req_body = {"model": mdl, "messages": upstream_messages}
                if is_apimart_provider(provider_cfg):
                    req_body["stream"] = False
                response = await client.post(f"{chat_base}/chat/completions", headers=chat_hdrs, json=req_body)
                response.raise_for_status()
                raw = response.json()
        except httpx.HTTPStatusError as exc:
            last_detail = f"上游模型接口错误 {exc.response.text[:200]}"
            continue
        except httpx.HTTPError as exc:
            last_detail = f"请求上游模型接口出错：{exc}"
            continue
        text = text_from_chat_response(raw)
        json_text = _agent_extract_json(text)
        if not json_text:
            last_detail = f"模型返回的不是合法 JSON：{(text or '')[:200]}"
            continue
        try:
            plan = _agent_json_loads(json_text)
        except Exception as exc:
            last_detail = f"JSON 解析错误：{exc}"
            continue
        if not isinstance(plan, dict):
            last_detail = "模型返回的不是对象"
            continue
        if not isinstance(plan.get("steps"), list):
            last_detail = "模型返回格式不符合要求（缺 steps 数组）"
            continue
        return _agent_normalize_plan(plan, mdl)
    if not tried:
        raise HTTPException(status_code=400,
                            detail="无法生成计划（对话模型不可用）：尚未配置可用的对话平台："
                                   "请到「设置 › API 设置」为平台填写 API Key 并拉取对话模型")
    raise HTTPException(status_code=400,
                        detail=f"无法生成计划（对话模型不可用）：{last_detail or '无可用 provider'}（已尝试: {'、'.join(tried)}）")


def _agent_normalize_plan(plan, mdl):
    """校验并清洗模型返回的计划：过滤未知工具、规范 steps 结构。"""
    intent = str(plan.get("intent") or "").strip()
    steps = plan.get("steps")
    if not isinstance(steps, list) or not steps:
        raise HTTPException(status_code=400, detail="计划生成失败：steps 为空或不是数组")
    unknown_tools = []
    clean_steps = []
    for i, step in enumerate(steps):
        if not isinstance(step, dict):
            raise HTTPException(status_code=400, detail=f"计划生成失败：第 {i} 步不是对象")
        tool = str(step.get("tool") or "").strip()
        if tool not in AGENT_TOOLS:
            unknown_tools.append(tool or "<空>")
            continue
        args = step.get("args")
        if args is None:
            args = {}
        if not isinstance(args, dict):
            raise HTTPException(status_code=400, detail=f"计划生成失败：第 {i} 步（{tool}）的 args 必须是对象")
        clean_steps.append({
            "tool": tool,
            "args": args,
            "description": str(step.get("description") or "")[:300],
        })
    if unknown_tools:
        raise HTTPException(status_code=400,
                            detail=f"计划生成失败：包含未知工具 {unknown_tools}（可用工具：{list(AGENT_TOOLS.keys())}）")
    return {
        "intent": intent or "未命名意图",
        "steps": clean_steps,
        "expected_output": str(plan.get("expected_output") or "")[:500],
        "model": mdl,
    }


# ---------------------------------------------------------------------------
# 计划 API
# ---------------------------------------------------------------------------

class AgentPlanRequest(BaseModel):
    canvas_id: str
    instruction: str = Field(min_length=1, max_length=4000)
    context: str = ""
    provider: str = "comfly"
    model: str = ""
    ms_model: str = ""


class AgentPreviewRequest(BaseModel):
    plan_id: str = ""
    steps: Optional[List[Dict[str, Any]]] = None
    canvas_id: str = ""


class AgentApplyRequest(BaseModel):
    plan_id: str = ""
    steps: Optional[List[Dict[str, Any]]] = None
    canvas_id: str = ""


class AgentRollbackRequest(BaseModel):
    canvas_id: str
    to_version: int


@app.get("/api/agent/tools")
async def agent_tools_list():
    """工具注册表目录（名称/描述/Schema），供前端与 LLM 使用。"""
    return {"total": len(AGENT_TOOLS), "tools": _agent_build_tools_catalog()}


@app.post("/api/agent/tools/{tool_name}")
async def agent_tools_execute(tool_name: str, payload: dict = None):
    """直接执行单个工具（调试/前端直调）。统一返回 {ok, result, message} 或 4xx 错误详情。"""
    payload = payload or {}
    args = payload.get("args") or {}
    result = await agent_execute_step(tool_name, args)
    if result["ok"]:
        return {"ok": True, "tool": tool_name, "result": result.get("result"), "message": result.get("message")}
    detail = {"ok": False, "tool": tool_name, "message": result.get("error"),
              "code": result.get("code"), "warnings": result.get("warnings") or []}
    status = 409 if result.get("requires_force") else (result.get("status_code") or 400)
    raise HTTPException(status_code=status, detail=detail)


@app.post("/api/agent/plan")
async def agent_plan(payload: AgentPlanRequest):
    """接收 {canvas_id, instruction, context?} → 对话模型生成结构化计划并存为会话。"""
    plan = await agent_generate_plan(payload.canvas_id, payload.instruction, payload.context,
                                     payload.provider, payload.model, payload.ms_model)
    session = _agent_new_session(payload.canvas_id, payload.instruction, payload.context, plan)
    agent_session_save(session)
    return {
        "session_id": session["session_id"],
        "canvas_id": payload.canvas_id,
        "intent": plan["intent"],
        "steps": plan["steps"],
        "expected_output": plan["expected_output"],
        "model": plan["model"],
        "created_at": session["created_at"],
        "status": "planned",
    }


def _agent_steps_from_request(payload, require_canvas: bool):
    """从 plan_id 或 steps 提取步骤列表 + 画布 ID（统一 preview/apply 的取数逻辑）。"""
    steps = None
    canvas_id = str(payload.canvas_id or "").strip()
    session = None
    if str(payload.plan_id or "").strip():
        session = agent_session_load(str(payload.plan_id).strip())
        if not session:
            raise HTTPException(status_code=404, detail="计划会话不存在")
        plan = session.get("plan") or {}
        steps = plan.get("steps") or []
        if not canvas_id:
            canvas_id = str(session.get("canvas_id") or "")
        elif canvas_id != session.get("canvas_id"):
            raise HTTPException(status_code=400, detail="plan_id 与 canvas_id 不匹配（计划属于另一个画布）")
    elif payload.steps:
        steps = payload.steps
    if not steps:
        raise HTTPException(status_code=400, detail="需要提供 plan_id 或 steps")
    if require_canvas and not canvas_id:
        raise HTTPException(status_code=400, detail="canvas_id 不能为空（使用 steps 时必填）")
    clean = []
    for i, step in enumerate(steps):
        if not isinstance(step, dict):
            raise HTTPException(status_code=400, detail=f"第 {i} 步不是对象")
        tool = str(step.get("tool") or "").strip()
        if tool not in AGENT_TOOLS:
            raise HTTPException(status_code=400, detail=f"第 {i} 步包含未知工具：{tool or '<空>'}")
        args = step.get("args")
        if args is None:
            args = {}
        if not isinstance(args, dict):
            raise HTTPException(status_code=400, detail=f"第 {i} 步（{tool}）的 args 必须是对象")
        clean.append({"tool": tool, "args": dict(args),
                      "description": str(step.get("description") or "")[:300]})
    return clean, canvas_id, session


@app.post("/api/agent/preview")
async def agent_preview(payload: AgentPreviewRequest):
    """接收计划 → 不执行，返回每步的「将要做什么」（描述 + 参数摘要 + 影响范围 + 校验警告）。"""
    steps, canvas_id, session = _agent_steps_from_request(payload, require_canvas=False)
    canvas = None
    if canvas_id:
        try:
            canvas = load_canvas(canvas_id)
        except HTTPException:
            canvas = None
    previews = []
    for i, step in enumerate(steps):
        entry = AGENT_TOOLS[step["tool"]]
        item = {
            "index": i,
            "tool": step["tool"],
            "description": step["description"] or entry["description"],
            "args": step["args"],
            "impact": "",
            "valid": True,
            "warning": "",
        }
        try:
            norm_args = entry["validate"](step["args"])
            item["impact"] = entry["preview"](norm_args, canvas or {})
            item["args_summary"] = {k: (v if not isinstance(v, (dict, list)) else f"<{type(v).__name__} {len(v)}项>")
                                    for k, v in norm_args.items() if v not in (None, "", [])}
        except AgentToolError as exc:
            if _agent_args_have_step_refs(step["args"]):
                # 含 {stepN...} 前序结果引用：apply 时才解析，预览跳过存在性校验
                item["valid"] = True
                item["warning"] = "步骤含 {stepN...} 前序结果引用，apply 时解析（预览跳过存在性校验）"
            else:
                item["valid"] = False
                item["warning"] = exc.message
            item["impact"] = entry["preview"](step["args"], canvas or {})
        except HTTPException as exc:
            item["valid"] = False
            item["warning"] = str(exc.detail)
        previews.append(item)
    return {
        "canvas_id": canvas_id,
        "steps": previews,
        "summary": {"total": len(previews),
                    "valid": sum(1 for p in previews if p["valid"]),
                    "invalid": sum(1 for p in previews if not p["valid"])},
        "note": "仅预览，未执行任何操作",
    }


@app.post("/api/agent/apply")
async def agent_apply(payload: AgentApplyRequest):
    """接收 {plan_id 或 steps, canvas_id} → 顺序执行（走工具注册表）；任一失败即停；
    全部成功后自动存画布版本快照便于回滚。"""
    steps, canvas_id, session = _agent_steps_from_request(payload, require_canvas=True)
    load_canvas(canvas_id)  # 404 校验
    if not session:
        # 直接 steps 执行也落一个会话（执行记录），保证 GET /api/agent/sessions/{id} 可查
        session = _agent_new_session(canvas_id, "直接步骤执行（未走计划生成）", "",
                                     {"intent": "direct-steps", "steps": steps, "expected_output": ""})
    session_id = session["session_id"]
    execution_log = []
    results = []
    failed = None
    # 执行前快照（回滚目标：apply 前状态）
    pre_version = None
    try:
        pre_version = _agent_snapshot(load_canvas(canvas_id), note=f"agent apply 前 {session_id or 'direct'}")
    except Exception as exc:
        print(f"[Agent] apply 前版本快照失败（不影响执行）: {exc}")
    for i, step in enumerate(steps):
        resolved_args = _agent_resolve_step_refs(step["args"], results)
        r = await agent_execute_step(step["tool"], resolved_args)
        entry = {
            "index": i,
            "tool": step["tool"],
            "args": resolved_args,
            "description": step["description"] or "",
            "ok": r["ok"],
            "result": r.get("result"),
            "error": r.get("error"),
            "code": r.get("code"),
            "warnings": r.get("warnings") or [],
            "requires_force": r.get("requires_force") or False,
            "at": time.time(),
        }
        execution_log.append(entry)
        results.append(r)
        if not r["ok"]:
            failed = {"step_index": i, "tool": step["tool"], "reason": r.get("error"),
                      "code": r.get("code"), "warnings": r.get("warnings") or [],
                      "requires_force": r.get("requires_force") or False}
            break
    ok = failed is None
    version = None
    if ok:
        try:
            fresh = load_canvas(canvas_id)
            version = _agent_snapshot(fresh, note=f"agent apply {session_id or 'direct'}")
        except Exception as exc:
            print(f"[Agent] apply 后版本快照失败（不影响结果）: {exc}")
    if session:
        session["execution_log"] = execution_log
        session["status"] = "applied" if ok else "failed"
        session["version"] = version
        session["updated_at"] = time.time()
        agent_session_save(session)
    try:
        fresh = load_canvas(canvas_id)
        await manager.broadcast_canvas_updated(canvas_id, int(fresh.get("updated_at") or now_ms()))
    except Exception:
        pass
    if ok:
        return {
            "ok": True,
            "session_id": session_id,
            "canvas_id": canvas_id,
            "executed": len(execution_log),
            "total": len(steps),
            "version": version,
            "pre_version": pre_version,
            "message": f"计划执行完成：{len(execution_log)}/{len(steps)} 步成功，已存画布版本 v{version}（可回滚到 v{pre_version}）" if version
                       else f"计划执行完成：{len(execution_log)}/{len(steps)} 步成功（版本快照未生成）",
            "log": execution_log,
        }
    return {
        "ok": False,
        "session_id": session_id,
        "canvas_id": canvas_id,
        "executed": failed["step_index"],
        "total": len(steps),
        "failed_step": failed,
        "message": f"计划执行失败：第 {failed['step_index']} 步（{failed['tool']}）— {failed['reason']}",
        "log": execution_log,
    }


@app.post("/api/agent/rollback")
async def agent_rollback(payload: AgentRollbackRequest, request: Request):
    """接收 {canvas_id, to_version} → 复用 Phase 2 版本化还原逻辑回滚画布。"""
    canvas_id = str(payload.canvas_id or "").strip()
    to_version = int(payload.to_version or 0)
    if to_version <= 0:
        raise HTTPException(status_code=400, detail="to_version 必须是正整数")
    canvas = load_canvas(canvas_id)
    require_canvas_access(canvas, request, "edit")
    rec = read_canvas_version(canvas_id, to_version)
    snapshot = rec.get("canvas_snapshot")
    if not isinstance(snapshot, dict):
        raise HTTPException(status_code=400, detail="版本快照损坏，无法回滚")
    restored = dict(snapshot)
    for key in ("id", "created_at", "project", "owner", "owner_id", "color", "pinned", "board_x", "board_y", "deleted_at"):
        if key in canvas:
            restored[key] = canvas[key]
    restored["kind"] = canvas.get("kind") or restored.get("kind") or "classic"
    restored_ids = {str(n.get("id")) for n in (restored.get("nodes") or []) if isinstance(n, dict)}
    restored["deleted_node_ids"] = canvas.get("deleted_node_ids") or []
    _agent_add_tombstones(restored, [n.get("id") for n in (canvas.get("nodes") or [])
                                     if isinstance(n, dict) and str(n.get("id")) not in restored_ids])
    save_canvas(restored)
    note = f"agent rollback to v{to_version}"
    new_version = snapshot_canvas_version(restored, note=note, force=True)
    try:
        await manager.broadcast_canvas_updated(canvas_id, int(restored.get("updated_at") or now_ms()))
    except Exception:
        pass
    return {
        "ok": True,
        "canvas_id": canvas_id,
        "restored_from": to_version,
        "version": new_version,
        "note": note,
        "canvas": _agent_canvas_summary(restored),
    }


