@app.get("/api/agent/files/{name}")
async def agent_artifact_file(name: str):
    """智能体产物受控下载：只允许 data 目录下、扩展名白名单内的文件。"""
    raw = str(name or "").strip()
    if (not raw or os.path.basename(raw) != raw or "\\" in raw or "/" in raw
            or ".." in raw or raw in (".", "..")):
        raise HTTPException(status_code=400, detail="非法文件名")
    ext = os.path.splitext(raw)[1].lower()
    if ext not in AGENT_ARTIFACT_EXTS:
        raise HTTPException(status_code=400,
                            detail="不支持的文件类型：%s（允许：%s）" % (ext or "无扩展名",
                                                                "、".join(sorted(AGENT_ARTIFACT_EXTS))))
    path = _agent_artifact_find_path(raw)
    if not path:
        raise HTTPException(status_code=404, detail="产物不存在：%s" % raw)
    return FileResponse(path, filename=raw)


@app.post("/api/agent/threads/rename")
async def agent_threads_rename(payload: AgentThreadRenameRequest, request: Request):
    """重命名线程（1..60 字，去首尾空白）。"""
    canvas_id = str(payload.canvas_id or "").strip()
    if not canvas_id:
        raise HTTPException(status_code=400, detail="canvas_id 不能为空")
    require_canvas_access(load_canvas(canvas_id), request, "view")
    title = str(payload.title or "").strip()
    if not title:
        raise HTTPException(status_code=400, detail="标题不能为空")
    if len(title) > 60:
        raise HTTPException(status_code=400, detail="标题过长（最多 60 字）")
    with _AGENT_THREAD_LOCK:
        doc = _agent_thread_doc_load(canvas_id)
        thread = _agent_thread_find(doc, payload.thread_id)
        if not thread:
            raise HTTPException(status_code=404, detail="线程不存在")
        thread["title"] = title
        thread["updated_at"] = time.time()
        _agent_thread_doc_save(canvas_id, doc)
    return {"ok": True, "thread": {"id": thread["id"], "title": thread["title"]}}


@app.post("/api/agent/threads/feedback")
async def agent_threads_feedback(payload: AgentThreadFeedbackRequest, request: Request):
    canvas_id = str(payload.canvas_id or "").strip()
    if not canvas_id:
        raise HTTPException(status_code=400, detail="canvas_id 不能为空")
    require_canvas_access(load_canvas(canvas_id), request, "view")
    rating = str(payload.rating or "").strip().lower()
    if rating not in ("", "up", "down"):
        raise HTTPException(status_code=400, detail="rating 只支持 up / down / null")
    with _AGENT_THREAD_LOCK:
        doc = _agent_thread_doc_load(canvas_id)
        thread = _agent_thread_find(doc, payload.thread_id)
        if not thread:
            raise HTTPException(status_code=404, detail="线程不存在")
        messages = thread.get("messages") or []
        index = int(payload.message_index)
        if index < 0 or index >= len(messages):
            raise HTTPException(status_code=400,
                                detail="message_index 越界（当前 0..%d）" % (len(messages) - 1))
        message = messages[index]
        if message.get("role") != "assistant":
            raise HTTPException(status_code=400, detail="只能评价助手回复")
        if rating:
            message["rating"] = rating
        else:
            message.pop("rating", None)
        thread["updated_at"] = time.time()
        _agent_thread_doc_save(canvas_id, doc)
    return {"ok": True, "thread_id": thread["id"], "message_index": index, "rating": rating or None}


@app.delete("/api/agent/threads/{thread_id}")
async def agent_threads_delete(thread_id: str, request: Request, canvas_id: str = ""):
    """删除线程；不允许删最后一条；删掉 active 时自动切到剩余里创建时间最新的一条。"""
    canvas_id = str(canvas_id or "").strip()
    if not canvas_id:
        raise HTTPException(status_code=400, detail="canvas_id 不能为空")
    require_canvas_access(load_canvas(canvas_id), request, "view")
    with _AGENT_THREAD_LOCK:
        doc = _agent_thread_doc_load(canvas_id)
        thread = _agent_thread_find(doc, thread_id)
        if not thread:
            raise HTTPException(status_code=404, detail="线程不存在")
        threads = doc.get("threads") or []
        if len(threads) <= 1:
            raise HTTPException(status_code=400, detail="至少保留一条对话")
        doc["threads"] = [item for item in threads if item.get("id") != thread["id"]]
        active_id = str(doc.get("active_id") or "")
        if active_id == thread["id"]:
            remaining = sorted(doc["threads"],
                               key=lambda item: float(item.get("created_at") or 0), reverse=True)
            active_id = str(remaining[0]["id"]) if remaining else ""
            doc["active_id"] = active_id
        _agent_thread_doc_save(canvas_id, doc)
    _agent_v2_memory_index_forget(canvas_id=canvas_id, thread_id=thread["id"])   # 删掉的对话不能还被 recall 搜到
    # B2：档案里的「各对话做过什么」按还存在的线程重建（删掉的那条不能继续留在档案里）
    _agent_v2_memory_refresh_profile(canvas_id)
    return {"ok": True, "deleted": thread["id"], "active_id": active_id}


@app.get("/api/agent/canvases/{canvas_id}/artifacts")
async def agent_canvas_artifacts(canvas_id: str, request: Request):
    """画布级产物清单：扫描 DATA_DIR 下的产物目录，跨多次 run 汇总（只读）。"""
    canvas_id = str(canvas_id or "").strip()
    if not canvas_id:
        raise HTTPException(status_code=400, detail="canvas_id 不能为空")
    require_canvas_access(load_canvas(canvas_id), request, "view")
    items = _agent_artifact_scan()
    truncated = len(items) > AGENT_ARTIFACTS_LIST_LIMIT
    files = items[:AGENT_ARTIFACTS_LIST_LIMIT]
    counts: Dict[str, int] = {}
    for item in files:
        kind = str(item.get("kind") or "")
        counts[kind] = counts.get(kind, 0) + 1
    return {"canvas_id": canvas_id, "files": files, "counts": counts, "truncated": truncated}


@app.get("/api/agent/runs/{run_id}/model-context")
async def agent_run_model_context(run_id: str, request: Request):
    """该 run 实际发给模型的上下文摘要（调试用，不返回提示词原文）。run 过期即 404。"""
    bus = _agent_run_bus_get(run_id)
    _agent_require_run_access(bus, request, "view")
    debug = bus.get("model_debug") if isinstance(bus.get("model_debug"), dict) else {}
    if not debug:
        # 老 run 没有 debug 快照：从总线事件里能捞多少给多少，捞不到的字段给 null
        usage = None
        start_data: Dict[str, Any] = {}
        for item in reversed(bus.get("events") or []):
            name = str(item.get("name") or "")
            if name == "context_usage" and usage is None and isinstance(item.get("data"), dict):
                usage = item["data"]
            if name == "run_start" and isinstance(item.get("data"), dict):
                start_data = item["data"]
        debug = {"model": start_data.get("model"),
                 "estimated_tokens": (usage or {}).get("used_tokens"),
                 "context_max": (usage or {}).get("max_tokens"),
                 "percentage": (usage or {}).get("percentage")}

    def pick(key):
        value = debug.get(key)
        return value if value is not None else None

    return {
        "run_id": str(run_id or ""),
        "model": pick("model"),
        "system_prompt_chars": pick("system_prompt_chars"),
        "system_prompt_sections": pick("system_prompt_sections"),
        "tool_count": pick("tool_count"),
        "tool_names": pick("tool_names"),
        "history_chars": pick("history_chars"),
        "instruction_chars": pick("instruction_chars"),
        "estimated_tokens": pick("estimated_tokens"),
        "context_max": pick("context_max"),
        "percentage": pick("percentage"),
    }


@app.post("/api/agent/runs/{run_id}/compact")
async def agent_run_compact(run_id: str, request: Request):
    """阶段一：手动把这个 run 的运行转录压缩一次（先折叠旧工具结果，不调模型；
    仍然超过 85% 才再调一次模型做摘要）。事件契约不动，只是把结果直接返回给调用方。

    运行中不允许：正在跑的 run 每轮本来就按预算自动压缩，中途插手会和组装争抢同一份转录。"""
    bus = _agent_run_bus_get(run_id)
    _agent_require_run_access(bus, request, "view")
    if _agent_context_engine is None:
        raise HTTPException(status_code=400, detail="上下文引擎不可用（server/agent_core 未安装）")
    if not _agent_v2_context_enabled():
        raise HTTPException(status_code=400, detail="上下文引擎未开启（需要 NOVAI_AGENT_V2_CONTEXT=1）")
    if not bus.get("done"):
        raise HTTPException(status_code=409, detail="运行还在进行中，结束后再压缩；运行中会自动按预算压缩")
    engine = _agent_context_engine
    transcript = bus.get("transcript")
    if transcript is None and _AgentTranscript is not None:
        transcript = _AgentTranscript.load(run_id, os.path.join(DATA_DIR, "agent_runs"))
    if transcript is None or not transcript.visible():
        return {"run_id": str(run_id or ""), "level": "", "before_tokens": 0, "after_tokens": 0,
                "folded": 0, "summarized": False, "message": "这次运行没有可压缩的记录"}
    chat = (bus.get("request") or {}).get("chat") or {}
    budget = engine.Budget(_agent_run_context_max(chat if isinstance(chat, dict) else {}))
    before_tokens = int(engine.transcript_tokens(transcript))
    folded = int(engine.fold_old_results(transcript, max(0, int(budget.total * engine.FOLD_AT))))
    after_tokens = int(engine.transcript_tokens(transcript))
    level = "fold" if folded else ""
    summarized = False
    upto = engine.summary_cut(transcript) if after_tokens > budget.total * engine.SUMMARY_AT else 0
    if upto:
        if not isinstance(chat, dict) or not str(chat.get("base") or "").strip():
            raise HTTPException(status_code=400, detail="这个 run 没有可用的对话模型，无法做摘要（折叠已完成）")
        try:
            summary_text = await _agent_run_chat(chat, engine.summary_request(
                transcript, upto, str(bus.get("goal") or "")))
        except Exception as exc:
            raise HTTPException(status_code=502, detail="摘要调用失败：%s" % exc)
        if str(summary_text or "").strip() and transcript.add_summary(upto, summary_text):
            summarized = True
            level = "summary"
            after_tokens = int(engine.transcript_tokens(transcript))
    return {"run_id": str(run_id or ""), "level": level, "before_tokens": before_tokens,
            "after_tokens": after_tokens, "folded": folded, "summarized": summarized,
            "transcript": transcript.path or "",
            "message": "已整理上下文" if level else "还不需要压缩"}


AGENT_THREAD_MESSAGES_DEFAULT = 60
AGENT_THREAD_MESSAGES_MAX = 200


@app.get("/api/agent/threads/{thread_id}/messages")
async def agent_thread_messages(thread_id: str, request: Request, canvas_id: str = "",
                                limit: int = AGENT_THREAD_MESSAGES_DEFAULT, before: int = -1):
    """只读：按线程 id 读消息（最近 limit 条，1..200，超限夹到 200）。

    与 switch 的区别：这里**不改变 active_id**，只是读某个线程的历史；切线程才用 switch。
    """
    canvas_id = str(canvas_id or "").strip()
    if not canvas_id:
        raise HTTPException(status_code=400, detail="canvas_id 不能为空")
    require_canvas_access(load_canvas(canvas_id), request, "view")
    try:
        limit_value = int(limit)
    except (TypeError, ValueError):
        limit_value = AGENT_THREAD_MESSAGES_DEFAULT
    limit_value = max(1, min(limit_value, AGENT_THREAD_MESSAGES_MAX))
    doc = _agent_thread_doc_load(canvas_id)
    thread = _agent_thread_find(doc, thread_id)
    if not thread:
        raise HTTPException(status_code=404, detail="线程不存在")
    messages = [item for item in (thread.get("messages") or []) if isinstance(item, dict)]
    total = len(messages)
    # before = 只要这个位置之前的（往上翻加载更早的一页）；缺省 / 负数 = 最新一页
    try:
        end = int(before)
    except (TypeError, ValueError):
        end = -1
    end = total if end < 0 or end > total else end
    start = max(0, end - limit_value)
    sliced = messages[start:end]
    rows = [_agent_thread_message_row(msg, "content") for msg in sliced]
    return {"thread_id": thread["id"], "title": thread.get("title") or "",
            "messages": rows, "count": len(rows), "has_more": start > 0,
            "start": start, "total": total}


@app.delete("/api/agent/thread/{canvas_id}")
async def agent_thread_clear(canvas_id: str):
    """「新对话」：清掉这张画布的对话记录（画布本身不动）。"""
    path = _agent_thread_path(canvas_id)
    thread_ids = []
    with _AGENT_THREAD_LOCK:
        if os.path.exists(path):
            try:
                thread_ids = [str(item.get("id") or "")
                              for item in (_agent_thread_doc_load(canvas_id).get("threads") or [])]
            except Exception:
                thread_ids = []
            os.remove(path)
    for thread_id in thread_ids:      # 清掉的对话不能再被 recall 搜出来
        _agent_v2_memory_index_forget(canvas_id=canvas_id, thread_id=thread_id)
    # B2：对话都清了，档案也按当前（空）线程重建，索引条目一起更新
    _agent_v2_memory_refresh_profile(canvas_id, [])
    return {"ok": True}


# ---------------------------------------------------------------------------
# 助手看图（P1）：选中节点的图、用户附带的参考图，作为真正的图片交给对话模型；
# 对话模型看不了图时，先用一个能看图的模型把图转成文字说明（按图缓存），并在对话里写明。
# ---------------------------------------------------------------------------

AGENT_VISION_MAX_IMAGES = 12
AGENT_VISION_MAX_SIDE = 1024
AGENT_CAPTIONS_FILE = os.path.join(DATA_DIR, "agent_image_captions.json")
AGENT_CAPTIONS_LIMIT = 600
_AGENT_VISION_HINTS = ("gpt-4o", "gpt-4.1", "gpt-5", "o3", "o4", "claude", "gemini", "-vl", "vl-", "vision", "glm-4v",
                       "glm-4.5v", "glm-4.6v", "qwen-vl", "qwen2.5-vl", "qwen3-vl", "qvq", "doubao-seed", "doubao-1.5-vision",
                       "seed-1.6", "kimi-vl", "pixtral", "llava", "grok-4", "step-1v", "internvl", "minicpm-v", "fake-vision")
_AGENT_VISION_DENY = set()        # 当前处于「暂时跳过」的 provider:model（保留 set 兼容外部读写）
# 失败记忆：key → {count, last_at, until, hard, reason}
# - 第 1 次失败：暂时跳过 10 分钟（不是永久拉黑，到期自动重试）；
# - 连续第 2 次失败：拉黑 30 分钟（仍会到期自动重试，不是进程级永久拉黑）；
# - 成功一次就清空（_agent_vision_clear）。
_AGENT_VISION_FAILURES = {}
_AGENT_VISION_SKIP_SECONDS = 10 * 60
_AGENT_VISION_HARD_SKIP_SECONDS = 30 * 60
_AGENT_CAPTIONS_LOCK = Lock()


def _agent_model_maybe_vision(model):
    name = str(model or "").lower()
    if not name or any(bad in name for bad in ("gpt-image", "dall-e", "imagen", "embedding", "tts", "whisper")):
        return False
    return any(h in name for h in _AGENT_VISION_HINTS)


def _agent_chat_vision_key(chat):
    return f"{(chat or {}).get('provider')}:{(chat or {}).get('model')}"


def _agent_vision_failure_entry(key):
    entry = _AGENT_VISION_FAILURES.get(str(key or ""))
    return dict(entry) if isinstance(entry, dict) else {}


def _agent_vision_deny_active(key, now=None):
    """这个模型现在是不是要跳过（带 TTL）：真拉黑只持续一段时间，到期自动放行重试。"""
    key = str(key or "").strip()
    if not key or key not in _AGENT_VISION_DENY:
        return False
    entry = _AGENT_VISION_FAILURES.get(key)
    if not isinstance(entry, dict):
        return True             # 外部直接 add 的（手工/测试拉黑）：当硬拒绝
    stamp = time.time() if now is None else float(now)
    until = float(entry.get("until") or 0)
    if until and stamp >= until:
        _AGENT_VISION_DENY.discard(key)
        reset = dict(entry)
        reset.update({"count": 0, "until": 0, "hard": False})
        _AGENT_VISION_FAILURES[key] = reset
        return False
    return bool(until)


def _agent_vision_record_failure(key, reason=""):
    """记一次看图失败：第 1 次是「暂时跳过」，连续第 2 次才拉黑（都带 TTL，到期自动重试）。"""
    key = str(key or "").strip()
    if not key:
        return {}
    now = time.time()
    entry = dict(_AGENT_VISION_FAILURES.get(key) or {"count": 0})
    entry["count"] = int(entry.get("count") or 0) + 1
    entry["last_at"] = now
    entry["reason"] = str(reason or "")[:200]
    if entry["count"] >= 2:
        entry["hard"] = True
        entry["until"] = now + _AGENT_VISION_HARD_SKIP_SECONDS
    else:
        entry["hard"] = False
        entry["until"] = now + _AGENT_VISION_SKIP_SECONDS
    _AGENT_VISION_FAILURES[key] = entry
    _AGENT_VISION_DENY.add(key)
    return entry


def _agent_vision_clear(key):
    """看图成功：清掉这个模型的失败记忆（连续失败计数也归零）。"""
    key = str(key or "").strip()
    if not key:
        return
    _AGENT_VISION_DENY.discard(key)
    _AGENT_VISION_FAILURES.pop(key, None)


def _agent_vision_deny_note(key):
    """给用户/模型看的跳过原因：为什么跳过、大约多久后重试。"""
    entry = _agent_vision_failure_entry(key)
    if not entry:
        return ""
    reason = str(entry.get("reason") or "").strip()
    minutes = max(1, int(round(max(0.0, float(entry.get("until") or 0) - time.time()) / 60.0)))
    label = "连续看图失败，已暂时拉黑" if entry.get("hard") else "上次看图失败，已暂时跳过"
    text = label + (f"（{reason}）" if reason else "")
    return text + f"，约 {minutes} 分钟后自动重试"


def _agent_run_collect_images(focus, canvas):
    """这轮要给模型看的图：选中节点的图 + 用户指定的参考对象（按 references 顺序）+ 用户附带的参考图，
    最多 AGENT_VISION_MAX_IMAGES 张，只要图片不要视频。"""
    picked, seen = [], set()
    by_id = _agent_nodes_by_id(canvas) if isinstance(canvas, dict) else {}

    def _take_first_image(node):
        # 一个节点只取第一张图（与选中节点同一口径），免得单个节点把看图预算吃光
        for item in _agent_media_items(node):
            if _agent_item_kind(item) != "image":
                continue
            url = str(item.get("url") or "").strip()
            if url and url not in seen:
                seen.add(url)
                picked.append({"url": url, "label": _agent_node_ref(node)})
            return

    for nid in (focus or {}).get("selected_node_ids") or []:
        node = by_id.get(str(nid))
        if node:
            _take_first_image(node)
    # references 排在旧 reference_images 前面：前者带身份（role 说明当什么用），意图更明确
    for ref in (focus or {}).get("references") or []:
        if not isinstance(ref, dict):
            continue
        node = by_id.get(str(ref.get("id") or ""))
        if node:
            _take_first_image(node)
    n = 0
    for url in (focus or {}).get("reference_images") or []:
        url = str(url or "").strip()
        if not url or url in seen or is_video_reference_value(url):
            continue
        seen.add(url)
        n += 1
        picked.append({"url": url, "label": f"参考图{n}"})
    return picked[:AGENT_VISION_MAX_IMAGES]


def _agent_image_payload_url(url):
    """本地图转成缩到 1024px 的 data URL；外链原样给（上游自己去取）。"""
    try:
        return reference_to_data_url({"url": url}, max_size=AGENT_VISION_MAX_SIDE)
    except Exception as exc:
        print(f"[Agent] 读取参考图失败 {url}: {exc}")
        return ""


def _agent_vision_user_content(user_text, images):
    parts = []
    for img in images:
        data_url = _agent_image_payload_url(img["url"])
        if not data_url:
            continue
        parts.append({"type": "text", "text": f"图片「{img['label']}」："})
        parts.append({"type": "image_url", "image_url": {"url": data_url}})
    if not parts:
        return user_text
    parts.append({"type": "text", "text": user_text})
    return parts


def _agent_vision_direct_ok(chat):
    """这个对话模型能不能直接收图：模型名像能看图的，且没有因为发图被上游拒过。"""
    return (_agent_model_maybe_vision((chat or {}).get("model"))
            and not _agent_vision_deny_active(_agent_chat_vision_key(chat)))


def _agent_step_view_images(result):
    """步骤结果里登记的「下一轮要看这张图」（view_image 工具产出）：[{"url", "label"}]，按 url 去重。
    兼容 canvas_cli 把工具结果再包一层（result / data / value）。"""
    out, seen = [], set()
    holders = [result]
    if isinstance(result, dict):
        holders.extend(result.get(key) for key in ("result", "data", "value"))
    for holder in holders:
        if not isinstance(holder, dict):
            continue
        for item in holder.get("view_images") or []:
            if not isinstance(item, dict):
                continue
            url = str(item.get("url") or "").strip()
            if not url or url in seen:
                continue
            seen.add(url)
            out.append({"url": url, "label": str(item.get("label") or "图片")})
    return out


def _agent_annotate_view_images(result, note):
    """看图说明写进这条步骤结果：模型下一轮从转录里读到的是文字，图本身只进那一轮消息。"""
    note = str(note or "").strip()
    if not note or not isinstance(result, dict):
        return result
    out = dict(result)
    out["view_note"] = note
    return out


def _agent_captions_load():
    try:
        with open(AGENT_CAPTIONS_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
            return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _agent_captions_save(data):
    try:
        if len(data) > AGENT_CAPTIONS_LIMIT:
            keep = sorted(data.items(), key=lambda kv: kv[1].get("at", 0))[-AGENT_CAPTIONS_LIMIT:]
            data = dict(keep)
        os.makedirs(os.path.dirname(AGENT_CAPTIONS_FILE), exist_ok=True)
        write_json_atomic(AGENT_CAPTIONS_FILE, data, ensure_ascii=False, indent=2)
    except Exception as exc:
        print(f"[Agent] 保存图片说明缓存失败: {exc}")


def _agent_caption_key(url):
    path = output_file_from_url(url)
    if path and os.path.exists(path):
        try:
            st = os.stat(path)
            return hashlib.sha1(f"{path}|{st.st_size}|{int(st.st_mtime)}".encode("utf-8")).hexdigest()
        except Exception:
            pass
    return hashlib.sha1(str(url).encode("utf-8")).hexdigest()


def _agent_vision_candidates(preferred=None, exclude_key=""):
    """按用户配置顺序列出所有「可能能读图」的候选 chat（本次 run 的 chat 优先，其次配置里的视觉模型）。

    失败的模型记在 _AGENT_VISION_DENY 里，这里直接跳过；一个都没有返回空列表。
    调用方负责逐个尝试：成功即用，失败换下一个，全部失败才报错（错误里聚合每个候选的真实原因）。
    """
    candidates, seen = [], set()

    def add(chat, require_vision_hint=False):
        if not isinstance(chat, dict) or not chat.get("base"):
            return
        if require_vision_hint and not _agent_model_maybe_vision(chat.get("model")):
            return
        key = _agent_chat_vision_key(chat)
        if not key or key in seen or _agent_vision_deny_active(key):
            return
        seen.add(key)
        candidates.append(chat)

    add(preferred, require_vision_hint=True)
    add(_agent_pick_caption_model(exclude_key))
    for pid in _agent_available_providers():
        cfg = get_api_provider(pid) or {}
        names = [str(m or "").strip() for m in (cfg.get("chat_models") or []) + (cfg.get("models") or [])
                 if str(m or "").strip()]
        for model in dict.fromkeys(names):
            if not _agent_model_maybe_vision(model):
                continue
            key = f"{pid}:{model}"
            if key == exclude_key or _agent_vision_deny_active(key):
                continue
            try:
                base, headers, mdl = resolve_chat_provider(pid, model, "")
            except HTTPException:
                continue
            if base:
                add({"provider": pid, "base": base, "headers": headers, "model": mdl or model,
                     "provider_cfg": cfg})
    return candidates


def _agent_pick_caption_model(exclude_key="", fallback_chat=None):
    """在已配置的对话平台里找一个看得了图的模型（按用户配置顺序）。

    找不到时：如果给了 fallback_chat（通常是当前对话模型）且它只是被暂时跳过、还在 TTL 外，
    就退回它再试一次——审查失败本来就是可降级的，别因为一次失败就报「没有能看图的模型」。"""
    for pid in _agent_available_providers():
        cfg = get_api_provider(pid) or {}
        names = [str(m or "").strip() for m in (cfg.get("chat_models") or []) + (cfg.get("models") or []) if str(m or "").strip()]
        for model in dict.fromkeys(names):
            key = f"{pid}:{model}"
            if key == exclude_key or _agent_vision_deny_active(key) or not _agent_model_maybe_vision(model):
                continue
            try:
                base, headers, mdl = resolve_chat_provider(pid, model, "")
            except HTTPException:
                continue
            if base:
                return {"provider": pid, "base": base, "headers": headers, "model": mdl or model, "provider_cfg": cfg}
    if isinstance(fallback_chat, dict) and fallback_chat.get("base"):
        fallback_key = _agent_chat_vision_key(fallback_chat)
        if _agent_model_maybe_vision(fallback_chat.get("model")) and not _agent_vision_deny_active(fallback_key):
            return fallback_chat
    return None


async def _agent_caption_images(images, exclude_key="", failures=None):
    """给每张图一段文字说明（有缓存就用缓存）。返回 (captions:[{label, caption}], model 名 或 "")。

    看图模型失败时换下一个候选继续（不再一失败就整批放弃）；每个候选的真实失败原因可写进 failures。"""
    with _AGENT_CAPTIONS_LOCK:
        cache = _agent_captions_load()
    out, missing = [], []
    for img in images:
        hit = cache.get(_agent_caption_key(img["url"]))
        if hit and hit.get("caption"):
            out.append({"label": img["label"], "caption": hit["caption"]})
        else:
            missing.append(img)
    model_name = ""
    if missing:
        candidates = _agent_vision_candidates(None, exclude_key)
        if not candidates:
            return out, ""
        for img in missing:
            data_url = _agent_image_payload_url(img["url"])
            if not data_url:
                continue
            messages = [{"role": "user", "content": [
                {"type": "text", "text": "用 2-3 句中文客观描述这张图，依次说：主体是什么、风格与色调、构图与机位、画面里有没有文字。不要评价，不要加前言。"},
                {"type": "image_url", "image_url": {"url": data_url}}]}]
            for chat in candidates:
                key = _agent_chat_vision_key(chat)
                if _agent_vision_deny_active(key):
                    continue
                try:
                    text = (await _agent_run_chat(chat, messages)).strip()[:400]
                except AgentRunError as exc:
                    print(f"[Agent] 图片转文字失败（{chat['model']}）: {exc.message}")
                    _agent_vision_record_failure(key, _agent_clean_error_text(exc.message))
                    if failures is not None:
                        failures.append(f"{key} → {_agent_clean_error_text(exc.message)}")
                    continue
                if text:
                    out.append({"label": img["label"], "caption": text})
                    model_name = model_name or chat["model"]
                    with _AGENT_CAPTIONS_LOCK:
                        cache = _agent_captions_load()
                        cache[_agent_caption_key(img["url"])] = {"caption": text, "model": chat["model"], "at": time.time()}
                        _agent_captions_save(cache)
                    break
    return out, model_name


def _agent_captions_text(captions):
    if not captions:
        return ""
    lines = ["参考图的文字说明（当前对话模型看不了图，系统先用能看图的模型转成了文字；只能据此理解，不要假装看过原图）："]
    lines += [f"- {c['label']}：{c['caption']}" for c in captions]
    return "\n".join(lines)


async def _agent_run_vision_setup(images, chat, emit):
    """对话模型看不了图时的兜底：先转文字说明；连能看图的模型都没有，就如实告诉用户和模型。返回 (mode, 给模型的说明)。"""
    labels = "、".join(i["label"] for i in images)
    failures = []
    caps, cap_model = await _agent_caption_images(images, _agent_chat_vision_key(chat), failures)
    if caps:
        emit("vision", {"mode": "caption", "labels": [i["label"] for i in images], "caption_model": cap_model,
                        "text": f"当前对话模型看不了图，已用{('「' + cap_model + '」') if cap_model else '能看图的模型'}把{labels}转成文字说明再理解"})
        return "caption", _agent_captions_text(caps)
    reasons = "；".join(failures)
    detail = (f"，试过的看图模型都失败（{reasons}）" if reasons
              else "，也没找到能看图的模型")
    emit("vision", {"mode": "none", "labels": [i["label"] for i in images],
                    "text": f"当前对话模型看不了图{detail}：{labels}只能按节点信息理解。换一个能看图的对话模型效果会更好"})
    return "none", (f"参考图说明：系统没法让你看到 {labels} 的画面（{detail.strip('，')}），"
                    "只知道它们是哪个节点、地址是什么；不要假装看过图。")


def _agent_run_resolve_chat(provider, model, ms_model):
    """/api/agent/run 的对话选型：直接走公共选型（用户点的平台+模型优先且原样使用，不可用才回退）。
    行为与 task-4 修好的版本完全一致，只是逻辑收敛到 _resolve_chat_with_preference。"""
    return _resolve_chat_with_preference(
        provider, model, ms_model,
        log_tag="Agent",
        error_prefix="无法运行 Agent（对话模型不可用）")


def _agent_auto_chat_model(provider_id):
    """智能体自动挑模型的唯一来源：该 provider 自己声明的 chat_models（modelscope 用它自己的列表）。
    解析不出返回空串，由调用方跳过——绝不把全局 CHAT_MODEL 塞给别的供应商，避免必然失败。"""
    pid = str(provider_id or "").strip().lower()
    if pid == "modelscope":
        return MODELSCOPE_CHAT_MODELS[0] if MODELSCOPE_CHAT_MODELS else ""
    try:
        cfg = get_api_provider(pid)
    except HTTPException:
        return ""
    if not (cfg.get("chat_models") or []):
        return ""
    return preferred_chat_model(cfg)


def _agents_resolve_chat(provider, model, ms_model):
    """智能体广场专用：走同一个公共选型，额外两条更严的口径（保持原有行为）：
      · 用户没显式给模型时，按该平台声明的 chat_models 自动挑（allow_auto_model）；
      · 解析出来的模型为空也算不可用（require_model），绝不静默落到一个必然失败的模型；
      · 全都不可用时把每个候选的原因汇总进错误（joined_detail）。"""
    return _resolve_chat_with_preference(
        provider, model, ms_model,
        log_tag="Agents",
        error_prefix="无法运行智能体（没有可用的对话模型）",
        allow_auto_model=True,
        require_model=True,
        joined_detail=True)


# 非流式 agent 决策调用的请求级超时：全局 AI_REQUEST_TIMEOUT 默认 1800s，agent 决策不能挂这么久。
# 90s：在用户 120s 耐心之前给出结果（失败/回退），超时按现有失败计数/刹车处理，并如实返回「模型 90 秒未响应」。
_AGENT_CHAT_TIMEOUT_SECONDS = 90.0




_AGENT_NON_STREAM_SLOW_LOG_SECONDS = 30.0


def _agent_non_stream_log_slow(model, elapsed_s):
    """非流式超过 30s 打一条慢请求警告（不改变行为，方便判断是上游波动）。"""
    elapsed_s = float(elapsed_s or 0)
    if elapsed_s < _AGENT_NON_STREAM_SLOW_LOG_SECONDS:
        return
    run_id = str(_AGENT_RUN_ID.get() or "-")
    round_no = int(_AGENT_RUN_ROUND.get() or 0)
    print(f"[Agent] 非流式慢请求 run={run_id} round={round_no} model={model or '-'} "
          f"elapsed_s={elapsed_s:.1f}s（上限 {int(_AGENT_CHAT_TIMEOUT_SECONDS)}s）", flush=True)


def _agent_chat_timeout():
    return httpx.Timeout(connect=15.0, read=float(_AGENT_CHAT_TIMEOUT_SECONDS),
                         write=30.0, pool=15.0)


_AGENT_CHAT_TOTAL_TIMEOUT_SECONDS = float(os.getenv("NOVAI_AGENT_CHAT_TOTAL_TIMEOUT", "120"))


async def _agent_chat_http_once(chat, messages, think_fields, tools=None):
    """一次非流式 HTTP 请求（单独抽出来，外层用总时长兜底）。"""
    async with httpx.AsyncClient(
            http2=False, verify=_SSL_CONTEXT,
            trust_env=provider_trust_env(chat.get("provider_cfg")),
            timeout=_agent_chat_timeout()) as client:
        body = {"model": chat["model"], "messages": messages}
        body.update(think_fields)
        if tools:
            body["tools"] = tools
            body["tool_choice"] = "auto"
        if is_apimart_provider(chat.get("provider_cfg")):
            body["stream"] = False
        response = await post_chat_with_think(client, f"{chat['base']}/chat/completions",
                                              chat["headers"], body, think_fields)
        response.raise_for_status()
        return response.json()


async def _agent_run_chat(chat, messages):
    """单次非流式对话调用（与 plan 同一套 provider/请求风格）。"""
    think_fields = chat_think_fields(chat.get("provider_cfg"), chat.get("model"), chat.get("think_level"))
    non_stream_started = time.monotonic()
    try:
        raw = await asyncio.wait_for(_agent_chat_http_once(chat, messages, think_fields),
                                     timeout=_AGENT_CHAT_TOTAL_TIMEOUT_SECONDS)
    except asyncio.TimeoutError:
        _agent_decision_timeout_log("non_stream_total", _agent_chat_vision_key(chat),
                                    _AGENT_CHAT_TOTAL_TIMEOUT_SECONDS)
        raise AgentRunError(f"模型 {int(_AGENT_CHAT_TOTAL_TIMEOUT_SECONDS)} 秒未返回"
                            "（非流式总时长超时）", code="provider_timeout")
    except httpx.TimeoutException:
        _agent_decision_timeout_log("non_stream", _agent_chat_vision_key(chat),
                                    _AGENT_CHAT_TIMEOUT_SECONDS)
        raise AgentRunError(f"模型 {int(_AGENT_CHAT_TIMEOUT_SECONDS)} 秒未响应", code="provider_timeout")
    except httpx.HTTPStatusError as exc:
        raise AgentRunError(f"上游模型接口错误 {exc.response.text[:200]}", code="provider_http_error")
    except httpx.HTTPError as exc:
        raise AgentRunError(f"请求上游模型接口出错：{exc}", code="provider_unreachable")
    except Exception as exc:
        raise AgentRunError(f"{type(exc).__name__}: {exc}", code="provider_error")
    non_stream_elapsed = time.monotonic() - non_stream_started
    _agent_timing_log("non_stream", _AGENT_RUN_ID.get(), _AGENT_RUN_ROUND.get(),
                      non_stream_elapsed * 1000.0, chat.get("model"))
    _agent_non_stream_log_slow(chat.get("model"), non_stream_elapsed)
    text = text_from_chat_response(raw) or ""
    if not text.strip():
        raise AgentRunError("模型返回了空内容", code="empty_model_reply")
    return text


def _agent_decision_real_steps(decision):
    """决策里真正要执行的步骤（有 tool 的 dict）。用来判断 done=true 时是不是还带了步骤。"""
    if not isinstance(decision, dict):
        return []
    raw = decision.get("steps")
    if not isinstance(raw, list):
        return []
    return [step for step in raw if isinstance(step, dict) and str(step.get("tool") or "").strip()]


def _agent_run_parse_round(text):
    """解析模型单轮返回：{thought, steps, done, message}。

    阶段四·修：模型可能输出「决策 JSON + 尾随对象/说明」——取第一个平衡对象，尾随的 suggestions 并进决策，
    其余尾随内容忽略并记日志；半截 JSON 仍然按失败处理。"""
    return _agent_parse_decision_json(text)


