@app.post("/api/native-save")
async def native_save(data: dict):
    """接收 base64 数据，通过 pywebview 窗口调原生保存对话框写入文件。
    macOS WKWebView 不支持 blob URL 触发下载，所以走这条路径最稳。
    """
    import base64 as _b64, re as _re
    payload = (data or {}).get("data") or ""
    filename = (data or {}).get("filename") or f"download-{int(time.time())}"
    if not payload:
        raise HTTPException(status_code=400, detail="empty data")
    try:
        b64 = payload
        ext = os.path.splitext(filename)[1] or ".png"
        if "," in payload and payload.startswith("data:"):
            header, b64 = payload.split(",", 1)
            m = _re.match(r"data:image/(\w+)", header)
            if m:
                ext = "." + m.group(1)
        raw = _b64.b64decode(b64)
        if not filename.lower().endswith(ext):
            filename += ext
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"decode failed: {e}")
    try:
        import webview as _webview
        wins = getattr(_webview, "windows", []) or []
        if not wins:
            raise HTTPException(status_code=503, detail="no webview window")
        result = wins[0].create_file_dialog(
            _webview.SAVE_DIALOG,
            directory="",
            save_filename=filename,
        )
        if not result:
            return {"ok": True, "saved": False}
        with open(result, "wb") as f:
            f.write(raw)
        return {"ok": True, "saved": True, "path": result}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"save dialog failed: {e}")


if __name__ == "__main__":
    import uvicorn
    # 端口来源优先级：命令行（--port N / -p N / --port=N / 位置参数 N）> 环境变量 NOVAI_PORT > 3000。
    # Electron 桌面壳用 `NOVAI.exe --port 3000` 启动；历史上这里只认位置参数，
    # 导致 int("--port") 抛 ValueError、后端一启动就崩（表现为"无法加载后端"）。
    _argv = sys.argv[1:]
    port = int(os.environ.get("NOVAI_PORT", 3000))
    _i = 0
    while _i < len(_argv):
        _a = _argv[_i]
        if _a in ("--port", "-p", "-P") and _i + 1 < len(_argv):
            try:
                port = int(_argv[_i + 1])
            except (TypeError, ValueError):
                pass
            break
        if _a.startswith("--port="):
            try:
                port = int(_a.split("=", 1)[1])
            except (TypeError, ValueError):
                pass
            break
        if _a.isdigit():
            port = int(_a)
            break
        _i += 1
    # 命令行端口要回写到环境变量：/api/lan-info 的局域网地址/二维码和 server/appRegistry.py 的
    # App 能力内部回环都只读 NOVAI_PORT，不回写就会出现"服务在 3101、二维码和自调用打 3000"。
    os.environ["NOVAI_PORT"] = str(port)
    # 关闭服务端协议级 WebSocket ping：部分客户端（如 PS UXP 面板）不会自动回 pong，
    # 默认 20s ping/20s 超时会把这些连接每隔一会儿就踢掉造成"频繁断连"。
    # 客户端有自己的应用层心跳 + 断线重连兜底，这里禁用协议 ping 更稳。
    uvicorn.run(app, host="0.0.0.0", port=port,
                ws_ping_interval=None, ws_ping_timeout=None)
